-- Sources: data/i18n/ruRU. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_ruRU")
P.entries["quest:1247"] = {n="Пропавший дипломат",s="Этот этап расследования дела пропавшего посланника Штормграда следует за допросом Дашеля Каменного Кулака в Старом городе. Выбив признание из головореза, вы несете весть о запасном плане похищения главе шпионов, притворяющемуся мастером-сыроделом, Иллингу Триасу.",h="Этот этап расследования дела пропавшего посланника Штормграда следует за допросом Дашеля Каменного Кулака в...",kw={"addle's stead","dashel stonefist","elling trias","menethil","missing diplomat","slim","stormwind","участок эддла","дашель каменный кулак","иллинг триас","гавань менетилов","пропавший дипломат","слим","штормград"},ang={["class:Rogue"]="Для агента теней согласование между уличными громилами вроде Дашеля и главами шпионов вроде Триаса показывает тонкую грань между обычной уличной преступностью и большой государственной политикой.",["faction:Alliance"]="Раскрытие исчезновения посланника жизненно важно для стабильности всего Альянса, ведь серьезная диверсия угрожает руководству в Штормграде.",["race:Human"]="Заговор разворачивается прямо в пределах столицы, доказывая, что измена загноилась внутри королевства Штормград, пока на троне сидит мальчик-король."},sec={{t="Трещина в стене",b="Дашель Каменный Кулак не из тех, кто уносит тайны в могилу, особенно когда уверен, что его здоровье под угрозой. Загнанный в угол за лавкой в Старом городе, Дашель сдается и признает, что его роль в похищении рухнула, когда первоначальный план заговорщиков провалился. Стремясь переложить вину, он указывает на тайную встречу, прошедшую за несколько недель до того на Участке Эддла в Сумеречном лесу, и дает единственную зацепку для запасной операции: связного из Гавани Менетилов, известного лишь как Слим."},{t="Доклад сыроделу",b="Иллинг Триас скромно стоит за прилавком «Сыров Триаса» в Торговом квартале, но его настоящее ремесло — собирать тайны для Короны. Пока вы выбивали подробности из Дашеля, Триас изучал перехваченные сообщения о заговоре. Признание Дашеля совпадает с письменными сведениями: целью был неназванный дипломат, главная засада провалилась, а запасной план был запущен через Болотину. С именем «Слим» поиски уходят из темных переулков Штормграда на север, к болотам."}},faq={{q="Кто такой Дашель Каменный Кулак?",a="Дашель Каменный Кулак — местный громила и посредник, действующий в Старом городе Штормграда. Связанный с преступным миром, близким к Братству Справедливости, он был рядовым подручным в первоначальном плане захвата штормградского посланника, а затем, когда его припугнули, стал информатором.",al={"dashel stonefist","who is dashel","stonefist stormwind","дашель каменный кулак","кто такой дашель","каменный кулак штормград"}},{q="Почему Иллинг Триас участвует в этом расследовании?",a="Хотя публично Иллинг Триас известен как мастер тонких сыров, он — один из опытных агентов разведки Штормграда. Свою лавку в Торговом квартале он использует как прикрытие для тайных расследований, требующих скрытности сверх возможностей городской стражи.",al={"why elling trias","cheese vendor spy","trias intelligence","почему иллинг триас","сыровар шпион","разведка триаса"}},{q="Что произошло на Участке Эддла?",a="Участок Эддла — заброшенная ферма на западе Сумеречного леса, где заговорщики собрались несколько недель назад, чтобы согласовать планы похищения после срыва первоначального замысла.",al={"addle's stead meeting","addles stead","westfall meeting","встреча на участке эддла","участок эддла","встреча в сумеречном лесу"}},{q="Какого дипломата они пытались похитить?",a="В официальных документах и у уличных головорезов цель называется лишь неназванным дипломатом, направлявшимся в Терамор. Настоящая личность посланника на этом этапе расследования остается строго охраняемой тайной.",al={"who is missing diplomat","who got kidnapped","the diplomat identity","кто пропавший дипломат","кого похитили","личность дипломата"}},{q="Кто такой Слим?",a="Слим — связной, которого Дашель Каменный Кулак назвал исполнителем «плана Б» в Гавани Менетилов в Болотине, то есть вторичного маршрута снабжения заговорщиков.",al={"who is slim","slim menethil","menethil contact","кто такой слим","слим менетил","связной в менетиле"}},{q="Куда ведет след дальше?",a="Когда известно, что связного зовут Слим, и Иллинг Триас это подтвердил, расследование смещается на север, в портовый город Гавань Менетилов в Болотине, где предстоит выследить связного.",al={"next step missing diplomat","where to go after dashel","what next","следующий шаг пропавший дипломат","куда идти после дашеля","что дальше"}}},fp="20,273,19.518.0,25.547.1,24.256.0,51.254.0,31.184.0,47.203.2,12.183.0,37.173.0"}
P.entries["quest:125"] = {n="Утраченные инструменты",s="Пока Приозерье находится под давлением враждебных сил, обслуживание и оборона города полностью зависят от местной рабочей силы. Необходимые инструменты Штейгера Ослоу, отправленные из Златоземья, были утеряны, когда обстрел из катапульт клана Черной горы потопил его лодку на Озере Безмолвия. Достать затонувший сундук со дна озера крайне важно для восстановления разрушенного моста.",h="Пока Приозерье находится под давлением враждебных сил, обслуживание и оборона города полностью зависят от...",kw={"catapult","foreman oslow","goldshire","lake everstill","lakeshire","murloc","redridge","thresher","toolbox","катапульта","штейгер ослоу","златоземье","озеро безмолвия","приозерье","мурлок","молотильщик","ящик с инструментами"},ang={["faction:Alliance"]="Приозерье — восточный оплот Альянса против клана Черной горы; снабжение гражданских строителей снаряжением жизненно важно для защиты границ Королевства Штормград.",["profession:Blacksmithing"]="Качественные инструменты трудно ковать в условиях осады, поэтому возврат специализированных кузнечных и строительных орудий из Златоземья незаменим для города."},sec={{t="Доставка пошла не так",b="Связь Приозерья с Элвиннским лесом прервана разрушением Большого моста. Когда замену каменщицких и плотницких инструментов отправили по суше из Златоземья, напрямую в город они пройти не смогли. Команда перегрузила припасы в лодку, чтобы пересечь Озеро Безмолвия, но суденышко поразила катапульта орков Черной горы. Лодка была уничтожена, а тяжелый окованный железом ящик Ослоу рухнул на глубокое дно озера."},{t="Опасности глубин",b="Достать ящик гораздо опаснее обычного ныряния. Воды Озера Безмолвия кишат агрессивными племенами мурлоков, рыщущими на мелководье, а в мутных глубинах охотятся хищные молотильщики. Несмотря на опасность, вернуть инструменты необходимо, чтобы Штейгер Ослоу смог возобновить ремонт моста и не дать Приозерью окончательно превратиться в руины."}},faq={{q="Почему инструменты вообще отправили на лодке?",a="Главная дорога в Приозерье пересекает каменный мост через Озеро Безмолвия, но орки Черной горы взорвали большой пролет. Поскольку повозки со снабжением из Златоземья больше не могли проехать, команде пришлось выгрузить инструменты и попытаться переправить их по воде.",al={"why boat","how did the tools sink","why lake transport","почему лодка","как утонули инструменты","почему перевозка по озеру"}},{q="Как затонула лодка?",a="Во время переправы через озеро транспортную лодку обстреляли орки Черной горы: они попали в нее снарядом катапульты с окрестных высот, и лодка вместе с грузом мгновенно затонула.",al={"who destroyed the boat","how did it get hit","кто уничтожил лодку","как попали в лодку"}},{q="Кто такой Штейгер Ослоу?",a="Штейгер Ослоу — главный строитель и надсмотрщик Приозерья. Он отвечает за общественные работы и городское обслуживание, а сейчас прежде всего за важнейшую задачу — восстановление разрушенного моста.",al={"foreman oslow","oslow role","штейгер ослоу","роль ослоу"}},{q="Какие опасности есть на Озере Безмолвия?",a="Озеро населено враждебными племенами мурлоков, патрулирующими берега и руины, а также свирепыми плотоядными озерными молотильщиками, охотящимися на открытой воде и в глубине.",al={"what's in the lake","lake monsters","lake everstill danger","что в озере","озерные чудовища","опасность озера безмолвия"}},{q="Почему Приозерью так нужны эти инструменты?",a="Приозерье фактически в осаде, отрезано от быстрой помощи и регулярных поставок. Без тяжелых инструментов Ослоу не может ни восстановить мост, ни починить укрепления, нужные, чтобы сдерживать нападающих орков и гноллов.",al={"why are tools important","bridge repair tools","почему важны инструменты","инструменты для ремонта моста"}},{q="Куда ведет задание дальше?",a="Когда его ящик с инструментами найден, Штейгер Ослоу привлекает искателей приключений для сбора сырья, нужного для ремонта Большого моста, в следующем задании «Мост Безмолвия».",al={"next quest","what after lost tools","следующее задание","что после утраченных инструментов"}}},fp="14,350,20.485.0,19.373.0,51.268.0,22.202.0,21.191.0,35.178.0,45.220.0,31.182.1"}
P.entries["quest:126"] = {n="Вой в холмах",s="«Вой в холмах» — награда за голову, которую предлагает Альянс в лице Вернера Осгуда в Приозерье: нужно выследить Яулера, грозного вожака гноллов Красногорья. Военные силы Штормграда слишком растянуты в борьбе с орками клана Черной горы, чтобы защищать местные границы, поэтому Приозерье рассчитывает на приезжих искателей приключений, которые сломят управление стаи гноллов.",h="«Вой в холмах» — награда за голову, которую предлагает Альянс в лице Вернера Осгуда в Приозерье: нужно...",kw={"blackrock","gnolls","lakeshire","paw","redridge","stormwind army","verner osgood","yowler","черная гора","гноллы","приозерье","лапа","красногорье","армия штормграда","вернер осгуд","яулер"},ang={["class:Hunter"]="Выследить доминирующего вожака вроде Яулера в его горном логове — значит обладать острым глазом на метки территории и повадки стаи.",["class:Warrior"]="Сразиться с Яулером — значит встретиться с противником, который правит своей жестокой стаей грубой физической силой, а это требует прямого столкновения мощи.",["faction:Alliance"]="То, что Приозерье полагается на наемников, а не на королевских солдат, показывает глубокий управленческий кризис, ослабляющий сейчас королевство Штормград."},sec={{t="Голос с высот",b="Даже после того как гноллы помельче, нападавшие на тропы вокруг Приозерья, были перебиты, их зловещий вой по-прежнему разносится по хребтам Красногорья. Вернер Осгуд, трудолюбивый кузнец-коновал Приозерья, понимает, что убийство разведчиков и падальщиков не остановит натиск, пока жив вожак стаи. Над всей этой сворой возвышается Яулер — исключительно хитрый и огромный гнолл, чей вой направляет стаю по холмам. Вернер поручает искателям приключений выследить зверя и отсечь ему лапу, чтобы вой был прекращен раз и навсегда."},{t="Город, брошенный армией",b="Этот заказ показывает мрачную реальность, с которой сталкиваются восточные границы королевства Штормград. Из-за пропажи короля Вариана Ринна и споров о регентстве верховное командование парализовано, и королевские солдаты сосредоточены почти исключительно на укрепившихся кланах орков Черной горы на севере. Обычные поселения вроде Приозерья остались совершенно без защиты от местных угроз, таких как гноллы, и жителям, подобным Вернеру Осгуду, приходится самим назначать награды за головы, чтобы их дома не были захвачены."}},faq={{q="Кто такой Яулер?",a="Яулер — свирепый вожак гноллов Красногорья, рыщущих по холмам близ Приозерья. По словам Вернера Осгуда, Яулер намного сильнее и опаснее обычных шакалов: он объединяющий всех вожак, который направляет стаю против путников и местных хуторов.",al={"yowler","who is the gnoll boss","yowler lore","yowler gnoll","яулер","кто такой вожак гноллов","яулер предания","яулер гнолл"}},{q="Почему награду назначает Вернер Осгуд, а не городская стража?",a="Официальное руководство Приозерья и местное ополчение полностью бессильны перед наступающими орками Черной горы. Вернер Осгуд, местный ремесленник и конюх, чье благополучие зависит от безопасных дорог, часто сам нанимает странствующих наемников для устранения непосредственных угроз.",al={"why verner","why not magistrate solomon","why osgood hiring","почему вернер","почему не магистрат соломон","почему осгуд нанимает"}},{q="Где солдаты Штормграда, которые должны защищать Приозерье?",a="Регулярные войска Штормграда задействованы в других местах. Присутствие армии в Красногорье связано наблюдением за орками клана Черной горы и их сдерживанием выше в горах, поэтому жители остались без всякой поддержки против местных зверей, мурлоков и гноллов.",al={"where is the army","why no stormwind guards","stormwind military lakeshire","где армия","почему нет стражи штормграда","армия штормграда приозерье"}},{q="Что станет с гноллами Красногорья после смерти Яулера?",a="Смерть Яулера разрушает управление стаи гноллов и ослабляет согласованные набеги на границы города. Однако гноллы остаются упорной и постоянной бедой на всех скалистых высотах Красногорья.",al={"did gnolls leave","what happens after yowler dies","гноллы ушли","что будет после смерти яулера"}},{q="Какие задания предшествуют этому заказу?",a="Цепочка заданий начинается с поручений Вернера Осгуда добыть конскую упряжь: «Цена подков» и «Доставка подков». После «Лая гноллов», где нужно разобраться с чешуей и проредить стаю, Вернер дает вам задание напрямую выследить Яулера.",al={"yowler quest pre reqs","unlock howling in the hills","chain for howling in the hills","предыдущие задания яулера","как открыть вой в холмах","цепочка вой в холмах"}},{q="Зачем Вернеру лапа Яулера в качестве доказательства?",a="Награды за опасных зверей требуют неопровержимых вещественных доказательств до выплаты. Отсеченная лапа Яулера докажет Вернеру и встревоженным жителям Приозерья, что жуткий зверь, чей вой разносился по холмам, действительно пал.",al={"why yowler paw","yowlers paw proof","зачем лапа яулера","лапа яулера доказательство"}}},fp="20,327,24.551.0,28.490.0,14.268.0,67.294.0,68.259.0,56.213.0,50.271.0,43.255.0"}
P.entries["quest:127"] = {n="Продажа рыбы",s="Начальник порта Барен управляет оживленным пирсом Приозерья, но свежий товар для торговли найти становится все труднее. Он платит путникам за пятнистых солнечников — ценный местный деликатес Озера Безмолвия, добывать который стало опасно из-за наступающих мурлоков.",h="Начальник порта Барен управляет оживленным пирсом Приозерья, но свежий товар для торговли найти становится...",kw={"dockmaster baren","lake everstill","lakeshire","murloc","redridge","selling fish","spotted sunfish","начальник порта барен","озеро безмолвия","приозерье","мурлок","красногорье","продажа рыбы","пятнистый солнечник"},ang={["faction:Alliance"]="Раз королевство Штормград почти не помогает Красногорью войсками, даже снабжение местных едой зависит от независимых путников Альянса, готовых помочь.",["profession:Cooking"]="Слава Приозерья как места тонких пресноводных деликатесов вроде пятнистого солнечника делает местные воды неизменно интересными для начинающих поваров."},sec={{t="Деликатес Озера Безмолвия",b="Озеро Безмолвия известно по всем окрестным землям своими пятнистыми солнечниками — нежным уловом, на который неизменно есть спрос у горожан и проезжих торговцев. Но несмотря на обилие рыбы под водой, запасы города регулярно иссякают. Когда Приозерье из последних сил противостоит разным местным угрозам, даже обычная торговля требует помощи вольных искателей приключений."},{t="Неприятности на мелководье",b="Обычно местные рыбаки без труда выполнили бы заказы начальника порта Барена. Однако рост агрессивных племен мурлоков на мелководье и берегах прогнал обычных горожан от воды. Путникам, желающим исполнить просьбу Барена, приходится либо забрасывать удочки, оглядываясь по сторонам, либо отбирать улов прямо у мурлоков, промышляющих на берегах."}},faq={{q="Кто такой начальник порта Барен?",a="Начальник порта Барен ведает причалами и движением лодок на Озере Безмолвия в Приозерье. Он управляет водной торговлей города и полагается на умелых путников, которые помогают добывать свежую рыбу и очищать окрестности воды от угроз.",al={"baren","who is the dockmaster","dockmaster baren","барен","кто такой начальник порта","начальник порта барен"}},{q="Почему на пятнистых солнечников такой большой спрос?",a="Озеро Безмолвия славится пятнистыми солнечниками, которые стали обычным деликатесом и важным товаром Приозерья. Запасы начальника порта Барена тают, потому что обычные городские рыбаки не могут безопасно ловить рыбу, пока озеро кишит враждебными тварями.",al={"why sunfish","spotted sunfish lore","why does lakeshire want fish","почему солнечник","пятнистый солнечник предания","почему приозерью нужна рыба"}},{q="Как рыба-солнечник попадает к мурлокам?",a="Племена мурлоков на Озере Безмолвия активно собирают добычу и охотятся на мелководье. Когда они убивают или прогоняют местных рыбаков, то забирают рыбу в свои лагеря, и эти запасы легко отнять искателям приключений, которые предпочитают сражаться, а не удить.",al={"murloc fish","why do murlocs drop fish","murlocs stealing fish","мурлоки рыба","почему с мурлоков падает рыба","мурлоки крадут рыбу"}},{q="Где можно найти пятнистых солнечников?",a="Пятнистые солнечники водятся в водах Озера Безмолвия в Красногорье. Их можно выловить удочкой или добыть с мурлоков, обитающих на берегах и мелководье озера.",al={"where are sunfish","lake everstill fish location","how to get spotted sunfish","где солнечники","озеро безмолвия рыба где","как добыть пятнистого солнечника"}},{q="Как это задание связано с «Мурлоками-браконьерами»?",a="Начальник порта Барен предлагает оба задания одновременно. Раз мурлоки рыщут по озеру и браконьерствуют, расправа с ними естественным образом совпадает с возвращением пятнистых солнечников, которых они вытащили из воды.",al={"murloc poachers connection","baren other quest","dockmaster quests","мурлоки-браконьеры связь","другое задание барена","задания начальника порта"}},{q="Нужна ли рыбалка, чтобы помочь начальнику порта Барену?",a="Нет, снасти и навыки рыбалки не нужны. Хотя удочка — мирный способ добыть пятнистых солнечников, начальник порта Барен прямо предлагает отбирать их силой у мурлоков, охотящихся на озере.",al={"do i need fishing","can i do this without fishing pole","fishing required","нужна ли рыбалка","можно ли без удочки","требуется рыбалка"}}},fp="12,269,26.402.0,23.397.0,24.218.0,44.251.0,39.261.0,35.199.0,45.218.0,45.198.0"}
P.entries["quest:1274"] = {n="Пропавший дипломат",s="«Пропавший дипломат» — первый шаг одного из важнейших и деликатнейших расследований Штормграда. Дело негласно доводится до вас на городских улицах и ведет прямо к епископу Делавею в Крепости Штормграда. Церкви Священного Света и короне нужны умелые руки для дела, слишком опасного, чтобы доверять его открытым каналам.",h="«Пропавший дипломат» — первый шаг одного из важнейших и деликатнейших расследований Штормграда.",kw={"bishop delavey","diplomat","investigation","stormwind keep","the missing diplomat","thomas","епископ делавей","дипломат","расследование","крепость штормграда","пропавший дипломат","томас"},ang={["faction:Alliance"]="Раскрытие тайны пропавшего дипломата жизненно важно для целостности и обороны Альянса, поскольку обнажает глубокие угрозы в самом дворе Штормграда.",["race:Human"]="Для людей Штормграда это задание затрагивает саму стабильность вашей родины в период хрупкого регентства."},sec={{t="Тихий призыв",b="Во время путешествия по Штормграду скромный служка по имени Томас обращается к надежным искателям приключений с тихой просьбой. Епископу Делавею, уважаемому деятелю Церкви Священного Света при Крепости Штормграда, нужна помощь постороннего. Дело названо крайне деликатным и срочным и требует полной скрытности, чтобы не вызвать панику среди населения."},{t="Шепот в Крепости",b="Когда вы являетесь на призыв в Крепость Штормграда, епископ Делавей раскрывает причину такой секретности. Высокопоставленный сановник королевства исчез при загадочных обстоятельствах. В пору нарастающих внутренних волнений и таинственного отсутствия короля Вариана Ринна любой намек на преступление на высшем уровне грозит нарушить хрупкий мир в королевстве."}},faq={{q="Кто такой Томас?",a="Томас — юный служка Собора Света, выполняющий поручения епископа Делавея. Он высматривает на городских улицах толковых искателей приключений и тихо направляет их в Крепость Штормграда, когда для деликатных дел Церкви или государства нужны способные посредники.",al={"who is thomas","thomas stormwind","thomas quest giver","кто такой томас","томас штормград","томас выдает задание"}},{q="Кто такой епископ Делавей?",a="Епископ Делавей — старший священнослужитель Церкви Священного Света при Крепости Штормграда. Работая вместе с королевским двором, он занимается негласными вопросами безопасности королевства и деликатными расследованиями, которые обычная городская стража не может вести открыто.",al={"who is bishop delavey","delavey","bishop delavey","кто такой епископ делавей","делавей","епископ делавей"}},{q="Почему это дело ведется тайно?",a="Штормград и так на грани: король Вариан Ринн пропал, а Братство Справедливости поднимает мятеж по всему Западному Краю. Если распространится весть, что исчез еще один видный дипломат или чиновник, это может вызвать всеобщую панику или выдать врагам уязвимость двора.",al={"why discreet","why secrecy","why secret","почему скрытно","почему секретность","почему тайно"}},{q="Куда ведет это расследование?",a="Встреча с епископом Делавеем в Крепости Штормграда начинает обширное расследование, которое уводит вас в самое сердце политики королевства: по улицам Штормграда, затем в окрестные людские земли и дальше, в опасные земли за морем.",al={"where does missing diplomat go","missing diplomat next","куда ведет пропавший дипломат","пропавший дипломат дальше"}},{q="Кто такой пропавший дипломат?",a="В начале расследования точная личность дипломата строго хранится епископом Делавеем в тайне. Огласка поставила бы под угрозу текущие расследования и безопасность как пропавшего чиновника, так и королевства.",al={"who is the diplomat","identity of missing diplomat","кто дипломат","личность пропавшего дипломата"}}},fp="20,334,15.391.0,20.366.1,14.280.0,22.255.0,37.274.0,35.275.0,28.229.0"}
P.entries["quest:1275"] = {n="Исследование порчи",s="Гершал Шепот Ночи в Аубердине ищет зараженные стволы мозга у тварей, населяющих Непроглядную Пучину. Встревоженный слухами о том, что кровавые эльфы за морем балуются демонической магией, он надеется изучить физиологическое происхождение нага и сатиров, чтобы предвидеть — а может, и предотвратить — еще одну катастрофическую мутацию эльфов.",h="Гершал Шепот Ночи в Аубердине ищет зараженные стволы мозга у тварей, населяющих Непроглядную Пучину.",kw={"ashenvale","auberdine","blackfathom deeps","blood elves","corrupted brain stem","corruption abroad","gershala nightwhisper","naga","satyr","ясеневый лес","аубердин","непроглядная пучина","кровавые эльфы","зараженный ствол мозга","проблема за морем","гершал шепот ночи","нага","сатиры"},ang={["class:Druid"]="Друиды питают врожденное отвращение к сатирам, чья скверна оскверняет природный сон и искажает саму землю.",["class:Mage"]="Мрачное исследование Гершал — суровое напоминание о физической и духовной цене безрассудной, неограниченной зависимости от магии.",["faction:Alliance"]="Альянс настороженно следит за слухами о том, как кровавые эльфы за морем погружаются в темные искусства, опасаясь появления новой демонической угрозы.",["race:NightElf"]="Для ночных эльфов это исследование касается самой глубокой раны в их истории: катастрофического перерождения их сородичей в сатиров и нага, терзающих Калимдор."},sec={{t="Предупреждение из прошлого",b="Для ночных эльфов Калимдора гибель их древних сородичей — живая память, запечатленная в чудовищах. Десять тысяч лет назад высокорожденные поддались соблазну демонических энергий и превратились в рогатых сатиров или канули в пучину, став змеевидными нага. Когда высшие эльфы объявляют себя кровавыми эльфами и принимают темную магию, Гершал Шепот Ночи видит в этом не далекое любопытное явление, а историю, обреченную повториться."},{t="В глубины",b="Непроглядная Пучина — идеальное место для добычи образцов для мрачного исследования Гершал. Руины подземного храма, скрытые под Зорамским взморьем в Ясеневом лесу, кишат как сатирами-культистами, так и свернувшимися нага. Отправив искателя приключений за стволами мозга обоих чудовищ, он надеется вскрыть биологическую связь между магической зависимостью, демонической порчей и катастрофическим превращением тела."},{t="Отчаянное лекарство",b="Методы Гершал пугающе анатомичны, но цель, по его словам, — предотвратить беду. Он полагает, что, разгадав точные физиологические мутации, общие для сатиров и нага, можно получить знания, способные вернуть кровавых эльфов с края полной погибели. Сможет ли исследование, проведенное в Темных берегах, повлиять на отчаявшихся эльфов Кель'Таласа, остается открытым вопросом."}},faq={{q="Почему Гершал Шепот Ночи беспокоится о кровавых эльфах?",a="Гершал опасается, что заигрывание кровавых эльфов с демонической силой породит еще одну расу уродливых чудовищ, которая будет угрожать Азероту, подобно тому как гордыня эльфов прошлого породила сатиров и нага.",al={"why help blood elves","gershala blood elf connection","auberdine blood elves","зачем помогать кровавым эльфам","гершал и кровавые эльфы","аубердин кровавые эльфы"}},{q="Где добывать зараженные стволы мозга?",a="Их собирают у сатиров и нага, обитающих в Непроглядной Пучине — древнем храмовом комплексе, погребенном у Зорамского взморья на северо-западном побережье Ясеневого леса.",al={"where are brain stems","brain stem location","corrupt brain stem drop","где стволы мозга","ствол мозга где взять","зараженный ствол мозга добыча"}},{q="Почему ему нужны именно образцы сатиров и нага?",a="И сатиры, и нага происходят от эльфов, изуродованных неестественными силами: сатиры — через демонические сделки, а нага — через Раскол. Гершал хочет сравнить мутации их мозга, чтобы понять, как физиология эльфов разрушается под воздействием темной силы.",al={"why satyr and naga","satyr naga connection","почему сатиры и нага","сатиры и нага связь"}},{q="Кто направляет вас к этому заданию?",a="К Гершал Шепот Ночи в Аубердине вас может направить вводное задание «Проблема за морем», хотя это исследование он предложит и напрямую.",al={"prerequisite quest","corruption abroad connection","предыдущее задание","проблема за морем"}},{q="Что Гершал собирается делать с образцами?",a="Он планирует изучить физиологические связи между двумя видами порчи, надеясь, что полученные знания помогут остановить скатывание кровавых эльфов к еще более глубокому уродству.",al={"brain stem study","gershala research goal","изучение ствола мозга","цель исследования гершал"}},{q="Угрожает ли Аубердину Непроглядная Пучина?",a="Хотя Непроглядная Пучина лежит сразу за южной границей, в Ясеневом лесу, ночные эльфы Аубердина следят за всем прибрежным районом, высматривая признаки растущей демонической и сумеречной порчи.",al={"why auberdine cares","blackfathom deeps threat darkshore","почему аубердин беспокоится","угроза непроглядная пучина темные берега"}}},fp="26,328,22.436.0,14.404.0,16.379.1,58.190.0,46.171.0,53.260.0,27.175.0,49.187.0,54.194.0"}
P.entries["quest:128"] = {n="Награда за головы орков Черной горы",s="«Награда за головы орков Черной горы» — оборонный контракт, выданный стражником Хоувом в Приозерье от имени мирового судьи Соломона. Поскольку Штормград не шлет подкреплений, город платит независимым искателям приключений за истребление элитных поборников клана Черной горы, собирающихся в северных горах. Уничтожение этих командиров боевых отрядов призвано сорвать согласованное наступление орочьего клана на Красногорье.",h="«Награда за головы орков Черной горы» — оборонный контракт, выданный стражником Хоувом в Приозерье от имени...",kw={"blackrock","bounty","burning steppes","champion","guard howe","lakeshire","magistrate solomon","redridge","stormwind","черная гора","награда","пылающие степи","поборник","стражник хоув","приозерье","мировой судья соломон","красногорье","штормград"},ang={["class:Warrior"]="Поборники клана Черной горы — тяжело бронированные закаленные бойцы-ветераны, проверяющие дисциплину и выносливость воина в ближнем бою.",["faction:Alliance"]="Приозерье — восточный щит Штормграда; если орки Черной горы прорвутся через эти горные лагеря, основные земледельческие края Альянса окажутся под прямой угрозой вторжения.",["race:Human"]="Клан Черной горы разрушил первоначальное Королевство Штормград в Первую войну. Для защитников-людей не дать ему вернуться на юг — горькая, унаследованная от предков необходимость."},sec={{t="Защита суверенной границы",b="Красногорье давно находится под суверенной властью Королевства Штормград, но клан Черной горы не уважает человеческих границ. Хлынув через горные перевалы со стороны Пылающих степей, орки возвели сильно укрепленные лагеря по всему северу Красногорья. Поскольку король Вариан Ринн пропал, а регентство в Штормграде не присылает королевских солдат, местные главы, такие как мировой судья Соломон, вынуждены назначать награды из тающей городской казны, чтобы защитить Приозерье."},{t="Охота на поборников",b="Стражник Хоув называет поборников клана Черной горы опорой вторгающегося авангарда. Будучи командирами отрядов и закаленными в боях ветеранами своих банд, они направляют передвижения войск и гонят вперед рядовых грантов. Назначив цену за их головы, защитники Приозерья надеются сломить тактическое руководство клана и остановить полномасштабное наступление на юг, пока внешний периметр поселения не рухнул."}},faq={{q="Почему стражник Хоув предлагает награды вместо того, чтобы послать городскую стражу?",a="Местный гарнизон Приозерья растянут до предела. Патрулируя Озеро Безмолвия, охраняя мосты и отбиваясь от гноллов и орочьих налетчиков, стража не может выделить силы, достаточные для штурма укрепленных орочьих лагерей, не оставив город беззащитным.",al={"why bounties","where is town guard","guard howe bounty","почему награды","где городская стража","награда стражник хоув"}},{q="Где находятся поборники клана Черной горы?",a="Они расквартированы в обширных лагерях клана Черной горы на севере Красногорья, к западу от высокой дороги, ведущей к Пылающим степям.",al={"where are champions","champion location","blackrock champion camp","где поборники","расположение поборников","лагерь поборников черной горы"}},{q="Почему орки Черной горы вторгаются в Красногорье?",a="Действуя из Черной горы на севере, клан Черной горы видит в окрестных холмах стратегическую территорию для захвата и грабежа. Пользуясь раздробленностью обороны Штормграда, орки стремятся изгнать людские поселения и подчинить себе горные перевалы.",al={"why blackrock in redridge","why orcs attacking lakeshire","blackrock invasion","почему черная гора в красногорье","почему орки атакуют приозерье","вторжение черной горы"}},{q="Почему Штормград не посылает королевских солдат, чтобы их выбить?",a="Король Вариан Ринн пропал, а королевский двор под началом регента Болвара Фордрагона и леди Престор настаивает, что армии королевства нельзя отвлекать. Приозерье неоднократно просило столицу о помощи, но получало отказ и было вынуждено нанимать проезжих наемников.",al={"why no stormwind army","where is stormwind help","magistrate solomon reinforcements","почему нет армии штормграда","где помощь штормграда","подкрепления мирового судьи соломона"}},{q="Какую роль играют поборники в клане Черной горы?",a="Поборники — тактические командиры на передовой. Каждый боевой отряд Черной горы полагается на поборника, который направляет атаки, поддерживает жестокую дисциплину и ведет в бой на земли Альянса.",al={"what are blackrock champions","champion rank","blackrock leader unit","кто такие поборники черной горы","ранг поборника","командир черной горы"}},{q="Кто одобрил этот контракт на награду?",a="Мировой судья Соломон, глава гражданской власти Приозерья, одобрил награду и поручил стражнику Хоуву набрать способных бойцов для истребления.",al={"who pays bounty","who wants champions dead","magistrate solomon bounty","кто платит награду","кто хочет смерти поборников","награда мирового судьи соломона"}}},fp="16,386,26.506.0,23.435.0,70.285.0,42.157.0,45.266.0,60.261.0,55.181.0,36.153.0"}
P.entries["quest:129"] = {n="Бесплатный обед",s="«Бесплатный обед» — поручение Альянса, начинающееся в Приозерье, где трактирная повариха Дарси просит искателя приключений отнести готовый обед стражнику Паркеру. Паркер патрулирует опасную южную дорогу к Сумеречному лесу, не подпуская к Приозерью враждебных гноллов и орков Черной горы.",h="«Бесплатный обед» — поручение Альянса, начинающееся в Приозерье, где трактирная повариха Дарси просит...",kw={"blackrock orcs","darcy","darkshire","free lunch","gnolls","guard parker","lakeshire","parker's lunch","redridge mountains","орки черной горы","дарси","темнолесье","бесплатный обед","гноллы","стражник паркер","приозерье","обед паркера","красногорье"},ang={["faction:Alliance"]="Доставка еды от Дарси показывает, какое напряжение испытывают простые жители и рядовые часовые в дальних поселениях Альянса, оставленных в основном на произвол судьбы.",["profession:Cooking"]="Теплый, хорошо приготовленный паек в походе — часто единственное, что поддерживает одинокого часового на враждебном перекрестке."},sec={{t="Обед в дорогу",b="Повседневная жизнь в Красногорье полна напряжения, но Дарси, жительница Приозерья, по-своему старается поддержать защитников города. Собрав сытный обед для стражника Паркера, она не может доставить его сама. Местность сразу за городскими воротами кишит агрессивными гноллами Красногорья и бродячими орочьими бандами, и выходить за пределы города слишком опасно для небронированной горожанки. Поэтому она рассчитывает на проезжих путников, которые отнесут паек по дороге к Темнолесью."},{t="Охрана границы",b="Стражник Паркер стоит на дороге к югу от Приозерья и следит за путем, соединяющим Красногорье с Сумеречным лесом. Стража в Красногорье растянута до опасного предела: армия Штормграда не присылает достаточных подкреплений против растущих стай гноллов Красногорья и клана Черной горы, засевшего в горах. Одинокий дозор среди враждебных земель сильно изматывает часовых вроде Паркера, и простые знаки заботы горожан и горячая еда становятся важным подспорьем для боевого духа."}},faq={{q="Где найти стражника Паркера?",a="Стражник Паркер патрулирует южную грунтовую дорогу из Приозерья к границе Сумеречного леса и городу Темнолесье.",al={"guard parker location","where is parker","find guard parker","где стражник паркер","где паркер","найти стражника паркера"}},{q="Почему Дарси не относит обед сама?",a="Дарси — простая горожанка и считает окрестности Приозерья слишком опасными, чтобы бродить там в одиночку. Враждебные гноллы и орки Черной горы рыщут прямо у дорог за городом.",al={"why cant darcy go","darcy redridge","почему дарси не идет","дарси красногорье"}},{q="С какими угрозами имеет дело стражник Паркер?",a="Паркеру приходится удерживать южную дорогу против бродячих стай гноллов, обитающих в Красногорье, а также агрессивных орочьих отрядов клана Черной горы.",al={"parker enemies","redridge threats","враги паркера","угрозы красногорья"}},{q="Что происходит после того, как стражник Паркер получает обед?",a="Обед от Дарси вызывает у Паркера благодарность, и в итоге он отправляет искателя приключений с другими бытовыми поручениями между стражей и горожанами, начиная с визита к местному травнику.",al={"a free lunch next quest","parker follow up","бесплатный обед следующее задание","продолжение паркер"}},{q="Почему страже Штормграда трудно обеспечивать безопасность Красногорья?",a="Поскольку король Вариан Ринн пропал, а политическое руководство королевства занято делами в Штормграде, отдаленные поселения вроде Приозерья почти не получают военной поддержки, и отдельные городские стражники оказываются в полной изоляции.",al={"why is lakeshire undefended","stormwind neglect redridge","почему приозерье не защищено","штормград бросил красногорье"}},{q="Какую награду обещает Дарси?",a="В обмен на доставку обеда Паркеру через опасные земли Дарси обещает приготовить и подать бесплатный обед посыльному по возвращении в город.",al={"what is the free lunch","darcy reward","что за бесплатный обед","награда дарси"}}},fp="12,287,19.526.0,19.536.0,32.125.0,44.188.0,42.147.0,47.208.1,58.230.0,32.159.0"}
P.entries["quest:13"] = {n="Народное ополчение",s="Это задание отражает нарастающую кампанию отряда добровольцев Гриана Камнегрива по изгнанию Братства Справедливости из Западного Края. Поскольку воры перешли от мелкого разбоя на дорогах к организованному разграблению ключевых мест, таких как Луноречье и Прииск на Золотом Берегу, Народное ополчение требует более жестких ответных мер.",h="Это задание отражает нарастающую кампанию отряда добровольцев Гриана Камнегрива по изгнанию Братства...",kw={"alexston farmstead","defias looter","defias pillager","gold coast quarry","gryan stoutmantle","moonbrook","peoples militia","sentinel hill","westfall","поместье алекстона","мародер братства справедливости","поджигатель братства справедливости","прииск на золотом берегу","гриан камнегрив","луноречье","народное ополчение","сторожевой холм","западный край"},ang={["class:Paladin"]="Гриан Камнегрив прямо взывает к Свету, чтобы очистить Западный Край от преступной порчи, и потому для паладинов эта кампания — прямая миссия правосудия.",["faction:Alliance"]="Эта борьба показывает горький разрыв между уютными стенами Штормграда и его голодающими окраинами, полностью предоставленными самим себе.",["race:Human"]="Для людей королевства сражение здесь — трагическое столкновение с бывшими каменщиками и соседями, жестоко обратившимися против своего народа."},sec={{t="Нарастание насилия",b="Хотя ранние стычки с Братством Справедливости сводились к мелким бандитам, досаждавшим путникам на дорогах, угроза быстро растет. Мошенники и огнеметающие погромщики Братства захватили важные экономические центры Западного Края, полностью заняв Луноречье, разорив Поместье Алекстона и захватив Прииск на Золотом Берегу. Гриан Камнегрив понимает, что если эти разбойники закрепятся в этих центрах, вернуть область без королевской армии станет невозможно."},{t="Философия ополчения",b="Не имея ни официальных солдат, ни ресурсов из Штормграда, Гриан Камнегрив взывает к Свету и к моральной стойкости оставшихся фермеров Западного Края. Война на истощение, которую ведет ополчение, целиком держится на добровольцах, несущих бой прямо в оплоты Братства Справедливости. Изгнание мародеров должно лишить Братство ресурсов и показать напуганным жителям, что остались защитники, готовые бороться за мир и процветание Западного Края."}},faq={{q="Что такое Народное ополчение?",a="Народное ополчение — вооруженный добровольческий отряд обороны, организованный Грианом Камнегривом. Он состоит в основном из лишившихся домов фермеров Западного Края и сочувствующих путников и был создан для защиты провинции от Братства Справедливости после того, как королевский двор в Штормграде отказался направить городскую стражу.",al={"peoples militia","who are the militia","westfall militia","народное ополчение","кто такое ополчение","ополчение западного края"}},{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — опытный командир-человек, возглавляющий оборону Западного Края из оплота на Сторожевом холме. Преданный Свету и родной земле, он руководит Народным ополчением в его отчаянном сопротивлении власти преступников.",al={"gryan","who is stoutmantle","stoutmantle lore","гриан","кто такой камнегрив","камнегрив предания"}},{q="Почему Братство Справедливости грабит фермы и каменоломни?",a="Братство Справедливости стремится подорвать снабжение Западного Края продовольствием и захватить сырье. Захват Прииска на Золотом Берегу дает ему контроль над камнем и минералами, а захват Луноречья и поместий прогоняет честных людей и обеспечивает базы для преступных дел.",al={"why defias looting","defias in moonbrook","why pillagers at quarry","почему грабят братство справедливости","братство справедливости в луноречье","почему мародеры на прииске"}},{q="Почему Штормград не прислал солдат в Западный Край?",a="Король Вариан Ринн загадочно исчез, и на троне остался юный король Андуин при регентстве верховного лорда Болвара Фордрагона. Дом знати Штормграда сильно скован разногласиями, королевские ресурсы истощены, а отдаленные земли вроде Западного Края полностью брошены на местных защитников.",al={"where are stormwind guards","why no help from stormwind","king varian westfall","где стражи штормграда","почему нет помощи из штормграда","король вариан западный край"}},{q="Где находятся мошенники и погромщики Братства Справедливости?",a="Они сосредоточены в захваченных поселениях на юге и западе Западного Края, особенно в заброшенном городке Луноречье, на Прииске на Золотом Берегу вдоль западных утесов и в разрушенном Поместье Алекстона.",al={"pillager location","where are looters","defias locations","где мародеры","где поджигатели","места братства справедливости"}}},fp="20,306,19.490.0,24.453.0,29.296.0,25.242.0,46.285.0,47.305.0,45.207.0"}
P.entries["quest:130"] = {n="Визит к травнице",s="Доставив обед на его дальний пост, вы получаете от Стражника Паркера просьбу, прежде чем вернуться в таверну Приозерья. Желая выразить чувства к Дарси, он посылает вас к местной травнице за цветами. Паркер настаивает, чтобы травнице не говорили, кто их заказал и кому они предназначены.",h="Доставив обед на его дальний пост, вы получаете от Стражника Паркера просьбу, прежде чем вернуться в таверну...",kw={"daffodils","darcy","flowers","guard parker","lakeshire","martie jainrose","redridge","visit the herbalist","нарциссы","дарси","цветы","стражник паркер","приозерье","марти джанроз","красногорье","визит к травнице"},ang={["faction:Alliance"]="Даже при постоянной угрозе стай гноллов и орков Черной Скалы, давящих на Красногорье, среди защитников Приозерья продолжаются маленькие гражданские романы.",["profession:Herbalism"]="Визит к Марти Джанроз знакомит собирателей с главной торговкой травами и алхимическими товарами Приозерья на западной окраине города."},sec={{t="Тайная просьба стражника",b="Стражник Паркер несет вахту на одиноком южном подходе к Приозерью и высматривает орков Черной Скалы и гноллов. Когда вы приносите ему горячий обед от Дарси из Таверны Приозерья, он пользуется случаем отплатить ей добром. Вместо того чтобы просто отпустить вас, он просит зайти в местную лавку травницы на западной окраине города и купить для нее букет цветов."},{t="Городские сплетни и тайное ухаживание",b="В маленьком городке вроде Приозерья трудно что-то скрыть, потому Паркер и предупреждает вас не говорить травнице Марти Джанроз, от кого и для кого эти цветы. Когда вы приходите в ее лавку, Марти не может удержаться от шуток, решив, что вы быстро завели в городе возлюбленную. В крае, терзаемом набегами орков и разбойников, даже скромный романтический жест — желанное отвлечение."}},faq={{q="Кто посылает вас к травнице?",a="Это задание дает Стражник Паркер. Он стоит на страже южной дороги в Красногорье, к северу от границы с Сумеречным лесом.",al={"who gives this quest","quest giver","guard parker","кто дает это задание","персонаж, выдающий задания","стражник паркер"}},{q="Кто травница в Приозерье?",a="Марти Джанроз — местная травница и цветочница в Приозерье. Ее лавка находится на западной окраине города.",al={"who is martie jainrose","where is herbalist","lakeshire herbalist","кто такая марти джанроз","где травница","травница приозерья"}},{q="Зачем Стражнику Паркеру цветы?",a="Паркер хочет послать цветы Дарси, подавальщице из Таверны Приозерья, приславшей ему бесплатный обед, в знак симпатии и благодарности.",al={"why buy flowers","who are flowers for","parker motive","зачем покупать цветы","для кого цветы","мотив паркера"}},{q="Почему Паркер хочет сохранить покупку в тайне?",a="Приозерье — маленький тесный городок, где новости разлетаются быстро. Паркер стесняется ухаживать за Дарси и хочет избежать сплетен Марти Джанроз и остальных горожан.",al={"why secrecy","why hide who flowers are for","dont tell martie","зачем тайна","зачем скрывать, для кого цветы","не говорить марти"}},{q="Что происходит после разговора с Марти Джанроз?",a="Марти собирает букет нарциссов, и вы получаете задание доставить цветы прямо Дарси в Таверну Приозерья.",al={"what comes next","delivering daffodils","after herbalist","что дальше","доставка нарциссов","после травницы"}},{q="Какое место это задание занимает в цепочке?",a="Это задание — связующее звено между заданием «Бесплатный обед», где вы приносите обед Стражнику Паркеру, и заданием «Доставка нарциссов», где вы относите цветы Дарси.",al={"quest chain","prerequisite","free lunch chain","цепочка заданий","предыдущее задание","цепочка бесплатный обед"}}},fp="19,303,24.413.0,31.449.0,37.153.0,34.116.0,35.148.0,46.173.0,46.127.1,39.158.1"}
P.entries["quest:131"] = {n="Доставка нарциссов",s="«Доставка нарциссов» завершает небольшое домашнее поручение между сторожевым постом и городской площадью Приозерья. Принеся обед Стражнику Паркеру и забрав букет у травницы Марти Джанроз, вы передаете цветы Дарси в Таверне Приозерья и попадаете прямо в неловкое местное соперничество.",h="«Доставка нарциссов» завершает небольшое домашнее поручение между сторожевым постом и городской площадью...",kw={"daffodil bouquet","darcy","delivering daffodils","guard parker","lakeshire","martie jainrose","redridge","sauteed sunfish","букет нарциссов","дарси","доставка нарциссов","стражник паркер","приозерье","марти джанроз","красногорье","жареный солнечник"},ang={["faction:Alliance"]="Помощь городской страже и хозяйке таверны в Приозерье поддерживает дух жителей, пока город страдает от набегов Черной Скалы и гноллов.",["profession:Cooking"]="Дарси награждает вас за доставку приправленным жареным солнечником — примером простой домашней кухни озерного Красногорья.",["profession:Herbalism"]="Поручение опирается на знания Марти Джанроз о растениях и ее чутье на свежие озерные цветы и показывает мирную сторону сбора трав."},sec={{t="Душистое поручение",b="Простая услуга — доставка горячего обеда Стражнику Паркеру — превращается в деликатный романтический жест. Благодарный за обед, Паркер просит вас взять у Марти Джанроз цветы в сюрприз для Дарси, приготовившей его еду. Марти составляет свежий букет из своих любимых цветов — нарциссов, не зная, кому он предназначен."},{t="Городское соперничество",b="Когда вы приносите букет в Таверну Приозерья, первая радость Дарси быстро сменяется подозрением. Узнав нарциссы, любимые цветы Марти, Дарси сразу подозревает, что Паркер имел дело с женщиной, которую она считает ревнивой вертихвосткой. Опасаясь, что Марти из злобы отравила бы стебли, знай она получателя, Дарси снимает с вас вину и отдает горячую порцию жареного солнечника за труды."}},faq={{q="Кто такая Дарси?",a="Дарси работает в Таверне Приозерья в Красногорье и готовит еду для местных жителей и городской стражи. Это она послала обед Стражнику Паркеру, после чего Паркер в благодарность отправил ей букет цветов.",al={"darcy","who is darcy in lakeshire","lakeshire cook darcy","дарси","кто такая дарси в приозерье","повар приозерья дарси"}},{q="Кто такая Марти Джанроз?",a="Марти Джанроз — травница Приозерья и любительница цветов. Стражник Паркер направляет вас к ней за красивым букетом, и Марти охотно собирает нарциссы, замечая, что это ее любимые цветы.",al={"martie jainrose","lakeshire herbalist","who gave the flowers","марти джанроз","травница приозерья","кто дал цветы"}},{q="Почему Дарси расстроена из-за нарциссов?",a="Дарси сразу узнает в нарциссах любимые цветы Марти. Она считает Марти ревнивой соперницей и боится, что Марти отравила бы стебли, знай она, что букет предназначен Дарси.",al={"why is darcy angry","darcy martie feud","why poisoned flowers","почему дарси злится","вражда дарси и марти","почему отравленные цветы"}},{q="Марти на самом деле отравила букет?",a="Нет. Марти понятия не имела, что цветы предназначены Дарси: Паркер просто попросил вас взять букет, а Марти по привычке выбрала для него свои любимые цветы.",al={"are daffodils poisoned","is bouquet poisoned","отравлены ли нарциссы","отравлен ли букет"}},{q="Какие задания предшествуют этой доставке?",a="Цепочка начинается с задания «Бесплатный обед», где вы несете еду Дарси Стражнику Паркеру. Затем Паркер дает вам задание «Визит к травнице», чтобы купить подарок у Марти Джанроз, и цепочка завершается заданием «Доставка нарциссов».",al={"quest chain","daffodils prerequisites","delivering daffodils chain","цепочка заданий","что предшествует нарциссам","цепочка доставка нарциссов"}},{q="Какую награду вы получаете за доставку цветов?",a="Дарси благодарит вас сытной порцией жареного солнечника, небольшой суммой меди и опытом, а также повышением репутации у Штормграда.",al={"quest reward","daffodils rewards","награда за задание","награды за нарциссы"}}},fp="20,322,17.358.0,14.430.1,13.214.0,23.223.0,39.196.1,39.173.1,37.203.0,50.136.0"}
P.entries["quest:132"] = {n="Братство Справедливости",s="Это поручение доставляет важные тайные сведения от Вилли Черного обратно Гриану Камнегриву на Сторожевой холм. Донесение Вилли показывает, что Братство Справедливости — не просто разрозненная банда разбойников, а организованная сила, действующая заодно с местными гноллами, кобольдами и гоблинами. Камнегрив опирается на эти сведения, чтобы оценить весь масштаб заговора, душащего Западный Край.",h="Это поручение доставляет важные тайные сведения от Вилли Черного обратно Гриану Камнегриву на Сторожевой холм.",kw={"defias brotherhood","gnolls","goblins","gryan stoutmantle","kobolds","sentinel hill","westfall","wiley the black","wiley's note","братство справедливости","гноллы","гоблины","гриан камнегрив","кобольды","сторожевой холм","западный край","вилли черный","записка вилли"},ang={["class:Rogue"]="Вилли Черный — пример тайного агента, балансирующего между разбойником и полезным осведомителем, и показывает, как связи в преступном мире питают военную разведку.",["faction:Alliance"]="Обнаружение сговора между людьми-разбойниками, гноллами и гоблинами показывает, какая серьезная брешь в безопасности образовалась на западных границах Штормграда.",["race:Human"]="Для жителей Западного Края и Красногорья записка подтверждает, что бандиты, грабящие их семейные усадьбы, ведут продуманную, согласованную кампанию."},sec={{t="Опасное донесение",b="Вилли Черный утверждает, что разглашение того, что он знает о Братстве Справедливости, может стоить ему жизни. Действуя на окраинах Красногорья и Западного Края, Вилли прослышал о замыслах куда более грандиозных, чем разбой на дорогах. В его запечатанной записке подробно описано, как Братству удалось согласовать действия разрозненных, обычно враждебных друг другу групп по всей округе."},{t="Невероятные союзы",b="Суть предупреждения Вилли — тревожная сеть, созданная Братством Справедливости. Вместо того чтобы действовать в одиночку, разбойники в красных масках привлекли стаи гноллов, кобольдов-землекопов и оборотистых гоблинов-инженеров. Сочетание грубой силы, подземного труда и механической хитрости говорит о предприятии, превосходящем все, что поначалу ожидало Народное ополчение."},{t="Вынужденная опора Камнегрива",b="Гриан Камнегрив не питает к Вилли теплых чувств и открыто сожалеет, что не оставил негодяя гнить, когда была возможность. Но Западный Край не может позволить себе гордыню. Поскольку Штормград игнорирует мольбы о военной помощи, Народному ополчению приходится брать полезные сведения там, где их удается найти."}},faq={{q="О чем говорится в Записке Вилли?",a="В записке содержится предупреждение Вилли Черного о том, что Братство Справедливости действует заодно с гноллами, кобольдами и гоблинами-инженерами. Она сообщает Народному ополчению, что разбойники готовят масштабную операцию, далеко выходящую за рамки мелкого бандитизма.",al={"wiley note","what is in the note","wiley the black note","записка вилли","что в записке","записка вилли черного"}},{q="Кто такой Вилли Черный?",a="Вилли Черный — подозрительный осведомитель, обосновавшийся в Приозерье в Красногорье. Хотя Гриан Камнегрив считает его ненадежным мерзавцем, у Вилли обширные связи в преступном мире и важные сведения о действиях Братства Справедливости.",al={"who is wiley","wiley the black lore","wiley lakeshire","кто такой вилли","вилли черный","вилли приозерье"}},{q="Почему Братство Справедливости заключило союз с гноллами и кобольдами?",a="Братство Справедливости использует местных существ для контроля над землями и дешевой рабочей силы. Гноллы выставляют грубых застрельщиков, отвлекающих местных защитников, кобольды роют туннели в местных шахтах, а гоблины-механики поставляют тяжелую технику и инструменты для подрывных работ.",al={"why defias use gnolls","kobolds and defias","defias allies","зачем братству гноллы","кобольды и братство справедливости","союзники братства справедливости"}},{q="Почему Гриан Камнегрив недолюбливает Вилли?",a="Гриан Камнегрив — дисциплинированный бывший солдат, считающий Вилли обычным карманником и преступником. Камнегрив жалеет, что когда-то избавил его от тюрьмы, хотя и признает, что осведомленность Вилли в делах преступного мира незаменима.",al={"stoutmantle and wiley","why hate wiley","камнегрив и вилли","почему ненавидит вилли"}},{q="Какое место это донесение занимает в расследовании ополчения?",a="Эта доставка — мост между местной разведкой и раскрытием более глубокого заговора Братства Справедливости. Возвращенное донесение Вилли побуждает Камнегрива глубже изучить руководство заговора и места сбора.",al={"defias chain step","what quest is this","цепочка братства справедливости","что это за задание"}},{q="Почему Штормград не занимается этой угрозой?",a="Поскольку король Вариан Ринн пропал, Дом знати Штормграда отказывается направлять королевских солдат или средства на защиту Западного Края. Область предоставлена сама себе и защищается силами разношерстного Народного ополчения под началом Камнегрива.",al={"stormwind help westfall","where are the guards","помощь штормграда западному краю","где стража"}}},fp="22,388,20.367.0,18.378.0,29.299.0,27.241.0,23.242.0,50.257.0,41.224.0,61.224.0,41.217.0"}
P.entries["quest:133"] = {n="Фигурка вурдалака",s="В мрачной глуши Сумеречного леса чудаковатый отшельник Аберкромби утверждает, что его уединенная хижина осаждена ходячими мертвецами. Чтобы защитить дом, он поручает проходящим искателям приключений добыть ребра вурдалаков для странного защитного пугала.",h="В мрачной глуши Сумеречного леса чудаковатый отшельник Аберкромби утверждает, что его уединенная хижина...",kw={"abercrombie","bone chewers","darkshire","duskwood","effigy","flesh eaters","ghoul rib","hermit","аберкромби","грызуны костей","темнолесье","сумеречный лес","фигурка","пожиратели плоти","ребра вурдалаков","отшельник"},ang={["class:Paladin"]="Охота на пожирателей плоти и грызунов костей очищает землю Сумеречного леса от порчи, даже если передавать их останки отшельнику крайне неприятно.",["class:Priest"]="Помощь напуганному отшельнику, оказавшемуся среди темных духов, — благое дело, хотя изготовление чучел из собранных останков испытывает желудок на прочность.",["faction:Alliance"]="Ночной Дозор с трудом охраняет дороги, и одиноким жителям леса, таким как Аберкромби, остается рассчитывать на защиту проходящих путников Альянса от неупокоенных мертвецов."},sec={{t="Беда отшельника",b="Аберкромби живет далеко за охраняемыми границами Темнолесья, в одиночестве среди сумрачных деревьев Сумеречного леса. Здесь без помех бродят вурдалаки, такие как пожиратели плоти и грызуны костей. Утверждая, что голодные трупы недавно проломили его стены, перепуганный отшельник просит принести ребра этих чудовищ, чтобы сделать отпугивающее чучело, надеясь, что жуткая фигура отгонит голодных мертвецов."},{t="Странная защита",b="Здравый смысл подсказывал бы искать защиты у Ночного Дозора или укрепить деревянную хижину, но Аберкромби настаивает на жутких методах. Он верит, что фигура из останков вурдалаков отпугнет других мертвецов-падальщиков. Хотя пугало из убитой нежити кажется тревожным, путники в Сумеречном лесу часто верят чудаковатому отшельнику на слово, чтобы заработать немного монет."}},faq={{q="Где живет Аберкромби?",a="Аберкромби живет в одинокой хижине в западной части Сумеречного леса, к северо-востоку от Кладбища Вороньего Холма и вдали от защиты Темнолесья.",al={"abercrombie location","where is abercrombies shack","hermit shack duskwood","где живет аберкромби","хижина аберкромби","хижина отшельника сумеречный лес"}},{q="Зачем Аберкромби нужны ребра вурдалаков?",a="Аберкромби утверждает, что стаи вурдалаков колотят в стены его хижины. Из костей он хочет сделать жуткое пугало, чтобы отпугнуть мертвецов-падальщиков.",al={"ghoul ribs purpose","why ghoul ribs","what is the effigy for","зачем ребра вурдалаков","для чего ребра","для чего нужна фигурка"}},{q="С каких существ падают ребра вурдалаков?",a="Ребра можно собрать с любой местной нежити, бродящей по дорогам и кладбищам Сумеречного леса: с пожирателей плоти, грызунов костей, пожирателей мозга, гнилых и разносчиков чумы.",al={"where to get ribs","ghoul rib drops","which ghouls drop ribs","где взять ребра","с кого падают ребра вурдалаков","какие вурдалаки дают ребра"}},{q="Действительно ли пугало из нежити отпугивает вурдалаков?",a="Нежить редко проявляет страх, поэтому план Аберкромби кажется сомнительным опытным охотникам на чудовищ. Тем не менее отшельник стоит на своем, а в такой отчаянной глуши мало кто сомневается в нанимателе, который платит.",al={"do effigies work on ghouls","ghoul scarecrow logic","помогают ли пугала от вурдалаков","логика пугала от вурдалаков"}},{q="Почему Аберкромби просто не переселится в Темнолесье?",a="Аберкромби предпочитает жить в уединении вдали от Ночного Дозора и городского управления. Несмотря на очевидные опасности сумеречной глуши, он предпочитает в одиночку управляться с хижиной, используя собственные странные средства защиты.",al={"why live in woods","why doesn't abercrombie move","darkshire safety","почему живет в лесу","почему аберкромби не переезжает","безопасность темнолесья"}},{q="Что дальше после сбора ребер?",a="Получив ребра вурдалаков, Аберкромби находит очередную странную задачу и отправляет искателей приключений дальше в глушь разобраться с местными ограми, укравшими его вещи.",al={"next quest","what after ghoulish effigy","следующее задание","что после фигурки вурдалака"}}},fp="15,258,17.392.0,17.409.0,28.140.0,37.170.0,36.186.0,56.197.0,53.208.0,41.182.0"}
P.entries["quest:1338"] = {n="Заказ Грозовой Вершины",s="Горный пехотинец Грозовая Вершина, несущий службу в заснеженных скалах Лок Модана, желает получить щит работы знаменитого оружейника Фьюрена Длинноборода. Поскольку Фьюрен открыл мастерскую далеко на юге, в Штормграде, пехотинец поручает путешествующему искателю приключений доставить заказ.",h="Горный пехотинец Грозовая Вершина, несущий службу в заснеженных скалах Лок Модана, желает получить щит работы...",kw={"armorsmith","dwarven district","furen longbeard","ironforge","loch modan","shield","stormpike","stormwind","оружейник","квартал дворфов","фьюрен длиннобород","стальгорн","лок модан","щит","грозовая вершина","штормград"},ang={["faction:Alliance"]="Доставка демонстрирует тесные торговые и культурные связи дворфийских твердынь Каз Модана со столицей людей Штормградом благодаря Подземному поезду.",["profession:Blacksmithing"]="Фьюрен Длиннобород признан оружейником исключительного мастерства даже в других королевствах, поэтому остановка у него заслуживает внимания начинающих кузнецов, проезжающих через Штормград.",["race:Dwarf"]="Для дворфов эта доставка показывает влияние кланов вроде Грозовой Вершины, а заодно шутливо ставит вопрос, почему мастер-оружейник выбрал человеческий камень вместо Стальгорна."},sec={{t="Щит, достойный путешествия",b="Даже в отдаленных форпостах вроде Лок Модана горные пехотинцы-дворфы строго судят о мастерстве. Горный пехотинец Грозовая Вершина настаивает, что его следующий щит может выковать лишь один кузнец — Фьюрен Длиннобород. Убежденный, что талант Длиннобород не знает равных, Грозовая Вершина готов щедро заплатить, чтобы заказ попал в руки мастера, несмотря на огромное расстояние."},{t="Из Стальгорна в Квартал Дворфов",b="Больше всего Грозовую Вершину озадачивает местонахождение Фьюрена. Вместо того чтобы жить рядом с Великой кузней Стальгорна среди сородичей, Длиннобород зарабатывает на жизнь далеко на юге, в Квартале Дворфов Штормграда. Грозовая Вершина полагает, что люди платят ему королевский выкуп, чтобы переманить такого мастера из родных мест. Когда послание наконец доходит до Фьюрена у наковальни, кузнец гордится вестью от знатного клана Грозовой Вершины и охотно готовится выковать щит."}},faq={{q="Кто такой Горный пехотинец Грозовая Вершина?",a="Это часовой Альянса, несущий службу в Лок Модане, один из горных пехотинцев-дворфов, охраняющих горные перевалы и долины. Он принадлежит к гордому и влиятельному клану Грозовой Вершины.",al={"mountaineer stormpike","who gives the quest","quest giver","горный пехотинец грозовая вершина","кто дает задание","персонаж, выдающий задания"}},{q="Кто такой Фьюрен Длиннобород?",a="Фьюрен Длиннобород — искусный дворфийский оружейник, живущий в Квартале Дворфов города Штормград. Слава о его превосходных щитах и доспехах дошла до самого Каз Модана на севере.",al={"furen longbeard","who is furen","the armorsmith","фьюрен длиннобород","кто такой фьюрен","оружейник"}},{q="Почему Фьюрен живет в Штормграде, а не в Стальгорне?",a="Пока традиционалисты вроде горного пехотинца Грозовая Вершина недоумевают, зачем мастеру-дворфу покидать Стальгорн, Фьюрен занимается ремеслом в Квартале Дворфов Штормграда, обслуживая человеческую знать, городскую стражу и странствующих искателей приключений и, вероятно, получая немалый доход в человеческих монетах.",al={"why is furen in stormwind","why dwarven district","furen leaving ironforge","почему фьюрен в штормграде","почему квартал дворфов","фьюрен покинул стальгорн"}},{q="Какую роль в доставке этого заказа играет Подземный поезд?",a="Путники с посланием Грозовой Вершины обычно идут на юг от Лок Модана через Стальгорн, а затем садятся на Подземный поезд, который доставляет их прямо в Квартал Дворфов города Штормград, где находится кузня Фьюрена.",al={"travel to stormwind","how to get to stormwind","deeprun tram","путь в штормград","как добраться до штормграда","подземный поезд"}},{q="Какое задание предшествует этому?",a="Прежде чем доверить вам это поручение курьера в Штормград, Горный пехотинец Грозовая Вершина проверяет вашу стойкость и надежность в Лок Модане заданием «Задание Грозовой Вершины».",al={"prerequisites","previous quest","mountaineer stormpike's task","предыдущие условия","предыдущее задание","задание грозовой вершины"}},{q="Выкует ли Фьюрен Длиннобород щит немедленно?",a="Получив письмо и осознав знатность имени Грозовой Вершины, Фьюрен охотно принимает заказ и обещает приступить к ковке щита до конца дня.",al={"what happens next","followup quest","furen reaction","что дальше","следующее задание","реакция фьюрена"}}},fp="17,286,26.381.0,38.486.0,29.187.0,23.203.0,54.272.0,57.217.0,29.168.0,50.188.0"}
P.entries["quest:1339"] = {n="Задание Грозовой Вершины",s="Задание Грозовой Вершины — короткое поручение курьера Альянса в Лок Модане. Горный пехотинец Кэдрелл направляет странствующих авантюристов к северной сторожевой башне, где горному пехотинцу Грозовая Вершина нужен надежный посыльный для поручения за пределами долины. Оно служит началом более длинной цепочки заданий, ведущей в соседние земли.",h="Задание Грозовой Вершины — короткое поручение курьера Альянса в Лок Модане.",kw={"guard tower","ironforge","loch modan","mountaineer kadrell","mountaineer stormpike","runner","stormpike's order","thelsamar","сторожевая башня","стальгорн","лок модан","горный пехотинец кэдрелл","горный пехотинец грозовая вершина","посыльный","заказ грозовой вершины","телсамар"},ang={["faction:Alliance"]="Курьерские поручения для горных пехотинцев помогают снабжать и координировать гарнизоны Стальгорна в восточных землях.",["race:Dwarf"]="Помочь собрату-дворфу из знаменитого рода Грозовой Вершины — естественный долг для любого странника, чтящего клановые узы по всему Каз Модану."},sec={{t="Страж, которому нужен посыльный",b="Патрулирование дорог и застав Лок Модана оставляет горных пехотинцев в растянутом положении перед набегами троггов и дикими зверями. Горный пехотинец Кэдрелл часто направляет способных путников к стражам, которые не могут покинуть свои посты. Горный пехотинец Грозовая Вершина, несущий службу высоко в северной сторожевой башне, прикован к дозору как раз тогда, когда срочное личное дело требует посыльного, способного отправиться далеко за границы региона."},{t="От башни к дальним дорогам",b="Чтобы добраться до Грозовой Вершины, нужно подняться на северную сторожевую башню, возвышающуюся над долиной. Как член знатного клана Грозовой Вершины, он часто занимается делами, выходящими за рамки обычной обороны границ Телсамара. Взять его задание означает согласиться доставлять вести и припасы за пределы региона от его имени. Для неопытных искателей приключений это первый серьезный шаг от озера к более широким дорогам Каз Модана."}},faq={{q="Где найти горного пехотинца Грозовая Вершина?",a="Горный пехотинец Грозовая Вершина несет службу на самом верху северной сторожевой башни в Лок Модане и следит за окрестными тропами.",al={"stormpike location","where is stormpike","find stormpike tower","где грозовая вершина","где найти пехотинца грозовая вершина","башня грозовой вершины"}},{q="Кто выдает это задание?",a="Горный пехотинец Кэдрелл, патрулирующий окрестности Телсамара в Лок Модане, дает это задание и указывает вам путь к башне Грозовой Вершины.",al={"who gives mountaineer stormpikes task","quest starter","kadrell location","кто дает задание грозовой вершины","начало задания","где кэдрелл"}},{q="Почему Грозовой Вершине нужен авантюрист?",a="Как действующий горный пехотинец, он не может покинуть пост у башни. Его личное поручение требует поездки далеко за пределы Лок Модана, поэтому свободный авантюрист — идеальный посыльный.",al={"why need runner","stormpike problem","what does stormpike want","зачем нужен посыльный","проблема грозовой вершины","что хочет грозовая вершина"}},{q="Что будет после разговора с горным пехотинцем Грозовая Вершина?",a="Разговор с ним завершает этот вводный этап и открывает следующее поручение — «Заказ Грозовой Вершины», в котором вам предстоит доставить груз в другую область.",al={"next quest","what comes after mountaineer stormpikes task","stormpike followup","следующее задание","что после задания грозовой вершины","продолжение грозовой вершины"}},{q="Связано ли это со Стражей Грозовой Вершины в Альтераке?",a="Горный пехотинец Грозовая Вершина носит то же имя и кровь знаменитого клана Грозовой Вершины, известного Стражей Грозовой Вершины и своими горными экспедициями, но это задание — скромное местное поручение.",al={"stormpike clan connection","alterac valley stormpike","is this the av stormpikes","клан грозовой вершины","альтеракская долина грозовая вершина","это стража грозовой вершины"}},{q="Есть ли здесь аналогичное задание для Орды?",a="Нет. Лок Модан — суверенная территория дворфов, всецело союзная Альянсу, и горные пехотинцы нападают на путников из Орды при первой встрече.",al={"horde version","can horde do this","версия для орды","может ли орда выполнить"}}},fp="28,332,30.440.0,27.414.0,38.136.0,22.124.0,38.194.0,42.167.0,50.198.0,47.140.0"}
P.entries["quest:135"] = {n="Братство Справедливости",s="Это задание — важный поворотный момент в борьбе с разбойниками, терзающими Западный Край. Гриан Камнегрив отправляет вас в Штормград с загадочной запиской для Мастера Матиаса Шоу: он подозревает, что Братство Справедливости связано со старой Гильдией каменщиков.",h="Это задание — важный поворотный момент в борьбе с разбойниками, терзающими Западный Край.",kw={"brotherhood","defias","gryan stoutmantle","mathias shaw","old town","si:7","stonemasons","westfall","wiley's note","братство","братство справедливости","гриан камнегрив","матиас шоу","старый город","шру","каменщики","западный край","записка вилли"},ang={["class:Rogue"]="Посетив штаб-квартиру ШРУ, вы встретитесь лицом к лицу с Матиасом Шоу, великим мастером разбойников и шпионов Штормграда, и увидите местные беспорядки Западного Края в свете более высокого шпионского искусства.",["faction:Alliance"]="Задание обнажает внутренние трещины в главном королевстве Альянса и показывает, что не все угрозы исходят от чудовищных чужаков — некоторые от преданных граждан.",["race:Human"]="Для людей Штормграда это задание связывает беззаконную окраину Западного Края с горькими нерешенными политическими скандалами, последовавшими за восстановлением их столицы."},sec={{t="Оговорка",b="Расследуя беспорядки в Западном Крае, Гриан Камнегрив замечает любопытную деталь в посланиях Вилли: упоминание каменщиков. Гильдию строителей, отстроивших Штормград после Первой войны, давно считали распавшейся. Если Братство Справедливости с ней связано, то этот сельский мятеж — гораздо больше, чем шайка разрозненных изгоев."},{t="Тайны Старого города",b="Камнегрив не может проверить эти подозрения из Сторожевого холма. За настоящими сведениями королевства он направляет вас к Мастеру Матиасу Шоу, главе тайной разведки Штормграда — ШРУ. Действуя из казарм Старого города, Шоу собирает слухи и тайны по всему королевству, и только он способен распутать происхождение Братства Справедливости."},{t="Тень над короной",b="Увидев Записку Вилли, Шоу сразу понимает серьезность положения. Он подтверждает, что мятеж в Западном Крае гораздо глубже и политически сложнее, чем способен понять простой командир ополчения вроде Камнегрива, и указывает прямо на бурное прошлое самого Штормграда."}},faq={{q="Почему Гриан Камнегрив отправляет вас в Штормград?",a="Камнегрив находит в записке Вилли упоминание каменщиков. Поняв, что это указывает на политическую интригу, а не на простой разбой, он отправляет вас к Мастеру Матиасу Шоу, шефу шпионов Штормграда, чтобы подтвердить связь.",al={"why go to stormwind","why stormwind quest","stoutmantle stormwind errand","зачем идти в штормград","почему задание в штормграде","поручение камнегрива в штормград"}},{q="Кто такой Матиас Шоу?",a="Мастер Матиас Шоу — глава ШРУ, тайной разведывательной и шпионской службы Королевства Штормград. Он работает из штаб-квартиры, скрытой в казармах Старого города.",al={"who is shaw","mathias shaw role","si7 leader","кто такой шоу","роль матиаса шоу","глава шру"}},{q="Где найти Матиаса Шоу?",a="Шоу находится на втором этаже штаб-квартиры ШРУ в казармах Старого города в Штормграде.",al={"where is shaw","shaw location","find mathias shaw","где шоу","местонахождение шоу","найти матиаса шоу"}},{q="Какая связь между Братством Справедливости и каменщиками?",a="Гильдия каменщиков отстроила Штормград после его разрушения в Первой войне. После жесткого спора об оплате с Домом знати гильдию обманули с платой, и озлобленные каменщики позже тайно объединились вновь как Братство Справедливости, чтобы отомстить.",al={"defias stonemasons","are defias stonemasons","stonemason connection","братство справедливости каменщики","каменщики и братство","связь с каменщиками"}},{q="Что такое Записка Вилли?",a="Это записка от Вилли Черного, негодяя, с которым Гриан Камнегрив уже имел дело; в ней предупреждается, что Братство Справедливости сговаривается с гноллами, кобольдами и гоблинами. Оговорка в ней невольно связывает действия Братства Справедливости с бывшей Гильдией каменщиков.",al={"wileys note","what is the note","note to shaw","записка вилли","что за записка","записка для шоу"}},{q="Знают ли об этом верховный лорд Болвар или юный король?",a="Дела тайной государственной безопасности проходят через Матиаса Шоу и ШРУ, прежде чем попасть к верховному лорду Болвару Фордрагону и на трон. Шоу лишь отвечает, что дело может быть сложнее, чем думает Камнегрив.",al={"does the king know","does bolvar know","stormwind government knowledge","знает ли король","знает ли болвар","осведомленность власти штормграда"}}},fp="22,277,20.377.0,16.350.0,25.321.1,49.239.0,20.188.0,29.105.0,62.270.1,21.277.0,53.222.0"}
P.entries["quest:1358"] = {n="Образец для Хелбрима",s="«Образец для Хелбрима» — задание Орды для курьеров, связывающее алхимические опыты Подгорода с аванпостами Отрекшихся в центральном Калимдоре. Его выдает аптекарь Зинг и отправляет курьеров за море, чтобы доставить зараженное сердце волка аптекарю Хелбриму на Перекресток.",h="«Образец для Хелбрима» — задание Орды для курьеров, связывающее алхимические опыты Подгорода с аванпостами...",kw={"apothecary helbrim","apothecary zinge","crossroads","royal apothecary society","sample for helbrim","the barrens","undercity","wolf heart sample","аптекарь хелбрим","аптекарь зинг","перекресток","королевское фармацевтическое общество","образец для хелбрима","степи","подгород","образец сердца волка"},ang={["faction:Horde"]="Хотя орки и таурены рады помощи Отрекшихся в обороне Перекрестка, тихие вскрытия зараженных останков, которые проводят аптекари, вносят мрачное и тревожное присутствие в мирные Степи.",["race:Undead"]="Перевозка оскверненных образцов через весь мир показывает далеко идущие замыслы Королевского фармацевтического общества — обеспечить господство Отрекшихся с помощью химического превосходства."},sec={{t="Зараза за морем",b="Королевское фармацевтическое общество редко ограничивает свои жуткие опыты руинами Лордерона. Получив оскверненные органы от аптекаря Ренферрела в Серебряном бору, аптекарь Зинг в Подгороде решила расширить исследования до мирового масштаба. Она доверила искателю приключений «Образец сердца волка», чтобы тот доставил его за море аптекарю Хелбриму, алхимику, который служит в засушливой саванне Степей."},{t="Замысел Хелбрима",b="Аптекарь Хелбрим работает на вершине башни на Перекрестке и изучает, как местные звери Калимдора реагируют на губительные составы, созданные в Чумных землях. Доставленное сердце волка дает ценные сведения о крайней токсичности. Хелбрим считает, что вскрытие и испытание образца вместе с местными животными заметно продвинет мастерство Отрекшихся в обращении с ядами и неестественными недугами."}},faq={{q="Что за посылка предназначена для Хелбрима?",a="В посылке находится «Образец сердца волка», который аптекарь Ренферрел взял у порченых волков Серебряного бора, а аптекарь Зинг изучила в Подгороде.",al={"what is the sample","wolf heart package","what did zinge give me","что за образец","посылка с сердцем волка","что дала мне зинг"}},{q="Почему аптекарю Хелбриму нужно оскверненное сердце волка?",a="Хелбрим исследует, как яды, созданные в Лордероне, влияют на животный мир Калимдора. Он намерен изучить крайнюю токсичность сердца, чтобы создать более сильные составы и яды для Королевского фармацевтического общества.",al={"why does helbrim need wolf heart","helbrim research","helbrim purpose","зачем хелбриму сердце волка","исследования хелбрима","цель хелбрима"}},{q="Где находится аптекарь Хелбрим?",a="Хелбрим служит на Перекрестке в Степях. Его можно найти на верхней внешней площадке центральной сторожевой башни, с которой виден весь поселок.",al={"where is helbrim","helbrim location","find helbrim","где хелбрим","местонахождение хелбрима","найти хелбрима"}},{q="Как путешественнику добраться из Подгорода на Перекресток?",a="Путешественники поднимаются на дирижабле с башни у Подгорода и прибывают в Оргриммар в Дуротаре. Из Оргриммара вы идете на юг через Дуротар, пересекаете Реку Строптивую, попадаете в Степи и продолжаете путь на запад по главной дороге до Перекрестка.",al={"travel to crossroads","how to get to helbrim","undercity to barrens","путь на перекресток","как добраться до хелбрима","из подгорода в степи"}},{q="Кто такие аптекарь Ренферрел и аптекарь Зинг?",a="Оба они исследователи Королевского фармацевтического общества. Ренферрел работает в Гробнице в Серебряном бору, а Зинг проводит исследования в Апотекариуме в Подгороде.",al={"who is renferrel","who is zinge","zinge and renferrel lore","кто такой ренферрел","кто такая зинг","предания о зинг и ренферреле"}},{q="Чьим интересам служит это исследование?",a="Это исследование напрямую служит Отрекшимся и Королевскому фармацевтическому обществу под началом леди Сильваны Ветрокрылой и способствует их общим усилиям по созданию смертоносного химического и биологического оружия.",al={"who benefits","is this for sylvanas","apothecary goal","кому это выгодно","для сильваны ли это","цель аптекарей"}}},fp="18,268,26.408.0,18.395.0,47.184.0,54.223.0,36.151.0,57.235.0,50.195.0,38.195.0"}
P.entries["quest:1359"] = {n="Посылка для Зинг",s="«Посылка для Зинг» — задание для курьеров от аптекаря Ренферрела из Гробницы в Серебряном бору. Курьер относит необычно ядовитую ткань сердца волка аптекарю Зинг в Подгород для официального изучения Королевским фармацевтическим обществом.",h="«Посылка для Зинг» — задание для курьеров от аптекаря Ренферрела из Гробницы в Серебряном бору.",kw={"apothecarium","apothecary renferrel","apothecary zinge","sepulcher","silverpine","undercity","wolf heart samples","zinge's delivery","апотекариум","аптекарь ренферрел","аптекарь зинг","гробница","серебряный бор","подгород","образцы сердца волка","посылка для зинг"},ang={["faction:Horde"]="Посланники, несущие биологические реагенты, связывают дальние аванпосты, такие как Гробница, с руководством и исследовательскими центрами в Подгороде.",["race:Undead"]="Полевые образцы, собранные в Лордероне, поступают прямо в центральные алхимические лаборатории под руинами Столицы, повышая научную мощь Отрекшихся."},sec={{t="Ядовитая аномалия",b="Изучая местных животных в Серебряном бору, аптекарь Ренферрел заметил тревожную особенность у волков, бродящих по разоренным лесам. Их сердца были настолько ядовиты, что при любых обычных обстоятельствах должны были убить носивших их зверей. Вместо того чтобы выбросить ткань, Ренферрел упаковал несколько образцов, чтобы поделиться с коллегами в Апотекариуме в Подгороде."},{t="Глаза Апотекариума",b="Сохраненные органы доставляются прямо аптекарю Зинг, исследовательнице, работающей в подземной штаб-квартире Королевского фармацевтического общества. Для общества, главная цель которого — создание сильных чум и новых алхимических составов, природные яды, которые поддерживают жизнь, а не убивают, представляют первостепенный интерес. Зинг встречает посылку как основу для дальнейших лабораторных испытаний во всей алхимической сети Отрекшихся."}},faq={{q="Что такое образцы сердца волка?",a="Это консервированные биологические ткани, собранные у волков Серебряного бора. Аптекарь Ренферрел обнаружил, что в сердцах содержатся природные токсины, настолько смертоносные, что животные не должны были выжить, неся их в себе.",al={"wolf hearts","what are wolf heart samples","renferrel samples","сердца волков","что такое образцы сердца волка","образцы ренферрела"}},{q="Кто такой аптекарь Ренферрел?",a="Аптекарь Ренферрел — член Королевского фармацевтического общества, служащий в Гробнице в Серебряном бору. Он руководит полевыми исследованиями местной флоры и фауны, собирая ингредиенты и биологические сведения для алхимии Отрекшихся.",al={"who is renferrel","renferrel silverpine","кто такой ренферрел","ренферрел серебряный бор"}},{q="Кто такая аптекарь Зинг?",a="Аптекарь Зинг — исследовательница-алхимик из квартала Апотекариум в Подгороде. Она ставит опыты на поступающих биологических образцах, чтобы открыть для Отрекшихся новые токсины и алхимические средства.",al={"who is zinge","zinge undercity","apothecary zinge lore","кто такая зинг","зинг подгород","предания об аптекаре зинг"}},{q="Куда ведет эта доставка дальше?",a="Когда Зинг получит и осмотрит необычную ткань сердца, исследование продолжится: образцы направят на другие алхимические аванпосты, например к аптекарю Хелбриму, который служит за морем, в Степях.",al={"next quest","what happens after zinge's delivery","follow up quest","следующее задание","что будет после посылки для зинг","продолжение задания"}},{q="Почему Королевское фармацевтическое общество интересуют сердца волков?",a="Королевское фармацевтическое общество постоянно ищет редкие яды, болезни и биологические аномалии. Зверь, переживший смертельную самотоксичность, открывает уникальные химические пути, которые могли бы помочь в создании новых чум и составов.",al={"why do apothecaries want wolf hearts","ras wolf hearts","зачем аптекарям сердца волков","кфо сердца волков"}},{q="Где находится Апотекариум в Подгороде?",a="Апотекариум образует юго-западное крыло Подгорода. Это главный лабораторный комплекс и управляющая штаб-квартира Королевского фармацевтического общества.",al={"undercity apothecary location","where is zinge","apothecarium map","где аптекари в подгороде","где зинг","карта апотекариума"}}},fp="16,250,15.439.0,28.454.0,32.221.0,28.237.0,24.213.0,35.201.1,62.237.0,39.166.0"}
P.entries["quest:136"] = {n="Спрятанное сокровище капитана Сандерса",s="«Спрятанное сокровище капитана Сандерса» — первый шаг многоэтапной охоты за сокровищами на побережье Западного Края. Потрепанная пергаментная карта отправляет искателей сокровищ обшаривать берег в поисках личного сундука покойного капитана. Найденный закопанный сундук запускает погоню по всему краю за его спрятанной добычей.",h="«Спрятанное сокровище капитана Сандерса» — первый шаг многоэтапной охоты за сокровищами на побережье...",kw={"captain sanders","footlocker","hidden treasure","rusty anchor","shipwreck","treasure map","westfall coast","капитан сандерс","сундук","спрятанное сокровище","ржавый якорь","кораблекрушение","карта сокровищ","побережье западного края"},ang={["class:Rogue"]="Охота за сокровищами пиратов — вторая натура для негодяев и каперов, знающих цену карте мертвого моряка на беззаконном берегу.",["faction:Alliance"]="Побережье Западного Края изобилует прибрежными мурлоками и обломками кораблей, поэтому любая находка морского состояния — маленькая победа среди смуты на границе королевства."},sec={{t="Последняя воля моряка",b="Море у западного берега Западного Края усеяно кораблекрушениями, разбитыми корпусами и неупокоенными духами утонувших моряков. Среди погибших в пучине был капитан Сандерс, старый мореход, нашедший могилу в волнах. Чтобы его трудом нажитое состояние не пропало в Великом море и не было украдено мародерами, старый морской волк записал ряд загадочных указаний и оставил след, который мог повторить лишь целеустремленный искатель приключений."},{t="Ржавый якорь",b="Первый шаг охоты указывает искателю на одинокий ржавый якорь в прибое у западного берега. Старый сундук капитана наполовину зарыт в песок возле обломков корабля и пережил удары волн. Внутри не золото, а морская вода, песок и неожиданный страж: юркий краб, сжимающий следующую часть загадки Сандерса."}},faq={{q="Кем был капитан Сандерс?",a="Капитан Сандерс был моряком, чей корабль разбился у коварных берегов Западного Края. Зная, что ему суждена могила в волнах, он оставил карту и ряд подсказок, ведущих к его спрятанной добыче.",al={"captain sanders lore","who is sanders","sanders backstory","предания о капитане сандерсе","кто такой сандерс","история сандерса"}},{q="Где находится сундук?",a="Сундук наполовину зарыт в песок на западном побережье Западного Края. Хотя на пляжах много обломков кораблей, Сандерс отметил, что сундук лежит возле приметного одинокого ржавого якоря у кромки воды.",al={"footlocker location","where is the rusty anchor","find sanders footlocker","местонахождение сундука","где ржавый якорь","найти сундук сандерса"}},{q="Лежит ли в сундуке сокровище капитана?",a="Карта указывает на сундук и следующую подсказку в более длинной охоте за сокровищами.",al={"is treasure in the chest","what is in the footlocker","where is the gold","есть ли сокровище в сундуке","что в сундуке","где золото"}},{q="Сколько подсказок в охоте за сокровищами капитана Сандерса?",a="Охота состоит из четырех шагов по побережью и окрестностям Западного Края: она начинается с карты и завершается находкой настоящего закопанного сундука с сокровищами капитана Сандерса.",al={"how long is sanders quest","how many parts","sanders quest chain","как долго задание сандерса","сколько частей","цепочка заданий сандерса"}},{q="Почему капитан Сандерс закопал сокровища в Западном Крае?",a="Сандерс потерпел крушение у берегов Западного Края. Перед лицом скорой смерти капитан спрятал сундук и разделил подсказки между знакомыми прибрежными приметами, чтобы достойный нашедший мог забрать его земное добро.",al={"why hide treasure","why westfall coast","зачем прятать сокровища","почему побережье западного края"}},{q="Могут ли игроки Орды идти по этой карте сокровищ?",a="Да. Карта капитана Сандерса и последующие подсказки нейтральны: по его следу может пойти любой искатель приключений, которого выбросило на берег или который отважился пройти по берегам Западного Края.",al={"can horde do this","horde sanders quest","faction neutral treasure","может ли орда выполнить это","задание сандерса для орды","нейтральное сокровище"}}},fp="32,330,23.445.0,16.355.1,24.207.0,32.215.0,51.84.1,53.176.0,54.218.0,43.168.0"}
P.entries["quest:1361"] = {n="Регтар Врата Смерти",s="Этот приказ направляет опытных бойцов Орды из крупных столиц на усиление заставы в западных Степях. Ветеран-воин Регтар Врата Смерти собирает способных добровольцев для предстоящего похода через горы в засушливые земли Пустошей. Он ищет тех, кто готов обрушить сталь Орды на укрепившиеся племена кентавров, терроризирующие границу.",h="Этот приказ направляет опытных бойцов Орды из крупных столиц на усиление заставы в западных Степях.",kw={"belgrom rockmaul","crossroads","desolace","kolkar","krusk","nazgrel","regthar deathgate","the barrens","vol'jin","белгром каменная булава","перекресток","пустоши","колкар","круск","назгрел","регтар врата смерти","степи","вол'джин"},ang={["class:Warrior"]="Регтар ценит прямую боевую мощь и непоколебимую дисциплину, поэтому его призыв — естественное испытание для воинов первой линии, стремящихся проверить себя во враждебных бесплодных землях.",["faction:Horde"]="Это задание отражает упреждающую оборону границ Орды: агрессивных кентавров соседних Пустошей нужно усмирить, прежде чем они начнут набеги вглубь Степей.",["race:Tauren"]="Поколениями выдерживая жестокую борьбу с кентаврами в центральном Калимдоре, воины-таурены лично заинтересованы помочь Регтару в ударе по племени Колкар."},sec={{t="Призыв помощников Вождя",b="По всему Калимдору влиятельные вожди Орды — среди них Охотник за тенями Вол'джин, Назгрел и опытные командиры вроде Белгрома Каменная Булава — следят за возможными угрозами на границах. В Степях опытный воин по имени Регтар Врата Смерти создал оборонительный пост, охраняющий западные перевалы. Понимая, что местные стычки требуют закаленных бойцов, а не новобранцев, офицеры Орды направляют проверенных искателей приключений к западу от Перекрестка откликнуться на призыв Регтара."},{t="Дорога в Пустоши",b="Регтар Врата Смерти расположился в укрепленном оплоте среди хребтов к западу от Перекрестка. Оттуда он следит за горными тропами на западе, ведущими в безжизненные бесплодные земли Пустошей. Его задача прямая и непреклонная: собрать экспедиционный авангард, способный пройти по враждебной местности и нанести удар прямо в сердце племени Колкар и других воюющих племен кентавров, пока их жестокая экспансия не угрожает землям Орды."}},faq={{q="Кто такой Регтар Врата Смерти?",a="Регтар Врата Смерти — орк-воин и командир Орды, расквартированный в Степях. Отвечая за безопасность границы, он координирует разведку и военные удары по опасным, покрытым пеплом просторам Пустошей.",al={"who is regthar","regthar deathgate lore","who is the questgiver","кто такой регтар","регтар врата смерти предыстория","кто выдает задание"}},{q="Где находится Регтар Врата Смерти?",a="Его можно найти в Степях: он расположился в укрепленных бункерах Орды на холмистой тропе прямо к западу от Перекрестка, с видом на западный горный перевал.",al={"where is regthar","regthar location","find regthar deathgate","где регтар","расположение регтара","найти регтара врата смерти"}},{q="Кто дает задание найти Регтара?",a="Это поручение дают несколько видных вождей и военачальников Орды, среди них Охотник за тенями Вол'джин, Назгрел и Белгром Каменная Булава в Оргриммаре и Круск в Мельнице Таррен.",al={"who starts regthar deathgate","where to get regthar quest","кто начинает регтар врата смерти","где взять задание регтара"}},{q="Какова главная цель задания Регтара?",a="Регтар набирает способных воинов, чтобы пересечь горы, войти в Пустоши и начать наступление на враждебные племена кентавров, в первую очередь на племя Колкар.",al={"what does regthar want","regthar deathgate purpose","что хочет регтар","цель регтара врата смерти"}},{q="Почему Орду беспокоят Пустоши?",a="Пустоши — истерзанная войной глушь, захваченная агрессивными племенами кентавров. Если их не сдерживать, их набеги могут перекинуться через горные перевалы в Степи и соседние поселения Орды.",al={"why go to desolace","horde interest in desolace","зачем идти в пустоши","интерес орды к пустошам"}},{q="Что дальше после разговора с Регтаром Врата Смерти?",a="Когда вы доложите Регтару, он сразу введет вас в курс дел за западными горами и поручит первый удар за границей в задании «Кентавры Пустошей».",al={"next quest after regthar","regthar follow up","следующее задание после регтара","продолжение регтара"}}},fp="17,377,34.505.0,20.468.0,25.215.0,35.165.0,40.177.0,51.166.0,41.204.0,54.193.0"}
P.entries["quest:1362"] = {n="Кентавры Пустошей",s="Это задание связывает военные операции Орды между Степями и унылыми просторами Пустошей. По указанию орка-воина Регтара Врата Смерти бойцы Орды отправляются на запад через горы, чтобы усилить разведчика Фелгура Бью-Двоих на Заставе Скитающихся Духов.",h="Это задание связывает военные операции Орды между Степями и унылыми просторами Пустошей.",kw={"centaur","desolace","felgur twocuts","ghost walker post","horde","kolkar","regthar deathgate","the barrens","кентавр","пустоши","фелгур бью-двоих","застава скитающихся духов","орда","колкар","регтар врата смерти","степи"},ang={["faction:Horde"]="Это задание знаменует важный стратегический поворот для Орды: от защиты молодых поселений в Дуротаре и Степях к активным военным кампаниям в глубине враждебных чужих земель.",["race:Orc"]="Закрепившись в восточном Калимдоре, орки считают неукротимые племена кентавров постоянной угрозой, которую необходимо усмирить, чтобы защитить линии снабжения Орды.",["race:Tauren"]="Агрессия кентавров привела кочевые племена тауренов на грань истребления до союза с Траллом. Поэтому бой в самих землях кентавров в Пустошах имеет глубоко личное значение для любого воина-таурена."},sec={{t="Угроза за горами",b="Пока Орда отбивается от разбойничьих стай кентавров в Степях, командиры вроде Регтара Врата Смерти понимают: обрезая ветви, дерево не убить. Племя Колкар черпает силу из безжизненных скал западного побережья Калимдора. Пока их родовая твердыня не укрощена, бесконечные волны налетчиков будут просачиваться через перевалы на земли Орды. Чтобы нейтрализовать Колкар, нужно ударить в самый источник."},{t="Застава Скитающихся Духов",b="Чтобы противостоять сердцу земель кентавров, Орда держит суровую передовую заставу — Заставу Скитающихся Духов. Глубоко в Пустошах разведчик Фелгур Бью-Двоих собирает сведения о враждующих племенах кентавров. Регтар отправляет ветеранов Степей на запад, чтобы они поставили клинки под командование Фелгура, и Орда переходит от пассивной обороны к активной кампании по нарушению планов врага."}},faq={{q="Кто посылает меня на это задание?",a="Регтар Врата Смерти, орк-воин, расквартированный в бункере к западу от Перекрестка в Степях, поручает вам нести бой прямо в родовые земли племени Колкар.",al={"quest giver","who gives quest","regthar","персонаж, выдающий задания","кто дает задание","регтар"}},{q="Где находится Застава Скитающихся Духов?",a="Застава Скитающихся Духов — уединенный лагерь Орды на суровых тропах Пустошей, расположенный на западной стороне горного хребта Калимдора.",al={"where is ghost walker post","felgur twocuts location","desolace camp","где застава скитающихся духов","фелгур бью-двоих расположение","лагерь в пустошах"}},{q="Почему Орда сосредоточилась на Пустошах?",a="Колкар, совершающие набеги на Степи, происходят из более крупных племен кентавров, обосновавшихся в Пустошах. Регтар понимает, что оборона в Степях не остановит вторжения навсегда, пока твердыня Колкар в Пустошах не будет разгромлена.",al={"why go to desolace","why fight kolkar in desolace","centaur connection","зачем идти в пустоши","зачем сражаться с колкар в пустошах","связь с кентаврами"}},{q="Кто такой Фелгур Бью-Двоих?",a="Фелгур Бью-Двоих — разведчик Орды на Заставе Скитающихся Духов, которому поручено наблюдать за воюющими племенами кентавров в Пустошах и организовывать тактические удары по ним.",al={"felgur twocuts","who is felgur","фелгур бью-двоих","кто такой фелгур"}},{q="Есть ли в этом задании сражения?",a="Нет. Это переходное задание на доставку, которое ведет повышающих уровень искателей приключений Орды от конфликтов средних уровней в Степях к более сложным испытаниям Пустошей.",al={"combat in quest","fighting quest","бой в задании","сражения в задании"}},{q="Против какого племени кентавров направлено это задание?",a="Оно направлено именно против племени Колкар — одного из главных племен кентавров, выходцев из Пустошей, которое агрессивно расширилось в Степи и Дуротар.",al={"which centaur","what clan","kolkar clan","какие кентавры","какое племя","племя колкар"}}},fp="22,256,29.454.0,17.373.0,29.169.0,35.153.0,38.241.0,22.168.0,31.169.0,42.163.0"}
P.entries["quest:138"] = {n="Спрятанное сокровище капитана Сандерса",s="Это задание — второй этап охоты за сокровищами, придуманной загадочным пиратом капитаном Сандерсом в Западном Крае. По указаниям из заброшенного сундука у моря искатели должны отправиться на восток от побережья и найти еще одну подсказку в старой бочке возле разрушенной каменной кладки.",h="Это задание — второй этап охоты за сокровищами, придуманной загадочным пиратом капитаном Сандерсом в Западном...",kw={"broken barrel","captain sanders","chimney","pirate","sanders treasure","treasure hunt","westfall","сломанная бочка","капитан сандерс","печная труба","пират","сокровище сандерса","охота за сокровищами","западный край"},ang={["class:Rogue"]="Расшифровывать пиратские шифры и пробираться по заброшенным руинам в поисках забытой добычи — вторая натура для тех, кто ценит скрытность, хитрость и быструю наживу.",["faction:Alliance"]="Пока местное ополчение Западного Края борется с организованными бандитами, погоня за следом Сандерса дает редкое развлечение, ведущее и по беззаконным берегам, и по неухоженным дорогам вглубь суши."},sec={{t="След загадок вглубь суши",b="Вместо того чтобы закопать добычу под единственным крестом на песчаном пляже, капитан Сандерс разбросал загадки по всей округе. Тем, кто разгадает его первый шифр на берегу, велено покинуть бурный прибой и подняться по скалистым утесам вглубь суши, следуя маршруту, который неуклонно ведет к главным дорогам Западного Края."},{t="Руины у дороги",b="Подсказка направляет искателей прямо к старой печной трубе среди придорожных руин, где в брошенной выветренной бочке спрятано следующее послание. Пират явно прекрасно знал приметы Западного Края и использовал остатки разрушенных ферм, чтобы сберечь вехи своей затейливой охоты за сокровищами."}},faq={{q="Кем был капитан Сандерс?",a="Капитан Сандерс был пиратским капитаном, действовавшим на побережье Западного Края. Вместо того чтобы спрятать добычу в обычном тайнике, он разбросал по округе цепочку подсказок и загадок, бросая вызов всем, кто захочет завладеть его спрятанным богатством.",al={"captain sanders lore","who is sanders","sanders pirate","капитан сандерс предыстория","кто такой сандерс","пират сандерс"}},{q="Куда ведет эта подсказка?",a="Подсказка направляет искателей строго на восток, вверх по утесам от западного моря, пока они не выйдут к дороге. Там, возле старой разрушенной каменной печной трубы, стоит сломанная бочка, скрывающая следующую часть головоломки.",al={"where do i go","clue location","chimney location","куда идти","место подсказки","где печная труба"}},{q="Почему Сандерс спрятал сокровище по частям?",a="Пираты обычно прятали награбленное от соперников и властей. Сандерс принял дополнительные меры предосторожности, разделив указания на многоступенчатые загадки, чтобы пройти путь до последнего тайника мог лишь упорный и находчивый человек.",al={"why clues","why the scavenger hunt","зачем подсказки","зачем охота за сокровищами"}},{q="Опасно ли идти по следу сокровищ?",a="Хотя сами подсказки — лишь пергаменты и старые емкости, путь по Западному Краю сталкивает искателей с бродячими зверями, рыщущими гноллами и враждебными членами Братства Справедливости, которые контролируют окрестные поля и заброшенные усадьбы.",al={"is it safe","westfall dangers","безопасно ли","опасности западного края"}},{q="Возле каких руин спрятана бочка?",a="Бочка стоит у осыпающейся каменной печной трубы разрушенного здания возле дороги — одной из множества усадеб Западного Края, заброшенных или разрушенных за последние годы смуты.",al={"chimney ruins","which building","руины с печной трубой","какое здание"}},{q="Раскрывает ли это задание само сокровище?",a="Нет. Этот шаг дает лишь очередную подсказку. Сандерс задумал свою охоту так, чтобы провести искателей через несколько этапов по всему краю, прежде чем откроется настоящий приз.",al={"is this the final chest","do i get loot now","это последний сундук","получу ли я добычу сейчас"}}},fp="32,303,25.357.0,20.310.0,24.250.0,30.214.0,44.284.0,41.257.0,45.190.0,43.168.0"}
P.entries["quest:139"] = {n="Спрятанное сокровище капитана Сандерса",s="Это задание — третий этап охоты за сокровищами капитана Сандерса на берегах Западного Края. Найденный в сломанной бочке пергамент направляет искателей на север, к старому кувшину у прибрежной мельницы. Эти загадочные указания ведут искателей приключений дальше по следу покойного пирата к его легендарному тайнику.",h="Это задание — третий этап охоты за сокровищами капитана Сандерса на берегах Западного Края.",kw={"bluffs","broken barrel","captain sanders","hidden treasure","old jug","pirate clue","westfall","windmill","утесы","сломанная бочка","капитан сандерс","спрятанное сокровище","старый кувшин","пиратская подсказка","западный край","мельница"},ang={["class:Rogue"]="Идти по следу негодяя из тайников и скрытых посланий вдоль утесов для любого разбойника, ценящего прибрежную контрабанду, — вторая натура.",["faction:Alliance"]="Пока Западный Край страдает от голода и бандитов Братства Справедливости, поиск потерянной пиратской добычи Сандерса дарит независимым искателям приключений долгожданную удачу."},sec={{t="Пиратская тропа из хлебных крошек",b="Капитан Сандерс был осторожен и никогда не оставлял местонахождение добычи на одном листе пергамента. Он разделил указания на последовательную охоту за сокровищами, разбросанную по западному побережью Западного Края. Каждая найденная подсказка указывает лишь на следующий промежуточный тайник, так что любому охотнику за чужим добром придется пройти по кишащим пиратами утесам, чтобы получить приз."},{t="На север, к утесам",b="Подсказка из сломанной бочки велит искателям идти строго на север, по прямой, к морским утесам. На этих утесах стоит одинокая мельница, возле которой брошенный кувшин скрывает следующее звено пиратской головоломки. Тем, кто идет по прибрежному Западному Краю, следовать подсказкам Сандерса значит пробираться по земле, где кишат мурлоки и мародеры из Братства Справедливости."}},faq={{q="Что такое Спрятанное сокровище капитана Сандерса?",a="Капитан Сандерс был буканьером, спрятавшим свои богатства на побережье Западного Края. Вместо обычной карты он оставил цепочку письменных загадок в бочках, сундуках и кувшинах по всей округе.",al={"sanders treasure","what is this quest","who is sanders","сокровище сандерса","что это за задание","кто такой сандерс"}},{q="Куда ведет эта третья подсказка?",a="Пергамент велит вам идти строго на север от сломанной бочки к утесам над океаном. Там, возле одинокой мельницы, стоит старый кувшин с последней подсказкой.",al={"where do i go","jug location","where is the windmill","куда идти","где кувшин","где мельница"}},{q="Почему Сандерс спрятал указания по частям?",a="Пираты Великого моря часто принимали сложные меры, чтобы защитить добычу от мятежных товарищей и соперников-мародеров. Разделив маршрут на несколько тайных меток, Сандерс позаботился, чтобы одна найденная подсказка не выдала сокровище сразу.",al={"why clues","why not a full map","зачем подсказки","почему не полная карта"}},{q="Могут ли игроки Орды пройти этот след?",a="Подсказки и предметы, связанные с тайником капитана Сандерса, нейтральны, и с ними может взаимодействовать любой нашедший их искатель приключений, хотя Западный Край лежит в глубине земель, лояльных Альянсу.",al={"is this alliance only","horde sanders treasure","только для альянса","сокровище сандерса орда"}},{q="Раскрывает ли эта подсказка сам сундук?",a="Нет. Кувшин у прибрежной мельницы содержит еще одну подсказку, указывающую на настоящее место, где покоится сундук Сандерса, так что это предпоследний шаг охоты.",al={"is the treasure in the jug","final step","сокровище в кувшине","последний шаг"}},{q="Какие опасности подстерегают на пути к мельнице?",a="Западные утесы и пляжи Западного Края кишат гноллами племени Речная Лапа, прибрежными мурлоками и бродячими бандитами Братства Справедливости, так что прямой путь на север опасен для неосторожных.",al={"dangers on the bluffs","what mobs are there","опасности на утесах","какие там монстры"}}},fp="32,342,27.414.0,23.407.0,41.218.0,32.179.0,46.266.0,38.186.0,41.170.0,48.184.0"}
P.entries["quest:14"] = {n="Народное ополчение",s="Это задание завершает кампанию Гриана Камнегрива по очистке дорог и ферм Западного Края от Братства Справедливости. Выследив закаленных разбойников, засевших в южных Холмах Разбойничьих Кинжалов, добровольцы доказывают свою преданность и получают полное посвящение в Народное ополчение Сторожевого холма.",h="Это задание завершает кампанию Гриана Камнегрива по очистке дорог и ферм Западного Края от Братства...",kw={"dagger hills","defias highwayman","defias knuckleduster","defias pathstalker","gryan stoutmantle","people's militia","sentinel hill","westfall","холмы разбойничьих кинжалов","разбойник с большой дороги","костолом братства справедливости","тропорез братства справедливости","гриан камнегрив","народное ополчение","сторожевой холм","западный край"},ang={["class:Paladin"]="Камнегрив призывает благословение Света на посвящаемых, отражая священные идеалы справедливости и защиты беззащитных от хищных преступников.",["faction:Alliance"]="Неспособность Штормграда защитить Западный Край вынуждает простых людей Альянса проливать собственную кровь ради порядка на родной земле.",["race:Human"]="Для людей Штормграда это задание — защита забытых соотечественников, чьи средства к существованию бросила политическая элита столицы."},sec={{t="Очищение Холмов Разбойничьих Кинжалов",b="Северные фермерские земли Западного Края сильно пострадали от Братства Справедливости, но преступники, ускользнувшие от первых зачисток Камнегрива, отступили на юг, в скалистые утесы Холмов Разбойничьих Кинжалов. Действуя из этой неприступной местности, бандиты Братства Справедливости — разбойники с большой дороги, тропорезы и костоломы — продолжают грабить сельские усадьбы и нападать на путников. Чтобы сломить их власть над южной частью края, Народное ополчение посылает в холмы закаленных рекрутов, чтобы те напрямую разгромили эти шайки."},{t="Поход Камнегрива",b="Гриан Камнегрив основал Народное ополчение после возвращения домой с войны с Плетью в Лордероне: он обнаружил, что королевский гарнизон Штормграда полностью покинул Западный Край. Перед лицом безнаказанного преступного синдиката и голодающих фермеров, изгнанных со своих земель, он организовал местных добровольцев и призвал их к оружию. Полностью выполнив этот последний этап патрульной службы, искатели приключений получают официальное посвящение в ополчение и благословение Камнегрива во имя Света, пока борьба с Братством углубляется."}},faq={{q="Где находятся Холмы Разбойничьих Кинжалов?",a="Холмы Разбойничьих Кинжалов лежат на юге Западного Края, к юго-западу от Сторожевого холма. Скалистые гряды и заброшенные штольни служат плацдармом и оплотом для самых сильных бойцов Братства Справедливости.",al={"dagger hills location","where to find dagger hills","where are the highwaymen","где холмы разбойничьих кинжалов","как найти холмы разбойничьих кинжалов","где разбойники с большой дороги"}},{q="Почему Народное ополчение сражается с Братством Справедливости в одиночку?",a="Король Вариан Ринн пропал, ресурсов не хватает, и Дом знати в Штормграде отказывается посылать королевскую армию на защиту сельского Западного Края. Гриану Камнегриву и местным фермерам ничего не оставалось, кроме как создать собственный отряд добровольцев для защиты своих домов.",al={"why no stormwind guards","where is stormwind army","why is westfall abandoned","почему нет стражи штормграда","где армия штормграда","почему западный край брошен"}},{q="Что дает выполнение этого задания?",a="Уничтожив разбойников с большой дороги, тропорезов и костоломов, вы разорвете хватку Братства Справедливости на дорогах юга Западного Края и получите официальное посвящение в Народное ополчение под командованием Гриана Камнегрива.",al={"peoples militia completion","militia induction","what do i get for finishing","завершение народного ополчения","посвящение в ополчение","что получу за выполнение"}},{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — солдат-ветеран, сражавшийся в Третьей войне в Лордероне. Вернувшись домой в Западный Край и увидев, как Королевство Штормград бросило сельских жителей на произвол судьбы, он основал в Сторожевом холме Народное ополчение, чтобы дать отпор Братству Справедливости.",al={"gryan background","who is stoutmantle","sentinel hill leader","гриан камнегрив история","кто такой камнегрив","глава сторожевого холма"}},{q="Какие бойцы Братства Справедливости прячутся в Холмах Разбойничьих Кинжалов?",a="В Холмах Разбойничьих Кинжалов укрываются опытные разбойники с большой дороги, смертоносные тропорезы и жестокие костоломы Братства Справедливости. Они организуют набеги на юг Западного Края и охраняют дальние оплоты Братства.",al={"defias mobs southern westfall","what are pathstalkers and knuckledusters","who is in dagger hills","братство справедливости юг западного края","кто такие тропорезы и костоломы","кто в холмах разбойничьих кинжалов"}},{q="Как это связано с Лордероном?",a="Гриан Камнегрив упоминает, что недавно вернулся из «оскверненных земель Лордерона», где Альянс сражался с Плетью. Пережитое на той мрачной войне дало ему решимость организовать оборону Западного Края, когда местные власти не справились.",al={"stoutmantle lordaeron","tainted lands of lordaeron","gryan war history","камнегрив лордерон","оскверненные земли лордерона","гриан военное прошлое"}}},fp="20,306,24.514.0,21.516.0,27.203.0,54.268.0,39.204.0,25.272.0,45.198.0,35.250.0"}
P.entries["quest:140"] = {n="Спрятанное сокровище капитана Сандерса",s="Это завершение охоты за сокровищами капитана Сандерса по Западному Краю. По записке, пропитанной виски и найденной в старом кувшине, искатели удачи отправляются от западного берега за давно зарытым кладом. Путь ведет в открытое море, прочь от бед материка, к далекому прибрежному островку.",h="Это завершение охоты за сокровищами капитана Сандерса по Западному Краю.",kw={"captain sanders","final clue","hidden treasure","island","locked chest","old jug","treasure hunt","westfall","капитан сандерс","последняя подсказка","спрятанное сокровище","остров","запертый сундук","старый кувшин","охота за сокровищами","западный край"},ang={["class:Rogue"]="Идти по следу негодяя по пустынным пляжам и в открытое море для любого разбойника, ценящего пиратскую контрабанду, — дело привычное.",["race:Human"]="Для людей, защищающих Западный Край от бандитов Братства Справедливости и гноллов, поиски тайника забытого местного пирата — приятная передышка от патрулирования ферм."},sec={{t="Путь моряка",b="Капитан Сандерс оставил вдоль побережья Западного Края цепочку подсказок, бросая вызов любому искателю приключений собрать их воедино. Последний пергамент, извлеченный из остатков любимого виски в кувшине, указывает окончательный курс. Чернила размазаны, от записки несет спиртным, но указания капитана просты: идти прямо на запад до кромки воды и нырнуть в волны."},{t="Одинокий островок",b="У берегов Западного Края из бурлящего Великого моря торчат небольшие скалы. Если плыть строго на запад, попадешь на один из таких уединенных островков, где капитан Сандерс спрятал свою добычу. Наполовину скрытый и годами терпевший соленый прибой, запертый сундук с ржавыми петлями упрямо поддается тем, кто достаточно настойчив, чтобы довести игру пирата до конца."}},faq={{q="Куда ведет последняя подсказка?",a="Записка, пропитанная виски, из старого кувшина велит искателям сокровищ идти прямо на запад к берегу Западного Края и плыть дальше в океан. Сундук ждет на небольшом острове посреди воды.",al={"where is the chest","sanders treasure location","final clue destination","где сундук","где сокровище сандерса","куда ведет последняя подсказка"}},{q="Кто такой капитан Сандерс?",a="Капитан Сандерс был пиратом, плававшим у берегов Западного Края. Вместо того чтобы хранить добычу в банке или крепости, он проложил вдоль берега путь из загадочных подсказок и зарыл свой сундук на далеком острове у побережья.",al={"who is captain sanders","sanders lore","captain sanders background","кто такой капитан сандерс","предания о сандерсе","капитан сандерс история"}},{q="Почему последняя подсказка пахнет виски?",a="Последние указания были спрятаны в выброшенном кувшине из-под виски капитана Сандерса у берега. Сырость и спиртное размыли чернила, но разобрать указания все же можно.",al={"whiskey note","old jug clue","записка с виски","подсказка в старом кувшине"}},{q="Сколько этапов в этой охоте за сокровищами?",a="Всего охота состоит из четырех этапов. Она начинается с потрепанной морем карты сокровищ, найденной на берегу, проходит через несколько тайников — сундучок, бочку и кувшин из-под виски — и заканчивается у зарытого сундука.",al={"how long is sanders chain","sanders quest parts","captain sanders questline","сколько этапов у сандерса","части задания сандерса","цепочка заданий капитана сандерса"}},{q="Опасно ли добираться до острова?",a="Главная трудность — долгий заплыв от берега по Великому морю. Хотя прибрежные воды Западного Края часто тревожат агрессивные мурлоки и морские твари, сам островок служит в основном личным тайником Сандерса.",al={"swimming to sanders chest","island danger","murlocs near chest","плыть к сундуку сандерса","опасность острова","мурлоки у сундука"}},{q="В каком состоянии сундук с сокровищами?",a="Сырой морской воздух и разбивающийся прибой не пощадили сундук. Его петли сильно проржавели, но с помощью рычага его можно взломать и забрать лежащее внутри.",al={"condition of chest","is the chest locked","rusty chest","состояние сундука","заперт ли сундук","ржавый сундук"}}},fp="32,327,16.393.0,16.359.1,31.208.0,24.246.0,44.209.0,41.246.0,33.220.0,36.204.0"}
P.entries["quest:141"] = {n="Братство Справедливости",s="Доставьте секретный доклад Матиаса Шоу из Штормграда Гриану Камнегриву на Сторожевой холм. Шоу изучил историю бывшей Гильдии каменщиков, чтобы помочь Камнегриву выяснить происхождение Братства Справедливости.",h="Доставьте секретный доклад Матиаса Шоу из Штормграда Гриану Камнегриву на Сторожевой холм.",kw={"defias","sentinel hill","shaw","stonemasons","stormwind","stoutmantle","vancleef","westfall","братство справедливости","сторожевой холм","шоу","каменщики","штормград","камнегрив","ван клиф","западный край"},ang={["class:Rogue"]="Расследование о бывших мастерах Штормграда показывает, как распри внутри королевства могут сказаться на его отдаленных поселениях.",["faction:Alliance"]="Мятеж каменщиков обнажает глубокие трещины в королевстве: те самые рабочие, что отстроили каменные стены Штормграда, теперь грозят их обрушить.",["race:Human"]="Для людей Штормграда это открытие задевает за живое. Стены их домов и сам Собор построили те самые люди, что теперь грабят глубинку Западного Края."},sec={{t="Из строителя в бандиты",b="Несколько месяцев Гриан Камнегрив и Народное ополчение сражались с, казалось бы, безликим мятежом разбойников, воров и головорезов по всему Западному Краю. Когда Мастер Матиас Шоу из ШРУ изучает Записку Вилли, он делает потрясающий вывод: гильдия архитекторов и каменщиков, отстроивших белые стены Штормграда, так и не распалась. Ее предводитель, Эдвин ван Клиф, увел их в подполье."},{t="Обида и предательство",b="После разрушений Первой войны Штормград лежал в пепле. Гильдия каменщиков ван Клифа взялась за грандиозный труд по восстановлению столицы королевства, вновь превратив ее в жемчужину человечества. Но когда работа закончилась, вспыхнул горький спор об оплате. Недовольные отношением короны и Дома знати, ван Клиф и его мастера взялись за кинжалы и красные банданы, променяв гражданское ремесло на жестокий мятеж против трона."},{t="Неверие Камнегрива",b="Когда донесение Шоу попадает в Сторожевой холм, Гриан Камнегрив с трудом принимает эту весть. Камнегрив помнит ван Клифа не как головореза, крадущегося в тени сельской глуши, а как трудолюбивого и одаренного мастера, чьи труды дали кров тысячам вернувшихся горожан. Столкнувшись с таким тревожным обвинением, командир ополчения требует веских доказательств, прежде чем окончательно поверить, что главный зодчий Штормграда устраивает разорение Западного Края."}},faq={{q="Что такое Донесение Шоу?",a="В нем изложены выводы Матиаса Шоу о бывшей Гильдии каменщиков и Братстве Справедливости. Доставьте секретный доклад Гриану Камнегриву.",al={"shaws report","mathias shaw document","the report to stoutmantle","донесение шоу","документ матиаса шоу","донесение для камнегрива"}},{q="Кто такой Эдвин ван Клиф?",a="Эдвин ван Клиф возглавлял Гильдию каменщиков, отстроившую Штормград. В докладе изучается более поздняя история гильдии.",al={"vancleef identity","who is edwin vancleef","edwin vancleef lore","личность ван клифа","кто такой эдвин ван клиф","эдвин ван клиф предания"}},{q="Почему Гриан Камнегрив скептически относится к донесению?",a="Камнегриву трудно поверить обвинениям Шоу, и он хочет получить новые доказательства. Подробности раскрываются, когда он читает доклад.",al={"why doesnt gryan believe it","stoutmantle reaction","why does gryan need proof","почему гриан не верит","реакция камнегрива","зачем гриану доказательства"}},{q="Почему каменщики обратились против Штормграда?",a="Каменщики отстроили Штормград, но затем жестоко поспорили со знатью из-за оплаты. Доклад Шоу изучает, что было дальше.",al={"why are defias mad","stonemason dispute","vancleef motive","почему братство справедливости злится","спор каменщиков","мотив ван клифа"}},{q="Какую роль в этом задании играет ШРУ?",a="Шоу изучает возможные связи между бывшей гильдией и преступниками и отправляет свои выводы Камнегриву.",al={"why mathias shaw","si7 involvement","rogue guild stormwind","почему матиас шоу","участие шру","гильдия разбойников штормград"}},{q="Куда ведет это расследование дальше?",a="Доставьте доклад, а затем помогите Камнегриву искать дальнейшие доказательства в продолжающемся расследовании дела Братства Справедливости.",al={"what comes next","next quest defias","after shaws report","что дальше","следующее задание братства справедливости","после донесения шоу"}}},fp="22,214,23.409.1,23.489.1,23.463.1,22.137.0,22.127.0,49.136.0,47.138.0,39.110.0,40.102.1"}
P.entries["quest:142"] = {n="Братство Справедливости",s="Это важное задание отправляет искателей приключений по пыльным дорогам Западного Края на поиски разъезжающего гонца Братства Справедливости. Перехватив его донесения, Гриан Камнегрив и Народное ополчение получают ценные сведения о восстании бандитов.",h="Это важное задание отправляет искателей приключений по пыльным дорогам Западного Края на поиски разъезжающего...",kw={"defias","jangolode","messenger","moonbrook","quarry","saldean","stoutmantle","vancleef","westfall","братство справедливости","рудник янго","гонец","луноречье","прииск","сальден","камнегрив","ван клиф","западный край"},ang={["class:Rogue"]="Выслеживание гонцов Братства Справедливости показывает, как умелые разведчики и карманники координируют разветвленную теневую сеть прямо под носом у ополчения.",["faction:Alliance"]="Молчание Штормграда вынуждает Народное ополчение Западного Края самостоятельно заниматься разведкой, выслеживая гонцов на безлюдных проселочных дорогах без поддержки королевского гарнизона.",["race:Human"]="Для людей королевства выход на Эдвина ван Клифа через донесения выявляет горькие, не утихающие последствия политических и трудовых споров Штормграда."},sec={{t="Перехват гонца",b="Разведчики Гриана Камнегрива заметили неуловимого гонца Братства Справедливости, который перемещался между главными опорными пунктами разбойников: Луноречьем, Прииском на Золотом Берегу и Рудником Янго. В отличие от обычных громил, хозяйничающих в округе, этот гонец носит по региону важные письменные приказы. Камнегрив приказывает схватить или убить гонца, чтобы Народное ополчение могло прочесть содержимое его сумки и выяснить, откуда братство командует своими силами."},{t="Чернильный след",b="Послание, найденное у гонца, неопровержимо подтверждает, что Эдвин ван Клиф, легендарный бывший глава Гильдии каменщиков, лично руководит мятежом Братства Справедливости. Перехваченная записка подтверждает власть ван Клифа над местными отрядами, но не указывает, где находится его тайная база."},{t="Счастливый поворот",b="Как только приказы гонца подтверждают лидерство ван Клифа, Народному ополчению выпадает крупная удача. Отчаявшийся бандит, пойманный при попытке украсть повозку фермера Сальдена, соглашается предать своих в обмен на жизнь. Имея на руках письменное доказательство, Камнегрив переключается на этого перебежчика в надежде, что тот проведет отряд в самое сердце убежища Братства Справедливости."}},faq={{q="Где перемещается гонец Братства Справедливости?",a="Гонец Братства Справедливости начинает обход в Луноречье, возле кузницы. Оттуда он идет по дорогам на север к Прииску на Золотом Берегу и Руднику Янго, заходит в обе подземные выработки, а затем возвращается тем же путем в Луноречье.",al={"messenger route","where is defias messenger","find messenger","маршрут гонца","где гонец братства справедливости","найти гонца"}},{q="Что раскрывает перехваченное послание?",a="Stoutmantle hopes the courier's written orders will reveal the Brotherhood's command structure and help locate its hideout. Their contents are discovered when the message is recovered.",al={"what was in the message","mysterious message text","vancleef note","что было в послании","текст загадочного послания","записка ван Клифа"}},{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — полевой командир Народного ополчения, штаб которого находится в Сторожевом холме. Недовольный отсутствием королевских стражников Штормграда, он собирает добровольцев и искателей приключений для защиты Западного Края от налетчиков Братства Справедливости.",al={"stoutmantle role","who gives this quest","роль камнегрива","кто выдает это задание"}},{q="Почему гонец посещает рудники?",a="Братство захватило минеральные богатства Западного Края и использует такие места, как Рудник Янго и Прииск на Золотом Берегу, для добычи припасов, укрытия и сбора сил. Гонец поддерживает единство этих разрозненных отрядов согласно указаниям ван Клифа.",al={"why gold coast quarry","why jangolode mine","почему прииск на золотом берегу","почему рудник янго"}},{q="Раскроет ли поимка гонца убежище Братства Справедливости?",a="Stoutmantle intends to use the intercepted orders to advance his search for the hideout. The next lead is learned when you return to him.",al={"did we find the hideout","where is hideout","нашли ли убежище","где убежище"}},{q="Кто такой Эдвин ван Клиф?",a="Edwin VanCleef was the Grand Mason of the Stonemasons Guild that rebuilt Stormwind. Stoutmantle's investigation examines his possible connection to the Brotherhood.",al={"who is vancleef","defias leader","кто такой ван клиф","лидер братства справедливости"}}},fp="22,252,24.443.0,14.340.1,17.366.1,39.250.0,41.184.1,25.227.0,40.244.0,54.137.1,22.164.0"}
P.entries["quest:143"] = {n="Гонец в Западный Край",s="«Гонец в Западный Край» — поручение Альянса: срочная просьба Мирового судьи Соломона из Красногорья должна пересечь Элвиннский лес и добраться до Западного Края. Оставшись без поддержки армии Штормграда, руководство Приозерья ищет взаимопомощи у недавно созданного Грианом Камнегривом Народного ополчения.",h="«Гонец в Западный Край» — поручение Альянса: срочная просьба Мирового судьи Соломона из Красногорья должна...",kw={"gryan stoutmantle","lakeshire","magistrate solomon","peoples militia","redridge mountains","sentinel hill","solomons plea","westfall","гриан камнегрив","приозерье","мировой судья соломон","народное ополчение","красногорье","сторожевой холм","просьба соломона","западный край"},ang={["faction:Alliance"]="Это послание показывает полный крах центральной обороны Королевства Штормград, из-за чего приграничным городам приходится заключать частные пакты о взаимной обороне.",["race:Human"]="Послание показывает общую беду людей-поселенцев Красногорья и Западного Края, вынужденных полагаться на добровольцев и наемников, пока столица бездействует."},sec={{t="Отчаянная просьба",b="Мировой судья Соломон застает Приозерье в отчаянном положении. Красногорье осаждено орками Черной горы и гноллами, а Армия Штормграда так и не прибыла в достаточном числе. Понимая, что Приозерье не выстоит силами одной городской стражи и ополченцев, Соломон пишет официальную просьбу о помощи. Не видя поблизости регулярных королевских резервов, он обращает взгляд на запад: до него дошли слухи о том, что за пределами Элвиннского леса формируется отряд гражданской обороны."},{t="Через границы",b="Адресат послания — Гриан Камнегрив, опытный командир, который начал собирать добровольцев под знаменем Народного ополчения. Отправив гонца через все королевство, Соломон надеется, что организованные добровольцы Западного Края смогут выделить войска для защиты границ Приозерья, пока армии Короны наконец не выступят. Однако, как вскоре выясняют гонцы, Западный Край сам погряз в катастрофической борьбе с Братством Справедливости."}},faq={{q="Почему Мировой судья Соломон просит помощи у Западного Края?",a="Штормград не прислал военное подкрепление, в котором Приозерье отчаянно нуждается против орков и гноллов. Услышав о вооруженных гражданских силах, собирающихся в Западном Крае, Соломон надеется, что Гриан Камнегрив сможет выделить войска для усиления Красногорья.",al={"why westfall","solomons plea","why ask gryan","почему западный край","просьба соломона","почему гриан"}},{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — опытный солдат, расквартированный в Сторожевом холме в Западном Крае. В отсутствие власти и защиты Короны он организовал Народное ополчение и командует им, защищая местные фермы от грабителей и Братства Справедливости.",al={"who is gryan","stoutmantle role","who leads westfall","кто такой гриан","роль камнегрива","кто возглавляет западный край"}},{q="Куда ведет путь гонца?",a="Послание нужно доставить из ратуши Приозерья на запад через Красногорье и Элвиннский лес в Сторожевой холм в центре Западного Края.",al={"where do i deliver","where is stoutmantle","redridge to westfall","куда доставить","где камнегрив","из красногорья в западный край"}},{q="Почему Армия Штормграда не пришла на помощь Приозерью?",a="Мировой судья Соломон отмечает, что с армией происходит что-то странное: обещанные войска так и не появились. Руководство Штормграда парализовано при регентстве Болвара Фордрагона и леди Престор, и окраинам приходится справляться самим.",al={"why no stormwind army","where are royal guards","stormwind army missing","почему нет армии штормграда","где королевская стража","армия штормграда пропала"}},{q="Сможет ли Западный Край выделить войска для Красногорья?",a="Нет. Прибыв в Сторожевой холм, вы обнаруживаете, что Западный Край едва держится против Братства Справедливости. У Народного ополчения нет лишних солдат, и оно с трудом защищает собственные границы.",al={"does westfall help","will militia come","can gryan help","поможет ли западный край","придет ли ополчение","поможет ли гриан"}},{q="Что будет после доставки письма?",a="Гриан Камнегрив получает послание и сразу составляет ответ, объясняющий тяжелое положение Западного Края, после чего отправляет вас в обратный путь с ответом для Мирового судьи Соломона.",al={"what next","follow up quest","after messenger to westfall","что дальше","следующее задание","после гонца в западный край"}}},fp="21,278,18.449.0,23.482.0,51.252.0,25.241.0,37.156.0,49.255.0,52.211.1,39.184.1"}
P.entries["quest:1431"] = {n="Отношения с Альянсом",s="«Отношения с Альянсом» — вводное задание, которое выдает Кравен Дрок в Оргриммаре. Оно направляет опытных искателей приключений из Орды к Кельдрану, мистику, тихо живущему у западного выхода из города. Задание открывает разговор о тонкой закулисной дипломатии и разведке, необходимых для поддержания хрупкого мира Тралла с Альянсом.",h="«Отношения с Альянсом» — вводное задание, которое выдает Кравен Дрок в Оргриммаре.",kw={"alliance relations","craven drok","diplomacy","horde","keldran","orgrimmar","thrall","отношения с альянсом","кравен дрок","дипломатия","орда","кельдран","оргриммар","тралл"},ang={["class:Rogue"]="Упор Кельдрана на тайну и восприятие делает его задания особенно подходящими для тех, кто зарабатывает на жизнь в тени.",["faction:Horde"]="Это задание подчеркивает идеологический контраст внутри Орды между традиционной грубой силой и тонкой, дипломатической политикой Тралла.",["race:Orc"]="Для орков, привыкших решать конфликты топором, подход Кельдрана требует непривычной дисциплины: терпения и тактической тонкости."},sec={{t="Дипломатическая дилемма",b="Хотя многие орки предпочитают грубую силу и прямое завоевание, вождь Тралл понимает, что бесконечная война с Альянсом погубит его молодой народ. Выросши в человеческом плену, Тралл усвоил тонкости человеческого государственного управления и военной стратегии. Кравен Дрок присматривается к воинам и чемпионам, которым может хватить терпения для более тонкого подхода, и направляет их смотреть дальше грубой силы."},{t="Лачуга Кельдрана",b="Возле западных ворот Оргриммара притаилось скромное жилище Кельдрана, знатока магии и тайных искусств. В отличие от шумных воинов, пьющих в Аллее Силы, Кельдран имеет дело с видимостью, восприятием и государственными делами. Он ищет тайных агентов, способных проявлять осмотрительность от имени Вождя в напряженном противостоянии Орды и ее заклятых врагов."}},faq={{q="Кто выдает задание «Отношения с Альянсом»?",a="Кравен Дрок выдает это задание в Оргриммаре искателям приключений из Орды, достигшим тридцатого уровня.",al={"quest giver alliance relations","who starts alliance relations","where to get alliance relations","кто выдает отношения с альянсом","кто начинает отношения с альянсом","где взять отношения с альянсом"}},{q="Где найти Кельдрана?",a="Кельдран живет в небольшой лачуге возле западного выхода из Оргриммара, вдали от шумного центра города.",al={"keldran location","where is keldran","keldran orgrimmar","где кельдран","местонахождение кельдрана","кельдран оргриммар"}},{q="Какова роль Кельдрана в Оргриммаре?",a="Кельдран — знаток магии и мистических искусств, помогающий вождю Траллу в деликатных делах, особенно связанных с дипломатией, разведкой и общественным мнением об Орде.",al={"who is keldran","keldran lore","кто такой кельдран","предания о кельдране"}},{q="Почему Тралл заботится о дипломатии с Альянсом?",a="Тралл вырос среди людей и хорошо понимает их политику и военную мощь. Зная, что открытая война может погубить его молодой народ, он выбирает осторожность и взвешенное управление государством, чтобы защитить будущее Орды.",al={"thrall diplomacy","why horde peace with alliance","thrall and humans","дипломатия тралла","почему орда мир с альянсом","тралл и люди"}},{q="Ведет ли это задание к дальнейшим поручениям?",a="Да, сдача этого поручения Кельдрану начинает более глубокий разговор о положении Орды среди других сил и ведет прямо к последующим заданиям, связанным с региональной дипломатией и шпионажем.",al={"alliance relations followup","what comes after alliance relations","продолжение отношений с альянсом","что после отношений с альянсом"}},{q="Почему осмотрительность так важна для этого задания?",a="Открытый конфликт с Альянсом грозит огромными потерями и дестабилизацией Калимдора. Тралл полагается на незаметных агентов, которые улаживают щекотливые дипломатические трения до того, как они перерастут в открытую войну.",al={"why subtlety","keldran subtlety","почему скрытность","скрытность кельдрана"}}},fp="18,359,20.415.0,15.401.0,39.118.0,25.120.0,36.193.0,55.229.0,41.201.0,45.191.0"}
P.entries["quest:1432"] = {n="Отношения с Альянсом",s="«Отношения с Альянсом» — задание Орды, отданное в Оргриммаре и касающееся Пустошей; его цель — предотвратить опасные политические последствия. Поскольку Альянс продвигается все глубже в центральный Калимдор, Орда действует на опережение и уничтожает местные силы Пылающего Легиона, пока соперники не обвинили народ Тралла в новом подчинении демонам.",h="«Отношения с Альянсом» — задание Орды, отданное в Оргриммаре и касающееся Пустошей; его цель — предотвратить...",kw={"alliance relations","burning legion","charred vale","desolace","ghost walker post","keldran","kodo graveyard","takata steelblade","отношения с альянсом","пылающий легион","обугленная долина","пустоши","застава скитающихся духов","кельдран","кладбище кодо","таката стальной клинок"},ang={["class:Warlock"]="Хотя обычные солдаты вроде Такаты Стального Клинка относятся к темным силам с подозрением, операции против диких демонов часто пересекаются с прагматичным использованием Ордой чернокнижников.",["faction:Horde"]="Задание отражает непрекращающуюся борьбу вождя Тралла за признание новой Орды и стремление похоронить наследие демонического рабства, пока враждебные соседи не воспользовались им.",["race:Orc"]="Для орков, стремящихся исполнить замысел Тралла об искуплении, любой намек на демоническую скверну в Калимдоре — горькая угроза с трудом завоеванной свободе."},sec={{t="Вопрос восприятия",b="Пока разведчики и экспедиции Альянса пересекают Калимдор, руководство Орды сталкивается с деликатной дипломатической угрозой. Остатки демонов в центральном Калимдоре рискуют подтвердить старые предрассудки о том, что орки и их союзники по-прежнему связаны с Пылающим Легионом. С санкции вождя Тралла Кельдран в Оргриммаре руководит точечными операциями, чтобы эти демонические остатки были уничтожены раньше, чем враждебные фракции Альянса используют их присутствие как повод для войны."},{t="Застава в пустошах",b="Чтобы доставить приказы на юг, нужно пройти через Обугленную долину в Когтистых горах и спуститься в мрачные просторы Пустошей. Там, к северу от обширного Кладбища кодо, находится Застава Скитающихся Духов. Агенты Орды, такие как Таката Стальной Клинок, наблюдают за безлюдной глушью, где им приходится иметь дело и с многочисленными племенами кентавров, и с повсеместной демонической скверной, грозящей захлестнуть весь край."},{t="Прагматичные союзы",b="Таката Стальной Клинок относится к заданию с мрачным прагматизмом. Хотя уничтожение местных демонов неизбежно ослабляет давление на воинственные племена кентавров и даже помогает чернокнижникам Орды, долг важнее. Уничтожение оплотов Пылающего Легиона служит общей безопасности Орды, кто бы еще ни извлек из этого выгоду."}},faq={{q="Почему Орда беспокоится об Альянсе в этих землях?",a="Пока силы Альянса продвигаются по Калимдору, руководство Орды опасается, что нашествия демонов могут счесть доказательством того, что Орда все еще водится с Пылающим Легионом. Активно уничтожая местных демонов, Орда стремится лишить такие обвинения почвы.",al={"why worry about alliance","horde alliance relations desolace","alliance accusations","зачем беспокоиться об альянсе","отношения орды и альянса пустоши","обвинения альянса"}},{q="Кто такой Кельдран?",a="Кельдран — агент Орды, находящийся в Оргриммаре. С одобрения Вождя он руководит особыми заданиями, направленными на уничтожение демонических сил, которые угрожают положению Орды.",al={"keldran","who is keldran","keldran orgrimmar","кельдран","кто такой кельдран","кельдран оргриммар"}},{q="Где находится Застава Скитающихся Духов?",a="Застава Скитающихся Духов — лагерь в центральной части Пустошей, расположенный прямо к югу от перевала из Обугленной долины в Когтистых горах и к северу от Кладбища кодо.",al={"ghost walker post location","where is takata steelblade","finding ghost walker post","застава скитающихся духов где","где таката стальной клинок","найти заставу скитающихся духов"}},{q="Кто такой Таката Стальной Клинок?",a="Таката Стальной Клинок — солдат Орды на Заставе Скитающихся Духов в Пустошах. По поручению Вождя он сдерживает местные угрозы, например демонов и враждебных кентавров.",al={"takata steelblade","who is steelblade","steelblade desolace","таката стальной клинок","кто такой стальной клинок","стальной клинок пустоши"}},{q="Почему Таката упоминает помощь кентаврам?",a="Кентавры считают Пустоши своей территорией, но у них не хватает сил сдержать растущую демоническую угрозу. Уничтожая местных демонов, Орда невольно помогает кентаврам выжить. Таката мирится с этим лишь ради большей безопасности Орды.",al={"helping centaur","centaur desolace","why aid centaur","помощь кентаврам","кентавры пустоши","зачем помогать кентаврам"}},{q="Как чернокнижники связаны с этим заданием?",a="Задание искореняет диких демонов, но Таката с некоторым отвращением отмечает, что очистка от демонических реагентов и влияния неизбежно пересекается с деятельностью спорных чернокнижников Орды и помогает им.",al={"warlock connection","why help warlocks","warlocks in the horde","связь с чернокнижниками","зачем помогать чернокнижникам","чернокнижники в орде"}}},fp="18,314,22.507.0,21.393.0,19.377.1,51.256.0,15.187.0,35.179.0,25.185.0,43.255.0,38.213.0"}
P.entries["quest:144"] = {n="Гонец в Западный Край",s="«Гонец в Западный Край» — дипломатическое поручение: доставить суровый ответ Гриана Камнегрива из Сторожевого холма Мировому судье Соломону в Приозерье. Соломон, измученный местными угрозами в Красногорье, просил военной помощи у Народного ополчения, но узнал, что Западный Край так же брошен короной.",h="«Гонец в Западный Край» — дипломатическое поручение: доставить суровый ответ Гриана Камнегрива из Сторожевого...",kw={"gryan stoutmantle","lakeshire","magistrate solomon","messenger to westfall","peoples militia","redridge","sentinel hill","westfall","гриан камнегрив","приозерье","мировой судья соломон","гонец в западный край","народное ополчение","красногорье","сторожевой холм","западный край"},ang={["faction:Alliance"]="Эта переписка обнажает глубокий разлом между правителями в Крепости Штормграда и дальними провинциями: Западный Край и Красногорье оставлены полностью на произвол судьбы.",["race:Human"]="Для людей-путников доставка этого послания подчеркивает трагическую оторванность провинциальных городов, где простые жители и ветераны проливают кровь, удерживая земли, которые знать Штормграда отказывается защищать."},sec={{t="Мольба через меняющиеся рубежи",b="Мировой судья Соломон из Приозерья столкнулся с растущими бедами в Красногорье, не имея поддержки королевского гарнизона Штормграда. Ища союзников в южных землях королевства, он обратился к Гриану Камнегриву, командиру Народного ополчения в Западном Крае. Соломон надеялся, что организованный отряд добровольцев на Сторожевом холме выделит войска для обороны Приозерья, не зная о мрачной действительности западных равнин."},{t="Горький отказ",b="Ответ Гриана Камнегрива — недвусмысленный отказ, сказанный с тяжелым сердцем. Западный Край поглощен собственной отчаянной войной с Братством Справедливости и разбойничающими гноллами, и эта борьба стала необходимой лишь потому, что Дом знати и корона бросили свою житницу. Камнегрив ясно дает понять, что Народное ополчение существует только ради выживания: люди гибнут каждый день, и ни одного бойца для спасения Красногорья выделить нельзя."},{t="Раскалывающееся королевство",b="Ответ Камнегрива, доставленный в Приозерье, разрушает иллюзии Соломона. Судья понимает, что пограничные земли королевства брошены так же, а местные судьи и народные ополчения предоставлены сами себе, тогда как Армия Штормграда необъяснимо остается в стороне. Разочарование заставляет Соломона обратить взор на юг и искать помощи в Темнолесье в Сумеречном лесу."}},faq={{q="Почему Мировой судья Соломон попросил помощи у Западного Края?",a="Мировой судья Соломон сталкивается с растущими угрозами в Приозерье без поддержки армии Штормграда. Зная, что Гриан Камнегрив создал Народное ополчение для защиты Западного Края, Соломон надеялся, что у пограничных сил найдутся лишние бойцы для военной помощи Красногорью.",al={"why ask westfall","solomon letter to stoutmantle","why westfall militia","почему просить западный край","письмо соломона камнегриву","почему ополчение западного края"}},{q="Почему Гриан Камнегрив отказывается прислать помощь?",a="Народное ополчение и так измотано до предела борьбой с Братством Справедливости и защитой ферм Западного Края. Камнегрив объясняет, что, не оставь Штормград Западный Край, ополчению не пришлось бы и существовать, а лишних солдат у него нет.",al={"why stoutmantle says no","militia refuse lakeshire","stoutmantle response","почему камнегрив отказал","ополчение отказ приозерье","ответ камнегрива"}},{q="Где Армия Штормграда во время этих бедствий?",a="Королевская армия сосредоточена вокруг Штормграда, и правящий совет не пускает ее в сельские земли. И Соломон, и Камнегрив выражают недоумение и обиду из-за того, что столица оставляет внешние провинции без защиты.",al={"why stormwind not helping","where is the army","stormwind desertion","почему штормград не помогает","где армия","штормград бросил"}},{q="Что происходит после возвращения письма Камнегрива Соломону?",a="Поняв, что Западный Край помочь не сможет, Мировой судья Соломон обращается к Сумеречному лесу и отправляет гонца дальше, в Темнолесье, в надежде, что Ночной Дозор мэра Элло Эбонлока пришлет помощь.",al={"next quest after messenger to westfall","what does solomon do next","следующее задание после гонца в западный край","что делает соломон дальше"}},{q="Что такое Народное ополчение?",a="Народное ополчение — армия добровольцев, созданная Грианом Камнегривом, с базой на Сторожевом холме. Оно состоит из местных фермеров, ветеранов и жителей и защищает Западный Край от разбойников и гноллов при полном отсутствии королевских войск.",al={"who are the peoples militia","westfall militia","кто такое народное ополчение","ополчение западного края"}},{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — солдат-ветеран, взявший на себя командование обороной Западного Края. Из башни на Сторожевом холме он собирает добровольцев и координирует войну против Братства Справедливости.",al={"gryan stoutmantle lore","who is stoutmantle","гриан камнегрив предания","кто такой камнегрив"}}},fp="21,319,32.470.0,16.441.0,30.395.1,49.262.0,46.273.0,48.236.0,61.195.1,29.234.0,25.204.0"}
P.entries["quest:1442"] = {n="Поиск самоцвета Кора",s="«Поиск самоцвета Кора» — задание паладинов Альянса, которое уводит новичка вглубь древних руин северного Калимдора. По указанию ночного эльфа Тандриса Ветропряда в Аубердине паладины отправляются в Непроглядную Пучину, чтобы отнять могущественный самоцвет Кора у оскверняющих его наг. Добытый камень — ключевой материал для работы Джордана Стилвелла.",h="«Поиск самоцвета Кора» — задание паладинов Альянса, которое уводит новичка вглубь древних руин северного...",ang={["class:Paladin"]="Для паладина Альянса это задание — важнейшее испытание характера и выносливости: оно проверяет вашу готовность отправиться во враждебные глубины Калимдора, чтобы выковать освященное оружие Света.",["faction:Alliance"]="Это задание показывает единство Альянса в действии: кузнец-человек полагается на мудрость ночных эльфов и дворфийскую сталь, чтобы выковать оружие против нарастающей тьмы.",["race:NightElf"]="Сотрудничество Тандриса Ветропряда подчеркивает хрупкий, но крепнущий мост между древними кальдораями и недавно ставшими союзниками приверженцами Света из Восточных королевств."},sec={{t="Надежный Альянс",b="Когда паладины-ученики ищут материалы, нужные кузнецу-человеку Джордану Стилвеллу, их путь пересекает границы континентов и ведет к Темным берегам. Там, в Аубердине, Тандрис Ветропряд с уважением вспоминает кузнеца. Несмотря на природную отчужденность ночных эльфов и проступки некоторых павших людей, Тандрис верит в паладинов, идущих праведным путем, и охотно открывает, где находятся такие древние самоцветы."},{t="В глубины",b="Поиски ведут прямо в подземный храмовый комплекс Непроглядной Пучины на туманном северо-западном побережье Ясеневого леса. В водных глубинах, населенных культистами Сумеречного Молота и коварными морскими обитателями, также живут жрицы наги, направляющие скверную магию через древние самоцветы Кора. Паладин должен пройти эти темные залы, победить колдуний и добыть самоцвет, пропитанный змеиной злобой."},{t="Очищение камня",b="Когда оскверненный самоцвет Кора возвращается к Тандрису Ветропряду, становится ясна истинная цель поисков эльфийского мистика. Наги наделяют самоцвет сырой магической силой, но их чары искажают его во зло. Прежде чем Джордан Стилвелл выкует из него священное оружие, Тандрис должен изгнать тьму, чтобы сила камня осталась чистой и устойчивой для предстоящего священного ритуала."}},faq={{q="Кто посылает вас искать самоцвет Кора?",a="Задание выдает Тандрис Ветропряд, ночной эльф из прибрежного порта Аубердин на Темных берегах. Он направляет паладинов от имени оружейника Джордана Стилвелла.",al={"quest giver seeking kor gem","who gives seeking the kor gem","thundris windweaver quest","кто дает задание поиск самоцвета кора","кто выдает поиск самоцвета кора","задание тандриса ветропряда"}},{q="Где находится самоцвет Кора?",a="Самоцвет находится в Непроглядной Пучине — древнем подземном подземелье на северо-западе Ясеневого леса, на побережье. Его носят жрицы наги, населяющие руины.",al={"kor gem location","where to get kor gem","where is corrupted kor gem","где самоцвет кора","где достать самоцвет кора","где оскверненный самоцвет кора"}},{q="Зачем Джордану Стилвеллу нужен самоцвет Кора?",a="The gem contains potent magical energies required as a component for crafting Jordan's refined weapon during the paladin trial known as The Test of Righteousness.",al={"why kor gem","what is kor gem for","stilwell gem","зачем самоцвет кора","для чего самоцвет кора","самоцвет стилвелла"}},{q="Почему Тандрису нужно очистить самоцвет?",a="Наги наделяют самоцветы Кора значительной тайной силой, но их мерзкая природа оскверняет магию. Тандрис очищает самоцвет от скверны, чтобы оставшуюся силу можно было безопасно направить в оружие Света.",al={"why purify kor gem","corrupted kor gem cleansed","cleansing the gem","зачем очищать самоцвет кора","очищение самоцвета кора","очистка самоцвета"}},{q="Почему Тандрис упоминает «падший род»?",a="Тандрис, вероятно, намекает на громкие предательства людей, например принца Артаса Менетила, чье падение во тьму запятнало репутацию Серебряной Длани по всему Азероту. Тем не менее Тандрис судит о каждом паладине по его собственным заслугам.",al={"who is the fallen one","thundris fallen kind","fallen paladin reference","кто падший","тандрис падший род","упоминание падшего паладина"}},{q="Нужна ли мне группа, чтобы добыть самоцвет Кора?",a="Тандрис прямо предупреждает искателей приключений не идти в одиночку. Поскольку самоцвет выпадает из элитных наг в глубине Непроглядной Пучины, настоятельно советуется входить туда со сплоченной группой.",al={"is kor gem soloable","can you solo kor gem","blackfathom deeps group","самоцвет кора в одиночку","можно ли в одиночку самоцвет кора","непроглядная пучина группа"}}},fp="19,352,18.444.0,14.411.0,19.377.1,34.175.0,29.185.0,40.162.0,41.222.0,42.260.0,37.188.0"}
P.entries["quest:1447"] = {n="Пропавший дипломат",s="Это напряженное столкновение — ключевой шаг в раскрытии тайны пропавшего дипломата. Идя по следу через трущобы Штормграда, следователь загоняет Дашеля Каменного Кулака в угол в Старом городе, чтобы выбить ответы из упрямого головореза.",h="Это напряженное столкновение — ключевой шаг в раскрытии тайны пропавшего дипломата.",kw={"brawl","conspiracy","dashel","missing diplomat","old town","stonefist","stormwind","thugs","драка","заговор","дашель","пропавший дипломат","старый город","каменный кулак","штормград","головорезы"},ang={["class:Rogue"]="Старый город — ваша естественная среда, а разговор с громилами вроде Дашеля Каменного Кулака — обычное дело, когда нужно выбить из осведомителей уличные сведения.",["faction:Alliance"]="Каждая зацепка в деле об исчезновении дипломата важна для раскрытия внутренней измены, угрожающей устойчивости руководства Альянса.",["race:Human"]="Открытие того, что местные головорезы в самой столице Штормграда активно мешают поискам пропавшего дипломата, бьет в самое сердце безопасности королевства."},sec={{t="Дружеская беседа в Старом городе",b="След пропавшего дипломата ведет в глубокие тени Старого города, где карманники и подозрительные посредники скрываются от бдительных глаз Собора. Известно, что Дашель Каменный Кулак связан с сомнительными группировками города и владеет ценными сведениями о похищении, но не желает делиться ими по доброй воле с агентами, задающими щекотливые вопросы."},{t="Драка в переулке",b="Когда к нему подходят, Дашель быстро отбрасывает всякое притворство. При поддержке верных ему головорезов из Старого города он пытается избить любопытных путников и навсегда заставить расследование замолчать. Усмирить Дашеля и перебить его подмогу — единственный язык, который он уважает: он быстро меняет тон и открывает путь к следующей зацепке в заговоре."}},faq={{q="Кто такой Дашель Каменный Кулак?",a="Дашель Каменный Кулак — подозрительный тип, обитающий в Старом городе и связанный с преступным миром Штормграда. Он выступает местным осведомителем и знает гораздо больше, чем говорит, о незаконных делах в городе.",al={"dashel stonefist","who is stonefist","dashel","дашель каменный кулак","кто такой каменный кулак","дашель"}},{q="Почему я должен сражаться с Дашелем, а не просто поговорить с ним?",a="Дашель не заинтересован в сотрудничестве со следователями. Как только вы спрашиваете о пропавшем дипломате, он решает, что вас легко запугать, и призывает головорезов, чтобы заставить вас замолчать. Только хорошая трепка убеждает его заговорить.",al={"why fight dashel","can i talk to stonefist","why beat up dashel","почему сражаться с дашелем","можно ли поговорить с каменным кулаком","зачем бить дашеля"}},{q="Нужно ли убивать Дашеля Каменного Кулака?",a="Нет. Цель — заставить его сдаться, а не казнить. Когда его здоровье падает достаточно низко, он уступает, отзывает своих приспешников и соглашается ответить на ваши вопросы.",al={"do i kill dashel","stonefist alive","is dashel dead","убивать ли дашеля","каменный кулак жив","мертв ли дашель"}},{q="Где происходит этот бой?",a="Столкновение происходит на открытом месте в Старом городе, возле переулков за таверной «Свинья и свисток» и местных учебных залов, где обычно околачивается Каменный Кулак.",al={"stonefist location","where is dashel","old town brawl","где каменный кулак","где дашель","драка в старом городе"}},{q="Что происходит после победы над Дашелем?",a="Побежденный и смирившийся Дашель извиняется и готов рассказать, что знает о заговоре, направляя расследование к следующему звену цепочки за пределами столицы.",al={"what next after dashel","stonefist next quest","diplomat chain next","что дальше после дашеля","следующее задание каменного кулака","следующая цепочка дипломата"}},{q="О чем на самом деле цепочка заданий «Пропавший дипломат»?",a="Хотя официально это поиски пропавшего посла, цепочка заданий раскрывает паутину обмана вокруг похищения дипломата и теневых фигур, которые за ним стоят.",al={"missing diplomat lore","who is the diplomat","missing king","пропавший дипломат предание","кто такой дипломат","пропавший король"}}},fp="20,242,27.380.0,18.363.1,24.210.0,61.230.0,35.179.0,33.173.0,34.184.1,50.181.2"}
P.entries["quest:145"] = {n="Гонец в Темнолесье",s="«Гонец в Темнолесье» — срочная дипломатическая миссия, которую Мировой судья Соломон из Приозерья посылает к лорду Элло Чернодреву в Сумеречный лес. Отчаянно нуждаясь в военном подкреплении против орков Черной Горы и гноллов, угрожающих Красногорью, Соломон обращается за помощью к соседнему поселению. Гонцу предстоит пройти по мрачным дорогам Сумеречного леса, чтобы доставить официальную просьбу Соломона мэру Темнолесья.",h="«Гонец в Темнолесье» — срочная дипломатическая миссия, которую Мировой судья Соломон из Приозерья посылает к...",kw={"darkshire","duskwood","ebonlocke","lakeshire","messenger","night watch","redridge","solomon","темнолесье","сумеречный лес","чернодрев","приозерье","гонец","ночной дозор","красногорье","соломон"},ang={["faction:Alliance"]="Отчаянные письма Соломона показывают, насколько разобщенными и заброшенными стали отдаленные города Альянса, пока королевский двор Штормграда остается парализованным.",["race:Human"]="Это задание иллюстрирует общую беду южных поселений людей, вынужденных полагаться на нерегулярное местное ополчение после того, как королевство отозвало патрули регулярной армии."},sec={{t="Отчаянный призыв о помощи",b="Поскольку королевский двор Штормграда игнорирует его просьбы, а соседний Западный Край погряз в собственном мятеже, Мировой судья Соломон обращает взгляд на юг, к Сумеречному лесу. Красногорью грозит растущая осада кланов орков Черной Горы и агрессивных стай гноллов, и местная стража Приозерья измотана до предела. В отчаянии Соломон пишет письмо прямо мэру Элло Чернодреву, надеясь нанять или одолжить прославленный Ночной Дозор Темнолесья для усиления обороны поселка."},{t="Дорога в мрак",b="Чтобы доставить письмо Соломона, нужно пересечь границы королевства и попасть в Сумеречный лес — лесистую область, окутанную сверхъестественным мраком. Соломон предупреждает гонцов строго держаться дорог, так как дикая местность между Приозерьем и Темнолесьем стала крайне опасной. Дойдя до Ратуши Темнолесья, вы передадите послание в руки лорда Чернодрева, но найдутся ли в Сумеречном лесу лишние силы — совсем другой вопрос."}},faq={{q="Почему Приозерье просит помощи у Темнолесья?",a="Штормград отказал в официальной военной помощи, оставив такие города, как Приозерье, защищаться самостоятельно от огромных угроз вроде орков Черной Горы. Мировой судья Соломон пробует обратиться ко всем соседним союзникам Альянса, надеясь, что гражданское ополчение Темнолесья, Ночной Дозор, сможет выделить обученных бойцов.",al={"why ask duskwood","why darkshire","solomon darkshire plea","почему сумеречный лес","почему темнолесье","просьба соломона к темнолесью"}},{q="Кто такой лорд Элло Чернодрев?",a="Лорд Элло Чернодрев — мэр Темнолесья и главный гражданский лидер Сумеречного леса. Он управляет городом из ратуши и координирует гражданские дела вместе с командиром Алтеей Чернодрев, возглавляющей Ночной Дозор.",al={"ello ebonlocke","who is ebonlocke","mayor of darkshire","элло чернодрев","кто такой чернодрев","мэр темнолесья"}},{q="Что такое Ночной Дозор?",a="Ночной Дозор — независимое гражданское ополчение Темнолесья, созданное для патрулирования окрестностей и борьбы с нежитью, чудовищами и тенями, подбирающимися через Сумеречный лес, поскольку войск гарнизона Штормграда здесь нет.",al={"night watch duskwood","who are night watch","ночной дозор сумеречный лес","кто такой ночной дозор"}},{q="Почему Соломон предупреждает меня держаться дорог?",a="Дикие земли Сумеречного леса кишат ужасами нежити, пауками и свирепыми зверями. Стоит сойти с мощеной дороги в подлесок, и путники рискуют встретиться с агрессивными хищниками и засадами.",al={"duskwood road warning","stay on roads duskwood","предупреждение о дороге сумеречный лес","держаться дорог сумеречный лес"}},{q="С чего началась эта цепочка заданий?",a="Это задание — часть серии отчаянных посланий Мирового судьи Соломона. Оно следует за его предыдущей просьбой, отправленной Гриану Камнегриву в Западный Край, и продолжает его неустанные усилия привлечь помощь для Приозерья.",al={"previous quest","messenger quest order","предыдущее задание","порядок заданий гонца"}},{q="Есть ли у Темнолесья действительно лишние стражники?",a="Сумеречный лес переживает собственный экзистенциальный кризис: его осаждают восставшие мертвецы, одичавшие воргены и таящиеся чудовища. Ночному Дозору едва хватает бойцов для защиты самого Темнолесья, так что просьба Соломона — горькая попытка почти без шансов.",al={"will darkshire help","does ebonlocke send guards","поможет ли темнолесье","пришлет ли чернодрев стражу"}}},fp="22,397,24.474.0,23.445.0,43.299.0,27.230.0,24.213.0,46.185.0,31.203.0,45.237.0"}
P.entries["quest:1453"] = {n="Дела Поисковой корпорации в Пустошах",s="«Дела Поисковой корпорации в Пустошах» — вводное задание Альянса, направляющее искателей приключений из Стальгорна в суровые бесплодные земли Пустошей. Его выдает Ройттен Камнемолот и отправляет новобранцев за море к Крелдигу Унгору на Высоту Найджела, чтобы помочь Поисковой корпорации за плату возвращать утраченные сокровища и реликвии.",h="«Дела Поисковой корпорации в Пустошах» — вводное задание Альянса, направляющее искателей приключений из...",kw={"centaur","desolace","ironforge","kreldig ungor","nijel's point","reclaimers","roetten stonehammer","stonetalon","кентавр","пустоши","стальгорн","крелдиг унгор","высота найджела","поисковая корпорация","ройттен камнемолот","когтистые горы"},ang={["faction:Alliance"]="Высота Найджела — главное убежище Альянса в западных пустошах центрального Калимдора, служащее плацдармом, окруженным враждебными кланами кентавров.",["race:Dwarf"]="Через Лигу исследователей или независимые группы поисковиков вроде Поисковой корпорации, предприимчивость дворфов проникает даже в самые мрачные уголки Калимдора."},sec={{t="Зов пустошей",b="Пока Стальгорн кипит ремесленниками и делами дворфов, далекий Калимдор остается диким рубежом. Ройттен Камнемолот выступает городским посредником Поисковой корпорации — предприимчивой группы, стремящейся нажиться на забытых руинах и бесплодных землях. Он вербует рвущихся в бой искателей приключений, проходящих через великий горный город, предупреждая, что Пустоши — ужасная местность, наводненная враждующими кланами кентавров, но полная выгодных возможностей для тех, кто достаточно смел, чтобы отправиться в путь."},{t="Высота Найджела и Поисковая корпорация",b="Дорога ведет далеко на запад через Когтистые горы на север Пустошей, где Альянс держит Высоту Найджела — укрепленное убежище высоко в скалах. Там Крелдиг Унгор приветствует новых людей. Поисковая корпорация работает по простому принципу: в истерзанном войнами мире люди постоянно теряют семейные реликвии, магические артефакты и сокровища. При достаточной выдержке и подходящей цене Крелдиг и его соратники добиваются, чтобы утраченные ценности были возвращены из диких земель."}},faq={{q="Кто выдает это задание?",a="Ройттен Камнемолот предлагает это задание в Стальгорне. Он направляет искателей приключений, ищущих честную и прибыльную работу, в Калимдор, чтобы они связались с его компаньоном.",al={"quest giver","who starts reclaimers business","roetten stonehammer location","персонаж, выдающий задание","кто начинает дела поисковой корпорации","где ройттен камнемолот"}},{q="Где находится Высота Найджела?",a="Высота Найджела расположена в северо-восточных скалах Пустошей. Двигаясь на юг из Когтистых гор в Пустоши, идите вдоль утесов на восток, пока не найдете освещенную факелами горную тропу, ведущую вверх к форпосту Альянса.",al={"find nijels point","how to get to nijels point","nijels point location","найти высоту найджела","как добраться до высоты найджела","где высота найджела"}},{q="Что представляет собой Поисковая корпорация?",a="Поисковая корпорация — предприимчивое объединение, которое возглавляют дворфы-агенты вроде Крелдига Унгора. Они специализируются на возвращении утраченных семейных реликвий, редких древностей и магических реликвий из опасных уголков мира по поручению платящих клиентов.",al={"what are reclaimers","reclaimers faction","reclaimers lore","что такое поисковая корпорация","фракция поисковой корпорации","поисковая корпорация предание"}},{q="Какие опасности ждут в Пустошах?",a="Пустоши — засушливая мрачная пустошь, где господствуют враждующие племена кентавров, остатки нежити и враждебные животные. Это суровое испытание для бывалых путников, отважившихся выйти за пределы Когтистых гор.",al={"desolace dangers","what is in desolace","опасности пустошей","что в пустошах"}},{q="Кто такой Крелдиг Унгор?",a="Крелдиг Унгор — дворф, расквартированный на Высоте Найджела в Пустошах. Он координирует спасательные операции и поиски реликвий в регионе, нанимая способных искателей приключений для вылазок в руины и лагеря кентавров.",al={"kreldig ungor lore","who is kreldig","крелдиг унгор предание","кто такой крелдиг"}},{q="Обязательно ли это задание для выполнения заданий в Пустошах?",a="Нет, это необязательное вводное задание. Вы можете самостоятельно отправиться прямо на Высоту Найджела, но разговор с Ройттеном Камнемолотом даст удобные сведения и направление перед выходом.",al={"do i need this quest","is reclaimers business required","нужно ли это задание","обязательны ли дела поисковой корпорации"}}},fp="32,321,23.489.0,32.515.0,21.152.0,23.241.0,23.239.0,31.198.0,21.197.0,44.196.0"}
P.entries["quest:146"] = {n="Гонец в Темнолесье",s="Гонец в Темнолесье завершает отчаянную дипломатическую переписку между Приозерьем и Темнолесьем. Просьба Мирового судьи Соломона о военном подкреплении решительно отклонена лордом Элло Чернодревом, и обнажается горькая правда: оба города брошены Штормградом на произвол судьбы.",h="Гонец в Темнолесье завершает отчаянную дипломатическую переписку между Приозерьем и Темнолесьем.",kw={"darkshire","ebonlocke","lakeshire","messenger","night watch","solomon","stormwind","темнолесье","чернодрев","приозерье","гонец","ночной дозор","соломон","штормград"},ang={["faction:Alliance"]="Это донесение обнажает глубокие трещины в южном королевстве: окраинные поселения Альянса оказались брошены и беззащитны.",["race:Human"]="Для людей-путников эта переписка — отрезвляющий пример того, насколько изолированными стали города королевства, пока королевский двор смотрит в другую сторону."},sec={{t="Отчаянная просьба отклонена",b="Перед натиском орков Черной горы и гноллов Мировой судья Соломон из Красногорья надеялся, что его старый собрат в Сумеречном лесу сможет выделить войска. Но реакция лорда Элло Чернодрева граничит с возмущением. Темнолесье едва сдерживает живых мертвецов, голодных зверей и проклятую магию, наступающие со всех сторон леса. Чернодрев прямо заявляет, что Ночной Дозор существует лишь потому, что Штормград первым бросил Сумеречный лес. Если лишить Темнолесье защитников, поселение падет еще до того, как патруль выйдет за пределы леса."},{t="Череда предательств",b="Прочитав ответ Чернодрева, Соломон осознает суровую действительность королевства. Армия Штормграда ушла из Западного Края, оставила Темнолесье справляться самостоятельно, а теперь проигнорировала и призывы Приозерья о помощи. Соломон вынужден признать то, о чем начали шептаться местные правители по всему королевству: это не просто бюрократическая оплошность или некомпетентность, а подозрение в измене в самом сердце Штормграда."}},faq={{q="Почему лорд Чернодрев не отправляет Ночной Дозор на помощь Приозерью?",a="Темнолесье осаждено со всех сторон нежитью, зверями и грязным колдовством. Ночной Дозор — нерегулярное местное ополчение, созданное именно потому, что Штормград вывел свои гарнизоны. Если бы Чернодрев отправил стражу в Красногорье, Темнолесье было бы захвачено еще до того, как войска миновали бы границу леса.",al={"why ebonlocke refuse","why no night watch for lakeshire","darkshire refuses help","почему чернодрев отказал","почему ночной дозор не помог приозерью","темнолесье отказывает в помощи"}},{q="Что понимает Мировой судья Соломон, прочитав ответ?",a="Соломон понимает, что беда Приозерья — часть кризиса, охватившего все королевство. Поскольку армия отступила из Западного Края, а стража полностью исчезла из Темнолесья, Соломон подозревает не простое пренебрежение, а настоящую измену в руководстве Штормграда.",al={"solomon reaction","what does solomon realize","реакция соломона","что понял соломон"}},{q="Кто создал Ночной Дозор?",a="Ночной Дозор собрали измученные жители и предводители Сумеречного леса во главе с лордом Элло Чернодревом после того, как официальные силы Штормграда бросили эти земли во тьме и разложении.",al={"night watch origins","who made night watch","происхождение ночного дозора","кто создал ночной дозор"}},{q="Куда Соломон отправится дальше за помощью?",a="Поскольку Темнолесье отказывает в помощи, а Западный Край захвачен Братством Справедливости, Приозерье остается совсем одно. Соломон вынужден внимательнее присмотреться ко двору во дворце Штормграда, чтобы выяснить, почему корона отказывается защищать окраинные земли.",al={"what does solomon do next","who else can help lakeshire","что соломон делает дальше","кто еще может помочь приозерью"}},{q="Действительно ли Штормград официально ушел из Сумеречного леса и Западного Края?",a="Да. Когда темная магия исказила Сумеречный лес, а в Западном Крае вспыхнули беспорядки, регулярные войска Штормграда ушли, и пограничным городам пришлось создавать местные ополчения, такие как Ночной Дозор и Народное ополчение, чтобы выжить.",al={"why did stormwind leave","stormwind abandoned towns","почему штормград ушел","штормград бросил города"}},{q="Какие отношения связывают Соломона и Чернодрева?",a="Они давние собратья и мировые судьи, управляющие пограничными городами королевства. Соломон рассчитывал на эти личные отношения, прося войска, но чрезвычайная опасность в Сумеречном лесу сделала согласие невозможным.",al={"are solomon and ebonlocke friends","solomon and ello relationship","друзья ли соломон и чернодрев","соломон и элло отношения"}}},fp="22,292,26.542.0,24.418.1,64.301.0,63.257.0,27.189.0,44.245.0,59.213.0,51.234.0"}
P.entries["quest:1462"] = {n="Сапта земли",s="Сапта земли — обряд восполнения, который предлагает Провидица Воронье Перо в Лагере Нараче. Молодым шаманам, проходящим посвящение для общения с духами камня, нужен этот отвар, чтобы открыть внутреннее зрение. Если новичок потерял или разлил приготовленное зелье до завершения обряда, провидица готовит новое, чтобы испытание можно было продолжить.",h="Сапта земли — обряд восполнения, который предлагает Провидица Воронье Перо в Лагере Нараче.",kw={"call of earth","camp narache","draught","earth sapta","elemental","mulgore","seer ravenfeather","shaman","зов земли","лагерь нараче","отвар","сапта земли","элементаль","мулгор","провидица воронье перо","шаман"},ang={["class:Shaman"]="Сапта — основа вашего раннего обучения, духовный катализатор, который впервые открывает вам глаза на стихийные силы, направляющие мир.",["faction:Horde"]="Приверженность Орды шаманским традициям взращивается в таких местах, как Мулгор, где племенные провидцы терпеливо воспитывают следующее поколение духовных вожатых.",["race:Tauren"]="Почитание Матери-Земли начинается с умения слышать землю, и старейшины Лагеря Нараче тщательно следят, чтобы ни один юноша не был отвернут от священного пути."},sec={{t="Отвар прозрения",b="Путь шамана начинается с настройки смертных чувств на силы, недоступные физическому зрению. Чтобы воспринимать духов стихий этой земли, посвящаемый должен выпить сильный ритуальный отвар — сапту. Сапта земли, наполненная природными сущностями, связанными со стихией камня и почвы, приподнимает завесу между материальным миром и миром духов и позволяет новичку напрямую общаться с элементалями земли Мулгора."},{t="Второй шанс прозреть",b="Духовные искусства требуют дисциплины, но опытные провидцы знают, что молодые посвящаемые часто оступаются или теряют священные реагенты в диких землях. Провидица Воронье Перо несет неусыпную вахту в Лагере Нараче и следит, чтобы любой ученик, потерявший отвар до общения у каменного монумента, мог обновить свое приготовление. С тихим терпением она дает новый сосуд, чтобы новичок мог предстать перед духами непоколебимым."}},faq={{q="Что такое сапта земли?",a="Сапта земли — священное травяное снадобье, которое варят шаманские старейшины. Выпитая посвящаемым, она пробуждает его внутренние чувства и дает духовное зрение, необходимое, чтобы видеть элементалей земли, невидимых обычным глазам, и общаться с ними.",al={"what is sapta","earth sapta lore","what does the brew do","что такое сапта","сапта земли предание","что делает отвар"}},{q="Зачем посвящаемому еще одна сапта земли?",a="Ученики, проходящие испытания в диких землях, порой теряют, разливают или преждевременно выпивают отвар, не дойдя до священного места. Провидица Воронье Перо дает еще одну порцию, чтобы духовное обучение не прервалось навсегда из-за простой ошибки.",al={"lost my sapta","why get another sapta","lost earth sapta","потерял сапту","зачем еще сапта","потерял сапту земли"}},{q="Кто такая Провидица Воронье Перо?",a="Провидица Воронье Перо — духовная наставница из народа таурен, живущая в Лагере Нараче в Мулгоре. Она руководит первыми испытаниями юных шаманов-таурен и направляет их при первом общении с духами земли.",al={"who is ravenfeather","seer ravenfeather lore","camp narache seer","кто такая воронье перо","провидица воронье перо","провидица лагерь нараче"}},{q="Почему шаманы должны пить сапту, чтобы видеть элементалей?",a="Шаманы-новички еще не развили врожденную связь со стихиями настолько, чтобы воспринимать их по желанию. Сапта служит мостом, изменяя духовное восприятие пьющего, пока он не научится слышать стихии и общаться с ними собственной силой.",al={"why need a potion to see spirits","why drink sapta","зачем зелье чтобы видеть духов","зачем пить сапту"}},{q="Где проходит испытание сапты земли?",a="Ритуальное испытание проводится на холмах Плато Красного Облака в Мулгоре, недалеко от Лагеря Нараче. Новички несут отвар к священному каменному монументу, где обитают местные духи земли.",al={"where do i use sapta","call of earth location","где использовать сапту","зов земли местонахождение"}},{q="Все ли шаманы используют сапты?",a="И шаманские традиции таурен, и орков используют сапты при первых посвящениях в стихии. У каждой стихии, с которой шаман впервые общается, например земли, огня и воды, есть своя сапта, помогающая настроить чувства шамана на эту стихийную плоскость.",al={"do orcs use saptas","are saptas only tauren","используют ли орки сапты","сапты только у таурен"}}},fp="11,355,19.433.0,24.422.0,23.266.0,47.265.0,25.214.0,48.248.0,51.181.0,25.255.0"}
P.entries["quest:1463"] = {n="Сапта земли",s="Это поручение — проверка ответственности для посвящаемого шамана в Долине Испытаний. Если послушник потерял освященную сапту земли до общения с духами земли, Канага заклинатель земли выдает новую и строго напоминает бережно обращаться со священными отварами.",h="Это поручение — проверка ответственности для посвящаемого шамана в Долине Испытаний.",kw={"call of earth","canaga earthcaller","draught","durotar","earth sapta","shaman","totem","valley of trials","зов земли","канага заклинатель земли","отвар","дуротар","сапта земли","шаман","тотем","долина испытаний"},ang={["class:Shaman"]="Для посвящаемого потеря сапты — ранний урок дисциплины: общение со стихиями требует неослабного внимания, а не небрежных рук.",["race:Orc"]="В засушливых скалах Дуротара молодые орки, постигающие древние пути шаманизма, должны доказать преданность предкам и земле под своими ногами.",["race:Troll"]="Тролли Черного Копья, идущие путем стихий в Долине Испытаний, учатся сочетать традиционное поклонение лоа с непосредственным почитанием духов стихий."},sec={{t="Второй шанс со стихиями",b="Путь шамана требует полной внимательности и уважения к духам мира. Сапта земли, приготовленная особыми обрядами, — стихийный отвар, истончающий завесу между материальным миром и духами камня и почвы. Если посвящаемый случайно потерял или разлил этот отвар, путешествуя по Дуротару, Канага заклинатель земли с доброй волей готов приготовить новый, но заодно предупреждает новичка, что нужно быть гораздо бдительнее со священными дарами."},{t="Наставление Канаги",b="Канага заклинатель земли присматривает за юными шаманами, выходящими из Логова в Долине Испытаний. Понимая, что молодые орки и тролли склонны к хаосу первых испытаний, он подчеркивает, что духи стихий не терпят небрежности. Принять вторую сапту — небольшой урок смирения: юный шаман должен помнить, что силу, данную землей, нужно оберегать и уважать."}},faq={{q="Что такое сапта земли?",a="Сапта земли — особо приготовленный церемониальный отвар, который используют посвящаемые шаманы. Выпивший его обретает духовное зрение и может видеть духов земли и говорить с ними, хотя обычным глазам они незримы.",al={"what is sapta","earth sapta use","purpose of sapta","что такое сапта","применение сапты земли","назначение сапты"}},{q="Почему Канага заклинатель земли предлагает это задание?",a="Канага заклинатель земли выдает замену, если посвящаемый потерял сапту земли до завершения обряда общения во время испытаний Зова Земли. Он дает новую с доброй волей, чтобы послушник мог завершить свою духовную задачу.",al={"why canaga gives sapta","lost my earth sapta","зачем канага дает сапту","потерял сапту земли"}},{q="Где проходит этот обряд?",a="Это происходит в Долине Испытаний — выжженном солнцем каньоне на юго-западе Дуротара, где молодые орки и тролли начинают свой путь дисциплины и чести.",al={"where is canaga","valley of trials sapta location","где канага","долина испытаний сапта местонахождение"}},{q="Неужели духи плохо относятся к потере сапты?",a="Хотя духи терпеливы, Канага напоминает посвящаемым, что небрежное обращение со священными отварами свидетельствует о недостатке сосредоточенности. Истинный шаман должен относиться к каждому дару стихий с полным благоговением.",al={"does losing sapta matter","lore of losing sapta","важна ли потеря сапты","предание о потере сапты"}},{q="Кто может пройти это общение?",a="Приготовление и питье сапты земли доступно только практикующим шаманам, стремящимся настроиться на свой первый тотем стихии — Тотем земли.",al={"who can get earth sapta","classes for sapta","кто может получить сапту земли","классы для сапты"}},{q="Что происходит после того, как посвящаемый выпьет сапту?",a="Выпитый отвар открывает внутреннее зрение посвящаемого, позволяя ему найти и поговорить с местным воплощением духа земли, скрывающимся среди скал Долины Испытаний.",al={"what does sapta do when drunk","after earth sapta","что делает сапта когда выпить","после сапты земли"}}},fp="11,293,33.494.0,17.415.0,23.229.0,45.248.0,34.167.0,47.197.0,33.161.0,48.189.0"}
P.entries["quest:147"] = {n="Охота на человека",s="«Охота на человека» — задание Альянса, которое выдает маршал Дугхан в Златоземье: нужно устранить сборщика золота Братства Справедливости по прозвищу «Вымогатель». Действуя из захваченного Тыквенного поля Бреквеллов, этот лазутчик направляет похищенное золото из рудников Элвиннского леса прямо в казну Братства.",h="«Охота на человека» — задание Альянса, которое выдает маршал Дугхан в Златоземье: нужно устранить сборщика...",kw={"brackwell pumpkin patch","collector","defias","goldshire","manhunt","marshal dughan","ring","stonemasons guild","тыквенное поле бреквеллов","вымогатель","братство справедливости","златоземье","охота на человека","маршал дугхан","кольцо","гильдия каменщиков"},ang={["class:Rogue"]="Скрытная операция Вымогателя на тыквенном поле показывает, как разрастается сеть разбойников и карманников, пускающих корни по всему Элвиннскому лесу.",["faction:Alliance"]="Защита местных ресурсов Штормграда крайне важна: остановив Вымогателя, Альянс перекрывает незаконный поток королевского золота, предназначенного для мятежа прямо у порога столицы.",["race:Human"]="Возвращение кольца каменщика задевает больное место в недавней истории Штормграда, напоминая о жестоких трудовых спорах, расколовших королевство после восстановления столицы."},sec={{t="Правосудие на тыквенном поле",b="После того как у гноллов Элвиннского леса нашли расписание вывоза золота, маршал Дугхан отправляет искателей приключений на Тыквенное поле Бреквеллов. Некогда тихая усадьба захвачена бандитами Братства Справедливости и гноллами. Среди заросших лоз прячется Вымогатель — посредник, который присваивает королевскую руду и организует поставки для растущего мятежа."},{t="Печать мастера",b="Убив Вымогателя, искатели приключений забирают его кольцо и относят его маршалу Дугхану. К удивлению маршала, на кольце нет обычного знака преступников — на нем клеймо старой Гильдии каменщиков Штормграда. Эта находка намекает на неприятную правду: разбойники, терроризирующие Элвиннский лес, — не просто проходимцы, а бывшие мастера, озлобившиеся и ставшие изгоями после восстановления Штормграда."}},faq={{q="Где найти Вымогателя?",a="Вымогатель прячется на Тыквенном поле Бреквеллов на юго-востоке Элвиннского леса, к востоку от Виноградников Маклура и к северу от границы по реке.",al={"collector location","where is collector","collector spot","где вымогатель","местонахождение вымогателя","где найти вымогателя"}},{q="Почему Вымогатель крадет золото из рудников Элвиннского леса?",a="Он собирает контрабандную руду и деньги, вымогаемые у кобольдов из Рудника Подземных Глубин и Яшмовой шахты, чтобы финансировать тайные операции Братства Справедливости по всему королевству.",al={"why steal gold","defias mines","what is collector doing","зачем красть золото","рудники братства справедливости","что делает вымогатель"}},{q="Чем важно кольцо Вымогателя?",a="Кольцо принадлежало Гильдии каменщиков — мастерам, которые отстроили Штормград после Первой и Второй войны. Находка у лазутчика Братства Справедливости напрямую связывает разбойников с недовольными мастерами, которых обделил с оплатой Дом знати.",al={"collectors ring lore","stonemason ring","what does the ring mean","кольцо вымогателя","кольцо каменщиков","что значит кольцо"}},{q="Выясняет ли маршал Дугхан, кто стоит за Братством?",a="Не сразу. Маршал Дугхан узнает знак мастеров на кольце, но не понимает, почему у простого вора печатка гильдии мастеров, и потому общий заговор остается в Златоземье нерешенным вопросом.",al={"does dughan know","dughan reaction","marshal dughan Stonemasons","знает ли дугхан","реакция дугхана","маршал дугхан каменщики"}},{q="Кто отправляет вас в эту охоту на человека?",a="Маршал Дугхан, командир гарнизона в таверне Гордость Льва в Златоземье, выдает задание после того, как вы добудете расписание вывоза золота Братства Справедливости.",al={"who gives manhunt","quest giver manhunt","marshal dughan quest","кто выдает охоту на человека","персонаж, выдающий охоту на человека","задание маршала дугхана"}},{q="Что случилось с семьей Бреквеллов?",a="Тыквенное поле Бреквеллов пришло в упадок: владельцы покинули его, и там обосновались разбойники и бандиты Братства Справедливости, а также наступающие гноллы Речной Лапы, рыщущие по юго-восточным лесам.",al={"brackwell lore","who owns pumpkin patch","brackwell farm","бреквеллы","кому принадлежит тыквенное поле","ферма бреквеллов"}}},fp="7,280,28.376.0,17.413.1,31.158.0,55.176.0,49.268.1,61.217.1,30.149.0,38.183.0"}
P.entries["quest:1470"] = {n="Приоткрывая завесу",s="«Приоткрывая завесу» — вводное испытание чернокнижника, которое выдает Вения Мартанд в Могильнике. Оно проверяет решимость недавно восставшего чернокнижника: ему нужно собрать черепа у бездумных скелетов поблизости. Выполнив задание, новичок получает знания, необходимые для призыва и подчинения беса.",h="«Приоткрывая завесу» — вводное испытание чернокнижника, которое выдает Вения Мартанд в Могильнике.",kw={"deathknell","imp","piercing the veil","rattlecage skull","tirisfal glades","venya marthand","warlock","могильник","бес","приоткрывая завесу","череп гремящего скелета","тирисфальские леса","вения мартанд","чернокнижник"},ang={["class:Warlock"]="Этот обряд — ваш первый настоящий шаг в демонологию и основной урок: хаотическую магию нужно подчинять железной воле.",["race:Undead"]="Чернокнижники из числа Отрекшихся используют свою жуткую отрешенность от смертности, чтобы бесстрашно изучать хаотическую и темную магию в тени Могильника."},sec={{t="Первый шаг новичка",b="Недавно пробудившиеся чернокнижники из числа Отрекшихся начинают путь в Могильнике под руководством Вении Мартанд. Она учит, что истинная сила — не в грубой мощи, а в знании и точном владении хаотическими силами. Чтобы доказать, что у них достаточно сосредоточенности и способностей, чтобы приоткрыть завесу между мирами и покорять существ Пустоты, новичков отправляют добыть черепа беспокойных Гремящих скелетов, бродящих у заброшенной кузницы Могильника."},{t="Покорение Пустоты",b="Когда останки скелетов добыты, Вения считает посвященного готовым выйти за рамки простых темных заклинаний. Добытые материалы служат обрядом посвящения: они показывают, что новичок способен одолеть бездумную нежить и выдержать суровую реальность своего ремесла. В награду Вения передает обряды, нужные, чтобы подчинить беса воле призывателя, и предупреждает: несмотря на малый рост демона, его хитрость и огонь делают его опасным союзником."}},faq={{q="Кто выдает задание «Приоткрывая завесу»?",a="Задание выдает Вения Мартанд, учитель чернокнижников в склепе Могильника в Тирисфальских лесах.",al={"who starts piercing the veil","piercing the veil questgiver","venya marthand quest","кто начинает приоткрывая завесу","приоткрывая завесу выдает задание","задание вении мартанд"}},{q="Что нужно собрать, чтобы выполнить это задание?",a="Нужно собрать три черепа Гремящего скелета, которые достаются при уничтожении Гремящих скелетов, бродящих у разрушенной кузницы в Могильнике.",al={"piercing the veil objective","what do i collect for piercing the veil","rattlecage skulls","приоткрывая завесу цель","что собирать для приоткрывая завесу","черепа гремящих скелетов"}},{q="Зачем Вении Мартанд черепа скелетов?",a="Охота на бездумных скелетов проверяет самообладание, решимость и базовые магические умения новичка, прежде чем Вения доверит ему более опасные демонические обряды.",al={"why rattlecage skulls","purpose of skulls quest","зачем черепа скелетов","цель задания с черепами"}},{q="Какую силу или какого прислужника вы учитесь призывать?",a="Пройдя урок, чернокнижник готов призвать и подчинить беса — первого демонического спутника, которым учатся повелевать.",al={"piercing the veil reward spell","what demon do i get","imp summon quest","награда приоткрывая завесу","какого демона я получу","призыв беса задание"}},{q="Где находятся Гремящие скелеты?",a="Они бродят на окраинах Могильника, особенно вокруг разрушающейся заброшенной кузницы к северо-западу от главной поляны поселения.",al={"rattlecage skeleton location","where are the skeletons deathknell","abandoned smithy deathknell","где гремящие скелеты","где скелеты могильник","заброшенная кузница могильник"}},{q="Кто может взяться за это задание?",a="Взяться за него могут только чернокнижники из числа Отрекшихся, достигшие нужного уровня вводного обучения в Могильнике.",al={"who can take piercing the veil","can other classes do this","is this warlock only","кто может взять приоткрывая завесу","другие классы","только для чернокнижников"}}},fp="17,294,21.468.0,22.460.0,38.117.0,45.148.0,45.165.0,44.131.0,43.144.0,40.126.0"}
P.entries["quest:1471"] = {n="Оковы",s="«Связывание» — завершающий обряд для чернокнижников из числа Отрекшихся, желающих повелевать демоном Бездны. В Магическом квартале Подгорода Карендин Халгар требует от посвященных призвать существо Пустоты, победить его и навсегда подчинить.",h="«Связывание» — завершающий обряд для чернокнижников из числа Отрекшихся, желающих повелевать демоном Бездны.",kw={"carendin halgar","magic quarter","runes of summoning","subjugation","the binding","undercity","voidwalker","warlock quest","карендин халгар","магический квартал","руны призыва","подчинение","связывание","подгород","демон пустоты","задание чернокнижника"},ang={["class:Warlock"]="Этот обряд знаменует переход чернокнижника от мелких фокусов с бесами к настоящему господству над существами, способными выдерживать на поле боя огромный физический урон.",["race:Undead"]="Для Отрекшихся подчинение теневого существа — естественное продолжение их стойкости и отсутствия моральных ограничений в запретной магии."},sec={{t="Обряд подчинения",b="В отличие от мелких бесов, которых легко склонить к договору с темной магией, существа Пустоты презирают реальность и обладают огромной физической силой. Чтобы получить право призвать демона Пустоты, начинающий чернокнижник в Подгороде должен доказать полное превосходство над ним. В сумрачном убежище Магического квартала наставник из числа Отрекшихся Карендин Халгар дает таинственные руны, нужные, чтобы вырвать демона Пустоты из Круговерти Пустоты в материальный мир."},{t="Внутри круга",b="Обряд проходит в светящемся круге призыва, начертанном под помостом наставника. Когда руны активированы, свободный демон Пустоты появляется в ярости. Усмирить его — не вопрос переговоров: призыватель должен сломить существо чистой тайной силой и волей. Лишь когда существо полностью сокрушено, Карендин открывает истинную формулу призыва, навечно привязывающую сущность создания к чернокнижнику."}},faq={{q="Для чего нужен этот обряд?",a="Обряд проверяет способность начинающего чернокнижника подчинить существо Пустоты. Победив в бою свободного демона Пустоты, призыватель доказывает, что его воля достаточно сильна для власти над ним, и Карендин Халгар обучает его постоянному заклинанию призыва.",al={"why do the binding","what does the binding quest do","binding reward","зачем связывание","что дает задание связывание","награда за связывание"}},{q="Где проходит призыв?",a="Он проходит прямо в фиолетовом круге призыва, начертанном на полу под помостом Карендина Халгара в Магическом квартале Подгорода.",al={"where do i summon voidwalker","where is the summoning circle","circle of summoning undercity","где призвать демона пустоты","где круг призыва","круг призыва подгород"}},{q="Кто такой Карендин Халгар?",a="Карендин Халгар — главный учитель чернокнижников, живущий в Магическом квартале Подгорода; он руководит обучением и темными посвящениями недавно восставших Отрекшихся.",al={"who is halgar","carendin halgar lore","кто такой халгар","карендин халгар предыстория"}},{q="Нужно ли чернокнижникам побеждать каждого демона, которого они хотят призвать?",a="Чернокнижники должны утвердить власть над могущественными существами из иных измерений, прежде чем повелевать ими. Мелкие создания вроде бесов связаны простыми договорами и обрядами, а демоны Пустоты покоряются, лишь признав физическое и магическое превосходство.",al={"do warlocks always fight demons","why fight the voidwalker","всегда ли чернокнижники сражаются с демонами","зачем сражаться с демоном пустоты"}},{q="Что будет, если чернокнижнику не удастся усмирить демона Пустоты?",a="Свободный демон Пустоты безжалостно бьет и уничтожает всех поблизости. Как предупреждает Халгар, разочаровать его — ничто по сравнению с опасностью быть растерзанным неукрощенным существом в круге.",al={"what if i fail the binding","failure lore warlock","что если провалить связывание","провал чернокнижника"}},{q="Что такое демон Пустоты?",a="Демоны Пустоты — теневые существа из иных измерений, пришедшие из Пустоты. Они обладают огромной физической стойкостью и врожденным стремлением гасить живой свет и энергию, что делает их идеальными защитниками для практиков темной магии.",al={"what is a voidwalker","voidwalker lore","что такое демон пустоты","демон пустоты предыстория"}}},fp="11,234,21.440.0,17.447.0,35.262.0,36.154.0,23.182.0,59.255.0,57.218.0,21.246.0"}
P.entries["quest:1472"] = {n="Пожирательница душ",s="«Пожирательница душ» — начальный этап пути чернокнижника из числа Отрекшихся к призыву и подчинению суккуба. По указанию Карендина Халгара в Храме Проклятых в Подгороде практик должен поговорить с его помощником Годриком Фарсаном и узнать, как выманить такое существо из Круговерти Пустоты. Для обряда нужна неотразимая приманка: сердца чистых и любящих смертных.",h="«Пожирательница душ» — начальный этап пути чернокнижника из числа Отрекшихся к призыву и подчинению суккуба.",kw={"bait","carendin halgar","godrick farsan","hearts of the pure","succubus","temple of the damned","undercity","приманка","карендин халгар","годрик фарсан","чистые сердца","суккуб","храм проклятых","подгород"},ang={["class:Warlock"]="Подчинение суккуба — важная веха в обучении чернокнижника: оно показывает темное искусство использования врожденных пороков и аппетитов демона, чтобы поработить его.",["race:Undead"]="Наставники-чернокнижники из числа Отрекшихся в Храме Проклятых действуют без моральных ограничений и походя используют живую чистоту и преданность как расходуемые реагенты для ритуалов Пустоты."},sec={{t="Приманка для Пустоты",b="Карендин Халгар учит, что суккуба нельзя просто притянуть через порог по приказу — ее нужно соблазнить. Движимому ненасытной жаждой губить добродетель и поглощать суть смертных, демону нужна особая приманка. Стратегия чернокнижника состоит в том, чтобы воспользоваться этим единственным желанием и предложить в качестве приманки сердца по-настоящему добродетельных, любящих мужчин. Халгар направляет своих учеников к Годрику Фарсану, который знает, где добыть такую редкую добычу."},{t="Слепой помощник",b="Годрик Фарсан находится в глубине Храма Проклятых и помогает Карендину в практической подготовке к подчинению демонов. Хотя Фарсан потерял физическое зрение, он утверждает, что это дало ему глубокое внутреннее видение: он с поразительной ясностью воспринимает духовные течения и далекие души. Он помогает найти чистые сердца, необходимые, чтобы выманить демона."}},faq={{q="Для чего нужно это задание?",a="Это задание связывает первый призыв Карендина Халгара с практической охотой, необходимой для подчинения суккуба. Оно отправляет чернокнижника к Годрику Фарсану, который рассказывает о мрачных компонентах для обряда.",al={"why do devourer of souls","succubus quest undercity","warlock quest level 20","зачем пожирательница душ","задание суккуб подгород","задание чернокнижника 20 уровня"}},{q="Зачем для призыва суккуба нужны чистые сердца?",a="Суккуб живет за счет растления добра, искушения сердец смертных и поглощения добродетельных душ. Карендин Халгар объясняет, что без неотразимой приманки демон не может легко прорваться в этот мир, и потому незапятнанная преданность добрых мужчин — идеальная наживка.",al={"why hearts of the pure","succubus bait lore","зачем чистые сердца","приманка для суккуба"}},{q="Кто такой Годрик Фарсан?",a="Годрик Фарсан — служитель-чернокнижник из числа нежити, помогающий Карендину Халгару в Храме Проклятых. Хотя он слеп физически, его мистические чувства позволяют ему постигать духовные истины и находить подходящую добычу по всем Восточным королевствам.",al={"who is farsan","blind warlock assistant","кто такой фарсан","слепой помощник чернокнижника"}},{q="Где сдается это задание?",a="Задание сдается прямо в Храме Проклятых в Подгороде, в нескольких шагах от Карендина Халгара, где ждет Годрик Фарсан.",al={"where is godrick farsan","devourer of souls turn in","где годрик фарсан","пожирательница душ сдать задание"}},{q="Что идет после «Пожирательницы душ»?",a="Фарсан сразу выдает задание «Чистые сердца»: чернокнижник должен отправиться в Болотину и к Стене Седогрива в Серебряном бору, чтобы добыть сердца двух добродетельных смертных.",al={"next quest after devourer of souls","hearts of the pure next","следующее задание после пожирательницы душ","чистые сердца дальше"}},{q="Может ли этот обряд пройти представитель любой расы?",a="Хотя обряд проходит в Подгороде и наставники — Отрекшиеся, любой чернокнижник Орды, желающий подчинить суккуба через наставников Подгорода, может выполнить шаги обряда, которые дают Халгар и Фарсан.",al={"who can do devourer of souls","undead only warlock quest","кто может пожирательница душ","задание только для нежити"}}},fp="17,385,18.458.0,19.420.0,34.211.0,52.283.0,22.257.0,30.162.0,35.200.0,35.210.0"}
P.entries["quest:1473"] = {n="Создание Бездны",s="«Создание Бездны» — важный обряд посвящения для чернокнижников Отрекшихся: им поручено вернуть утраченный магический текст у Алого ордена. Чтобы узнать, как призвать и подчинить хаотичного демона Бездны, посвящаемый должен отправиться на запад от Тирисфальских лесов и забрать Гримуар Эгалина у враждебных фанатиков.",h="«Создание Бездны» — важный обряд посвящения для чернокнижников Отрекшихся: им поручено вернуть утраченный...",kw={"carendin halgar","egalin","egalins grimoire","perrine","scarlet crusade","temple of the damned","tirisfal glades","undercity","voidwalker","карендин халгар","эгалин","гримуар эгалина","перрин","алый орден","храм проклятых","тирисфальские леса","подгород","демон бездны"},ang={["class:Warlock"]="Это задание знаменует переход от возни с бесами к управлению мощными демонами тьмы на передовой, способными выдерживать огромный физический урон.",["faction:Horde"]="Темные искусства, которым обучают в Подгороде, строятся на строгой научной технике и превращают опасные силы иных миров в надежное оружие для пограничных войн Орды.",["race:Undead"]="Удар по Алому ордену ради возвращения темных знаний подчеркивает горькую борьбу между Отрекшимися и живыми фанатиками, занимающими руины Лордерона."},sec={{t="Наследие учителя",b="В темных альковах Храма Проклятых в Подгороде Карендин Халгар наблюдает за развитием молодых призывателей из числа Отрекшихся. Когда послушник достаточно искусен, чтобы владеть силой, превосходящей возможности мелких бесов, Халгар направляет его к подчинению существа, рожденного из чистой тьмы и хаоса, — демона Бездны. Отрекшиеся основывают свои призывы не на простом инстинкте, а на тщательных исследованиях Эгалина, прежнего наставника самого Халгара, который первым записал ритуалы, необходимые для подчинения этих чудовищных обитателей Бездны."},{t="Украденный гримуар",b="Овладеть войдвокером нельзя без Гримуара Эгалина, где описаны точные методы направления столь неустойчивой магии. Однако драгоценный том украл агент Алого ордена — фанатик по имени Перрин, стоящий в башне заставы на западе. Хотя Перрин и его крестоносцы, вероятно, считали гримуар лишь кощунственной контрабандой для конфискации и накопления, вернуть его необходимо, если Отрекшиеся хотят получить тайны ритуала до попытки разорвать завесу."}},faq={{q="Что такое Гримуар Эгалина?",a="Гримуар Эгалина — магическое руководство, написанное чернокнижником Эгалином, который обучал Карендина Халгара. В нем подробно описаны сложные приемы направления силы и заклинания, необходимые, чтобы прорвать завесу Бездны и призвать демона Бездны под полным контролем заклинателя.",al={"egalins grimoire","what is the book","who was egalin","гримуар эгалина","что за книга","кто такой эгалин"}},{q="Почему Алый орден украл книгу?",a="Алый орден считает всю демоническую магию и магию Тьмы порочной по своей природе. Агент по имени Перрин завладел гримуаром во время стычки или проникновения и спрятал его в западной сторожевой башне в Тирисфальских лесах, по всей видимости не подозревая о силе призыва, заключенной внутри.",al={"why did scarlet crusade take it","perrine grimoire","scarlet tower west","почему алый орден взял гримуар","перрин гримуар","алая башня на западе"}},{q="Кто такой Карендин Халгар?",a="Карендин Халгар — мастер-учитель чернокнижников, живущий в Храме Проклятых в Подгороде. Он наставляет начинающих чернокнижников Отрекшихся, учит их уважению к переменчивым космическим силам и осторожности, рожденной его собственными прошлыми ошибками при призыве.",al={"carendin halgar","warlock trainer undercity","temple of the damned trainer","карендин халгар","учитель чернокнижников подгород","учитель храм проклятых"}},{q="Что будет, если чернокнижник потеряет контроль над демоном Бездны?",a="Демоны Бездны — существа чистого хаоса и тьмы. Как предупреждает Карендин Халгар, если посвящаемый попытается призвать такого без безупречной дисциплины и воли к подчинению, существо яростно разорвет призывателя на части.",al={"can voidwalker kill you","voidwalker danger","summoning failure","может ли демон бездны убить","опасность демона бездны","неудачный призыв"}},{q="Что будет после возвращения гримуара?",a="Получив книгу, Халгар изучает текст, чтобы передать вам руны ритуала. Это сразу ведет к заданию «Связывание», где посвящаемый должен с помощью круга призыва вызвать демона Бездны и победить его в поединке, утвердив свое господство.",al={"what next after grimoire","next quest","binding ritual","что после гримуара","следующее задание","ритуал связывания"}},{q="Где находится застава Алого ордена?",a="Гримуар спрятан в сторожевой башне Алого ордена к западу, через Тирисфальские леса; ее охраняют воины ордена под командованием Перрина.",al={"where is perrine","scarlet tower location","where is the book","где перрин","расположение алой башни","где книга"}}},fp="20,302,18.549.0,19.515.0,26.244.0,43.285.0,23.242.0,56.210.0,41.253.1,45.154.0"}
P.entries["quest:1474"] = {n="Оковы",s="«Связывание» — последнее посвящение на пути чернокнижника Подгорода к призыву и подчинению суккуба. По указанию Карендина Халгара практик использует чистые сердца, чтобы вытянуть демона из Круговерти Пустоты в круг ритуала и подчинить его волю в бою.",h="«Связывание» — последнее посвящение на пути чернокнижника Подгорода к призыву и подчинению суккуба.",kw={"binding","carendin halgar","magic quarter","pure hearts","succubus","undercity","warlock","связывание","карендин халгар","магический квартал","чистые сердца","суккуб","подгород","чернокнижник"},ang={["class:Warlock"]="Этот обряд — важный шаг на вашем темном пути: он показывает вашу способность овладевать соблазнительными силами разума и подчинять своей воле хитрых созданий Пустоты.",["race:Undead"]="Чернокнижники Отрекшихся прагматично относятся к подчинению демонов и используют любые темные средства, нужные для выживания и господства в Лордероне."},sec={{t="Испытание воли",b="В темных альковах Магического квартала чернокнижники Отрекшихся оттачивают власть над демонами. Призыв суккуба считается важнейшим обрядом посвящения. В отличие от грубой силы демона Бездны или мелкой злобы беса, суккуб владеет соблазнительными и умственными чарами, способными пленить заклинателя. Карендин Халгар требует от посвящаемых доказать, что их разум и магия непоколебимы, прежде чем доверить им вечную власть над таким существом."},{t="Подчинение в круге",b="Используя добытые чистые сердца невинных душ из Болотины и Серебряного бора, чернокнижник открывает проход в Круговерть Пустоты. Призванный в круг связывания демон тут же нападает, пытаясь одолеть или околдовать заклинателя. Лишь разрушив его телесную форму и отправив его суть обратно в Бездну, чернокнижник утверждает полное господство и получает знание, нужное, чтобы призывать демона по своей воле."}},faq={{q="Для чего нужно это задание?",a="Этот ритуал позволяет чернокнижникам Отрекшихся доказать власть над высшими демонами. Призвав и победив суккуба в Магическом квартале, чернокнижник доказывает, что чары демона над ним не властны, и получает заклинание, позволяющее призывать суккуба и повелевать им в бою.",al={"why do the binding","what does the binding reward","what is this quest for","зачем связывание","награда за связывание","для чего это задание"}},{q="Кто такой Карендин Халгар?",a="Карендин Халгар — учитель чернокнижников в Магическом квартале Подгорода. Он руководит обучением и испытаниями заклинателей Отрекшихся, проверяя их стойкость разума и темные искусства, прежде чем доверить им более опасные ритуалы призыва.",al={"who gives the binding","carendin halgar lore","кто дает связывание","карендин халгар предания"}},{q="Почему для призыва демона нужны чистые сердца?",a="Демоны-суккубы питаются эмоциями, чистотой и порчей. Чистые сердца, добытые в прежних заданиях, служат неотразимой метафизической приманкой и заставляют демона явиться в мир смертных через круг призыва.",al={"why pure hearts","hearts of the pure purpose","зачем чистые сердца","назначение чистых сердец"}},{q="Где происходит призыв?",a="Призыв происходит прямо в Магическом квартале Подгорода, в особом круге ритуала рядом с Карендином Халгаром и наставниками чернокнижников.",al={"where do i summon the succubus","undercity summoning circle location","где призвать суккуба","круг призыва в подгороде"}},{q="Почему суккуба нужно убить?",a="Чернокнижники не договариваются со своими слугами — они их подчиняют. Разрушив облик демона в круге призыва, чернокнижник склоняет его дух перед своим господством, и тот возвращается покорным рабом, а не хозяином.",al={"why fight the succubus","why kill summoned succubus","зачем сражаться с суккубом","зачем убивать суккуба"}},{q="Опасны ли суккубы для чернокнижников Подгорода?",a="Да. Хотя Отрекшиеся весьма устойчивы к страху и сну, Карендин Халгар прямо предупреждает, что чары суккуба подчинили многие сильные умы. Неосторожность во время ритуала ведет к смерти или порабощению.",al={"can a succubus charm undead","succubus danger","может ли суккуб очаровать нежить","опасность суккуба"}}},fp="11,266,14.469.0,25.459.1,34.250.0,23.245.0,48.246.0,36.155.0,39.237.0,44.240.0"}
P.entries["quest:1476"] = {n="Чистые сердца",s="«Чистые сердца» — зловещее испытание чернокнижников, которое выдает в Подгороде Годрик Фарсан от имени Карендина Халгара. Чтобы приготовить ритуальную приманку для связывания суккуба, начинающий призыватель должен выследить и убить двух редкостно праведных людей. Их чистые сердца — неотразимый соблазн для демонической искусительницы, ожидающей призыва.",h="«Чистые сердца» — зловещее испытание чернокнижников, которое выдает в Подгороде Годрик Фарсан от имени...",kw={"carendin halgar","comar villard","dalin forgewright","godrick farsan","greymane wall","hearts of the pure","succubus","temple of the damned","thandol span","undercity","карендин халгар","комер виллард","далин искусник","годрик фарсан","стена седогрива","чистые сердца","суккуб","храм проклятых","мост тандола","подгород"},ang={["class:Warlock"]="Этот обряд учит, что чернокнижник должен использовать как оружие не только страдание и страх, но и само благородство других, чтобы подчинить демонов своей воле.",["faction:Alliance"]="Жертвы — трагические фигуры среди Альянса и остатков людей: один охраняет голодающих беженцев, которым закрыл путь Гилнеас, другой тщетно ищет пропавшую супругу в болотах.",["race:Undead"]="Задание показывает жуткий взгляд Отрекшихся, которые походя видят в уцелевших жителях Лордерона и их неугасшей добродетели удобный скот для ритуальной бойни."},sec={{t="Приманка для демона",b="Для связывания суккуба нужно понимать, что искушение обоюдоостро. Хотя сирены Пустоты охотятся на желания и гибель, ничто не влечет их из Круговерти Пустоты так, как незапятнанная добродетель, созревшая для порчи. В Храме Проклятых мастер-призыватель Карендин Халгар поручает подготовку Годрику Фарсану, который прочесывает земли людей в поисках душ с нетронутой и несломленной добротой."},{t="Добыча",b="Фарсан называет двух образцов добродетели. Первый — Далин Искусник, честный человек, заботящийся об отчаявшихся беженцах Лордерона, которым закрыт путь в убежище за запертой Стеной Седогрива на юге Серебряного бора. Второй — Комер Виллард, верный муж, неустанно ищущий в опасных болотах Болотины хоть какие-то следы своей пропавшей жены. Для чернокнижника Отрекшихся их преданность, сострадание и верность делают их лучшими жертвами."},{t="Взгляд Отрекшихся",b="Чтобы выполнить охоту, призывателю предстоит пройти через опасные земли Альянса и дикие места и убить обоих. Когда окровавленная добыча доставлена в Храм Проклятых, Карендин Халгар с мрачной иронией замечает, что сердце доброго человека ничем не отличается от остатков любого другого трупа. Но в темном искусстве демонологии духовная чистота, пропитавшая их плоть, достаточно сильна, чтобы заманить суккуба в плен."}},faq={{q="Зачем чернокнижникам чистые сердца для призыва суккуба?",a="Суккуб питается развращением невинности и добродетели смертных. Чтобы заманить ее через Пустоту и поймать в круг связывания, Карендину Халгару нужна приманка, которой она не сможет противиться. Сердца по-настоящему чистых и бескорыстных людей дают такой неотразимый духовный соблазн.",al={"why pure hearts","succubus bait lore","why kill dalin and comar","зачем чистые сердца","приманка для суккуба","зачем убивать далина и комера"}},{q="Кто такой Далин Искусник?",a="Далин Искусник — честный человек, который патрулирует верхом у закрытых ворот Стены Седогрива на юге Серебряного бора. Он посвятил жизнь заботе о перемещенных беженцах Лордерона и их защите: королевство Гилнеас отвергло их и закрыло перед ними двери.",al={"dalin forgewright lore","who is dalin","greymane wall guy","далин искусник","кто такой далин","человек у стены седогрива"}},{q="Кто такой Комер Виллард?",a="Комер Виллард — преданный человек-скиталец, который ищет жену на северной дороге Болотины, чуть южнее Моста Тандола. В отличие от обычных путников, им движут лишь горе и непоколебимая любовь, и он отказывается прекращать поиски пропавшей жены.",al={"comar villard lore","who is comar","wetlands human heart","комер виллард","кто такой комер","сердце человека в болотине"}},{q="Куда ведет эта цепочка заданий?",a="Доставив два сердца Карендину Халгару, вы позволяете ему подготовить круг призыва в Храме Проклятых. Это сразу ведет к заданию «Связывание», где чернокнижник призывает и подчиняет суккуба, чтобы тот служил ему постоянно.",al={"what comes next","after hearts of the pure","succubus quest reward","что дальше","после чистых сердец","награда за задание суккуба"}},{q="Кто выдает это задание?",a="Задание выдает Годрик Фарсан, помощник в Храме Проклятых в Магическом квартале Подгорода. Он создает магические иллюзии Далина и Комера, чтобы показать чернокнижнику, на кого охотиться.",al={"who starts hearts of the pure","godrick farsan quest","кто начинает чистые сердца","годрик фарсан задание"}},{q="Почему Карендин Халгар пренебрежительно относится к виду сердец?",a="По завершении задания Карендин с мрачной отстраненностью замечает, что сердце добродетельного человека выглядит почти так же, как любой другой кусок плоти. Для него, нежити и практика темных искусств, телесная нравственность значит мало, кроме пользы как магического реагента.",al={"carendin dialogue","heart appearance","слова карендина","вид сердец"}}},fp="18,365,16.415.0,10.449.0,22.470.1,54.268.0,25.283.0,21.250.0,33.240.1,21.215.0,62.282.0"}
P.entries["quest:1478"] = {n="Призыв Халгара",s="Призыв Халгара — официальное распоряжение, которое получают восходящие чернокнижники Отрекшихся, достигшие критического порога в своем темном искусстве. Мастер Карендин Халгар требует их присутствия в Магическом квартале Подгорода, чтобы начать суровое углубленное обучение. Ответ на его зов открывает путь к призыву и подчинению опасных существ из Пустоты.",h="Призыв Халгара — официальное распоряжение, которое получают восходящие чернокнижники Отрекшихся, достигшие...",kw={"ageron kargal","carendin halgar","halgar's summons","magic quarter","temple of the damned","undercity","voidwalker","warlock","агерон каргал","карендин халгар","призыв халгара","магический квартал","храм проклятых","подгород","демон бездны","чернокнижник"},ang={["class:Warlock"]="Этот обряд посвящения связывает начальное обучение с настоящим порабощением демонов и ставит вас под пристальное внимание главного мастера темных искусств Подгорода.",["race:Undead"]="Чернокнижники Отрекшихся преследуют тьму и Скверну с беспощадным, ничем не сдерживаемым честолюбием, а святилище Халгара служит примером их практичного пренебрежения осторожностью живых."},sec={{t="Уведомление мастера",b="Когда чернокнижник, действующий в окрестностях Брилла или в глуши Тирисфаля, демонстрирует достаточный контроль над основными силами Скверны, весть об этом доходит до глубоких подземных залов Подгорода. Старшие мастера, такие как Агерон Каргал, служат искателями талантов и передают уведомления тем, кто проявляет подлинные способности. Получить призыв от Карендина Халгара — редкая привилегия и в то же время опасное дело: это означает, что простых бесов и мелких проклятий для обучения чернокнижника уже недостаточно."},{t="Магический квартал",b="Халгар руководит обрядами чернокнижников из сумрачных глубин Магического квартала, неподалеку от зловещего алтаря — Храма Проклятых. Темные чародеи Отрекшихся не знают брезгливых моральных ограничений живых, но даже они требуют строгой дисциплины при обращении к призыву из иных миров. Халгар не терпит колебаний и сентиментальности: его вызов предполагает мгновенное повиновение и полную готовность встретить враждебные ужасы Круговерти Пустоты."}},faq={{q="Кто такой Карендин Халгар?",a="Карендин Халгар — главный учитель чернокнижников, обитающий в Магическом квартале Подгорода. Он следит за темным развитием призывателей Отрекшихся и проверяет их решимость, прежде чем научить подчинять могущественных существ Пустоты.",al={"carendin halgar","master halgar","who is halgar","карендин халгар","мастер халгар","кто такой халгар"}},{q="Кто направляет меня к Халгару?",a="Агерон Каргал, опытный учитель чернокнижников из Брилла, посылает вас к нему, получив весть, что мастер Халгар лично заинтересовался вашим развитием.",al={"who gives halgars summons","ageron kargal","who gives quest","кто выдает призыв халгара","агерон каргал","кто выдает задание"}},{q="Где найти Карендина Халгара в Подгороде?",a="Халгар находится в Магическом квартале Подгорода, возле темного возвышения — Храма Проклятых.",al={"halgar location","where is halgar","magic quarter halgar","где халгар","местонахождение халгара","магический квартал халгар"}},{q="Почему этот вызов важен?",a="Вызов отмечает ваш переход от простейших заклинаний к опасному подчинению демонов и открывает испытания, необходимые, чтобы подчинить себе демона Бездны.",al={"why do i need this quest","quest purpose","what does halgars summons lead to","зачем нужно это задание","цель задания","к чему ведет призыв халгара"}},{q="Готов ли Халгар учить любого?",a="Халгар уделяет внимание лишь многообещающим чернокнижникам. Он не тратит время на пустые любезности и требует, чтобы каждый приведенный к нему ученик уже умел обращаться с изменчивыми искусствами Скверны.",al={"can anyone talk to halgar","halgar requirements","может ли любой говорить с халгаром","требования халгара"}},{q="Что происходит после доклада Халгару?",a="Когда вы докладываете Халгару, он сразу проверяет ваши магические способности и поручает добыть компоненты, нужные для призыва и подчинения потустороннего теневого слуги.",al={"what comes next","after halgars summons","что дальше","после призыва халгара"}}},fp="16,349,17.484.0,17.481.0,23.229.0,25.171.0,46.129.0,30.181.0,34.208.0,39.177.0"}
P.entries["quest:1483"] = {n="Зиз Физзикс",s="Это задание отправляет путников Орды проведать Зиза Физзикса, недовольного инженера-гоблина на западном гребне Утеса Ветрорезов. Обидевшись, что Торговая Компания наняла вместо него инженера-гнома, Зиз перешел в Союз механиков под требовательное начало Пароклапана.",h="Это задание отправляет путников Орды проведать Зиза Физзикса, недовольного инженера-гоблина на западном...",kw={"gerenzo wrenchwhistle","sputtervalve","stonetalon","tinkers union","venture company","windshear crag","ziz fizziks","геренцо терминатрикс","пароклапан","когтистые горы","союз механиков","торговая компания","утес ветрорезов","зиз физзикс"},ang={["faction:Horde"]="Искатели приключений Орды в Когтистых горах часто помогают агентам Союза механиков, таким как Пароклапан и Зиз, подрывать господство Торговой Компании на Утесе Ветрорезов.",["profession:Engineering"]="Ожесточенная вражда Зиза и Геренцо прекрасно отражает давнее, бурное соперничество гоблинской и гномьей инженерных философий."},sec={{t="Вопрос профессиональной гордости",b="Торговая Компания держится на безжалостной эксплуатации и механических новинках, но для Зиза Физзикса она перешла черту, наняв инженера-гнома Геренцо Терминатрикса. Глубоко оскорбленный необходимостью работать бок о бок с соперником-гномом, Зиз тут же стал искать выход. Он обратился к Пароклапану, представителю Союза механиков, умоляя о переводе подальше от надзора Геренцо."},{t="Из огня да в Сковороду",b="Новая должность в Союзе механиков не принесла Зизу легкой жизни, на которую он рассчитывал. Оказавшись на западном краю Утеса Ветрорезов, он быстро понял, что Пароклапан такой же погонщик, как любой надсмотрщик Торговой Компании. И все же Зиз считает тяжелый труд под началом требовательного гоблина куда предпочтительнее, чем делить инженерную мастерскую с гномом."}},faq={{q="Кто такой Зиз Физзикс?",a="Зиз Физзикс — инженер-гоблин, прежде работавший на Торговую Компанию в Когтистых горах. Он перешел в Союз механиков после того, как бывшие работодатели наняли инженера-гнома.",al={"who is ziz","ziz fizziks npc","about ziz fizziks","кто такой зиз","зиз физзикс","о зизе физзиксе"}},{q="Почему Зиз Физзикс ушел из Торговой Компании?",a="Он ушел в знак протеста после того, как Торговая Компания наняла инженера-гнома Геренцо Терминатрикса. Отказываясь работать бок о бок с соперником-гномом, Зиз упросил Пароклапана о новой работе.",al={"why did ziz quit","why leave venture co","ziz venture co","почему зиз уволился","почему ушел из торговой компании","зиз торговая компания"}},{q="Где найти Зиза Физзикса?",a="Он находится на западном краю Утеса Ветрорезов в Когтистых горах, откуда видны лесозаготовки и раскопки Торговой Компании.",al={"ziz fizziks location","where is ziz","find ziz fizziks","где зиз физзикс","где зиз","найти зиза физзикса"}},{q="Кто такой Пароклапан?",a="Пароклапан — гоблин-агент Союза механиков, переманивающий опытных инженеров из Торговой Компании и ставящий их на конкурирующие проекты.",al={"who is sputtervalve","sputtervalve role","кто такой пароклапан","роль пароклапана"}},{q="Кто такой Геренцо Терминатрикс?",a="Геренцо — инженер-гном, которого Торговая Компания привела на Утес Ветрорезов; это назначение возмутило Зиза и породило ожесточенное профессиональное соперничество.",al={"gerenzo wrenchwhistle","who is the gnome engineer","геренцо терминатрикс","кто такой инженер-гном"}},{q="Что такое Союз механиков?",a="Союз механиков — устоявшееся торговое объединение гоблинов-инженеров. Он активно соперничает с такими конкурентами, как Торговая Компания, и при любой возможности нанимает или возвращает лучшие таланты.",al={"tinkers union","goblin tinkers union","союз механиков","гоблинский союз механиков"}}},fp="11,281,30.405.0,21.383.0,19.190.0,46.185.0,31.150.0,20.176.0,29.153.0,27.186.0"}
P.entries["quest:1485"] = {n="Злобные фамильяры",s="В засушливой Долине Испытаний учитель чернокнижников Рузан поручает начинающим адептам темных искусств доказать свою стойкость в схватке со злобными фамильярами. Чтобы получить знания о призыве демонов, посвящаемые должны сразиться с этими бесами и принести их отрубленные головы. Это скромный, но опасный первый шаг к овладению силой Скверны под наблюдением Орды.",h="В засушливой Долине Испытаний учитель чернокнижников Рузан поручает начинающим адептам темных искусств...",kw={"burning blade coven","durotar","imp","ruzan","the den","valley of trials","vile familiars","warlock","грот пылающего клинка","дуротар","бес","рузан","логово","долина испытаний","злобные фамильяры","чернокнижник"},ang={["class:Warlock"]="Это испытание — ваш первый обряд посвящения в чернокнижники: вы доказываете, что можете укротить демонический огонь, прежде чем провести ритуал призыва собственного беса.",["faction:Horde"]="Хотя Орда позволяет чернокнижникам обучаться в Дуротаре, их темные искусства строго ограничены уединенными местами вроде Логова.",["race:Orc"]="Чернокнижникам-оркам приходится каждый день сталкиваться с темным прошлым своего народа, доказывая самоконтроль и верность в обществе, помнящем ужасы порчи Скверной."},sec={{t="Шаткое место в Орде",b="Чернокнижники занимают в новой Орде Тралла шаткое положение. Наследие демонической порчи и кровавых договоров, некогда погубивших народ орков, оставило глубокие шрамы и стойкое недоверие. Хотя в Дуротаре владеющих магией Скверны терпят, их не любят и не принимают широко. Многие выбирают уединенную жизнь в тенистых уголках вроде Логова, практикуя свое искусство вдали от чужих глаз и обучая редких посвященных, осмелившихся пойти этим путем."},{t="Испытание мастерства",b="Прежде чем доверить ученику опасные обряды, необходимые, чтобы подчинить беса, Рузан требует доказательств превосходства. Возле пещеры к северо-востоку от Логова таятся злобные фамильяры и мечут огненные стрелы в каждого, кто подойдет. Убивая этих младших демонов и принося их головы, посвященный доказывает, что может одолеть огненных противников, которыми собирается повелевать, и что его не поглотит сама магия, которой он хочет повелевать."}},faq={{q="Почему Рузан посылает чернокнижников сражаться со злобными фамильярами?",a="Рузан требует, чтобы посвящаемые сразились со злобными фамильярами и поняли огненную природу и опасность бесов, прежде чем пытаться призвать одного из них. Поскольку чернокнижников мало и им не доверяют, он отказывается рисковать жизнью ученика и не учит призыву демонов, пока тот не докажет, что способен одолеть таких существ в прямом бою.",al={"why kill vile familiars","ruzan test","imp trial","зачем убивать злобных фамильяров","испытание рузана","испытание беса"}},{q="Где найти злобных фамильяров?",a="Они собираются вокруг пещеры и внутри нее, к северо-востоку от Логова в Долине Испытаний, за кабанами и скорпидами. Эта пещера служит лагерем зловещему Гроту Пылающего Клинка.",al={"vile familiar location","where are familiars","ruzan cave","где злобные фамильяры","где фамильяры","пещера рузана"}},{q="Как Орда относится к чернокнижникам в Дуротаре?",a="К чернокнижникам по всей Орде относятся с глубоким подозрением и недоверием из-за демонического прошлого, некогда развратившего народ орков. Хотя правительство Тралла терпит их присутствие и признает их боевую пользу, их держат на расстоянии, и многие живут в одиночестве.",al={"are warlocks hated","horde warlock lore","why distrust warlocks","ненавидят ли чернокнижников","предания об орде и чернокнижниках","почему не доверяют чернокнижникам"}},{q="Какую награду дает это испытание?",a="Убив существ и вернув Рузану их отрубленные головы, вы доказываете, что обладаете дисциплиной и силой, нужными для власти над демонами, и сразу переходите к обучению призыву беса.",al={"what do i learn","quest reward ruzan","imp spell","чему я научусь","награда рузана","заклинание беса"}},{q="Настоящие ли демоны злобные фамильяры?",a="Да, злобные фамильяры — мелкие демонические бесы, связанные с магией Скверны. Хотя они малы ростом, это грозные противники, способные метать во врагов огненные шары.",al={"what are vile familiars","are familiars imps","familiar demon type","что такое злобные фамильяры","фамильяры это бесы","тип демона фамильяр"}},{q="Кто такой Рузан?",a="Рузан — орк, учитель чернокнижников, находящийся в Логове в Долине Испытаний. Он учит новых чернокнижников-орков и троллей безопасно использовать энергии Скверны и управлять призванными слугами.",al={"ruzan","who is ruzan","valley of trials warlock","рузан","кто такой рузан","чернокнижник долина испытаний"}}},fp="14,398,31.472.0,20.441.0,53.326.0,35.202.0,44.315.0,45.197.0,33.174.0,13.190.0"}
P.entries["quest:1486"] = {n="Шкуры загадочных существ",s="«Шкуры загадочных существ» — задание, которое выдает Налпак, ученик Наралекса, живущий над входом в Пещеры Стенаний. Пока Наралекс заточен в искаженном кошмаре, Налпак стремится извлечь пользу из мутировавших зверей, порожденных под Степями. Собирая шкуры этих искаженных хищников, он надеется применить их странные, потусторонние свойства на практике.",h="«Шкуры загадочных существ» — задание, которое выдает Налпак, ученик Наралекса, живущий над входом в Пещеры...",kw={"barrens","cenarion circle","deviate","deviate hides","emerald nightmare","leatherworking","nalpak","naralex","wailing caverns","степи","круг кенария","скверна","шкуры загадочных существ","изумрудный кошмар","кожевничество","налпак","наралекс","пещеры стенаний"},ang={["class:Druid"]="Лагерь Налпака — мрачный дозор Круга Кенария над начинанием, пошедшим ужасно не так, и потому сдерживание мутаций пещер для собратьев-друидов — личное дело.",["profession:Herbalism"]="Ненормальный рост, питающий искаженных зверей, напрямую связан с оскверненной флорой и подземными источниками, пронизывающими сеть пещер."},sec={{t="Воплощенная порча",b="Когда ночной эльф-друид Наралекс попытался задействовать подземные источники под Степями, чтобы вернуть жизнь засушливым равнинам, его разум погрузился в ужасный кошмар. Это мрачное видение просочилось в реальность и превратило местных животных Пещер Стенаний в свирепых искаженных тварей. Ящеры-хищники, кроколиски, гадюки и шаркающие чудовища стали уродливыми и агрессивными под действием изумрудной порчи, исходившей от их спящего повелителя."},{t="Практичный друид",b="Налпак, расположившийся на скале над входом в пещеру, наблюдает за бедствием со смесью страха и практического любопытства. Хотя он признает искаженных существ злобными и противоестественными, он полагает, что их изменившиеся тела могут дать уникальные материалы. В особенности их прочные, искривленные шкуры обладают стойкостью, полезной для опытных кожевников: плоды трагического кошмара можно превратить в надежное снаряжение."}},faq={{q="Где найти Налпака?",a="Налпак и другие ученики разбили небольшой лагерь высоко на скале, похожей на череп, над входом в Пещеры Стенаний. Не заходите прямо в главный туннель: поднимитесь по склонам горы позади входа и осторожно спуститесь на верхний уступ в «глазнице», с которого виден оазис.",al={"nalpak location","where is nalpak","how to find nalpak","quest giver deviate hides","налпак где найти","где налпак","как найти налпака","выдающий задание шкуры загадочных существ"}},{q="Что такое искаженные существа?",a="Искаженные существа — местные звери, преобразившиеся под действием Изумрудного Кошмара, вырвавшегося из спящего разума Наралекса. Ящеры-хищники, змеи, кроколиски и ветряные змеи Степей превратились в более темные, свирепые формы со странными магическими свойствами и пятнистыми, неестественными шкурами.",al={"what are deviates","deviate beasts","why are animals mutated in wailing caverns","кто такие искаженные","искаженные звери","почему животные мутировали в пещерах стенаний"}},{q="Зачем Налпаку эти шкуры?",a="Налпак понимает, что хотя звери рождены злой порчей, их шкуры обладают необычной, потусторонней прочностью. Он считает, что кожевники, изучая и обрабатывая шкуры, смогут превратить скверну кошмара в прочное снаряжение.",al={"why deviate hides","what does nalpak want hides for","purpose of deviate hides","зачем шкуры загадочных существ","для чего налпаку шкуры","назначение шкур"}},{q="Могут ли шкуры выпадать из любых искаженных существ?",a="Эти шкуры носят мутировавшие звери, бродящие по туннелям и внутри Пещер Стенаний. Охотники и кожевники часто обнаруживают, что снятие шкур со зверей дает дополнительные шкуры сверх тех, что можно просто подобрать с их тел.",al={"which mobs drop deviate hides","who drops deviate hide","deviate hide farm","с кого падают шкуры загадочных существ","кто дает шкуры","добыча шкур"}},{q="Налпак на стороне Орды или Альянса?",a="Налпак — ученик Наралекса и член Круга Кенария. Он сохраняет нейтралитет и примет помощь любого способного искателя приключений, будь то из Альянса или из Орды, у кого хватит храбрости войти в оскверненные пещеры.",al={"is nalpak horde","is deviate hides alliance","can alliance do deviate hides","налпак орда","шкуры загадочных существ альянс","может ли альянс взять задание"}},{q="Что случилось с Наралексом?",a="Наралекс стремился пробудить подземные источники Степей, связав свое сознание с Изумрудным Сном. Но его сон захватил Кошмар, превратив систему пещер в рассадник ужасов, а сам он остался в коме в глубине пещер.",al={"who is naralex","naralex nightmare","what happened to the druid in wailing caverns","кто такой наралекс","кошмар наралекса","что случилось с друидом в пещерах стенаний"}}},fp="13,382,24.451.0,17.451.0,24.331.0,27.292.0,33.244.0,40.238.0,49.212.0,25.281.0"}
P.entries["quest:1487"] = {n="Искоренение Скверны",s="«Искоренение Скверны» — задание, которое выдает ночной эльф-друид Эбру над входом в Пещеры Стенаний. Пока другие ученики стараются пробудить своего спящего предводителя, Эбру просит искателей приключений очистить пещеры от мутировавших зверей, порожденных его искаженным видением. Избавление подземного оазиса от этих ужасов — важный шаг к тому, чтобы остановить порчу, угрожающую Степям.",h="«Искоренение Скверны» — задание, которое выдает ночной эльф-друид Эбру над входом в Пещеры Стенаний.",kw={"barrens","deviate dreadfang","deviate eradication","deviate ravager","deviate shambler","deviate viper","ebru","naralex","wailing caverns","степи","искаженный ужасный клыкастик","искоренение скверны","искаженный разоритель","искаженный шаркун","искаженная гадюка","эбру","наралекс","пещеры стенаний"},ang={["class:Druid"]="Искаженная экосистема пещер служит мрачным предостережением о том, что бывает, когда единение с Изумрудным Сном оборачивается бедой.",["faction:Horde"]="Поскольку Пещеры Стенаний лежат в самом сердце центральных равнин Калимдора, истребление этих свирепых хищников жизненно важно для защиты ближайших поселений, таких как Перекресток.",["race:NightElf"]="Видеть, как благородное стремление Наралекса обернулось порожденным кошмаром ужасом, — тяжкое бремя для странников-кальдораев, которые чувствуют долг помочь своим застрявшим сородичам."},sec={{t="Мечта, пошедшая ужасно не так",b="Ночной эльф-друид Наралекс привел своих последователей к подземным источникам Степей с амбициозной целью: обратиться к Изумрудному Сну, чтобы превратить иссохшие равнины в цветущие леса. Вместо этого Наралекс оказался в ловушке Сна, и его дрему исказил мучительный кошмар. Сила, хлынувшая по пещерам, не исцелила землю, а превратила местных животных и растения в чудовищных, агрессивных мутантов — искаженных зверей."},{t="Оборона Эбру",b="Эбру и горстка уцелевших учеников Наралекса, расположившись в пещере на скале над входом, в отчаянии наблюдают, как их становится все меньше. Пока одни посвящают силы пробуждению павшего наставника, Эбру видит неотложную угрозу. Если ничего не делать, быстро плодящиеся искаженные гадюки, шаркуны, разорители и ужасные клыкастики выплеснутся в Степи. Поэтому Эбру нанимает проходящих искателей приключений, чтобы они спустились в глубокие туннели и истребили уродливых чудовищ у самого источника."}},faq={{q="Где найти Эбру, чтобы начать это задание?",a="Эбру вместе с несколькими другими учениками Наралекса находится в укромной пещере высоко над главным входом в Пещеры Стенаний, внутри того, что напоминает правую глазницу скалы в форме черепа. Чтобы добраться до нее, обычно нужно обойти горный хребет и осторожно спуститься на верхний уступ.",al={"ebru location","where is ebru","how to get to ebru","wailing caverns eye cave","эбру где найти","где эбру","как добраться до эбру","пещера-глаз пещер стенаний"}},{q="Из-за чего звери стали искаженными?",a="Существ изменила темная энергия, просочившаяся из Изумрудного Сна. Когда друид Наралекс связал свое сознание с подземными источниками, чтобы возродить Степи, его разум захватил кошмар, и восстанавливающая энергия превратилась в разрушительную силу, мутирующую местных животных в искаженных чудовищ.",al={"why are they deviate","deviate beasts origin","what corrupted the animals in wc","почему они искаженные","происхождение искаженных зверей","что исказило животных в пещерах стенаний"}},{q="Кто такие ученики Наралекса?",a="Ученики Наралекса — круг друидов, сопровождавших Наралекса в Пещеры Стенаний, чтобы помочь возродить Степи. После его пленения в Кошмаре многие одичали или обезумели, остались лишь немногие здравомыслящие ученики, пытающиеся исправить беду.",al={"disciples of naralex","naralex followers","who are the druids in wailing caverns","ученики наралекса","последователи наралекса","кто такие друиды в пещерах стенаний"}},{q="Могут ли это задание взять и Альянс, и Орда?",a="Да. Эбру и ее спутники — нейтральные друиды, заботящиеся о сохранении природы и сдерживании Кошмара. Они принимают помощь способных героев как Орды, так и Альянса.",al={"deviate eradication alliance or horde","is deviate eradication neutral","искоренение скверны альянс или орда","нейтральное ли искоренение скверны"}},{q="Каких существ нужно убить для Эбру?",a="Эбру поручает вам выследить в глубине пещер четыре вида оскверненных тварей: искаженных разорителей, искаженных гадюк, искаженных шаркунов и искаженных ужасных клыкастиков — по семь каждого.",al={"deviate eradication mobs","deviate eradication targets","which deviate to kill","искоренение скверны цели","искоренение скверны монстры","каких искаженных убивать"}},{q="Пробудит ли выполнение этого задания Наралекса?",a="Нет. Поручение Эбру сводится к борьбе с вредителями и сокращению ущерба путем уничтожения опасных зверей. Чтобы пробудить Наралекса, нужно провести ритуал в его святилище в сердце пещеры.",al={"does this wake naralex","how to wake naralex","пробудит ли это наралекса","как разбудить наралекса"}}},fp="19,393,27.477.0,12.537.0,41.337.0,41.324.0,33.299.0,44.210.0,44.194.0,40.219.0"}
P.entries["quest:1489"] = {n="Хамуул Рунический Тотем",s="Это задание отправляет искателей приключений из Орды от цветущих, но неспокойных оазисов Степей на высоты Громового Утеса. Тонга Рунический Тотем подозревает глубокую духовную порчу в Пещерах Стенаний и посылает вас за советом к верховному друиду Хамуулу Руническому Тотему.",h="Это задание отправляет искателей приключений из Орды от цветущих, но неспокойных оазисов Степей на высоты...",kw={"elder rise","hamuul runetotem","oases","taint","the barrens","thunder bluff","tonga runetotem","wailing caverns","вершина старейшин","хамуул рунический тотем","оазисы","порча","степи","громовой утес","тонга рунический тотем","пещеры стенаний"},ang={["class:Druid"]="Для друидов-таурен явиться к верховному друиду Хамуулу Руническому Тотему — паломничество к наставнику, который заложил основы современного друидизма таурен по учению Малфуриона Ярость Бури.",["faction:Horde"]="Поскольку Степи служат перекрестком молодой Орды, расследование распространяющейся порчи защищает линии снабжения, связывающие Дуротар, Мулгор и северные форпосты.",["race:Tauren"]="Это поручение связывает тревоги об исконных охотничьих угодьях Степей с советом старейшин племени, живущих на вершине священных утесов Мулгора."},sec={{t="Тревожный сон",b="Изучая животных Степей, Тонга Рунический Тотем заметил странный недуг, охвативший существ возле цветущих оазисов. Измененные звери носили панцири, оскверненные неестественной силой, и Тонга понял, что сама земля погружена в бредовый, беспокойный сон. Убежденный, что источник этой гнили — воды, текущие из подземных Пещер Стенаний, Тонга знает, что для входа туда нужно куда больше мудрости, чем есть у одинокого натуралиста."},{t="Совет на Вершине Старейшин",b="Чтобы понять угрозу в пещерах, Тонга направляет вас в Громовой Утес к его сородичу, верховному друиду Хамуулу Руническому Тотему. Хамуул — высший по рангу друид-таурен и почитаемый духовный лидер Круга Кенария в Мулгоре. Находясь на безмятежной Вершине Старейшин, Хамуул следит за потрясениями по всему Калимдору и подтверждает, что кошмар, просачивающийся через Степи, — грозная опасность, требующая всей мощи героев Орды."}},faq={{q="Почему Тонга посылает меня к Хамуулу?",a="Тонга обнаружил, что оазисы Степей поражены странной хворью, исходящей из Пещер Стенаний. Поскольку это явление похоже на кошмар, сковавший землю, он посылает вас к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин за советом высокого уровня по делам друидов, прежде чем кто-либо попытается войти в пещеры.",al={"why hamuul","why talk to hamuul","hamuul quest purpose","почему хамуул","зачем говорить с хамуулом","цель задания хамуула"}},{q="Где находится Хамуул Рунический Тотем?",a="Верховный друид Хамуул Рунический Тотем находится в Громовом Утесе, столице таурен в Мулгоре. Он стоит на Вершине Старейшин и смотрит на окрестные равнины вместе с другими друидами и шаманами.",al={"hamuul location","where is hamuul","find hamuul runetotem","хамуул где находится","где хамуул","найти хамуула рунического тотема"}},{q="Что является источником порчи, которую заметил Тонга?",a="Порча исходит из подземных источников Пещер Стенаний. Странные воды оскверняют местных животных и растения, и земля ведет себя так, будто угодила в неизбывный кошмар.",al={"what is the taint","oasis corruption","wailing caverns taint","что за порча","порча оазисов","порча пещер стенаний"}},{q="Что будет после разговора с Хамуулом?",a="Хамуул приветствует вас в Громовом Утесе и готовит к предстоящим испытаниям. Он предупреждает, что борьба с кошмаром под Степями — опасное дело, и направляет вас к Наре Буйногривой, чтобы подготовиться к спуску в Пещеры Стенаний.",al={"next quest after hamuul","what next","hamuul follow up","следующее задание после хамуула","что дальше","продолжение хамуула"}},{q="Кто такой Хамуул Рунический Тотем?",a="Верховный друид Хамуул Рунический Тотем — главный предводитель друидов-таурен, близкий друг детства и советник верховного вождя Кэрна Кровавого Копыта. Постигнув пути природы после Третьей войны, он направляет друидов-таурен к единению с природой и Кругом Кенария.",al={"who is hamuul","hamuul lore","archdruid hamuul","кто такой хамуул","предания о хамууле","верховный друид хамуул"}},{q="Обязательно ли это задание для входа в Пещеры Стенаний?",a="Чтобы войти в Пещеры Стенаний, не требуется никакого допуска, но это задание — сюжетный мост Орды, связывающий загадку цветущих оазисов Степей с походом внутрь подземелья.",al={"wailing caverns attunement","is this quest mandatory","допуск в пещеры стенаний","обязательно ли это задание"}}},fp="16,269,18.485.0,21.447.0,33.311.0,34.200.0,46.204.0,40.241.0,24.284.0,52.200.0"}
P.entries["quest:149"] = {n="Прядь призрачных волос",s="«Прядь призрачных волос» — поручение гадалки Мадам Евы из Темнолесья. Чтобы собрать призрачные нити для прядения, путников отправляют на юг к Слепой Мэри, измученному духу, обитающему в заброшенном фермерском доме. Преподнеся ей призрачный гребень, можно собрать нужные пряди с ее призрачных локонов.",h="«Прядь призрачных волос» — поручение гадалки Мадам Евы из Темнолесья.",kw={"blind mary","darkshire","duskwood","farmhouse","ghost","ghost hair thread","madame eva","spectral comb","слепая мэри","темнолесье","сумеречный лес","ферма","призрак","прядь призрачных волос","мадам ева","призрачный гребень"},ang={["class:Priest"]="Зрелище духа, выцарапавшего себе глаза от душевной муки, показывает глубокую трагедию и сохраняющиеся тени, терзающие неупокоенных мертвецов Сумеречного леса.",["faction:Alliance"]="Трагические призраки, бродящие по фермам вокруг Темнолесья, напоминают о том, как быстро процветавшая Большая деревня погрузилась во тьму и изоляцию.",["profession:Tailoring"]="Прядение нити из бесплотных останков призрака — редкая оккультная техника, не имеющая ничего общего с обычными прялками и ткацкими станками."},sec={{t="Просьба гадалки",b="Мадам Еве из Темнолесья нужны особые потусторонние материалы, чтобы спрясть для Аберкромби Прядь призрачных волос. Обычных льняных и шерстяных нитей для обрядов Сумеречного леса недостаточно: ей нужны призрачные пряди, взятые прямо у духа. Чтобы добыть этот жуткий материал без насилия, Ева дает хрупкий Призрачный гребень, способный проходить сквозь завесу смерти и собирать выпавшие призрачные волосы."},{t="Скорбь Слепой Мэри",b="К югу от Темнолесья, среди сумрачных холмов, стоит заброшенная ферма, которую преследует воющий призрак по имени Слепая Мэри. Дух, охваченный отвращением к себе, постоянно оплакивает свой уродливый облик и кричит на незваных гостей, чтобы они отвели взгляд: в муках она вырвала себе глаза еще при жизни или в момент смерти. Дар в виде Призрачного гребня приносит ей мимолетное утешение, и она расчесывает свои призрачные волосы, несмотря на бесконечные страдания."}},faq={{q="Кто такая Слепая Мэри?",a="Слепая Мэри — скорбный призрак, обитающий в заброшенном фермерском доме в холмах к югу от Темнолесья. Обезумев от отчаяния и мнимого уродства, она вырвала себе глаза, чтобы больше никогда не видеть себя. Несмотря на слепоту, она остро и мучительно ощущает каждого, кто на нее смотрит.",al={"blind mary lore","who is mary duskwood","spectral comb woman","слепая мэри","кто такая мэри сумеречный лес","женщина с призрачным гребнем"}},{q="Зачем Мадам Еве призрачные волосы?",a="Мадам Еве нужны пряди призрачных волос, чтобы прясть призрачные нити. В населенном призраками Сумеречном лесу обычных материалов для ремесла часто не хватает, и для своих обрядов и защитных чар она использует оккультные компоненты.",al={"why ghost hair","what is ghost hair thread for","madame eva hair thread","зачем призрачные волосы","для чего прядь призрачных волос","мадам ева нить из волос"}},{q="Где находится дом Слепой Мэри?",a="Ее разрушенная усадьба стоит в холмах прямо к югу от Темнолесья, за городским кладбищем, среди бродящих чудовищ и нежити, наводнивших темный лес.",al={"where is blind mary","blind mary location","farmhouse south of darkshire","где слепая мэри","местонахождение слепой мэри","ферма к югу от темнолесья"}},{q="Как Призрачный гребень действует на дух?",a="Призрачный гребень создан или зачарован для незримого мира и может взаимодействовать с бесплотными призраками. Он скользит сквозь духовную материю так же, как обычный гребень сквозь живые волосы, собирая выпавшие пряди, сохраняющие эфирную форму.",al={"how does spectral comb work","spectral comb lore","comb ghost hair","как работает призрачный гребень","призрачный гребень предания","расчесать призрачные волосы"}},{q="Враждебна ли Слепая Мэри к путникам?",a="Нет. Несмотря на жуткие крики и плач, Слепая Мэри не враждебна к живым гостям. Ее страдание обращено только внутрь, хотя в окрестных лесах и постройках обитает множество агрессивных существ и нежити.",al={"will blind mary attack","is blind mary dangerous","нападет ли слепая мэри","опасна ли слепая мэри"}},{q="Что будет после того, как отдать гребень Мэри?",a="Когда Мэри расчешет волосы, она возвращает гребень с запутавшимися в нем призрачными прядями. Искатели приключений должны отнести гребень Мадам Еве в Темнолесье, чтобы она спряла пряди в Прядь призрачных волос.",al={"what next ghost hair","return the comb quest","after ghost hair thread","что дальше призрачные волосы","вернуть гребень задание","после пряди призрачных волос"}}},fp="17,359,25.430.0,24.467.0,18.307.0,36.240.0,38.172.0,44.246.0,35.232.0,40.187.0"}
P.entries["quest:1490"] = {n="Нара Буйногривая",s="Нара Буйногривая — молодая таурен-друид из Громового Утеса, стремящаяся разгадать трагедию, разворачивающуюся в глубинах Пещер Стенаний. После того как верховный друид Хамуул Рунический Тотем заглянул в Изумрудный Сон и отступил от зарождающейся там порчи, он отправил искателей приключений к Наре, чей стойкий дух позволил ей достаточно долго наблюдать за кошмаром, охватывающим их сородичей. Она — ключевая связная Орды, направляющая героев положить конец Друидам Клыка.",h="Нара Буйногривая — молодая таурен-друид из Громового Утеса, стремящаяся разгадать трагедию, разворачивающуюся...",kw={"barrens","druids of the fang","elder rise","emerald dream","hamuul runetotem","nara wildmane","thunder bluff","wailing caverns","степи","друиды клыка","вершина старейшин","изумрудный сон","хамуул рунический тотем","нара буйногривая","громовой утес","пещеры стенаний"},ang={["class:Druid"]="Друиды оценят отвагу Нары, пробирающейся по коварным, оскверненным просторам Изумрудного Сна, где даже опытные наставники вроде Хамуула не решались задерживаться.",["faction:Horde"]="Бдительность Нары защищает сердце земель Орды, не давая темным силам, искажающим Степи, беспрепятственно проникнуть в Мулгор.",["race:Tauren"]="Для таурен, недавно вставших на путь друидизма под руководством Хамуула, Нара олицетворяет молодое, непреклонное поколение, готовое лицом к лицу встретить неестественную порчу."},sec={{t="Видение порчи",b="Когда по Степям начали распространяться странные, неестественные явления, верховный друид Хамуул Рунический Тотем отправился в Изумрудный Сон, чтобы выяснить причину. Там он увидел культ друидов, которые изначально стремились вернуть жизнь засушливой саванне, но лишились рассудка из-за мерзкой скверны. Будучи стар и не в силах долго противостоять натиску кошмара, Хамуул бежал обратно в мир яви. Однако его юная ученица Нара Буйногривая не пожелала так легко сдаваться. Ее пылкая решимость удерживала ее в мире снов гораздо дольше, и она смогла собственными глазами увидеть преображенный культ."},{t="Противостояние кошмару",b="Пока Хамуул направляет Круг Кенария в Громовом Утесе, Нара Буйногривая обладает тактическим чутьем, необходимым для искоренения гнили. Она прямо видела искаженные, покрытые змеиной чешуей лики падших друидов, знает об их преступлениях и о разрушениях, которые они намерены обрушить на Калимдор. Ее решимость знаменует начало наступления Орды на Пещеры Стенаний, чтобы уничтожить предводителей, отринувших священные клятвы."}},faq={{q="Кто такая Нара Буйногривая?",a="Нара Буйногривая — молодая и бойкая таурен-друид, живущая на Вершине Старейшин в Громовом Утесе. Она учится у верховного друида Хамуула Рунического Тотема и не боится противостоять разрушительным кошмарам, угрожающим равновесию природы.",al={"who is nara","nara wildmane lore","nara wildmane thunder bluff","кто такая нара","нара буйногривая предания","нара буйногривая громовой утес"}},{q="Почему Хамуул Рунический Тотем посылает путников поговорить с ней?",a="Хамуул признает, что преклонный возраст и слабеющие силы не позволили ему долго оставаться в оскверненном сне, где обитают Друиды Клыка. Поскольку Нара молода и очень решительна, она осталась в мире грез дольше и собрала важные сведения о планах культа.",al={"why speak with nara","hamuul to nara","why hamuul send me here","зачем говорить с нарой буйногривой","хамуул к наре","почему хамуул отправил меня сюда"}},{q="Что Нара увидела в Изумрудном Сне?",a="Нара стала свидетельницей того, как падшие друиды обитают в Пещерах Стенаний. Она видела их лица, искаженные в змеиные, чешуйчатые облики, и узнала о темных замыслах и преступлениях, которые они намерены совершить в Степях.",al={"what did nara see","nara dream vision","scaled druids dream","что видела нара","видение нары во сне","чешуйчатые друиды сон"}},{q="Где можно найти Нару Буйногривую?",a="Ее можно найти в друидской палатке на Вершине Старейшин в Громовом Утесе, прямо напротив верховного друида Хамуула Рунического Тотема.",al={"where is nara","nara wildmane location","find nara wildmane","где нара","местонахождение нары буйногривой","найти нару буйногривую"}},{q="Что будет после разговора с Нарой Буйногривой?",a="Когда вы поговорите с ней, Нара поручит вам войти в Пещеры Стенаний и убить отступников из числа Друидов Клыка, что подводит к важному заданию подземелья «Повелители Змей».",al={"next quest after nara","what does nara want me to do","leaders of the fang follow up","следующее задание после нары","что нара хочет от меня","повелители змей продолжение"}},{q="Почему друиды в Пещерах Стенаний осквернены?",a="Друиды во главе с Наралексом вошли в пещеры, надеясь обратиться к Изумрудному Сну и принести пышную жизнь в Степи. Вместо этого сон Наралекса превратился в ужасный кошмар, опутавший его последователей и превративший их в змееподобных Друидов Клыка.",al={"wailing caverns cult","druids of the fang why evil","why barrens druids evil","культ пещер стенаний","друиды клыка почему злые","почему друиды степей злые"}}},fp="13,481,22.598.0,25.471.1,21.230.0,59.289.0,39.210.0,33.127.0,46.169.0,52.263.0"}
P.entries["quest:1491"] = {n="Умный напиток",s="«Умный напиток» — предприимчивая затея торговца-гоблина Мебока Миззрикса из Кабестана. Не сумев сварить тонизирующее зелье для повышения интеллекта из рогов солнечночешуйчатых ящеров, Мебок теперь поручает искателям приключений спуститься в Пещеры Стенаний и собрать эктоплазму для рецепта своего нового напитка.",h="«Умный напиток» — предприимчивая затея торговца-гоблина Мебока Миззрикса из Кабестана.",kw={"barrens","ectoplasm","mebok mizzyrix","raptor horns","ratchet","smart drinks","wailing caverns","wailing essence","степи","эктоплазма","мебок миззрикс","рога ящеров","кабестан","умный напиток","пещеры стенаний","воющая субстанция"},ang={["class:Druid"]="Пока друиды входят в Пещеры Стенаний, чтобы очистить кошмар, искажающий изумрудный мир снов, Мебок видит в этой трагической экологической скверне лишь дешевый жидкий сироп для своей торговой затеи.",["faction:Horde"]="Путникам, идущим через перекресток Степей, торговцы Кабестана предложат немало быстрых денег, если не задавать слишком много вопросов о том, что они собираются делать с частями чудовищ, которые вы доставляете.",["profession:Cooking"]="Любой кулинар сразу заметит санитарную катастрофу в Кабестане: настаивать сырую эктоплазму, оскверненную кошмаром, прямо в питьевой тоник — нарушение всех норм безопасности пищи."},sec={{t="Рецепт катастрофы",b="Работая в шумном портовом городе Кабестан, Мебок Миззрикс воплощает классическую гоблинскую философию: превращать любое странное местное явление в звонкую монету. Убежденный, что напиток, повышающий интеллект, сделает его магнатом за одну ночь, он сначала думал, что секрет кроется в порошке из рогов ящеров. Когда эта партия оказалась совершенно неудачной, он просто обратил внимание на еще более сомнительный ингредиент: оскверняющую субстанцию, сочащуюся из соседних Пещер Стенаний."},{t="Воющая субстанция",b="В Степях происходят тревожные экологические мутации: внезапно появляются пышные оазисы, а местные звери превращаются в агрессивных чудовищ. Миззрикс полагает, что причина этих внезапных перемен — странное вещество, которое он называет «воющей субстанцией». Решив, что все, столь сильно меняющее живую природу, должно стать мощным тайным ингредиентом, он посылает наемников уничтожать сочащиеся эктоплазмы в глубинах лабиринта пещер и сливать их светящуюся жидкость прямо в бутылки для напитков."}},faq={{q="Кто такой Мебок Миззрикс?",a="Мебок Миззрикс — предприимчивый гоблин, обосновавшийся в портовом городе Кабестан. Не обращая внимания на санитарные нормы, он одержим созданием коммерческого «умного напитка», чтобы продавать его по всему Калимдору и разбогатеть.",al={"mebok mizzyrix","who gives smart drinks","smart drinks quest giver","мебок миззрикс","кто дает умный напиток","умный напиток персонаж, выдающий задания"}},{q="Почему рога ящеров не подошли?",a="Мебок сначала считал, что измельченные рога солнечночешуйчатых ящеров дадут мощное снадобье для повышения интеллекта. Полученный напиток не принес обещанной гениальности, и ему пришлось перейти к гораздо более опасному активному ингредиенту.",al={"why raptor horns failed","raptor horn drink","почему рога ящеров не подошли","напиток из рогов ящера"}},{q="Что такое воющая субстанция?",a="Воющая субстанция — эктоплазменное вещество, сочащееся из неестественных слизней в глубинах Пещер Стенаний. Мебок полагает, что это изменчивое вещество — движущая сила странных мутаций растений и животных, распространяющихся по Степям.",al={"what is wailing essence","essence from wailing caverns","что такое воющая субстанция","субстанция из пещер стенаний"}},{q="Где найти эктоплазмы, несущие субстанцию?",a="Субстанцию собирают с эктоплазменных существ, таких как развивающиеся, пожирающие и кошмарные эктоплазмы, обитающих в подземных туннелях Пещер Стенаний к западу от Кабестана.",al={"where are ectoplasms","smart drinks mobs","who drops wailing essence","где эктоплазмы","умный напиток монстры","с кого падает воющая субстанция"}},{q="Безопасно ли пить умный напиток?",a="Учитывая, что субстанцию добывают из кошмарных слизней, связанных с оскверняющими мутациями по всем Степям, разливать ее как коммерческий тоник крайне опрометчиво. Верный гоблинской деловой этике, Мебок гораздо больше заботится о товарном виде, чем о безопасности покупателей.",al={"is smart drink poisonous","does the drink work","умный напиток ядовит","работает ли напиток"}},{q="Что будет после выполнения задания «Умный напиток»?",a="«Умный напиток» завершает ближайшую напиточную затею Мебока. Довольный доставкой воющей субстанции, он вознаграждает вас и обещает поделиться будущей прибылью, когда его сомнительный тоник принесет ему состояние.",al={"smart drinks follow up","what next after smart drinks","умный напиток продолжение","что дальше после умного напитка"}}},fp="12,312,21.488.0,19.518.0,22.207.0,33.250.0,24.258.0,54.194.0,35.266.0,41.203.0"}
P.entries["quest:1492"] = {n="Управляющий пристанью Головокружилкинс",s="Управляющий пристанью Головокружилкинс — курьерское поручение: доставить ящик с зельями и реагентами через Степи в портовый город Кабестан. Груз отправится через Великое море в Старый Свет на корабле, зафрахтованном через местные причалы. Задание знакомит путников с оживленной нейтральной торговлей, сосредоточенной вокруг пирса Кабестана.",h="Управляющий пристанью Головокружилкинс — курьерское поручение: доставить ящик с зельями и реагентами через...",kw={"blackwater cove","docks","pier","ratchet","secure crate","shipping","the barrens","wharfmaster dizzywig","бухта черноводья","доки","причал","кабестан","надежный ящик","доставка","степи","управляющий пристанью головокружилкинс"},ang={["faction:Horde"]="Для авантюристов Орды, идущих по сухим равнинам Степей, доставка груза в Кабестан знакомит с важными нейтральными морскими путями, соединяющими Калимдор с Восточными королевствами."},sec={{t="Курьер в порт",b="Когда товары нужно перевезти через океан между Калимдором и Восточными королевствами, нейтральный порт Кабестан служит главными воротами для путников в центральном Калимдоре. Поскольку караваны уже ушли, а алхимические припасы ждут отправки коллегам в Старом свете, путников часто просят лично донести надежные ящики прямо к кромке воды."},{t="Причалы Кабестана",b="Управляющий пристанью Головокружилкинс заведает входящими и исходящими морскими грузами со своего поста на деревянных пирсах Кабестана. Сводя книги, декларации и трюмы, Головокружилкинс следит, чтобы частным грузам нашлось место на кораблях, идущих на восток через Великое море в такие порты, как Бухта Черноводья."}},faq={{q="Кто такой Управляющий пристанью Головокружилкинс?",a="Управляющий пристанью Головокружилкинс — гоблин-портовый чиновник, расположившийся на главном пирсе Кабестана. Он ведет декларации судов, учет трюмов и перевозки между Калимдором и портами за морем.",al={"wharfmaster dizzywig","who is dizzywig","where is dizzywig","управляющий пристанью головокружилкинс","кто такой головокружилкинс","где головокружилкинс"}},{q="Куда отправляют ящик?",a="Ящик с зельями и реагентами предназначен для Старого света и заказан на следующий корабль, уходящий из Кабестана в Бухту Черноводья.",al={"where does crate go","blackwater cove","destination of crate","куда идет ящик","бухта черноводья","место назначения ящика"}},{q="Где находится Кабестан?",a="Кабестан расположен на восточном побережье Степей, в защищенной бухте прямо к востоку от центрального перекрестка.",al={"ratchet location","how do i find ratchet","где кабестан","как найти кабестан"}},{q="Зачем отправлять груз через гоблинский порт?",a="Кабестан — нейтральный порт, открытый и для Орды, и для независимых торговцев, с регулярными морскими маршрутами через Великое море, обходящими военные блокады и политические конфликты.",al={"why ratchet","why use goblin port","почему кабестан","зачем гоблинский порт"}},{q="Что внутри надежного ящика?",a="В ящике находится набор готовых зелий, реагентов для ремесла и разных алхимических товаров, предназначенных для партнеров в Восточных королевствах.",al={"crate contents","what is in the box","содержимое ящика","что в коробке"}},{q="Кто отправляет груз Головокружилкинсу?",a="Груз отправляет алхимик из Степей, опоздавший на обычный караван и нуждавшийся в надежном посыльном, чтобы добраться до причала до следующего прилива.",al={"who gives the quest","quest giver","кто дает задание","персонаж, выдающий задания"}}},fp="20,347,21.359.0,15.294.0,28.192.0,30.152.0,25.123.0,37.185.0,32.148.0,35.181.0"}
P.entries["quest:1498"] = {n="Путь защиты",s="Путь защиты — обряд посвящения для молодых воинов Орды, который выдает ветеран Уззек на Дальней заставе. Новичкам поручают охотиться на электрических тварей Громового хребта, чтобы доказать, что они достаточно стойки и могут стать щитом Орды.",h="Путь защиты — обряд посвящения для молодых воинов Орды, который выдает ветеран Уззек на Дальней заставе.",kw={"barrens","durotar","far watch post","path of defense","singed scales","thunder lizards","thunder ridge","uzzek","степи","дуротар","дальняя застава","путь защиты","опаленная чешуя","громовые ящеры","громовой хребет","уззек"},ang={["class:Warrior"]="Это задание отмечает переход новичка к дисциплине обороны и учит, что истинная боевая сила — в защите союзников от гибели.",["faction:Horde"]="Дальняя застава — важнейший пост на дороге в Степи, поэтому стойкость ее стражей жизненно важна для безопасности Орды."},sec={{t="Щит Орды",b="Война в Орде — это не только безудержная атака в дикой ярости. На Дальней заставе, расположенной на границе Степей и Дуротара, ветеран Уззек учит молодых воинов суровому долгу защиты. По мнению Уззека, высшее призвание воина — встать между опасностью и теми, кто не может защитить себя, принимая сокрушительные удары ради того, чтобы Орда выстояла."},{t="Испытание грома",b="Чтобы доказать, что у них есть выносливость и решимость для дисциплинированной защиты, Уззек отправляет новичков на Громовой хребет. Этот каньон лежит к северу, за рекой Строптивой в Дуротаре, и кишит громовыми ящерами и молниеносными шкурами. Выдержав сотрясающие удары этих тварей и собрав их опаленную чешую, новичок показывает, что у него хватит стойкости удерживать передовую."}},faq={{q="Кто выдает задание «Путь защиты»?",a="Задание выдает ветеран Уззек, опытный воин с Дальней заставы, которая охраняет границу, где Дуротар встречается с восточным краем Степей.",al={"quest giver","who starts path of defense","uzzek location","персонаж, выдающий задания","кто дает путь защиты","где уззек"}},{q="Где находится Громовой хребет?",a="Громовой хребет находится за мостом через реку Строптивую, на западе Дуротара, к северу от главной дороги. В ущелье обитают агрессивные громовые ящеры и молниеносные шкуры.",al={"thunder ridge location","where are thunder lizards","singed scales location","где громовой хребет","где громовые ящеры","где опаленная чешуя"}},{q="Почему Уззек требует именно опаленную чешую?",a="Опаленную чешую можно добыть, только охотясь на тварей Громового хребта, владеющих молниями. Выдержав их электрические атаки, воин доказывает, что обладает физической крепостью и стойкостью, нужными для изучения продвинутых приемов обороны.",al={"why singed scales","purpose of scales","зачем опаленная чешуя","для чего чешуя"}},{q="В чем философский урок этого испытания?",a="Уззек учит, что воин — это не просто убийца, а несокрушимый оплот. Пережив ярость диких зверей, новички учатся сочетать крепкую шкуру с расчетливыми движениями, чтобы защищать более слабых союзников.",al={"warrior philosophy","lore behind path of defense","defensive stance lore","философия воина","предания пути защиты","предания оборонительной стойки"}},{q="Что дальше после задания «Путь защиты»?",a="Когда вы докажете Уззеку свою стойкость, он отправит вас продолжить боевую подготовку у Тун'грима Огневзора.",al={"next quest","what after path of defense","follow up","следующее задание","что после пути защиты","продолжение"}},{q="Могут ли пройти это испытание не воины?",a="Нет. Путь защиты — обряд посвящения исключительно для воинов, призванный проверить и обучить новобранцев основам караульной службы и оборонительного боя.",al={"is this warrior only","who can do this quest","только для воинов","кто может выполнить это задание"}}},fp="15,278,23.412.0,16.391.0,36.169.0,31.197.0,49.235.0,51.239.0,49.129.0,38.155.0"}
P.entries["quest:1499"] = {n="Злобные фамильяры",s="Это задание отмечает завершение первой вылазки юного чернокнижника против демонических прислужников, прячущихся в Долине Испытаний. Убив злобных фамильяров под руководством Рузана, неофит докладывает о содеянном Зурите Востроглазой, которая руководит истреблением наступающего Пылающего Клинка.",h="Это задание отмечает завершение первой вылазки юного чернокнижника против демонических прислужников...",kw={"burning blade coven","durotar","imps","ruzan","the den","valley of trials","vile familiars","warlock quest","zureetha fargaze","грот пылающего клинка","дуротар","бесы","рузан","логово","долина испытаний","злобные фамильяры","задание чернокнижника","зурита востроглазая"},ang={["class:Warlock"]="Для новичка темных искусств схватка со злобными фамильярами — необходимое испытание: оно доказывает, что вы способны подчинять и уничтожать диких существ Скверны, а не становиться их добычей.",["race:Orc"]="Присутствие демонических фамильяров — мерзкое напоминание о темных пактах, некогда поработивших орочий народ, поэтому изгнать их с земли Дуротара для орков — вопрос выживания их культуры.",["race:Troll"]="Тролли Черного Копья, живущие в Долине Испытаний, глубоко не доверяют демонической магии, поэтому молодым практикам важно доказать свою верность в борьбе с отступниками-культистами."},sec={{t="Вопрос дисциплины",b="Других молодых воинов и разведчиков в Долине Испытаний Зурита Востроглазая напрямую отправляет сдерживать нашествие в Гроте Пылающего Клинка, а новички-чернокнижники сначала подчиняются своим мрачным наставникам. Рузан требует доказать силу и власть над низшими демонами, а затем возвращает учеников к общей обороне Орды, чтобы их усилия служили и сообществу чернокнижников, и безопасности Логова."},{t="Угроза грота",b="Зурита Востроглазая внимательно следит за северной пещерой, возвышающейся над Долиной Испытаний. Злобные фамильяры, таящиеся там, — лишь самые слабые питомцы культистов Пылающего Клинка, но их открытое присутствие на священной тренировочной земле — дерзкое оскорбление и растущая опасность. Доклад об успехе против них подтверждает, что даже те, кто изучает магию Скверны, остаются преданы защите Дуротара от настоящей порчи."}},faq={{q="Почему Рузан отправляет меня к Зурите Востроглазой, а не награждает сам?",a="Зурита Востроглазая координирует общую оборону и истребление Пылающего Клинка в Долине Испытаний. Рузан сначала проверяет вашу власть над низшими существами Скверны, но отправляет вас к Зурите, чтобы ваша служба была официально признана и учтена в общей обороне Долины.",al={"why see zureetha","ruzan to zureetha","why talk to zureetha","зачем идти к зурите","рузан к зурите","почему говорить с зуритой"}},{q="Кто такие злобные фамильяры?",a="Злобные фамильяры — мелкие демоны-бесы и прислужники, подчиненные Гроту Пылающего Клинка. Хотя по отдельности они слабы, они служат более темным хозяевам, скрывающимся в глубине пещеры над Долиной Испытаний.",al={"what are vile familiars","vile familiar lore","familiars burning blade","что такое злобные фамильяры","предания злобных фамильяров","фамильяры пылающего клинка"}},{q="Где найти Зуриту Востроглазую?",a="Зурита Востроглазая стоит на открытом месте почти в центре Логова в Долине Испытаний, совсем недалеко от лагеря наставников, где живет Рузан.",al={"where is zureetha","zureetha fargaze location","zureetha map","где зурита","зурита востроглазая где найти","зурита на карте"}},{q="Почему есть еще одно задание с таким же названием?",a="Большинство героев получают задание «Злобные фамильяры» прямо от Зуриты Востроглазой, чтобы охотиться на этих тварей. Чернокнижникам же Рузан дает отдельное задание для их класса, которое по завершении ведет к краткому возвращению к Зурите.",al={"two vile familiars quests","duplicate vile familiars","warlock vile familiars","два задания злобные фамильяры","повтор злобных фамильяров","злобные фамильяры чернокнижник"}},{q="Что Пылающий Клинок делает в Долине Испытаний?",a="Культ Пылающего Клинка тайно действует по всему Дуротару, стремясь подорвать новую Орду Тралла изнутри. Обосновавшись в пещере прямо в Долине Испытаний, культисты могут охотиться на неопытных новичков и распространять демоническую порчу под самым носом у орочьих надзирателей.",al={"burning blade valley of trials","why are cultists in the den","пылающий клинок долина испытаний","почему культисты в логове"}},{q="Уничтожает ли убийство этих фамильяров культ?",a="Нет. Как отмечает Зурита, злобные фамильяры — лишь питомцы и разведчики более темных сил в гроте. Их поражение — только первый шаг к обнаружению и искоренению более глубокой угрозы культистов, зреющей в Долине.",al={"is burning blade defeated","are cultists gone","пылающий клинок побежден","культисты исчезли"}}},fp="14,288,22.439.0,23.442.0,75.298.0,27.216.0,34.169.0,52.245.0,56.294.0,47.225.0"}
P.entries["quest:15"] = {n="Разведка в руднике Горного эха",s="Разведка в руднике Горного эха — одно из первых военных поручений маршала Макбрайда в Долине Североземья. Новобранцев отправляют на север, в Рудник Горного Эха, истребить наступающих кобольдов-рабочих и выяснить истинный масштаб нашествия, угрожающего минеральным богатствам аббатства.",h="Разведка в руднике Горного эха — одно из первых военных поручений маршала Макбрайда в Долине Североземья.",kw={"echo ridge","elwynn","kobold","kobold worker","marshal mcbride","mine","northshire","northshire valley","рудник горного эха","элвиннский лес","кобольд","кобольд-рабочий","маршал макбрайд","шахта","североземье","долина североземья"},ang={["faction:Alliance"]="Подползающее нашествие кобольдов так близко к духовному сердцу Штормграда в Североземье показывает, насколько уязвимо стало королевство, чьи регулярные войска растянуты.",["profession:Mining"]="Рудник Горного Эха — важный источник меди для кузнецов Североземья, поэтому расчистка этих подземных туннелей для шахтеров — вопрос прямого экономического выживания.",["race:Human"]="Для молодых людей, начинающих службу в Долине Североземья, защита Рудника Горного Эха от подземных паразитов — одно из первых испытаний, доказывающих их ценность для королевства."},sec={{t="Растущее нашествие",b="Если ранние стычки вокруг Североземья касались разрозненных паразитов, бродивших по лесной окраине, то вскоре донесения разведчиков показали куда более организованную угрозу. Кобольды не просто рыскали по лесу: они собрались в силе вокруг Рудника Горного Эха. Маршал Макбрайд отправляет новобранцев на север, чтобы они встретились с кобольдами-рабочими у входа в рудник и выяснили, насколько глубоко закрепились вредители."},{t="Угроза богатствам аббатства",b="Рудник Горного Эха — важнейший источник руды и сырья для братства Североземья и штормградской стражи, расквартированной здесь. Крысоподобные падальщики, захватившие туннели, парализуют добычу и показывают, как слабо растянута местная оборона. Истребление десяти рабочих — лишь первый шаг, и опасения Макбрайда подтверждаются: нашествие уходит в штольни глубже, чем способен исправить обычный наземный дозор."}},faq={{q="Кто посылает меня на это задание?",a="Маршал Макбрайд, командир штормградских стражей в Аббатстве Североземья, отдает приказ исследовать рудник, когда разведчики обнаруживают, что кобольды собираются на севере.",al={"quest giver","who gives quest","marshal mcbride","персонаж, выдающий задания","кто дает задание","маршал макбрайд"}},{q="Где находится Рудник Горного Эха?",a="Рудник Горного Эха находится на крайнем севере Долины Североземья, прямо в предгорьях над аббатством и его виноградниками.",al={"echo ridge location","where is the mine","find echo ridge","где рудник горного эха","где шахта","найти рудник горного эха"}},{q="Чем кобольды опасны для Североземья?",a="Хотя отдельные кобольды — трусливые падальщики, они быстро размножаются и огромными стаями наводняют подземные туннели. Захватив Рудник Горного Эха, они останавливают важнейшую добычу и грозят захлестнуть малочисленную долину.",al={"why kill kobolds","what makes kobolds a threat","kobold danger","зачем убивать кобольдов","чем опасны кобольды","опасность кобольдов"}},{q="Что будет после победы над рабочими снаружи?",a="Вернувшись к маршалу Макбрайду, вы подтверждаете его худшие подозрения: рудник сильно заражен. Он тут же снова просит вашей помощи для более глубокого броска в подземные штольни в задании «Схватка у рудника Горного эха».",al={"what next","follow up quest","next quest","что дальше","следующее задание","продолжение"}},{q="Почему штормградская армия не очистит рудник сама?",a="Из-за исчезновения короля Вариана Ринна и нехватки ресурсов в Элвиннском лесу и соседних землях местный гарнизон Североземья слишком мал, чтобы выделять полноценные патрули на борьбу с вредителями, и полагается на способных новобранцев.",al={"where are stormwind guards","why use recruits","stormwind garrison","где штормградские стражи","почему новобранцы","штормградский гарнизон"}},{q="Какие кобольды встречаются у входа в рудник?",a="На поверхности и у верхних входов работают кобольды-рабочие — простые трудяги, которые копают туннели и собирают свечной воск для своей подземной колонии.",al={"kobold types","what enemies to kill","kobold worker","виды кобольдов","каких врагов убивать","кобольд-рабочий"}}},fp="22,301,23.435.0,28.426.0,29.183.0,37.146.0,40.227.0,48.204.1,57.228.0,56.163.0"}
P.entries["quest:150"] = {n="Мурлоки-браконьеры",s="Начальник порта Барен из Приозерья ищет искателей приключений, которые сократят растущие ряды мурлоков у Озера Безмолвия, пока те не истощили главный источник пищи города. То, что начинается как обычная награда за истребление вредителей, поднимает тревожный экологический вопрос: почему прибрежные создания селятся так глубоко в горах внутри страны?",h="Начальник порта Барен из Приозерья ищет искателей приключений, которые сократят растущие ряды мурлоков у...",kw={"dockmaster baren","dwarven fishing pole","lake everstill","lakeshire","murloc fin","poachers","redridge","начальник порта барен","дворфийская удочка","озеро безмолвия","приозерье","плавник мурлока","браконьеры","красногорье"},ang={["faction:Alliance"]="Приозерье и без того теснят орки Черной горы и гноллы, поэтому у города Альянса почти не остается сил для защиты жизненно важных запасов пищи на Озере Безмолвия.",["race:Human"]="Красногорье было мирным местом отдыха королевства Штормград; вид его чистых горных вод, захваченных враждебными мурлоками, показывает, насколько ослаб порядок."},sec={{t="Угроза городским запасам",b="Озеро Безмолвия — источник жизни Приозерья: оно кормит горный город и снабжает его рынок свежим уловом. Когда большие племена мурлоков начали обосновываться на мелководье, начальник порта Барен понял, что городу грозит экологический кризис. Прожорливые рыболюды рьяно выбирали рыбу из вод, и, если их не остановить, местная рыба могла исчезнуть полностью."},{t="Странное переселение вглубь суши",b="Мурлоки обычно собирают пищу на побережье, поэтому их огромное число высоко в Красногорье выглядит необычно. Начальник порта Барен открыто недоумевает, почему они ушли так далеко от открытого океана. Были ли они вытеснены вглубь суши морскими хищниками, бежали от споров за территорию или их привлекли обильные воды Озера Безмолвия, их переселение указывает на более глубокие беды в другой части региона."}},faq={{q="Кто такой начальник порта Барен?",a="Начальник порта Барен управляет причалами и рыболовным движением на берегу Озера Безмолвия в Приозерье. Он занимается водными поставками и нанимает искателей приключений, чтобы защищать ресурсы озера от водных угроз.",al={"baren","who gives murloc poachers","dockmaster baren","барен","кто выдает задание мурлоки-браконьеры","начальник порта барен"}},{q="Почему мурлоки в Красногорье?",a="Мурлоки обычно обитают на прибрежных землях и в болотах, поэтому их присутствие на высокогорном Озере Безмолвия необычно. Начальник порта Барен предполагает, что эти племена ушли вглубь суши, спасаясь от чего-то еще худшего на побережье.",al={"why are murlocs in lake everstill","murlocs inland redridge","why fishmen in lake","почему мурлоки у озера безмолвия","мурлоки в красногорье","почему рыболюды в озере"}},{q="Чем мурлоки угрожают Приозерью?",a="Приозерье сильно зависит от Озера Безмолвия в рыбной ловле и торговле. Племена мурлоков быстро вылавливают рыбу, угрожая лишить город главного источника пищи и подорвать местную экономику.",al={"why kill murlocs","murloc problem lakeshire","lake everstill fish depleted","зачем убивать мурлоков","проблема мурлоков приозерье","рыба в озере безмолвия истреблена"}},{q="Зачем начальник порта Барен собирает плавники мурлоков?",a="Барен собирает восемь плавников мурлоков как вещественное доказательство истребления. Плавники подтверждают, что искатели приключений действительно сокращают численность мурлоков на берегах и отпугивают наступающие племена.",al={"why murloc fins","fin bounty lakeshire","зачем плавники мурлоков","награда за плавники приозерье"}},{q="Есть ли другие задания, связанные с мурлоками Озера Безмолвия?",a="Да, начальник порта Барен также предлагает дополнительное задание «Продажа рыбы»: нужно собрать свежее мясо рыб и мурлоков озера, очищая его воды.",al={"selling fish quest connection","other murloc quests redridge","задание продажа рыбы","другие задания про мурлоков красногорье"}},{q="Какую награду дает начальник порта Барен за расправу с браконьерами?",a="Получив восемь плавников, начальник порта Барен награждает искателя приключений добротной дворфийской удочкой, чтобы поощрить бережное отношение к водам озера.",al={"murloc poachers reward","dwarven fishing pole quest","награда мурлоки-браконьеры","дворфийская удочка задание"}}},fp="15,317,29.394.0,24.401.0,24.209.0,38.253.0,45.211.0,46.189.0,57.169.0,65.166.0"}
P.entries["quest:1501"] = {n="Создание Бездны",s="«Создание Бездны» — важный обряд посвящения для молодых чернокнижников Орды, обучающихся в Оргриммаре. Желая расширить мастерство призыва новичка и научить его вызывать демона Бездны, Ган'рул Кровавый Глаз поручает чернокнижнику вернуть украденную Табличку Верги у отступников-культистов Пылающего Клинка, прячущихся в Скале Черепа.",h="«Создание Бездны» — важный обряд посвящения для молодых чернокнижников Орды, обучающихся в Оргриммаре.",kw={"burning blade","cleft of shadow","creature of the void","gan'rul bloodeye","orgrimmar","skull rock","tablet of verga","voidwalker","warlock quest","пылающий клинок","расселина теней","создание бездны","ган'рул кровавый глаз","оргриммар","скала черепа","табличка верги","демон бездны","задание чернокнижника"},ang={["class:Warlock"]="Это испытание — важнейший обряд посвящения для чернокнижников Орды: от маленьких бесов они переходят к управлению теневыми слугами на передовой.",["faction:Horde"]="Хотя Орда Тралла в целом не доверяет практикующим магию Скверны, наставники вроде Ган'рула следят, чтобы изучающие темные искусства использовали силу строго на службе Вождю.",["race:Orc"]="Для орков, преследуемых прошлым связи с Советом Теней, охота на Пылающий Клинок — способ отомстить тем, кто все еще принимает демоническую погибель."},sec={{t="Опасное искусство",b="В подземных тенях Расселины Теней в Оргриммаре Ган'рул Кровавый Глаз наблюдает за практикующими чернокнижниками Орды. Магию Скверны в новом государстве Тралла встречают с глубокой опаской: ее запятнала мрачная история орочьих кланов. Ган'рул признает, что настоящих чернокнижников в Орде осталось мало, но настаивает, что их опасные умения необходимы для выживания Орды. Чтобы быть полезным Вождю, новичок не может полагаться лишь на хаотичный огонь беса: он должен научиться повелевать существами чистой тени и стойкости."},{t="Украденная табличка",b="Для призыва демона Бездны нужны особые руны, начертанные на Табличке Верги. К несчастью, реликвию похитил Пылающий Клинок — фанатичный теневой культ, действующий прямо под носом у Вождя в пещере Скала Черепа. Ган'рул посылает ученика ударить по логову культистов, вернуть табличку и нанести кровавый удар отступникам, бросающим тень на всех чернокнижников."}},faq={{q="Кто такой Ган'рул Кровавый Глаз?",a="Ган'рул Кровавый Глаз — старший учитель чернокнижников, обитающий в Расселине Теней под Оргриммаром. Он руководит обучением молодых чернокнижников Орды, показывая, как безопасно использовать темные силы и подчинять потусторонних слуг, не поддаваясь порче.",al={"gan'rul","ganrul bloodeye","who gives this quest","ган'рул","ганрул кровавый глаз","кто выдает это задание"}},{q="Что такое Табличка Верги?",a="Табличка Верги — реликвия с особыми рунами призыва, нужными, чтобы вызвать демона Бездны из Пустоты. Ее похитил культ Пылающего Клинка, и ее необходимо вернуть, чтобы Ган'рул мог провести новичка через ритуал.",al={"tablet of verga","verga tablet","what is the tablet","табличка верги","табличка верги где","что за табличка"}},{q="Где находится Скала Черепа?",a="Скала Черепа — темная пещера прямо к востоку от Оргриммара, среди неровных утесов Дуротара. Она служит тайным убежищем культистов Пылающего Клинка.",al={"skull rock location","where is skull rock","where to find tablet","где скала черепа","как найти скалу черепа","где искать табличку"}},{q="Почему Ган'рул Кровавый Глаз презирает Пылающий Клинок?",a="Культ Пылающего Клинка открыто служит демоническим господам и подрывает Орду Тралла. Ган'рул считает их невыносимой помехой для Вождя и безрассудной заразой, навлекающей подозрения и дурную славу на всех чернокнижников.",al={"burning blade warlock","why hate burning blade","чернокнижник пылающий клинок","почему ненавидеть пылающий клинок"}},{q="Зачем чернокнижникам призывать демона Бездны?",a="Демоны Бездны — существа Пустоты, способные выдерживать огромный урон и защищать призывателя. Овладение подчинением такого демона — важный шаг в практическом выживании и силе призыва чернокнижника.",al={"why voidwalker","voidwalker purpose","зачем демон бездны","назначение демона бездны"}},{q="Что происходит после возвращения таблички?",a="Когда Ган'рул получает Табличку Верги, он дает новичку нужные руны и призывает его завершить ритуал в задании «Связывание», где чернокнижник должен лично одолеть призванного демона Бездны, чтобы овладеть им.",al={"next quest","what comes next","следующее задание","что дальше"}}},fp="20,320,16.544.0,17.411.0,24.261.0,28.230.0,20.167.0,52.242.0,44.237.0,41.229.1"}
P.entries["quest:1502"] = {n="Тун'грим Огневзор",s="После начального обучения защитной тактике воины Орды направляются через Степи на поиски Тун'грима Огневзора. Этот замкнутый мастер-оружейник разбил лагерь на неровных хребтах Тернистого холма к востоку от Перекрестка. Найти его — обряд посвящения для бойцов, ищущих оружие, достойное их растущей мощи.",h="После начального обучения защитной тактике воины Орды направляются через Степи на поиски Тун'грима Огневзора.",kw={"blacksmith","crossroads","forged steel","the barrens","thorn hill","thun'grim firegaze","uzzek","warrior weapon","кузнец","перекресток","стальные слитки","степи","тернистый холм","тун'грим огневзор","уззек","оружие воина"},ang={["class:Warrior"]="Каждый молодой воин Орды отправляется в глушь на поиски Тун'грима и получает особое выкованное оружие в дополнение к боевой подготовке.",["faction:Horde"]="Орда полагается не только на численность, но и на умелые руки опытных мастеров, которые куют качественную сталь для солдат на передовой, защищающих Калимдор.",["profession:Blacksmithing"]="Тун'грим воплощает уединенную орочью традицию кузнечного дела: он терпит одиночество и слепоту ради искусства превращать раскаленный металл в смертоносные орудия."},sec={{t="Отшельник на хребте",b="Когда начинающий воин показывает мастерство в защитных искусствах под руководством опытных наставников вроде Уззека, ему велят отточить боевое мастерство подходящей сталью. Обычные оружейные доведут бойца передовой лишь до определенного предела; истинное мастерство требует личного оружия от кузнеца исключительной славы. В суровой саванне Степей таков Тун'грим Огневзор, стареющий орк-отшельник, покинувший поселения ради уединенной кузни высоко над равнинами."},{t="Жизнь в огне кузни",b="Чтобы добраться до Тун'грима, нужно подняться на Тернистый холм — зубчатую возвышенность к востоку от Перекрестка, где водятся дикие ящеры и враждебные свинобразы. Живя вдали от защиты городских стен, кузнец проводит одинокие часы, целиком посвящая их обработке металла. Десятилетия взглядов в раскаленное пламя кузни погубили его зрение, но чутье осталось острым. Когда странник поднимается на высоту и нарушает его уединение, Огневзор уже знает причину: пришел воин за стальными слитками."}},faq={{q="Кто посылает воинов к Тун'гриму Огневзору?",a="Задание дает Уззек, учитель воинов, стоящий у дороги возле Дальней заставы в восточных Степях, после того как вы докажете свою подготовку в защите.",al={"who gives this quest","who starts thun'grim firegaze","quest giver","кто выдает это задание","кто начинает тун'грим огневзор","персонаж, выдающий задания"}},{q="Где находится Тун'грим Огневзор?",a="Тун'грим живет в уединенном лагере на вершине Тернистого холма — высокого хребта прямо к востоку от Перекрестка в Степях.",al={"thun'grim location","where is thun'grim","find firegaze","где тун'грим","местонахождение тун'грима","найти огневзора"}},{q="Почему Тун'грим живет один в холмах?",a="Он посвятил жизнь исключительно работе с металлом вдали от городской суеты. Он трудится у наковальни в одиночестве на Тернистом холме, несмотря на опасных зверей и свинобразов, населяющих окрестные хребты.",al={"why is thun'grim a hermit","firegaze hermit","почему тун'грим отшельник","огневзор отшельник"}},{q="Что случилось с глазами Тун'грима Огневзора?",a="Десятилетия неустанной работы над раскаленными углями и взглядов прямо в жар кузни во многом иссушили и погубили его зрение.",al={"is thun'grim blind","firegaze eyes","тун'грим слепой","глаза огневзора"}},{q="Что будет после встречи с Тун'гримом Огневзором?",a="Когда вы доложите Тун'гриму, он поймет, что вам нужно оружие, и предложит задание «Стальные слитки»: нужно собрать сырье, чтобы он смог выковать оружие.",al={"next quest","what after thun'grim","forged steel follow up","следующее задание","что после тун'грима","стальные слитки продолжение"}},{q="Может ли любой класс взять это задание?",a="Нет. Эта цепочка заданий задумана как обряд посвящения именно для воинов Орды, ищущих особое оружие.",al={"is this warrior only","who can do thun'grim firegaze","только для воинов","кто может выполнить тун'грим огневзор"}}},fp="18,344,23.514.0,24.488.0,46.169.0,36.117.0,47.206.0,43.140.0,44.162.0,30.111.0"}
P.entries["quest:1503"] = {n="Стальные слитки",s="Орк-кузнец Тун'грим Огневзор просит помочь вернуть украденные металлические изделия из соседнего лагеря свинобразов. В обмен на возвращенные стальные слитки он предлагает выковать отличное оружие для растущего воина.",h="Орк-кузнец Тун'грим Огневзор просит помочь вернуть украденные металлические изделия из соседнего лагеря...",kw={"barrens","firegaze","forged steel","iron chest","quilboar","razormane","steel bars","thun'grim","warrior weapon","степи","огневзор","стальные слитки","железный сундук","свинобразы","иглогривые","тун'грим","оружие воина"},ang={["class:Warrior"]="Это задание — важный ранний обряд посвящения: воины учатся возвращать жизненно важные военные припасы и доказывают свою ценность, прежде чем получить первое выкованное на заказ оружие.",["faction:Horde"]="Племя Иглогривых постоянно досаждает линиям снабжения и одиноким лагерям по всем Степям, поэтому ответные набеги необходимы для защиты границ Орды.",["profession:Blacksmithing"]="Зависимость Тун'грима от качественной стали показывает постоянную потребность Орды в очищенном металле на суровой, бедной ресурсами границе Калимдора."},sec={{t="Использованная слепота",b="Тун'грим Огневзор устроил лагерь на неровных хребтах восточных Степей и живет там оружейником и кузнецом вдали от шумных кузниц Оргриммара. Несмотря на свой свирепый дух, возраст и суровые условия пустыни лишили его почти всего зрения. Заметив эту слабость, соседние свинобразы из племени Иглогривых прокрались в его лагерь под покровом темноты. Одни нарочно шумели и хрюкали с одной стороны, отвлекая его затуманенный взгляд, а шайка воров проскользнула с другой и унесла железный сундук с его запасом стальных слитков."},{t="Бесценный металл, глупые воры",b="Хотя Тун'грима привела в ярость унизительная кража, он почти не боялся, что Иглогривые с толком употребят металл. Мастерство свинобразов обычно держится на грубом камне, заостренных клыках и колючих корнях, а не на сложной металлургии. Тяжелый железный сундук остался цел и нетронут в их лагере возле сломанной повозки: свинобразам он совершенно бесполезен, но очень ценен для орка-оружейника, который ждет, чтобы выковать боевое снаряжение для молодых воинов Орды."}},faq={{q="Кто такой Тун'грим Огневзор?",a="Тун'грим Огневзор — опытный орк-оружейник и кузнец, живущий в небольшом лагере в восточных Степях. Несмотря на слабеющее зрение, он продолжает свое ремесло, помогает обучать и вооружать начинающих воинов Орды.",al={"thungrim firegaze","who is the smith","thungrim","тун'грим огневзор","кто кузнец","тун'грим"}},{q="Зачем свинобразы украли сталь?",a="Иглогривые свинобразы — хищные падальщики, которые постоянно нападают на путников и форпосты в Степях. Железный сундук они похитили во время ночного отвлекающего маневра, просто чтобы ограбить беззащитного кузнеца, но знаний кузнечного дела, чтобы обработать лежавшие в нем Стальные слитки, у них не было.",al={"why steal metal","why quilboar stole","what did razormane want","зачем красть металл","зачем свинобразы украли","чего хотели иглогривые"}},{q="Где хранятся стальные слитки?",a="Стальные слитки остаются запертыми в похищенном железном сундуке, брошенном возле сломанной повозки на землях свинобразов-Иглогривых к северо-западу от лагеря Тун'грима.",al={"where is the chest","stolen iron chest location","where are the bars","где сундук","местонахождение железного сундука","где слитки"}},{q="Какое оружие Тун'грим предлагает взамен?",a="В обмен на возвращенный запас отличной стали Тун'грим предлагает молодым воинам на выбор свежевыкованное оружие, которое поможет им в испытаниях по всему Калимдору.",al={"reward weapon","what do i get","forged steel reward","оружие в награду","что я получу","награда стальные слитки"}},{q="Как Иглогривым удалось обмануть Тун'грима?",a="Свинобразы воспользовались слабым зрением Тун'грима. Несколько налетчиков держались поодаль и громко хрюкали, отвлекая его внимание, а другие незаметно проникли в лагерь и утащили сундук.",al={"how did they rob him","how was thungrim robbed","distracted thungrim","как его обокрали","как ограбили тун'грима","отвлекли тун'грима"}},{q="Почему Тун'грим живет в Степях, а не в Оргриммаре?",a="Тун'грим держит уединенный аванпост в засушливых холмах над торговыми путями и служит оружейником и наставником для воинов, отправляющихся из Дуротара на обширные испытательные земли Степей.",al={"why is thungrim here","why barrens camp","почему тун'грим здесь","почему лагерь в степях"}}},fp="12,227,22.580.0,33.492.0,26.217.0,37.296.0,37.157.0,43.160.0,49.222.0,64.208.0"}
P.entries["quest:1506"] = {n="Призыв от Ган'рула",s="Призыв от Ган'рула — срочный вызов, который Офек в Колючем Холме передает молодым чернокнижникам Орды. Старший чернокнижник Ган'рул Кровавый Глаз требует их немедленного присутствия в Расселине Теней для продолжения обучения. Это первый шаг к овладению темным искусством призыва демона Бездны.",h="Призыв от Ган'рула — срочный вызов, который Офек в Колючем Холме передает молодым чернокнижникам Орды.",kw={"bloodeye","cleft of shadow","gan'rul","ophek","orgrimmar","summons","voidwalker","warlock quest","кровавый глаз","расселина теней","ган'рул","офек","оргриммар","призыв","демон бездны","задание чернокнижника"},ang={["class:Warlock"]="Этот призыв означает, что вы прошли дальше простого вызова бесов и теперь можете повелевать надежной защитой демона Бездны.",["faction:Horde"]="Чернокнижники занимают неспокойное место в новой Орде Тралла: их терпят за прагматичную силу, но держат глубоко под Оргриммаром."},sec={{t="Призыв во тьму",b="Начинающие чернокнижники в Дуротаре недолго остаются незамеченными. Когда практик показывает достаточное мастерство над своим первым бесом, весть доходит до глубоких подземелий Оргриммара. Офек, стоящий в Дуротаре, служит посланником старших темных заклинателей и перехватывает чернокнижников со срочным требованием бросить все дела и явиться в Расселину Теней."},{t="Старший чернокнижник",b="Ган'рул Кровавый Глаз руководит обучением молодых орков-чернокнижников Орды. Действуя из потайных пещер под Оргриммаром, он поддерживает хрупкий баланс между оттачиванием смертоносной сил скверны и сокрытием столь опасных искусств от неодобрительного взгляда Вождя. Когда Кровавый Глаз зовет ученика в свой круг, это значит, что простых огненных заклинаний и бесов уже мало: пора связать существо из Круговерти Пустоты."}},faq={{q="Кто такой Офек?",a="Офек — помощник чернокнижников, находящийся в Дуротаре. Он следит за растущими практиками и передает приказы старших наставников вроде Ган'рула Кровавого Глаза.",al={"ophek","who gives this quest","quest starter","офек","кто выдает это задание","начало задания"}},{q="Где находится Ган'рул Кровавый Глаз?",a="Ган'рул Кровавый Глаз обитает в Расселине Теней — темной системе подземных пещер, скрытой под скалистыми плато Оргриммара.",al={"where is ganrul","gan'rul location","find gan'rul bloodeye","где ган'рул","местонахождение ган'рула","найти ган'рула кровавого глаза"}},{q="Почему Ган'рул Кровавый Глаз хочет меня видеть?",a="Ган'рул счел, что вы достаточно опытны, чтобы продолжить обучение чернокнижника и начать опасные ритуалы, нужные для призыва и связывания демона Бездны.",al={"why summons","what does ganrul want","quest reason","зачем призыв","чего хочет ган'рул","причина задания"}},{q="Что будет после встречи с Ган'рулом?",a="Встреча с Ган'рулом начинает задание «Создание Бездны», которое отправляет вас за нужными компонентами и знаниями, чтобы призвать существо Бездны в Азерот.",al={"next quest","what comes after gan'rul's summons","следующее задание","что после призыва от ган'рула"}},{q="Почему чернокнижники остаются в Расселине Теней?",a="Чернокнижники практикуют переменчивую магию скверны, к которой Тралл и традиционная шаманская Орда относятся с глубоким подозрением. Расселина Теней позволяет им проводить ритуалы вдали от посторонних глаз.",al={"why cleft of shadow","why are warlocks hiding","warlock cave orgrimmar","почему расселина теней","почему чернокнижники прячутся","пещера чернокнижников оргриммар"}},{q="Может ли любой класс взять это задание?",a="Нет. Это задание предлагают только чернокнижникам Орды, достигшим десятого круга обучения.",al={"is this warlock only","who gets this quest","только для чернокнижников","кто получает это задание"}}},fp="17,290,24.399.0,18.455.0,13.157.0,34.132.0,41.147.0,40.163.0,48.182.0,30.108.0"}
P.entries["quest:1507"] = {n="Пожирательница душ",s="«Пожирательница душ» — первое задание на пути начинающего чернокнижника Орды, который хочет призвать и подчинить суккуба. Задание выдает Ган'рул Кровавый Глаз в глубине Расселины Теней и отправляет адепта через пещеру к древнему чернокнижнику Казулу, чтобы узнать, как приманить и связать этого коварного демона.",h="«Пожирательница душ» — первое задание на пути начинающего чернокнижника Орды, который хочет призвать и...",kw={"binding","cazul","cleft of shadow","gan'rul bloodeye","orgrimmar","succubus","summoning","warlock","привязывание","казул","расселина теней","ган'рул кровавый глаз","оргриммар","суккуб","призыв","чернокнижник"},ang={["class:Warlock"]="Это задание знаменует ваш переход к управлению демонами ментального господства и соблазна: оно требует не только силы Скверны, но и душевной стойкости.",["faction:Horde"]="В отличие от шаманов и воинов Орды Тралла, чернокнижники вынуждены проводить эти опасные обряды скрытно, в сырых уединенных расщелинах Расселины Теней."},sec={{t="Шаг в соблазнительные тени",b="Чернокнижники Орды, овладевшие младшими демонами, такими как бес и демон Бездны, рано или поздно доходят до предела, за которым грубой силы уже недостаточно. Ган'рул Кровавый Глаз, наставник темных искусств под Оргриммаром, решает, когда чернокнижник готов протянуть руку в Круговерть Пустоты за суккубом — созданием, известным тем, что оно обращает разум слабых против них самих. Связать такого демона можно лишь тонкими методами, а не одной силой."},{t="Знания Казула",b="Суккуб питается желаниями смертных, поэтому его нельзя призвать одними лишь заклинаниями: в наш мир его нужно заманить предметом, наполненным чистой любовью и преданностью. Ган'рул не хочет или не может предоставить такую реликвию сам, поэтому направляет призывателя к Казулу — древнему чернокнижнику, скрывающемуся в Расселине Теней. Его обширные познания в тайных и демонических обрядах помогут на следующем этапе ритуала."}},faq={{q="В чем смысл этого задания?",a="«Пожирательница душ» начинает цепочку заданий Орды, необходимых, чтобы изучить ритуал призыва суккуба. Она сводит вас с наставниками в Расселине Теней, которые расскажут о природе этого демона и о том, как выманить его из Круговерти Пустоты.",al={"why do devourer of souls","succubus quest start","what does this quest unlock","зачем пожирательница душ","начало задания суккуба","что открывает это задание"}},{q="Где найти Казула?",a="Казул находится в Расселине Теней — подземной пещере под Оргриммаром, где наставники разбойников и чернокнижников занимаются запретными искусствами вдали от глаз Вождя.",al={"cazul location","where is cazul","find cazul orgrimmar","казул где","где казул","найти казула оргриммар"}},{q="Почему чернокнижнику нужен предмет любви для призыва суккуба?",a="Суккубы — демоны-манипуляторы, питающиеся эмоциями смертных, их преданностью и слабой волей. Чтобы перетащить одного из них через завесу Круговерти Пустоты, призыватель должен предложить в качестве приманки мощный талисман искренней преданности и привязанности, а затем подавить и связать существо.",al={"succubus bait love","why love item for succubus","succubus summoning lore","приманка суккуба любовь","зачем предмет любви для суккуба","призыв суккуба предания"}},{q="Кто такой Ган'рул Кровавый Глаз?",a="Ган'рул Кровавый Глаз — старший наставник чернокнижников Орды, живущий в Расселине Теней в Оргриммаре. Он направляет начинающих чернокнижников через опасные обряды подчинения все более могущественных демонических слуг.",al={"who gives devourer of souls","gan'rul lore","ganrul bloodeye","кто дает пожирательницу душ","ган'рул предания","ган'рул кровавый глаз"}},{q="Какой уровень нужен для начала этого задания?",a="Чернокнижник должен достичь 20 уровня: только тогда Ган'рул Кровавый Глаз сочтет его магическое мастерство и силу духа достаточными, чтобы провести ритуал и пережить сделку с суккубом.",al={"what level for succubus","devourer of souls level","succubus chain level req","какой уровень для суккуба","пожирательница душ уровень","уровень цепочки суккуба"}},{q="Что происходит после разговора с Казулом?",a="Разговор с Казулом ведет к заданию «Слепой Казул», которое отправляет призывателя к Занкайе в Оргриммаре: ее спутник Догран не вернулся со службы на Перекрестке. С нее начинаются поиски подходящего символа любви.",al={"next quest after devourer of souls","what comes after cazul","succubus quest progression","следующее задание после пожирательницы душ","что после казула","продвижение цепочки суккуба"}}},fp="17,310,29.439.0,17.417.0,34.243.0,22.207.0,63.268.0,24.207.0,43.181.0,39.224.1"}
P.entries["quest:1508"] = {n="Слепой Казул",s="«Слепой Казул» — промежуточный этап испытания чернокнижников Орды по подчинению суккуба. Получив указание от предводителей круга в Расселине Теней, адепт ищет слепого чернокнижника Казула, который указывает на предмет сильных чувств, необходимый для ритуала.",h="«Слепой Казул» — промежуточный этап испытания чернокнижников Орды по подчинению суккуба.",kw={"blind cazul","cazul","cleft of shadow","dogran","orgrimmar","succubus","warlock","zankaja","слепой казул","казул","расселина теней","догран","оргриммар","суккуб","чернокнижник","занкайя"},ang={["class:Warlock"]="Это задание показывает, что демоническое призывание опирается на психологический резонанс не меньше, чем на магию Скверны: чтобы приманить суккуба, нужны проводники сильных чувств смертных.",["faction:Horde"]="Темные искусства, которые практикуют в глубинах Расселины Теней, существуют прямо под столицей Орды и тихо касаются жизней обычных жителей на плато выше."},sec={{t="Искусство приманки",b="Для подчинения демонического слуги мало одной силы воли: некоторых созданий Круговерти Пустоты нужно перетянуть через завесу их собственной жаждой. Суккуб, известный как пожирательница душ, охотно откликается на тоску, скорбь и неутоленные желания смертных. Казул хорошо это знает и сразу понимает, зачем к нему пришел начинающий призыватель."},{t="Глаза на утесах",b="Хотя Казул слеп, он чутко улавливает тихие жизни и трагедии в красных стенах Оргриммара. Вместо того чтобы сразу отправить чернокнижника в бой, он направляет его к орчанке по имени Занкайя, живущей на утесах возле гнезда наездников на ветрокрылах. Занкайя с тревогой ждет возвращения своего спутника Дограна, и в ее отчаянии демоны не могут не найти соблазн."}},faq={{q="Кто такой Казул?",a="Казул — слепой чернокнижник, действующий в Оргриммаре тихо. Он помогает чернокнижникам Расселины Теней, определяя реагенты и проводники для демонических призывов.",al={"blind cazul","who is cazul","слепой казул","кто такой казул"}},{q="Почему Казул отправляет вас к Занкайе?",a="Чтобы призвать и подчинить суккуба, адепту нужен предмет, пропитанный сильной тоской или любовью смертного. Занкайя в тревоге ждет пропавшего спутника Дограна, и ее личная связь с ним — ключ к получению эмоциональной приманки.",al={"why zankaja","what does zankaja have","почему занкайя","что есть у занкайи"}},{q="Где в Оргриммаре найти Занкайю?",a="Занкайя живет на возвышенных утесах Оргриммара, к западу от гнезда наездников на ветрокрылах. Чтобы дойти до нее, нужно пересечь мост от башни полетов и осмотреть ближайшие жилища справа.",al={"zankaja location","where is zankaja","занкайя где","где занкайя"}},{q="Что происходит после разговора с Занкайей?",a="Занкайя в отчаянии: ее спутник Догран пропал. Разговор с ней отправляет чернокнижника в Степи на поиски вестей о его судьбе и начинает цепочку заданий по добыче могущественного символа любви.",al={"what comes next","next step after cazul","что дальше","следующий шаг после казула"}},{q="Какого демона призывает это задание?",a="Это поручение — часть обряда посвящения для призыва и порабощения суккуба, демонического слуги, владеющего соблазном и разрушительной пыткой разума.",al={"which pet","demon reward","какой питомец","награда демон"}},{q="Почему чернокнижники используют чужие трагедии в своих ритуалах?",a="Младших демонов вроде суккуба влекут сильные чувства смертных — прежде всего страсть, преданность и душевная боль. Чернокнижники намеренно используют предметы, отмеченные горем или желанием, как духовную приманку во время ритуала призыва.",al={"warlock morality","why use dogran","мораль чернокнижников","зачем использовать дограна"}}},fp="11,268,22.367.0,18.414.0,13.171.0,35.236.0,40.194.0,39.193.0,57.136.0,63.238.0"}
P.entries["quest:1509"] = {n="Вести о Догране",kw={"barrens","cazul","crossroads","dogran","gazrog","news of dogran","quilboar","succubus","zankaja","степи","казул","перекресток","догран","газрог","вести о догране","свинобраз","суккуб","занкайя"},ang={["class:Warlock"]="Этот отрезок пути переводит ваше обучение от темных текстов в Оргриммаре к использованию настоящей людской трагедии ради получения суккуба.",["race:Orc"]="Тихое горе Занкайи показывает, какой личной ценой оплачены расширение и оборона Орды в Дуротаре и Степях."},sec={{t="Отчаяние спутницы",b="На утесах Оргриммара Занкайя в тихом ужасе ждет. Ее спутника Дограна направили на Перекресток с почетным повышением, но срок его возвращения давно прошел, а вестей нет. Не зная о темных искусствах, дергающих за ниточки, она обращается к сочувствующему путнику с просьбой узнать ответы у его командира Газрога."},{t="Мрачные вести в Степях",b="Когда вы добираетесь до центрального поселения — Перекрестка, правда оказывается мрачной. Дограна задержали не просто дела службы: он попал в руки свирепых свинобразов, наводнивших равнины. Газрог признает, что Догран еще жив, но его плен — жестокая реальность, которую он не решается передать Занкайе."},{t="Орудие призыва",b="Для начинающего чернокнижника трагедия Дограна — не просто спасательная операция. Чтобы призвать и подчинить суккуба — создание, связанное необузданной страстью, отчаянием и мукой, — нужны реликвии, тронутые настоящими чувствами. Страдания Дограна и его связь с Занкайей дают именно тот эмоциональный проводник, который нужен для ритуала подчинения."}},faq={{q="Кто такой Догран?",a="Dogran is an orc grunt stationed in the Barrens who recently earned a promotion to the Crossroads. He is also the mate of Zankaja, an orc woman living in Orgrimmar.",al={"dogran lore","who is dogran","grunt dogran"}},{q="Почему чернокнижника заботит пропавший орк-стражник?",a="Наставники чернокнижников в Расселине Теней организуют эти поиски, потому что для ритуала подчинения суккуба нужны предметы, пропитанные глубокими чувствами смертных — любовью, преданностью и страданием.",al={"why warlock quest","why do warlocks do this","succubus connection","зачем задание чернокнижника","зачем чернокнижники это делают","связь с суккубом"}},{q="Где находится Газрог?",a="Газрог служит на Перекрестке в Степях и является одним из главных представителей власти Орды, отвечающих за оборону от местных угроз.",al={"where is gazrog","gazrog location","crossroads gazrog","где газрог","газрог где найти","перекресток газрог"}},{q="Что случилось с Дограном?",a="Догран давно должен был вернуться к Занкайе. Она просит вас узнать новости у Газрога на Перекрестке.",al={"is dogran dead","where is dogran","dogran fate","мертв ли догран","где догран","судьба дограна"}},{q="Кто выдает это задание?",a="Задание выдает Занкайя на утесах Оргриммара, после того как к ней направит наставник чернокнижников Казул.",al={"quest giver","where to start news of dogran","персонаж, выдающий задание","где начать вести о догране"}},{q="Что дальше в цепочке заданий?",a="Продолжайте расспросы в Степях, чтобы узнать судьбу Дограна и передать новости дальше.",al={"what next","next quest","succubus chain continuation","что дальше","следующее задание","продолжение цепочки суккуба"}}},fp="14,360,16.351.0,27.315.1,26.330.1,14.164.0,50.192.0,24.141.0,24.96.1,21.115.0,29.88.1"}
P.entries["quest:151"] = {n="Бедная старая Савраска",s="«Бедная старая Савраска» — задание, которое выдает Верна Хмуробров на главной дороге в Западном Крае. Когда их повозка сломалась во время попытки бегства, Хмуробровы обнаружили, что их пожилая кобыла истощена и голодна. Приключенцев просят собрать разбросанные мешки овса на заброшенных фермах поблизости, чтобы накормить измученное животное.",h="«Бедная старая Савраска» — задание, которое выдает Верна Хмуробров на главной дороге в Западном Крае.",kw={"harvest golem","horse","oats","old blanchy","poor old blanchy","verna furlbrow","wagon","westfall","жнец-голем","лошадь","овес","старая савраска","бедная старая савраска","верна хмуробров","повозка","западный край"},ang={["class:Hunter"]="Забота об измученной рабочей лошади подчеркивает связь между трудовым людом и животными, что верно несут их ношу.",["faction:Alliance"]="Застрявшие Хмуробровы показывают, как отчаянно забыты сельские подданные-люди, пока столица парализована политическим застоем."},sec={{t="Семья на обочине",b="Путники, идущие по пыльной дороге Западного Края, встречают Верну и Фермера Хмуроброва, застрявших на обочине. Как и многие работящие семьи региона, Хмуробровы лишились дома из-за разгула бандитов и взбесившихся механических жнецов-големов. Пытаясь вывезти пожитки в безопасное место, они потерпели серьезную поломку повозки и остались посреди глухой местности."},{t="Забота о верной кобыле",b="В центре их беды — Старая Савраска, почтенная рабочая кобыла, которая долгие сезоны служила семье на пахоте и в перевозках. Измученная тяжестью перегруженной повозки и голодом из-за неожиданной задержки, кроткая лошадь быстро слабеет. Верна умоляет прохожих проникнуть на ближайшие разоренные фермы и найти уцелевшие мешки зерна, рискуя столкнуться с враждебными молотилками и гноллами-мародерами, лишь бы дать верному животному достойную еду."}},faq={{q="Кто такая Старая Савраска?",a="Старая Савраска — любимая немолодая рабочая лошадь семьи Хмуробровых. Много лет она возила их плуги и повозки по Западному Краю, а теперь, после поломки оси, измучена и застряла у дороги.",al={"who is blanchy","what is old blanchy","blanchy lore","кто такая савраска","что такое старая савраска","савраска предания"}},{q="Почему сломалась повозка Хмуробровых?",a="Хмуробровы пытались бежать с фермы со всем скарбом, но повозка не выдержала нагрузки. Теперь они застряли у дороги, беззащитные перед бандитами и бродящими зверями.",al={"why are they stuck","furlbrow wagon","broken wagon road","почему они застряли","повозка хмуробровых","сломанная повозка на дороге"}},{q="Откуда берется овес?",a="Мешки с овсом до сих пор разбросаны по полям и хозяйственным постройкам захваченных ферм Западного Края: их бросили поселенцы, бежавшие от взбесившихся жнецов и бандитов.",al={"where are oats","find oats","sacks of oats","где овес","найти овес","мешки с овсом"}},{q="Какие угрозы охраняют зерно на полях?",a="Поля к юго-западу от дороги страдают от взбесившихся механических жнецов-сторожей и бродячих банд гноллов Речной Лапы, разоряющих опустевшие амбары.",al={"what attacks at farms","farm dangers","harvest golems oats","кто нападает на фермах","опасности ферм","жнецы-големы овес"}},{q="Почему семья не уведет Старую Савраску в безопасное место?",a="Старая Савраска совершенно выбилась из сил и голодает, она не может ни тянуть повозку, ни идти далеко без еды, а Хмуробровы не хотят бросать ни верную кобылу, ни свое добро.",al={"why stay with wagon","can horse walk","why not go sentinel hill","почему остаются у повозки","может ли лошадь идти","почему не идти в дозорный холм"}},{q="Помогает ли Штормград фермерам вроде Хмуробровых?",a="Королевский двор Штормграда почти не дает защиты и помощи поселенцам Западного Края. Сельским жителям в основном приходится справляться самим или полагаться на едва держащееся Народное ополчение.",al={"stormwind help westfall","where are guards","alliance aid westfall","штормград помощь западный край","где стража","помощь альянса западный край"}}},fp="16,322,20.393.0,27.460.0,19.210.0,38.200.0,28.167.0,43.163.0,50.179.0,54.190.0"}
P.entries["quest:1510"] = {n="Вести о Догране",s="Это задание отправляет авантюристов Орды в предгорья Когтистых гор на встречу с троллем из племени Черного Копья Кен'зиглой в Малака'джине. Раненый рубака из Лагеря Таурахо по имени Догран лежит при смерти, а первый посыльный, отправленный за целебным травяным зельем, так и не вернулся.",h="Это задание отправляет авантюристов Орды в предгорья Когтистых гор на встречу с троллем из племени Черного...",kw={"camp taurajo","dogran","gazrog","ken'zigla","malaka'jin","quilboar","stonetalon","лагерь таурахо","догран","газрог","кен'зигла","малака'джин","свинобраз","когтистые горы"},ang={["class:Warlock"]="То, что кажется обычной военной миссией милосердия, на деле — важное испытание, подготовленное Казулом и чернокнижниками Оргриммара: оно подводит вас к эмоциональному отклику, необходимому, чтобы подчинить суккуба.",["faction:Horde"]="Этот отрезок пути показывает, насколько тонки и хрупки цепи снабжения, связывающие отдаленные форпосты вроде Лагеря Таурахо с изолированными лагерями вроде Малака'джина, когда им угрожают свинобразы и гоблины."},sec={{t="Мольба через пограничье",b="Догран, рубака Орды из Лагеря Таурахо на юге Степей, был тяжело ранен в стычке с укрепившимися свинобразами. Товарищи сумели удержать его на месте, но из-за гноящихся ран любая тряская перевозка через равнины убила бы его. Отчаянно нуждаясь в сильном лекарстве, в Таурахо отправили весть на север, в Когтистые горы, в надежде получить традиционное целебное зелье, которое готовят тролли джунглей Малака'джина."},{t="Кровопролитие в Малака'джине",b="Прибыв к скалам Малака'джина, путники обнаруживают, что спасательная миссия почти сразу провалилась. Первый посыльный, отправленный за лекарством, попал в засаду и был убит местными гоблинами Торговой Компании, так и не получив зелья. Кен'зигла по-прежнему владеет нужным Дограну средством, но чтобы получить его, придется столкнуться с непредсказуемыми опасностями пограничья у проходов Когтистых гор."}},faq={{q="Кто такой Догран и почему он ранен?",a="Догран — орк-рубака из Лагеря Таурахо. Возглавляя отряд, который зачищал агрессивные лагеря свинобразов на юге Степей, он получил тяжелые гноящиеся раны, из-за которых его нельзя было перевозить без немедленной медицинской помощи.",al={"who is dogran","why is dogran hurt","dogran story","кто такой догран","почему ранен догран","история дограна"}},{q="Где находится Малака'джин?",a="Малака'джин — небольшой форпост троллей Черного Копья у скалистого подножия Когтистых гор, сразу за северо-западной границей Степей.",al={"malakajin location","where is malakajin","find ken'zigla","малака'джин расположение","где малака'джин","найти кен'зиглу"}},{q="Что случилось с первым посыльным, отправленным за зельем?",a="Первый посыльный, отправленный из Таурахо за зельем Кен'зиглы, попал в засаду и был убит гоблинами Торговой Компании, действовавшими на дороге у предгорий Когтистых гор.",al={"first runner","what happened to the messenger","dead courier","первый посыльный","что случилось с посыльным","убитый гонец"}},{q="Почему судьба Дограна волнует наставников чернокнижников?",a="Новичков-чернокнижников направляют к беде Дограна под видом поручения для Слепого Казула и Газрога, но в итоге это испытание приводит их к артефакту, полному любви и душевной боли, который нужен, чтобы призвать и подчинить суккуба.",al={"warlock quest connection","succubus dogran","why warlocks do this","связь с заданием чернокнижника","суккуб догран","зачем чернокнижникам это"}},{q="Кто такой Кен'зигла?",a="Кен'зигла — тролль из племени Черного Копья, алхимик и травник, живущий в поселении Малака'джин в Когтистых горах и умеющий варить сильные зелья из лесных трав.",al={"who is kenzigla","kenzigla stonetalon","ken'zigla","кто такой кен'зигла","кен'зигла когтистые горы","кен'зигла"}},{q="Почему Дограна нельзя было сразу отвезти в город?",a="Раны Дограна сильно загноились после схватки со свинобразами. Его товарищи опасались, что тряска по неровным дорогам Степей к опытному целителю убьет его раньше, чем он туда доберется.",al={"why not move dogran","dogran wounds","why camp taurajo left him","почему не перевезти дограна","раны дограна","почему лагерь таурахо оставил его"}}},fp="14,283,26.445.0,23.407.1,33.256.0,28.150.0,58.181.0,49.233.1,17.160.0,49.213.0"}
P.entries["quest:1511"] = {n="Зелье Кен'зиглы",s="Зелье Кен'зиглы — срочное курьерское задание в цепочке чернокнижников Орды на призыв суккуба. Получив сильное целебное снадобье из Малака'джина в Когтистых горах, чернокнижник должен спешно пересечь Калимдор и добраться до Лагеря Таурахо, чтобы спасти бойца по имени Догран.",h="Зелье Кен'зиглы — срочное курьерское задание в цепочке чернокнижников Орды на призыв суккуба.",kw={"barrens","dogran","draught","ken'zigla","logmar","stonetalon","succubus","taurajo","степи","догран","зелье","кен'зигла","логмар","когтистые горы","суккуб","таурахо"},ang={["class:Warlock"]="Этот отрезок пути — испытание терпения и находчивости: чтобы повелевать существом необузданного желания и соблазна, вы должны сначала исцелить сломленного смертного, который хранит залог подчинения.",["faction:Horde"]="Показывает, насколько растянуты снабжение и связь молодой Орды в центре Калимдора, где изолированные форпосты в Когтистых горах и Степях полагаются на путников, которые доставляют важные вести и медицинскую помощь."},sec={{t="Спасительное варево",b="В скалах Когтистых гор тролль-аптекарь Кен'зигла предчувствовал беду. Зная, что прежний посланник, отправленный за лекарством для пропавшего разведчика Дограна, не вернулся, Кен'зигла приготовил вторую порцию своего сильного укрепляющего зелья. Снадобье мощное и опасное: половина дозы дает смертельно раненному бойцу силы двигаться, не истекая кровью, а остальное нужно приберечь до следующего дня для полного выздоровления."},{t="Встреча в Лагере Таурахо",b="Вынеся зелье из гор в южные Степи, чернокнижник направляется к Рубаке Логмару в Лагере Таурахо. Логмар владеет важными сведениями о том, где находится Догран, но его гарнизон обескровлен из-за добывающих экспедиций. Пока Догран в плену и истекает кровью на вражеской земле, доставка зелья в Таурахо становится последней подготовкой к спасательной операции."}},faq={{q="Для чего предназначено Зелье Кен'зиглы?",a="Это сильное лекарственное варево, созданное Кен'зиглой, чтобы поставить на ноги раненого орка Дограна. Его дают двумя дозами: первая половина дает раненому достаточно сил, чтобы двигаться, не открывая смертельных ран, а вторая завершает исцеление.",al={"what is the draught","kenziglas draught purpose","why make draught","что такое зелье","зелье кен'зиглы назначение","зачем варить зелье"}},{q="Кто такой Кен'зигла?",a="Кен'зигла — тролль-аптекарь, живущий в Когтистых горах. Он поставляет особые алхимические смеси и снадобья агентам Орды, действующим в этой местности.",al={"kenzigla lore","who is kenzigla","предания о кен'зигле","кто такой кен'зигла"}},{q="Почему Рубака Логмар ждет в Лагере Таурахо?",a="Рубака Логмар несет службу в Лагере Таурахо на юге Степей. Он следит за передвижениями местных разведчиков и располагает последними сведениями о том, где пропал Догран, но у него не хватает рубак, чтобы самому организовать спасение.",al={"who is grunt logmar","logmar taurajo","grunt logmar role","кто такой рубака логмар","логмар таурахо","роль рубаки логмара"}},{q="Как это задание связано с призывом суккуба?",a="Чтобы призвать и подчинить суккуба, чернокнижникам Орды в Оргриммаре нужен кулон Дограна — артефакт, пронизанный страстью и преданностью. Чтобы добыть кулон, нужно найти Дограна и спасти ему жизнь с помощью зелья Кен'зиглы.",al={"why succubus quest draught","succubus chain dogran","зачем зелье в задании суккуба","цепочка суккуба догран"}},{q="Почему первый посыльный не доставил зелье?",a="Первый посыльный, отправленный в Когтистые горы, так и не выполнил задание, и Кен'зигла приготовил запасную дозу для следующего искателя приключений, который будет разыскивать Дограна.",al={"what happened to first messenger","previous courier","что случилось с первым посыльным","прежний посыльный"}},{q="Куда ведет след после Лагеря Таурахо?",a="Получив зелье, Рубака Логмар указывает чернокнижнику на похитителей Дограна на юге Степей, где умирающий разведчик удерживается в плену.",al={"where is dogran","next step after logmar","где догран","следующий шаг после логмара"}}},fp="19,273,18.489.0,26.399.1,40.261.0,17.170.0,44.218.0,52.223.0,47.167.0,43.147.1"}
P.entries["quest:1512"] = {n="Дар любви",s="Дар любви — предпоследнее задание в цепочке чернокнижников Орды на призыв и подчинение суккуба. После того как его находят и возвращают к жизни в Степях, умирающий Рубака Догран отдает бесценную памятную вещь, которая послужит приманкой для темного ритуала.",h="Дар любви — предпоследнее задание в цепочке чернокнижников Орды на призыв и подчинение суккуба.",kw={"dirt-caked pendant","gan'rul bloodeye","grunt dogran","love's gift","orgrimmar","succubus","the barrens","zankaja","грязный кулон","ган'рул кровавый глаз","рубака догран","дар любви","оргриммар","суккуб","степи","занкайя"},ang={["class:Warlock"]="Подчинение суккуба учит чернокнижников, что демонов не просто призывают тайной силой, но и улавливают, играя на их жажде необузданных смертных страстей, таких как любовь и горе.",["faction:Horde"]="Рубака Догран воплощает суровый воинский дух Орды: он предпочитает умереть на поле боя, а не жить обузой для своих сородичей."},sec={{t="Жертва рубаки",b="Найденного в плену у свинобразов Дыбогривов в Степях, где его пытали, Рубаку Дограна возвращает в сознание зелье Кен'зиглы. Понимая, что его тело разбито безвозвратно, Догран решает встретить смерть в славном бою, а не вернуться к своей подруге Занкайе калекой. Он отдает покрытый грязью кулон — дар, рожденный чистой любовью, — и просит лишь, чтобы она никогда не узнала, чем он пожертвовал."},{t="Приманка для демона",b="Чтобы призвать и подчинить суккуба, чернокнижнику нужен талисман сильного, незапятнанного чувства. Суккубы питаются смертным желанием и обращают подлинную привязанность в муку. Кулон Дограна несет в себе вес настоящей преданности и трагической разлуки. После возвращения к Ган'рулу Кровавому Глазу в сумрачных расселинах Оргриммара талисман чистят и полируют, чтобы его сияющий эмоциональный отклик сумел заманить пожирательницу душ через Круговерть Пустоты."}},faq={{q="Почему чернокнижнику нужен кулон Дограна?",a="Суккубы — демонические существа, привлеченные глубокими смертными страстями, которые они искажают и поглощают. Кулон Дограна воплощает самоотверженную любовь и искреннюю жертву, поэтому он — идеальная магическая приманка, чтобы заманить суккуба в круг призыва.",al={"why pendant","succubus bait","why dirt-caked pendant","зачем кулон","приманка для суккуба","зачем грязный кулон"}},{q="Кто такой Рубака Догран?",a="Догран — воин Орды, попавший в плен к свинобразам Дыбогривам на юге Степей и подвергнутый жестоким пыткам. Хотя его спасли и вернули к жизни алхимическим снадобьем, тяжелые раны не позволяют ему жить как гордому воину.",al={"who is dogran","grunt dogran lore","кто такой догран","предания о рубаке догране"}},{q="Кто такая Занкайя?",a="Занкайя — молодая подруга Дограна, тревожно ждавшая вестей о нем. Чтобы избавить ее от горя и бремени ухода за сломленным телом, Догран решает отдать ее залог любви и искать смерть воина.",al={"zankaja lore","dogran mate","предания о занкайе","подруга дограна"}},{q="Почему Догран просит вас скрыть это от Занкайи?",a="Догран не хочет привязывать молодую подругу к умирающему калеке. Он отдает ее кулон, зная, что тот к ней не вернется, но умоляет избавить ее от вины за то, как закончилась его судьба.",al={"why not tell zankaja","dogran secret","почему не рассказать занкайе","тайна дограна"}},{q="Кто чистит кулон и зачем?",a="Кулон забирает Ган'рул Кровавый Глаз, наставник чернокнижников в Оргриммаре. Он счищает грязь и налет, чтобы яркий, безупречный вид кулона и его эмоциональный отклик оказались непреодолимы для призванного демона.",al={"gan'rul bloodeye role","why clean the pendant","роль ган'рула кровавого глаза","зачем чистить кулон"}},{q="Что происходит сразу после выполнения этого задания?",a="Ган'рул Кровавый Глаз велит вам принести очищенный кулон в круг призыва под Оргриммаром, провести ритуал подчинения и победить суккуба в одиночном бою.",al={"what comes next","next quest after love's gift","что дальше","следующее задание после дара любви"}}},fp="11,255,19.408.1,16.446.0,41.239.0,20.229.0,15.206.1,57.188.1,31.210.0,53.171.1"}
P.entries["quest:1513"] = {n="Связывание",s="Связывание — последнее испытание начинающего чернокнижника Орды на пути к порабощению суккуба в Оргриммаре. Используя преданность, заключенную в подвеске Дограна, в призывном круге Нииру Огненного Клинка чернокнижник вырывает демона из Круговерти Пустоты и ломает его волю силой оружия и чар.",h="Связывание — последнее испытание начинающего чернокнижника Орды на пути к порабощению суккуба в Оргриммаре.",kw={"binding","cleft of shadows","dogran","gan'rul","neeru","orgrimmar","pendant","succubus","warlock","zankaja","связывание","расселина теней","догран","ган'рул","нииру","оргриммар","подвеска","суккуб","чернокнижник","занкайя"},ang={["class:Warlock"]="Этот обряд знаменует переход чернокнижника к повелению хитрыми, непокорными демонами и доказывает, что личная сила воли способна одолеть соблазнительные опасности Пустоты.",["faction:Horde"]="Тайно проводимый в Расселине Теней ритуал показывает неловкую терпимость Орды Тралла к практикам демонопоклонников, скрытым от жителей города, чтящих честь.",["race:Orc"]="Для орков общение с демоническими существами несет горький груз прошлого порчи их народа, поэтому дисциплина и самоконтроль, которых требует Ган'рул, особенно пронзительны."},sec={{t="Якорь для демона",b="Чтобы дотянуться через миры и подчинить суккуба, призывателю нужен якорь — проводник, настроенный на природу этого существа. Такой темной цели служит подвеска, которую отдал искалеченный орк Догран. Эта памятная вещь о его любви к Занкайе, пронесенная через плен и муки, хранит эмоциональный отклик, необходимый, чтобы перекинуть мост через Круговерть Пустоты и привлечь внимание демона."},{t="Круг в тенях",b="Под ущельями Оргриммара, в глубине палатки Нииру Огненного Клинка, находится призывный круг, подготовленный для такой опасной работы. Под руководством Ган'рула Кровавого Глаза чернокнижник активирует круг с начертанными рунами и сражается с призванной соблазнительницей. Чернокнижник не может просто призвать демона на службу: он должен одолеть его в поединке, подчинив его злобный дух своей верховной воле."},{t="Уловки и сила воли",b="Как предупреждает Ган'рул, суккубы — опасные рабыни. Их присутствие пьянит и искушает чувства, а неосторожных хозяев они неуклонно лишают жизненных сил и духа. Ган'рул велит чернокнижнику помнить о горе Дограна и Занкайи как о защите от уловок демона: гордыня и излишняя самоуверенность погубили немало многообещающих чернокнижников. Истинное мастерство требует несгибаемой воли, которая никогда не поддается чарам демона."}},faq={{q="Что происходит во время этого ритуала?",a="Чернокнижник приносит подвеску Дограна в призывный круг в палатке Нииру Огненного Клинка в Расселине Теней. Используя преданность, заключенную в талисмане, призыватель вызывает суккуба из Круговерти Пустоты и сражается с ним до покорности, чтобы установить полную власть над существом.",al={"how does the ritual work","what do you do in the binding","succubus ritual","как работает ритуал","что делать в связывании","ритуал суккуба"}},{q="Где проходит призыв?",a="Призыв проходит в Расселине Теней в Оргриммаре, в палатке Нииру Огненного Клинка, где на полу постоянно начертан ритуальный круг.",al={"where is the circle","summoning circle location","where do i summon the succubus","где круг","расположение призывного круга","где призвать суккуба"}},{q="Кем был Догран и зачем нужна его подвеска?",a="Догран был рубакой Орды, которого захватили в плен и искалечили свинобразы в Степях. Его подвеска, памятная вещь о возлюбленной Занкайе, служит главным средоточием, необходимым, чтобы привлечь и удержать суккуба.",al={"who is dogran","why dograns pendant","dogran story","кто такой догран","зачем подвеска дограна","история дограна"}},{q="Кто такой Ган'рул Кровавый Глаз?",a="Ган'рул Кровавый Глаз — старший учитель чернокнижников, живущий в Расселине Теней под Оргриммаром. Он наставляет подающих надежды последователей темных искусств и ведет их через опасные обряды подчинения демонов.",al={"who gives the quest","who is ganrul","ganrul bloodeye role","кто выдает задание","кто такой ган'рул","роль ган'рула кровавого глаза"}},{q="Какую силу получает чернокнижник после этого испытания?",a="Подчинение существа завершает обучение чернокнижника и дает тайные знания и власть над рунами, необходимые, чтобы в любой момент призвать суккуба себе на службу.",al={"what reward do warlocks get","why summon succubus","succubus pet ability","какую награду получают чернокнижники","зачем призывать суккуба","способность питомца суккуба"}},{q="Почему призыв суккуба считается особенно опасным?",a="Суккубы владеют мощными чарами и играют на желаниях смертных. Самоуверенные чернокнижники рискуют тем, что их души будут медленно высосаны: они поддаются тонкому коварству демона, вместо того чтобы повелевать им.",al={"succubus danger","why are succubi risky","succubus lore","опасность суккуба","чем опасны суккубы","предания о суккубах"}}},fp="11,305,16.391.1,25.401.0,19.425.1,32.298.0,36.173.0,45.203.1,24.210.0,58.171.0,60.203.0"}
P.entries["quest:1515"] = {n="Догран в плену",s="Догран в плену — важное испытание в обучении начинающего чернокнижника Орды: оно отправляет его в самое сердце лагеря свинобразов, чтобы спасти плененного воина-орка. Получив восстанавливающее снадобье, чернокнижник должен найти измученного Рубаку Дограна и дать ему силы, чтобы бежать от захватчиков.",h="Догран в плену — важное испытание в обучении начинающего чернокнижника Орды: оно отправляет его в самое...",kw={"barrens","dogran","draught","ken'zigla","logmar","quilboar","succubus","taurajo","warlock","степи","догран","зелье","кен'зигла","логмар","свинобраз","суккуб","таурахо","чернокнижник"},ang={["class:Warlock"]="Это спасение — важный шаг к пониманию страсти и жертвенности смертных, необходимых для призыва суккуба.",["faction:Horde"]="Беда Дограна показывает постоянную опасность, которую свинобразы представляют для патрулей и застав Орды по всем центральным Степям.",["race:Orc"]="Даже перед лицом увечий и пыток в руках свинобразов выносливость Дограна демонстрирует стойкость, ожидаемую от орка-рубаки."},sec={{t="Одинокое спасение",b="Рубака Логмар в Лагере Таурахо отказывается рисковать воинами Орды ради дорогого налета на укрепившихся свинобразов, и судьба его товарища Дограна целиком оказывается в руках предприимчивого чернокнижника. Вооруженный лишь Зельем Кен'зиглы, спаситель должен отправиться на север, через колючие заросли и вражеские лагеря, чтобы найти место, где держат Дограна."},{t="Цена крови",b="Дограна находят жестоко избитым, в окружении враждебных свинобразов, в группе хижин к северу от Таурахо. Горькое зелье дает ровно столько сил, чтобы воин смог уковылять в безопасное место, но спасение обходится дорого: тяжелые раны навсегда калечат Дограна, и он теряет руку и ногу."}},faq={{q="Где держат Рубаку Дограна?",a="Рубаку Дограна держат в плену в небольшой группе из двух хижин свинобразов прямо к северу от Лагеря Таурахо в Степях.",al={"dogran location","where is dogran","find dogran barrens","где догран","расположение дограна","найти дограна степи"}},{q="Почему Рубака Логмар не посылает солдат на помощь?",a="Рубака Логмар не может выделить ни одного бойца из обороны Лагеря Таурахо: он считает спасательную вылазку на сильно охраняемую территорию свинобразов слишком рискованной, чтобы жертвовать новыми жизнями воинов.",al={"why no horde guard help","logmar soldiers","taurajo reinforcements","почему орда не помогает","солдаты логмара","подкрепление таурахо"}},{q="Что такое Зелье Кен'зиглы?",a="Это сильное восстанавливающее снадобье с отвратительным вкусом, сваренное специально для того, чтобы дать тяжело раненному Дограну достаточно сил встать и бежать из плена свинобразов.",al={"kenzigla potion","what is the draught","dogran medicine","зелье кен'зиглы","что за зелье","лекарство дограна"}},{q="В каком состоянии находят Дограна?",a="Догран при смерти: он получил множество ран и пережил пытки от рук свинобразов. Даже после того как он выпивает зелье, его рука и нога повреждены безвозвратно.",al={"dogran injuries","is dogran alive","dogran arm leg","раны дограна","жив ли догран","рука и нога дограна"}},{q="Как это спасение связано с призывом суккуба?",a="У Дограна есть памятная вещь, связанная с любовью и преданностью смертного — чувствами и понятиями, которыми чернокнижники пользуются, чтобы призвать суккуба и подчинить его своей воле.",al={"why do warlocks do this","succubus quest connection","warlock quest dogran","зачем это чернокнижникам","связь с заданием суккуба","задание чернокнижника догран"}},{q="Кто взял Дограна в плен?",a="Его взяли в плен местные племена свинобразов, обитающие в зарослях к северу от Лагеря Таурахо.",al={"who took dogran","dogran captors","barrens kidnappers","кто похитил дограна","захватчики дограна","похитители в степях"}}},fp="18,321,15.354.0,18.331.1,27.115.0,45.191.0,28.166.0,39.183.1,52.148.1,20.97.0"}
P.entries["quest:1516"] = {n="Зов Земли",kw={"burning blade","call of earth","canaga earthcaller","earth totem","felstalker","sapta","shaman trial","valley of trials","пылающий клинок","зов земли","канага заклинатель земли","тотем земли","ловчий","сапта","испытание шамана","долина испытаний"},ang={["class:Shaman"]="Этот обряд знаменует ваше первое формальное единение со стихиями и закладывает основу для вашего Тотема земли.",["race:Orc"]="При Орде Тралла возвращение на путь шаманов чтит древние традиции кланов, существовавшие до демонической порчи.",["race:Troll"]="Знахари и духовидцы Черного Копья обращаются к духам земли, чтобы поддержать свой новый дом рядом с орками."},sec={{t="Первая связь",b="Прежде чем шаман сможет взывать к стихиям, он должен выстроить прочные отношения с каждой из них по очереди. В культуре орков и троллей этот духовный путь начинается с земли — основы жизни, выносливости и терпения. Канага заклинатель земли наставляет новичков в Долине Испытаний, учит, что земля требует высшего уважения и стойкости, прежде чем даровать свою защиту."},{t="Очистительная охота",b="Чтобы показать готовность общаться с упрямыми духами земли, посвящаемых отправляют в северные ущелья, где гнездится культ Пылающего Клинка. Охотясь на демонических гончих — порченых существ иных миров, призванных темной магией, — шаман доказывает, что способен защитить землю от неестественной порчи. Из собранных копыт Канага варит Сапту земли — священный отвар, открывающий глаза смертных на мир стихий."}},faq={{q="В чем смысл этого испытания?",a="Испытание посвящает шамана в тайны стихий и доказывает духам земли его терпение и духовную дисциплину, чтобы со временем он мог общаться с ними напрямую и обрести Тотем земли.",al={"why do call of earth","what does call of earth give","purpose of quest","зачем зов земли","что дает зов земли","смысл задания"}},{q="Кто такой Канага заклинатель земли?",a="Канага заклинатель земли — тролль, учитель шаманов, живущий в Долине Испытаний в Дуротаре. Он ведет юных шаманов-орков, троллей и приезжих тауренов по первым шагам к власти над стихиями.",al={"who is canaga","canaga earthcaller lore","кто такой канага","канага заклинатель земли предания"}},{q="Why does Canaga need felstalker hooves?",a="Канага использует копыта как главные ингредиенты для приготовления Сапты земли — особого напитка, позволяющего чувствам смертного шамана воспринимать духов стихий и говорить с ними.",al={"why felstalker hooves","hooves purpose","зачем копыта","назначение копыт"}},{q="Where are the felstalkers located?",a="Они обитают чуть севернее тренировочной площадки в Долине Испытаний, в пещере и на окрестных обрывах Грота Пылающего Клинка.",al={"felstalker location","where to find felstalkers","где найти ловчих","расположение ловчих"}},{q="Могут ли другие расы Орды пройти этот вариант испытания?",a="Да. Хотя оно предназначено в основном для шаманов-орков и троллей, взрослеющих в Дуротаре, шаманы-таурены, покинувшие Плато Красного Облака, тоже могут пройти испытание Канаги в Долине Испытаний.",al={"can tauren do this","is this orc only","могут ли таурены","только для орков"}},{q="Какие добродетели олицетворяет земля для шамана?",a="По шаманской традиции земля — основа жизни, воплощение огромной силы, стойкости и вечного терпения, хотя при отсутствии уважения она может оказаться упрямо переменчивой.",al={"virtues of earth","shaman earth meaning","добродетели земли","значение земли для шамана"}}},fp="13,260,14.398.0,16.449.0,34.202.0,26.202.0,39.178.0,34.160.0,58.189.0,50.188.0"}
P.entries["quest:1517"] = {n="Зов Земли",s="Этот священный обряд знаменует первое духовное общение новичка со стихиями в Дуротаре. Под руководством Канаги заклинателя земли молодые шаманы пьют сильнодействующую сапту земли на Священном Камне, чтобы заглянуть за завесу и предстать перед Низшим воплощением земли.",h="Этот священный обряд знаменует первое духовное общение новичка со стихиями в Дуротаре.",kw={"call of earth","canaga earthcaller","earth sapta","hidden path","minor manifestation of earth","sapta sight","spirit rock","valley of trials","зов земли","канага заклинатель земли","сапта земли","потайная тропа","низшее воплощение земли","зрение сапты","священный камень","долина испытаний"},ang={["class:Shaman"]="Этот обряд — ваш самый первый шаг на пути единения со стихиями. Он учит, что истинное мастерство начинается с тихого терпения земли.",["race:Orc"]="Для орков, возвращающихся к путям предков после поколений порчи скверной, общение с помощью сапты земли — священное возвращение к традиционной связи их народа с духами.",["race:Troll"]="Знахари и духовидцы Черного Копья принимают эти земные обряды, чтобы приспособить глубокие связи предков к суровой, выжженной солнцем земле Дуротара."},sec={{t="Сила сапты",b="Сапта — мистический отвар, известный лишь немногим мастерам-шаманам. Напиток, сваренный с помощью магии стихий, соединяет смертное восприятие с миром духов и дарует сильным духом «зрение сапты». Поскольку его сила напрямую связывает дух пьющего со стихией, традиция требует никогда не пить его вне освященной земли."},{t="Паломничество к Священному Камню",b="Чтобы приобщиться к земле, новички покидают Долину Испытаний и поднимаются по Потайной тропе в южные скалы Дуротара. В конце тропы находится Священный Камень — возвышенное святилище над суровой пустошью. Выпив здесь сапту, новичок видит то, что недоступно обычному взору: стихийное присутствие, тихо ожидающее среди камня."},{t="Терпение земли",b="Низшее воплощение земли не требует ни крови, ни покорения — лишь того, чтобы просящий смиренно предстал перед миром. Духи других стихий — огня, воды и воздуха — буйны, переменчивы и зачастую хаотичны, а земля дарует твердость. Она приветствует просящего, напоминая, что горы дают стойкость, а равнины — безграничное терпение."}},faq={{q="Что такое сапта земли?",a="Сапта земли — особое зелье, которое варят опытные шаманы. Оно на время настраивает дух пьющего на стихию земли. Выпивший его обретает внутреннее зрение, нужное, чтобы видеть скрытых духов стихий и говорить с ними.",al={"what is sapta","earth sapta meaning","what does sapta do","что такое сапта","сапта земли значение","что делает сапта"}},{q="Где находится Священный Камень?",a="Священный Камень стоит в скалистых горах к юго-западу от Логова в Долине Испытаний. Новички добираются до него по Потайной тропе, ведущей в холмы к югу от дна долины.",al={"where is spirit rock","spirit rock location","how to find spirit rock","где священный камень","расположение священного камня","как найти священный камень"}},{q="Почему сапту нужно пить именно на Священном Камне?",a="Шаманская традиция велит пить сапту только в особых священных местах. Такие места, как Священный Камень, — естественные тонкие границы между миром смертных и духами стихий.",al={"why drink at spirit rock","can i drink sapta anywhere","почему пить на священном камне","можно ли пить сапту где угодно"}},{q="Кто такое Низшее воплощение земли?",a="Это стихийный дух земли, обитающий на Священном Камне. Он виден лишь обостренному восприятию «зрения сапты» и встречает молодых шаманов, чтобы испытать их смирение и преподать первые основы стихийного равновесия.",al={"manifestation of earth","who is the earth spirit","воплощение земли","кто такой дух земли"}},{q="Может ли любой шаман Орды пройти это испытание?",a="Хотя это в первую очередь обряд посвящения для молодых шаманов-орков и троллей Черного Копья, обучающихся в Дуротаре, шаманы-таурены, прибывшие сюда, тоже могут его пройти, хотя у них есть собственный обряд на Плато Красного Облака.",al={"can tauren do this quest","who can do call of earth","могут ли таурены это задание","кто может выполнить зов земли"}},{q="Как дух земли относится к новичку?",a="В отличие от буйных воплощений огня или воздуха, дух земли приветлив и спокоен. Он принимает новичков, которые подходят со смиренным почтением, и дарует благословение, не требуя состязания в силе.",al={"what does the earth spirit say","is the earth spirit hostile","что говорит дух земли","враждебен ли дух земли"}}},fp="13,260,22.371.0,25.352.0,21.400.0,23.225.0,29.179.0,46.196.0,40.238.0,42.217.0,48.212.0"}
P.entries["quest:1518"] = {n="Зов Земли",s="Зов Земли — завершающий обряд испытания земли для молодых шаманов в Дуротаре. Пообщавшись с воплощением духа земли, новичок возвращается к Канаге заклинателю земли с необработанным кварцем, чтобы получить свой первый стихийный тотем.",h="Зов Земли — завершающий обряд испытания земли для молодых шаманов в Дуротаре.",kw={"call of earth","canaga earthcaller","durotar","earth totem","minor manifestation","rough quartz","shaman","valley of trials","зов земли","канага заклинатель земли","дуротар","тотем земли","низшее воплощение","необработанный кварц","шаман","долина испытаний"},ang={["class:Shaman"]="Этот обряд дает ваш самый первый тотем, открывая способность укореняться в стихиях и призывать на помощь почву.",["faction:Horde"]="Стихии Калимдора дики и неукротимы, поэтому связь, которую создают шаманы Орды, необходима для выживания их новых поселений.",["race:Orc"]="Испытание отражает продолжающееся возрождение шаманизма орков в Дуротаре, возвращение к стихийному равновесию после десятилетий демонической порчи.",["race:Troll"]="Знахари и духовидцы Черного Копья учатся рядом с орками в Долине Испытаний, приспосабливая традиционное общение к четырем стихийным путям."},sec={{t="Сердце камня",b="Чтобы приобщиться к земле, начинающий шаман должен смотреть дальше грубой силы. Проявив терпение и смирение перед Низшим воплощением земли, новичок получает скромный дар — кусок необработанного кварца. Хотя камень неприметен, он служит неиссякаемым зерном силы и доказательством того, что дух принял обет просящего."},{t="Первый из четырех путей",b="Возвращение кварца к Канаге заклинателю земли в Долине Испытаний завершает испытание. Канага мастерит из камня Тотем земли — вещественное средоточие, через которое шаман направляет неколебимую защиту и силу земли. Этот обряд знаменует официальное вступление новичка в первую из четырех стихийных дисциплин и закладывает основу для всей жизни в единении с миром природы."}},faq={{q="Для чего нужен необработанный кварц?",a="Необработанный кварц дарит Низшее воплощение земли как доказательство того, что вы пообщались с духом. Канага заклинатель земли вставляет этот камешек в ваш новый тотем земли, где он становится сердцем и средоточием ваших заклинаний земли.",al={"rough quartz","what does quartz do","purpose of quartz","необработанный кварц","что делает кварц","для чего кварц"}},{q="Кто такой Канага заклинатель земли?",a="Канага заклинатель земли — учитель шаманов в Долине Испытаний в Дуротаре. Он ведет юных орков и троллей через первые испытания, готовит их к общению с духами стихий и создает их первые тотемы.",al={"canaga","canaga earthcaller","who is canaga","канага","канага заклинатель земли","кто такой канага"}},{q="Могут ли таурены выполнить это задание?",a="Да. Хотя таурены обычно проходят испытание земли со своими старейшинами на Плато Красного Облака в Мулгоре, любой шаман Орды, добравшийся до Долины Испытаний, может пройти обряд с Канагой заклинателем земли.",al={"can tauren do durotar call of earth","tauren shaman durotar","tauren call of earth","могут ли таурены зов земли в дуротаре","шаман таурен дуротар","зов земли таурен"}},{q="Что означает получение тотема земли?",a="Получение тотема земли означает, что дух земли признал вас. Это и знак вашего положения среди шаманов, и необходимое средоточие для земных благословений и защитных чар.",al={"why get earth totem","shaman earth totem meaning","зачем тотем земли","значение тотема земли шамана"}},{q="Каких добродетелей земля требует от шамана?",a="Дух просит новичка оставаться терпеливым, быть сильным и искать мудрости. Он учит, что даже малый камешек переживет горы, если выстоит, и призывает шаманов уважать землю, чтобы она поддерживала их в ответ.",al={"earth spirit lessons","what does earth ask","уроки духа земли","чего просит земля"}},{q="Куда ведет путь шамана после этого?",a="Земля — лишь первая из четырех стихий, которые должен освоить шаман. По мере обучения вы будете призваны искать общения с духами огня, воды и воздуха.",al={"what totem next","after earth totem","four paths shaman","какой тотем дальше","после тотема земли","четыре пути шамана"}}},fp="13,246,18.371.0,23.408.0,34.245.0,26.235.0,25.210.0,44.216.0,49.228.0,41.184.0"}
P.entries["quest:152"] = {n="Зачистка побережья",s="Вдоль скалистого западного края Западного Края мели усеяны обломками кораблей, а берега наводнены племенами мурлоков. Призрачный капитан Грейсон на Маяке в Западном Крае нанимает способных искателей приключений, чтобы очистить побережье от морских налетчиков, и у потерпевших крушение моряков появился шанс выжить.",h="Вдоль скалистого западного края Западного Края мели усеяны обломками кораблей, а берега наводнены племенами...",kw={"captain grayson","coastrunner","great sea","murloc","oracle","shipwrecks","tidehunter","westfall lighthouse","капитан грейсон","береговой бегун","великое море","мурлок","оракул","кораблекрушения","охотник приливов","маяк в западном крае"},ang={["faction:Alliance"]="Поскольку армия Штормграда отсутствует в Западном Крае, Народное ополчение едва справляется с защитой внутренних ферм, и оборона побережья целиком ложится на одиночных союзников вроде капитана Грейсона.",["race:Human"]="Торговые суда и рыбаки людей давно ходят по водам у Западного Края; видеть, как берег превратился в смертельную ловушку, кишащую мурлоками, — горькое напоминание об утраченных рубежах королевства."},sec={{t="Кладбище кораблей",b="Великое море вдоль западной границы Западного Края славится коварством. Рифы, внезапные шквалы и острые скалы за годы превратили бесчисленные суда в обломки. Обычно уцелевшие цепляются за обломки и выползают на песок в ожидании спасения. Но на беду моряков, берег целиком оказался во власти агрессивных племен мурлоков, не знающих пощады к выброшенным на сушу."},{t="Призрачный дозорный",b="На одинокой скале к юго-западу от материка стоит Маяк в Западном Крае, за которым присматривает дух капитана Грейсона. Хотя смерть привязала его к этому посту, Грейсон по-прежнему считает своим долгом безопасность проходящих кораблей и заблудших моряков. Понимая, что племена мурлоков — от простых береговых бегунов на севере до опасных охотников приливов, воинов и оракулов на юге — делают берега смертельно опасными, он призывает путников провести систематическую зачистку побережья."}},faq={{q="Кто такой капитан Грейсон?",a="Капитан Грейсон — призрачный морской капитан, обитающий на Маяке в Западном Крае. Несмотря на нежизнь, он не оставляет чувства долга перед моряками, плывущими по коварным водам у берега, и стремится защитить берега для тех, кто переживет кораблекрушение.",al={"captain grayson","ghost in the lighthouse","lighthouse keeper westfall","капитан грейсон","призрак в маяке","смотритель маяка западный край"}},{q="Почему Грейсон хочет очистить побережье от мурлоков?",a="Воды у Западного Края усеяны затонувшими кораблями, и выжившие моряки часто оказываются на берегу. Поскольку агрессивные племена мурлоков наводняют пляжи с севера до юга, любого выбравшегося на сушу моряка быстро убьют, если не держать берег чистым.",al={"why kill murlocs westfall","coast isn't clear reason","why clear the coast","зачем убивать мурлоков западный край","зачистка побережья причина","зачем очищать побережье"}},{q="Где обитают эти разные мурлоки?",a="Береговые бегуны мурлоков обычно обитают на северных участках побережья Западного Края. Более грозные воины, оракулы и охотники приливов мурлоков сосредоточены в поселениях и лагерях на южных пляжах.",al={"murloc locations westfall","where are coastrunners","where are tidehunters","места мурлоков западный край","где береговые бегуны","где охотники приливов"}},{q="Враждебен ли капитан Грейсон к Альянсу или Орде?",a="Капитан Грейсон — нейтральная фигура. Он связан морским долгом, а не политическими союзами, и предложит свои поручения и награды любому способному искателю приключений, готовому сделать побережье безопаснее.",al={"is grayson friendly","grayson faction","can horde do this quest","дружелюбен ли грейсон","фракция грейсона","может ли орда выполнить это задание"}},{q="Нужно ли для этого задания сначала зажечь маяк?",a="Нет. Капитан Грейсон поручит вам зачистить побережье независимо от того, помогали ли вы ему снова зажечь Маяк в Западном Крае.",al={"do i need keeper of the flame first","prerequisite for coast isnt clear","нужен ли хранитель пламени сначала","требование для зачистки побережья"}},{q="Работают ли мурлоки на Братство Справедливости?",a="Нет. Мурлоки действуют самостоятельно из территориальной агрессии. Хотя Братство Справедливости действует неподалеку, в области Луноречья и южных бухтах, прибрежные племена мурлоков нападают на любого, кто вторгается в их охотничьи угодья на берегу.",al={"are defias allied with murlocs","defias murloc connection","союз справедливости с мурлоками","связь братства справедливости и мурлоков"}}},fp="21,304,20.443.0,19.490.0,23.275.0,57.284.0,42.221.0,52.213.0,56.141.0,51.246.0"}
P.entries["quest:1520"] = {n="Зов Земли",s="Этот священный обряд знаменует духовную связь тауренского шамана со стихией земли. Выпив Сапту земли у священного камня к востоку от Лагеря Нараче, посвящаемые заглядывают за пределы физических чувств и напрямую общаются с Низшим воплощением земли.",h="Этот священный обряд знаменует духовную связь тауренского шамана со стихией земли.",kw={"call of earth","camp narache","earth sapta","kodo rock","manifestation","mulgore","sapta","seer ravenfeather","зов земли","лагерь нараче","сапта земли","дольмен кодо","воплощение","мулгор","сапта","провидица воронье перо"},ang={["class:Shaman"]="Этот обряд — духовная основа связи тауренского шамана с землей и необходимый шаг к единению со стихией земли и получению Тотема земли.",["race:Tauren"]="Глубокое почтение к Матери-Земле делает обряд сапты одним из самых почитаемых испытаний взросления для тауренских шаманов на Плато Красного Облака."},sec={{t="Назначение сапты",b="Сапта — тщательно приготовленный обрядовый напиток, который создают старейшины-шаманы, чтобы напрямую связать смертный дух посвящаемого с изначальной стихией. Он готовится с помощью древней магии, и секреты его приготовления хранят лишь немногие из тауренов. Если выпить его в особом священном месте, напиток расширяет сознание и прорывает завесу между физическим миром и миром духов, позволяя увидеть стихии в их первозданном облике."},{t="Единение у Дольмена Кодо",b="К востоку от Лагеря Нараче стоит Дольмен Кодо — возвышающийся каменный столб, служащий священным убежищем. Выпитая здесь сапта открывает Низшее воплощение земли, ожидающее паломника. В отличие от переменчивых, огненных и яростных ликов природы, которые встретятся шаману позже, дух земли просит лишь, чтобы посвящаемый приблизился в тихом смирении, и дарует несокрушимую силу гор и спокойное терпение равнин всем, кто чтит землю."}},faq={{q="Что такое Сапта земли?",a="Сапта земли — алхимический и духовный напиток, который варят старейшины-шаманы. Его магия раскрывает восприятие выпившего, позволяя посвящаемому видеть духов стихии земли и напрямую общаться с ними.",al={"what is sapta","earth sapta meaning","what does the drink do","что такое сапта","сапта земли значение","что делает напиток"}},{q="Где находится Дольмен Кодо?",a="Дольмен Кодо — внушительный природный каменный монолит, расположенный прямо к востоку от Лагеря Нараче, через Плато Красного Облака.",al={"find kodo rock","kodo rock location","where is the shrine","найти дольмен кодо","дольмен кодо расположение","где святилище"}},{q="Кто приготовил Сапту земли для этого обряда?",a="Напиток приготовила и вручила Провидица Воронье Перо, старейшина-шаманка из Лагеря Нараче, которая руководит обучением юных духовных наставников.",al={"who gives the sapta","seer ravenfeather sapta","кто дает сапту","провидица воронье перо сапта"}},{q="Почему сапту нужно пить в священном месте?",a="Сапта по сути священна и опасна при неверном обращении. По обычаю тауренов ее пьют только в освященных святилищах, где обитают духи стихий и могут безопасно принять просителя.",al={"why drink at kodo rock","can i drink sapta anywhere","почему пить у дольмена кодо","можно ли пить сапту где угодно"}},{q="Что происходит после того, как выпить напиток у Дольмена Кодо?",a="Напиток приподнимает обыденную завесу и открывает Низшее воплощение земли. Беседа с ним завершает связь между шаманом и стихией земли.",al={"what appears","minor manifestation of earth spawn","что появляется","низшее воплощение земли появление"}},{q="Какой урок дух земли преподает посвящаемым?",a="Дух учит, что земля требует смиренного терпения, а не сражений. Тогда как огонь или воздух могут быть хаотичными и яростными, земля дарует душе шамана силу, стойкость и тихую опору.",al={"earth spirit lesson","meaning of earth rite","урок духа земли","смысл обряда земли"}}},fp="13,245,24.449.0,22.456.0,23.205.0,27.115.0,42.151.0,46.204.0,52.165.0,54.210.0"}
P.entries["quest:1521"] = {n="Зов Земли",s="Этот обряд завершает первое общение юного тауренского шамана с духами земель Мулгора. Выпив Сапту земли и поговорив напрямую с воплощением духа, посвящаемый получает осколок необработанного камня, чтобы принести его домой. Возвращение в Лагерь Нараче знаменует формальную связь начинающего мистика с первой из четырех стихий.",h="Этот обряд завершает первое общение юного тауренского шамана с духами земель Мулгора.",kw={"call of earth","camp narache","earth totem","minor manifestation of earth","mulgore","red cloud mesa","rough quartz","seer ravenfeather","tauren shaman","зов земли","лагерь нараче","тотем земли","низшее воплощение земли","мулгор","плато красного облака","грубый кварц","провидица воронье перо","тауренский шаман"},ang={["class:Shaman"]="Этот обряд знаменует получение вашего самого первого тотема. Он закрепляет вашу духовную сущность и открывает возможность накладывать основные защитные обереги земли.",["faction:Horde"]="Шаманы служат важной духовной опорой и советниками новой Орды, связывая смертные расы с переменчивыми силами стихий Калимдора.",["race:Tauren"]="Тауренская культура относится к Матери-Земле с глубоким почтением. Это испытание напрямую связывает посвящаемого с живым камнем и почвой родной земли предков."},sec={{t="Дар горы",b="После общения с Низшим воплощением земли на скалах у Плато Красного Облака дух отдает простой Грубый кварц. Хотя камень на вид неприметен, он олицетворяет договор со стихией и стойкость самого камня. Дух напоминает юному шаману, что терпение и сила — главные добродетели, которых требует земля, и обещает, что взаимное уважение принесет согласие с землей."},{t="Первый тотем",b="По возвращении в Лагерь Нараче Провидица Воронье Перо делает из подаренного кварца самый первый Тотем земли шамана. Это не просто украшение, символ статуса: тотем служит постоянной физической и духовной опорой. Через этот резной фокус посвящаемый направляет укрепляющую, защитную магию самой земли, делая первый настоящий шаг по четверичному пути стихий."}},faq={{q="Для чего нужен Грубый кварц?",a="Кварц — знак, который Низшее воплощение земли дает в доказательство единения. Провидица Воронье Перо использует его как духовное сердце вашего нового Тотема земли.",al={"why do i need rough quartz","what is the quartz for","rough quartz use","зачем нужен грубый кварц","для чего кварц","применение грубого кварца"}},{q="Почему Тотем земли так важен для шамана?",a="Тотемы служат проводниками, через которые шаман направляет силу стихий. Без Тотема земли в качестве фокуса шаман не может просить духов земли явить его заклинания и защитные обереги.",al={"why do i need earth totem","what does earth totem do","earth totem lore","зачем нужен тотем земли","что делает тотем земли","предания тотема земли"}},{q="Кто такая Провидица Воронье Перо?",a="Провидица Воронье Перо — духовная наставница и учитель шаманов в Лагере Нараче на Плато Красного Облака. Она руководит испытаниями стихий для юных тауренов, проводит их через первые видения и создает их священные орудия.",al={"who is ravenfeather","seer ravenfeather lore","camp narache seer","кто такая воронье перо","провидица воронье перо предания","провидица лагеря нараче"}},{q="Какие четыре пути упоминает Провидица Воронье Перо?",a="Она говорит о четырех изначальных стихиях, которыми должен овладеть шаман: земле, огне, воде и воздухе. Земля — основа, воплощение стойкости и твердости, и она становится первым испытанием посвящаемого.",al={"four paths","four elements shaman","what are the paths","четыре пути","четыре стихии шамана","какие есть пути"}},{q="Где происходит это общение?",a="Низшее воплощение земли обитает на неприступных утесах у Плато Красного Облака в Мулгоре, и добраться до него можно, лишь выпив особую Сапту земли.",al={"where do i find the earth spirit","manifestation location","where is the spirit","где найти духа земли","расположение воплощения","где дух"}},{q="Проходят ли другие шаманы Орды подобный обряд?",a="Да. Орки и тролли Черного Копья в Дуротаре проходят собственный вариант Зова Земли в Долине Испытаний, стремясь к единению с местными воплощениями стихий, чтобы создать свои первые тотемы.",al={"do orcs do call of earth","troll call of earth","do all shamans get earth totem","проходят ли орки зов земли","зов земли троллей","получают ли все шаманы тотем земли"}}},fp="13,352,24.402.0,15.387.0,40.178.0,47.203.0,25.241.0,51.205.0,37.157.0,48.198.0"}
P.entries["quest:1524"] = {n="Зов Огня",s="Это паломничество — второе испытание на пути шамана к единению с огнем. Посланный Краналом Фиссом из Степей, начинающий шаман несет незажженный Факел Дремлющего Пламени к уединенному святилищу на горной вершине над Рекой Строптивой в Дуротаре.",h="Это паломничество — второе испытание на пути шамана к единению с огнем.",kw={"barrens","call of fire","durotar","fire totem","kranal fiss","shrine of the dormant flame","southfury river","telf joolam","степи","зов огня","дуротар","тотем огня","кранал фисс","святилище дремлющего пламени","река строптивая","телф джулам"},ang={["class:Shaman"]="Путь к Тотему огня требует прямого общения с силами стихий Калимдора и предполагает паломничество к отдаленным святилищам, а не простое обучение.",["faction:Horde"]="Общие шаманские учения орков, тауренов и троллей объединяют их духовные традиции и отправляют учеников от равнин Степей к священным утесам Дуротара."},sec={{t="Проверка готовности",b="Посвящаемый может проявить сырую мистическую силу, но огонь требует гораздо большего, чем одна лишь сила: умеренности, сосредоточенности и уважения. Кранал Фисс вверяет шаману Факел Дремлющего Пламени. Этот предмет служит и ритуальным орудием, и удостоверением, показывая хранителю святилища, что носитель официально признан готовым к испытанию."},{t="Скрытая вершина",b="Цель лежит за Рекой Строптивой, среди южных скал Дуротара. Едва заметная тропа, отмеченная лишь выветренным камнем с руной огня, поднимается к одной из высочайших точек края. На ее вершине стоит Святилище Дремлющего Пламени, которое охраняет отшельник-тролль Телф Джулам. Телф то и дело прогоняет любопытных путников и охотников за сокровищами, оберегая священную жаровню от посторонних глаз, пока не явится истинный проситель с незажженным факелом."}},faq={{q="Для чего нужен Факел Дремлющего Пламени?",a="Незажженный факел — знак намерения, который выдает Кранал Фисс. Он показывает Телфу Джуламу, хранителю святилища, что носитель — достойный посвящаемый шаман; случайных странников и искателей сокровищ Телф прогоняет.",al={"why carry torch","dormant flame torch","torch meaning","зачем нести факел","факел дремлющего пламени","значение факела"}},{q="Кто такой Телф Джулам?",a="Телф Джулам — шаман-отшельник Орды, охраняющий Святилище Дремлющего Пламени на вершинах южного Дуротара. Он оберегает жаровню от тех, кто не понимает природу духов и не уважает ее.",al={"telf joolam","shrine keeper","who is the troll at the shrine","телф джулам","хранитель святилища","кто тролль у святилища"}},{q="Где находится скрытая тропа?",a="Тропа начинается в Дуротаре, к югу от моста через Реку Строптивую. На берегу реки, там, где горы подходят к побережью, камень с руной пламени отмечает узкую тропу, ведущую на высокий хребет.",al={"hidden path location","how to find shrine of the dormant flame","path up the mountain","расположение скрытой тропы","как найти святилище дремлющего пламени","тропа в гору"}},{q="Почему факел нужно приносить незажженным?",a="Огонь нельзя просто взять: его нужно пробудить и подчинить с помощью надлежащего обряда. Незажженный факел символизирует дремлющее состояние пламени до того, как шаман совершит единение, необходимое, чтобы его зажечь.",al={"why is torch unlit","dormant torch ritual","why dormant flame","почему факел не зажжен","ритуал дремлющего факела","почему дремлющее пламя"}},{q="Что происходит после встречи с Телфом Джуламом?",a="Убедившись в подлинности факела, Телф Джулам направляет посвящаемого к более суровым и опасным обрядам, нужным, чтобы зажечь дремлющее пламя и доказать власть над стихией огня.",al={"next step call of fire","what after telf joolam","следующий шаг зов огня","что после телфа джулама"}},{q="Почему это святилище скрыто от остальной Орды?",a="Силы стихий переменчивы и опасны в неумелых руках. Шаманские традиции держат священные места вдали от обычных поселений, чтобы охотники за сокровищами и любопытные не тревожили покоящихся духов и не навлекли беду.",al={"why secret shrine","is the shrine hidden","почему тайное святилище","скрыто ли святилище"}}},fp="12,269,19.369.0,15.481.0,54.221.0,19.227.0,33.234.0,36.219.0,40.173.0,58.227.0"}
P.entries["quest:1525"] = {n="Зов Огня",s="Это испытание — важный этап подготовки к общению шамана с огнем: посвящаемому нужно собрать нестабильные ингредиенты для приготовления сапты огня. Телфу Джуламу нужны компоненты, насыщенные жаром и магической силой: смола геомантов из племени Иглогривых и мешочек темных реагентов, который носят культисты Пылающего Клинка, прячущиеся в Дуротаре.",h="Это испытание — важный этап подготовки к общению шамана с огнем: посвящаемому нужно собрать нестабильные...",kw={"burning blade","call of fire","dustwind cave","fire sapta","fire tar","razormane","reagent pouch","telf joolam","пылающий клинок","зов огня","пещера пыльного ветра","сапта огня","огненная смола","иглогривые","мешочек с реагентами","телф джулам"},ang={["class:Shaman"]="Этот обряд проверяет умение молодого шамана уравновешивать противоположные силы и показывает, что пламя — не просто топливо гнева, а орудие жизненной силы и света, когда им руководит мудрость.",["faction:Horde"]="Испытание отправляет защитников Орды против двух насущных угроз у самых их границ: наступающих свинобразов из Иглогривых в Степях и коварных культистов Пылающего Клинка, засевших в Дуротаре.",["race:Orc"]="Для орков столкновение с Пылающим Клинком — горькое напоминание о темной магии чернокнижников, некогда развратившей их народ, а возвращение огню чистой, природной сути становится важным актом культурного возрождения."},sec={{t="Приготовление Сапты огня",b="Чтобы видеть духов огня и говорить с ними, шаман не может полагаться только на обычное зрение. Как земля требовала собственного отвара, так и открытие чувств для Вечного Пламени требует особой Сапты огня. Для зелья нужны реагенты, изначально связанные с жаром и пламенем. Отшельник Телф Джулам отправляет посвященных по Дуротару и в восточные Степи, чтобы добыть эти составляющие у тех, кто владеет первобытным жаром и губительным колдовством."},{t="Враги и стихии",b="Нужные ингредиенты показывают, как разные силы обращаются к огню. Заклинатели-свинобразы из племени Иглогривых в восточных Степях носят огненную смолу — вязкий горючий побочный продукт своих земных ритуалов. Мешочек с реагентами, напротив, нужно забрать у культистов Пылающего Клинка, скрывающихся в Пещере Пыльного Ветра среди ущелий к северо-востоку от Колючего Холма. Хотя эти чернокнижники используют огонь как орудие разрушения и демонического хаоса, сырые реагенты в их мешочках остаются естественно созвучны самой стихии."},{t="Природа пламени",b="Когда сапта приготовлена, Телф Джулам открывает существенную истину о стихиях: огонь — это гораздо больше, чем просто разрушение и гибель. Он жжет и пожирает, но он же — сердце тепла, света и созидания. Истинное равновесие требует понимать, что противоположные силы придают смысл друг другу, а мудрый шаман использует контрастные силы стихий вместе, а не видит в огне только оружие."}},faq={{q="Что такое Сапта огня?",a="Сапта — ритуальный отвар, который шаманы готовят из ингредиентов, связанных с определенной стихией. Выпив Сапту огня, шаман на время настраивает свой дух и зрение на план огня и может видеть духов огня и говорить с ними — обычным чувствам они незаметны.",al={"what is fire sapta","fire sapta meaning","why drink sapta"}},{q="Где найти огненную смолу?",a="Огненную смолу носят заклинатели-свинобразы из Иглогривых, живущие на восточных равнинах Степей, сразу за рекой Строптивой от Дуротара. Геоманты, провидцы, мистики и плетущие шипы часто носят горшки с этим густым горючим составом для племенных ритуалов.",al={"fire tar location","who drops fire tar","fire tar quilboar","где взять огненную смолу","у кого огненная смола","огненная смола свинобразы"}},{q="Где найти мешочек с реагентами?",a="Мешочек с реагентами носят культисты Пылающего Клинка в Пещере Пыльного Ветра. Эта пещера находится над ущельями к северо-востоку от Колючего Холма в Дуротаре; не путайте ее со Скалой Черепа, лежащей севернее, у побережья.",al={"reagent pouch location","which cave has reagent pouch","burning blade pouch","мешочек с реагентами где","в какой пещере мешочек с реагентами","мешочек пылающего клинка"}},{q="Почему шаман использует вещи чернокнижников?",a="Для сапты нужны ингредиенты, естественно насыщенные нужной стихией. Поскольку культисты Пылающего Клинка постоянно призывают разрушительное демоническое пламя, их мешочки плотно набиты мощными реагентами, связанными с огнем, — именно таким катализатором, какой нужен Телфу Джуламу для приготовления отвара.",al={"why use burning blade reagents","warlock items for shaman","warlock fire","зачем реагенты пылающего клинка","вещи чернокнижников для шамана","огонь чернокнижников"}},{q="Кто такой Телф Джулам?",a="Телф Джулам — тролль-шаман, живущий в одиночестве в лагере на скалах Дуротара, к югу от Колючего Холма. Он руководит суровыми испытаниями огнем для посвященных Орды и помогает им овладеть опасным равновесием между разрушением и созиданием.",al={"telf joolam lore","who is telf joolam","телф джулам предания","кто такой телф джулам"}},{q="Что происходит после этого задания?",a="Когда Телф Джулам приготовит Сапту огня из собранных реагентов, он отправит вас на пылающие высоты спящей вершины неподалеку. Там вы должны выпить отвар, чтобы встретиться с духом стихии и получить свой тотем огня.",al={"next quest call of fire","after getting reagents","what to do with fire sapta","следующее задание зов огня","после получения реагентов","что делать с саптой огня"}}},fp="12,343,22.442.0,20.527.0,19.406.1,21.302.0,29.275.0,33.219.0,42.311.0,19.245.0,30.223.1"}
P.entries["quest:1526"] = {n="Зов Огня",s="Это испытание — решающий момент в единении шамана с огнем на вершинах Дуротара. Под руководством отшельника Телфа Джулама посвященный должен выпить мощную сапту огня, чтобы увидеть Малое воплощение огня и сразиться с ним. Победа над духом дает тлеющий уголь, которым зажигают жаровню у Святилища Вечного Пламени и церемониальный факел.",h="Это испытание — решающий момент в единении шамана с огнем на вершинах Дуротара.",kw={"brazier of the dormant flame","call of fire","durotar","fire sapta","fire totem","minor manifestation of fire","shaman trial","shrine of eternal flame","telf joolam","жаровня спящего пламени","зов огня","дуротар","сапта огня","тотем огня","малое воплощение огня","испытание шамана","святилище вечного пламени","телф джулам"},ang={["class:Shaman"]="В отличие от твердой, непреклонной земли, огонь переменчив и разрушителен. Это испытание учит, что огонь пожирает нерешительного заклинателя: чтобы овладеть им, нужны непоколебимая сосредоточенность и властность.",["faction:Horde"]="Шаманы-орки и тролли совершают паломничество на красные скалы Дуротара, чтобы доказать свое единение с огненными духами этой земли."},sec={{t="Глаза пламени",b="Духи огня редко показываются непосвященным. Чтобы общаться с ними, шаман должен изменить свое восприятие с помощью сапты огня — отвара стихии, приготовленного из реагентов, собранных в степях и на побережье. Выпив отвар, шаман открывает чувства невидимому и видит малых духов и воплощения, пляшущие на скалах вершины."},{t="Схватка с воплощением",b="Огонь не уступает пассивной преданности: он требует силы, решительности и уважения. На вершине горы ждет Малое воплощение огня. Дух знает о проницательном взгляде шамана, когда действует сапта, и ждет начала испытания. Посвященных учат бить быстро и без колебаний: стихийный огонь питается затянувшимся боем и свирепеет и разгорается тем сильнее, чем дольше длится схватка."},{t="Жаровня Спящего Пламени",b="Когда воплощение побеждено, шаман забирает его остаточный жар в виде тлеющего угля. Вернувшись к святилищу на вершине, он кладет уголь в Жаровню Спящего Пламени. Хотя металл с узорами подвергается жгучему солнцу и ветрам Дуротара, он остается чистым и прохладным, пока уголь не коснется чаши: тогда вспыхивает ритмичное белое пламя, зажигающее ритуальный факел."}},faq={{q="В чем смысл этого испытания?",a="Это испытание проверяет, достоин ли начинающий шаман повелевать стихийным огнем. Встретившись с воплощением и заключив его первозданный жар в ритуальный факел, посвященный доказывает свою силу и получает право создать Тотем огня.",al={"why do call of fire","fire totem quest meaning","call of fire trial","зачем зов огня","смысл задания тотем огня","испытание зов огня"}},{q="Зачем мне пить сапту огня?",a="Духи стихий часто обитают чуть за пределами обычного смертного зрения. Сапта огня истончает завесу, позволяя шаману видеть огненных элементалей на вершине горы и взаимодействовать с ними.",al={"what does fire sapta do","why sapta","cant see fire elemental","что делает сапта огня","зачем сапта","не вижу огненного элементаля"}},{q="Где найти Малое воплощение огня?",a="Воплощение обитает на самой вершине горного хребта над обителью Телфа Джулама в Дуротаре, рядом со Святилищем Вечного Пламени.",al={"manifestation location","where is the fire elemental","where do i go","где воплощение","где огненный элементаль","куда идти"}},{q="Кто такой Телф Джулам?",a="Телф Джулам — чудаковатый шаман-отшельник, живущий высоко на скалистом хребте в Дуротаре. Он ведет молодых посвященных Орды через опасные и переменчивые обряды, необходимые для понимания огня.",al={"telf joolam role","telf joolam lore","who is the hermit","роль телфа джулама","телф джулам предания","кто такой отшельник"}},{q="Почему воплощение крепнет по ходу боя?",a="Огонь по своей природе нарастает, распространяется и питается энергией со временем. Шаманов предупреждают бить решительно: долгое промедление позволяет духу набраться сил и гореть все жарче.",al={"why is the fire elemental so strong","manifestation scaling","swift strike fire","почему огненный элементаль такой сильный","усиление воплощения","быстрый удар огонь"}},{q="Что происходит после зажигания жаровни?",a="Зажженная жаровня воспламеняет церемониальный факел. Посвященный несет это священное пламя вниз с горы, чтобы завершить создание своего Тотема огня.",al={"what after dormant flame","next quest call of fire","where to take lit torch","что после спящего пламени","следующее задание зов огня","куда нести зажженный факел"}}},fp="12,363,17.359.0,29.427.0,32.403.1,34.232.0,38.217.0,47.140.0,19.189.0,58.193.0,38.158.0"}
P.entries["quest:1529"] = {n="Зов Воды",s="Зов Воды — обряд посвящения, направляющий восходящих шаманов Орды с высот Громового Утеса к восточным берегам Степей. Чтобы обрести единение со стихией очищающей воды, посвященный должен найти затворницу Ислен Заклинательницу Воды. Эта встреча — первый шаг на духовном пути к получению Тотема воды.",h="Зов Воды — обряд посвящения, направляющий восходящих шаманов Орды с высот Громового Утеса к восточным берегам...",kw={"barrens","call of water","islen waterseer","ratchet","shaman","southfury river","thunder bluff","water totem","xanis flameweaver","степи","зов воды","ислен заклинатель воды","кабестан","шаман","река строптивая","громовой утес","тотем воды","ксаварик"},ang={["class:Shaman"]="Этот обряд знаменует переход от ранних испытаний стихий к овладению текучими силами очищения, исцеления и прилива.",["faction:Horde"]="Шаманизм остается опорой новой Орды, связывая древние традиции духовников-орков, троллей и тауренов.",["race:Tauren"]="Начавшись в Громовом Утесе, это задание уводит юных шаманов шу'хало из защищенных равнин Мулгора в широкие просторы Калимдора."},sec={{t="Призыв из Утеса",b="Having mastered the unyielding earth and the untamed flame, an aspiring shaman is eventually deemed ready to study the deeper mysteries of the elements. In Thunder Bluff, trainers like Xanis Flameweaver recognize when a student has shown enough discipline to approach the fluid, cleansing spirit of water. The journey requires leaving the windswept mesas of Mulgore behind and traveling east across the sun-scorched plains of the Barrens."},{t="Отшельница побережья",b="Путь ведет к Ислен Заклинательнице Воды — тихой провидице, живущей вдали от шумных поселений в скромной рыбацкой хижине на восточном побережье, к югу от Кабестана и устья реки Строптивой. Стоя на краю великого океана, Ислен определяет готовность путников по тому, как стихии льнут к ним. Увидев, что устойчивая земля, резкий ветер и тепло огня уже связаны с духом искателя, она готовит его к испытаниям, нужным для понимания чистоты воды."}},faq={{q="Кто посылает меня в это путешествие?",a="Наставники шаманов в Громовом Утесе, например Ксаварик, выдают это задание, когда посвященный достаточно продвинулся в духовном обучении, чтобы приступить к обрядам воды.",al={"quest giver","who starts call of water","where to get call of water tb","персонаж, выдающий задание","кто начинает зов воды","где взять зов воды громовой утес"}},{q="Где находится Ислен Заклинатель Воды?",a="Ислен Заклинатель Воды живет в уединенной рыбацкой хижине на восточном побережье Степей. Ее жилище стоит на берегу к югу от Кабестана и к югу от места, где река Строптивая впадает в море.",al={"where is islen waterseer","islen location","find islen","где ислен заклинатель воды","где ислен","найти ислен"}},{q="В чем смысл испытания Зова Воды?",a="Это испытание — необходимый обряд посвящения для каждого шамана, стремящегося к единению с водой. Оно проверяет понимание посвященным чистоты стихий и ведет прямо к получению Тотема воды.",al={"why do call of water","call of water purpose","shaman water totem quest","зачем зов воды","смысл зова воды","тотем воды шаман задание"}},{q="Получают ли такое наставление другие расы Орды?",a="Хотя вводный призыв в Громовом Утесе обычно получают таурены, шаманы-орки и тролли в Оргриммаре и Деревне Сен'джин получают похожие призывы найти Ислен Заклинательницу Воды на побережье Степей.",al={"is this only for tauren","orc call of water","troll call of water","только для тауренов","зов воды орк","зов воды тролль"}},{q="Какие стихии шаман должен освоить до воды?",a="Шаман общается с устойчивой землей и с разрушительным, но дарующим жизнь огнем, прежде чем искать текучую природу воды. Как замечает Ислен при вашем появлении, земля, ветер и огонь уже должны коснуться вашего духа, прежде чем вода откроет свою чистоту.",al={"prerequisites","which totems first","elemental order","требования","какие тотемы сначала","порядок стихий"}},{q="Что происходит после встречи с Ислен Заклинательницей Воды?",a="Разговор с Ислен завершает первую часть пути из Громового Утеса. Она сразу даст вам новые задания по всему Калимдору, чтобы вы напрямую постигли и очистили стихию воды.",al={"what next","after finding islen","call of water part 2","что дальше","после встречи с ислен","зов воды часть 2"}}},fp="13,329,24.438.0,23.499.0,29.177.0,33.187.0,47.195.0,51.195.0,48.246.0,43.195.0"}
P.entries["quest:153"] = {n="Красные кожаные банданы",s="«Красные кожаные банданы» — задание на охоту за головами, которое выдает Разведчик Галиан на Сторожевом холме в Западном Крае. Пока Народное ополчение безуспешно пытается выследить Братство Справедливости на равнинах, Галиан обещает награду всем, кто готов проредить ряды бандитов и принести характерные красные тканевые маски, которые те носят.",h="«Красные кожаные банданы» — задание на охоту за головами, которое выдает Разведчик Галиан на Сторожевом холме...",kw={"bandanas","defias brotherhood","peoples militia","red leather bandanas","scout galiaan","sentinel hill","westfall","банданы","братство справедливости","народное ополчение","красные кожаные банданы","разведчик галиан","сторожевой холм","западный край"},ang={["class:Rogue"]="Багровые маски разбойников Братства Справедливости напоминают о том, как умелые мошенники и карманники организовались в целую армию у самых ворот Штормграда.",["faction:Alliance"]="Выполняя задания на охоту за головами для Народного ополчения, вы напрямую поддерживаете оборону Западного Края, когда королевское руководство Штормграда не присылает помощи."},sec={{t="Знак верности",b="Во всем Западном Крае красная бандана стала безошибочной приметой Братства Справедливости. Банда принимает в свои ряды обычных карманников, грабителей и предателей всех мастей, но объединяет их этим багровым знаком. Для Разведчика Галиана и измотанного Народного ополчения на Сторожевом холме сбор этих трофеев служит двум целям: он подтверждает уничтожение бандитов и помогает собирать сведения об их перемещающихся отрядах в окрестностях."},{t="Разведка ополчения",b="Поскольку Штормград не присылает в Западный Край настоящих военных подкреплений, Народное ополчение во многом полагается на опытных наблюдателей вроде Разведчика Галиана, которые отслеживают действия Братства Справедливости. Галиан целыми днями следит за патрулями бандитов, находясь в безопасности на Сторожевом холме, а грязную работу — истребление разбойников, согнавших честных фермеров с их земли, — поручает случайным искателям приключений и добровольцам из ополчения."}},faq={{q="Почему члены Братства Справедливости носят красные кожаные банданы?",a="Красная кожаная бандана — единая форма и знак верности Братству Справедливости. Она скрывает личности бывших работников, воров и разбойников и внушает ужас оставшимся фермерам Западного Края.",al={"defias red mask meaning","why red masks","defias bandana lore","значение красных масок","почему красные маски","бандана братства справедливости"}},{q="Кто такой Разведчик Галиан?",a="Разведчик Галиан — боец Народного ополчения, расквартированный на Сторожевом холме. Он следит за перемещениями отрядов Братства Справедливости по всему Западному Краю и выдает искателям приключений задания на охоту за головами, чтобы обуздать бандитов.",al={"scout galiaan","who gives red leather bandanas","sentinel hill scout","разведчик галиан","кто дает красные кожаные банданы","разведчик сторожевого холма"}},{q="Почему ополчению нужны искатели приключений, чтобы собирать эти банданы?",a="Народное ополчение предельно измотано и действует без королевских солдат и средств из Штормграда. Назначая награды за доказательства гибели бандитов, разведчики вроде Галиана могут ослаблять силы Братства Справедливости, не оставляя оборону Сторожевого холма без людей.",al={"why collect bandanas","why militia bounty","зачем собирать банданы","зачем награда ополчения"}},{q="Где находятся бандиты, у которых есть Красные кожаные банданы?",a="Бандиты Братства Справедливости бродят почти по всему Западному Краю: они занимают заброшенные фермы, рыщут на перекрестках и разбивают лагеря на Золотом побережье и у холмов Луноречья.",al={"where find defias bandanas","defias locations westfall","где найти банданы братства справедливости","где братство справедливости в западном крае"}},{q="Что происходит с Красными кожаными банданами после того, как вы их сдадите?",a="Разведчик Галиан использует их как доказательство гибели бандитов, чтобы отслеживать их перемещения и оценивать, насколько сильно походы ополчения сокращают численность Братства в этом районе.",al={"what does galiaan do with bandanas","что галиан делает с банданами"}},{q="Участвует ли Армия Штормграда в этой охоте за головами?",a="Нет. Военные Штормграда в основном оставили Западный Край, занявшись другими внутренними проблемами, и местная оборона целиком лежит на Гриане Камнегриве и добровольцах Народного ополчения.",al={"stormwind guard westfall","does stormwind help sentinel hill","стража штормграда западный край","помогает ли штормград сторожевому холму"}}},fp="20,307,20.481.0,30.406.0,44.237.0,21.233.0,64.273.0,52.177.0,52.183.0,46.195.0"}
P.entries["quest:1530"] = {n="Зов Воды",s="Этот этап пути «Зов Воды» направляет начинающих шаманов Орды в опасные южные земли Степей. По поручению Ислен Заклинательницы Воды путники должны найти отшельницу по имени Брин, чтобы лучше постичь очищающую и исцеляющую природу воды.",h="Этот этап пути «Зов Воды» направляет начинающих шаманов Орды в опасные южные земли Степей.",kw={"barrens","brine","call of water","islen waterseer","quilboar","rebirth","shaman","water sapta","степи","брин","зов воды","ислен заклинатель воды","свинобраз","возрождение","шаман","сапта воды"},ang={["class:Shaman"]="Общение с водой — важная веха в становлении шамана: она соединяет воинственную землю и переменчивый огонь с силой исцеления.",["faction:Horde"]="Новички Орды преодолевают просторы Калимдора, чтобы овладеть стихиями, и почитают духов, дарующих шаманам Вождя их жизненно важную магию."},sec={{t="Уроки прилива",b="Прежде чем допустить новичка к сапте воды, Ислен Заклинатель Воды внушает ему главную истину: вода означает возрождение. Ее поток способен вытачивать камень, смывать нечистоты и исцелять плоть, но ее целительная сила целиком зависит от чистоты. Оскверненная вода несет гибель, а не жизнь — хрупкое равновесие, которое должен осознать каждый шаман, прежде чем пытаться говорить со стихией."},{t="Отшельница в пыли",b="Чтобы продолжить путь, новички должны отправиться далеко на юг, в засушливые Степи, и найти Брин. Она предпочла жить в одиночестве среди непрекращающихся набегов свинобразов, обходится без стражи и страха и хранит знания и испытания, необходимые для того, чтобы связать новичка с водой."}},faq={{q="Кто такая Ислен Заклинатель Воды?",a="Ислен Заклинатель Воды — мастер-шаман, живущая на побережье Степей, к югу от Торгового побережья. Она ведет шаманов Орды через испытания, необходимые для общения с духами воды.",al={"islen","waterseer","who sends this quest","ислен","заклинатель воды","кто дает это задание"}},{q="Почему жить на юге Степей среди свинобразов?",a="Брин живет одна в южных пустошах, несмотря на постоянные нападки свинобразов. Она признает, что чужакам такая опасность кажется безрассудной, но скрывает свои причины, проверяя, хватит ли новичкам стойкости, чтобы ее разыскать.",al={"why does brine live there","brine quilboar","brine location","почему брин живет там","брин и свинобразы","где находится брин"}},{q="Для чего нужна сапта воды?",a="Сапта — это обрядовая смесь, изменяющая восприятие шамана и позволяющая ему видеть духов стихий и говорить с ними, хотя смертным глазам они незримы.",al={"sapta","water sapta use","why get water sapta","сапта","применение сапты воды","зачем получать сапту воды"}},{q="Какой главный урок вода дает шаману?",a="Вода воплощает возрождение, очищение и обновление. Ее целительная сила не имеет равных, но когда вода оскверняется или застаивается, она может нести губительный распад и разорение.",al={"lesson of water","elemental meaning water","water rebirth","урок воды","значение стихии воды","возрождение воды"}},{q="Кто может пройти этот путь?",a="Испытания «Зова Воды» проходят только шаманы Орды, которые доказали свою преданность и уже обрели связь с духами земли и огня.",al={"who gets call of water","is call of water horde only","кто получает зов воды","только ли для орды зов воды"}},{q="Какие опасности ждут на пути к Брин?",a="Юг Степей опасен: там свирепствуют племена свинобразов, защищающие свои колючие логова, и бродят звери, нападающие на неосторожных путников вдали от безопасности Перекрестка или Лагеря Таурахо.",al={"dangers southern barrens","path to brine","опасности юга степей","путь к брин"}}},fp="13,261,19.391.0,21.271.0,23.194.0,56.238.0,39.171.0,50.172.0,31.154.0,38.210.0"}
P.entries["quest:1532"] = {n="Зов Воздуха",s="«Зов Воздуха» — важная веха на духовном пути шамана Орды: он направляет его к общению с непредсказуемой стихией ветра. Это задание выдает Ксаварик в Громовом Утесе и велит опытным новичкам отправиться на юг, в Тысячу Игл, чтобы учиться у Пратты Заклинательницы Туч. Овладение воздухом дарует шаману священный тотем, необходимый, чтобы направлять быстрейшие силы природы.",h="«Зов Воздуха» — важная веха на духовном пути шамана Орды: он направляет его к общению с непредсказуемой...",kw={"air totem","call of air","prate cloudseer","shaman","thousand needles","thunder bluff","xanis flameweaver","тотем воздуха","зов воздуха","пратта заклинательница туч","шаман","тысяча игл","громовой утес","ксаварик"},ang={["class:Shaman"]="Завершение набора стихий — глубокий поворотный момент: вам открываются быстрые потоки и силы молний Тотема воздуха.",["faction:Horde"]="Заключая дикие ветра Калимдора в священный тотем, шаманы Орды укрепляют духовный стержень своего молодого союза.",["race:Tauren"]="Глядя вниз с высоких утесов Мулгора, шу'хало почитают ветра как священных вестников, несущих по равнинам шепот Матери-Земли."},sec={{t="Шепчущие ветра",b="Уже обретя устойчивость земли, ярость огня и исцеляющие глубины воды, шаман подходит к последнему стихийному столпу — воздуху. Ксаварик, наставляющая шаманов с высот Громового Утеса, признает, что ветра гораздо капризнее и труднее поддаются управлению, чем прежние стихии. Испытание требует смирения, сосредоточенности и врожденного уважения к бурному нраву неба."},{t="Паломничество на юг",b="Чтобы обрести связь с ветрами, шаман должен отправиться на юг мимо обширных равнин Степей и спуститься в выточенные ветром каньоны Тысячи Игл. Там, далеко на востоке, живет мистик-отшельница Пратта Заклинательница Туч. В уединенной пещере на склоне утеса, где день и ночь воют каньонные сквозняки, она проверяет готовность новичка, прежде чем даровать Тотем воздуха — орудие, необходимое для призыва порывов ветра, молний и быстрых духов ветра."}},faq={{q="Кто посылает меня на это задание?",a="Ксаварик, наставница шаманов в Громовом Утесе, выдает это задание, когда новичок набирается достаточно опыта, чтобы обрести связь со стихией воздуха.",al={"quest giver","who starts call of air","xanis flameweaver","персонаж, выдающий задание","кто начинает зов воздуха","ксаварик"}},{q="Где находится Пратта Заклинательница Туч?",a="Пратта Заклинательница Туч живет в укрытой пещере далеко на востоке, в продуваемом ветрами каньоне Тысячи Игл, к югу от Степей.",al={"prate cloudseer location","where is prate","find prate cloudseer","где пратта заклинательница туч","где пратта","найти пратту заклинательницу туч"}},{q="Почему стихию воздуха постигают последней?",a="Воздух слывет переменчивым, внезапным и неуловимым. По шаманской традиции новичок сначала должен овладеть устойчивостью земли, переменчивым теплом огня и текучестью воды, и лишь затем пытаться обуздать дикие невидимые потоки ветра.",al={"why air last","shaman air totem lore","elemental order","почему воздух последний","предания тотема воздуха шамана","порядок стихий"}},{q="Что я получу, найдя Пратту Заклинательницу Туч?",a="Пратта Заклинательница Туч вручает вам Тотем воздуха — духовный проводник, который позволяет сосредоточить стихийную магию и призывать духов воздуха на помощь.",al={"air totem reward","what does prate give","quest reward call of air","награда тотем воздуха","что дает пратта","награда за зов воздуха"}},{q="Это задание только для тауренов?",a="Хотя оно начинается в столице тауренов, Громовом Утесе, любой шаман Орды, обретший связь с первыми тремя стихиями, может отправиться этим путем в Тысячу Игл за своим Тотемом воздуха.",al={"can orcs do this","is this tauren only","horde shaman air quest","могут ли орки","только ли для тауренов","задание воздуха шамана орды"}},{q="Что происходит после выполнения этого задания?",a="По вашем прибытии Пратта Заклинательница Туч дарует вам Тотем воздуха, и вы сразу можете призывать тотемы ветра. Она также предлагает дальнейшее обучение и испытания, чтобы укрепить вашу связь с небом.",al={"what comes next","after call of air","prate cloudseer quests","что дальше","после зова воздуха","задания пратты заклинательницы туч"}}},fp="11,391,20.426.0,18.452.0,27.160.0,33.135.0,38.258.0,47.159.0,34.179.0,40.183.0"}
P.entries["quest:1534"] = {n="Зов Воды",s="Это задание — последнее испытание по сбору воды на пути шамана к получению Зова Воды. По указанию отшельницы Брин из южных Степей посвящаемые должны отправиться далеко на север, в чужие, мглистые рощи Ясеневого леса, чтобы набрать чистой воды из древнего источника в Руинах Звездной Пыли.",h="Это задание — последнее испытание по сбору воды на пути шамана к получению Зова Воды.",kw={"ashenvale","blue waterskin","brine","call of water","islen waterseer","mystral lake","ruins of stardust","shaman","ясеневый лес","синий бурдюк","брин","зов воды","ислен заклинатель воды","озеро мистраль","руины звездной пыли","шаман"},ang={["class:Shaman"]="Этот обряд проверяет готовность шамана пересекать опасные границы ради равновесия и собирать последнюю текучую сущность, необходимую для связи с Тотемом воды.",["faction:Horde"]="Чтобы попасть в Ясеневый лес, нужно отправиться в древние земли кальдораев, где Всадники Песни Войны ведут непрерывную лесную войну против враждебных часовых ночных эльфов.",["race:Tauren"]="Паломничество соединяет засушливые родные земли центрального Калимдора со священными, омытыми росой рощами, о которых помнят мифы и песни старейшин."},sec={{t="Путь в Мглистую рощу",b="Собрав образцы воды из водопоя под ее хижиной в Степях и из чистого колодца Мельницы Таррен, шаман должен найти третью и последнюю сущность. Брин посылает посвящаемого через северную границу сухих равнин в Ясеневый лес — густые древние заросли, священные для ночных эльфов. Контраст между засушливыми Степями и глубокой сенью Ясеневого леса подчеркивает разнообразие стихий, которое шаман должен понять, чтобы по-настоящему обрести гармонию с водой."},{t="Руины Звездной Пыли",b="Руины Звездной Пыли скрыты возле горного прохода, отделяющего Ясеневый лес от Когтистых гор, за мерцающей гладью Озера Мистраль. В этом уединенном эльфийском святилище находится нетронутый источник, окруженный тихими водами и древними камнями. Хотя руины дышат дикой безмятежностью, их охраняют необузданные духи стихий и природы, враждебные к чужакам, поэтому шаману приходится двигаться осторожно, чтобы добыть священный глоток из источника."},{t="Глоток чистейшей воды",b="Возвращение к Брин с наполненным синим бурдюком завершает паломничество по Калимдору и Восточным королевствам. Соединив нетронутый образец из эльфийского источника с образцами из водопоя в Степях и Мельницы Таррен, Брин готовит флакон безупречной чистоты. Это снадобье становится основой следующего испытания: общения с духами воды через провидицу Ислен Заклинательницу Воды."}},faq={{q="Где находятся Руины Звездной Пыли?",a="Руины Звездной Пыли расположены на юго-западе Ясеневого леса. Перейдя на север из Степей, следуйте по дорогам на запад мимо Озера Мистраль к предгорьям, граничащим с Когтистыми горами.",al={"ruins of stardust location","where is stardust","how to get to ruins of stardust","руины звездной пыли где","где звездная пыль","как добраться до руин звездной пыли"}},{q="Зачем Брин нужна вода из эльфийских руин?",a="Чтобы общаться с духами воды, шаман должен собрать воду, воплощающую разные проявления стихии. Источник в Руинах Звездной Пыли хранит древнюю, магически чистую воду, не тронутую иссушающей порчей Степей, и завершает тройку сущностей, необходимых для ритуальной смеси Брин.",al={"why ashenvale water","why ruins of stardust","reason for stardust water","почему вода ясеневого леса","почему руины звездной пыли","зачем вода звездной пыли"}},{q="Какие опасности есть вокруг Руин Звездной Пыли?",a="Руины и окружающие воды охраняют защитные звери и духи природы, в том числе территориальные элементали воды и звери, обитающие в дебрях Ясеневого леса, которые нападают на любого, кто тревожит рощу.",al={"stardust enemies","is stardust dangerous","who guards the fountain","враги звездной пыли","опасны ли руины звездной пыли","кто охраняет источник"}},{q="Кто такая Брин и почему она помогает?",a="Брин — отшельница, орчиха-шаманка, живущая в одинокой хижине в южных Степях. Она старшая наставница и помогает Ислен Заклинательнице Воды: испытывает будущих шаманов на терпение, выносливость и понимание многоликости воды, прежде чем даровать им благословение стихии.",al={"who is brine","brine lore","what is brine's role","кто такая брин","брин предания","роль брин"}},{q="Что происходит после того, как принести воду Брин?",a="Когда Брин получает третий образец, она соединяет их и создает глоток чистейшей воды. Затем она отправляет шамана обратно к Ислен Заклинательнице Воды на восточном побережье Степей, чтобы начать общение с элементалями в видении.",al={"next step call of water","what happens next","where do i go after brine","следующий шаг зов воды","что дальше","куда идти после брин"}},{q="Безопасен ли Ясеневый лес для шаманов Орды низкого уровня?",a="Ясеневый лес — спорная территория, где сталкиваются ночные эльфы и Орда. Хотя путь через южные леса обходит крупные поселения ночных эльфов, такие как Астранаар, бродячие звери, агрессивные элементали и патрули Альянса представляют для посвящаемого реальную опасность.",al={"is ashenvale dangerous","level for ashenvale quest","опасен ли ясеневый лес","уровень для заданий ясеневого леса"}}},fp="13,306,31.489.0,21.457.0,27.423.1,40.204.0,45.299.0,48.209.0,36.268.0,48.224.1,46.268.0"}
P.entries["quest:1535"] = {n="Зов Воды",s="Это задание — первое испытание по сбору воды, которое Брин дает в Степях во время приобщения шамана к воде. Чтобы сварить сапту воды, Брин поручает посвящаемым набрать образец из охраняемого водопоя под ее хижиной и побуждает размышлять о священной и оспариваемой природе дарующей жизнь воды в пустыне.",h="Это задание — первое испытание по сбору воды, которое Брин дает в Степях во время приобщения шамана к воде.",kw={"barrens","brine","brown waterskin","call of water","quilboar","sapta","watering hole","степи","брин","коричневый бурдюк","зов воды","свинобраз","сапта","водопой"},ang={["class:Shaman"]="Это испытание учит шаманов, что стихия воды — не только исцеление и восстановление, но и причина конфликтов и отчаянной борьбы жизни за выживание.",["faction:Horde"]="Контроль над водой и ее распределение остаются главной трудностью освоения Степей, где соперничающие племена и звери постоянно воюют за каждую каплю."},sec={{t="Урок пустыни",b="Прежде чем даровать сапту воды, необходимую для общения с духами, отшельница Брин требует от посвящаемых шаманов изучить воду во всех ее формах по всему миру. В засушливых Степях вода — это разница между выживанием и голодом. Брин велит шаманам наблюдать не только за самой водой, но и за окружающей природой: как леса цветут в ее объятиях, как пустыни голодают без нее и как живые существа убивают, защищая даже скромнейший родник."},{t="Сокровище свинобразов",b="Водопой под холмом Брин яростно охраняют местные свинобразы. Для них любая лужа воды — бесценное сокровище, которое они отмечают пиршествами, когда небо соизволит пролить дождь. Брин сожалеет о неизбежном насилии, вызванном их скопидомством, но отмечает, что замкнутая жадность и разобщенные кланы свинобразов сдерживают их угрозу, сохраняя шаткое равновесие для других рас, пытающихся выжить на равнинах."}},faq={{q="Зачем собирать воду для Брин?",a="Брин нужны образцы чистой воды из разных уголков мира, чтобы сварить церемониальную сапту воды. Этот отвар открывает восприятие посвящаемого и позволяет напрямую общаться с духами воды.",al={"why get water","brine water task","call of water quest 3 purpose","зачем собирать воду","задание брин с водой","зов воды задание 3 цель"}},{q="Почему водопой под хижиной Брин так яростно оспаривают?",a="В засушливом климате Степей вода — самый ценный ресурс. Местные свинобразы почитают любую лужу как священное сокровище и яростно сражаются с каждым, кто пытается зачерпнуть из нее.",al={"why are quilboar guarding water","quilboar pond","water hole barrens","почему свинобразы охраняют воду","водоем свинобразов","водопой степи"}},{q="Кто такая Брин?",a="Брин — пожилая отшельница, живущая в одинокой хижине с видом на южные Степи. Она обладает глубокой мудростью о воде и духах стихий и направляет шаманов Орды на пути общения с ними.",al={"who is brine","brine barrens","brine npc","кто такая брин","брин степи","брин нпс"}},{q="Что происходит после возвращения наполненного коричневого бурдюка?",a="Когда вы вернетесь с образцом из водопоя, Брин продлит ваше паломничество и отправит вас дальше, за чистой водой из совершенно иных мест, например из колодца Мельницы Таррен в Предгорьях Хилсбрада.",al={"what next call of water","after watering hole","next step brine","что дальше зов воды","после водопоя","следующий шаг брин"}},{q="Почему Брин упоминает разобщенность свинобразов?",a="Брин замечает, что яростная территориальность и вражда кланов свинобразов сами поддерживают их несчастья. Если бы они объединили силы, а не дрались за отдельные источники, они представляли бы куда большую угрозу для остальных Степей.",al={"brine quilboar commentary","why quilboar fighting each other","замечания брин о свинобразах","почему свинобразы воюют друг с другом"}},{q="Что такое сапта?",a="Сапта — мистический эликсир, который шаманы готовят из собранных реагентов и вод, связанных со стихиями. Выпив его, можно расширить духовное зрение и увидеть существ стихий, обычно скрытых от глаз смертных.",al={"what is sapta","water sapta meaning","что такое сапта","сапта воды значение"}}},fp="13,326,22.466.0,20.449.0,50.215.0,58.187.0,13.203.0,56.227.1,49.248.0,16.208.0"}
P.entries["quest:1536"] = {n="Зов Воды",s="Это паломничество поручает начинающему шаману отправиться из засушливых Степей за море, в спорные Предгорья Хилсбрада. Там, в деревне Мельница Таррен, удерживаемой Отрекшимися, находится небольшой колодец, чудом оставшийся чистым среди окружающего разложения. Сбор его воды учит посвящаемого тому, что чистота и надежда могут выжить даже в самой мрачной среде.",h="Это паломничество поручает начинающему шаману отправиться из засушливых Степей за море, в спорные Предгорья...",kw={"barrens","brine","call of water","hillsbrad","sapta","shaman","tarren mill","thrall","waterskin","степи","брин","зов воды","хилсбрад","сапта","шаман","мельница таррен","тралл","бурдюк"},ang={["class:Shaman"]="Доставка воды со всего мира — испытание преданности, которое учит вас искать гармонию и жизнь даже среди суровых земель Восточных королевств.",["faction:Horde"]="Посещение Мельницы Таррен сводит молодых воинов и шаманов Орды, рожденных в Калимдоре, лицом к лицу с их новыми неспокойными союзниками, Отрекшимися, и с войной на передовой против людей-защитников Хилсбрада.",["race:Orc"]="Испытание дает повод поразмыслить о непреходящем наследии выживания и силы Тралла и напоминает оркам о тяжелой цене, заплаченной за их свободу."},sec={{t="Чудесный родник",b="Готовя реагенты для Сапты воды, отшельница Брин отправляет посвящаемых далеко за море, в Мельницу Таррен в Предгорьях Хилсбрада. Среди сопротивления людей и зараженного чумой присутствия недавно ставших союзниками Отрекшихся небольшой колодец в центре поселения удивительным образом дает чистую, незапятнанную родниковую воду. Брин видит в этом роднике священный остаток — остров чистоты, уцелевший в оскверненном море."},{t="Стойкость во тьме",b="Для Брин чистый колодец Мельницы Таррен — больше, чем ингредиент; это глубокий урок стойкости. Она сравнивает его выживание с самим вождем Траллом, который вынес огромные тяготы, плен и горе вопреки невозможным шансам, прежде чем возглавить орков. Как Тралл служит маяком обновленной надежды для Орды, так и колодец Мельницы Таррен доказывает, что жизнь и чистота могут устоять среди трагедии и порчи."}},faq={{q="Где берут образец воды?",a="Образец набирают прямо из городского колодца в центре Мельницы Таррен — старого человеческого поселения в Предгорьях Хилсбрада, которое теперь занимают Отрекшиеся.",al={"tarren mill water","where is the well","call of water well location","вода мельницы таррен","где колодец","зов воды расположение колодца"}},{q="Почему Брин посылает вас за водой так далеко?",a="Брин нужны особые сущности воды, чтобы сварить Сапту воды — отвар, позволяющий шаманам видеть духов стихий. Она обнаружила этот родник во время прежнего путешествия в Хилсбрад и считает его неизменную чистоту среди разложения Отрекшихся стихийно мощной и духовно поучительной.",al={"why tarren mill","why hillsbrad water","why brine wants this water","почему мельница таррен","почему вода хилсбрада","зачем брин эта вода"}},{q="Что такое Мельница Таррен?",a="Мельница Таррен когда-то была скромным человеческим городком на севере Предгорий Хилсбрада. После Третьей войны и падения Лордерона она перешла под контроль Отрекшихся Сильваны Ветрокрылой, которые теперь держат ее как укрепленный форпост Орды против местных человеческих сил.",al={"tarren mill history","who owns tarren mill","история мельницы таррен","кому принадлежит мельница таррен"}},{q="Как это задание связано с Траллом?",a="Брин использует незапятнанный колодец как аналогию с вождем Траллом. Как колодец сохраняет свежую чистоту, окруженный чумой и смертью, так и Тралл пережил рабство и сильные страдания, сохранив нравственную стойкость и видение, необходимые, чтобы вести новую Орду.",al={"brine thrall dialogue","thrall connection","диалог брин о тралле","связь с траллом"}},{q="Что происходит после возвращения наполненного бурдюка?",a="Брин принимает наполненный красный бурдюк и сообщает вам, что нужен только еще один особый образец воды, прежде чем она сможет закончить смесь реагентов для вашей Сапты воды.",al={"what next call of water","after tarren mill water","что дальше зов воды","после воды мельницы таррен"}},{q="Почему чистота колодца считается необычной?",a="Большая часть Лордерона страшно осквернена чумой нежити Плети, и поселения Отрекшихся редко связывают со свежими, живыми родниками. То, что центральный колодец Мельницы Таррен по-прежнему дает чистую воду, делает его редким неоскверненным остатком былого.",al={"why is tarren mill water pure","forsaken polluted well","почему вода мельницы таррен чистая","колодец отрекшихся загрязнен"}}},fp="13,377,19.416.0,21.435.0,36.167.0,46.297.0,20.265.0,38.277.0,50.173.0,44.269.0"}
P.entries["quest:154"] = {n="Гребень для Эвы",s="«Гребень для Эвы» — задание Альянса в Сумеречном лесу, завершающее мрачную сделку с духом Слепой Мэри. Когда ей предлагают гребень, чтобы собрать пряди ее призрачных волос, измученный призрак впадает в отчаяние из-за утраченной красоты и отбрасывает его. Если вернуть гребень с волосами Мадам Еве, прорицательница сможет спрясть эфирную Прядь призрачных волос.",h="«Гребень для Эвы» — задание Альянса в Сумеречном лесу, завершающее мрачную сделку с духом Слепой Мэри.",kw={"blind mary","darkshire","duskwood","ghost hair","ghost hair thread","madame eva","return the comb","слепая мэри","темнолесье","сумеречный лес","призрачные волосы","прядь призрачных волос","мадам ева","гребень для эвы"},ang={["class:Priest"]="Страшное самоуничижение Слепой Мэри — мрачный пример мучений неупокоенных духов, привязанных к миру смертных скорбью, а не злобой.",["faction:Alliance"]="Путь по мрачным дорогам между Темнолесьем и одиноким домом Мэри показывает путникам всепроникающий упадок в сердце Сумеречного леса.",["profession:Tailoring"]="Прядение Пряди призрачных волос показывает жутковатые ремесла Сумеречного леса: призрачный материал можно собирать и чесать, получая прочные сверхъестественные ткани."},sec={{t="Горькое отражение",b="Слепая Мэри обитает в ветхой лачуге к югу от Темнолесья, вечно оплакивая свою трагическую смерть и свою участь. Когда к ней приходят с гребнем Мадам Евы, напоминание об обычном уходе за волосами лишь усиливает ее скорбь. Осознав, что теперь она лишь призрак — чудовище, лишенное человеческой прелести, которое больше никто не полюбит, — она в ужасе отшатывается и сует гребень вместе с призрачными волосами, запутавшимися в зубцах, обратно в руки путника."},{t="Плетение сверхъестественного",b="Мадам Ева ждет возвращения гребня в Темнолесье, прекрасно зная о жутком характере поручения. Заполучив призрачные волосы, гадалка обретает редкую духовную основу, необходимую, чтобы спрясть моток Пряди призрачных волос. Ева прядет из этих эфирных волокон нить и платит путникам за все лишние волоски, оставшиеся после тонкой работы."}},faq={{q="Почему Слепая Мэри в ужасе реагирует на гребень?",a="Гребень напоминает Слепой Мэри о ее смертной жизни и красоте. Увидев себя в облике иссохшего призрака, она в горе срывается, отвергает гребень и сетует, что стала чудовищем, которого никто больше не полюбит.",al={"why is mary upset","why did blind mary scream","mary comb reaction","почему мэри расстроена","почему слепая мэри кричала","реакция мэри на гребень"}},{q="Что Мадам Ева делает с волосами на гребне?",a="Мадам Ева сплетает собранные на гребне пряди в Прядь призрачных волос — волшебную нить с тысячей применений: от связывания злых духов до вшивания жизни в неживые предметы.",al={"why ghost hair","what does eva do with ghost hair","madame eva thread","зачем призрачные волосы","что ева делает с призрачными волосами","нить мадам евы"}},{q="Где находится Слепая Мэри?",a="Слепая Мэри обитает в заброшенной ветхой лачуге к югу от Темнолесья, рядом с Безмятежным кладбищем в Сумеречном лесу.",al={"where is blind mary","blind mary location","где слепая мэри","местонахождение слепой мэри"}},{q="Кто такая Мадам Ева?",a="Мадам Ева — загадочная человеческая мистик и прорицательница, живущая в Темнолесье. Она гадает, дает туманные советы, а также изготавливает волшебные безделушки и реагенты для тех, кто странствует среди опасностей Сумеречного леса.",al={"who is madame eva","eva darkshire","кто такая мадам ева","ева темнолесье"}},{q="Что будет после возвращения гребня Мадам Еве?",a="Когда Мадам Ева забирает гребень и готовит моток Пряди призрачных волос, она просит вас доставить готовую нить Аберкромби, отшельнику, живущему рядом с Кладбищем Вороньего Холма.",al={"what comes next","next quest after return the comb","что дальше","следующее задание после гребня"}},{q="Почему Мадам Ева дает вам монеты по завершении?",a="Ева замечает, что на гребне оказалось более чем достаточно призрачных волос для нужного мотка нити, и платит вам несколько монет, выкупая лишние пряди для себя.",al={"why do i get coins","extra strands money","почему я получаю монеты","деньги за лишние пряди"}}},fp="15,389,19.452.0,24.362.0,50.248.0,50.180.0,28.126.0,18.209.0,52.182.1,51.189.0"}
P.entries["quest:155"] = {n="Братство Справедливости",s="На этом важнейшем этапе расследования Народное ополчение добивается прорыва с помощью разбойника-перебежчика. В обмен на защиту Предатель Братства Справедливости соглашается провести героев Альянса прямо к тайной базе Братства. Путь проходит через захваченный город-призрак Луноречье к тайному убежищу Эдвина ван Клифа.",h="На этом важнейшем этапе расследования Народное ополчение добивается прорыва с помощью разбойника-перебежчика.",kw={"deadmines","defias traitor","edwin vancleef","escort","gryan stoutmantle","moonbrook","peoples militia","sentinel hill","westfall","мертвые копи","предатель братства справедливости","эдвин ван клиф","сопровождение","гриан камнегрив","луноречье","народное ополчение","сторожевой холм","западный край"},ang={["class:Rogue"]="Путь бок о бок с бывшим разбойником Братства Справедливости жестко показывает цену предательства в преступном мире, где нарушенные клятвы караются кинжалами.",["faction:Alliance"]="Обнаружение убежища — крупный военный прорыв для осажденного Народного ополчения, первый реальный шанс нанести решающий удар по преступному мятежу в Западном Крае.",["race:Human"]="Для людей Штормграда вид Луноречья, павшего в беззаконие и занятого бывшими Каменщиками, показывает, насколько глубоко королевство раскололось со времен Третьей войны."},sec={{t="Сделка перебежчика",b="Поход Гриана Камнегрива против Братства Справедливости достигает переломного момента, когда пойманный бандит соглашается говорить. Столкнувшись с казнью или убийством от рук бывших братьев, Предатель Братства Справедливости заключает сделку с Народным ополчением: пусть его безопасно проведут по вражеской земле, и он выдаст место, где прячутся Эдвин ван Клиф и его главари. Зная, что сеть воров беспощадно заставит замолчать любого, кто заговорит, перебежчик требует вооруженной защиты на каждом шагу пути."},{t="Дорога через Луноречье",b="Путь к убежищу ведет прямо на юго-запад от Сторожевого холма в Луноречье, поселок, полностью захваченный Братством. Предатель ведет своих защитников мимо заброшенной городской площади и фонтана, навлекая ярость каждого бандита, мародера и грабителя с большой дороги, патрулирующего руины. Перебежчик приводит прямо ко входу в обширные Мертвые копи под Луноречьем, подтверждая худшие опасения ополчения: ван Клиф укрепил подземную твердыню прямо под носом у Западного Края."}},faq={{q="Кто такой Предатель Братства Справедливости?",a="Это бывший член Братства Справедливости, ставший осведомителем Гриана Камнегрива и Народного ополчения. Опасаясь смерти от рук бывших соратников, он выдал тайное местонахождение подземного укрепления Эдвина ван Клифа в обмен на сопровождение в безопасное место.",al={"who is the traitor","defias traitor identity","defias rat","кто предатель","личность предателя братства справедливости","крыса братства справедливости"}},{q="Куда предатель вас ведет?",a="Он ведет вас от Сторожевого холма по дороге в Луноречье, прямо через разрушенную городскую площадь мимо фонтана ко входу в туннели Мертвых копей под городом.",al={"where is the defias hideout","traitor path","where does he go","где убежище братства справедливости","путь предателя","куда он идет"}},{q="Зачем Гриану Камнегриву эти сведения?",a="Хотя Народное ополчение сражалось с грабителями по всему Западному Краю, оно не знало, откуда Эдвин ван Клиф руководит действиями. Найдя вход в его подземное логово, ополчение получает ясную цель для удара в самое сердце мятежа.",al={"why do we escort the traitor","stoutmantle purpose","why find the hideout","зачем сопровождать предателя","цель камнегрива","зачем искать убежище"}},{q="Почему Луноречье кишит членами Братства Справедливости?",a="Луноречье когда-то было процветающим земледельческим центром, но когда Королевство Штормград пришло в упадок, а в округе поселились бандиты, жители покинули город. Братство Справедливости заняло пустые здания как наземный рубеж, охраняющий вход в Мертвые копи.",al={"why are there defias in moonbrook","moonbrook takeover","who owns moonbrook","почему в луноречье братство справедливости","захват луноречья","кому принадлежит луноречье"}},{q="Что происходит после обнаружения убежища?",a="Когда предатель показывает вход в Мертвые копи, вы возвращаетесь к Гриану Камнегриву на Сторожевой холм. Получив доказательство местонахождения ван Клифа, ополчение готовит прямой штурм подземного логова.",al={"what comes next","after defias escort","quest progression","что дальше","после сопровождения","ход заданий"}},{q="Почему Братство хочет смерти предателя?",a="Братство Справедливости опирается на тайну: оно действует из скрытых туннелей, руководя операциями по всем землям Штормграда. Перебежчик, раскрывший парадный вход их главной базы, грозит разрушить весь их заговор.",al={"why kill traitor","defias attacking traitor","зачем убивать предателя","нападение братства справедливости на предателя"}}},fp="22,374,20.505.0,26.517.1,26.274.0,32.187.0,49.257.0,38.285.0,44.214.1,47.235.0"}
P.entries["quest:156"] = {n="Сбор цветков гнили",s="Хозяину таверны Смиттсу из Темнолесья нужны цветки гнили, чтобы приготовить партию его скандально известного «зомби-сока». Эти жуткие растения прорастают прямо из гниющих черепов скелетных ужасов и скелетных извергов, бродящих по беспокойным кладбищам Сумеречного леса.",h="Хозяину таверны Смиттсу из Темнолесья нужны цветки гнили, чтобы приготовить партию его скандально известного...",kw={"darkshire","night watch","raven hill cemetery","rot blossom","skeletal fiend","skeletal horror","tavernkeep smitts","tranquil gardens cemetery","zombie juice","темнолесье","ночной дозор","кладбище вороньего холма","цветок гнили","скелетный изверг","скелетный ужас","хозяин таверны смиттс","безмятежное кладбище","зомби-сок"},ang={["faction:Alliance"]="Охота на нежить на кладбищах Сумеречного леса приносит столь нужное облегчение измученному Ночному Дозору Темнолесья, который ежедневно сражается, чтобы город не пал.",["profession:Herbalism"]="В отличие от обычных трав, расцветающих на плодородной почве под солнцем, цветки гнили — темные ботанические аномалии, целиком укорененные в некромантском тлене и оживших костях."},sec={{t="Странный ингредиент",b="Большинство трактирщиков гордятся выдержанным элем и тонкими винами, но Хозяин таверны Смиттс из таверны «Алый ворон» порой варит куда более жуткое. Для его рецепта «зомби-сока» нужны цветки гнили — мерзкие некротические растения, пускающие корни в пустых черепах оживших скелетов. Сам Смиттс достаточно разумен, чтобы не приближаться к нежити, и оставляет жуткий сбор проезжим наемникам."},{t="Борьба с кладбищенской напастью",b="Чтобы собрать эти цветки, нужно сразить скелетных ужасов и извергов, бродящих по заросшим участкам Безмятежного кладбища или по обширному Кладбищу Вороньего Холма. Местное ополчение Сумеречного леса, Ночной Дозор, вечно измотано борьбой с подступающими ужасами леса. Смиттс следит, чтобы каждого искателя приключений, отважившегося пройти среди надгробий, должным образом отметили перед командиром Алтеей Чернодрев за истребление беспокойных мертвецов."}},faq={{q="Что такое цветок гнили?",a="Цветок гнили — мерзкое растение, прорастающее там, где царят темная магия и тлен. В Сумеречном лесу они растут прямо в черепных полостях оживших скелетных ужасов и извергов.",al={"rot blossom","what is rot blossom","where do rot blossoms come from","цветок гнили","что такое цветок гнили","откуда берутся цветки гнили"}},{q="Зачем Хозяину таверны Смиттсу цветки гнили?",a="Смиттс использует цветки как главный компонент для варева, известного как «зомби-сок», — крепкого напитка, который заказывают некоторые посетители в этих краях.",al={"why smitts want blossoms","zombie juice ingredients","smitts drink","зачем смиттсу цветки","ингредиенты зомби-сока","напиток смиттса"}},{q="Где найти скелетов с этими цветками?",a="Скелетные ужасы и скелетные изверги собираются по всем кладбищам Сумеречного леса, особенно на Безмятежном кладбище возле Темнолесья и на обширном Кладбище Вороньего Холма на западе.",al={"where are skeletal horrors","rot blossom location","tranquil gardens skeletons","где скелетные ужасы","где цветки гнили","скелеты безмятежного кладбища"}},{q="Помогает ли это задание обороне Темнолесья?",a="Да. Темнолесье выживает против постоянных атак нежити благодаря Ночному Дозору. Смиттс отмечает, что охота на скелетов ради цветков помогает командиру Алтее Чернодрев, проредив ряды чудовищ, угрожающих городу.",al={"night watch help","althea ebonlocke skeleton killing","помощь ночному дозору","алтея чернодрев убийство скелетов"}},{q="Что будет после доставки цветков?",a="Когда Смиттс получает цветки и варит зомби-сок, он просит вас доставить готовый напиток Аберкромби, чудаковатому отшельнику, живущему рядом с Кладбищем Вороньего Холма.",al={"next quest after rot blossoms","juice delivery follow up","следующее задание после цветков гнили","доставка сока"}},{q="Обычный ли напиток в Темнолесье зомби-сок?",a="Нет. В таверне «Алый ворон» обычно подают привычную местную еду и питье. Зомби-сок — странное особое варево, которое готовят, лишь когда Смиттс получает чудаковатый заказ, требующий некротических ингредиентов.",al={"is zombie juice normal","scarlet raven drinks","обычный ли зомби-сок","напитки алого ворона"}}},fp="19,236,20.415.0,22.438.0,22.190.0,45.148.0,56.204.0,45.230.0,46.176.1,54.199.0"}
P.entries["quest:157"] = {n="Доставка ниток",s="«Доставка ниток» — задание Альянса в Сумеречном лесу: нужно отнести катушку с «Прядью призрачных волос» от Мадам Евы из Темнолесья через зловещий лес к Аберкромби. Эксцентричный отшельник, живущий возле Кладбища Вороньего Холма, утверждает, что зачарованная нить нужна ему, чтобы оградить свою ветхую хижину от неупокоенных духов. Однако мрачные замечания Мадам Евы о нити намекают, что ей можно найти куда более зловещее применение.",h="«Доставка ниток» — задание Альянса в Сумеречном лесу: нужно отнести катушку с «Прядью призрачных волос» от...",kw={"abercrombie","darkshire","deliver the thread","duskwood","ghost hair thread","madame eva","raven hill","raven hill cemetery","zombie juice","аберкромби","темнолесье","доставка ниток","сумеречный лес","прядь призрачных волос","мадам ева","вороний холм","кладбище вороньего холма","сок зомби"},ang={["class:Priest"]="Для защиты дома от неупокоенных мертвецов обычно нужны священные обряды Света; то, что Аберкромби полагается на сотканные останки самих мертвецов, говорит о гораздо более темном пути.",["faction:Alliance"]="Хрупкая безопасность Темнолесья держится на бдительности, а отправка помощи через кишащие чудовищами западные леса к одинокому отшельнику ложится нагрузкой на и без того растянутую границу Ночного Дозора.",["profession:Tailoring"]="Превращение призрачных волос в годные катушки — не обычное ткачество: оно сочетает шитье с деревенской некромантией и создает материал, способный сшивать материю за пределами физического мира."},sec={{t="Переправа во тьме",b="Когда Мадам Ева заканчивает прясть призрачные волосы, собранные у призрака Слепой Мэри, она доверяет Прядь призрачных волос любому путнику, готовому отнести ее на запад. Путь лежит через темные просторы Сумеречного леса, мимо подстерегающих пауков и бродячей нежити, к ветхой лачуге Аберкромби к северу от обширного кладбища."},{t="Нити жизни и смерти",b="Аберкромби уверяет, что ему нужна эта призрачная нить, чтобы обвить окна и дверные косяки и не пускать воющих мертвецов Вороньего Холма. Но Мадам Ева проговаривается, что у пряди призрачных волос тысяча применений: ею можно связывать злобных духов, а также вшивать подобие жизни в мертвую и неодушевленную материю. Отшельник встречает катушку с огромной радостью и спешит приступить к своему тайному ремеслу."}},faq={{q="Что такое прядь призрачных волос?",a="Это зачарованная катушка, которую Мадам Ева в Темнолесье напряла из волос призрака Слепой Мэри. По словам Евы, она обладает мощными оккультными свойствами: может связывать духов или вшивать жизнь в неодушевленные предметы.",al={"ghost hair","what is the thread","ghost thread","призрачные волосы","что за нить","призрачная нить"}},{q="Кто такой Аберкромби?",a="Аберкромби — старый затворник, живущий в одинокой лачуге к северу от Кладбища Вороньего Холма. Он выставляет себя безобидным слабым отшельником, который постоянно боится нежити, бродящей возле его дома.",al={"hermit","who is abercrombie","shack guy","отшельник","кто такой аберкромби","хозяин лачуги"}},{q="Почему Аберкромби утверждает, что ему нужна нить?",a="Аберкромби говорит посетителям, что собирается натянуть призрачные волосы вдоль окон и дверей. Он утверждает, что их духовные свойства оградят дом от непрошеных вурдалаков и духов, бродящих по Сумеречному лесу.",al={"why thread","abercrombie excuse","warding spirits","зачем нить","отговорка аберкромби","защита от духов"}},{q="Где находится Аберкромби?",a="Он живет в уединенной деревянной лачуге к северу от основной территории Кладбища Вороньего Холма, недалеко от западной дороги, проходящей через Сумеречный лес.",al={"abercrombie location","where is the shack","hermit shack","местонахождение аберкромби","где лачуга","лачуга отшельника"}},{q="Что происходит после передачи нити Аберкромби?",a="Получив нить, Аберкромби награждает посыльного и тут же начинает жаловаться на другие неотложные нужды, отправляя путников с новыми поручениями за странными алхимическими ингредиентами, например за Соком зомби.",al={"next quest","what comes after","after deliver thread","следующее задание","что дальше","после доставки ниток"}},{q="Знает ли Мадам Ева, что затевает Аберкромби?",a="Ева не обвиняет Аберкромби напрямую, но в загадочных прощальных словах упоминает, что призрачными волосами можно вшивать жизнь в неодушевленные предметы. Похоже, она хорошо понимает некромантический потенциал нити, хотя и выполняет заказ без возражений.",al={"does eva know","madame eva complicit","eva warning","знает ли ева","мадам ева соучастница","предупреждение евы"}}},fp="18,414,22.355.0,25.386.1,26.228.0,19.212.0,47.217.0,29.147.0,52.207.0,47.261.0"}
P.entries["quest:1578"] = {n="Помощь фронту",s="«Помощь фронту» — одно из первых заданий для начинающих кузнецов-дворфов, которое выдает Тормус Подземная Кузня в Стальгорне. Кузнецам нужно выковать оружие и доспехи для Горцев, стоящих в Лок Модане против непрестанных набегов троггов.",h="«Помощь фронту» — одно из первых заданий для начинающих кузнецов-дворфов, которое выдает Тормус Подземная...",kw={"blacksmithing","copper axe","copper chain belt","ironforge","loch modan","supplying the front","thelsamar","thorvald deepforge","tormus deepforge","troggs","кузнечное дело","медный топор","медный кольчужный пояс","стальгорн","лок модан","помощь фронту","телсамар","торвальд подземная кузня","тормус подземная кузня","трогги"},ang={["faction:Alliance"]="Охрана границ Каз Модана защищает горные дороги, связывающие Стальгорн со Штормградом и операциями Альянса на юге.",["profession:Blacksmithing"]="Это задание служит первым испытанием для начинающих металлургов: оно проверяет их умение делать надежное, однородное медное оружие и доспехи для настоящих военных нужд.",["race:Dwarf"]="Оборона Лок Модана напрямую зависит от дворфийского мастерства: мастер у мехов так же важен для выживания королевства, как горец с ружьем."},sec={{t="Вооружение Горцев",b="В великих кузнях Стальгорна мастер-кузнец Тормус Подземная Кузня внимательно следит за границами королевства Каз Модан. Горцы, защищающие долины Лок Модана, измотаны внезапными нападениями троггов, выбирающихся из раскопанных руин и пещер. Чтобы снабжать оборонительные рубежи, нужен непрерывный поток новых клинков, поясов и фурнитуры, и к делу привлекают местных мастеров."},{t="Братство Подземной Кузни",b="Чтобы обеспечить оборону снаряжением и не отрывать опытных мастеров от городских кузниц, Тормус отправляет подмастерьев на восток, в Лок Модан. Там его коллега Торвальд Подземная Кузня содержит полевой арсенал в южной сторожевой башне. Доставляя Торвальду прочные медные топоры и медные кольчужные пояса, кузнецы доказывают свою надежность и получают более сложные кузнечные навыки."}},faq={{q="Кто выдает это задание и что для него нужно?",a="Тормус Подземная Кузня, кузнец из Великой кузни Стальгорна, предлагает это задание подмастерьям кузнечного дела с навыком не ниже тридцати. Вы должны изготовить шесть медных топоров и шесть медных кольчужных поясов.",al={"who gives supplying the front","quest starter","blacksmith quest requirements","кто дает помощь фронту","начало задания","требования задания кузнеца"}},{q="Где находится Торвальд Подземная Кузня?",a="Торвальд Подземная Кузня находится в южной сторожевой башне Лок Модана. Чтобы добраться до него, идите на юг по главной дороге мимо Телсамара к границе Бесплодных земель: башня стоит возле горного перевала.",al={"where is thorvald","thorvald location","southern guard tower loch modan","где торвальд","местонахождение торвальда","южная сторожевая башня лок модан"}},{q="Почему Горцам нужно так много медных припасов?",a="Горцы в Лок Модане постоянно сражаются со свирепыми троггами. В жестоких боях снаряжение быстро выщербливается, тупится и ломается, поэтому нужен бесконечный приток простого оружия и кольчужных доспехов.",al={"why do they need axes","what is the copper for","зачем им топоры","для чего нужна медь"}},{q="Кем Торвальд приходится Тормусу?",a="Тормус называет Торвальда своим коллегой; они носят общее имя клана Подземной Кузни и тесно связаны как мастера, вместе соединяющие промышленные мощности Стальгорна с полевой обороной.",al={"are thorvald and tormus related","tormus colleague","торвальд и тормус родственники","коллега тормуса"}},{q="Какую награду предлагает Торвальд?",a="В благодарность за облегчение снабжения южной сторожевой башни Торвальд делится знаниями своего ремесла, передавая чертежи новых доспехов.",al={"quest reward","what does thorvald teach","награда за задание","чему учит торвальд"}},{q="Why are the troggs such an issue in Loch Modan right now?",a="Недавние раскопки дворфов вскрыли подземные своды и пещеры по всему Каз Модану и невольно пробудили полчища агрессивных троггов, которые теперь угрожают окрестным поселениям и сторожевым башням.",al={"why are troggs attacking","trogg problem loch modan","почему нападают троггов","проблема троггов лок модан"}}},fp="19,259,23.405.0,21.389.0,43.205.0,36.215.0,53.221.0,36.194.0,40.146.0,57.219.0"}
P.entries["quest:1579"] = {n="Суперразъемы",s="Бацбах Кривошип, гном-изобретатель, мающийся похмельем в Аубердине, просит помочь вернуть ящик с потерянными деталями, который он выбросил в море. Бежав от грохота Стальгорна к тихим берегам Калимдора, он умудрился уронить за борт свои важные суперразъемы во время плавания. Любой с удочкой и терпением может выловить пропавшие детали вдоль побережья.",h="Бацбах Кривошип, гном-изобретатель, мающийся похмельем в Аубердине, просит помочь вернуть ящик с потерянными...",kw={"auberdine","darkshore","electropellers","fishing","gaffer jacks","ironforge","stintle pegs","wizbang cranktoggle","аубердин","темные берега","электропропеллеры","рыбная ловля","суперразъемы","стальгорн","штифты стинтл","бацбах кривошип"},ang={["profession:Engineering"]="Любой инженер знает муку нехватки одной крошечной нестандартной детали, нужной для завершения настройки тонкого устройства.",["race:Gnome"]="Бацбах воплощает неугомонную эксцентричность гномов-механиков, хотя даже другие гномы могут поморщиться от его безрассудного сочетания высокоточных деталей и обильных возлияний.",["race:NightElf"]="Тихие священные леса Темных берегов — странное место для сварливого, страдающего похмельем гнома-изобретателя, и он испытывает легендарное терпение ночных эльфов-часовых Аубердина."},sec={{t="Загроможденный разум в тихой гавани",b="Ища покоя вдали от оглушительного грохота Великой кузни Стальгорна, эксцентричный гном-изобретатель Бацбах Кривошип переплыл Великое море и добрался до Темных берегов. К несчастью, во время плавания Бацбах выпил лишнего. Перегнувшись через поручень в хмельном тумане, он умудрился потерять в прибрежных водах возле Аубердина целый ящик особых металлических деталей — суперразъемов."},{t="Настройка штифтов стинтл",b="Суперразъемы могут показаться случайным прохожим непонятным металлоломом, но для Бацбаха это незаменимые точные инструменты. Без них, по его словам, невозможно как следует настроить штифты стинтл или продолжить тонкую работу. Не желая сам лезть в холодный прибой, гном рассчитывает, что местные рыбаки забросят удочки у Темных берегов и выудят рассыпанные детали."}},faq={{q="Что такое суперразъемы?",a="Суперразъемы — небольшие гномьи механические крепежи и детали. По словам Бацбаха Кривошипа, это жизненно важные особые инструменты, нужные именно для настройки штифтов стинтл в его изобретениях.",al={"what is a gaffer jack","gaffer jack use","gaffer jacks item","что такое суперразъем","применение суперразъемов","предмет суперразъемы"}},{q="Как суперразъемы оказались в море?",a="Бацбах Кривошип выпил лишнего, плывя на корабле из Восточных королевств в Калимдор. Во хмелю он случайно уронил свой ящик с припасами за борт у берегов Темных берегов.",al={"how did he lose them","why are they in the water","why fish for gaffer jacks","как он их потерял","почему они в воде","зачем ловить суперразъемы"}},{q="Почему Бацбах Кривошип в Аубердине, а не в Стальгорне?",a="Бацбах выбрал Аубердин именно за тишину и покой. Постоянный грохот, звон наковален и шумные мастерские Стальгорна стали для него невыносимы, особенно из-за упорного похмелья после сильных возлияний.",al={"why is wizbang in auberdine","why did wizbang leave ironforge","почему бацбах в аубердине","почему бацбах покинул стальгорн"}},{q="Где можно выловить потерянные суперразъемы?",a="Их можно выловить в открытой соленой воде вдоль побережья Темных берегов возле Аубердина. Рыбаки вытаскивают их обычными забросами у берега, а не из косяков рыбы.",al={"where do i fish gaffer jacks","gaffer jacks location","где ловить суперразъемы","местонахождение суперразъемов"}},{q="Что происходит после возвращения суперразъемов?",a="Получив суперразъемы для настройки штифтов, Бацбах признается, что умудрился потерять в море и другой важный комплект оборудования — электропропеллеры, которые тоже придется вылавливать или доставать вплавь.",al={"what next after gaffer jacks","quest after gaffer jacks","что дальше после суперразъемов","задание после суперразъемов"}},{q="Почему Бацбаху нужны искатели приключений, а не он сам?",a="Из-за раскалывающейся головы и отсутствия морских снастей Бацбах предпочитает оставаться на сухих доках Аубердина, а нудную работу по вылавливанию оставляет любому прохожему с удочкой.",al={"why cant wizbang get them","why doesnt wizbang fish","почему бацбах сам не может","почему бацбах не ловит"}}},fp="12,380,33.436.0,23.442.0,22.203.0,43.225.0,61.243.0,45.182.0,47.219.1,69.189.0"}
P.entries["quest:158"] = {n="Сок зомби",s="«Сок зомби» — поручение от Аберкромби, странного отшельника, живущего в зловещих дебрях Сумеречного леса. Жалуясь на гнетущий полуночный холод, он отправляет путников в таверну Темнолесья за необычайно крепким напитком.",h="«Сок зомби» — поручение от Аберкромби, странного отшельника, живущего в зловещих дебрях Сумеречного леса.",kw={"abercrombie","darkshire","duskwood","liquor","scarlet raven tavern","tavernkeep smitts","zombie juice","аберкромби","темнолесье","сумеречный лес","выпивка","таверна алый ворон","хозяин таверны смиттс","сок зомби"},ang={["faction:Alliance"]="Искатели приключений Альянса, помогающие осажденному форпосту Темнолесья, часто становятся посыльными для эксцентричных затворников, укрывшихся вдоль опасных дорог Сумеречного леса."},sec={{t="Холодная просьба",b="Живя в одиночестве среди ужасов темного леса, отшельник Аберкромби часто посылает отзывчивых путников с необычными поручениями. Утверждая, что сумеречная прохлада отнимает у него тепло и силы, он просит искателя приключений дойти на восток до Темнолесья. Ему нужен Хозяин таверны Смиттс из таверны «Алый ворон», у которого он хочет получить бутылку крепкого напитка со зловещим названием Сок зомби, чтобы вернуть огонь в жилы."},{t="В таверне «Алый ворон»",b="В таверне Темнолесья бывает много усталых стражников и напуганных горожан, но просьбы о Соке зомби редки даже для Хозяина таверны Смиттса. У напитка репутация опасно крепкого. Смиттс знает этот сорт, но жажда Аберкромби к такому мрачному зелью вызывает тихие удивленные взгляды в краю, и без того осажденном неупокоенными."}},faq={{q="Что такое Сок зомби?",a="Это исключительно крепкий напиток с мрачным названием, который продает Хозяин таверны Смиттс в Таверне «Алый ворон» в Темнолесье. Обычные посетители просят его редко.",al={"zombie juice drink","what is the liquor","zombie juice lore","напиток сок зомби","что за выпивка","сок зомби предания"}},{q="Кто посылает за Соком зомби?",a="Отшельник Аберкромби, живущий в уединении в лачуге в западной части Сумеречного леса, просит путников принести его, чтобы согреть свои старые кости.",al={"who gives quest zombie juice","abercrombie quest drink","hermit drink request","кто дает задание сок зомби","напиток аберкромби","просьба отшельника"}},{q="Где сдать задание?",a="Вы говорите с Хозяином таверны Смиттсом в Таверне «Алый ворон» — главной гостинице Темнолесья в восточной части Сумеречного леса.",al={"where is smitts","turn in zombie juice","smitts location","где смиттс","сдать сок зомби","местонахождение смиттса"}},{q="Зачем он нужен Аберкромби?",a="Аберкромби утверждает, что мрачные темные ночи Сумеречного леса заставляют его дрожать и что огненный напиток нужен ему, чтобы согреть кровь.",al={"why does abercrombie need juice","abercrombie cold","why does he drink zombie juice","зачем аберкромби сок","аберкромби мерзнет","зачем он пьет сок зомби"}},{q="Удивлен ли Хозяин таверны Смиттс этому заказу?",a="Да. Смиттс отмечает, что Сок зомби — необычайно крепкая вещь, и говорит, что обычные посетители редко его заказывают.",al={"smitts reaction","does smitts have zombie juice","smitts dialogue","реакция смиттса","есть ли у смиттса сок зомби","диалог смиттса"}},{q="Нужно ли в этом задании сражаться с монстрами?",a="Нет. Для поручения нужно лишь пройти по дороге от уединенной хижины Аберкромби до Темнолесья и поговорить с Хозяином таверны Смиттсом, хотя дороги Сумеречного леса всегда полны бродячих зверей и нежити.",al={"zombie juice combat","is zombie juice dangerous","zombie juice mobs","бой сок зомби","опасен ли сок зомби","монстры сок зомби"}}},fp="12,261,16.437.0,20.360.0,21.164.0,36.130.0,31.115.0,29.131.0,44.157.0,46.226.0"}
P.entries["quest:1580"] = {n="Электропеллеры",s="«Электропеллеры» — шутливое поручение эксцентричного гнома-изобретателя Бацбаха Кривошипа из Аубердина. Потеряв сумку с прототипами деталей в пресных ручьях Темных берегов во время неудачного опыта со взрывающейся утиной приманкой, Бацбах просит проходящих мимо рыболовов выловить их.",h="«Электропеллеры» — шутливое поручение эксцентричного гнома-изобретателя Бацбаха Кривошипа из Аубердина.",kw={"auberdine","cliffspring river","darkshore","duck decoy","electropellers","fishing","wildbend river","wizbang cranktoggle","аубердин","река скалистая","темные берега","утиная приманка","электропеллеры","рыбалка","петляющая река","бацбах кривошип"},ang={["profession:Engineering"]="Электропеллеры — любопытные образцы миниатюрных гномьих движителей, предназначенных для приведения в движение механических приманок перед их бурным возгоранием.",["race:Gnome"]="Хаотичное стремление Бацбаха создавать взрывающихся уток знакомо любому гному, хотя потеря дорогих деталей в реке под присмотром эльфов все же слегка неловка.",["race:NightElf"]="Местные ночные эльфы смотрят на шумные, дымные изобретения Бацбаха и его речные оплошности с тихим неодобрением: они предпочитают, чтобы ручьи Темных берегов оставались нетронутыми."},sec={{t="Хмельное изобретение",b="Бацбах Кривошип, гном-изобретатель, живший в тихом порту ночных эльфов Аубердине, целый вечер бродил по внутренним землям Темных берегов в поисках места для испытаний. Его последним увлечением была самоходная взрывающаяся утиная приманка. К несчастью, лишняя порция выпивки привела к несвоевременной потере сознания. Бацбах очнулся спустя несколько часов в городе с опаленными волосами и совершенно пустым рюкзаком: драгоценную сумку с электропеллерами он случайно уронил в одну из прибрежных рек."},{t="Прочесывание вод",b="Вместо того чтобы самому отправляться в дикие земли за разбросанными механическими деталями, Бацбах призывает местных рыбаков обшарить пресные ручьи Темных берегов. Рыболовы, забрасывающие удочки в таких водах, как Петляющая река и Река Скалистая, часто вылавливают эти плавучие металлические штуковины вместе с местной рыбой. Вернув детали, ничего не подозревающий гном сможет продолжить свои опасно непредсказуемые опыты с водоплавающей птицей."}},faq={{q="Где найти электропеллеры?",a="Их нужно вылавливать в пресных реках и озерах Темных берегов, например в Реке Скалистой или Петляющей реке. В морских водах вдоль побережья они не встречаются.",al={"where are electropellers","how to get electropellers","electropeller location","где электропеллеры","как получить электропеллеры","где найти электропеллеры"}},{q="Кто такой Бацбах Кривошип?",a="Бацбах — эксцентричный гном-инженер, живущий в Аубердине. Он известен странными и взрывоопасными изобретениями и полагается на отважных путников, которые собирают для его опытов потерянные детали и диковинки.",al={"who gives electropellers","wizbang cranktoggle","кто дает электропеллеры","бацбах кривошип"}},{q="Что пытался создать Бацбах?",a="Он работал над самоходной взрывающейся утиной приманкой. Испытания пошли наперекосяк, когда он выпил лишнего и случайно взорвал ранний прототип: волосы опалило, а сумка с деталями упала в воду.",al={"exploding duck decoy","wizbang project","взрывающаяся утка","приманка для уток","проект бацбаха"}},{q="Можно ли найти электропеллеры в рыбных косяках?",a="Нет, электропеллеры достают при обычной ловле в пресной воде. Если забрасывать удочку прямо в особые косяки, например в скопления малых масляных черноротиков, механические детали не попадутся.",al={"fish schools electropellers","can i fish schools","косяки электропеллеры","можно ли ловить в косяках"}},{q="Что предшествует этому заданию?",a="Сначала нужно выполнить задание «Суперразъемы» — более раннее рыбацкое поручение, в котором Бацбах проверяет вашу удачу в местных водах.",al={"prereq for electropellers","electropellers prerequisite","предыдущее задание электропеллеры","требования электропеллеры"}},{q="Падают ли электропеллеры с монстров?",a="Нет. Их нельзя добыть с врагов или найти в наземных контейнерах; их нужно вылавливать из рек удочкой.",al={"do mobs drop electropellers","who drops electropellers","падают ли электропеллеры с мобов","кто дропает электропеллеры"}}},fp="14,289,17.479.0,19.429.0,35.178.0,27.202.0,33.229.0,44.184.0,29.124.0,39.130.0"}
P.entries["quest:1581"] = {s="В ветвях Доланаара Сирел Остролист ищет алхимика, чтобы пополнить запасы растущего семейного дела. Ее муж часами простаивает над котлами, и Сирел надеется, что партия свежих эликсиров облегчит его труд, а помощник получит связку редких трав.",h="В ветвях Доланаара Сирел Остролист ищет алхимика, чтобы пополнить запасы растущего семейного дела.",kw={"alchemy","dolanaar","earthroot","elixir of lion's strength","elixir of minor defense","elixirs for the bladeleafs","silverleaf","syral bladeleaf","teldrassil","алхимия","доланаар","землекорень","эликсир силы льва","эликсир малой защиты","эликсиры для клана режущего листа","сребролист","сирел остролист","тельдрассил"},ang={["faction:Alliance"]="Снабжение Доланаара восстанавливающими и защитными зельями помогает защитникам и путешествующим союзникам быть готовыми к лесным угрозам.",["profession:Herbalism"]="Богатая почва Тельдрассила изобилует сребролистом и землекорнем, так что собрать сырье для заказа лавки Сирел совсем несложно.",["race:NightElf"]="Поддержка местных торговцев вроде Остролистов помогает молодому поселению Доланаар расти под кронами Тельдрассила."},sec={{t="Бремя процветания",b="Поселение Доланаар — важный перекресток для путников, часовых и друидов, пересекающих кроны Тельдрассила. Благодаря множеству прохожих торговля травами и алхимией, которую ведут Сирел Остролист и ее муж, процветает. Но высокий спрос имеет свою цену. Муж почти все время склоняется над флаконами и котлами, чтобы полки не пустовали, и у супругов почти не остается времени друг для друга."},{t="Торговый обмен",b="Чтобы муж не выгорел под грузом заказов, Сирел обращается к проходящим мимо травникам и зельеварам. Заказывая готовые зелья — эликсиры силы льва и малой защиты, — она пополняет запасы лавки и предлагает взамен свежесобранные необычные травы. Для начинающего алхимика, практикующего ремесло под Великим Древом, это отличная возможность превратить обычную лесную растительность в редкую местную."}},faq={{q="Зачем Сирел Остролист нужны эти зелья?",a="Семейная лавка трав и алхимии в Доланааре стала очень оживленной. Муж Сирел все время варит зелья, чтобы справиться со спросом, и у них не остается времени друг для друга. Передав часть работы другим, она даст ему столь необходимый отдых.",al={"why need elixirs","syral bladeleaf motive","bladeleaf shop problem","зачем нужны эликсиры","мотив сирел остролист","проблема лавки остролистов"}},{q="Какие зелья нужны для задания?",a="Сирел просит шесть эликсиров силы льва и два эликсира малой защиты. Оба зелья — обычный товар, который часто покупают искатели приключений и местные часовые Тельдрассила.",al={"which elixirs","what do i need to brew","potions needed","какие эликсиры","что нужно сварить","нужные зелья"}},{q="Какие травы нужны для варки этих эликсиров?",a="Для варки требуются сребролист и землекорень, которые в изобилии растут на лесной земле Тельдрассила, а также обычные хрустальные флаконы.",al={"ingredients needed","mats for elixirs","what herbs do i pick","ингредиенты","материалы для эликсиров","какие травы собирать"}},{q="Кто может взяться за это поручение?",a="Задание предлагают только алхимикам, достигшим базового уровня мастерства. Сирел нужны надежные, хорошо приготовленные снадобья для лавки, а не любительские варева.",al={"level requirement","profession requirement","can anyone do this quest","требуемый уровень","требования к профессии","кто может выполнить задание"}},{q="Что Сирел предлагает в обмен на эликсиры?",a="Сирел награждает помогающих алхимиков связкой свежесобранных необычных трав, которые непросто найти на лесных тропах Тельдрассила.",al={"reward lore","what does syral give","bladeleaf trade reward","награда","что дает сирел","награда остролистов"}},{q="Где находится Сирел Остролист?",a="Ее можно найти у северного здания в Доланааре, рядом с центральной дорогой, проходящей через лесную деревню.",al={"where is syral","bladeleaf location","where do i turn this in","где сирел","где остролисты","где сдать задание"}}},fp="26,276,22.435.0,19.467.0,44.238.0,39.175.0,51.165.0,31.185.0,50.161.0,33.119.0"}
P.entries["quest:1582"] = {n="Жилет лунного сияния",s="«Жилет лунного сияния» — обучающее задание от кожевницы-ночной эльфийки Лотериас из Дарнасса. Перегруженная постоянными нуждами юных искателей приключений, отправляющихся в дебри Калимдора, она обменивает знание особого выкроя туники ночных эльфов на крупные партии тисненого кожаного снаряжения.",h="«Жилет лунного сияния» — обучающее задание от кожевницы-ночной эльфийки Лотериас из Дарнасса.",kw={"crafting","darnassus","embossed leather","kaldorei","leatherworking","lotherias","moonglow vest","teldrassil","ремесло","дарнасс","тисненая кожа","кальдораи","кожевничество","лотериас","жилет лунного сияния","тельдрассил"},ang={["faction:Alliance"]="Снаряжение новобранцев в Дарнассе помогает Альянсу удерживать шаткие позиции на севере Калимдора при растущих дикой и враждебной угрозах.",["race:NightElf"]="Жилет лунного сияния воплощает изящное мастерство, типичное для ремесленников Тельдрассила, и дает разведчикам и часовым подвижную защиту под лесным пологом."},sec={{t="Снаряжение для кальдораев",b="В защищенных ветвях Дарнасса ремесленники неустанно трудятся, снаряжая растущие ряды часовых и начинающих лесных разведчиков. Пока юные ночные эльфы и их союзники отправляются за пределы Тельдрассила в неспокойный Калимдор, надежные доспехи очень востребованы. Мастера-кожевники вроде Лотериас несут бремя снабжения этих рубежей прочными шкурами."},{t="Постижение мастерства",b="Чтобы ее ученики обладали и выносливостью, и технической точностью, Лотериас требует доказательств их мастерства в виде нескольких одинаковых предметов: тисненых перчаток, сапог и плащей. Выполнив этот объем, ученик заслуживает ее доверия, и она передает особый выкрой ночных эльфов для жилета лунного сияния — одежды, ценимой за сочетание мягкой защиты и подвижности."}},faq={{q="Кто такая Лотериас?",a="Лотериас — опытная ночная эльфийка, учитель кожевничества в Дарнассе. Она руководит обучением ремеслу для мастеров Альянса и дает сложные чертежи кожевникам, доказавшим свою преданность делу.",al={"lotherias darnassus","who gives moonglow vest","лотериас дарнасс","кто дает жилет лунного сияния"}},{q="Зачем Лотериас столько кожаных вещей?",a="Дарнасс полон недавно обученных искателей приключений, готовящихся отправиться в мир. Мастера не справляются с постоянным спросом на походное снаряжение, поэтому Лотериас поручает обычную тисненую одежду способным ученикам.",al={"why need so many boots","why craft embossed leather","зачем столько сапог","зачем делать тисненую кожу"}},{q="Что такое жилет лунного сияния?",a="Жилет лунного сияния — сложный предмет кожаной брони. Лотериас обучает его выкрою в награду, когда вы показываете, что способны изготавливать большие партии качественных тисненых изделий.",al={"moonglow vest recipe","what do i get","рецепт жилет лунного сияния","что я получу"}},{q="Какие материалы нужны для выполнения этого задания?",a="Нужно предоставить одну пару тисненых кожаных перчаток, пять пар тисненых кожаных сапог и пять тисненых кожаных плащей. Все предметы должны быть изготовлены и доставлены прямо Лотериас.",al={"what do i need","moonglow vest items","что нужно","предметы для жилета лунного сияния"}},{q="Могут ли кожевники Орды изучить этот чертеж здесь?",a="Нет. Лотериас живет в Дарнассе и обучает только мастеров Альянса. Ремесленникам Орды нужно искать своих учителей по всему Калимдору и Восточным королевствам, чтобы развивать ремесло.",al={"can horde do this","is moonglow vest alliance only","может ли орда","жилет лунного сияния только для альянса"}},{q="Требуется ли для этого задания определенный уровень профессии?",a="Да, мастер должен достичь навыка кожевничества не ниже 70, прежде чем Лотериас сочтет его достаточно умелым, чтобы взяться за заказ и изучить выкрой жилета.",al={"leatherworking level needed","when can i get moonglow vest","нужный уровень кожевничества","когда получить жилет лунного сияния"}}},fp="13,317,22.381.0,19.376.0,17.208.0,46.256.0,26.199.0,50.189.0,49.204.0,53.168.0"}
P.entries["quest:159"] = {n="Доставка сока",s="«Доставка сока» — поручение между Темнолесьем и западной окраиной Сумеречного леса. Хозяин таверны Смиттс доверяет вам крепкое варево под названием «Сок зомби», которое нужно доставить отшельнику Аберкромби. Считается, что оно должно согревать дрожащего старика, но необычная крепость напитка вызывает подозрения.",h="«Доставка сока» — поручение между Темнолесьем и западной окраиной Сумеречного леса.",kw={"abercrombie","darkshire","duskwood","juice delivery","scarlet raven","tavernkeep smitts","zombie juice","аберкромби","темнолесье","сумеречный лес","доставка сока","алый ворон","хозяин таверны смиттс","сок зомби"},ang={["faction:Alliance"]="Жители Темнолесья полагаются на храбрых курьеров Альянса, способных пройти по опасным дорогам Сумеречного леса, хотя доверять каждому лесному отшельнику бывает чревато бедой.",["profession:Cooking"]="Рецепт «Сока зомби» Хозяина таверны Смиттса сильно зависит от резко пахнущих необычных ингредиентов и проверяет границы того, что можно считать трактирным напитком."},sec={{t="Сомнительное варево",b="Хозяин таверны Смиттс из Темнолесья варит легендарный напиток, в народе известный как «Сок зомби». Когда заказ наконец готов, Смиттс вручает бутылку со строгим предупреждением обращаться с ней осторожно и замечает, что варево достаточно крепко, чтобы поднять мертвеца. Для усталого искателя приключений, выполняющего поручения в населенном призраками лесу, доставка крепкого самогона эксцентричному затворнику кажется обычным благодеянием."},{t="Оплошность отшельника",b="Путь с опасным варевом на запад мимо воющих воргенов и неупокоенных мертвецов ведет прямо к хижине Аберкромби на краю леса. Получив бутылку, хилый затворник утверждает, что ему нужен напиток лишь для того, чтобы согреть ноющие кости в холодные туманные ночи Сумеречного леса. Однако, взяв ее, он едва не благодарит путника за «глупость», но тут же поправляется и хвалит его «доброту» — эта оговорка намекает, что в голове отшельника зреет нечто большее, чем простой вечерний напиток."}},faq={{q="Что такое «Сок зомби»?",a="«Сок зомби» — чрезвычайно крепкий напиток, который готовит Хозяин таверны Смиттс в таверне «Алый ворон» в Темнолесье. Хотя его считают крепким спиртным, Смиттс говорит, что варево способно разбудить мертвых, так что оно куда опаснее обычных напитков.",al={"zombie juice lore","what is smitts juice","abercrombie drink","сок зомби","что за сок смиттса","напиток аберкромби"}},{q="Кто заказывает «Сок зомби»?",a="Доставку просит Аберкромби, эксцентричный старый отшельник, живущий в уединенной хижине у западной границы Сумеречного леса.",al={"who wants the juice","who is juice delivery for","кто хочет сок","для кого доставка сока"}},{q="Зачем Аберкромби нужен напиток?",a="Аберкромби утверждает, что напиток нужен ему, чтобы согреваться в лютые сырые ночи Сумеречного леса. Однако оговорка при получении бутылки намекает, что у него куда более зловещие планы на это варево.",al={"why does abercrombie need juice","abercrombie cold","зачем аберкромби сок","аберкромби холод"}},{q="Кто варит «Сок зомби»?",a="Хозяин таверны Смиттс, трактирщик таверны «Алый ворон» в самом сердце Темнолесья, варит напиток сам, получив необходимые резко пахнущие ингредиенты.",al={"who makes zombie juice","smitts barkeep","кто делает сок зомби","смиттс трактирщик"}},{q="Где находится хижина Аберкромби?",a="Хижина Аберкромби одиноко стоит в западной части Сумеречного леса, к северо-западу от холмов Кладбища Вороньего Холма и чуть восточнее горного перевала, ведущего в Западный Край.",al={"abercrombie location","where is abercrombie shack","где аберкромби","где хижина аберкромби"}},{q="Что делает Аберкромби после получения сока?",a="Заполучив «Сок зомби», Аберкромби продолжает докучать доверчивым путникам, отправляя их на Кладбище Вороньего Холма собирать ребра вурдалаков для жуткого чучела, которое, по его словам, отпугнет нежить.",al={"next quest after juice delivery","what happens next","следующее задание после доставки сока","что дальше"}}},fp="14,317,20.410.0,17.548.1,21.267.0,28.133.0,36.222.0,27.171.0,29.146.0,56.205.0"}
P.entries["quest:1598"] = {n="Украденная книга",s="«Украденная книга» — вступительное задание для начинающих чернокнижников-людей, обучающихся в Долине Североземья. По поручению учительницы Друзиллы ла Салле адепт должен проникнуть в соседний лагерь Братства Справедливости и вернуть запретный текст «Силы Бездны». Так юный чернокнижник доказывает свои способности и получает знания, необходимые, чтобы подчинить своего первого демона-слугу.",h="«Украденная книга» — вступительное задание для начинающих чернокнижников-людей, обучающихся в Долине...",kw={"defias brotherhood","drusilla la salle","northshire abbey","novice thief","powers of the void","stolen book","vineyards","warlock imp","братство справедливости","друзилла ла салле","аббатство североземья","послушник-вор","силы бездны","украденная книга","виноградники","бес чернокнижника"},ang={["class:Warlock"]="Этот обряд посвящения проверяет, сможет ли начинающий чернокнижник пройти по опасной местности без страха. Добыв книгу, вы получаете тайные обряды, необходимые, чтобы призвать вашего первого беса.",["faction:Alliance"]="Действуя прямо под носом у паладинов и клириков Североземья, чернокнижники Альянса должны вести себя тихо и пользоваться промахами преступников, чтобы получить запретные тайные знания.",["race:Human"]="Задание показывает, насколько глубоко влияние Братства Справедливости проникло в Североземье: оно соблазнило даже затворников-учеников аббатства красть священные тексты и присоединяться к мятежу."},sec={{t="Запретная возможность",b="Чернокнижники осторожно ведут себя во владениях Штормграда: они занимаются своим опасным ремеслом в тайных уголках и скрывают исследования от посторонних глаз. В архивах Аббатства Североземья хранятся древние знания, в том числе запретные гримуары под замком. Друзилла ла Салле, наставница чернокнижников, обосновавшаяся на землях аббатства, желала заполучить один такой том — «Силы Бездны», — но не решалась рисковать, вызвав подозрения клириков и паладинов аббатства попыткой самой проникнуть в охраняемое крыло библиотеки."},{t="Расчет Братства Справедливости",b="Возможность представилась Друзилле ла Салле, когда один из послушников аббатства примкнул к Братству Справедливости. Бежав в Виноградники Североземья к бандитам, ученый-отступник прихватил с собой несколько ценных текстов. Укрывшись в лагере Братства Справедливости среди виноградников, воры спрятали добычу в палатке, не подозревая об истинной опасности темных искусств, заключенных в книге."},{t="Первое подчинение",b="Для начинающего чернокнижника возвращение книги — это и проверка выдержки, и практический путь к более темным тайнам. Отважившись пройти в лагерь бандитов и вернув текст, послушник удовлетворяет амбиции Друзиллы и доказывает свою готовность. Получив гримуар, она награждает ученика темными обрядами, необходимыми, чтобы призвать и подчинить беса — первого демона, которым учится повелевать ученик."}},faq={{q="Что такое «Силы Бездны»?",a="Это запретный гримуар, описывающий темные магические понятия и управление иными мирами. Первоначально он хранился в охраняемом, защищенном крыле библиотеки Аббатства Североземья. В нем содержатся тайные знания, которые жаждут получить для личных исследований и обучения наставники чернокнижников, например Друзилла ла Салле.",al={"powers of the void book","what is the book","what did the novice steal","книга силы бездны","что за книга","что украл послушник"}},{q="Почему Друзилла ла Салле не украла книгу сама?",a="Друзилле нужно соблюдать осторожность, чтобы сохранить свое положение в Аббатстве Североземья. Проникновение в закрытые архивы библиотеки немедленно вызвало бы тревогу среди клириков. Когда недовольный послушник украл книгу и примкнул к Братству Справедливости, у нее появился отличный шанс получить ее чисто, воспользовавшись учеником.",al={"why drusilla didn't steal it","why send me","почему друзилла не украла книгу","почему я"}},{q="Где спрятана украденная книга?",a="Бандиты из Братства Справедливости спрятали книгу в палатке лагеря, разбитого в Виноградниках Североземья, к востоку от аббатства, где обосновались их разведчики и отступники.",al={"where is the book","tome location","stolen tome tent","где книга","местонахождение книги","палатка с книгой"}},{q="Почему послушник из Североземья примкнул к Братству Справедливости?",a="Недовольство и социальные волнения охватили королевство и толкнули рабочих, крестьян и даже учеников церкви на сторону Братства Справедливости. Послушник нарушил обеты, захватил из библиотеки несколько важных книг в качестве добычи и бежал к бандитам в виноградниках.",al={"why novice joined defias","abbey defias traitor","who stole the book","почему послушник примкнул к братству справедливости","предатель из аббатства","кто украл книгу"}},{q="Какую награду получает чернокнижник за возвращение книги?",a="Возвращение книги убеждает Друзиллу, что ученик обладает выдержкой и стойкостью для занятий темными искусствами. Она дает основы знаний, необходимые для призыва беса, — первого удачного демонического союза ученика.",al={"what do you learn","warlock quest reward","why do this quest","чему учат","награда чернокнижника","зачем выполнять задание"}},{q="Умеют ли бандиты Братства Справедливости пользоваться книгой?",a="Бандиты считают украденные книги прежде всего ценной добычей, взятой в аббатстве. Хотя в Братстве Справедливости есть чародеи-отступники, послушник и его товарищи просто припрятали том в ящике в палатке, не стремясь постичь его темные тайны.",al={"can defias use the tome","what defias do with book","могут ли братство справедливости использовать книгу","что делают с книгой"}}},fp="15,377,23.518.0,18.420.0,17.410.0,31.286.0,52.312.0,32.181.0,56.276.0,55.237.0,39.246.0"}
P.entries["quest:1599"] = {n="В начале славных дел",ang={["class:Warlock"]="Это задание — важнейший первый шаг пути чернокнижника Альянса в Дун Мороге: оно открывает возможность призвать вашего первого демона-слугу.",["race:Gnome"]="Гномы-чернокнижники, постигающие свое ремесло в Холодной долине, должны доказать свой ум и магическое превосходство, перехитрив местных троллей Мерзлогривов."},sec={{t="Неохотный наставник",b="Within the safe haven of Anvilmar, dark magic is not openly celebrated, but it is tolerated out of necessity. Alamar Grimm, an established warlock, conducts his occult research in relative discretion. When new practitioners show raw promise, Grimm is persuaded by unknown backers among Ironforge's darker circles to step away from his studies and assess the recruits personally."},{t="Искра темной магии",b="Before granting a novice the secrets to enslaving lesser demons, Grimm requires practical proof of both physical endurance and magical affinity. Nearby Frostmane troll novices, gathering in a cave southwest of Anvilmar, carry primitive feather charms infused with subtle primal magics. Harvesting these charms proves the aspiring warlock can conquer a magical adversary, while also providing Grimm with curious specimens for his ongoing research."},{t="Призыв беса",b="Returning with the charms satisfies Grimm that the novice has sufficient will to survive. The trial culminates in teaching the summoning of the imp, the warlock's most foundational minion. Grimm offers a stern warning alongside the ritual: despite their diminutive stature, imps wield chaotic fire magic that can easily overpower an undisciplined master."}},faq={{q="Кто дает задание «В начале славных дел»?",a="Alamar Grimm gives the quest. He is a warlock trainer located inside Anvilmar in Coldridge Valley, Dun Morogh.",al={"who starts beginnings","beginnings quest giver","alamar grimm location"}},{q="Для чего нужны перьевые обереги?",a="The feather charms serve a dual purpose: they prove an aspiring warlock can face and defeat magically adept enemies, and they provide Alamar Grimm with curious enchanted troll trinkets to examine in his research.",al={"why feather charms","feather charm purpose","frostmane charms","зачем перьевые обереги","назначение перьевых оберегов","обереги мерзлогривов"}},{q="Где находятся молодые Мерзлогривы?",a="Они обитают в пещере к юго-западу от Старой Наковальни в Холодной долине, где обосновались тролли Мерзлогривы.",al={"where are the troll novices","frostmane cave location","frostmane novice spot","где молодые тролли","пещера мерзлогривов","где мерзлогривы"}},{q="Какую награду получает чернокнижник за выполнение этого задания?",a="Completing the task earns Alamar Grimm's approval and grants the knowledge required to summon an imp, a warlock's first demonic companion.",al={"what does beginnings teach","quest reward beginnings","imp spell quest","чему учит в начале славных дел","награда за задание","заклинание беса"}},{q="Why is Alamar Grimm teaching new warlocks?",a="Grimm mentions that influential voices have taken an interest in the fledgling warlock, convincing him to pause his private occult studies to test and mentor the recruit.",al={"why does alamar train me","who told alamar to train me"}},{q="Опасен ли бес для начинающего чернокнижника?",a="Yes. Alamar Grimm explicitly cautions that despite an imp's small size, its fel fire and cunning make it volatile, and an inexperienced summoner can easily be overpowered by one.",al={"imp danger","can imps kill you","imp warnings","опасность беса","могут ли бесы убить","предупреждения о бесах"}}},fp="10,299,18.378.0,23.446.0,17.354.0,31.110.0,37.212.0,40.127.0,58.138.0,42.170.0,42.178.0"}
P.entries["quest:16"] = {n="Жажда Джерарда",s="«Жажда Джерарда» — простая услуга для Джерарда Румпеля, фермера, трудящегося на Виноградниках Маклура в Элвиннском лесу. Желая утолить жажду под солнцем, он обменивает простые продукты на бутылки свежей ключевой воды. Задание дает юным искателям приключений ранний урок обмена и помощи местным работникам.",h="«Жажда Джерарда» — простая услуга для Джерарда Румпеля, фермера, трудящегося на Виноградниках Маклура в...",kw={"abbey farm","apples","barter","elwynn forest","gerard tiller","northshire valley","refreshing spring water","ферма аббатства","яблоки","обмен","элвиннский лес","джерард румпель","долина североземья","освежающая ключевая вода"},ang={["faction:Alliance"]="Поддержка фермеров Североземья помогает гарнизону и священникам аббатства оставаться сытыми в неспокойное время обороны королевства.",["race:Human"]="Для людей, начинающих путь в Североземье, помощь соседям вроде Джерарда Румпеля — ранний пример общинного духа, на котором держится Элвинн."},sec={{t="Жаркая работа на виноградных полях",b="Фермы Элвиннского леса производят большую часть зерна, фруктов и овощей, которые едят горожане и гарнизоны Штормграда. Ухаживать за грядками под открытым небом — тяжелый, жаркий труд. Джерард Румпель проводит долгие дни в грязи на Виноградниках Маклура, отгоняя вредителей и управляясь с урожаем. Ему некогда бегать к городским колодцам, поэтому он рассчитывает на проходящих новобранцев, которые принесут чистую ключевую воду, чтобы он мог продолжать работу."},{t="Экономика обмена",b="Вместо денег Джерард предпочитает честный и простой обмен припасами. Путники с лишними флягами освежающей ключевой воды могут обменять их прямо на свежие яблоки из сада. В королевстве, которое с трудом тянет ресурсы, чтобы поддерживать порядок и кормить армию, прямой обмен между мелкими хозяевами и новобранцами остается практичным способом выживать в сельском Элвинне."}},faq={{q="Кто такой Джерард Румпель?",a="Джерард Румпель — скромный фермер, работающий на сельскохозяйственных участках Виноградников Маклура на юге Элвиннского леса. Он управляет полями и садами, снабжающими местных жителей.",al={"gerard tiller","who is tiller","gerard","джерард румпель","кто такой румпель","джерард"}},{q="Зачем Джерарду вода?",a="Целый день трудиться в полях под солнцем изнурительно. Джерард рассчитывает, что проходящие путники принесут ему свежую ключевую воду, чтобы он мог утолять жажду, не бросая работу.",al={"why spring water","gerard thirsty","why need drink","зачем ключевая вода","джерард хочет пить","зачем нужно питье"}},{q="Где можно найти освежающую ключевую воду?",a="Освежающую ключевую воду обычно продают торговцы едой и напитками и трактирщики по всему Элвиннскому лесу, в том числе брат Данил в Аббатстве Североземья.",al={"where get water","spring water source","how to get water","где взять воду","источник ключевой воды","как получить воду"}},{q="Можно ли повторять этот обмен?",a="Да. Джерард постоянно работает в полях и охотно обменивает свежие яблоки из сада на новые бутылки воды, пока они у вас есть.",al={"repeatable quest","can i do this again","turn in more water","повторяемое задание","можно ли повторить","сдать больше воды"}},{q="Что Джерард предлагает взамен за питье?",a="В обмен на свежую воду Джерард дает спелое красное яблоко.",al={"gerard reward","what do i get","trade reward","награда джерарда","что я получу","награда за обмен"}},{q="Где находится Джерард?",a="Его можно найти у амбара на Виноградниках Маклура на юге Элвиннского леса.",al={"gerard tiller location","where is gerard","where is the farm","где джерард румпель","где джерард","где ферма"}}},fp="19,325,35.446.0,21.394.0,21.183.0,27.192.0,43.155.0,25.160.0,47.61.0,24.84.0"}
P.entries["quest:160"] = {n="Записка для мэра",s="«Записка для мэра» — задание Альянса в Сумеречном лесу, связывающее эксцентричного отшельника Аберкромби с руководством Темнолесья. После того как искатели приключений помогают нелюдимому старику, их просят лично передать послание мэру, лорду Элло Чернодреву. Однако письмо сразу вызывает не радость, а подозрения.",h="«Записка для мэра» — задание Альянса в Сумеречном лесу, связывающее эксцентричного отшельника Аберкромби с...",kw={"abercrombie","darkshire","duskwood","ello ebonlocke","letter","mayor","note to the mayor","аберкромби","темнолесье","сумеречный лес","элло чернодрев","письмо","мэр","записка для мэра"},ang={["faction:Alliance"]="Выживание Темнолесья зависит от того, удастся ли разгадать странные происшествия, прежде чем они прорвут оборону Ночного Дозора, поэтому это подозрительное письмо немедленно становится вопросом безопасности для агентов Альянса.",["race:Human"]="Люди-посыльные, служащие Ночному Дозору и дому Чернодревов, быстро понимают, что странный старый отшельник на окраине Сумеречного леса обманул их."},sec={{t="Дружеское послание?",b="После того как вы помогли Аберкромби вернуть украденный ограми сундук из Лощины Вул'Гол, отшельник отправляет вас обратно по окутанным туманом дорогам к городу. Посмеиваясь от удовольствия, Аберкромби утверждает, что они с мэром, лордом Элло Чернодревом, старые друзья. Он уверяет, что, узнав о том, что совершил искатель приключений, мэр обрадуется так же сильно, как и он сам."},{t="Озадаченное руководство",b="По прибытии в ратушу Темнолесья выясняется, что действительность противоречит словам Аберкромби. Лорд Элло Чернодрев не помнит никого по имени Аберкромби. Развернув пергамент, он лишь сильнее запутывается: вместо сердечного приветствия старых товарищей там написано древними нечитаемыми письменами, которые приводят мэра Темнолесья в полное замешательство."}},faq={{q="Кто отправляет «Записку для мэра»?",a="Аберкромби, эксцентричный отшельник, живущий в уединенной лачуге на западной окраине Сумеречного леса, вручает вам письмо после того, как вы возвращаете его украденные вещи у местных огров.",al={"who gives note to the mayor","who starts note to the mayor","abercrombie letter sender","кто дает записку для мэра","кто начинает записку для мэра","кто отправитель письма аберкромби"}},{q="Действительно ли Аберкромби и мэр Чернодрев друзья?",a="Нет. Хотя Аберкромби утверждает, что они старые знакомые, мэр, лорд Элло Чернодрев, никогда о нем не слышал и выражает полное недоумение по поводу полученного послания.",al={"do they know each other","is abercrombie friends with the mayor","abercrombie ello ebonlocke relationship","знают ли они друг друга","дружит ли аберкромби с мэром","аберкромби элло чернодрев отношения"}},{q="Что написано в записке?",a="Записка написана на древнем, малоизвестном языке, который не могут разобрать ни посыльный, ни мэр Чернодрев, поэтому мэр решает обратиться за переводом к кому-то другому.",al={"what does abercrombie note say","can ello read the note","what language is the letter","что говорится в записке аберкромби","может ли элло прочесть записку","на каком языке письмо"}},{q="Где находится лорд Элло Чернодрев?",a="Мэр, лорд Элло Чернодрев, находится в Ратуше Темнолесья, на восточной стороне города у главной дороги в Сумеречном лесу.",al={"where is the mayor","ello ebonlocke location","where do i turn in note to the mayor","где мэр","где найти элло чернодрева","куда сдать записку для мэра"}},{q="Что происходит после того, как мэр Чернодрев получает письмо?",a="Поскольку лорд Чернодрев не может прочесть загадочные письмена, он просит вас найти того, кто сможет истолковать текст. Так начинается задание «Перевод записки Аберкромби».",al={"what is next after note to the mayor","what follows note to the mayor","что дальше после записки для мэра","что следует за запиской для мэра"}},{q="Почему Аберкромби смеялся, когда отдавал вам письмо?",a="Радостный смех Аберкромби намекает, что его замыслы намного мрачнее простой встречи со старым знакомым, и предвещает Темнолесью зловещие беды.",al={"why does abercrombie laugh","is abercrombie evil","abercrombie laugh note","почему аберкромби смеется","зол ли аберкромби","смех аберкромби записка"}}},fp="17,319,19.373.0,18.368.1,32.178.0,53.164.0,28.159.0,37.126.0,55.168.0,57.165.1"}
P.entries["quest:161"] = {n="Прямая и черная угроза",s="Заподозрив диверсию на Каменной Плотине, главный инженер Плотиннер VII отправляет посыльного на север, в опасную Болотину, чтобы проверить образец взрывчатого порошка. Посыльному предстоит пройти по опасной дороге мимо Врат Альгаза и доставить образец эксперту по взрывчатке Ашлану Камнехмылу в Дун Модр.",h="Заподозрив диверсию на Каменной Плотине, главный инженер Плотиннер VII отправляет посыльного на север, в...",kw={"ashlan stonesmirk","dark threat looms","dun modr","explosive powder","hinderweir","stonewrought dam","thandol span","wetlands","ашлан камнехмыл","прямая и черная угроза","дун модр","взрывчатый порошок","плотиннер","каменная плотина","мост тандола","болотина"},ang={["faction:Alliance"]="Дорога через Лок Модан и Болотину служит важнейшей военной артерией между Стальгорном и северными владениями Альянса за Мостом Тандола.",["profession:Engineering"]="Определение остатков мощной взрывчатки требует наметанного глаза сапера и доказывает, что даже обычные порошки могут выдать техническое мастерство вражеского диверсанта.",["race:Dwarf"]="Каменная Плотина — одна из жемчужин инженерного искусства Бронзобородов. Любой признак заговора с целью разрушить ее кладку бьет по гордости и безопасности всего Каз Модана."},sec={{t="Порошок со злым умыслом",b="После происшествий у Каменной Плотины главному инженеру Плотиннеру VII приносят странно пахнущий порошок из подозрительной бочки у восточного пандуса плотины, где он заметил саперов Черного Железа. Понимая, что возможна катастрофическая диверсия, Плотиннер предполагает, что это очищенная взрывчатка, способная разрушить кладку дворфов. Не имея на плотине специального оборудования для химических анализов, он настаивает на консультации с армейским подрывником, прежде чем делать выводы."},{t="Дорога на север",b="Срочный анализ требует пути через Врата Альгаза вниз, в сырые низины Болотины. Болота кишат враждебными животными, агрессивными драконидами и лазутчиками Черного Железа, так что путь полон опасностей. Плотиннер призывает путников твердо держаться мощеной дороги до самого Дун Модра — укрепленного форпоста дворфов, прикрывающего южный подход к Мосту Тандола."},{t="Эксперт по взрывчатке из Дун Модра",b="Ашлан Камнехмыл, служащий на передовой в северной части Каз Модана, — главный знаток мощной взрывчатки в полку. Наполовину оглохший за десятилетия сотрясающих взрывов, Камнехмыл по виду и запаху сразу подтверждает худшие опасения Плотиннера: состав действительно является специальным подрывным зарядом, а значит, это спланированный заговор, направленный в самое сердце дворфийской инженерии."}},faq={{q="Что это за странно пахнущий порошок?",a="Это алхимический взрывчатый заряд, собранный возле Каменной Плотины. Главный инженер Плотиннер VII подозревает, что диверсанты намерены с его помощью пробить стены плотины.",al={"what is the powder","hinderweir powder","strange powder","что за порошок","порошок плотиннера","странный порошок"}},{q="Почему порошок отправляют так далеко, в Дун Модр?",a="В Дун Модре расквартирован военный отряд Стальгорна, защищающий Мост Тандола, в том числе подрывник Ашлан Камнехмыл. Как опытный эксперт по взрывчатке, он обладает техническими знаниями, необходимыми для определения специальных взрывчатых составов.",al={"why dun modr","why ashlan stonesmirk","why go to wetlands","почему дун модр","почему ашлан камнехмыл","зачем идти в болотину"}},{q="Где находится Ашлан Камнехмыл?",a="Ашлан Камнехмыл служит в военном лагере Дун Модр, расположенном на крайнем севере Болотины, к югу от Моста Тандола.",al={"where is stonesmirk","find ashlan","stonesmirk location","где камнехмыл","найти ашлана","где находится камнехмыл"}},{q="Почему Плотиннер предупреждает держаться дороги?",a="Дорога, спускающаяся от Врат Альгаза через Болотину, проходит прямо по землям, кишащим враждебными зверями, ящерами, гноллами и диверсантами Черного Железа, поэтому путешествие вне дороги крайне опасно для посыльных.",al={"why stick to road","wetlands dangers","road to wetlands","почему держаться дороги","опасности болотины","дорога в болотину"}},{q="Кто устраивает диверсию на Каменной Плотине?",a="Взрывчатка принадлежит дворфам Черного Железа, которые стремятся подорвать инфраструктуру Бронзобородов и разрушить Каменную Плотину, чтобы затопить долины внизу.",al={"who made the powder","dam saboteurs","dark threat culprit","кто сделал порошок","диверсанты плотины","виновник темной угрозы"}},{q="Почему Ашлан Камнехмыл плохо слышит?",a="Годы службы армейским сапером на передовой и специалистом по взрывчатке оставили Ашлана с постоянным звоном в ушах и сильной потерей слуха от взрывных контузий.",al={"stonesmirk deaf","why can't ashlan hear","камнехмыл глухой","почему ашлан не слышит"}}},fp="19,321,22.504.0,14.414.0,28.390.1,36.162.0,44.236.0,35.149.0,46.223.0,39.158.1,41.171.0"}
P.entries["quest:1618"] = {n="Экипирование Красногорья",s="«Экипирование Красногорья» — торговое задание Альянса для кузнецов, которое выдает Тормус Подземная Кузня в Стальгорне. Начинающие кузнецы куют прочное медное снаряжение, чтобы помочь осажденному гарнизону Приозерья и местному кузнецу Вернеру Осгуду защитить область от враждебных орков и гноллов.",h="«Экипирование Красногорья» — торговое задание Альянса для кузнецов, которое выдает Тормус Подземная Кузня в...",kw={"blackrock orcs","blacksmithing","gnolls","heavy copper maul","lakeshire","redridge","runed copper belt","stonewatch","tormus deepforge","verner osgood","орки Черной горы","кузнечное дело","гноллы","тяжелый медный молот","приозерье","красногорье","рунический медный пояс","каменная стража","тормус подземная кузня","вернер осгуд"},ang={["faction:Alliance"]="Эта поставка показывает жизненно важную взаимопомощь между Стальгорном и осажденными человеческими поселениями юга, где Стальгорн приходит на помощь там, где отстало разделенное руководство Штормграда.",["profession:Blacksmithing"]="Это задание — обряд посвящения для начинающих кузнецов: оно проверяет вашу способность по требованию массово изготавливать прочное оружие и защитные доспехи для действующего фронта.",["race:Dwarf"]="Мастерство дворфов — становой хребет военных усилий Альянса, и Тормус следит, чтобы талантливые мастера Стальгорна использовали свое ремесло для помощи осажденным союзникам.",["race:Human"]="Для людей южных королевств металлические изделия, выкованные в Каз Модане, — крайне необходимая помощь против агрессивных остатков Черной горы."},sec={{t="Мольба через королевства",b="Хотя Великая кузня Стальгорна почти не знает покоя, кузнецы-дворфы понимают, что борьба Альянса на передовой выходит далеко за пределы Дун Морога. В Красногорье человеческое поселение Приозерье постоянно подвергается нападениям: орки Черной горы выходят из Крепости Каменной Стражи, а бродячие стаи гноллов наводняют северные хребты. Поскольку королевские подкрепления из Штормграда прибывают медленно, местные запасы остаются опасно истощенными."},{t="Наковальни Приозерья",b="Местный кузнец Приозерья Вернер Осгуд работает почти в одиночку у своего кузнечного горна под открытым небом, пытаясь чинить разбитые доспехи и заменять сломанное оружие. Понимая, как тяжело его человеческому коллеге, Тормус Подземная Кузня поручает начинающим кузнецам доставить в Приозерье четыре рунических медных пояса и четыре тяжелых медных молота. В обмен на пополнение оборонных запасов ополчения Вернер охотно передает странствующим мастерам более тонкие приемы ремесла."}},faq={{q="Кто выдает задание «Экипирование Красногорья»?",a="Тормус Подземная Кузня, кузнец-дворф из Великой кузни в Стальгорне, предлагает это задание кузнецам Альянса, достаточно овладевшим своим ремеслом.",al={"gearing redridge questgiver","who gives gearing redridge","tormus quest","экипирование красногорья выдающий задание","кто дает экипирование красногорья","задание тормуса"}},{q="Почему Приозерью нужны оружие и доспехи из Стальгорна?",a="Приозерье постоянно подвергается нападениям орков Черной горы, занявших Крепость Каменной Стражи, а также агрессивных местных гноллов. Единственный кузнец города, Вернер Осгуд, совершенно не справляется с починкой оружия и снаряжением ополчения в одиночку.",al={"why redridge needs gear","why lakeshire needs weapons","redridge supply shortage","почему красногорью нужно снаряжение","почему приозерью нужно оружие","нехватка припасов в красногорье"}},{q="Кто принимает груз в Красногорье?",a="Груз доставляется Вернеру Осгуду, местному кузнецу, работающему у горна в прибрежном городке Приозерье.",al={"where to turn in gearing redridge","verner osgood location","redridge blacksmith turnin","куда сдавать экипирование красногорья","где вернер осгуд","кузнец красногорья сдача задания"}},{q="Какое снаряжение нужно выковать для задания?",a="Вы должны предоставить четыре рунических медных пояса и четыре тяжелых медных молота. Они демонстрируют мастерство как в защитных пластинах, так и в тяжелом ударном оружии.",al={"gearing redridge items needed","materials for gearing redridge","what to craft for tormus","экипирование красногорья нужные предметы","материалы для экипирования красногорья","что выковать для тормуса"}},{q="Какие угрозы беспокоят Красногорье в это время?",a="Главные опасности для Приозерья — кланы орков Черной горы, закрепляющиеся в Крепости Каменной Стражи, и свирепые стаи гноллов, рыщущие по северным предгорьям.",al={"redridge enemies","who is attacking lakeshire","redridge threats","враги красногорья","кто нападает на приозерье","угрозы красногорья"}},{q="Какую награду предлагает Вернер Осгуд взамен?",a="Избавившись от изнуряющего бремени снаряжать каждого стражника с нуля, Вернер находит время, чтобы обучить вас продвинутым приемам кузнечного дела.",al={"verner osgood training","reward for gearing redridge","what do i get","обучение у вернера осгуда","награда за экипирование красногорья","что я получу"}}},fp="16,277,22.481.0,23.464.0,38.157.0,57.240.0,38.124.0,43.144.0,49.188.0,47.146.0"}
P.entries["quest:163"] = {n="Вороний холм",s="Сообщения о движущихся тенях и мерцающем свете в окнах заброшенного поселения Вороний Холм встревожили Ночной Дозор. По поручению Иланы Карвин из Темнолесья путники отправляются на запад через населенный призраками лес, чтобы встретиться со зловещим существом, укрывшимся среди руин.",h="Сообщения о движущихся тенях и мерцающем свете в окнах заброшенного поселения Вороний Холм встревожили Ночной...",kw={"calor","darkshire","duskwood","elaine carevin","jitters","night watch","raven hill","калор","темнолесье","сумеречный лес","илана карвин","трясунчик","ночной дозор","вороний холм"},ang={["class:Paladin"]="Паладин, обученный охоте на неупокоенную нежить с соседнего кладбища, расследуя сообщения о зловещих призраках, может неожиданно обнаружить скулящего Трясунчика из плоти и крови.",["faction:Alliance"]="Ночной Дозор Сумеречного леса почти не получает помощи от гарнизона Штормграда, поэтому ему приходится полагаться на странствующих героев Альянса, которые проверяют зловещие угрозы в заброшенных уголках края."},sec={{t="Глаза на западе",b="Для разведчиков Ночного Дозора дальний западный край Сумеречного леса уже давно отдан мертвецам и дикой природе. Однако полное запустение было бы предпочтительнее неожиданной активности. Калор, дозорный, патрулирующий мрачные дороги, две ночи подряд замечал движение среди безмолвных домов Вороньего Холма, а в окне тревожно мерцал свет фонаря. В краю, где орудуют упыри, скелеты и звери, любые необъяснимые признаки жизни требуют немедленной проверки."},{t="Перепуганный отшельник",b="Те, кто ожидает в Вороньем Холме схватки с явившимся демоном или предводителем нежити, находят куда более жалкую картину. Среди полуразрушенных руин в ужасе жмется Трясунчик — совершенно обезумевший бродяга, вздрагивающий от каждого шороха во тьме. Он исступленно твердит, что здесь нет иной угрозы, кроме «безобидного Трясунчика», но его лихорадочный бред говорит о том, что он знает о кошмаре, поглощающем Сумеречный лес, гораздо больше, чем осмеливается сказать."}},faq={{q="Кто посылает вас проверить Вороний Холм?",a="Илана Карвин, жительница Темнолесья, помогающая Ночному Дозору, просит путников, которым небезразлична безопасность Сумеречного леса, проверить тревожные сообщения с запада.",al={"who gives raven hill quest","quest giver raven hill","elaine carevin quest","кто дает задание вороний холм","персонаж, выдающий задание вороний холм","задание илана карвин"}},{q="Что именно Калор увидел в Вороньем Холме?",a="Калор сообщил, что две ночи подряд видел движущиеся тени в заброшенном поселении, а за ночь до этого — фонарь или свечу, горевшие в одном из окон.",al={"what did calor see","calor sighting raven hill","shadows in raven hill","что видел калор","калор вороний холм","тени в вороньем холме"}},{q="Какое чудовище обитает в руинах?",a="Именно это вам и предстоит выяснить. Калор лишь мельком заметил движущиеся тени и свет в окне; тот, кто скрывается в заброшенных зданиях Вороньего Холма, должен быть найден лично.",al={"who is haunting raven hill","what is in raven hill","is raven hill monster real","кто обитает в вороньем холме","что в вороньем холме","чудовище вороний холм"}},{q="Кто такой Трясунчик?",a="Трясунчик — дерганый, мнительный бродяга, живущий на грани ужаса на западе Сумеречного леса. Он уверяет, что совершенно безобиден, но его крайнее чувство вины и лихорадочный бред намекают, что он замешан в мрачных тайнах этих мест.",al={"jitters lore","who is jitters duskwood","why is jitters hiding","трясунчик предания","кто такой трясунчик сумеречный лес","почему трясунчик прячется"}},{q="Где находится Вороний Холм?",a="Вороний Холм лежит на дальнем западе Сумеречного леса, к югу от огромного кладбища, кишащего нежитью, которое носит то же название.",al={"raven hill location","where to find raven hill","raven hill map","где вороний холм","как найти вороний холм","карта вороний холм"}},{q="Почему Ночной Дозор так обеспокоен движущимися тенями?",a="Темнолесье с трудом противостоит восстаниям скелетов, диким воргенам и затаившимся паукам. Любой признак организованного движения или странных обитателей в заброшенных западных землях может предвещать скорое нападение на оставшиеся поселения живых.",al={"why care about raven hill","night watch raven hill","почему важен вороний холм","ночной дозор вороний холм"}}},fp="10,297,16.493.0,16.438.1,40.178.0,42.178.0,35.190.1,15.230.1,28.138.0,57.237.0"}
P.entries["quest:1638"] = {n="Обучение воина",s="«Обучение воина» — вводное классовое задание, которое направляет многообещающих молодых воинов из Златоземья в Штормград. По поручению учителя Лирии дю Лак солдаты идут в таверну «Свинья и свисток» в Старом городе, чтобы найти ветерана Гарри Берлгарда и получить опытное наставление в боевой выносливости.",h="«Обучение воина» — вводное классовое задание, которое направляет многообещающих молодых воинов из Златоземья...",kw={"bartleby","goldshire","harry burlguard","lyria du lac","old town","pig and whistle","stormwind","training","warrior","бартлби","златоземье","гарри берлгард","лирия дю лак","старый город","свинья и свисток","штормград","обучение","воин"},ang={["class:Warrior"]="Этот обряд посвящения отмечает ваш переход от новобранца местного ополчения к признанному солдату Альянса и открывает продвинутые стойки и защитные приемы.",["faction:Alliance"]="Бывалые ветераны вроде Гарри Берлгарда следят за тем, чтобы новобранцы, отправляющиеся на спорные границы, владели практической мудростью драки, а не только книжной тактикой.",["race:Human"]="Путь ведет людей-бойцов от сельской обороны Элвиннского леса прямо в Старый город — исконную рабочую колыбель боевых традиций Штормграда."},sec={{t="Из Элвинна в Старый город",b="Когда начинающий боец показывает надежное владение основами и способен справляться с угрозами по всему Элвиннскому лесу, его наставники понимают, что наставники в Златоземье больше ничего не могут ему дать. Лирия дю Лак отправляет новобранцев в самое сердце Штормграда, в суровый квартал Старого города. Там собираются бывалые бойцы, чтобы обменяться боевым опытом вдали от строгих формальностей королевского гарнизона."},{t="Уроки ветерана",b="В Старом городе нужный человек — Гарри Берлгард, пожилой ветеран сражений, обосновавшийся в таверне «Свинья и свисток». Вместо муштры на плацу Гарри проверяет стойкость воина тавернной грубостью и практической выносливостью. Прежде чем обучить защитным приемам, помогающим солдатам выжить в опасных походах, Гарри ждет, что новички сравняются с ним в любви к выпивке и справятся с местными буянами."}},faq={{q="Кто выдает это задание?",a="Задание выдает Лирия дю Лак, учитель воинов, стоящая за кузницей в Златоземье, когда боец доказал свои первые боевые навыки.",al={"quest giver","who starts a warriors training","lyria du lac quest","персонаж, выдающий задание","кто начинает обучение воина","задание лирия дю лак"}},{q="Где можно найти Гарри Берлгарда?",a="Гарри Берлгард находится в таверне «Свинья и свисток», расположенной в квартале Старый город в Штормграде.",al={"where is harry burlguard","harry burlguard location","pig and whistle tavern","где гарри берлгард","гарри берлгард местоположение","таверна свинья и свисток"}},{q="Чему учит Гарри Берлгард?",a="Гарри — старый ветеран, обучающий воинов практическим приемам и стойкам, помогающим дольше оставаться в живых на поле боя; начинает он с нескольких колоритных проверок на выносливость.",al={"what do you learn","warrior quest reward level 10","harry burlguard lesson","чему учат","награда воина 10 уровень","урок гарри берлгарда"}},{q="Почему обучение проходит в таверне, а не в казармах?",a="Старый город — традиционное, более суровое сердце Штормграда, где собираются отставные солдаты и закаленные ветераны. Гарри предпочитает вести занятия за элем и кулачной дисциплиной, а не следовать чопорному военному протоколу.",al={"why pig and whistle","why train in tavern","stormwind barracks","почему свинья и свисток","почему обучение в таверне","казармы штормграда"}},{q="Что будет после разговора с Гарри?",a="Гарри тут же втягивает новобранца в состязание с местным буяном Бартлби Пьянью, проверяя его физическую стойкость до завершения обучения.",al={"what is next quest","after a warriors training","next step","какое следующее задание","после обучения воина","следующий шаг"}},{q="Могут ли получить это задание не воины?",a="Нет. Это задание входит в особую цепочку обучения воинов и предлагается только персонажам класса воина.",al={"is this warrior only","can paladins do this","warrior class quest","только для воинов","могут ли паладины","классовое задание воина"}}},fp="20,312,23.407.0,22.408.0,21.161.0,35.113.0,32.180.0,57.228.0,35.164.1,36.124.0"}
P.entries["quest:1639"] = {n="Бартлби Пьянь",s="«Бартлби Пьянь» — ранний обряд посвящения для воинов Альянса, обучающихся в Штормграде. По указанию Гарри Берлгарда в таверне «Свинья и свисток» начинающему бойцу нужно схлестнуться с упрямым завсегдатаем и забрать его любимую кружку. Это простая проверка стойкости: воин должен уметь постоять в драке, прежде чем перейти к настоящим боевым приемам.",h="«Бартлби Пьянь» — ранний обряд посвящения для воинов Альянса, обучающихся в Штормграде.",kw={"bartleby","drunk","harry burlguard","mug","old town","pig and whistle","stormwind","training","warrior","бартлби","пьянь","гарри берлгард","кружка","старый город","свинья и свисток","штормград","обучение","воин"},ang={["class:Warrior"]="Это столкновение — практическая проверка, которую штормградские учителя требуют пройти, прежде чем обучать вас защитной тактике и владению стойками.",["faction:Alliance"]="Трактирная потасовка показывает грубую, лишенную блеска сторону Старого города Штормграда, далекую от королевского двора Крепости."},sec={{t="Трактирное испытание",b="Прежде чем Гарри Берлгард передаст более глубокие боевые навыки в таверне Старого города, он требует доказательств, что у новичка есть настоящий стержень. Вместо чинного учебного поединка Гарри указывает через зал на Бартлби — задиристого посетителя, потягивающего выпивку в дальнем конце стойки. Задача проста: забрать его кружку. Берлгард прекрасно знает, что Бартлби скорее подерется, чем расстанется с элем, и потому столкновение сразу становится проверкой решимости воина."},{t="Этикет Старого города",b="В «Свинье и свистке» собираются солдаты, работяги и грубоватые местные, и до изящных манер здесь нет дела. Подойдя к Бартлби, вы получите насмешки вместо беседы: пьяница тут же объявляет любого новичка слишком изнеженным для трактирной потасовки. Эта вражда ведет к драке прямо на половицах и показывает, что путь в военных кругах Штормграда часто начинается с обычной трактирной драки."}},faq={{q="Кто такой Бартлби?",a="Бартлби — упрямый заядлый пьяница, слоняющийся у стойки в таверне «Свинья и свисток» в квартале Старый город в Штормграде.",al={"who is bartleby","bartleby npc","bartleby the drunk","кто такой бартлби","бартлби персонаж","бартлби пьянь"}},{q="Почему Гарри Берлгард посылает меня к Бартлби?",a="Гарри Берлгард хочет увидеть, на что вы способны, прежде чем взяться учить вас продвинутым приемам воина. Требование забрать кружку Бартлби гарантирует драку и проверяет, готовы ли вы принять удар и устоять.",al={"why fight bartleby","harry burlguard test","why get the mug","зачем драться с бартлби","проверка гарри берлгарда","зачем забирать кружку"}},{q="Где происходит эта встреча?",a="Встреча происходит в таверне «Свинья и свисток» в Старом городе, в восточной части Штормграда.",al={"where is bartleby","pig and whistle location","где бартлби","местоположение свинья и свисток"}},{q="Что происходит, когда вы заговариваете с Бартлби?",a="Бартлби оскорбляет вас, называя разряженным неженкой и предупреждая, чтобы вы не сломали ноготь в таком грубом заведении, как «Свинья и свисток», — и вскоре вспыхивает драка.",al={"what does bartleby say","bartleby dialogue","что говорит бартлби","диалог бартлби"}},{q="Что будет после разговора с Бартлби?",a="Столкновение с Бартлби сразу перерастает в трактирную драку, в которой вам нужно победить его, забрать кружку и вернуть ее Гарри Берлгарду.",al={"next quest after bartleby","what follows bartleby the drunk","следующее задание после бартлби","что после бартлби пьяни"}},{q="Доступно ли это задание любому классу?",a="Нет, это задание входит в сюжетную линию обучения класса, доступную только воинам Альянса, достигшим 10 уровня.",al={"can anyone do bartleby","warrior only","может ли любой бартлби","только воин"}}},fp="18,363,18.491.0,18.433.0,16.142.0,45.216.0,37.114.0,40.167.0,37.143.0,37.104.0"}
P.entries["quest:164"] = {n="Припасы для Свена",s="«Припасы для Свена» — задание Альянса, которое дает Илана Карвин в Темнолесье: нужно доставить жизненно важные припасы в одинокий лагерь на северо-западной границе Сумеречного леса. Там Свен Йорген и его немногочисленные последователи ведут отчаянную одинокую борьбу с ужасами оскверненных лесов. Поручение связывает горожан, живущих во мраке, с изолированным отрядом на краю дикой местности.",h="«Припасы для Свена» — задание Альянса, которое дает Илана Карвин в Темнолесье: нужно доставить жизненно...",kw={"carevin","darkshire","duskwood","elaine carevin","light","supplies for sven","sven yorgen","карвин","темнолесье","сумеречный лес","илана карвин","свет","припасы для свена","свен йорген"},ang={["class:Paladin"]="Илана говорит о Свене как о человеке, творящем истинное дело Света, и потому эта доставка припасов становится актом солидарности с братом, осажденным врагами.",["faction:Alliance"]="Дальние стражи вроде Свена олицетворяют истощенное влияние Альянса в Сумеречном лесу, где выживание зависит от добровольных посыльных, а не от регулярных гарнизонных линий снабжения.",["race:Human"]="Карвины и последователи Свена показывают упрямую стойкость сельских жителей Штормграда, не желающих покидать Сумеречный лес, несмотря на его неослабевающий мрак."},sec={{t="Спасательная нить в глуши",b="Пока Темнолесье едва удерживает свои стены от волков, пауков и неупокоенных мертвецов, некоторые отказываются прятаться за частоколом. Свен Йорген и горстка соратников устроили одинокий лагерь на северо-западной окраине Сумеречного леса. Опасность так постоянна, что они не могут отпустить ни одного человека в опасный путь до города за припасами. Илана Карвин берется организовать помощь, полагаясь на отважных путников, чтобы эти бойцы границы не умерли с голоду."},{t="Связь с Карвинами",b="Семья Карвин глубоко уважает Свена, видя в его стойкости истинную преданность Свету. Готовность Иланы собирать и отправлять припасы показывает тихие сети выживания, не дающие Сумеречному лесу целиком погрузиться во тьму. Получив ящик, Свен понимает, что Карвины по-прежнему его поддерживают, хотя мысли его остаются поглощены мрачной битвой."}},faq={{q="Кто такой Свен Йорген?",a="Свен Йорген — житель границы, содержащий вооруженный лагерь на северо-западной окраине Сумеречного леса. Такие люди, как Илана Карвин, видят в нем честного бойца, творящего дело Света; Свен и его малый отряд борются с множеством ужасов, терзающих окрестные леса.",al={"who is sven","sven lore","sven yorgen info","кто такой свен","свен предания","свен йорген информация"}},{q="Почему Свену нужно доставлять припасы?",a="Отряд Свена критически мал и постоянно настороже перед окружающими угрозами. Они не могут отпустить даже одного человека в опасный путь до Темнолесья и обратно, поэтому полностью зависят от сочувствующих горожан и случайных посыльных.",al={"why can't sven get supplies","sven supplies","why delivery","почему свен не может достать припасы","припасы свена","зачем доставка"}},{q="Кто предоставляет припасы?",a="Припасы предоставляет Илана Карвин из Темнолесья. Ее семья близка со Свеном, высоко ценит его преданность и регулярно организует помощь его лагерю.",al={"who sends supplies","elaine carevin","carevin family","кто присылает припасы","илана карвин","семья карвин"}},{q="Где находится лагерь Свена?",a="Лагерь Свена прячется у северо-западных гор Сумеречного леса, далеко за дорогой и к северу от оскверненных полей, прямо в пограничной глуши.",al={"where is sven","sven location","sven camp","где свен","местоположение свена","лагерь свена"}},{q="Обязательна ли эта доставка, чтобы помогать Свену дальше?",a="Нет. Хотя Илана Карвин предлагает это задание, чтобы направить путников к Свену, предприимчивые путники, самостоятельно нашедшие лагерь Свена, могут помочь ему напрямую, не неся ящик Иланы.",al={"is deliveries to sven required","do i need deliveries to sven","deliveries prerequisite","обязательно ли припасы для свена","нужно ли припасы для свена","условие доставки"}},{q="Что делает Свен после получения припасов?",a="Свен выражает искреннюю благодарность за поддержку семьи Карвин, но его мысли тут же возвращаются к страшным угрозам его лагерю и истории его семьи; он ищет способных бойцов, которые помогут ему отомстить.",al={"what happens next","after deliveries to sven","sven next quest","что дальше","после припасов для свена","следующее задание свена"}}},fp="18,417,28.505.0,22.404.0,19.277.0,43.268.0,26.196.0,29.173.0,55.189.0,47.207.0"}
P.entries["quest:1640"] = {n="Побить Бартлби",s="«Побить Бартлби» — простое испытание боевой доблести для будущих воинов Альянса в Штормграде. Чтобы выполнить посвятительное задание, новобранец должен подраться с упрямым городским пьяницей, который не желает отдавать свою драгоценную кружку без боя. Доказав свою силу, воин заслуживает его неохотное уважение и сосуд, необходимый учителям воинов.",h="«Побить Бартлби» — простое испытание боевой доблести для будущих воинов Альянса в Штормграде.",kw={"bartleby","brawl","drunk","mug","stormwind","training","trial","warrior","бартлби","драка","пьяница","кружка","штормград","обучение","испытание","воин"},ang={["class:Warrior"]="Эта трактирная драка — классическое раннее испытание для воинов Альянса. Она преподает суровый урок: сила воли и тяжелый кулак нередко решают споры там, где дипломатия бессильна.",["faction:Alliance"]="Эта стычка на столичных улицах Штормграда дает яркое представление о грубой изнанке города наряду с его величественными каменными стенами."},sec={{t="Вызов задиры",b="Наставники воинов в Штормграде не принимают отговорок и не учат своих учеников, что бой всегда благороден и величав. В рамках официального обучения молодым воинам поручают забрать определенную кружку у Бартлби, известного пьяницы, который отдыхает в городе. На вежливые просьбы Бартлби только фыркает и клянется, что его драгоценную посуду можно забрать лишь из его холодных мертвых пальцев. Для начинающего воина слова быстро сменяются кулачной дракой."},{t="Пьяный урок",b="Хотя Бартлби громко заявляет, что будет драться насмерть, отрезвить его можно лишь хорошей взбучкой. Побежденный, он теряет всю браваду, и она сменяется восхищением, приправленным синяками. Поняв, что противник намного сильнее, чем кажется, он мирно уступает, позволяя победителю наконец забрать кружку и завершить испытание для тренировочного зала."}},faq={{q="Кто такой Бартлби?",a="Бартлби — драчливый пьяница, часто бывающий в Штормграде. Он известен тем, что сжимает любимую кружку, и невольно становится препятствием и спарринг-партнером для начинающих воинов, которых отправляют проверить свою физическую стойкость.",al={"bartleby","who is bartleby","bartleby npc","бартлби","кто такой бартлби","бартлби нпс"}},{q="Почему я должен драться с Бартлби?",a="Учителя воинов Альянса посылают новобранцев забрать определенную кружку, которая есть у Бартлби. Поскольку он упрямо отказывается отдавать ее без драки, новобранец должен победить его в рукопашной схватке, чтобы ослабить его хватку.",al={"why fight bartleby","beat bartleby reason","why beat him","зачем драться с бартлби","побить бартлби причина","почему побить его"}},{q="Нужно ли в этом задании действительно убить Бартлби?",a="Нет. Несмотря на его хвастовство, что кружку можно забрать лишь из его холодных мертвых пальцев, Бартлби сдается, когда его здоровье истощено, и охотно признает, что вы намного сильнее, чем он думал.",al={"does bartleby die","kill bartleby","is bartleby dead","умирает ли бартлби","убить бартлби","бартлби мертв"}},{q="Где происходит это задание?",a="Схватка происходит в городе Штормград, где можно найти Бартлби, пьющего и слоняющегося без дела.",al={"beat bartleby location","where is bartleby","bartleby spot","побить бартлби где","где бартлби","местонахождение бартлби"}},{q="Что происходит после победы над ним?",a="Побежденный Бартлби уступает и дружелюбно говорит с вами. После этого вы можете забрать его кружку и вернуть учителям воинов, чтобы завершить посвящение.",al={"after beat bartleby","what next bartleby","после побить бартлби","что дальше бартлби"}},{q="Какому уровню обучения соответствует это испытание?",a="Эта драка — ранняя веха для начинающих воинов примерно на десятом уровне опыта, практическая проверка базовой выносливости в ближнем бою.",al={"bartleby quest level","when do i fight bartleby","уровень задания бартлби","когда драться с бартлби"}}},fp="13,374,21.537.0,16.389.0,16.222.0,32.223.0,42.188.0,33.111.0,32.163.0,49.158.0"}
P.entries["quest:1641"] = {n="Фолиант Божественности",s="«Фолиант Божественности» — важный обряд посвящения для молодых паладинов Королевства Штормград. Под руководством Даториана Ралла в Соборе Света посвящаемых проверяют на понимание добродетели, преданности и серьезной ответственности, связанной с владением Светом.",h="«Фолиант Божественности» — важный обряд посвящения для молодых паладинов Королевства Штормград.",kw={"book of divinity","brother wilhelm","cathedral of light","duthorian rall","holy light","paladin","stormwind","tome of divinity","virtue","книга божественности","брат вильгельм","собор света","даториан ралл","свет","паладин","штормград","фолиант божественности","добродетель"},ang={["class:Paladin"]="Этот обряд знаменует переход от простого ученика воинского дела к истинному служителю Света и закладывает основные принципы жертвенности и милосердия, определяющие орден.",["faction:Alliance"]="Подготовка стойких паладинов укрепляет сердце Штормграда: праведные защитники готовы оградить Альянс от поднимающейся тьмы.",["race:Human"]="Для людей Штормграда эта церемония чтит наследие павших рыцарей Лордерона и продолжает гордую традицию Серебряной Длани в южном королевстве."},sec={{t="Призвание паладина",b="В тихих мраморных залах Собора Света Даториан Ралл руководит обучением тех, кто принимает на себя звание паладина. Ранняя подготовка посвящена воинской дисциплине и воинским обрядам, но дальнейшее продвижение в ордене требует более глубокой духовной преданности. Испытания, связанные с Фолиантом Божественности, заставляют посвящаемых смотреть за пределы битвы и понимать вес нравственного долга в королевстве, осажденном внутренними и внешними опасностями."},{t="Путь добродетели",b="Получить Книгу Божественности — значит заключить договор служения и самопожертвования. Даториан поручает будущим защитникам изучить священный текст, чтобы понять, чего Свет требует от своих защитников. Заключенные в нем уроки готовят паладинов противостоять подступающим ужасам Плети и защищать простой люд, доказывая, что праведная сила всегда должна направляться подлинной добродетелью и состраданием."}},faq={{q="Для чего нужен Фолиант Божественности?",a="Фолиант Божественности — основополагающий священный текст и испытание для развивающихся паладинов. Он проверяет понимание посвящаемым священных принципов до того, как ему доверят большие божественные умения, и гарантирует, что его сила основана на преданности и добродетели, а не на одной лишь воинской мощи.",al={"why tome of divinity","what is tome of divinity","paladin book quest","зачем фолиант божественности","что такое фолиант божественности","задание паладина с книгой"}},{q="Кто такой Даториан Ралл?",a="Даториан Ралл — высокопоставленный учитель паладинов в Соборе Света в Штормграде. Он отвечает за наставление новоиспеченных паладинов, вручает им Книгу Божественности и направляет их испытания по всему королевству.",al={"duthorian rall","paladin trainer stormwind","who is duthorian","даториан ралл","учитель паладинов штормград","кто такой даториан"}},{q="Где проходит это испытание?",a="Задание начинается на Соборной площади Штормграда, в величественном Соборе Света. Посвящаемые являются прямо к Даториану Раллу, выполнив предварительные поручения в дальних поселениях, например в Златоземье.",al={"where is duthorian","cathedral of light quest","where start tome of divinity","где даториан","задание собор света","где начать фолиант божественности"}},{q="Почему в учении Штормграда упоминается Плеть?",a="Хотя Плеть опустошила Лордерон на севере, нежить остается смертельной угрозой для всех живых смертных. Паладинов Штормграда с самого начала учат распознавать нечестивую скверну Плети и бороться с ней, где бы она ни появилась в Азероте.",al={"scourge threat stormwind","why scourge here","paladins vs scourge","угроза плети штормград","почему плеть здесь","паладины против плети"}},{q="Что происходит после прочтения Книги Божественности?",a="Изучение текста — лишь первый шаг. Даториан Ралл проверяет, действительно ли посвящаемый усвоил его уроки, отправляя его на помощь тем, кто отчаянно нуждается, чтобы он доказал свое сострадание и стойкость делами, а не словами.",al={"next step tome of divinity","after reading book","what does duthorian want next","следующий шаг фолиант божественности","после прочтения книги","что дальше хочет даториан"}},{q="Кто обычно направляет кандидатов к Даториану Раллу?",a="Местные наставники и священнослужители в отдаленных поселениях Элвиннского леса, например Брат Вильгельм в Златоземье, понимают, когда посвящаемый готов к официальным испытаниям, и направляют его прямо к Даториану в столицу.",al={"who sent me to duthorian","previous quest tome of divinity","brother wilhelm","кто послал меня к даториану","предыдущее задание фолиант божественности","брат вильгельм"}}},fp="20,289,19.466.0,18.414.0,44.293.0,22.241.0,33.215.0,54.271.0,46.236.0,50.223.0"}
P.entries["quest:1645"] = {n="Фолиант Божественности",s="«Фолиант Божественности» — важная веха в обучении паладина-дворфа в Стальгорне. Этот священный текст вручает Тиза Боевой Горн в Зале Тайн, и с него начинается путь испытаний, проверяющих преданность посвящаемого Свету и его готовность защищать Азерот от темных сил, например Плети.",h="«Фолиант Божественности» — важная веха в обучении паладина-дворфа в Стальгорне.",kw={"book of divinity","hall of mysteries","holy light","ironforge","paladin","redemption","scourge","tiza battleforge","tome of divinity","книга божественности","зал тайн","свет","стальгорн","паладин","искупление","плеть","тиза боевой горн","фолиант божественности"},ang={["class:Paladin"]="Этот обряд соединяет раннее воинское обучение с более глубокими добродетелями Света и выводит посвящаемых на путь, ведущий к силе искупления и воскрешения.",["race:Dwarf"]="Для защитников-дворфов принятие Фолианта Божественности укрепляет союз веры, заключенный между королевством Бронзобородов и рыцарями-людьми Серебряной Длани."},sec={{t="Призвание к добродетели",b="Наставники паладинов в восточных королевствах направляют многообещающих посвящаемых в Зал Тайн Стальгорна, когда те овладевают основами воинского и духовного дела. Под бдительным взором Тизы Боевого Горна молодые паладины-дворфы знакомятся с суровыми принципами, отличающими простого воина от рукоположенного защитника Света. Принять это задание — значит осознанно дать обет пожизненного самопожертвования, долга и духовной дисциплины."},{t="Книга Божественности",b="Принимая это поручение, новичок получает Книгу Божественности. Этот текст излагает требования, добродетели и духовные принципы, необходимые, чтобы действенно направлять священные силы против злых угроз. Изучение ее учений — лишь первый шаг: писание служит основой, прежде чем посвящаемого отправят по Каз Модану и дальше воплощать его уроки в настоящих актах веры."}},faq={{q="Для чего нужно задание «Фолиант Божественности»?",a="Это задание — дверь к продвинутому обучению паладинов для защитников-дворфов. Поговорив с Тизой Боевым Горном, посвящаемые получают священный текст и приступают к ряду испытаний, которые должны доказать их добродетель и открыть способность возвращать павших союзников из мертвых.",al={"what does tome of divinity do","tome of divinity purpose","why do this quest","что дает фолиант божественности","цель фолианта божественности","зачем выполнять задание"}},{q="Кто такая Тиза Боевой Горн?",a="Тиза Боевой Горн — известная учительница паладинов, живущая в Зале Тайн в Стальгорне. Ей поручено направлять паладинов-дворфов к большей добродетели, проверять их преданность Свету и готовить их к столкновению с такими угрозами, как Плеть.",al={"tiza battleforge","who is the paladin trainer in ironforge","who gives tome of divinity","тиза боевой горн","кто учитель паладинов в стальгорне","кто выдает фолиант божественности"}},{q="Почему посвящаемые должны изучать Книгу Божественности?",a="Книга Божественности содержит основные учения об обязанностях и добродетелях, которых требует Свет. Ее изучение гарантирует, что посвящаемый понимает духовную дисциплину, необходимую до того, как он овладеет чудесными священными силами.",al={"what is the book of divinity","why read the book","book of divinity lore","что такое книга божественности","зачем читать книгу","предания книги божественности"}},{q="С какими главными угрозами готовятся бороться паладины-дворфы?",a="Как говорит Тиза Боевой Горн, паладины посвящают себя защите Азерота от опасностей по всей земле, особенно внимательно следя за надвигающейся угрозой нежити из Плети.",al={"who do paladins fight","why train paladins ironforge","paladin purpose","с кем борются паладины","зачем обучать паладинов в стальгорне","цель паладинов"}},{q="Где проходит это обучение?",a="Посвящение начинается в Зале Тайн — тихом убежище в северных кварталах Стальгорна, где собираются для молитвы и учебы ученые, жрецы, маги и паладины.",al={"where is tiza battleforge","ironforge paladin location","hall of mysteries paladin","где тиза боевой горн","паладин стальгорн местонахождение","зал тайн паладин"}},{q="Что происходит после получения книги?",a="Когда посвящаемый прочтет и обдумает Книгу Божественности, Тиза Боевой Горн дает практические испытания, в которых паладин должен проявить сострадание, долг и самопожертвование за безопасными воротами города.",al={"what happens next","next quest tome of divinity","where do i go after getting the book","что дальше","следующее задание фолиант божественности","куда идти после получения книги"}}},fp="20,325,19.469.0,20.423.0,50.272.0,24.259.0,46.230.0,59.213.0,36.186.0,41.215.0"}
P.entries["quest:1649"] = {n="Фолиант Отваги",s="Фолиант Отваги — священное переходное испытание для растущих паладинов в Соборе Света. Под руководством священных текстов и опытных наставников соискатели отыскивают в Штормграде Даториана Ралла, чтобы доказать свою непоколебимую веру, отвагу и преданность добродетелям Церкви.",h="Фолиант Отваги — священное переходное испытание для растущих паладинов в Соборе Света.",kw={"cathedral of light","church of the holy light","duthorian rall","faith","paladin","stormwind","tome of valor","valor","собор света","церковь священного света","даториан ралл","вера","паладин","штормград","фолиант отваги","отвага"},ang={["class:Paladin"]="Это испытание — важный шаг в росте паладина: оно доказывает, что праведную воинскую доблесть должны подкреплять дисциплинированная вера и бескорыстное служение.",["faction:Alliance"]="Испытания, проводимые в Штормграде, помогают сохранить основу оборонительной и духовной силы Альянса в неспокойные времена."},sec={{t="Закалка духа",b="В традициях Света доблесть не считается врожденным качеством, которое остается чистым само по себе. Священный текст Фолианта сравнивает добродетели с драгоценными необработанными рудами: они ценны сразу, но требуют тщательной плавки и очистки, чтобы выдержать трудности. Лишь через тяжкие испытания и истинную преданность паладин может сплавить веру, сострадание и отвагу в сплав, способный противостоять самому темному злу, угрожающему Азероту."},{t="Обращение к Церкви",b="Усвоив мудрость Фолианта Отваги, паладин направляется к Даториану Раллу, уважаемому предводителю паладинов, собравшихся в Соборе Света Штормграда. Даториан выступает судьей для тех, кто просит допустить их к испытаниям доблести. Он предупреждает соискателей: предстоящие проверки — не пустой обряд. Защита невинных и служение Церкви требуют готовности пожертвовать жизнью, и лишь по-настоящему стойкие получают признание в ордене."}},faq={{q="Для чего нужно это задание?",a="Это задание связывает начальное изучение священного учения с настоящими опасными испытаниями. Изучив Фолиант Отваги, будущие паладины являются к Даториану Раллу в Соборе Света и просят назначить им настоящие проверки веры и отваги.",al={"what is the tome of valor quest","why do i need this quest","tome of valor purpose","что за задание фолиант отваги","зачем нужно это задание","для чего фолиант отваги"}},{q="Кто такой Даториан Ралл?",a="Даториан Ралл — паладин высокого ранга и наставник, служащий в Соборе Света в Штормграде. Он следит за развитием многообещающих защитников и проводит суровые испытания, которые должны подтвердить перед Церковью достоинство новичка.",al={"who is duthorian rall","duthorian rall lore","cathedral paladin trainer","кто такой даториан ралл","даториан ралл предания","наставник паладинов в соборе"}},{q="Почему Церковь так сурово испытывает своих паладинов?",a="Церковь Священного Света ждет от паладинов, что они станут несокрушимым оплотом против отчаяния и насилия. Слабая решимость или хрупкая вера могут стоить жизней на поле боя, поэтому наставники закаляют и проверяют дух новичка, прежде чем отправить его на важные священные задания.",al={"why are paladin trials dangerous","why test valor","почему испытания паладинов опасны","зачем испытывать отвагу"}},{q="Где проходит это испытание?",a="Новичок передает свое прошение прямо Даториану Раллу в Соборе Света, который стоит на видном месте в центре Соборной площади Штормграда.",al={"where to turn in tome of valor","duthorian rall location","где сдать фолиант отваги","где даториан ралл"}}},fp="17,283,20.449.0,22.486.0,34.272.0,22.254.0,50.292.0,33.171.0"}
P.entries["quest:165"] = {n="Отшельник",s="Обеспокоенная долгим отсутствием пожилого затворника, Илана Карвин из Темнолесья просит путников проведать его. Одинокий старик Аберкромби живет в ветхой лачуге на самом краю Кладбища Вороньего Холма.",h="Обеспокоенная долгим отсутствием пожилого затворника, Илана Карвин из Темнолесья просит путников проведать...",kw={"abercrombie","darkshire","duskwood","elaine carevin","raven hill cemetery","shack","the hermit","аберкромби","темнолесье","сумеречный лес","илана карвин","кладбище вороньего холма","лачуга","отшельник"},ang={["faction:Alliance"]="Ночной Дозор с трудом защищает дороги между Темнолесьем и Вороньим Холмом, и отдаленные затворники вроде Аберкромби остаются полностью отрезанными от безопасности города.",["race:Human"]="Семья Карвинов воплощает прочные соседские узы Сумеречного леса: люди присматривают за чудаковатыми старейшинами общины, даже когда их край погружается во тьму."},sec={{t="Проведать соседа",b="В осажденном поселении вроде Темнолесья легко потерять из виду чудаковатых одиночек, пока их отсутствие не начинает тревожить. Илана Карвин вспоминает старика, который раньше регулярно приходил в город за припасами, а потом внезапно исчез. Учитывая неослабевающие опасности на дорогах Сумеречного леса, она посылает странствующих искателей приключений осмотреть его лачугу над мрачными просторами Кладбища Вороньего Холма, чтобы убедиться, что его не постигла печальная участь."},{t="Затворник с Вороньего Холма",b="Добравшись до одинокой хижины, путник узнает, что ее обитатель, старик по имени Аберкромби, еще жив. Он тихо посмеивается при упоминании Карвинов и говорит, что долго не появлялся лишь из-за преклонных лет и коварных чудовищ, рыскающих по лесу. Обрадованный тем, что на пороге оказался крепкий путник, Аберкромби тут же спрашивает, не окажет ли тот ему несколько полезных услуг."}},faq={{q="Кто дает это поручение?",a="Илана Карвин, жительница Темнолесья в Сумеречном лесу, дает это задание из беспокойства о старом отшельнике, который раньше покупал припасы в городе.",al={"who gives the hermit","where to start the hermit","elaine carevin quest","кто дает задание отшельник","где начать отшельника","задание илана карвин"}},{q="Где находится отшельник?",a="Аберкромби живет в полуразрушенной деревянной лачуге на северной окраине Кладбища Вороньего Холма на западе Сумеречного леса.",al={"where is abercrombie","hermit location duskwood","shack near raven hill","где аберкромби","отшельник сумеречный лес","лачуга у вороньего холма"}},{q="Почему Илана Карвин беспокоилась о нем?",a="Аберкромби регулярно приходил в Темнолесье за припасами, но вдруг перестал появляться. Поскольку на дорогах бродят дикие звери и нежить, она боялась, что он погиб.",al={"why check on abercrombie","why is elaine worried","what happened to the old man","зачем проведать аберкромби","почему илана беспокоится","что случилось со стариком"}},{q="Грозит ли Аберкромби опасность, когда вы его находите?",a="Нет. Когда вы приходите к его лачуге, Аберкромби жив, здоров и тихо забавляется беспокойством горожан. Он объясняет, что из-за опасных дорог и преклонного возраста путешествия стали для него слишком обременительны.",al={"is abercrombie ok","is the hermit dying","did the hermit get attacked","аберкромби в порядке","отшельник умирает","на отшельника напали"}},{q="Почему кто-то решает поселиться прямо рядом с Кладбищем Вороньего Холма?",a="Аберкромби говорит, что предпочитает уединение, хотя жизнь в тени одного из самых оскверненных некромантией кладбищ Восточных королевств кажется многим путникам жутковатой.",al={"why live by raven hill","abercrombie cemetery shack","why is the hermit near graves","почему жить у вороньего холма","аберкромби лачуга на кладбище","почему отшельник у могил"}},{q="О чем просит Аберкромби, когда вы до него доберетесь?",a="Аберкромби спешит воспользоваться тем, что у его порога оказался крепкий искатель приключений, и сразу просит помочь с разными поручениями и делами в лесу.",al={"what does abercrombie want","hermit followup quest","what comes after the hermit","что хочет аберкромби","продолжение задания отшельника","что после отшельника"}}},fp="10,225,21.461.0,25.419.0,23.140.0,28.125.0,41.179.0,52.190.0,66.189.0,49.174.0"}
P.entries["quest:1650"] = {n="Фолиант Отваги",s="Это задание — второе испытание на пути паладина к Фолианту Отваги. Даториан Ралл посылает рыцарей на дальние берега Западного Края защитить Дафну Стилвелл, уединенную поселянку, которой угрожают окрестные бандиты из Братства Справедливости.",h="Это задание — второе испытание на пути паладина к Фолианту Отваги.",kw={"daphne stilwell","defias brotherhood","duthorian rall","jordan stilwell","longshore","stormwind","tome of valor","westfall","дафна стилвелл","братство справедливости","даториан ралл","джордан стилвелл","бескрайний берег","штормград","фолиант отваги","западный край"},ang={["class:Paladin"]="Эта задача — основа обряда посвящения для молодых паладинов: им нужно покинуть безопасный Собор Штормграда и доказать свою доблесть, защищая беззащитных.",["faction:Alliance"]="Беда усадьбы Стилвеллов показывает, как далеко Западный Край оказался от прямой защиты Штормграда: сельским жителям приходится в одиночку отбиваться от Братства Справедливости."},sec={{t="Призыв к оружию",b="В Соборе Света Даториан Ралл проверяет будущих паладинов не только по писанию или одинокой молитве, но и через непосредственную защиту жителей королевства. Приняв бремя доблести, паладины сразу получают задачу воплотить свои идеалы там, где рухнули власть и закон."},{t="Опасность на Бескрайнем берегу",b="Цель — отдаленный Бескрайний берег Западного Края, где Дафна Стилвелл и ее муж Джордан держат форпост у океана. Джордан уехал в Стальгорн советоваться с кузнецами-дворфами, и Дафна осталась одна среди разгула Братства Справедливости. Даториан приказывает паладину ехать на запад и стать ее щитом, пока воры не захватили ее уединенный участок."}},faq={{q="Почему Дафна Стилвелл одна в Западном Крае?",a="Ее муж, Джордан Стилвелл, — известный кузнец, отправившийся в королевство дворфов Стальгорн посоветоваться с другими кузнецами. Из-за его отсутствия Дафне пришлось в одиночку защищать прибрежный участок от усиливающихся нападений Братства Справедливости.",al={"where is daphnes husband","why is jordan stilwell gone","daphne stilwell alone","где муж дафны","почему джордана стилвелла нет","дафна стилвелл одна"}},{q="Кто поручает паладину это задание?",a="Даториан Ралл, ведущий наставник паладинов в Соборе Света Штормграда, отдает приказ, когда вы доказываете готовность пройти испытания доблести.",al={"who gives tome of valor 1650","quest giver tome of valor","duthorian rall quest","кто дает фолиант отваги 1650","персонаж фолиант отваги","задание даториана ралла"}},{q="Где можно найти Дафну Стилвелл?",a="Она живет в небольшом доме на дальнем юге Бескрайнего берега, на побережье юго-запада Западного Края.",al={"where is daphne stilwell","daphne stilwell location","find daphne stilwell","где дафна стилвелл","местонахождение дафны стилвелл","найти дафну стилвелл"}},{q="Совсем ли беспомощна Дафна, когда вы приходите?",a="Ничуть. К тому времени, как паладин добирается до ее крыльца, Дафна уже лично расправилась из своего оружия с полудюжиной бандитов Братства Справедливости, удерживая участок.",al={"can daphne fight","is daphne defenseless","daphne stilwell fighting","умеет ли дафна драться","беззащитна ли дафна","дафна стилвелл сражается"}},{q="Какая угроза нависла над домом Стилвеллов?",a="Братство Справедливости захватило большую часть Западного Края и постоянно донимает уединенный прибрежный участок, пытаясь завладеть землей и разграбить остатки имущества.",al={"who is attacking daphne","defias in westfall","enemies at stilwell farm","кто нападает на дафну","братство справедливости в западном крае","враги на ферме стилвеллов"}},{q="Как это задание вписывается в цепочку Фолианта Отваги?",a="В традиции паладинов доблесть измеряется деятельной жертвенностью и защитой беззащитных. Встав между Дафной и грабителями-бандитами, паладин на деле показывает праведность в действии.",al={"why do i have to help daphne","tome of valor trial purpose","meaning of this quest","почему я должен помогать дафне","цель испытания фолианта отваги","смысл этого задания"}}},fp="17,250,14.325.0,22.397.0,41.231.0,37.165.0,35.130.0,46.185.0,42.163.0,52.210.0"}
P.entries["quest:1651"] = {n="Фолиант Отваги",s="Это ключевое испытание для развивающихся паладинов требует защитить усадьбу Дафны Стилвелл от согласованного налета Братства Справедливости. Оказавшись в меньшинстве на открытых полях Западного Края, паладин должен удержать рубеж и воплотить главный принцип доблести.",h="Это ключевое испытание для развивающихся паладинов требует защитить усадьбу Дафны Стилвелл от согласованного...",kw={"daphne stilwell","defias brotherhood","defias raiders","paladin trial","tome of valor","westfall","дафна стилвелл","братство справедливости","налетчики братства справедливости","испытание паладина","фолиант отваги","западный край"},ang={["class:Paladin"]="Это сражение проверяет вашу роль несгибаемого защитника. Удержание рубежа рядом с Дафной показывает главную добродетель доблести: священные воины существуют прежде всего для защиты невинных от зла.",["faction:Alliance"]="Гарнизон Штормграда растянут и не может защитить сельские усадьбы, поэтому защита верных граждан Западного Края целиком ложится на плечи отдельных героев."},sec={{t="Стойкость в пыли",b="Следуя добродетелям, записанным в Фолианте Отваги, паладин направляется в осажденную усадьбу Дафны Стилвелл в Западном Крае. Ферма расположена на территории, за которую борется Братство Справедливости: его люди не раз пытались захватить участок и убить Дафну. Зная, что после прошлых стычек ответный удар неизбежен, защитник должен твердо встать у ее дома, а не отступать на безопасную землю."},{t="Испытание доблести",b="Вооруженные лишь ее личным огнестрельным оружием и тем, что может даровать Свет, Дафна и паладин встречают волну за волной налетчиков Братства Справедливости. В отличие от одиночного боя, это испытание проверяет способность стража защищать слабых под сокрушительным натиском. Выдержав натиск, паладин доказывает, что истинная доблесть — не просто погоня за личной славой, а готовность встать между невинными мирными жителями и безжалостным насилием."}},faq={{q="Кто такая Дафна Стилвелл?",a="Дафна Стилвелл — стойкая поселянка-человек, живущая на равнинах Западного Края. Несмотря на регулярные набеги Братства Справедливости, она отказывается покидать свою землю и активно отбивается от бандитских налетов.",al={"daphne stilwell","who is daphne","stilwell westfall","дафна стилвелл","кто такая дафна","стилвеллы западный край"}},{q="Почему Братство Справедливости нападает именно на эту ферму?",a="Братство Справедливости в основном захватило сельскую местность Западного Края, изгоняя или подчиняя местных фермеров. Муж Дафны Джордан уехал в Стальгорн, и она осталась одна и без защиты, а Братство хочет завладеть ее землей.",al={"why defias attack","defias raid daphne","why attack stilwell","почему нападает братство справедливости","налет на дафну","почему нападают на стилвеллов"}},{q="Что такое Фолиант Отваги?",a="Фолиант Отваги — священный наставительный текст, которым Церковь Священного Света наставляет молодых паладинов. Рыцари-ученики проходят телесные и духовные испытания по всему королевству, чтобы воплотить добродетели, описанные на его страницах.",al={"what is tome of valor","tome of valor quest","paladin valor tome","что такое фолиант отваги","задание фолиант отваги","фолиант отваги паладин"}},{q="Что будет, если Дафна падет в бою?",a="Если Дафна Стилвелл падет в бою, испытание будет провалено. Главная проверка доблести требует уберечь ее жизнь наравне со своей от нападения бандитов.",al={"can daphne die","daphne stilwell dies","может ли дафна погибнуть","дафна стилвелл погибает"}},{q="Где происходит это нападение?",a="Столкновение происходит у дома Дафны Стилвелл — небольшой фермы в Холмах Разбойничьих Кинжалов, с которых открывается вид на Бескрайний берег на юге Западного Края.",al={"daphne stilwell location","where is the farm","местонахождение дафны стилвелл","где ферма"}},{q="Что будет после защиты фермы?",a="Когда вы докажете свою отвагу и отгоните налетчиков Братства Справедливости, Дафна оценит вашу преданность и направит вас к следующему этапу испытаний паладина.",al={"next quest tome of valor","after defending daphne","следующее задание фолиант отваги","после защиты дафны"}}},fp="17,246,19.450.0,18.431.0,23.219.0,48.232.0,26.239.0,47.163.0,34.143.0,36.157.0"}
P.entries["quest:1652"] = {n="Фолиант Отваги",s="Это задание завершает испытания доблести, которые устраивает Церковь Священного Света в Штормграде. Защитив уединенную ферму Стилвеллов от бандитов в Западном Крае, начинающий паладин возвращается к Даториану Раллу, чтобы сообщить о безопасности Дафны. Задание закрепляет священный долг паладина — быть самоотверженным щитом для невинных.",h="Это задание завершает испытания доблести, которые устраивает Церковь Священного Света в Штормграде.",kw={"cathedral of light","daphne stilwell","duthorian rall","ironforge","jordan stilwell","stormwind","tome of valor","westfall","собор света","дафна стилвелл","даториан ралл","стальгорн","джордан стилвелл","штормград","фолиант отваги","западный край"},ang={["class:Paladin"]="Доклад Даториану Раллу завершает ваш урок доблести и доказывает, что вам присуща самоотверженность, необходимая священному защитнику Альянса.",["faction:Alliance"]="Беда семьи Стилвелл напрямую связывает фермерские земли людей в Западном Крае с мастерскими дворфов в Стальгорне и показывает практическую взаимозависимость в Альянсе."},sec={{t="Священный щит",b="Путь паладина определяется не только боевым мастерством, но и готовностью встать между опасностью и беззащитными. Когда Дафна Стилвелл оказалась в осаде на своей ферме в Западном Крае, Церковь Священного Света направила туда новобранца, чтобы удержать оборону. Вернувшись в Собор Света в Штормграде, новобранец сообщает, что ферма устояла, и доказывает, что его храбрость соответствует его убеждениям."},{t="Связи между королевствами",b="Муж Дафны, Джордан Стилвелл, находится в Стальгорне и помогает Альянсу своим известным мастерством. Теперь, когда ферма под защитой и Дафне ничто не угрожает, Даториан Ралл готовит весть для отправки на север, в горный город дворфов. Уверенность Джордана в безопасности семьи позволяет мастеру сосредоточиться на работе и показывает, как взаимопомощь и преданность паладинов объединяют Альянс на огромных расстояниях."}},faq={{q="Кто такой Даториан Ралл?",a="Даториан Ралл — старший наставник паладинов в Соборе Света в Штормграде. Он руководит духовными и боевыми испытаниями молодых паладинов, направляя их через уроки, записанные в священных текстах, чтобы они воплощали добродетели отваги, праведности и смирения.",al={"duthorian rall","who is duthorian","paladin trainer stormwind","даториан ралл","кто такой даториан","наставник паладинов штормград"}},{q="Почему Дафне Стилвелл грозила опасность?",a="Дафна Стилвелл живет на уединенной ферме в Западном Крае. Из-за бандитов Братства Справедливости и беззакония вокруг ферма стала легкой мишенью, пока ее муж Джордан работал в Стальгорне.",al={"daphne stilwell","stilwell farm","who attacked daphne","дафна стилвелл","ферма стилвеллов","кто напал на дафну"}},{q="Кто такой Джордан Стилвелл?",a="Джордан Стилвелл — искусный кузнец и мастер, преданный Церкви Священного Света и Альянсу. Сейчас он работает в Стальгорне, делясь своим опытом ради общего дела, и рассчитывает, что Церковь защитит его жену дома.",al={"jordan stilwell","daphne husband","jordan ironforge","джордан стилвелл","муж дафны","джордан стальгорн"}},{q="Что такое Фолиант Отваги?",a="Фолиант Отваги — это одновременно священная книга уроков и череда практических испытаний, которые проводит Собор Света. Проходя их, паладины доказывают, что у них хватает мужества противостоять тьме и защищать слабых, рискуя собой.",al={"tome of valor meaning","what is tome of valor","значение фолианта отваги","что такое фолиант отваги"}},{q="Что будет после завершения этого испытания?",a="Когда Даториан Ралл признает вашу доблесть в защите Дафны Стилвелл, он направит вас к следующему шагу духовного и боевого пути — Испытанию доблести, — и вы продолжите продвижение в ордене.",al={"next quest after tome of valor","what is next","следующее задание после фолианта отваги","что дальше"}},{q="Почему Церковь заботится о ферме Стилвеллов?",a="Дафна и Джордан Стилвелл давно помогают Церкви Священного Света верной службой и мастерством. Защита Дафны во время отсутствия Джордана — акт взаимной чести и милосердия, исполнение обещания Церкви заботиться о своих.",al={"why church help daphne","church and stilwells","почему церковь помогает дафне","церковь и стилвеллы"}}},fp="17,347,15.427.0,21.438.0,22.283.0,34.192.0,23.245.0,26.263.0,39.224.0,54.255.0"}
P.entries["quest:1653"] = {n="Испытание доблести",s="Испытание доблести знаменует переход от защиты невинных в Западном Крае к созданию священного оружия паладина. По поручению Даториана Ралла новобранец отправляется в Стальгорн, чтобы принести добрые вести набожному кузнецу Джордану Стилвеллу.",h="Испытание доблести знаменует переход от защиты невинных в Западном Крае к созданию священного оружия паладина.",kw={"daphne stilwell","defias brotherhood","dun morogh","duthorian rall","ironforge","jordan stilwell","stormwind","test of righteousness","дафна стилвелл","братство справедливости","дун морог","даториан ралл","стальгорн","джордан стилвелл","штормград","испытание доблести"},ang={["class:Paladin"]="Этот этап испытаний означает переход от защиты слабых к созданию священных орудий, необходимых, чтобы искоренять зло на землях Альянса.",["faction:Alliance"]="Беда семьи Стилвелл отражает растущую нестабильность в Западном Крае, где простой люд борется с Братством Справедливости, а королевские советники в Штормграде медлят.",["profession:Blacksmithing"]="Джордан Стилвелл доказывает, что истинная преданность наковальне может быть столь же святым выражением веры, как и освященный клинок на поле боя."},sec={{t="Вестник добрых новостей",b="Отстояв Дафну Стилвелл во время жестокой засады Братства Справедливости на ее ферме в Западном Крае, новобранец-паладин возвращается на Соборную площадь с докладом. Даториан Ралл понимает, что весть должна дойти до ее мужа, Джордана Стилвелла, который уехал в Стальгорн, считая свою семью в опасности. Ралл посылает юного рыцаря лично принести облегчение — это и жест товарищества, и преддверие более серьезного дела."},{t="Кузнец из Дун Морога",b="Джордану Стилвеллу изначально была уготована судьба паладина, но он предпочел продолжить ремесло отца и стал мастером-оружейником, не отказавшись от веры. Он поставил наковальню у ворот Стальгорна, чтобы работать на бодрящем горном воздухе, и полагается на духовную преданность, направляющую его молот. Узнав, что жена пережила нападение Братства Справедливости, он так глубоко благодарен, что решает помочь паладину выковать благословенное оружие праведности."}},faq={{q="Кто такой Джордан Стилвелл?",a="Джордан Стилвелл — набожный оружейник, работающий у огромных главных ворот Стальгорна. Хотя он изначально учился вместе с паладинами пути Света, в итоге он решил посвятить жизнь продолжению отцовского кузнечного ремесла.",al={"jordan stilwell","who is jordan","the smith in ironforge","джордан стилвелл","кто такой джордан","кузнец в стальгорне"}},{q="Почему жене Джордана грозила опасность?",a="Дафна Стилвелл живет на ферме в Западном Крае — диком краю, кишащем преступниками из Братства Справедливости. Ее муж опасался нападения, когда уезжал в столицу дворфов, и страх оправдался: бандиты напали на ферму, но были отброшены новобранцами-паладинами.",al={"daphne stilwell danger","what happened to jordan's wife","why defias attacked","опасность для дафны стилвелл","что случилось с женой джордана","почему напало братство справедливости"}},{q="Где найти Джордана Стилвелла?",a="Джордан Стилвелл работает у главных ворот Стальгорна, на холодном снегу Дун Морога. Он предпочитает свежий горный воздух удушающей жаре Великой кузни внутри горного города.",al={"where is jordan stilwell","stilwell location","jordan ironforge location","где джордан стилвелл","местонахождение стилвелла","где джордан стальгорн"}},{q="Почему Даториан Ралл посылает игрока в Стальгорн?",a="Даториан Ралл хочет, чтобы Джордан услышал от спасителя жены, что она пережила нападение Братства Справедливости. Это путешествие также сводит новобранца с мастером-кузнецом, способным помочь создать священное оружие паладина.",al={"why go to ironforge","duthorian rall errand","reason for message","зачем идти в стальгорн","поручение даториана ралла","причина послания"}},{q="Что будет после разговора с Джорданом?",a="Обрадованный новостью, Джордан предлагает свое мастерство, чтобы выковать для новобранца великолепный священный боевой молот. Для этого нужно собрать редкие материалы и освященные реликвии, разбросанные по дальним землям.",al={"test of righteousness next","what does jordan want","after talking to jordan","испытание доблести дальше","чего хочет джордан","после разговора с джорданом"}},{q="Что Джордан думает об угрозе Братства Справедливости?",a="Джордан возмущен слепой халатностью совета Штормграда. Он отмечает, что Братство Справедливости давно терзает Западный Край, но надеется, что нападения на честные фермы заставят регентов короля-мальчика наконец признать кризис.",al={"jordan defias opinion","stilwell king advisors","defias in westfall","мнение джордана о братстве справедливости","стилвелл советники короля","братство справедливости в западном крае"}}},fp="25,271,24.430.0,23.472.0,23.257.0,32.287.0,35.191.0,53.244.0,38.201.1,45.270.0"}
P.entries["quest:1655"] = {n="Партия руды Балора",s="«Партия руды Балора» — задание паладинов, которым нужен очищенный металл для освященного оружия Джордана Стилвелла. Партию сплава разграбили огры Мо'грош, устроив засаду на дороге из Болотины.",h="«Партия руды Балора» — задание паладинов, которым нужен очищенный металл для освященного оружия Джордана...",kw={"bailor","jordan stilwell","loch modan","mo'grosh","ogres","ore","shipment","stonehand","test of righteousness","балор","джордан стилвелл","лок модан","мо'грош","огры","руда","партия","крепкорук","испытание доблести"},ang={["class:Paladin"]="Возвращение сплава Балора — важный обряд посвящения в Испытании доблести: он доказывает, что вы способны бросить вызов опасным громилам ради материалов для вашего священного молота.",["faction:Alliance"]="Присутствие огров Мо'грош на северо-востоке Лок Модана остается угрозой для путей снабжения и караванов, идущих через перевал из Болотины.",["profession:Blacksmithing"]="Особый сплав Балора отражает строгие требования к металлургии, которые Джордан Стилвелл предъявляет при создании легендарного вооружения."},sec={{t="Караван в засаде",b="Когда Джордану Стилвеллу понадобилась особая партия руды, очищенной его старым другом Балором Крепкоруком, груз так и не добрался до рук Стальгорна. Когда караван с припасами пробирался на юг из Болотины в Лок Модан, на него напали из засады огры Мо'грош и перебили охрану. Последний уцелевший стражник дополз до лагеря, но вскоре скончался от ран, а груз остался на землях огров."},{t="Возвращение сплава",b="Балор Крепкорук, разбивший лагерь в Лок Модане, направляет паладинов через воды Озера Лок к северо-восточным холмам. Там, среди стоянок огров Мо'грош, брошен как добыча украденный ящик со сплавом. Вернув ящик, паладин доказывает решимость идти во вражескую землю, и Балор может выполнить прежнюю договоренность с Джорданом Стилвеллом."}},faq={{q="Кто такой Балор Крепкорук?",a="Балор Крепкорук — дворф-ремесленник и старый друг Джордана Стилвелла, работающий в Лок Модане. Он отвечает за приготовление и поставку особого сплава, нужного для ремесла Джордана.",al={"bailor stonehand","who is bailor","bailor","балор крепкорук","кто такой балор","балор"}},{q="Кто украл партию руды Джордана?",a="Огры Мо'грош напали из засады на караван с припасами, когда он шел из Болотины в Лок Модан, убили охрану и утащили груз в свои лагеря.",al={"who stole the ore","who took the shipment","ore thieves","кто украл руду","кто забрал партию","похитители руды"}},{q="Где произошла засада?",a="На караван напали на горной дороге, соединяющей Болотину и Лок Модан, до того как он добрался до безопасных поселений.",al={"ambush location","where was caravan attacked","место засады","где напали на караван"}},{q="Где находятся огры Мо'грош?",a="У огров Мо'грош укрепленные лагеря в суровых холмах к северо-востоку от Озера Лок, на другом берегу от западных поселений.",al={"where are mogrosh","ogre camp location","where is shipment","где мо'грош","лагерь огров","где груз"}},{q="Зачем нужна эта партия?",a="В партии лежит особый сплав, который нужен Джордану Стилвеллу, чтобы выковать священное оружие для паладинов, проходящих Испытание доблести.",al={"why need ore","what is shipment for","purpose of ore","зачем нужна руда","для чего партия","назначение руды"}},{q="Что случилось со стражниками каравана?",a="Почти все были убиты ограми сразу. Единственный стражник, сумевший бежать и добраться до помощи, умер через несколько дней, и целитель не успел его спасти.",al={"caravan guards","survivors of caravan","стражники каравана","выжившие из каравана"}}},fp="21,229,19.444.0,20.375.0,24.196.0,32.163.0,32.142.0,37.129.0,28.143.0,36.155.0"}
P.entries["quest:166"] = {n="Братство Справедливости",s="Это задание — венец долгой кампании Гриана Камнегрива за возвращение Западного Края из-под власти преступников. Защитники Альянса должны проникнуть в Мертвые копи, взломать убежище злодеев и сразить главаря, Эдвина ван Клифа.",h="Это задание — венец долгой кампании Гриана Камнегрива за возвращение Западного Края из-под власти...",kw={"deadmines","head","juggernaut","militia","moonbrook","stonemasons","stoutmantle","vancleef","westfall","мертвые копи","голова","исполин","ополчение","луноречье","каменщики","камнегрив","ван клиф","западный край"},ang={["class:Rogue"]="Ван Клиф — легендарный разбойник и мастер-ремесленник; скрестить с ним клинки в его логове — проверка боевой подготовки любого скрытного бойца.",["faction:Alliance"]="Это задание — важная ранняя победа Альянса: он защищает житницу Западного Края, когда трон Штормграда не может выделить собственные войска.",["race:Human"]="Для людей королевства смерть ван Клифа — горькая трагедия: падет тот самый мастер, чьи руки восстановили их столицу из пепла."},sec={{t="Вынесенный приговор",b="Месяцами Гриан Камнегрив и измотанное Народное ополчение отчаянно сдерживали Братство Справедливости по всему Западному Краю. Когда под Луноречьем обнаружили настоящее логово воров, Камнегрив издал свой последний мрачный приказ: Эдвина ван Клифа необходимо убить, чтобы раз и навсегда сломить хребет мятежа."},{t="В лабиринт",b="Чтобы привести приговор в исполнение, бойцам предстоит углубиться в извилистые штольни Мертвых копей. За мятежными каменщиками, гоблинами-инженерами и тяжелыми железными взрывоустойчивыми дверями находится центральный сухой док, где ван Клиф следит за достройкой своего большого боевого корабля. Его смерть разрушит цепь командования, скрепляющую всю сеть преступников."},{t="Тени большого заговора",b="Камнегрив считает, что смерть ван Клифа — начало конца Братства Справедливости, но тело павшего главаря хранит тревожные тайны. При нем найдено неотосланное письмо, намекающее, что восстание в Западном Крае не было отдельным мятежом, а частью более широкой и темной паутины, протянувшейся до самой знати Штормграда."}},faq={{q="Какова цель этого задания?",a="Гриан Камнегрив поручает вам отправиться в подземелье Мертвые копи в Луноречье, убить Эдвина ван Клифа и вернуться с его отрубленной головой в Сторожевой холм.",al={"quest objective","what do i do","what is this quest","цель задания","что делать","что это за задание"}},{q="Кто такой Эдвин ван Клиф?",a="Эдвин ван Клиф был Великим каменщиком Гильдии каменщиков и руководил восстановлением Штормграда после Первой и Второй войны. После жаркого спора об оплате с Домом знати он основал Братство Справедливости, чтобы отомстить королевству.",al={"who is vancleef","vancleef identity","edwin vancleef lore","кто такой ван клиф","личность ван клифа","эдвин ван клиф предание"}},{q="Почему Гриан Камнегрив приказывает совершить убийство?",a="Народному ополчению не хватает подкреплений регулярной армии из Штормграда, нужных для затяжной войны. Камнегрив понимает, что обезглавить руководство — единственный реальный шанс Западного Края сломить власть синдиката над фермами.",al={"why kill vancleef","stoutmantle motive","why death penalty","зачем убивать ван клифа","мотив камнегрива","почему смертный приговор"}},{q="Где можно найти Эдвина ван Клифа?",a="Он скрывается глубоко в Мертвых копях под Луноречьем. Гриан Камнегрив просит вас проникнуть в убежище и найти его.",al={"vancleef location","where is edwin vancleef","deadmines boss location","где ван клиф","где эдвин ван клиф","босс мертвых копей"}},{q="Уничтожит ли смерть ван Клифа Братство Справедливости полностью?",a="Камнегрив надеется, что смерть ван Клифа сломит власть Братства над Западным Краем. Исход и дальнейшие открытия ждут вас при штурме.",al={"is defias defeated","are defias gone","end of brotherhood","побеждено ли братство","исчезло ли братство справедливости","конец братства"}},{q="Какой важный предмет находят у ван Клифа после его гибели?",a="Камнегрив требует голову ван Клифа в качестве доказательства. Другие открытия в убежище раскрываются в ходе задания.",al={"vancleef drop","unsent letter","what does vancleef drop","добыча с ван клифа","неотосланное письмо","что выпадает с ван клифа"}}},fp="22,257,17.364.0,18.354.1,31.343.1,31.164.0,22.275.0,50.257.0,34.123.0,52.140.1,55.115.1"}
P.entries["quest:1665"] = {n="Кружка Бартлби",s="«Кружка Бартлби» — заключительное задание в начальном испытании выдержки молодого воина Штормграда. Победив драчуна Бартлби в таверне «Свинья и свисток», герой забирает его кружку как доказательство победы для своего учителя, Гарри Берлгарда.",h="«Кружка Бартлби» — заключительное задание в начальном испытании выдержки молодого воина Штормграда.",kw={"bartleby","burlguard","mug","old town","pig and whistle","stormwind","warrior","бартлби","берлгард","кружка","старый город","свинья и свисток","штормград","воин"},ang={["class:Warrior"]="Учителя Штормграда считают, что практическая драка учит тому, чему не научит ни одно руководство: кружка Бартлби доказывает, что вы способны сойтись лицом к лицу и одолеть буйных врагов.",["faction:Alliance"]="Поддержание порядка в Старом городе часто означает усмирение буйных посетителей, и Бартлби — привычная местная головная боль для боевых наставников Штормграда."},sec={{t="Трофей трактирной драки",b="Учителя воинов в Штормграде не жалуют изящную теорию: им нужны чистая решимость и умение стоять на своем. Гарри Берлгард поручает начинающим воинам одолеть Бартлби, упрямого пьяницу у стойки таверны «Свинья и свисток» в Старом городе. Усмиренный Бартлби неохотно отдает свою любимую кружку, но сперва делает последний глоток, допивая остатки."},{t="Шаг к мастерству",b="Возвращение кружки Гарри Берлгарду завершает испытание новичка. Заметив талант бойца убеждать грубой силой, Берлгард признает готовность воина к защитному мастерству и направляет его к дальнейшему боевому обучению и опытному ветерану, маршалу Хаггарду в Элвиннском лесу."}},faq={{q="Зачем Гарри Берлгарду кружка Бартлби?",a="Кружка — неоспоримое доказательство того, что начинающий воин действительно сразился с Бартлби и победил его. Бартлби сильно привязан к выпивке, так что отданная личная кружка доказывает, что его крепко побили.",al={"why bartleby mug","burlguard mug purpose","proof of beating bartleby","зачем кружка бартлби","зачем берлгарду кружка","доказательство победы над бартлби"}},{q="Кто такой Бартлби?",a="Бартлби — буйный посетитель таверны, засевший у стойки «Свиньи и свистка» в Старом городе Штормграда. Из-за пьянства и скверного нрава местные учителя воинов используют его как неофициальное испытание для подающих надежды бойцов.",al={"bartleby lore","who is bartleby the drunk","bartleby old town","бартлби предание","кто такой бартлби пьяница","бартлби старый город"}},{q="Где проходит этот бой?",a="Драка происходит в таверне «Свинья и свисток» в Старом городе Штормграда.",al={"where is bartleby","bartleby location","pig and whistle fight","где бартлби","местонахождение бартлби","драка в свинье и свистке"}},{q="Что будет после возвращения кружки Берлгарду?",a="Когда Берлгард осмотрит кружку и подтвердит вашу победу, он научит вас продвинутым защитным боевым стойкам, а затем отправит за городские ворота искать маршала Хаггарда в Элвиннском лесу.",al={"what next after bartleby mug","quest after bartleby mug","haggard quest","что дальше после кружки бартлби","задание после кружки бартлби","задание хаггарда"}},{q="Получает ли Бартлби в драке постоянные увечья?",a="Нет. Драка — всего лишь нешуточная потасовка в таверне. Побежденный Бартлби сдается, допивает свой напиток, отдает кружку и остается в таверне зализывать синяки и уязвленную гордость.",al={"is bartleby dead","did bartleby die","bartleby survived","бартлби мертв","умер ли бартлби","бартлби выжил"}},{q="Может ли выполнить это задание любой класс Альянса?",a="Это задание строго для воинов Альянса: оно входит в обучение класса на 10 уровне и учит искусству боевых стоек и защитных приемов.",al={"is bartlebys mug warrior only","who can do bartleby quest","mug quest classes","кружка бартлби только для воинов","кто может выполнить задание бартлби","классы задания с кружкой"}}},fp="14,263,24.402.0,21.338.0,45.218.0,16.237.0,33.91.0,48.203.0,48.184.0,37.166.0"}
P.entries["quest:1666"] = {n="Маршал Хаггард",s="«Маршал Хаггард» — задание Альянса, которое в Штормграде дает новичкам-воинам Гарри Берлгард, когда они ищут оружие получше. Молодого бойца отправляют из столицы на Лесопилку Восточной долины на востоке Элвиннского леса, к отставному маршалу, хранящему богатую коллекцию ветеранского оружия. Это ранний шаг на боевом пути воина за пределами безопасных городских стен.",h="«Маршал Хаггард» — задание Альянса, которое в Штормграде дает новичкам-воинам Гарри Берлгард, когда они ищут...",kw={"eastvale","eastvale logging camp","elwynn forest","harry burlguard","marshal haggard","stormwind","warrior","восточная долина","лесопилка восточной долины","элвиннский лес","гарри берлгард","маршал хаггард","штормград","воин"},ang={["class:Warrior"]="Это задание — ранняя веха для воинов Альянса: они переходят от формального городского обучения в глушь в поисках боевого снаряжения.",["faction:Alliance"]="Задание показывает, что Штормград полагается на опыт и личные запасы отставных ветеранов, воспитывая следующее поколение защитников."},sec={{t="Арсенал ветерана",b="Новичкам-воинам в Штормграде быстро напоминают, что одна техника без надежной стали мало чего стоит. Гарри Берлгард направляет перспективных бойцов найти маршала Хаггарда, отставного офицера королевства, живущего в тихой глуши востока Элвиннского леса. За жизнь в походах Хаггард собрал изрядный личный арсенал, и его усадьба — естественная цель для начинающих воинов, которым нужно настоящее снаряжение."},{t="Отставка в Восточной долине",b="Маршал Хаггард живет в уединенном особняке возле Лесопилки Восточной долины. Годы тяжелой службы сказались на стареющем командире: зрение слабеет, и он склонен принимать приближающихся путников за крадущихся гноллов Речной Лапы. Несмотря на возраст и уединение, старый маршал остается уважаемой фигурой среди стражей и учителей Штормграда."}},faq={{q="Кто дает это задание?",a="Гарри Берлгард, учитель воинов в Штормграде, предлагает это задание, когда начинающий воин доказал свои основные навыки.",al={"where do i get marshal haggard quest","who gives marshal haggard","quest giver marshal haggard","где взять задание маршала хаггарда","кто дает задание маршала хаггарда","персонаж, выдающий задание маршал хаггард"}},{q="Где находится маршал Хаггард?",a="Маршал Хаггард живет в особняке к востоку от Лесопилки Восточной долины, на крайнем востоке Элвиннского леса, у границы Красногорья.",al={"marshal haggard location","where is haggard","eastvale lumber camp manor","местонахождение маршала хаггарда","где хаггард","особняк у лесопилки восточной долины"}},{q="Почему Гарри Берлгард посылает вас к Хаггарду?",a="Берлгард понимает, что растущему воину нужно качественное снаряжение, а не обычные клинки новобранцев. Хаггард за долгую карьеру собрал немало оружия и доспехов и, как известно, расстается со снаряжением с теми, кто доказал свою ценность.",al={"why marshal haggard","why go to eastvale warrior","purpose of marshal haggard quest","почему маршал хаггард","зачем идти к воину в восточную долину","цель задания маршала хаггарда"}},{q="Почему Хаггард принимает посетителей за гноллов?",a="Зрение Хаггарда сильно ухудшилось с возрастом. Поскольку гноллы часто досаждают лесозаготовкам и окраинам востока Элвиннского леса, осторожный старый ветеран настороженно встречает внезапных гостей.",al={"haggard eyesight","is haggard blind","haggard gnoll dialogue","зрение хаггарда","слеп ли хаггард","хаггард гноллы диалог"}},{q="Что будет после выполнения этого задания?",a="Встретив Хаггарда, отставной маршал испытает вашу доблесть, отправив вас на задание «Джек Мертвозуб», прежде чем расстанется с оружием из своих запасов.",al={"marshal haggard next quest","follow up to marshal haggard","следующее задание маршала хаггарда","продолжение маршала хаггарда"}},{q="Доступно ли это задание другим классам, кроме воинов?",a="Нет. Эта цепочка заданий входит в обучение воина на 10 уровне и призвана снарядить молодых бойцов для испытаний за пределами Элвиннского леса.",al={"can paladins do marshal haggard","warrior only quest haggard","могут ли паладины выполнить маршала хаггарда","задание хаггарда только для воинов"}}},fp="15,402,18.447.0,22.364.0,22.144.0,33.167.0,45.245.0,45.226.0,39.178.1,55.142.0"}
P.entries["quest:1667"] = {n="Джек Мертвозуб",s="Маршал Хаггард, отставной офицер, живущий в восточной части Элвиннского леса, был обманом лишен своего официального знака отличия: его отдал разбойнику из Братства Справедливости по имени Джек Мертвозуб. Джек в темноте нарядился в табард Штормграда, выдал себя за маршала Дугхана и украл значок. Хаггарду нужно вернуть значок, пока Братство Справедливости не использовало его, чтобы выдавать себя за штормградских чиновников.",h="Маршал Хаггард, отставной офицер, живущий в восточной части Элвиннского леса, был обманом лишен своего...",kw={"badge","dead-tooth jack","defias","elwynn forest","guard burlguard","impersonation","marshal dughan","marshal haggard","strongbox","значок","джек мертвозуб","братство справедливости","элвиннский лес","гарри берлгард","самозванство","маршал дугхан","маршал хаггард","ларец"},ang={["class:Rogue"]="Проделка Джека Мертвозуба показывает, что Братство Справедливости полагается на маскировку, обман и наглость не меньше, чем на грубый разбой на дорогах.",["class:Warrior"]="Маршал Хаггард когда-то был ветераном передовой и награждает тех, кто вернет его честь, запасным оружием, сохраненным со времен активной службы.",["race:Human"]="Для людей Штормграда эта кража показывает, насколько уязвимы сельские границы королевства перед лазутчиками Братства Справедливости, которые без колебаний надевают цвета короны, чтобы обманывать отставных ветеранов."},sec={{t="Обман в темноте",b="Даже опытных солдат могут застать врасплох на склоне лет. Маршал Хаггард, живущий в уединенном домике на восточных холмах Элвиннского леса, решил, что говорит с маршалом Дугханом, когда однажды ночью к нему подошла фигура в табарде Штормграда. Незнакомец сослался на служебное дело и попросил старый маршальский значок Хаггарда. Полагая, что передает его другому офицеру, Хаггард отдал значок — и самозванец, вор из Братства Справедливости по имени Джек Мертвозуб, рассмеялся ему в лицо и скрылся в лесу."},{t="Угроза ложной власти",b="Хотя Хаггард в отставке, его старый значок по-прежнему несет юридический вес и власть Королевства Штормград. Поскольку бандиты Братства Справедливости рыщут по Элвиннскому лесу, Западному Краю и Красногорью, подлинный офицерский значок в руках преступников представляет непосредственную опасность. Он мог бы позволить мошенникам проходить через сторожевые посты, перенаправлять патрули или отбирать припасы. Джек уходит в лагерь на юге, чтобы спрятать добычу в запертый ларец, и Хаггард отчаянно желает вернуть значок, пока не случилась беда."}},faq={{q="Кто такой Джек Мертвозуб?",a="Джек Мертвозуб — агент Братства Справедливости, действующий в восточной части Элвиннского леса. Известный своей дерзостью, он под покровом темноты выдал себя за маршала Дугхана и обманом заставил маршала Хаггарда, находящегося в отставке, передать ему свой официальный знак Штормграда.",al={"dead tooth jack","who is dead tooth","dead tooth jack lore","джек мертвозуб","кто такой мертвозуб","джек мертвозуб предания"}},{q="Почему маршалу Хаггарду нужно вернуть значок?",a="Значок — подлинный символ власти Штормграда. Хаггард опасается, что, если он останется у Братства Справедливости, его используют, чтобы выдавать себя за чиновников, обходить военные патрули и сеять хаос по всему королевству.",al={"why recover badge","haggards badge","why does the badge matter","зачем возвращать значок","значок хаггарда","почему значок важен"}},{q="Как Джеку удалось обмануть маршала Хаггарда?",a="Джек подошел к дому Хаггарда ночью в табарде Штормграда. При плохом освещении Хаггард принял его за маршала Дугхана из Златоземья и по просьбе без вопросов отдал знак отличия.",al={"how did he fool haggard","haggard tricked","why did haggard give the badge","как он обманул хаггарда","хаггард обманут","почему хаггард отдал значок"}},{q="Где Джек хранит украденный значок?",a="Джек держит значок в запертом ларце в своем лагере бандитов к югу от дома маршала Хаггарда. Ключ от сундука Джек носит при себе.",al={"badge location","where is the badge","dead tooth camp","где значок","местонахождение значка","лагерь мертвозуба"}},{q="Кто отправил вас к маршалу Хаггарду?",a="Гарри Берлгард, воин-ветеран, частый гость таверны «Свинья и свисток» в Штормграде, посылает искателей приключений к Хаггарду, зная, что у старого маршала есть лишнее оружие, с которым он может расстаться в обмен на помощь.",al={"who sends you here","burlguard","questgiver start","кто посылает сюда","берлгард","начало задания"}},{q="Что будет, когда значок вернут?",a="Хаггард несказанно рад, что Братство Справедливости не сможет использовать его личность и звание против королевства. В благодарность он салютует вам и предлагает выбрать любое из добротного военного оружия времен его службы.",al={"quest turn in","haggard reaction","badge returned","сдача задания","реакция хаггарда","значок возвращен"}}},fp="15,375,17.532.0,29.519.0,23.253.0,45.200.0,44.199.0,38.156.0,51.204.0,40.207.1"}
P.entries["quest:167"] = {n="О, брат мой...",s="«О, брат мой...» — задание Альянса, которое дает Чертополохх Дикий в Штормграде. Потрясенный обвалом во время экспедиции в глубины под Луноречьем, Чертополохх просит искателей приключений найти в лабиринте шахт его пропавшего брата, Штейгера Чертополоха, или вернуть его значок Лиги исследователей.",h="«О, брат мой...» — задание Альянса, которое дает Чертополохх Дикий в Штормграде.",kw={"badge","deadmines","explorers' league","moonbrook","stormwind","thistlenettle","undead","westfall","wilder","значок","мертвые копи","лига исследователей","луноречье","штормград","чертополох","нежить","западный край","чертополохх"},ang={["faction:Alliance"]="Мертвые копи — язва на пороге Штормграда, и это задание показывает, насколько сильно Братство Справедливости и подземные чудовища навредили мирным жителям.",["race:Dwarf"]="Трагическая гибель штейгера Лиги исследователей в землях людей задевает каждого дворфа, ценящего братство, каменотесное дело и неустанную работу Лиги."},sec={{t="Экспедиция в ловушке",b="Чертополохх Дикий и его брат вошли в пещерные подземные туннели под Луноречьем как члены горнодобывающей компании. Но все обернулось катастрофой: на местность налетели враждебные воры, а сильный обвал запер нижние туннели. Чертополохху удалось бежать в Штормград, но его брат и остальная бригада остались в ловушке за завалом."},{t="Мрачная судьба Штейгера Чертополоха",b="Правда, ждущая любого спасателя, который проникнет вглубь туннелей Мертвых копей, трагична. Штейгер Чертополох не пережил погребения: темные силы, пробудившиеся в заброшенных копях, подняли несчастного дворфа в виде оболочки нежити. Блуждая по подземным пещерам среди других беспокойных мертвецов, штейгер сохранил лишь свой драгоценный значок Лиги исследователей как память о том, кем он был."}},faq={{q="Где начать задание «О, брат мой...»?",a="Задание выдает Чертополохх Дикий, которого можно найти в Квартале Дворфов города Штормград.",al={"quest giver oh brother","who gives oh brother","where to get oh brother","кто выдает о брат мой","кто дает о брат мой","где взять о брат мой"}},{q="Где находится Штейгер Чертополох?",a="Штейгер Чертополох бродит по внешним коридорам Мертвых копей, расположенных под городом Луноречье в Западном Крае. Он находится в кишащей нежитью части туннелей снаружи портала в подземелье.",al={"foreman thistlenettle location","where is thistlenettle","where is the brother","где штейгер чертополох","где чертополох","где брат"}},{q="Что случилось со Штейгером Чертополохом?",a="Обвал запер Штейгера Чертополоха и его рабочих в пещерах, и с тех пор о них нет вестей. Найти его или хотя бы его значок — единственный способ для Чертополохха узнать судьбу брата.",al={"is thistlenettle alive","what happened to the brother","thistlenettle lore","жив ли чертополох","что случилось с братом","чертополох предания"}},{q="Какой предмет нужно добыть?",a="Нужно добыть значок Лиги исследователей Штейгера Чертополоха, который он всегда носил с собой; найдите штейгера в глубине туннелей Мертвых копей, и значок будет при нем.",al={"oh brother quest item","what drops for oh brother","предмет задания о брат мой","что выпадает для о брат мой"}},{q="Чем занималась экспедиция в Луноречье?",a="Братья Чертополох были членами горнодобывающей компании, работавшей в обширной шахте под Луноречьем, пока на них не напали бандиты Братства Справедливости, а внезапный обвал туннеля не разделил их.",al={"why were the dwarves in westfall","explorers league deadmines","why were they in moonbrook","почему дворфы в западном крае","лига исследователей мертвые копи","почему они в луноречье"}},{q="Выполняется ли это задание внутри подземелья Мертвые копи?",a="Нет, входить в подземелье не нужно. Штейгер Чертополох — элитный монстр, бродящий по спорным туннелям копей, ведущим к порталу в подземелье.",al={"is oh brother inside deadmines instance","do i need a dungeon group","о брат мой внутри мертвых копей","нужна ли группа в подземелье"}}},fp="15,316,20.372.0,38.411.1,45.105.0,39.207.0,39.215.1,32.173.1,43.182.0,62.168.0"}
P.entries["quest:1679"] = {n="Марен Грозовая Вершина",s="Марен Грозовая Вершина — вводное задание для начинающих воинов Альянса, которое дают, когда новобранец доказывает свою базовую доблесть в Дун Мороге. По указанию Граниса Быстрого Топора в Караносе молодой боец отправляется в горный город Стальгорн, чтобы пройти формальное обучение воинской дисциплине. Встреча с Мареном знаменует начало более глубокого обучения боевым стойкам и военным традициям дворфов.",h="Марен Грозовая Вершина — вводное задание для начинающих воинов Альянса, которое дают, когда новобранец...",kw={"defensive stance","granis swiftaxe","hall of arms","ironforge","kharanos","military ward","muren stormpike","warrior trainer","оборонительная стойка","гранис быстрый топор","зал оружия","стальгорн","каранос","военный квартал","марен грозовая вершина","наставник воинов"},ang={["class:Warrior"]="Этот вызов отмечает ваш переход от неопытного новобранца к дисциплинированному солдату, способному держать строй и защищать союзников.",["race:Dwarf"]="Для воинов-дворфов явка в Зал Оружия напрямую связывает вас со знаменитой воинской родословной и тактической дисциплиной горных кланов.",["race:Gnome"]="Гномы-воины, эвакуировавшиеся в Дун Морог после падения Гномрегана, полагаются на Зал Оружия Стальгорна, чтобы освоить традиционный тяжелый бой на передовой."},sec={{t="Вызов в Стальгорн",b="Набравшись опыта в сражениях с местными угрозами в снежных долинах Дун Морога, новички-воины привлекают внимание Граниса Быстрого Топора в Караносе. Понимая, что грубыми стычками драчун далеко не уйдет, Быстрый Топор посылает многообещающих бойцов в сердце воинского мастерства дворфов — Военный квартал Стальгорна. Там, в гулких залах города-кузницы, старшие бойцы руководят официальным обучением тех, кому предстоит битва."},{t="Мастер оружия",b="Добравшись до Зала Оружия, новобранцы знакомятся с Мареном Грозовой Вершиной, опытным ветераном знаменитого клана дворфов. Марен мало заботится о тавернных байках и требует доказательств, что его новые подопечные выдержат настоящий бой. Явка к нему открывает путь к освоению защитных умений, к умению принимать на себя и контролировать вражескую агрессию и к получению добротного железного вооружения, достойного настоящей службы на передовой."}},faq={{q="Кто посылает вас к Марену Грозовой Вершине?",a="Гранис Быстрый Топор, наставник воинов в Караносе, дает вам задание, когда вы докажете свои базовые боевые способности в Дун Мороге.",al={"who gives muren stormpike quest","where do i get muren stormpike","quest giver muren stormpike","кто дает задание марен грозовая вершина","где взять марен грозовая вершина","выдающий задание марен"}},{q="Где находится Марен Грозовая Вершина?",a="Марен Грозовая Вершина находится в Зале Оружия, расположенном в Военном квартале в восточной части Стальгорна.",al={"where is muren stormpike","muren stormpike location","how to find muren","где марен грозовая вершина","местонахождение марена","как найти марена"}},{q="Чем это задание важно для воинов?",a="Явка к Марену начинает продвинутое обучение воина. Оно напрямую ведет к заданиям, открывающим Оборонительную стойку, обучающим важным защитным умениям, таким как Провокация, и дающим надежное оружие для начала пути.",al={"what does muren stormpike unlock","why do muren stormpike","muren stormpike rewards","что открывает марен грозовая вершина","зачем марен грозовая вершина","награды марена"}},{q="Кто такой Марен Грозовая Вершина?",a="Марен — ветеран-инструктор по боевой подготовке в Стальгорне из знаменитого клана Грозовой Вершины, влиятельной семьи дворфов, известной свирепыми воинами и инженерами-исследователями.",al={"who is muren","muren stormpike lore","is muren stormpike clan","кто такой марен","марен грозовая вершина предания","клан грозовой вершины"}},{q="Может ли взять это задание любой класс?",a="Нет. Это задание предназначено строго для новичков-воинов, готовых пройти специальное боевое обучение.",al={"can non warriors do muren stormpike","is muren stormpike warrior only","muren stormpike classes","могут ли не воины марен грозовая вершина","только для воинов","классы марен грозовая вершина"}},{q="Что происходит после встречи с Мареном?",a="Когда вы прибудете и поговорите с Мареном, он сразу проверит вашу решимость и направит вас на боевое испытание, начиная с задания о схватке с Вейреком.",al={"what is next after muren stormpike","next quest after muren stormpike","vejrek quest","что дальше после марена","следующее задание после марена","задание вейрек"}}},fp="15,395,22.444.0,18.414.0,38.145.0,33.115.0,41.202.0,23.180.0,30.105.0,38.158.0"}
P.entries["quest:168"] = {n="Сбор воспоминаний",s="Сбор воспоминаний — торжественное поручение дворфа-шахтера Чертополохха Дикого в Штормграде. Он просит искателей приключений, отважившихся спуститься в разрушенные шахты под Луноречьем, вернуть членские карточки Союза шахтеров его погибших товарищей. Эти реликвии приносят скорбящим семьям в столице утешение после страшного обвала.",h="Сбор воспоминаний — торжественное поручение дворфа-шахтера Чертополохха Дикого в Штормграде.",kw={"collecting memories","deadmines","miners union card","moonbrook","stormwind","undead miners","wilder thistlenettle","сбор воспоминаний","мертвые копи","карточка союза шахтеров","луноречье","штормград","шахтеры-нежить","чертополохх дикий"},ang={["faction:Alliance"]="Возвращая реликвии погибших рабочих Западного Края, вы напрямую помогаете скорбящим семьям рабочих, переживающим тяжелые времена в стенах Штормграда.",["profession:Mining"]="Каждый шахтер знает, какой гнетущий страх вызывает обвал в штольне, и потому это задание — вернуть утерянные карточки Союза — находит глубокий и скорбный отклик у тех, кто держит кирку.",["race:Dwarf"]="Дворфы высоко ценят узы, выкованные под землей, и неприкосновенность павших собратьев, поэтому просьба Чертополохха Дикого близка каждому, в ком течет каменная кровь."},sec={{t="Трагический обвал",b="Прежде чем Луноречье окончательно погрузилось в беззаконие и оказалось под тенью Братства Справедливости, шахты Западного Края кормили множество семей рабочих. Чертополохх Дикий пережил чудовищный обвал, погребший одно из крыльев запутанных туннелей, но многие его друзья и товарищи по работе не были так удачливы. Отрезанные от помощи, они погибли глубоко под землей, а их родные в Штормграде так и не получили настоящего подтверждения или утешения о судьбе близких."},{t="Неупокоенные останки",b="Туннели за главными подземными железными рудниками больше не безмолвные гробницы. Души шахтеров, погибших при обвале, теперь бродят по темным ходам в виде неупокоенных мертвецов. Чтобы вернуть карточки Союза шахтеров, путникам придется пройти через эти населенные призраками штольни и сразиться с оживленными останками тех самых рудокопов, с которыми когда-то работал Дикий. Если вернуть карточки в Штормград, родные наконец узнают правду, а Дикий сможет почтить память павших собратьев."}},faq={{q="Кто такой Чертополохх Дикий?",a="Чертополохх Дикий — дворф-шахтер, живущий в Штормграде. Он пережил страшный обвал туннеля под Западным Краем, унесший жизни его близких товарищей, и теперь стремится принести покой и определенность их оставшимся в живых семьям.",al={"wilder thistlenettle","quest giver","who gives collecting memories","чертополохх дикий","персонаж, выдающий задание","кто дает задание сбор воспоминаний"}},{q="Что случилось с шахтерами в Мертвых копях?",a="Страшный обвал туннеля похоронил и убил целую бригаду шахтеров в одном из крыльев рудников Луноречья. Лишенные спасения и достойного погребения, их души и тела восстали неупокоенной нежитью и бродят по заброшенным ходам.",al={"why are there undead miners","mine collapse","deadmines cave in","почему шахтеры нежить","обвал в шахте","обвал в мертвых копях"}},{q="Зачем Дикому карточки Союза шахтеров его товарищей?",a="Карточки Союза служат официальным удостоверением погибших при обвале рабочих. Поскольку тела так и не нашли, с помощью карточек Дикий может официально уведомить их семьи в Штормграде и дать им утешение.",al={"what are the union cards for","miners union cards","для чего нужны карточки союза","карточки союза шахтеров"}},{q="Где найти карточки Союза?",a="Карточки находятся в населенных призраками внешних туннелях под Луноречьем, в коридорах прямо перед входом в охраняемую часть самих Мертвых копей.",al={"where do i find the cards","undead deadmines location","where are the dead miners","где найти карточки","нежить в мертвых копях","где мертвые шахтеры"}},{q="Был ли обвал делом рук Братства Справедливости?",a="Чертополохх Дикий вспоминает об этом просто как о страшном несчастном случае и обвале туннеля. Хотя теперь глубокими ходами Мертвых копей владеет Братство Справедливости, сама трагедия, судя по всему, была катастрофическим обрушением на производстве, погубившим его товарищей-шахтеров.",al={"did defias cause the cave in","who collapsed the mine","виновно ли братство справедливости в обвале","кто обрушил шахту"}},{q="Входят ли шахтеры в Братство Справедливости?",a="Нет. Это были обычные рабочие Союза, трудившиеся в шахтах, когда произошел обвал. Их неупокоенные останки бродят на окраинах пещер отдельно от организованных сил Братства Справедливости Эдвина ван Клифа, находящихся дальше внутри.",al={"are dead miners defias","are undead miners with defias","мертвые шахтеры из братства справедливости","нежить шахтеры с братством"}}},fp="19,339,17.529.0,16.482.0,28.247.0,45.237.0,47.237.0,32.162.0,45.261.0,57.210.0"}
P.entries["quest:1681"] = {n="Мастерская Сталекрута",s="Кузнец из Стальгорна Тормус Подземная Кузня жаждет отомстить за своего наставника Стерджи Сталекрута, чья отдаленная учебная мастерская в восточном Дун Мороге пала жертвой внезапного кровавого нападения. Резня последовала за прибытием редкой партии теневой руды, которая тут же привлекла жестокое внимание дворфов Черного Железа.",h="Кузнец из Стальгорна Тормус Подземная Кузня жаждет отомстить за своего наставника Стерджи Сталекрута, чья...",kw={"blacksmithing","dark iron","dun morogh","helm's bed lake","ironband's compound","sturgy ironband","tormus deepforge","umbral ore","кузнечное дело","черное железо","дун морог","озеро хельмово ложе","мастерская сталекрута","стерджи сталекрут","тормус подземная кузня","теневая руда"},ang={["profession:Blacksmithing"]="Печальная судьба Стерджи Сталекрута — поучительная история о том, как погоня за экзотическими, неопробованными рудами может навлечь на кузню смертельную опасность.",["race:Dwarf"]="Набег на форпост Сталекрута показывает горькую и неугасающую ненависть между дворфами Бронзоборода из Стальгорна и их сородичами из Черного Железа."},sec={{t="Гибель мастера",b="Стерджи Сталекрут пользовался в Стальгорне почетом как непревзойденный наставник кузнечного дела. Из своей уединенной мастерской к югу от Озера Хельмово Ложе он обучал многообещающих учеников вдали от людных наковален Великой кузни. Эта мирная жизнь внезапно оборвалась, когда один из его учеников раздобыл незнакомый минерал, названный теневой рудой. Заинтригованный ее свойствами, Сталекрут решил поэкспериментировать с образцом, не подозревая, что обладание им обрекло его школу на гибель."},{t="Набег Черного Железа",b="Вскоре после того как теневая руда попала в мастерскую, враждебные дворфы Черного Железа предприняли безжалостное внезапное нападение на форпост. Нападавшие не знали пощады: они убили Стерджи Сталекрута и всех учеников, находившихся на его попечении, а затем заняли территорию. Тормус Подземная Кузня, один из уцелевших учеников Сталекрута, живущий в столице, не желает мириться с этой резней и посылает путников из Альянса отомстить за учителя и вернуть проклятую руду, принесшую гибель лагерю."}},faq={{q="Где находится Мастерская Сталекрута?",a="Мастерская Сталекрута находится в восточном Дун Мороге, среди заснеженных холмов к югу от Озера Хельмово Ложе.",al={"ironband location","where is compound","find ironband's compound","где сталекрут","где мастерская","найти мастерскую сталекрута"}},{q="Кто такой Стерджи Сталекрут?",a="Стерджи Сталекрут был известным дворфом, мастером-кузнецом. Он содержал особую учебную мастерскую за пределами Стальгорна, где обучал учеников сложной обработке металла, пока не был убит во время набега дворфов Черного Железа.",al={"who is ironband","sturgy ironband lore","who was sturgy","кто такой сталекрут","стерджи сталекрут предания","кто был стерджи"}},{q="Почему дворфы Черного Железа напали на мастерскую?",a="Нападение вызвала партия теневой руды, привезенная одним из учеников Сталекрута. Вскоре после ее прибытия дворфы Черного Железа обрушились на мастерскую, перебили всех, кто там был, и захватили это место.",al={"why attack","why dark iron raid","dark iron motive","почему напали","почему набег черного железа","мотив черного железа"}},{q="Что такое теневая руда?",a="Теневая руда — редкий и загадочный минерал. Мастер Сталекрут горел желанием выковать из нее что-нибудь, но ее появление тут же привлекло смертельный интерес клана Черного Железа.",al={"umbral ore lore","what is umbral","strange ore","теневая руда предания","что такое теневая руда","странная руда"}},{q="Кто такой Тормус Подземная Кузня?",a="Тормус Подземная Кузня — кузнец из Стальгорна и бывший ученик Стерджи Сталекрута. Потрясенный потерей учителя, он посылает искателей приключений наказать захватчиков из Черного Железа и вернуть руду.",al={"who gives ironbands compound","tormus deepforge lore","who is deepforge","кто дает задание мастерская сталекрута","тормус подземная кузня предания","кто такой подземная кузня"}},{q="Что Тормус хочет забрать из мастерской?",a="Тормус поручает путникам уничтожить налетчиков из Черного Железа, чтобы отомстить за Сталекрута, и добыть партию теневой руды, ставшую причиной катастрофы.",al={"what to get","compound objective","quest turn in","что добыть","цель в мастерской","сдача задания"}}},fp="19,307,15.487.0,18.496.0,37.101.0,24.208.0,50.230.0,19.169.0,24.205.0,50.149.0"}
P.entries["quest:1683"] = {n="Ворлус Подлое Копыто",s="Ворлус Подлое Копыто — это обряд посвящения для молодых ночных эльфов-воинов, обучающихся в Дарнассе. По указанию учителя воинов Эланарии кандидаты должны выследить мерзкого сатира, осквернившего скрытый лунный колодец близ Обители Бен'этиль.",h="Ворлус Подлое Копыто — это обряд посвящения для молодых ночных эльфов-воинов, обучающихся в Дарнассе.",kw={"ban'ethil","darnassus","elanaria","horn of vorlus","moonwell","satyr","teldrassil","vorlus vilehoof","warrior quest","бен'этиль","дарнасс","эланария","рог ворлуса","лунный колодец","сатир","тельдрассил","ворлус подлое копыто","задание воина"},ang={["class:Warrior"]="Охота на Ворлуса Подлого Копыта — ваше посвящение в продвинутую боевую подготовку, доказывающее, что ваш клинок служит защите земель кальдораев и святости богини.",["faction:Alliance"]="Защита глубин Тельдрассила от притаившихся остатков демонических сил обеспечивает Дарнассу роль надежного оплота Альянса в северном Калимдоре.",["race:NightElf"]="Лунные колодцы воплощают чистоту Элуны и животворную основу духовности кальдораев; терпеть сатира, купающегося в их водах, — нестерпимое оскорбление для всех ночных эльфов."},sec={{t="Испытание воли",b="Прежде чем Эланария передаст молодым ночным эльфам-воинам передовые боевые приемы, она требует доказательств их преданности и дисциплины. Слова ничего не значат в обороне Калимдора: истинный страж должен уметь лицом к лицу встретить скверну и очистить священные ветви Тельдрассила от порчи."},{t="Осквернение священных вод",b="Цель этого испытания — Ворлус Подлое Копыто, сатир, пробравшийся к уединенному лунному колодцу в горах к юго-востоку от Обители Бен'этиль. Сатиры, древние предатели, искаженные влиянием демонов, питают неугасимую ненависть к священным реликвиям кальдораев. Ворлус взял за обыкновение купаться в лунном колодце, оскверняя его благословенные воды своим присутствием и насмехаясь над милостью Элуны."},{t="Добыча рога",b="Чтобы найти Ворлуса, нужно пройти по скрытой горной тропе, которую охраняют враждебные фурболги из племени Гнилой Сосны. Когда сатир будет загнан у оскверненного источника, его нужно убить в честном бою. Рог Ворлуса, принесенный на Террасу Воинов в Дарнассе, докажет гибель твари, вернет святость уединенной поляне и откроет путь к особому боевому оружию."}},faq={{q="Кто такой Ворлус Подлое Копыто?",a="Ворлус Подлое Копыто — оскверненный сатир, обитающий в Тельдрассиле. Он обнаружил уединенный лунный колодец к юго-востоку от Обители Бен'этиль и стал купаться в нем, намеренно оскверняя его освященные воды.",al={"vorlus vilehoof lore","who is vorlus","vorlus the satyr","ворлус подлое копыто предания","кто такой ворлус","сатир ворлус"}},{q="Почему Эланария посылает воинов за Ворлусом?",a="Эланария использует эту охоту как испытание для многообещающих воинов. Победа над опасным, порочным созданием вроде Ворлуса показывает собранность, мужество и решимость, которых она требует, прежде чем обучать продвинутым боевым навыкам или помогать в ковке особого оружия.",al={"why kill vorlus","elanaria quest reason","purpose of vorlus vilehoof quest","зачем убивать ворлуса","причина задания эланарии","смысл задания ворлус подлое копыто"}},{q="Где находится скрытый лунный колодец?",a="Лунный колодец спрятан среди хребтов к юго-востоку от Обители Бен'этиль. Чтобы добраться до него, нужно найти неприметную горную тропу, освещенную факелами, сразу за лагерем фурболгов из племени Гнилой Сосны к востоку от кургана.",al={"vorlus location","how to find vorlus","hidden moonwell path","где ворлус","как найти ворлуса","тропа к лунному колодцу"}},{q="Что такое лунный колодец и почему важно его присутствие?",a="Лунные колодцы — священные чаши с благословенной водой, в которых течет свет Элуны и которые поддерживают жизненную силу природы. Если демонический сатир вроде Ворлуса купается в одном из них, это считается прямым осквернением веры кальдораев и опасным источником порчи в Тельдрассиле.",al={"why are moonwells important","moonwell desecration","night elf moonwells","почему важны лунные колодцы","осквернение лунного колодца","лунные колодцы ночных эльфов"}},{q="Что будет после победы над Ворлусом Подлым Копытом?",a="Отрубленный рог Ворлуса, принесенный Эланарии, удовлетворит ее и подтвердит готовность воина. Затем она направит воина на поиски легендарного Оружия из элунита, начав с поисков Тени Элуры.",al={"next quest after vorlus","what happens next","shade of elura quest","следующее задание после ворлуса","что дальше","задание тень элуры"}},{q="Есть ли в Тельдрассиле другие сатиры?",a="Да. Хотя Тельдрассил относительно молод, сатиры скрываются в таких местах, как Пещера Бесов, и в разрозненных оскверненных лощинах, постоянно стремясь заразить Мировое Древо демонической порчей.",al={"satyrs on teldrassil","teldrassil satyr threat","сатиры в тельдрассиле","угроза сатиров в тельдрассиле"}}},fp="15,245,17.315.0,26.388.0,17.363.1,23.199.0,45.261.0,37.222.0,53.271.0,43.217.1,37.178.0"}
P.entries["quest:1685"] = {n="Приглашение Гакина",s="Приглашение, которое Ремен Маркот передает перспективным чернокнижникам Альянса от имени Гакина Темнопряда. Оно направляет начинающих практиков в склепы под «Забитым ягненком» в Квартале магов Штормграда для следующего этапа темного оккультного обучения.",h="Приглашение, которое Ремен Маркот передает перспективным чернокнижникам Альянса от имени Гакина Темнопряда.",kw={"demonology","gakin the darkbinder","mage quarter","remen marcot","slaughtered lamb","stormwind","voidwalker","warlock","демонология","гакин темнопряд","квартал магов","ремен маркот","забитый ягненок","штормград","демон бездны","чернокнижник"},ang={["class:Warlock"]="Это приглашение знаменует ваш переход от салонных фокусов и мелких бесов к испытаниям, необходимым, чтобы подчинить демона Бездны, который защитит вас в бою.",["faction:Alliance"]="Даже в самом сердце Штормграда Альянс терпит подземный заговор мастеров теней, чья изощренная магия Скверны дает преимущество перед врагами."},sec={{t="Осторожное послание",b="Демонология строго запрещена во всех цивилизованных районах Штормграда, однако темные искусства живут прямо под носом у городской стражи. Когда чернокнижник проявляет достаточное мастерство в обращении со своими первыми бесами, весть тихо доходит до старших практиков. Ремен Маркот передает послание с намеренной осторожностью, призывая посвященных хранить место встречи в тайне и спуститься в сумрачные подземелья под Кварталом магов."},{t="Склепы «Забитого ягненка»",b="За скромным фасадом таверны «Забитый ягненок» скрывается сеть сырых подвалов и тайных катакомб. Здесь, вдали от любопытных магов Кирин-Тора и инквизиторов Собора Света, Гакин Темнопряд руководит обучением чернокнижников Штормграда. Приглашение открывает путь к управлению демоном Бездны — обряду, требующему опасных краденых реагентов и рискованных кругов призыва."}},faq={{q="Почему Гакин Темнопряд призывает чернокнижников?",a="Гакин призывает начинающих чернокнижников, когда они достигают подходящего уровня опыта. Он считает необученных чернокнижников обузой, склонной терять голову, и стремится научить их сложному ритуалу подчинения демона Бездны.",al={"why gakin summons","what is gakin summons for","voidwalker quest start","зачем гакин зовет","для чего приглашение гакина","начало задания демона бездны"}},{q="Где находится Гакин Темнопряд?",a="Гакин скрывается в глубоких подземных склепах под «Забитым ягненком» — таверной в Квартале магов Штормграда.",al={"where is gakin","gakin location","slaughtered lamb basement","где гакин","расположение гакина","подвал забитого ягненка"}},{q="Кто такой Ремен Маркот?",a="Ремен Маркот — соратник штормградского ковена чернокнижников. Он выслеживает в городе перспективных кандидатов, чтобы незаметно направить их в тайное убежище Гакина.",al={"remen marcot","who starts gakin summons","ремен маркот","кто выдает приглашение гакина"}},{q="Почему место нужно хранить в тайне?",a="Магия Скверны и призыв демонов запрещены в Королевстве Штормград. Если Серебряная Длань, Собор Света или городская стража обнаружат их, это грозит тюрьмой или казнью.",al={"why secret","warlock secrecy stormwind","почему тайна","тайна чернокнижников штормград"}},{q="Что происходит после ответа на приглашение Гакина?",a="После доклада Гакину он поручает чернокнижнику отправиться на Тыквенное поле Бреквеллов в Элвиннском лесу и забрать у Сурены Каледон кровавое ожерелье — важный компонент ритуала подчинения демона Бездны.",al={"next quest after gakins summons","what happens next","следующее задание после приглашения гакина","что дальше"}},{q="Может ли получить это приглашение не чернокнижник?",a="Нет. Приглашение предназначено строго для чернокнижников, освоивших своего базового беса и нуждающихся в продвинутом тайном обучении.",al={"can mages get this","who can do gakins summons","могут ли маги получить","кто может взять приглашение гакина"}}},fp="15,265,18.434.0,34.392.0,46.241.0,38.128.0,20.174.0,37.188.0,43.219.1,38.135.0"}
P.entries["quest:1686"] = {n="Тень Элуры",s="«Тень Элуры» — начальное посвящение молодых воинов-ночных эльфов, которое проводит учитель воинов Эланария в Дарнассе. Воину предстоит нырнуть в воды у Аубердина, упокоить призрак измученного морского капитана и поднять ящики с редкой рудой элунита. Эти материалы — основа для создания особого боевого оружия.",h="«Тень Элуры» — начальное посвящение молодых воинов-ночных эльфов, которое проводит учитель воинов Эланария в...",kw={"auberdine","darkshore","darnassus","elanaria","elunite ore","elura","shade of elura","smith mathiel","weapons of elunite","аубердин","темные берега","дарнасс","эланария","руда элунита","элура","тень элуры","кузнец матиль","оружие из элунита"},ang={["class:Warrior"]="Это задание — важный шаг в карьере воина-ночного эльфа: оно проверяет выносливость под водой и боевую дисциплину, чтобы заслужить выкованное оружие из элунита.",["profession:Blacksmithing"]="Подъем затонувшего элунита показывает уникальные металлургические традиции ночных эльфов, создающих мощное оружие из благословенных материалов.",["race:NightElf"]="Упокоение тени Элуры чтит сородича-кальдорая, чье безграничное чувство долга на поколения заточило ее под волнами."},sec={{t="Вечный дозор капитана",b="Давным-давно судно с грузом редкой элунитовой руды село на острые прибрежные скалы у аубердинского маяка. В отчаянии и из непоколебимой верности долгу капитан корабля Элура прокляла собственную душу. Привязанная к обломкам под водой, ее тень остается на морском дне, охраняя потерянный груз от всякого, кто посмеет его потревожить."},{t="Оружие из элунита",b="Чтобы молодой воин-ночной эльф обрел свое первое настоящее выкованное оружие, нужны и боевое мастерство, и уважение к павшим сородичам. Учитель Эланария посылает начинающих бойцов в холодный прибой Темных берегов не только ради металла, но и чтобы победить Тень Элуры и забрать ее медальон. Упокоение Элуры освобождает проклятого капитана от ее бдения и дает сырую руду, нужную для кузни Кузнеца Матиль."}},faq={{q="Кто такая Тень Элуры?",a="Элура была капитаном эльфийского корабля, разбившегося на коварном мелководье у аубердинского маяка. Не оставив свой долг, она при жизни или в смерти прокляла себя, чтобы вечно бдительно охранять затонувший груз элунитовой руды.",al={"shade of elura lore","who is elura","captain elura","предание о тени элуры","кто такая элура","капитан элура"}},{q="Почему Эланария посылает воинов к Элуре?",a="Эланария стремится и упокоить измученный дух Элуры, и добыть затонувшую руду элунита. Победа над капитаном и добыча ее медальона доказывают доблесть молодого воина и обеспечивают сырье для выковки превосходного оружия.",al={"why do we kill elura","elanaria quest purpose","зачем убивать элуру","цель задания эланарии"}},{q="Где произошло крушение?",a="Обломки лежат под водой у побережья Аубердина на Темных берегах, возле маяка и чуть южнее главных пристаней гавани, рассыпанные по морскому дну.",al={"where is the shipwreck","elura ship location","где кораблекрушение","где корабль элуры"}},{q="Для чего нужна руда элунита?",a="Элунит — редкая руда, ценимая кузнецами ночных эльфов. В этом испытании поднятые ящики относят кузнецу Кузнецу Матиль в Дарнасс, чтобы выковать особое боевое оружие для перспективных воинов.",al={"what is elunite","elunite ore purpose","что такое элунит","для чего руда элунита"}},{q="Вредит ли победа над тенью Элуре навсегда?",a="Победа над ее тенью разрывает наложенное на себя проклятие, привязывающее ее дух к морскому дну. Как отмечает Эланария, победа над ней в бою приносит капитану заслуженный покой после столетий холодного призрачного бдения.",al={"did elura die","is elura saved","умерла ли элура","спасена ли элура"}},{q="Кто выковывает оружие, когда руда собрана?",a="Получив руду и медальон, Эланария направляет воина к Кузнецу Матиль на Террасе Воинов в Дарнассе, который превращает металл в превосходное оружие.",al={"who makes the elunite weapon","next quest after elura","кто делает оружие из элунита","следующее задание после элуры"}}},fp="18,370,25.362.0,18.423.0,26.254.0,44.248.0,27.157.0,29.206.0,48.209.0,48.173.0"}
P.entries["quest:1688"] = {n="Сурена Каледон",s="Сурена Каледон — учебное задание чернокнижников от Гакина Темнопряда в тайном подвале под «Забитым ягненком» в Штормграде. Гакин поручает начинающему чернокнижнику выследить его бывшую ученицу, которая предала его и сбежала к Братству Справедливости, и вернуть ценное кровавое ожерелье.",h="Сурена Каледон — учебное задание чернокнижников от Гакина Темнопряда в тайном подвале под «Забитым ягненком»...",kw={"bloodstone choker","brackwell pumpkin patch","defias","erlan drudgemoor","gakin the darkbinder","slaughtered lamb","surena caledon","voidwalker","кровавое ожерелье","тыквенное поле бреквеллов","братство справедливости","эрлан драджмур","гакин темнопряд","забитый ягненок","сурена каледон","демон бездны"},ang={["class:Warlock"]="Охота на Сурену Каледон — испытание для чернокнижника Альянса, показывающее, что предательство имеет смертельную цену, а сентиментальной привязанности нет места в темных искусствах.",["race:Human"]="Бегство Сурены показывает неослабевающую притягательность Братства Справедливости для недовольных жителей королевства Штормград."},sec={{t="Озлобленный учитель",b="Под таверной «Забитый ягненок» в Квартале магов Гакин Темнопряд обучает новичков запретному искусству призыва Скверны. Но в прошлом Гакин ошибался в людях. Прежде чем взять новых учеников, он обучал молодую женщину по имени Сурена Каледон, восхищаясь и ее скрытым магическим талантом, и ее красотой. Однако Сурена бросила учебу и лишилась расположения Гакина, сбежав из города к Братству Справедливости вместе со своим возлюбленным Эрланом Драджмуром."},{t="Украденный кровавый камень",b="Гакину мало дела до судьбы девушки после ее ухода, но он не желает расставаться с ценным кровавым ожерельем, которое подарил ей во время обучения. Он отправляет своего новейшего ученика на юго-восток, на Тыквенное поле Бреквеллов в Элвиннском лесу — ферму, захваченную бандитами из Братства Справедливости, — с прямым приказом забрать драгоценность у Сурены любой ценой. Возвращенный кровавый камень служит магическим катализатором для следующего испытания ученика: призыва и подчинения демона Бездны."}},faq={{q="Кто такая Сурена Каледон?",a="Сурена Каледон была ученицей-чернокнижницей Гакина Темнопряда в Штормграде. Наделенная природным талантом, она заслужила расположение и подарки Гакина, а затем бросила свое ремесло и сбежала с бандитом из Братства Справедливости по имени Эрлан Драджмур.",al={"surena lore","who is surena","surena caledon backstory","предание о сурене","кто такая сурена","история сурены каледон"}},{q="Почему Гакин хочет вернуть ее ожерелье?",a="В ожерелье вставлен ценный кровавый камень, который Гакин подарил Сурене во время ее обучения. Помимо обиды за кражу и предательство, Гакину нужен темный резонанс камня как ритуальный реагент, чтобы помочь новому ученику подчинить демона Бездны.",al={"why get the choker","bloodstone choker importance","зачем забирать ожерелье","значение кровавого ожерелья"}},{q="Где можно найти Сурену Каледон?",a="Сурену можно найти укрывшейся вместе с ее спутниками из Братства Справедливости на Тыквенном поле Бреквеллов — заброшенной ферме на юго-востоке Элвиннского леса.",al={"surena location","where is surena","where is the pumpkin patch","где сурена","местонахождение сурены","где тыквенное поле"}},{q="Что происходит после возвращения ожерелья?",a="Возвращение кровавого ожерелья Гакину завершает это испытание и открывает следующее задание: войти в круг призыва в склепах под «Забитым ягненком» и подчинить демона Бездны из Круговерти Пустоты.",al={"what comes next","next quest after surena","что дальше","следующее задание после сурены"}},{q="Кто такой Эрлан Драджмур?",a="Эрлан Драджмур — разбойник из Братства Справедливости, который соблазнил Сурену Каледон и убедил ее бросить обучение чернокнижника и бежать из Штормграда, чтобы жить среди бандитов.",al={"erlan lore","who is erlan drudgemoor","предание об эрлане","кто такой эрлан драджмур"}},{q="Испытывает ли Гакин сожаление о судьбе Сурены?",a="Нисколько. Гакин открыто заявляет, что ее жизнь для него больше ничего не значит, и холодно замечает, что хотя и жаль тратить магический талант впустую, ее предательство делает ее уничтожение необходимым.",al={"does gakin care","gakin reaction to surena","волнует ли гакина","реакция гакина на сурену"}}},fp="14,305,15.455.0,21.499.1,22.227.0,36.250.0,34.148.0,41.205.1,24.189.0,47.190.0"}
P.entries["quest:1689"] = {n="Связывание",s="Связывание — заключительное испытание в начальном обучении чернокнижника Альянса связыванию демона Бездны в Штормграде. Под руководством Гакина Темнопряда начинающий призыватель с помощью найденного Колье кровавого камня втягивает исчадие бездны в тайный подземный круг и подчиняет его силой.",h="Связывание — заключительное испытание в начальном обучении чернокнижника Альянса связыванию демона Бездны в...",kw={"binding","bloodstone choker","gakin the darkbinder","mage quarter","slaughtered lamb","stormwind","summoning circle","voidwalker","связывание","колье кровавого камня","гакин темнопряд","квартал магов","забитый ягненок","штормград","круг призыва","тенеходец"},ang={["class:Warlock"]="Этот обряд посвящения дает чернокнижнику главного защитного прислужника и знаменует переход от опрометчивого дилетанта к повелителю сил иных измерений.",["faction:Alliance"]="Хотя Альянс отстаивает Свет и магический порядок, прагматичные лидеры закрывают глаза на темных практиков под Кварталом магов, признавая необходимость их мрачных искусств в опасные времена.",["race:Gnome"]="Гномы-чернокнижники привносят в темный призыв клиническое любопытство и относятся к подчинению существ Бездны как к точному метафизическому эксперименту под руководством Гакина.",["race:Human"]="Людям-чернокнижникам приходится выдерживать пристальное внимание духовенства Штормграда: они овладевают опасными существами в тени, скрывая свою силу от города наверху."},sec={{t="Подчинение в склепах",b="Под «Забитым ягненком» в Квартале магов Штормграда тянется сеть забытых катакомб, вдали от бдительных глаз Серебряной Длани и судей Кирин-Тора. Здесь Гакин Темнопряд учит новичков: овладеть темными искусствами — значит не просто направлять потоки магии, но и полностью подчинять себе потусторонние существа. Вернув у Сурены Каледон украденное колье кровавого камня Гакина, чернокнижник получает задание вызвать демона-тенеходца прямо в круг призыва под таверной."},{t="Подчинение воли Бездны",b="С тенеходцем нельзя договориться — его нужно сломить. Используя скрытую силу колье кровавого камня, призыватель разрывает пространство и втягивает существо тени в мир смертных. Чтобы завершить договор, чернокнижник должен физически и магически избивать существо, пока его воля не сломится, доказав свою власть. После победы сущность тенеходца оказывается связана с призывателем, и чернокнижник получает прочного теневого защитника, способного выдерживать жестокие удары в грядущих битвах."}},faq={{q="Где находится круг призыва?",a="Круг призыва находится глубоко в катакомбах под «Забитым ягненком» в Квартале магов Штормграда. От Гакина Темнопряда спуститесь по лестнице в подземные ходы, пока не достигнете самой нижней комнаты со светящейся фиолетовой руной ритуала на каменном полу.",al={"summoning circle location","where do i summon the voidwalker","where is the circle","где круг призыва","где призвать тенеходца","где находится круг"}},{q="Кто такой Гакин Темнопряд?",a="Гакин Темнопряд — наставник чернокнижников, тайно работающий под таверной «Забитый ягненок» в Штормграде. Он втайне обучает перспективных людей и гномов призыву, подчинению и управлению демонами и существами Бездны, не привлекая внимания городской стражи и церковных властей.",al={"who is gakin","gakin the darkbinder lore","gakin","кто такой гакин","гакин темнопряд предания","гакин"}},{q="Для чего нужно колье кровавого камня?",a="Колье кровавого камня — магический талисман, ранее украденный Суреной Каледон. Наполненный сосредоточенной магической силой, он служит катализатором, позволяющим начинающему чернокнижнику пробить завесу и вытянуть непокорного тенеходца в отведенный круг призыва.",al={"bloodstone choker use","why do i need the choker","choker","колье кровавого камня применение","зачем нужно колье","колье"}},{q="Почему чернокнижники должны сражаться со своими демонами, чтобы подчинить их?",a="Внепространственные существа, такие как демоны и создания Бездны, не служат смертным хозяевам добровольно. Чернокнижник должен доказать свое превосходство в силе и железную волю, физически или магически сломив существо в бою, прежде чем установить с ним постоянную связь подчинения.",al={"why fight the voidwalker","why subdue demons","demon subjugation","зачем драться с тенеходцем","зачем подчинять демонов","подчинение демонов"}},{q="Что происходит после завершения ритуала?",a="Когда существо побеждено, а колье возвращено Гакину, чернокнижник получает знание и ритуальную технику, необходимые для призыва верного тенеходца и управления им, чтобы он защищал его в странствиях.",al={"what reward do i get","voidwalker spell","after the binding","какая награда","заклинание тенеходца","после связывания"}},{q="Почему этот ритуал проводят тайно под таверной?",a="Демонология и магия Бездны — строжайшее табу, к которому Церковь Священного Света и маги Альянса относятся с сильной враждебностью. Чернокнижники Штормграда работают в скрытых подвалах и катакомбах, чтобы практиковать запретные искусства вдали от властей.",al={"why hidden under tavern","is fel magic illegal","slaughtered lamb basement","почему скрыто под таверной","запрещена ли магия скверны","подвал забитого ягненка"}}},fp="11,290,25.543.0,28.501.0,38.288.0,28.301.0,39.261.0,56.262.0,41.203.0,56.266.0"}
P.entries["quest:169"] = {n="Розыск: Гат'Илзогг",kw={"blackrock","bounty","gath'ilzogg","lakeshire","magistrate solomon","redridge","stonewatch","wanted poster","черная гора","награда","гат'илзогг","приозерье","мировой судья соломон","красногорье","каменная стража","объявление о розыске"},ang={["class:Warrior"]="Прорыв на вершину Крепости Каменной Стражи означает схватку с закаленными воинами-ветеранами и грубой силой передового командования Темной Орды.",["faction:Alliance"]="Убийство Гат'Илзогга устраняет одну из самых непосредственных военных угроз восточным границам королевства и дает жителям Приозерья жизненно важную передышку.",["race:Human"]="Для жителей Штормграда Крепость Каменной Стражи была с трудом завоеванным укреплением; резня невинных, устроенная Гат'Илзоггом при ее падении, делает эту награду делом горькой мести."},sec={{t="The Warlord of Stonewatch",b="Гат'Илзогг — жестокий командир, руководящий набегами клана Черной горы по всему Красногорью. По его приказу орки штурмом взяли Крепость Каменной Стражи, превратив бывший оплот людей в укрепленный плацдарм для нападений на окрестные поселения. С высочайших стен крепости он замышляет новые вторжения в Приозерье, грозя отрезать Красногорье от остального королевства."},{t="Город на грани",b="Поскольку королевская армия Штормграда не шлет подкрепления в приграничные области, Мировой судья Соломон взял дело в свои руки. У поселения Приозерье просто не хватает солдат, чтобы силой отбить Крепость Каменной Стражи. Объявив публичную награду за Гат'Илзогга, Соломон стремится обезглавить руководство клана Черной горы и начать первый этап возвращения крепости короне."}},faq={{q="Кто такой Гат'Илзогг?",a="Gath'Ilzogg is an orc warlord leading the Blackrock clan forces occupying Stonewatch. He directed the conquest of the keep and is responsible for frequent deadly raids against the human settlers of Lakeshire.",al={"gath'ilzogg lore","who is gathilzogg","blackrock leader redridge","гат'илзогг предания","кто такой гатилзогг","предводитель черной горы красногорье"}},{q="Где можно найти Гат'Илзогга?",a="Он засел на самой вершине Крепости Каменной Стражи в восточных скалах Красногорья. Его усиленно охраняют бойцы и телохранители клана Черной горы.",al={"gath'ilzogg location","where is gathilzogg","stonewatch boss location","гат'илзогг местонахождение","где гатилзогг","босс каменной стражи"}},{q="Почему Мировой судья Соломон объявляет награду, а не посылает солдат?",a="Местная стража Приозерья измотана до предела, а корона в Штормграде не прислала нужных войск для помощи региону. Мировому судье Соломону приходится полагаться на наемников и независимых искателей приключений в борьбе с серьезными угрозами.",al={"why a bounty","where are stormwind soldiers","lakeshire guard help","почему награда","где солдаты штормграда","помощь стражи приозерья"}},{q="Что произойдет после убийства Гат'Илзогга?",a="Мировой судья Соломон видит в смерти полководца важнейший первый шаг к избавлению от орочьего нашествия и возвращению Крепости Каменной Стражи Королевству Штормград, хотя присутствие клана Черной горы в регионе остается значительным.",al={"is stonewatch retaken","after gath'ilzogg","отбита ли каменная стража","после гат'илзогга"}},{q="Почему орки клана Черной горы захватили Крепость Каменной Стражи?",a="Клан Черной горы использует Крепость Каменной Стражи как укрепленную передовую базу. Расположенная высоко в горах над Красногорьем, она дает им стратегический контроль над перевалами и прямую точку для набегов на поселения людей.",al={"why are blackrock in redridge","why stonewatch taken","почему черная гора в красногорье","почему захвачена каменная стража"}},{q="Кто получает награду после смерти Гат'Илзогга?",a="Награду нужно сдать лично Мировому судье Соломону в ратуше Приозерья, предъявив голову Гат'Илзогга как неоспоримое доказательство его гибели.",al={"who to turn in gathilzogg","gathilzogg quest turn in","кому сдать гатилзогга","сдача задания гатилзогг"}}},fp="19,281,25.414.0,26.396.0,19.208.0,31.173.0,72.237.0,41.240.0,50.228.0,47.154.0"}
P.entries["quest:1692"] = {n="Кузнец Матиль",s="Кузнец Матиль — важное задание воинов в Дарнассе, знаменующее переход от сырья к выкованному оружию. Добыв священную элунитовую руду из потерпевшего крушение корабля у Аубердина, начинающий воин относит ее мастеру-кузнецу Матилю. Тот соглашается сделать из благословенного металла оружие, достойное защиты кальдораев.",h="Кузнец Матиль — важное задание воинов в Дарнассе, знаменующее переход от сырья к выкованному оружию.",kw={"warrior's terrace","darnassus","elanaria","elunite","mathiel","smith","warrior","терраса воинов","дарнасс","эланария","элунит","матиль","кузнец","воин"},ang={["class:Warrior"]="Для юных воинов-кальдораев принести элунит Матилю — обряд посвящения: простые учебные клинки меняются на особое оружие, благословленное Богиней Луны.",["profession:Blacksmithing"]="Благоговение Матиля перед элунитом показывает, как кузнецы-кальдораи вплетают священные благословения в свое ремесло, а не полагаются лишь на жар и молот.",["race:NightElf"]="Работа с элунитовой рудой соединяет мастерство ночных эльфов со священной преданностью Элуне, показывая, что воинская сила и божественная вера идут рука об руку."},sec={{t="Священная доставка",b="Достав элунитовую руду из населенного призраками разбитого корабля у Аубердина и сохранив ее с помощью наставницы воинов Эланарии, юные воины-ночные эльфы отправляются через Террасу Воинов Дарнасса. Эланария аккуратно упаковывает руду в прочный ящик и велит новичку найти Матиля, одного из лучших кузнецов столицы, чтобы тот выковал оружие, достойное их воинского призвания."},{t="Благословение элунита",b="Матиль видит в работе у горна не просто ручной труд, а благочестивое ремесло. Элунит — не обычная руда: он несет священное благословение Богини Луны, Элуны. Получив ящик, Матиль охотно берется за дело, считая великой честью выковать из такого святого металла оружие для защиты юных ветвей Тельдрассила."}},faq={{q="Кто такой Кузнец Матиль?",a="Матиль — искусный кузнец-ночной эльф, работающий на Террасе Воинов в Дарнассе. Он изготавливает особое вооружение и берет индивидуальные заказы на ковку для защитников Дарнасса.",al={"who is mathiel","blacksmith mathiel","where is mathiel","кто такой матиль","кузнец матиль","где матиль"}},{q="Чем особенна элунитовая руда?",a="Элунит — редкий металл, почитаемый ночными эльфами, поскольку он благословлен самой Элуной. Кузнецы вроде Матиля считают работу с ним высокой честью и используют его священные свойства для создания могучего оружия.",al={"what is elunite","is elunite magical","elunite lore","что такое элунит","магический ли элунит","элунит предания"}},{q="Кто посылает вас к Матилю?",a="Эланария, известная наставница воинов, живущая на Террасе Воинов в Дарнассе, упаковывает добытую вами руду и велит найти Матиля прямо через террасу.",al={"who gives smith mathiel quest","quest giver smith mathiel","кто дает задание кузнец матиль","персонаж, выдающий задание кузнец матиль"}},{q="Это задание доступно только воинам?",a="Да. Это задание — часть цепочки заданий воинов 10 уровня, призванной снабдить юных воинов первым специализированным боевым оружием.",al={"warrior only","can other classes do smith mathiel","только для воинов","могут ли другие классы выполнить кузнец матиль"}},{q="Где в Дарнассе можно найти Матиля?",a="Матиль работает на Террасе Воинов в Дарнассе, к югу, напротив Эланарии через строение.",al={"mathiel location","find mathiel","где матиль","найти матиля"}},{q="Что происходит после доставки руды Матилю?",a="Матиль начинает ковать элунитовую руду, сразу предлагая следующее задание, где вы выбираете, какое оружие из элунита лучше подходит вашему стилю боя.",al={"what comes after smith mathiel","next quest after smith mathiel","что дальше после кузнеца матиля","следующее задание после кузнеца матиля"}}},fp="13,330,17.400.0,23.351.0,21.180.0,34.209.0,25.167.0,41.143.0,40.107.0,50.170.0"}
P.entries["quest:1693"] = {n="Оружие из элунита",s="«Оружие из элунита» — завершение раннего испытания для воинов-ночных эльфов в Дарнассе. Добыв необработанную руду, благословленную Элуной, воин приносит ее искусному кузнецу Матиль, чтобы из нее выковали оружие, достойное защитника Калимдора.",h="«Оружие из элунита» — завершение раннего испытания для воинов-ночных эльфов в Дарнассе.",kw={"darnassus","elune","elunite","kaldorei","mathiel","teldrassil","warrior","weaponsmith","дарнасс","элуна","элунит","кальдораи","матиль","тельдрассил","воин","оружейник"},ang={["class:Warrior"]="Это задание — важный ранний обряд воинской службы для молодых воинов-кальдораев, награждающий их усердие надежным оружием, благословленным Элуной.",["profession:Blacksmithing"]="Мастерство Кузнеца Матиль показывает тонкий баланс между обычной обработкой металла и работой с божественными материалами вроде элунита.",["race:NightElf"]="Ковка элунита отражает то, как общество ночных эльфов вплетает почитание Богини Луны прямо в практическое ремесло войны и обороны."},sec={{t="Священная кузница",b="Воины-ночные эльфы несут священный долг защищать Тельдрассил и народ кальдораев. Тех, кто подает надежды, посылают не за простой сталью, а за элунитом — минералом, наделенным благодатью Богини Луны. Для ковки такого оружия нужен мастер, который разбирается и в кузнечном деле, и в почтении, которого требуют дары Элуны."},{t="Мастерство Матиль",b="Кузнец Матиль работает в столице, Дарнассе, и гордится тем, что превращает благословленную руду в боевое оружие. Для Матиль работа с элунитом — не обычная металлургия, а честь. Получив руду, он создает набор орудий, подходящих стилю воина, и награждает его за службу оружием, благословленным его богиней."}},faq={{q="Для чего нужно это задание?",a="Это задание завершает раннее испытание воинов в Дарнассе. Добыв редкую элунитовую руду, воин приносит ее Кузнецу Матиль, который выковывает надежное оружие, наполненное сущностью Элуны, чтобы помочь воину в странствиях по Калимдору.",al={"weapons of elunite quest","why do this quest","warrior level 10 darnassus","задание оружие из элунита","зачем выполнять это задание","воин 10 уровень дарнасс"}},{q="Кто такой Матиль?",a="Матиль — искусный ночной эльф, кузнец-оружейник и бронник, живущий в Дарнассе. Он обладает особыми знаниями, нужными, чтобы выковывать из элунитовой руды точно сбалансированное вооружение для растущего числа защитников города.",al={"smith mathiel","who is mathiel","darnassus smith","кузнец матиль","кто такой матиль","кузнец дарнасса"}},{q="Что такое элунит?",a="Элунит — редкий минерал, священный для ночных эльфов. Считается, что он пропитан сиянием и благосклонностью Богини Луны, Элуны. Из-за его божественной природы мастера считают ковку из него оружия торжественной честью.",al={"what is elunite ore","elunite lore","что такое элунитовая руда","предания об элуните"}},{q="Кто может взять это задание?",a="Это задание предназначено только для воинов Альянса, обучающихся в окрестностях Дарнасса, которые выполнили предварительные задания по поиску и сбору элунита для Кузнеца Матиль.",al={"who gets weapons of elunite","is this warrior only","кто получает оружие из элунита","только для воинов"}},{q="Где происходит это задание?",a="Задание сдается непосредственно Кузнецу Матиль в столице ночных эльфов, Дарнассе, расположенном высоко в ветвях Мирового Древа, Тельдрассила.",al={"weapons of elunite location","where is mathiel","оружие из элунита местонахождение","где матиль"}},{q="Почему Матиль благодарит искателя приключений?",a="Матиль считает работу с элунитом и священной честью, и личным удовольствием. Обрабатывать руду, связанную с Элуной, — привилегия, доступная немногим кузнецам, поэтому подношение воина — благо и для мастера.",al={"why is mathiel honored","mathiel dialogue","почему матиль польщен","диалог матиль"}}},fp="18,261,14.349.0,15.350.0,34.255.0,15.215.0,16.223.0,29.168.0,33.151.0,38.211.0"}
P.entries["quest:1698"] = {n="Йорус Ячменовар",s="«Йорус Ячменовар» — призыв для воинов Альянса, направляющий опытных бойцов из Штормграда в пограничье Красногорья. Это задание выдают наставники воинов в столицах Альянса: оно отправляет честолюбивых бойцов к необычному дворфу, бросающему смертельный вызов в Таверне Приозерья.",h="«Йорус Ячменовар» — призыв для воинов Альянса, направляющий опытных бойцов из Штормграда в пограничье...",kw={"kelv sternhammer","lakeshire","lakeshire inn","redridge","rethban","stormwind","warrior","wu shen","yorus barleybrew","кельв стернхаммер","приозерье","таверна приозерья","красногорье","ретбан","штормград","воин","ву шен","йорус ячменовар"},ang={["class:Warrior"]="Это задание — важный обряд посвящения для воинов Альянса: от вводных упражнений они переходят к опасным испытаниям на границе Красногорья.",["faction:Alliance"]="Вызов Ячменовара приводит способных бойцов-новобранцев прямо в Приозерье — уязвимое поселение, которое сейчас осаждают гноллы и орки Черной Горы."},sec={{t="Призыв к сильным",b="Наставники воинов в столицах Альянса, в том числе Кельв Стернхаммер, Ву Шен и Дарнат Песнь Клинка, внимательно следят за бойцами, переросшими простые упражнения. Когда ученик доказывает свою доблесть, примерно к двадцатому году, мастера передают весть о дворфе по имени Йорус Ячменовар. Вместо обычного военного приказа Ячменовар объявил открытое пари и испытание оружием для любого воина Альянса, достаточно смелого, чтобы откликнуться."},{t="Ожидание в Приозерье",b="Ячменовар обосновался в таверне Приозерья, прямо на передовой борьбы Красногорья с наступающими гноллами и орками Черной Горы. Те, кто находит его, видят хвастливого дворфа с кружкой в руке, готового оценить любого, кто заявляет о настоящем боевом духе. Для воинов, желающих проявить себя за пределами безопасных мощеных улиц столицы, его испытание — посвящение в более суровые битвы на границе."}},faq={{q="Кто такой Йорус Ячменовар?",a="Йорус Ячменовар — дворф из известного пивоваренного клана Ячменоваров, бросивший воинам Альянса открытый боевой вызов. Находясь в Таверне Приозерья, он испытывает бойцов, считающих себя готовыми к суровому пограничью Красногорья.",al={"yorus barleybrew","who is barleybrew","dwarf in lakeshire inn","йорус ячменовар","кто такой ячменовар","дворф в таверне приозерья"}},{q="Почему наставники посылают воинов в Красногорье?",a="Когда воин достигает достаточного мастерства в Штормграде, местные мастера оружия направляют его к практическому бою с высокими ставками. Йорус Ячменовар предлагает испытание, которое заставляет учеников выйти за городские стены и проявить выносливость перед настоящими опасностями дикой местности.",al={"why lakeshire","warrior trainer quest redridge","why go to yorus","почему приозерье","задание наставника воинов красногорье","зачем идти к йорусу"}},{q="Где найти Йоруса Ячменовара?",a="Его можно найти в Таверне Приозерья, в городке Приозерье в Красногорье, к востоку от Элвиннского леса.",al={"yorus barleybrew location","where is yorus","find barleybrew","йорус ячменовар местонахождение","где йорус","найти ячменовара"}},{q="Что происходит после разговора с Йорусом?",a="Разговор с Йорусом начинает его боевое испытание: он предлагает вам пройти «Ретбанский вызов» — опасное состязание против свирепых зверей и гноллов, обитающих в окрестных холмах.",al={"after yorus","barleybrew trial","next quest","после йоруса","испытание ячменовара","следующее задание"}},{q="Кто выдает задание найти его?",a="Задание выдают различные наставники воинов в столицах Альянса, в том числе Кельв Стернхаммер, Ву Шен и Дарнат Песнь Клинка, когда воин доказал базовую компетентность.",al={"who gives quest","quest starter","trainers for yorus","кто дает задание","начало задания","наставники для йоруса"}},{q="Открыто ли это испытание для других классов, кроме воинов?",a="Нет. Вызов создан специально для воинов. Йорус Ячменовар предлагает свое испытание только бойцам, полагающимся исключительно на физическую выносливость и оружие.",al={"can paladins do this","is this warrior only","class restrictions","могут ли паладины","только для воинов","ограничения по классам"}}},fp="16,295,20.458.0,20.457.0,24.263.0,46.263.0,34.142.0,39.185.0,33.181.0,50.172.0"}
P.entries["quest:1699"] = {n="Ретбанский вызов",s="«Ретбанский вызов» — необычное испытание на выносливость, придуманное дворфом-пивоваром Йорусом Ячменоваром в Приозерье. Участники должны выпить крепкий глоток огненного «Кипятка Ячменоваров» — семейного напитка — и бегом добраться на север до населенных гноллами Пещер Ретбана и вернуться назад меньше чем за час.",h="«Ретбанский вызов» — необычное испытание на выносливость, придуманное дворфом-пивоваром Йорусом Ячменоваром в...",kw={"barleybrew scalder","gnolls","lakeshire","redridge","rethban caverns","rethban gauntlet","timed run","yorus barleybrew","кипяток ячменоваров","гноллы","приозерье","красногорье","пещеры ретбана","ретбанский вызов","забег на время","йорус ячменовар"},ang={["faction:Alliance"]="Пока Приозерье бьется под угрозой набегов гноллов, прохождение испытания помогает проредить вражеские патрули возле северных пещер.",["race:Dwarf"]="Дворфам придется по душе буйное представление Йоруса о веселье: крепкий семейный напиток и опасные горные забеги."},sec={{t="Дворфийский вызов",b="В Приозерье, где в таверне обычно царят мрачные разговоры о набегах гноллов и пропавших стражниках, дворф Йорус Ячменовар предлагает по-настоящему дворфийское развлечение. Его вызов, «Ретбанский вызов», проверяет доблесть, скорость и печень искателя приключений одновременно. Участники должны выпить глоток фирменного семейного напитка, «Кипятка Ячменоваров», прямо перед тем, как пешком отправиться к северным предгорьям."},{t="Бег по диким холмам",b="Это испытание куда опаснее простого пьяного забега. Между Приозерьем и целью лежат земли Красногорья, кишащие агрессивными гноллами Красногорья. Чтобы пройти испытание, бегуну нужно прорваться через стаи или проскользнуть мимо них, добраться до первой развилки в темных туннелях Пещер Ретбана и успеть вернуться к Йорусу за час — и все это под ошеломляющим действием огненного дворфийского напитка."}},faq={{q="Кто выдает «Ретбанский вызов»?",a="Йорус Ячменовар, дворф-пивовар, остановившийся в Приозерье, предлагает путникам этот забег, чтобы проверить их стойкость и испытать свое пойло.",al={"who gives rethban gauntlet","yorus barleybrew quest","who starts the gauntlet","кто дает ретбанский вызов","задание йоруса ячменовара","кто начинает испытание"}},{q="Что делает это испытание особенно трудным?",a="Кроме того, что нужно пробираться мимо стай гноллов в предгорьях Красногорья в жестких рамках одного часа, бегуны сначала должны проглотить «Кипяток Ячменоваров» — крепкий напиток, от которого они сильно пьянеют и с трудом держатся на ногах.",al={"why is rethban gauntlet hard","barleybrew scalder effect","почему ретбанский вызов сложный","эффект кипятка ячменоваров"}},{q="Где находятся Пещеры Ретбана?",a="Пещеры находятся в северных предгорьях Красногорья, к северо-западу от Приозерья. Путь ведет на север мимо местных усадеб к скалам, где обитают стаи гноллов.",al={"rethban caverns location","where is rethban","how to get to rethban caverns","местонахождение пещер ретбана","где ретбан","как добраться до пещер ретбана"}},{q="Как далеко в пещеры нужно зайти?",a="Участникам не нужно зачищать всю пещеру; достаточно дойти до первой внутренней развилки, развернуться и мчаться обратно в Приозерье.",al={"rethban caverns objective","how far inside rethban","цель пещер ретбана","как глубоко в ретбан"}},{q="Кто обитает в холмах и пещерах на маршруте?",a="Местность вокруг маршрута и внутри пещер захвачена враждебными гноллами Красногорья, поэтому для выживания в пути необходимы скрытность или быстрый бой.",al={"what enemies in rethban","what is in rethban caverns","какие враги в ретбане","что в пещерах ретбана"}},{q="Куда ведет это испытание дальше?",a="Пережив испытание, вы докажете Йорусу Ячменовару свою выносливость, и откроется путь к дальнейшим заданиям в регионе, например к поискам мастера по щитам Фьюрена Длинноборода в Штормграде.",al={"rethban gauntlet follow up","what quest comes after rethban gauntlet","продолжение ретбанского вызова","какое задание после ретбанского вызова"}}},fp="20,281,14.462.0,22.443.0,32.132.0,49.252.0,38.174.0,40.151.0,51.157.0,36.178.0"}
P.entries["quest:170"] = {n="Новая угроза",s="«Новая угроза» — раннее боевое задание, которое выдает Балир Морозный Молот в Холодной долине. Дворфов-горцев застала врасплох внезапная волна троггов, хлынувших по Дун Мороге и угрожающих местным поселениям и лагерям.",h="«Новая угроза» — раннее боевое задание, которое выдает Балир Морозный Молот в Холодной долине.",kw={"a new threat","anvilmar","balir frosthammer","burly rockjaw","coldridge valley","dun morogh","rockjaw trogg","новая угроза","старая наковальня","балир морозный молот","дюжий трогг каменной челюсти","холодная долина","дун морог","трогг каменной челюсти"},ang={["faction:Alliance"]="Сдерживание подземной угрозы в Холодной долине сохраняет пригодность учебных земель Стальгорна и обеспечивает безопасность южных горных врат для новобранцев Альянса.",["race:Dwarf"]="Для молодых дворфов Бронзобородов, покидающих Старую Наковальню, отражение вторжения троггов — личный долг по защите священных земель и туннелей Дун Морога."},sec={{t="Прорыв в Холодной долине",b="Холодная долина долго считалась защищенным убежищем для молодых дворфов-воинов и горцев, обучавшихся в Дун Мороге. Мир рухнул, когда подземные трогги из племени Каменной Челюсти стали в поразительном числе выбираться на поверхность. В Старую Наковальню быстро дошли вести, что трогги наводнили замерзшее озеро и окрестные предгорья, нарушая ежедневные патрули и перерезая важные пути снабжения через долинный перевал."},{t="Захваченный лагерь",b="Кризис достиг пика, когда твари организованно напали на дворфийский лагерь на западе, вынудив горцев отступить и покинуть посты. Из-за нехватки людей и невозможности выделить полноценные полки из Стальгорна Балир Морозный Молот обратился к новоприбывшим искателям приключений, чтобы они проредили ряды троггов Каменной Челюсти и очистили холмы, пока звери не добрались до порога Старой Наковальни."}},faq={{q="Кто такой Балир Морозный Молот?",a="Балир Морозный Молот — опытный дворф-горец, расквартированный у Старой Наковальни в Холодной долине. Он организует оборону от диких зверей и троггов-захватчиков, угрожающих местным новобранцам.",al={"balir frosthammer","who gives a new threat","frosthammer anvilmar","балир морозный молот","кто выдает новую угрозу","морозный молот старая наковальня"}},{q="Почему трогги вдруг появились в Холодной долине?",a="Трогги Каменной Челюсти стали подниматься из глубоких подземных трещин по всему Дун Морогу. Холодная долина — одна из первых населенных долин, пострадавших от внезапных жестоких прорывов, когда твари захватывают наземные лагеря.",al={"where did troggs come from","why troggs attacking","trogg invasion","откуда пришли трогги","почему трогги нападают","вторжение троггов"}},{q="Какой лагерь захватили трогги?",a="Лагерь дворфов-горцев в западной части Холодной долины недавно попал в засаду и был захвачен троггами, вынудив выживших отступить к Старой Наковальне.",al={"overrun camp","western camp","where did troggs attack","захваченный лагерь","западный лагерь","где напали трогги"}},{q="Какие трогги угрожают долине?",a="Нападающие принадлежат к племени Каменной Челюсти: в основном это обычные трогги Каменной Челюсти и более крупные и крепкие дюжие трогги Каменной Челюсти, ведущие наступление вокруг замерзшего озера и предгорий.",al={"rockjaw troggs","which troggs","burly rockjaw troggs","трогги каменной челюсти","какие трогги","дюжие трогги каменной челюсти"}},{q="Знает ли король Магни о проблеме с троггами?",a="Местные стражи надеются, что король Магни Бронзобород и Сенат Стальгорна готовят более широкий ответ, но пограничным заставам вроде Холодной долины пока приходится самим справляться с локальными вспышками.",al={"does magni know","ironforge response to troggs","ironforge senate troggs","знает ли магни","ответ стальгорна на троггов","сенат стальгорна трогги"}},{q="Что будет после истребления этих троггов?",a="Сокращение числа троггов помогает стабилизировать ближайшие окрестности Старой Наковальни, хотя Балир и другие дворфийские офицеры продолжают готовить контрнаступления, чтобы вернуть потерянный западный лагерь и загнать тварей обратно под землю.",al={"follow up quest","after a new threat","coldridge trogg questline","следующее задание","после новой угрозы","цепочка заданий о троггах холодной долины"}}},fp="12,240,26.426.0,14.404.0,25.209.0,44.222.0,36.179.0,47.196.0,41.203.0,40.220.0"}
P.entries["quest:1700"] = {n="Гриманд Элмор",s="После создания особых доспехов дворф-кузнец Фьюрен Длиннобород отправляет копию своих записей через весь квартал Гриманду Элмору. Это короткое поручение доставляет технические заметки между двумя упрямыми оружейниками, работающими в одном городе — Штормграде.",h="После создания особых доспехов дворф-кузнец Фьюрен Длиннобород отправляет копию своих записей через весь...",kw={"blacksmithing","dwarven district","fire hardened mail","furen longbeard","furen's notes","grimand elmore","stormwind","кузнечное дело","квартал дворфов","закаленный доспех","фьюрен длиннобород","записи фьюрена","гриманд элмор","штормград"},ang={["class:Warrior"]="Эта доставка связывает создание собственных доспехов с поиском боевого оружия, выкованного в тех же стихийных опытах.",["profession:Blacksmithing"]="Обмен между Фьюреном и Гримандом показывает острое профессиональное соперничество и обмен секретами ремесла, обычные среди мастеров-металлургов.",["race:Dwarf"]="Горячая, гордая перепалка Гриманда и Фьюрена отражает глубоко соревновательные, но при этом совместные традиции кузнечной культуры Каз Модана."},sec={{t="Послание через весь квартал",b="Выковав особый Закаленный доспех, Фьюрен Длиннобород записывает сложные приемы термической обработки и стихийные принципы, которые он открыл в ходе работы. Вместо того чтобы оставить знания только себе, он доверяет заметки пергаменту и поручает искателю приключений доставить их прямо Гриманду Элмору, опытному мастеру, работающему в ближайшей оружейной лавке."},{t="Профессиональная гордость и любопытство",b="Первая реакция Гриманда Элмора на рукопись — уязвленная гордость. Он уверен, что научил Фьюрена всему, что тот знает, и возмущается самой мыслью, что его бывший ученик может чему-то его учить. Несмотря на показное негодование, мастер не может удержаться от чтения текста и быстро находит в заметках любопытную идею, которую ему не терпится проверить самому."}},faq={{q="Кто такой Гриманд Элмор?",a="Гриманд Элмор — уважаемый оружейник, у которого есть лавка в Квартале Дворфов города Штормград. Он известен своей огромной профессиональной гордостью и тем, что раньше обучал ремеслу других местных кузнецов, в том числе Фьюрена Длинноборода.",al={"grimand elmore","who is grimand","elmore stormwind","гриманд элмор","кто такой гриманд","элмор штормград"}},{q="Почему Фьюрен посылает записи Гриманду?",a="Создавая Закаленный доспех, Фьюрен открыл новые приемы и записал свои методы. Он хотел поделиться открытиями с Гримандом, хотя знал, что вспыльчивый нрав и упрямое самолюбие Гриманда заставят его обороняться, когда его учат чему-то новому.",al={"why send notes","furen notes","furen to grimand","зачем записи","записи фьюрена","фьюрен гриманду"}},{q="Где найти Гриманда Элмора?",a="Его можно найти за работой в оружейной лавке в Квартале Дворфов города Штормград, в двух шагах от кузницы Фьюрена Длинноборода.",al={"where is grimand","grimand location","grimand elmore shop","где гриманд","местонахождение гриманда","лавка гриманда элмора"}},{q="Как Гриманд реагирует на записи?",a="Сначала Гриманд возмущен и заявляет, что научил Фьюрена всему, что тот знает. Однако любопытство мастера-кузнеца быстро берет верх, когда он замечает в тексте интересный прием, который хочет испытать.",al={"grimand reaction","is grimand mad","реакция гриманда","злится ли гриманд"}},{q="Что происходит после того, как Гриманд прочитал записи?",a="Заинтересовавшись работой Фьюрена по огненной закалке металла, Гриманд решает взяться за собственный амбициозный проект, что ведет к новым заданиям по сбору редких компонентов со стихийным жаром.",al={"what next grimand","after grimand elmore quest","что дальше гриманд","после задания гриманда элмора"}},{q="Почему Фьюрен советует пригнуться, передавая записи?",a="Фьюрен на собственном опыте знает вспыльчивый нрав и чрезмерную гордость Гриманда. Он предполагает, что Гриманд может устроить истерику или швырнуть предмет от одного намека на то, что ученик способен научить мастера новому приему.",al={"why duck","furen duck warning","почему пригнуться","предупреждение фьюрена"}}},fp="14,256,29.392.0,32.407.0,22.240.0,37.270.0,34.149.0,36.233.0,43.187.1,56.215.0"}
P.entries["quest:1701"] = {n="Закаленный доспех",s="«Закаленный доспех» — задание воинов Альянса, которое выдает дворф-бронник Фьюрен Длиннобород в Штормграде. Продолжая прежнюю работу, Фьюрен обещает изготовить исключительно прочный кольчужный доспех, если воин добудет редкие алхимические компоненты и части зверей, разбросанные по обоим континентам.",h="«Закаленный доспех» — задание воинов Альянса, которое выдает дворф-бронник Фьюрен Длиннобород в Штормграде.",kw={"charred horn","fire hardened mail","furen longbeard","galvanized horn","phlogiston","razorfen kraul","roogug","scorched spider fang","stonetalon","wetlands","обожженный рог","закаленный доспех","фьюрен длиннобород","гальванизированный рог","флогистон","лабиринты иглошкурых","ругуг","обожженный паучий клык","когтистые горы","болотина"},ang={["class:Warrior"]="Это испытание — важный обряд посвящения для воинов Альянса: им приходится пройти через дикие земли и глубокие подземелья Калимдора, чтобы заслужить мастерски сделанный доспех.",["faction:Alliance"]="Чтобы выполнить список Фьюрена, солдату Альянса нужно углубиться в Степи и Когтистые горы — земли, за которые ожесточенно борется Орда.",["race:Dwarf"]="Мастерство Фьюрена отражает давнее убеждение дворфов: настоящая броня требует несокрушимых материалов, добытых прямо у самых суровых хищников."},sec={{t="Амбиции мастера-бронника",b="Выковав для начинающего воина превосходный баклер, Фьюрен Длиннобород предлагает проект еще масштабнее: кольчугу, закаленную против самых жестоких ударов. Такое дворфийское мастерство требует не просто железа или стали, а редких материалов, пропитанных стихийным жаром и природной стойкостью. Поскольку кузнец не может покинуть свою кузницу в Штормграде, бремя сбора опасных реагентов целиком ложится на воина, ищущего доспех."},{t="Экспедиция через континенты",b="Подробные указания Фьюрена отправляют воина в дальние глуши и коварные глубины. Для рецепта нужны клыки ядовитых паукообразных, ползающих по сырым расселинам Болотины, а также обожженные и гальванизированные рога свирепых химер, гнездящихся в Когтистых горах. Чтобы связать и закалить эти части зверей в носимую кольчугу, нужен еще фиал летучего флогистона, который можно отобрать у Ругуга, геоманта в глубине колючих лабиринтов Лабиринтов Иглошкурых в Степях."}},faq={{q="Кто такой Фьюрен Длиннобород?",a="Фьюрен Длиннобород — опытный дворф-бронник и щитник, живущий в Квартале Дворфов города Штормград. Он специализируется на изготовлении подогнанного защитного снаряжения для многообещающих воинов, готовых ему помочь.",al={"furen","who gives fire hardened mail","who is the smith","фьюрен","кто дает закаленный доспех","кто этот кузнец"}},{q="Зачем Фьюрену такие странные ингредиенты?",a="Обычная плавка дает простую сталь, но секретные приемы Фьюрена требуют органических материалов, закаленных природным ядом, горными ветрами и дыханием, а также летучего каталитического вещества флогистона, чтобы закалить металл лучше обычных дворфийских методов.",al={"why spider fangs","why horns","what is phlogiston","зачем клыки пауков","зачем рога","что такое флогистон"}},{q="Откуда берутся рога химер?",a="Обожженные рога и ценный гальванизированный рог добывают у химер, обитающих в Когтистых горах Калимдора, особенно у молодых зверей и грозной матриарха химер, которая ими предводительствует.",al={"where to find chimaera horns","charred horn location","galvanized horn","где найти рога химер","обожженный рог","гальванизированный рог"}},{q="Где найти флогистон?",a="Фиал флогистона носит с собой геомант-свинобраз Ругуг, чье логово находится в Лабиринтах Иглошкурых на южной оконечности Степей в Калимдоре.",al={"vial of phlogiston","who drops phlogiston","roogug","фиал флогистона","у кого флогистон","ругуг"}},{q="У каких пауков можно добыть обожженные паучьи клыки?",a="Клыки добывают у гигантских паукообразных Болотины в Восточных королевствах, а именно у пиявочных и пещерных сторожей, скрывающихся в болотах и пещерах региона.",al={"scorched spider fangs","where are the spiders","wetlands spiders","обожженные паучьи клыки","где пауки","пауки болотины"}},{q="Что происходит после сбора всех материалов?",a="Получив клыки, рога и флогистон, Фьюрен сразу принимается за работу в кузнице, чтобы выковать из сырых материалов нагрудник для воина в задании «Доспехи Фьюрена».",al={"what comes next","fire hardened mail follow up","reward","что дальше","продолжение закаленного доспеха","награда"}}},fp="18,333,27.465.0,30.544.0,23.212.0,48.277.0,38.199.0,30.163.0,42.182.0,50.190.0"}
P.entries["quest:1702"] = {n="Щитник",s="После изнурительного испытания в Красногорье Йорус Ячменовар отправляет воинов в Квартал Дворфов Штормграда за настоящей наградой. С бочонком крепкого «Ячменного ожога» воины ищут мастера-бронника Фьюрена Длинноборода, чтобы он выковал прочный щит.",h="После изнурительного испытания в Красногорье Йорус Ячменовар отправляет воинов в Квартал Дворфов Штормграда...",kw={"barleybrew scalder","cask","dwarven district","furen longbeard","rethban","shieldsmith","stormwind","warrior","yorus barleybrew","ячменный ожог","бочонок","квартал дворфов","фьюрен длиннобород","ретбан","щитник","штормград","воин","йорус ячменовар"},ang={["class:Warrior"]="Эта доставка связывает суровость Красногорья с мастерством Штормграда и доказывает ваше право носить щит, выкованный легендарным дворфом-бронником.",["profession:Blacksmithing"]="Знакомство с Фьюреном Длиннобородом сводит вас с мастером наковальни, чья работа над защитными доспехами славится по всему Альянсу.",["race:Dwarf"]="Обменять бочонок отличного ячменного эля Ячменоваров на кованое железо в сердце Квартала Дворфов Штормграда — вот самая что ни на есть дворфийская сделка."},sec={{t="Обещание исполнено",b="Доказав доблесть в схватке с гноллами и опасностями Ретбанского вызова, воины ждут платы от Йоруса Ячменовара. Йорус держит слово, но настоящую награду нельзя выковать в Приозерье. Он направляет перспективных бойцов обратно в Штормград, где дворф-бронник готов вернуть личный долг."},{t="Лучшее от Ячменоваров",b="Вместо пергаментного письма с поручительством Йорус дает валюту куда убедительнее для жаждущего стальгорнского мастера: тяжелый бочонок «Ячменного ожога». Доставленный Фьюрену Длиннобороду среди лязга и копоти Квартала Дворфов, напиток служит и рекомендацией, и платой, побуждая опытного кузнеца применить мастерство для начинающего защитника."}},faq={{q="Кто такой Фьюрен Длиннобород?",a="Фьюрен Длиннобород — мастер-бронник и щитник из дворфов, живущий в Квартале Дворфов города Штормград. Он известен среди воинов Альянса: изготавливает особое защитное снаряжение и тесно сотрудничает с ветеранами, заслужившими его уважение.",al={"furen longbeard","who is furen","who is the shieldsmith","фьюрен длиннобород","кто такой фьюрен","кто такой щитник"}},{q="Почему Йорус отправляет вас в Штормград?",a="Хотя Йорус Ячменовар предложил награду за прохождение Ретбанского вызова, у него нет нужных навыков кузнеца, чтобы выковать обещанный щит самому. Он посылает вас к своему другу Фьюрену Длиннобороду, который должен ему большую услугу.",al={"why go to stormwind","why stormwind","yorus reward location","зачем идти в штормград","почему штормград","где награда йоруса"}},{q="Что такое «Ячменный ожог»?",a="«Ячменный ожог» — исключительно крепкий дворфийский напиток, который варит семья Ячменоваров. Йорус посылает свежий бочонок Фьюрену Длиннобороду, чтобы утолить жажду кузнеца и смазать колеса их сделки.",al={"cask of scalder","barleybrew scalder","what is the scalder","бочонок ожога","ячменный ожог","что такое ожог"}},{q="Где найти Фьюрена Длинноборода?",a="Фьюрена Длинноборода можно найти у его кузницы в самом сердце Квартала Дворфов города Штормград, среди копоти, наковален и мастерских дворфийских ремесленников.",al={"furen location","where is furen longbeard","find furen","где фьюрен","где найти фьюрена длиннобород","найти фьюрена"}},{q="Что происходит после передачи бочонка Фьюрену?",a="Receiving the Scalder confirms that Yorus sent you. Furen acknowledges his debt and immediately offers to construct defensive armor suited for seasoned battle, beginning a path toward crafting fire-hardened gear.",al={"what comes next","furen follow up quest","что дальше","продолжение задания фьюрена"}},{q="Почему это поручение важно для воинов Альянса?",a="Это поручение знакомит воина Альянса с одним из самых искусных бронников королевства, открывая путь к подогнанному боевому снаряжению и дальнейшему обучению искусству защитной войны.",al={"warrior quest importance","why warriors care","важность задания воина","почему воинам важно"}}},fp="15,278,14.343.0,19.358.0,23.245.0,37.239.0,27.213.0,35.169.0,41.212.0,51.193.0"}
P.entries["quest:1703"] = {n="Матиль",s="В этом задании искателю приключений поручают доставить записи Фьюрена Длиннобороды о кузнечном деле за море, в Дарнасс. Получатель — Матиль, искусный кузнец с Террасы Воинов, желающий изучить дворфийские новшества в ковке кольчуг. Это важный обмен военной металлургией между Стальгорном и кальдораями.",h="В этом задании искателю приключений поручают доставить записи Фьюрена Длиннобороды о кузнечном деле за море...",kw={"blacksmith","darnassus","fire hardened mail","furen longbeard","furen's notes","mathiel","teldrassil","warrior's terrace","кузнец","дарнасс","закаленная огнем кольчуга","фьюрен длиннобород","записи фьюрена","матиль","тельдрассил","терраса воинов"},ang={["class:Warrior"]="Доставка этих записей — часть вашего пути от огненных кузниц Восточных королевств до испытательных площадок Дарнасса, пополняющая ваш личный арсенал.",["profession:Blacksmithing"]="Эта доставка показывает важное сотрудничество мастеров-кузнецов: чертежи и приемы термической закалки переходят от одной далекой наковальни к другой.",["race:Dwarf"]="Передача ночным эльфам металлургического открытия Фьюрена подчеркивает гордость дворфов своим непревзойденным мастерством в кузнечном деле.",["race:NightElf"]="Матиль воплощает готовность кальдораев изучать подземное дворфийское кузнечное дело и сочетать его с традиционным доспешным ремеслом ночных эльфов."},sec={{t="Посыльный за морем",b="Освоив сложный процесс ковки закаленных огнем доспехов, ветеран-кузнец дворф Фьюрен Длиннобород решает поделиться своими достижениями с другими ремесленниками Альянса. Вместо того чтобы хранить новые знания о металлургии в тайне, Фьюрен переписывает подробные технические чертежи и отправляет проверенного искателя приключений через континенты на поиски Матиля, опытного кузнеца, живущего высоко в Тельдрассиле."},{t="Сталь кальдораев и дворфийское мастерство",b="Матиль работает в своей кузнице на Террасе Воинов в Дарнассе, под сенью деревьев, и обслуживает Часовых и бойцов, защищающих столицу ночных эльфов. Получение записей Фьюрена становится мостом между разными кузнечными традициями: суровой подземной плавкой дворфов Каз Модана и изящным, созвучным природе доспешным ремеслом кальдораев."}},faq={{q="Кто такой Матиль?",a="Матиль — ночной эльф-кузнец, работающий на Террасе Воинов в Дарнассе. Он изготавливает снаряжение для защитников столицы и поддерживает дружескую переписку с другими мастерами-кузнецами по всему Альянсу.",al={"mathiel lore","who is mathiel darnassus","матиль предания","кто такой матиль дарнасс"}},{q="Почему Фьюрен посылает вас в Дарнасс?",a="Фьюрен Длиннобород хочет, чтобы его исследования ковки закаленных огнем доспехов пошли на пользу другим ремесленникам Альянса. Матиль — надежный коллега, способный оценить и применить передовые металлургические приемы, поэтому Фьюрен поручает вам доставить ему свои личные записи.",al={"why send notes to mathiel","furen notes reason","зачем отправлять записи матилю","причина записей фьюрена"}},{q="Где в Дарнассе найти Матиля?",a="Матиля можно найти у кузницы на Террасе Воинов, в восточном квартале Дарнасса у главных ворот, где тренируются воины и Часовые.",al={"mathiel location","where is mathiel","где матиль","местонахождение матиля"}},{q="Что будет после того, как отдать Матилю записи?",a="Впечатленный открытиями Фьюрена, Матиль решает развить дворфийские приемы и отправляет воина на новые испытания в дикие земли Калимдора, чтобы собрать редкие компоненты, например обожженные солнцем панцири.",al={"next quest after mathiel","mathiel followup","следующее задание после матиля","продолжение матиль"}},{q="Какие записи нужно доставить?",a="В записях содержатся подробные металлургические наблюдения и приемы ковки, которые Фьюрен узнал, экспериментируя с клыками обожженных пауков, рогами химер и флогистоном для создания усиленной кольчуги.",al={"furen notes contents","what are furen's notes","содержание записей фьюрена","что в записях фьюрена"}},{q="Доступно ли это задание только воинам?",a="Да, это поручение посыльного входит в особую цепочку испытаний и развития для воинов Альянса, совершенствующих боевое мастерство и искусство работы с доспехами.",al={"warrior quest mathiel","can other classes do mathiel","задание воина матиль","могут ли другие классы выполнить задание матиля"}}},fp="7,320,24.388.0,32.366.0,15.217.0,37.283.0,38.158.0,44.205.1,39.197.0,37.142.0"}
P.entries["quest:1704"] = {n="Клацморт Гайкокрут",s="В этом задании искателя приключений отправляют из Штормграда в Стальгорн, чтобы доставить секреты ремесла Клацморту Гайкокруту в Город механиков. Освоив искусство закаленных огнем доспехов, дворф-кузнец Фьюрен Длиннобород охотно делится своими металлургическими открытиями с коллегой-гномом. Это важное звено в пути начинающего воина, желающего испытать необычные способы ковки.",h="В этом задании искателя приключений отправляют из Штормграда в Стальгорн, чтобы доставить секреты ремесла...",kw={"blacksmith","fire hardened","furen","ironforge","klockmort","longbeard","notes","spannerspan","tinkertown","кузнец","закаленный огнем","фьюрен","стальгорн","клацморт","длиннобород","записи","гайкокрут","город механиков"},ang={["class:Warrior"]="Ваш путь к созданию прочного боевого снаряжения ведет вас от дворфийских горнов прямо к гномьим изобретениям и привлекает к вам внимание лучших мастеров Города механиков.",["profession:Blacksmithing"]="Записи Фьюрена — пример совместного обмена передовыми кузнечными приемами между мастерами-ремесленниками Стальгорна.",["race:Gnome"]="Клацморт воплощает изобретательное сочетание классической дворфийской металлургии и гномьих экспериментов в Городе механиков."},sec={{t="Коллега в Городе механиков",b="Успешно выковав комплект закаленной огнем кольчуги, Фьюрен Длиннобород собирает подробные выводы, чтобы передать их собрату по ремеслу. Вместо того чтобы хранить новые приемы в тайне, Фьюрен доверяет вам отнести его записи из Штормграда в Стальгорн, в грохот и пар Города механиков, где трудится гном-кузнец Клацморт Гайкокрут."},{t="Гномий восторг",b="Гномы-кузнецы встречаются сравнительно редко по сравнению с их дворфийскими хозяевами, и Клацморт с энтузиазмом расширяет границы традиционной работы с металлом. Изучив записи Фьюрена, Клацморт приходит в безудержный восторг от открытия и стремится применить эти огненные приемы в своих необычных проектах."}},faq={{q="Кто такой Клацморт Гайкокрут?",a="Клацморт Гайкокрут — гном-кузнец, работающий в Городе механиков в подземном городе Стальгорне. Он тесно сотрудничает с кузнецами-дворфами, такими как Фьюрен Длиннобород, в области передовых методов обработки металла.",al={"klockmort spannerspan","who is klockmort","gnome blacksmith ironforge","клацморт гайкокрут","кто такой клацморт","гном-кузнец стальгорн"}},{q="Почему Фьюрен Длиннобород посылает вас к Клацморту?",a="Фьюрен записал подробности прорывных приемов, которые обнаружил при ковке закаленной огнем кольчуги. Зная увлеченность Клацморта изобретательным кузнечным делом, Фьюрен посылает вас доставить эти сведения, чтобы гном мог поэкспериментировать с ними.",al={"why deliver notes","furen's notes","furen longbeard klockmort","зачем доставлять записи","записи фьюрена","фьюрен длиннобород клацморт"}},{q="Где найти Клацморта Гайкокрута?",a="Клацморт Гайкокрут находится в Городе механиков, квартале Стальгорна, где преобладают гномы, в восточной части города, среди верстаков и механизмов.",al={"klockmort location","where is klockmort","klockmort ironforge","где клацморт","местонахождение клацморта","клацморт стальгорн"}},{q="Что будет после того, как отдать Клацморту записи?",a="Восхищенный открытием Фьюрена, Клацморт сразу начинает планировать собственные металлургические проекты и отправляет вас собирать необычные материалы, например железный коралл.",al={"quest continuation","what next after klockmort","iron coral quest","продолжение задания","что дальше после клацморта","задание железный коралл"}},{q="Это задание только для воинов?",a="Да. Эта доставка входит в особую цепочку заданий по созданию доспехов, доступную только воинам Альянса, обучающимся у опытных мастеров оружия и доспехов.",al={"warrior only","can anyone do this quest","class requirement","только воин","кто может выполнить задание","требования к классу"}},{q="Почему Клацморт говорит, что не отличает день от ночи?",a="Стальгорн — полностью подземный город, вырубленный в самом сердце горы в Дун Мороге. В Городе механиков, под каменными сводами и светом ламп, ремесленники не видят ни солнца, ни неба.",al={"klockmort day night dialogue","way down here dialogue","клацморт день и ночь диалог","диалог здесь внизу"}}},fp="21,386,25.371.0,18.314.0,29.214.0,47.245.0,39.153.0,46.175.1,34.156.0,53.189.0"}
P.entries["quest:1705"] = {n="Пылающая кровь",s="Мастер-кузнец Гриманд Элмор из Штормграда поручает искателю приключений отправиться в сумрачные чащи Сумеречного леса и добыть редкие реагенты для кузни. Заинтересовавшись новаторскими приемами изготовления доспехов Фьюрена Длиннобороды, Гриманд хочет сам испытать процесс и требует Пылающую кровь и пылающий камень, которые носят дикие воргены.",h="Мастер-кузнец Гриманд Элмор из Штормграда поручает искателю приключений отправиться в сумрачные чащи...",kw={"burning blood","burning rock","duskwood","furen longbeard","grimand elmore","gutspill","nightbane worgen","roland's doom","пылающая кровь","пылающий камень","сумеречный лес","фьюрен длиннобород","гриманд элмор","потрошитель","воргены ночной погибели","погибель роланда"},ang={["class:Warrior"]="Для воинов, путешествующих по королевству, схватка с проклятыми тварями Сумеречного леса ради эксперимента Гриманда дает особо закаленный доспех, созданный для передовой.",["faction:Alliance"]="Добыча реагентов в Погибели Роланда помогает сдерживать наступающую угрозу воргенов в Сумеречном лесу и снабжает оружейные Штормграда новыми мощными защитными приемами.",["profession:Blacksmithing"]="Кузнецы оценят профессиональную гордость Гриманда и его бывшего ученика Фьюрена: она показывает, на что готовы мастера-кузнецы ради проверки редкой металлургии и закалочных средств."},sec={{t="Неохотный эксперимент",b="Гриманд Элмор, один из самых искусных оружейников Альянса, редко признает, что другой мастер может превзойти его методы. Но, услышав о нетрадиционных кузнечных открытиях Фьюрена Длиннобороды, он поддается профессиональному любопытству, победившему упрямую гордость. Гриманд соглашается проверить методы Фьюрена, выковав доспех на заказ. Чтобы закалить и отпустить металл по точным меркам, обычной воды или простого угля мало: ему нужны странные, нестабильные компоненты, которые встречаются только в темных землях на юге."},{t="Ужасы Погибели Роланда",b="Задание отправляет отважных кузнецов-новичков и воинов в Сумеречный лес, к заброшенной шахте Погибель Роланда. Пещеру заполонили свирепые воргены Ночной Погибели — волкоподобные звери, в проклятых жилах которых пульсирует неестественный жгучий ихор. Гриманду нужны флаконы этой Пылающей крови, а также редкое пылающее ядро — пылающий камень, которым владеет свирепый вожак стаи Потрошитель. Убив этих зверей и добыв их раскаленные останки, Гриманд сможет разжечь свой горн темной огненной силой."}},faq={{q="Кто такой Гриманд Элмор?",a="Гриманд Элмор — уважаемый мастер-оружейник, работающий в Квартале Дворфов Штормграда. Он трудится вместе с другими ремесленниками, снаряжая защитников города, и обучает начинающих воинов прочности и весу настоящих латных доспехов.",al={"grimand","grimand elmore","stormwind armorer","гриманд","гриманд элмор","оружейник штормград"}},{q="Зачем Гриманду пылающая кровь и пылающий камень?",a="Гриманд хочет испытать нетрадиционный способ изготовления доспехов, разработанный Фьюреном Длиннобородом. Пылающая кровь и пылающий камень обладают сильным сверхъестественным жаром, необходимым для закалки и ковки особых броневых пластин.",al={"why burning blood","what is burning rock for","quest purpose","зачем пылающая кровь","для чего пылающий камень","цель задания"}},{q="Где найти воргенов Ночной Погибели, носящих эти материалы?",a="Материалы можно найти в Сумеречном лесу, в Погибели Роланда — заброшенной шахте на юго-востоке Сумеречного леса, к юго-западу от Темнолесья. Туннели шахты кишат враждебными воргенами Ночной Погибели, в чьих жилах течет жгучая кровь.",al={"where are the worgen","roland's doom location","where is burning blood","где воргены","где погибель роланда","где пылающая кровь"}},{q="У кого пылающий камень?",a="Пылающий камень носит Потрошитель, могучий вожак воргенов Ночной Погибели, обитающий в глубинах Погибели Роланда.",al={"who has burning rock","gutspill","gutspill location","у кого пылающий камень","потрошитель","где потрошитель"}},{q="Какие отношения связывают Гриманда Элмора и Фьюрена Длиннобороды?",a="Фьюрен Длиннобород — бывший ученик Гриманда Элмора. Гриманд обычно скептически относится к чужим идеям, но последние новшества Фьюрена в изготовлении доспехов оказались достаточно убедительными, чтобы Гриманд проверил их лично.",al={"grimand and furen","who is furen longbeard","гриманд и фьюрен","кто такой фьюрен длиннобород"}},{q="Что будет после возвращения крови и камня?",a="Получив огненные реагенты, Гриманд сразу начинает ковать доспех, чтобы проверить приемы Фьюрена, и обещает готовое изделие искателю приключений, собравшему материалы.",al={"next quest","reward","what does grimand make","следующее задание","награда","что делает гриманд"}}},fp="13,332,22.553.0,28.524.0,22.240.0,55.219.0,62.209.0,27.130.0,68.207.0,48.193.0"}
P.entries["quest:1706"] = {n="Доспехи Гриманда",s="«Доспехи Гриманда» — завершающее задание цепочки обучения воина под руководством Гриманда Элмора в Квартале Дворфов Штормграда. После того как действенность металлургических методов Фьюрена Длинноборода подтверждается, кузнец изготавливает внушительный доспех, способный выдерживать сокрушительные удары в бою. Это важная веха на пути воина Альянса к мастерству.",h="«Доспехи Гриманда» — завершающее задание цепочки обучения воина под руководством Гриманда Элмора в Квартале...",kw={"armor","coif","burning blood","dwarven district","furen longbeard","grimand elmore","stormwind","warrior quest","доспехи","шлем","пылающая кровь","квартал дворфов","фьюрен длиннобород","гриманд элмор","штормград","задание воина"},ang={["class:Warrior"]="Это задание — переломный момент в карьере воина Альянса: он получает знаковый прочный шлем, откованный так, чтобы выдерживать жестокие удары первой линии боя.",["faction:Alliance"]="То, что Гриманд Элмор опирается на разработки Фьюрена Длинноборода, показывает, как дворфийские кузнецы Квартала Дворфов Штормграда делятся открытиями, чтобы вооружать воинов Альянса.",["profession:Blacksmithing"]="Обмен показывает сотрудничество двух дворфийских кузнецов Квартала Дворфов Штормграда, использующих необычные реагенты для резкой закалки металла."},sec={{t="Новаторство мастера доказано",b="Гриманд Элмор, работающий в своей кузнице в Квартале Дворфов Штормграда, поначалу глубоко сомневался в странных и смелых методах, разработанных дворфийским мастером-бронником Фьюреном Длиннобородом. Чтобы проверить методы Фьюрена, требовались опасные походы на вражескую территорию за редкими стихийными и звериными компонентами. Доставив эти важные материалы, воин позволяет Гриманду испытать теории дворфа огнем и превратить сырье в усиленный шлем, рассчитанный на катастрофические удары."},{t="Ковка эгиды",b="Готовое изделие показывает, что металлургические догадки Фьюрена были совершенно верны. Гриманду удается обработать металл так, что он выдерживает давление и физические повреждения, от которых обычная сталь покоробилась бы. Вручая изготовленный шлем помогавшему ему воину, Гриманд признает и мастерство Фьюрена, и решимость искателя приключений, давая ему возможность держать первую линию против величайших угроз Азерота."}},faq={{q="Для чего нужно это задание?",a="Это задание — заключительная сдача в большой цепочке заданий воина. Гриманд Элмор заканчивает изготовление особо обработанного шлема из редких материалов, которые вы добыли, и подтверждает опытные кузнечные методы Фьюрена Длинноборода.",al={"grimand armor purpose","why do grimands armor","what does grimand give me","доспехи гриманда зачем","для чего доспехи гриманда","что дает гриманд"}},{q="Кто такой Гриманд Элмор?",a="Гриманд Элмор — искусный дворфийский оружейник, живущий в Квартале Дворфов Штормграда. Он работает вместе с коллегами из Стальгорна, помогая начинающим воинам получить особые доспехи.",al={"who is grimand","grimand elmore role","where is grimand","кто такой гриманд","гриманд элмор","где гриманд"}},{q="Кто такой Фьюрен Длиннобород и почему он упоминается?",a="Фьюрен Длиннобород — дворфийский мастер-бронник из Квартала Дворфов Штормграда, придумавший опытный способ укрепления доспехов против огромных нагрузок. Гриманд поначалу сомневался в словах Фьюрена, пока вы не принесли материалы, нужные для проверки метода.",al={"who is furen","furen technique","furen longbeard","кто такой фьюрен","метод фьюрена","фьюрен длиннобород"}},{q="Какое задание непосредственно предшествует этому?",a="Это задание следует за заданием «Пылающая кровь»: воин приносит Гриманду последний редкий реагент — пылающую кровь ночных воргенов Ночной Погибели из Погибели Роланда в Сумеречном лесу, — чтобы тот мог закалить металл.",al={"prereq for grimands armor","burning blood quest","what quest comes before this","предыдущее задание доспехи гриманда","пылающая кровь задание","какое задание перед этим"}},{q="Может ли выполнить это задание любой класс?",a="Нет. Эта цепочка заданий предназначена строго для воинов Альянса примерно тридцатого уровня и является обрядом посвящения на пути к прочным кольчужным доспехам.",al={"is grimand's armor warrior only","who can do grimand armor","доспехи гриманда только для воинов","кто может выполнить доспехи гриманда"}},{q="Где сдается это задание?",a="Задание сдается напрямую Гриманду Элмору у его наковальни в Квартале Дворфов города Штормград.",al={"where turn in grimand armor","grimand location stormwind","где сдать доспехи гриманда","гриманд штормград"}}},fp="15,395,28.521.0,17.417.0,34.230.0,22.200.0,47.278.0,40.206.0,34.158.0,35.105.0"}
P.entries["quest:1708"] = {n="Железный коралл",s="«Железный коралл» — задание Альянса, которое выдает гном-кузнец Клацморт Гайкокрут в Городе механиков в Стальгорне. Желая испытать недавно полученные кузнечные методы на особом доспехе, Клацморт посылает вас нырять за редким жгучим кораллом вдоль побережья Болотины. Выполнив его просьбу, вы позволите ему соединить гномью изобретательность с дворфийским мастерством.",h="«Железный коралл» — задание Альянса, которое выдает гном-кузнец Клацморт Гайкокрут в Городе механиков в...",kw={"armor smelting","furen longbeard","iron coral","ironforge","klockmort spannerspan","menethil harbor","searing coral","tinker town","wetlands","плавка доспехов","фьюрен длиннобород","железный коралл","стальгорн","клацморт гайкокрут","гавань менетилов","жгучий коралл","город механиков","болотина"},ang={["profession:Blacksmithing"]="Кузнецы оценят нетрадиционный способ плавки, который пробует Клацморт: добытые морские залежи превращаются в закаленные пластины для личного доспеха.",["profession:Engineering"]="Задание показывает философию механиков: испытывать необычные свойства материалов ради превосходной защиты.",["race:Dwarf"]="Опыт напрямую рожден металлургическими открытиями стальгорнского мастера-кузнеца Фьюрена Длинноборода и показывает тесное сотрудничество гномов и дворфов в Городе механиков.",["race:Gnome"]="Стремление Клацморта использовать странные прибрежные минералы вместо обычного добытого железа отражает типичную гномью изобретательность: всегда улучшать традиционное мастерство посредством опытов."},sec={{t="Слияние ремесел",b="Обменявшись знаниями с дворфийским мастером-кузнецом Фьюреном Длиннобородом, Клацморт Гайкокрут полон вдохновения. Эксцентричный гном-кузнец хочет объединить металлургию Фьюрена со своими идеями механика и создать исключительно прочный доспех. Для этого смелого металлургического опыта обычной горной руды недостаточно: Клацморту нужен необычный, естественно закаленный морской материал — жгучий коралл."},{t="Ныряние у берегов Болотины",b="Жгучий коралл — нестабильное, прочное океаническое образование, встречающееся лишь в одном районе: под водой у побережья к югу от Гавани Менетилов в Болотине. Добыча двадцати кусков означает путь по коварным водам болот, схватки с местными морскими хищниками и доставку мокрого груза в Стальгорн. Но для Клацморта награда стоит этой сырой вылазки: он намерен выплавить и выковать коралл прямо в свою опытную броню."}},faq={{q="Кто такой Клацморт Гайкокрут?",a="Клацморт Гайкокрут — искусный гном-кузнец, живущий в Городе механиков в горном городе Стальгорне. Увлеченный механикой и передовой металлургией, он тесно сотрудничает с дворфийскими мастерами, изобретая новые методы изготовления доспехов.",al={"klockmort","who gives iron coral","quest giver iron coral","клацморт","кто дает железный коралл","выдающий задание железный коралл"}},{q="Что такое жгучий коралл?",a="Жгучий коралл — редкое океаническое образование, которое добывают со дна к югу от Гавани Менетилов в Болотине. Его особые химические и физические свойства позволяют изобретательному мастеру выплавить его и выковать в тяжелое пластинчатое усиление.",al={"searing coral lore","what is searing coral used for","жгучий коралл предания","для чего нужен жгучий коралл"}},{q="Где найти жгучий коралл?",a="Коралловые заросли растут только под водой у океанского берега к югу от Гавани Менетилов в Болотине. Ныряльщикам нужно искать под волнами и выламывать богатые минералами ветви.",al={"searing coral location","where is iron coral located","wetlands coral location","где жгучий коралл","где находится железный коралл","коралл болотина"}},{q="Почему Клацморту нужен жгучий коралл, а не металлическая руда?",a="Клацморт пытается усовершенствовать кузнечные методы, которым научился у дворфа Фьюрена Длинноборода. Вместо того чтобы полагаться только на традиционные руды Стальгорна, он надеется, что необычные свойства жгучего коралла дадут более легкое и заметно более прочное изделие после плавки.",al={"why coral for armor","coral metallurgy","зачем коралл для доспехов","металлургия коралла"}},{q="Какое отношение к заданию имеет Фьюрен Длиннобород?",a="Фьюрен Длиннобород ранее разработал новые методы изготовления доспехов при вашей помощи. Благодарный за помощь, Фьюрен поделился своими секретами ремесла с Клацмортом, вдохновив гнома приспособить их для собственных защитных изобретений.",al={"furen connection","furen longbeard iron coral","связь с фьюреном","фьюрен длиннобород железный коралл"}},{q="Что происходит после доставки коралла Клацморту?",a="Получив двадцать порций жгучего коралла, Клацморт тут же берется за плавку и ковку на своем верстаке, что ведет прямо к показу его опытного снаряжения в задании «Творение Клацморта».",al={"iron coral follow up","next quest iron coral","железный коралл продолжение","следующее задание железный коралл"}}},fp="10,353,18.451.0,25.468.0,29.265.0,22.245.0,34.203.0,59.284.0,45.227.0,51.233.1"}
P.entries["quest:1709"] = {n="Творение Клацморта",s="«Творение Клацморта» — успешная ковка особого доспеха в Городе механиков Стальгорна. Используя необычный метод мастера-бронника Фьюрена Длинноборода, гном-кузнец Клацморт Гайкокрут придает сырью форму исключительно прочного снаряжения.",h="«Творение Клацморта» — успешная ковка особого доспеха в Городе механиков Стальгорна.",kw={"furen longbeard","iron coral","ironforge","klockmort","siege engine","spannerspan","tinker town","warrior armor","фьюрен длиннобород","железный коралл","стальгорн","клацморт","осадная машина","гайкокрут","город механиков","доспех воина"},ang={["class:Warrior"]="Заказ этих рукавиц — важная веха для воинов Альянса: они получают особо закаленный доспех, созданный, чтобы выдерживать сокрушительные удары передовой.",["profession:Blacksmithing"]="Успешное применение формулы Фьюрена Длинноборода подчеркивает ценность опытов с нетрадиционными методами закалки и редкими морскими материалами.",["race:Gnome"]="Работа Клацморта показывает, что гномья изобретательность важна даже в тяжелом бронном деле: механическая точность улучшает традиционные дворфийские ремесла."},sec={{t="Слияние дисциплин",b="Ковка тяжелых доспехов обычно проходит на великих наковальнях Великой кузни, но Клацморт Гайкокрут работает в Городе механиков. Создание этого доспеха — совместный успех дворфийской металлургической традиции и гномьих механических новшеств. Приспособив строгие методы Фьюрена Длинноборода, Клацморт завершает пару латных рукавиц, рассчитанных на удары, которые раздавили бы обычную сталь."},{t="Непревзойденная стойкость",b="По словам Клацморта, прочность готового доспеха так велика, что осадная машина могла бы проехать прямо по нему, не оставив стойкой деформации. Секрет — в особой обработке редких компонентов: сочетание древних дворфийских методов ковки и гномьей изобретательности дает доспех, способный выдержать самые яростные бои на передовой."}},faq={{q="Кто такой Клацморт Гайкокрут?",a="Клацморт Гайкокрут — искусный гном-кузнец, живущий в Городе механиков в Стальгорне. Он помогает в сложных механических работах и вместе с дворфийскими мастерами, такими как Фьюрен Длиннобород, создает уникальное прочное снаряжение.",al={"klockmort","who is klockmort","gnome in tinker town","клацморт","кто такой клацморт","гном в городе механиков"}},{q="Кто разработал способ изготовления этого доспеха?",a="Процесс ковки придумал Фьюрен Длиннобород, опытный дворфийский бронник. Клацморт точно следовал методике Фьюрена, обрабатывая материалы и доводя доспех до готовности.",al={"who made the process","furen longbeard armor","furen method","кто создал способ","фьюрен длиннобород доспех","метод фьюрена"}},{q="Почему этот доспех сделал гном-кузнец?",a="Клацморт, гном-кузнец, хотел опробовать новый метод Фьюрена Длинноборода на собственном доспехе. Поскольку вы помогли Фьюрену, он предложил вам готовый доспех в обмен на сбор жгучего коралла, который был ему нужен.",al={"why a gnome","gnome blacksmithing","engineering armor","почему гном","гномье кузнечное дело","инженерный доспех"}},{q="Чем этот доспех лучше обычных латных?",a="Клацморт утверждает, что готовый доспех обладает удивительной упругостью и пружинистостью при жесткой прочности. Он хвастает, что даже если расплющить его гусеницами тяжелой осадной машины, металл мгновенно вернется в прежнюю форму.",al={"how strong is it","siege engine armor","armor durability","насколько он прочен","доспех осадная машина","прочность доспеха"}},{q="Какое место этот доспех занимает на пути обучения воина?",a="Это изделие — итог целой серии заданий, которые выполняют многообещающие воины Альянса, желающие обзавестись прочным доспехом, откованным лучшими умами Стальгорна.",al={"warrior quest armor","why do this quest","warrior reward","задание воина доспех","зачем выполнять задание","награда воина"}},{q="Где найти Клацморта?",a="Клацморта Гайкокрута можно найти среди мастерских, лязгающих шестерен и паровых клапанов Города механиков, гномьего квартала Стальгорна.",al={"klockmort location","where is spannerspan","где клацморт","где гайкокрут"}}},fp="20,309,23.429.0,20.378.0,29.238.0,44.190.0,43.227.0,57.241.0,62.195.0,25.138.0"}
P.entries["quest:1710"] = {n="Высохшая скорлупа",s="В Дарнассе оружейник Матиль вместе с дворфом-кузнецом Фьюреном Длиннобородом совершенствует новую технику изготовления кольчуг. Он поручает воинам отправиться в Тысячу Игл и собрать прочную скорлупу яиц виверн с высот Скального гнездовья.",h="В Дарнассе оружейник Матиль вместе с дворфом-кузнецом Фьюреном Длиннобородом совершенствует новую технику...",kw={"eggshells","furen longbeard","highperch","lacquer","mail armor","mathiel","thousand needles","wyvern","скорлупа","фьюрен длиннобород","скальное гнездовье","лак","кольчуга","матиль","тысяча игл","виверна"},ang={["class:Warrior"]="Эксперимент Матиля нацелен на создание прочной кольчуги, поэтому это задание — обязательное испытание для воинов Альянса, желающих улучшить боевое снаряжение.",["faction:Alliance"]="Это сотрудничество показывает технический обмен между мастерами-ночными эльфами Дарнасса и дворфами-оружейниками Штормграда.",["profession:Blacksmithing"]="Задание демонстрирует необычную кузнечную технику: превращение компонентов животных в защитные лаки для обработки металлических звеньев кольчуги."},sec={{t="Союз мастеров двух фракций",b="Матиль работает на Террасе Воинов в Дарнассе, но его ремесло уходит далеко за пределы традиционных приемов ночных эльфов. Он переписывается с Фьюреном Длиннобородом, опытным оружейником-дворфом из Штормграда. Вдохновленный открытиями Фьюрена в металлургии и изготовлении доспехов, Матиль стремится выковать кольчугу, усиленную природными компонентами, способную выдерживать огромные нагрузки. Для проверки этой смешанной теории ему нужны редкие материалы, которых не найти нигде рядом с Тельдрассилом."},{t="Опасности Скального гнездовья",b="Ключ к эксперименту Матиля лежит далеко на юге за морем, в каньонах Тысячи Игл. Там, высоко над соляными равнинами и красными каменными мезами, под палящим солнцем Калимдора гнездятся виверны Скального гнездовья. Их скорлупа затвердевает от постоянного воздействия зноя и высоты. Матиль намерен растолочь эти прокаленные солнцем осколки и превратить их в прочный лак, которым покрываются звенья кольчуги, чтобы получить гибкие, но исключительно прочные доспехи."}},faq={{q="Кто такой Матиль?",a="Матиль — ночной эльф, оружейник, живущий на Террасе Воинов в Дарнассе. Он тесно сотрудничает с дворфами, вместе с Фьюреном Длиннобородом разрабатывая улучшенные кольчужные доспехи для проверенных воинов.",al={"mathiel","who gives sunscorched shells","mathiel darnassus","матиль","кто дает высохшую скорлупу","матиль дарнасс"}},{q="Зачем Матилю скорлупа виверн?",a="Скорлупа виверн Скального гнездовья обжигается и затвердевает под суровым солнцем Тысячи Игл. Матиль измельчает ее и превращает в особый лак, которым покрывает звенья кольчуги, повышая их прочность.",al={"why wyvern shells","sunscorched shell purpose","what are shells for","зачем скорлупа виверн","для чего высохшая скорлупа","для чего нужна скорлупа"}},{q="Где находится Скальное гнездовье?",a="Скальное гнездовье — крутая меза на западе Тысячи Игл, недалеко от границы с Фераласом. Виверны строят гнезда на скалах и плато.",al={"highperch location","where is highperch","how to find highperch","где скальное гнездовье","расположение скального гнездовья","как найти скальное гнездовье"}},{q="Какое отношение к этому заданию имеет Фьюрен Длиннобород?",a="Фьюрен Длиннобород — мастер-оружейник из дворфов, живущий в Штормграде. Матиль считает Фьюрена уважаемым коллегой и вдохновляется его открытиями в изготовлении доспехов в своей работе в Дарнассе.",al={"furen longbeard connection","who is furen","фьюрен длиннобород","кто такой фьюрен"}},{q="Почему эльф из Дарнасса просит материалы из Тысячи Игл?",a="Особая химическая стойкость, которая нужна Матилю, свойственна лишь яйцам виверн, подвергавшимся неумолимому сухому зною южных каньонов и мез, и ее невозможно воспроизвести среди туманных ветвей Тельдрассила.",al={"why thousand needles","darnassus to thousand needles","почему тысяча игл","из дарнасса в тысячу игл"}},{q="Что будет после того, как принести скорлупу Матилю?",a="Получив двадцать штук высохшей скорлупы, Матиль сразу приступает к изготовлению лака и ковке кольчуги на заказ в награду за ваши труды в походе.",al={"what next mathiel","after sunscorched shells","mathiel follow up","что дальше матиль","после высохшей скорлупы","продолжение задания матиля"}}},fp="18,244,33.501.0,23.484.0,15.204.0,36.215.0,27.148.0,46.195.0,70.202.0,50.169.0"}
P.entries["quest:1715"] = {n="Забитый ягненок",s="Это поручение направляет начинающих гномов-чернокнижников из Стальгорна на поиски углубленного обучения в землях людей. Поскольку король Магни Бронзобород строго следит за темными практиками в горе дворфов, наставникам приходится полагаться на тайные связи в Штормграде, чтобы завершить обучение своих учеников.",h="Это поручение направляет начинающих гномов-чернокнижников из Стальгорна на поиски углубленного обучения в...",kw={"gakin the darkbinder","gnomeregan","ironforge","lago blackwrench","mage quarter","slaughtered lamb","stormwind","warlock","гакин темнопряд","гномреган","стальгорн","лаго злобноверт","квартал магов","забитый ягненок","штормград","чернокнижник"},ang={["class:Warlock"]="Это путешествие — важный обряд посвящения для молодых чернокнижников Альянса, знакомящий их с тайной подпольной сетью, которая связывает практиков разных рас.",["race:Dwarf"]="Власти Стальгорна совершенно нетерпимы к демоническим опытам, из-за чего чернокнижники города уходят в глубокую тень, а их ученикам приходится искать обучение в других местах.",["race:Gnome"]="Задание показывает унижение гномов в изгнании: они ютятся в тесноте Стальгорна и вынуждены полагаться на гостеприимство людей, потеряв собственные академии в Гномрегане."},sec={{t="Изгнание и надзор",b="До падения Гномрегана будущие чернокнижники Каз Модана учились у собственных механиков-магов и знатоков демонов в глубине техногорода. Катастрофа, изгнавшая гномов, разрушила эти учреждения. Уцелевшие практики оказались в тесноте мрачных подземных пещер Стальгорна под недоверчивым взглядом короля Магни Бронзоборода и стражи дворфов. Не имея возможности открыто практиковать демонические искусства и проводить опасные ритуалы в такой тесноте, старшие наставники, такие как Лаго Злобноверт, вынуждены отправлять учеников прочь."},{t="Тайный подвал Квартала магов",b="Этих учеников-изгнанников ждет «Забитый ягненок» — неприметная таверна в Квартале магов Штормграда. Под ее общим залом, за извилистыми каменными переходами и спускающимися лестницами, скрыто подземное святилище, где в тени собираются чернокнижники-люди. Под надзором опытных призывателей, таких как Гакин Темнопряд, это убежище дает место и темные принадлежности, необходимые, чтобы научить новичков призывать и подчинять младших демонов, не навлекая немедленного гнева городской стражи."},{t="Растущее напряжение в тени",b="Хотя круг Штормграда рад умелым рукам, приток новичков-беженцев создает трения. Наставникам-людям и так приходится ходить по лезвию ножа, чтобы не попасться паладинам и властям города. Гакин и его коллеги видят, что их тайное убежище все больше переполняется практиками, присланными на юг из Каз Модана. Постоянный поток из горы дворфов грозит раскрыть их скрытную деятельность, но у обеих сторон нет более простого выхода."}},faq={{q="Почему гномы-чернокнижники не могут учиться в Стальгорне?",a="Король Магни Бронзобород держит практиков в Стальгорне под пристальным наблюдением. После потери Гномрегана изгнанные чернокнижники остались без собственной тайной академии, а рискованные ритуалы призыва внутри горы дворфов слишком опасны.",al={"why send to stormwind","ironforge warlock training","why gnomeregan warlock leave","почему отправляют в штормград","обучение чернокнижников в стальгорне","почему чернокнижники гномреган уходят"}},{q="Где раньше обучали чернокнижников Каз Модана?",a="Раньше темные практики по всему Каз Модану обучались под руководством мастеров-чернокнижников в Гномрегане. Вторжение троггов и радиоактивное заражение уничтожили эти учреждения, и выжившим пришлось уйти в Стальгорн.",al={"gnomeregan warlock history","past warlock training khaz modan","история чернокнижников гномрегана","прежнее обучение чернокнижников каз модан"}},{q="Кто такой Гакин Темнопряд?",a="Гакин Темнопряд — старший чернокнижник-человек, обитающий в катакомбах под «Забитым ягненком» в Штормграде. Он учит подмастерьев подчинению и призыву демонов, в том числе начинающих гномов, присланных на юг из Стальгорна.",al={"who is gakin","gakin role","кто такой гакин","роль гакина"}},{q="Что такое «Забитый ягненок»?",a="«Забитый ягненок» — таверна в Квартале магов Штормграда. Заведение на уровне улицы выглядит обычным, но глубокий подвал под ним скрывает тайное объединение чернокнижников, действующее вдали от глаз городских властей.",al={"slaughtered lamb tavern","where is slaughtered lamb","таверна забитый ягненок","где забитый ягненок"}},{q="Почему Гакин недоволен новичками?",a="Гакин опасается, что огромный приток гномов-беженцев привлечет ненужное внимание к тайному кругу в Штормграде. Места и учителей мало, а слишком большая активность чернокнижников грозит разоблачением перед городскими властями.",al={"gakin complaining","why is gakin mad","гакин жалуется","почему гакин злится"}},{q="Кто такой Лаго Злобноверт?",a="Лаго Злобноверт — гном, наставник чернокнижников, живущий в темных переулках Стальгорна. Он озлоблен из-за потери Гномрегана и пристального надзора дворфов и отправляет многообещающих новичков в Штормград завершить их начальные договоры.",al={"lago blackwrench","quest giver slaughtered lamb","лаго злобноверт","персонаж, выдающий задание забитый ягненок"}}},fp="20,295,18.597.0,32.506.0,29.469.0,44.246.0,46.223.0,28.228.0,29.234.0,43.222.0,24.219.0"}
P.entries["quest:1716"] = {n="Пожирательница душ",s="«Пожирательница душ» — важный обряд посвящения для чернокнижников Альянса, которых отправляют из Штормграда учиться призыву суккуба. По указанию Гакина Темнопряда посвящаемые должны пересечь полмира и добраться до опасных диких земель Степей, чтобы получить совет Такара Провидца.",h="«Пожирательница душ» — важный обряд посвящения для чернокнижников Альянса, которых отправляют из Штормграда...",kw={"camp taurajo","gakin the darkbinder","heartswood","slaughtered lamb","stormwind","succubus","takar the seer","the barrens","warlock quest","лагерь таурахо","гакин темнопряд","сердцевина","забитый ягненок","штормград","суккуб","такар провидец","степи","задание чернокнижника"},ang={["class:Warlock"]="Подчинение суккуба означает переход чернокнижника к владению магией управления разумом и соблазна и требует физической отваги, чтобы добыть редкие реагенты для ритуала.",["faction:Alliance"]="Это испытание заставляет заклинателей Альянса углубляться в спорные земли Орды, что требует опасного морского путешествия и пути через континенты."},sec={{t="Опасный путь на запад",b="Под «Забитым ягненком» в Квартале магов Штормграда Гакин Темнопряд обучает многообещающих чернокнижников следующему важному призыву — суккубу. Это демоническое существо, описываемое как пожирательница душ, губительница сердец и повелительница разума, не может быть призвано в Азерот вслепую. Нужна сильная приманка — предмет, связанный с чистой любовью, — чтобы выманить ее из Круговерти Пустоты, и практик смог победить и подчинить ее. Добыть такой знак можно лишь с помощью мудрости, которой в кругах Штормграда нет."},{t="Провидец на враждебной земле",b="Чтобы найти нужный катализатор, Гакин отправляет учеников через Великое море в Калимдор. В глубине засушливых просторов Степей, возле поселения Орды Лагерь Таурахо, обитает Такар Провидец. Чернокнижнику Альянса, чтобы добраться до Такара, нужно пройти через дикую местность, где рыщут враждебные кентавры, свинобразы и воины Орды. Это негласное испытание на выживание еще до начала подготовки ритуала."}},faq={{q="Какова цель этого задания?",a="Это задание отправляет чернокнижников Альянса из Штормграда в Калимдор, чтобы научиться призывать и подчинять прислужницу-суккуба, полностью подвластную их приказам.",al={"why do devourer of souls","succubus quest goal","warlock succubus questline","зачем пожирательница душ","цель задания суккуба","цепочка заданий суккуба чернокнижника"}},{q="Почему мне нужно идти так далеко, в Степи?",a="Гакин Темнопряд знает, что для призыва суккуба нужен эмоциональный катализатор — символ чистой любви, — чтобы выманить демона из другого мира. Такар Провидец, живущий в Степях, обладает особыми тайными знаниями, нужными для поиска такого артефакта.",al={"why kalimdor","why go to the barrens","why send me so far","почему калимдор","почему идти в степи","почему посылают так далеко"}},{q="Кто такой Гакин Темнопряд?",a="Гакин — мастер-призыватель, скрывающийся в катакомбах под «Забитым ягненком» в Штормграде. Он обучает начинающих чернокнижников демоническим договорам, подчинению и темным искусствам вдали от любопытных глаз городской стражи.",al={"gakin darkbinder lore","who gives quest devourer of souls","предания о гакине темнопряде","кто выдает задание пожирательница душ"}},{q="Кто такой Такар Провидец?",a="Такар Провидец — мистик, живущий в центральных Степях, неподалеку от аванпоста тауренов Лагерь Таурахо. Он помогает странствующим чернокнижникам, указывая им реликвии, нужные, чтобы заманить демонов в Азерот.",al={"where is takar the seer","takar seer lore","где такар провидец","предания о такаре провидце"}},{q="Почему для призыва суккуба нужен символ любви?",a="Как объясняет Гакин, суккуб живет развращением сердец и подчинением разума. Ее по природе тянет пожирать подлинную, чистую привязанность, поэтому романтические реликвии — единственная действенная приманка, чтобы вытащить ее из Круговерти Пустоты.",al={"why love for succubus","succubus lure lore","bait for succubus","почему любовь для суккуба","приманка суккуба","приманка для суккуба"}},{q="Безопасны ли Степи для персонажа Альянса?",a="Нет. Степи — территория Орды, где полно враждебных зверей, племен свинобразов и поселений Орды, таких как Лагерь Таурахо. Путникам Альянса нужно держаться неприметно и обходить стражу, разыскивая Такара.",al={"is barrens dangerous","will horde attack me in barrens","опасны ли степи","нападет ли орда в степях"}}},fp="17,292,24.541.0,29.431.0,34.141.0,47.259.0,28.213.0,22.215.0,55.223.0,46.216.0"}
P.entries["quest:1717"] = {n="Приглашение Гакина",s="«Приглашение Гакина» — вызов, доставляемый многообещающим чернокнижникам Альянса в Стальгорне и направляющий их на юг, в Штормград. Гакин Темнопряд ждет под Кварталом магов города, чтобы направить их продвижение к власти над могущественными демонами.",h="«Приглашение Гакина» — вызов, доставляемый многообещающим чернокнижникам Альянса в Стальгорне и направляющий...",kw={"gakin","gakin's summons","ironforge","lago blackwrench","mage quarter","slaughtered lamb","succubus","warlock","гакин","приглашение гакина","стальгорн","лаго злобноверт","квартал магов","забитый ягненок","суккуб","чернокнижник"},ang={["class:Warlock"]="Это вводное задание направляет чернокнижников в Стальгорне обратно в Штормград, чтобы начать многоэтапную цепочку ритуальных заданий по подчинению прислужницы-суккуба.",["faction:Alliance"]="Показывает, как тайная сеть чернокнижников поддерживает связь между столицами Альянса, занимаясь демонологией в секрете от посторонних глаз.",["race:Gnome"]="Гномов-чернокнижников, обучающихся у Лаго Злобноверта в Стальгорне, направляют в подземную сеть Штормграда за более глубокими демоническими знаниями."},sec={{t="Весть из подполья",b="Демонология остается практикой, которой во всех землях Альянса занимаются исключительно в тени. В Стальгорне Лаго Злобноверт негласно присматривает за странствующими практиками от имени братства в Штормграде. Когда чернокнижник достаточно овладевает своими первыми прислужниками, весть разносится быстро. Лаго передает приказ: бросить все дела, что держат вас в заснеженных горах Каз Модана, и без промедления явиться на юг."},{t="Возвращение в «Забитый ягненок»",b="Глубоко под булыжниками Квартала магов Штормграда, под таверной «Забитый ягненок», Гакин Темнопряд руководит развитием чернокнижников города. Гакин считает каждого способного ученика ценным, но опасным вложением. Получение его приглашения знаменует порог истинного подчинения демонов и начало испытаний, нужных, чтобы покорить суккуба из Круговерти Пустоты."}},faq={{q="Кто присылает мне это приглашение?",a="Лаго Злобноверт, наставник чернокнижников в Стальгорне, доставляет приглашение от имени Гакина Темнопряда, руководящего обучением демонологии в Штормграде.",al={"who gives quest","who starts this","lago blackwrench","кто выдает задание","кто начинает это задание","лаго злобноверт"}},{q="Где найти Гакина Темнопряда?",a="Гакин скрывается в темных извилистых катакомбах под «Забитым ягненком» — таверной, спрятанной в Квартале магов Штормграда.",al={"gakin location","where is gakin","slaughtered lamb location","где гакин","расположение гакина","где забитый ягненок"}},{q="Почему Гакин вызывает меня?",a="Вы достаточно продвинулись в своем ремесле, чтобы провести ритуалы призыва и подчинения суккуба и расширить свой демонический арсенал.",al={"quest purpose","what is this for","why summoned","цель задания","для чего это","почему вызывают"}},{q="Что будет после разговора с Гакином?",a="Гакин даст вам задание «Пожирательница душ» и отправит в опасные земли за ритуальными компонентами, нужными, чтобы призвать и подчинить суккуба.",al={"next step","what follows this","quest chain","следующий шаг","что дальше","цепочка заданий"}},{q="Почему чернокнижник из Стальгорна подчиняется приказам из Штормграда?",a="Чернокнижники Альянса по необходимости действуют как скрытная тайная сеть. Практики Стальгорна и Штормграда поддерживают связь и направляют многообещающих подмастерьев к Гакину, у которого под «Забитым ягненком» есть особое ритуальное снаряжение и знания.",al={"ironforge warlocks","gnome warlocks stormwind","warlock organization","чернокнижники стальгорна","гномы-чернокнижники штормград","организация чернокнижников"}},{q="Можно ли игнорировать это приглашение, если я хочу остаться в Каз Модане?",a="Вы можете отложить поездку в Штормград, но научиться призывать суккуба, не пройдя испытание Гакина, нельзя, поэтому путь необходим любому начинающему чернокнижнику.",al={"is this required","can i skip","do i need to go to stormwind","обязательно ли это","можно ли пропустить","нужно ли идти в штормград"}}},fp="15,220,30.427.0,30.399.0,26.160.0,37.136.0,26.144.0,36.165.0,59.260.0,58.166.0"}
P.entries["quest:1718"] = {n="Островитянин",s="«Островитянин» — приглашение, которое опытные наставники воинов по всему Азероту передают тем, кто доказал свою основную доблесть в бою. Оно направляет растущих бойцов на Остров Битв у Торгового побережья, где замкнутое братство воинов испытывает равных себе в грубом бою. Встреча с главным воином Кланноком Маклеодом — важный шаг к овладению продвинутыми боевыми умениями.",h="«Островитянин» — приглашение, которое опытные наставники воинов по всему Азероту передают тем, кто доказал...",kw={"fray island","klannoc macleod","merchant coast","ratchet","the affray","the barrens","the islander","warrior","остров битв","кланнок маклеод","торговое побережье","кабестан","побоище","степи","островитянин","воин"},ang={["class:Warrior"]="Это испытание доступно только воинам и отмечает важный переход от изучения базовых приемов к раскрытию всей свирепости и тактической гибкости стоек ветерана.",["faction:Alliance"]="Воинам Альянса приходится пересекать море или пробираться через дебри Калимдора, чтобы добраться до Острова Битв, и проявлять боевую преданность в суровом приграничье, вдали от оплотов людей и дворфов.",["faction:Horde"]="Воины Орды отправляются из Громового Утеса или Оргриммара в Степи, чтобы доказать свою силу вдали от бдительных глаз вождей."},sec={{t="Собрание клинков",b="Наставники воинов в столицах как Альянса, так и Орды понимают, когда ученик перерос базовые упражнения. Для боевого роста важны не формальные звания и не политическая верность: бойцам необходимо мериться силами с достойными противниками. Путь уводит воинов от цивилизованных тренировочных площадок к суровому острову, затерянному в Великом море."},{t="Остров Битв и Торговое побережье",b="Остров Битв лежит к востоку от Торгового побережья, чуть южнее гоблинского порта Кабестан в Степях. Добраться до него можно вплавь, через воды над затонувшими песчаными отмелями. На этой скале политические узы теряют значение, уступая место боевому братству: бойцы собираются под взглядом Кланнока Маклеода, главного воина острова, и ждут любого жестокого испытания, которое он сочтет нужным."}},faq={{q="Что такое Остров Битв?",a="Остров Битв — скалистый остров у Торгового побережья в Степях, к югу от Кабестана. Это уединенная арена испытаний, где воины со всего Азерота собираются, чтобы оттачивать мастерство, сражаться в учебных боях и проходить изнурительные испытания вдали от гражданской власти.",al={"where is fray island","fray island lore","fray isle","где находится остров битв","остров битв предания","остров битв история"}},{q="Кто такой Кланнок Маклеод?",a="Кланнок Маклеод — главный воин, возглавляющий Остров Битв. Он оценивает претендентов, добравшихся до острова, и решает, достойны ли их дух и умение дальнейшего наставления на пути воина.",al={"who is klannoc","klannoc macleod role","macleod warrior","кто такой кланнок","кланнок маклеод","маклеод воин"}},{q="Почему наставники и Орды, и Альянса отправляют воинов сюда?",a="Истинное боевое мастерство выходит за рамки границ фракций. Мастера-наставники Оргриммара, Штормграда, Громового Утеса и Стальгорна понимают, что настоящее боевое умение нужно испытывать в безудержной схватке, а Остров Битв служит негласной ареной испытаний для любого воина, способного пережить его вызовы.",al={"why do both factions go here","is fray island neutral","horde and alliance fray island","почему обе фракции едут сюда","остров битв нейтральный","орда и альянс остров битв"}},{q="Как добраться до Острова Битв с материка?",a="Двигайтесь на юг вдоль Торгового побережья от портового города Кабестан в Степях. От берега пройдите по песчаным отмелям и плывите на восток через открытую воду к острову.",al={"how to get to fray island","fray island directions","finding fray island","как добраться до острова битв","остров битв как пройти","где найти остров битв"}},{q="Что происходит после встречи с Кланноком Маклеодом?",a="Когда Кланнок убеждается, что вы проделали путь, и оценивает вашу решимость, он предлагает вам принять участие в Побоище — суровом испытании, проверяющем вашу выносливость в бою против волн противников.",al={"what comes after the islander","klannoc macleod next quest","что после островитянина","кланнок маклеод следующее задание"}}},fp="12,393,21.364.0,34.375.0,20.263.0,23.232.0,64.296.0,47.188.0,43.199.1"}
P.entries["quest:1719"] = {n="Побоище",s="«Побоище» — жестокое боевое испытание на Острове Битв у побережья Степей. Эта схватка на арене, которой руководит Кланнок Маклеод, сталкивает честолюбивых воинов с волнами островных бойцов и их чемпионом, чтобы доказать, что у них достаточно доблести для продвинутого обучения.",h="«Побоище» — жестокое боевое испытание на Острове Битв у побережья Степей.",kw={"affray","barrens","big will","fray island","klannoc macleod","twiggy flathead","warrior trial","побоище","степи","большой уилл","остров битв","кланнок маклеод","пруттик плоскоголов","испытание воина"},ang={["class:Warrior"]="Побоище — важнейший обряд посвящения для опытных воинов, горнило, где они доказывают свои стойки и боевую выносливость, чтобы открыть более глубокое мастерство."},sec={{t="Арена испытаний в Великом море",b="Остров Битв стоит особняком от борьбы на материке и служит убежищем для закаленных бойцов, изгоев и боевых наставников. Кланнок Маклеод учит не каждого бродягу, сошедшего с лодки. Чтобы заслужить его наставничество, будущие воины должны пройти Побоище — открытое испытание боевой выносливости и чувства поля боя, призванное отделить настоящих бойцов от хвастливых притворщиков."},{t="Круг железа и крови",b="Правила Побоища просты и безжалостны. Встав на центральную железную решетку среди собравшихся зрителей, воин подает знак распорядителю Пруттику Плоскоголову начинать состязание. Противники выходят на ринг один за другим, проверяя выносливость новичка. Те, кто пережил первых бойцов, встречаются с чемпионом-тяжеловесом острова, Большим Уиллом, победа над которым — единственное условие для получения уважения Кланнока."}},faq={{q="Что такое Побоище?",a="Побоище — испытание в формате арены на Острове Битв. Оно проверяет, хватит ли будущему воину выносливости и умения для продвинутого боевого обучения у Кланнока Маклеода.",al={"affray trial","what is the affray","fray island arena","испытание побоища","что такое побоище","арена острова битв"}},{q="Где проходит Побоище?",a="Оно проходит на Острове Битв — суровом острове у восточного побережья Степей в Великом море.",al={"where is the affray","affray location","где побоище","место проведения побоища"}},{q="Кто организует испытание?",a="Наставник воинов Кланнок Маклеод руководит бойцами острова и определяет ход испытания, а Пруттик Плоскоголов управляет боями у края ямы.",al={"who runs the affray","affray organizer","кто проводит побоище","организатор побоища"}},{q="Как проходят бои на ринге?",a="Воин встает на центральную железную решетку, давая знак о готовности. Затем Пруттик Плоскоголов выпускает в яму волны бойцов Побоища и наконец выпускает могучего чемпиона острова, Большого Уилла.",al={"how does the fight work","affray waves","starting the affray","как проходит бой","волны побоища","начать побоище"}},{q="Кто такой Большой Уилл?",a="Большой Уилл — действующий чемпион бойцов Острова Битв. Победа над ним на ринге — последнее условие для прохождения Побоища.",al={"big will","who is big will","fray island champion","большой уилл","кто такой большой уилл","чемпион острова битв"}},{q="Почему воины должны проходить это испытание?",a="Кланнок Маклеод отказывается обучать своим боевым приемам тех, кто не доказал свою стойкость в крови и бою против нескольких противников.",al={"why do the affray","affray purpose","зачем проходить побоище","цель побоища"}}},fp="10,285,33.402.0,28.428.0,19.184.0,33.108.0,24.152.0,37.197.0,16.131.0,38.148.0"}
P.entries["quest:173"] = {n="Воргены в лесу",s="Калор, разочарованный бывший стражник из Темнолесья, поручает искателям приключений истребить зловещих ткачей теней Ночной Погибели, рыскающих в Сумеречном лесу. Выйдя на охоту в Светлую рощу и Гниющий сад, чужаки могут доказать свою доблесть охотникам на чудовищ мастера Джонотана Карвина.",h="Калор, разочарованный бывший стражник из Темнолесья, поручает искателям приключений истребить зловещих ткачей...",kw={"brightwood grove","calor","carevin","darkshire","duskwood","nightbane","rotting orchard","shadow weaver","worgen","светлая роща","калор","карвин","темнолесье","сумеречный лес","ночная погибель","гниющий сад","ткач теней","воргены"},ang={["class:Hunter"]="Охота на созданий Ночной Погибели предельно проверяет навыки выслеживания и знание зверей: воргены — не обычные животные и не простые люди-разбойники, а двуногие ужасы, владеющие заклинаниями тени.",["faction:Alliance"]="Темнолесье кажется совершенно брошенным верховной властью Штормграда, и жителям с борцами вроде Калора приходится вербовать любого странствующего искателя приключений Альянса, способного сдержать чудовищ.",["race:Human"]="Для людей из Элвиннского леса или Западного Края зрелище трагического разорения ферм Сумеречного леса, таких как Гниющий сад, служит мрачным предостережением о том, на что способна неудержимая темная магия в житницах королевства."},sec={{t="Личное бдение",b="Ночной Дозор постоянно борется с нежитью, пауками и разбойниками, теснящими границы Темнолесья. Некоторым, как Калору, официальная стража показалась слишком медлительной и самодовольной, чтобы очистить землю. Покинув Дозор, Калор примкнул к мастеру Джонотану Карвину, посвятив свой клинок полному искоренению ереси и порчи. Но Карвин принимает в свой круг не всякого: те, кто хочет помочь их делу, должны сначала доказать, что способны выжить среди самых свирепых ужасов леса."},{t="Затаившиеся твари Ночной Погибели",b="Испытательная площадка находится в Светлой роще и на зачумленном Гниющем саде, где властвуют дикие волкоподобные звери — воргены. Среди них ткачи теней Ночной Погибели используют темную магию, чтобы ослеплять и опутывать жертв перед тем, как растерзать их. Калор посылает начинающих охотников истреблять этих чародейных зверей — и чтобы проверить решимость чужака, и чтобы сократить угрозу, чье происхождение глубоко тревожит защитников Темнолесья."},{t="Чудовища из ниоткуда",b="Хотя волки-люди стали неизбежным кошмаром Сумеречного леса, их появление не поддается объяснению. Калор отмечает, что воргены словно появились из воздуха, не имея в этих краях естественного происхождения. В отличие от голодных диких волков или ходячих мертвецов, восставших из местных курганов, эти двуногие хищники владеют странным и чуждым колдовством. Убийство ткачей теней демонстрирует боевое мастерство, но лишь касается поверхности неестественного нашествия, укореняющегося по всему лесу."}},faq={{q="Кто такой Калор?",a="Калор — охотник и бывший член Ночного Дозора Темнолесья. Разочаровавшись в осторожной бюрократии городского ополчения, он присоединился к мастеру Джонотану Карвину, чтобы активно выслеживать мерзких тварей, угрожающих Сумеречному лесу.",al={"calor","calor darkshire","who gives worgen in the woods","калор","калор темнолесье","кто дает задание воргены в лесу"}},{q="Почему Калор хочет убить ткачей теней Ночной Погибели?",a="Калор использует ткачей теней Ночной Погибели как испытание умения и смелости. Каждый, кто хочет помочь делу мастера Карвина, должен показать, что способен охотиться на опасных воргенов-чародеев, а не просто говорить о защите города.",al={"why kill shadow weavers","worgen in the woods goal","зачем убивать ткачей теней","воргены в лесу цель"}},{q="Где находятся ткачи теней Ночной Погибели?",a="Они бродят в двух основных местах к западу и юго-западу от Темнолесья: среди искривленных деревьев Светлой рощи и на заброшенных, заросших землях Гниющего сада.",al={"where are nightbane shadow weavers","shadow weaver location","где ткачи теней ночной погибели","где найти ткачей теней"}},{q="Откуда появились воргены в Сумеречном лесу?",a="Их внезапное появление остается загадкой для жителей Сумеречного леса. По словам Калора, звери словно возникли из ниоткуда, принеся темную магию теней и голодную ярость в лес, уже стоящий на грани гибели.",al={"worgen origin duskwood","why are worgen in duskwood","where do worgen come from","происхождение воргенов сумеречный лес","почему воргены в сумеречном лесу","откуда взялись воргены"}},{q="Кто такой мастер Карвин?",a="Мастер Джонотан Карвин — независимый охотник на чудовищ из Темнолесья. Он и его последователи действуют вне Ночного Дозора, напористо истребляя зло, нежить и странных чудовищ по всему краю.",al={"carevin","master carevin","who is master carevin","карвин","мастер карвин","кто такой мастер карвин"}},{q="Почему Калор покинул Ночной Дозор?",a="Калор разочаровался в том, что считал пассивностью и самодовольством Ночного Дозора. Вместо того чтобы охранять границы, пока тьма смыкается, он предпочел деятельный подход Карвина к охоте на зло.",al={"why did calor leave the watch","calor night watch","почему калор ушел из дозора","калор ночной дозор"}}},fp="19,294,15.526.0,21.451.0,21.485.1,13.230.0,52.237.0,45.160.0,43.222.0,22.228.0,36.213.0"}
P.entries["quest:1738"] = {n="Сердцедрево",s="«Сердцедрево» — задание чернокнижников Альянса, которое уводит их вглубь Ясеневого леса за ветвью древнего трагического дерева. Отшельник Такар Провидец по поручению Гакина Темнопряда отправляет чернокнижников за этой романтической реликвией: она послужит мощной приманкой, чтобы выманить и подчинить суккуба в Штормграде.",h="«Сердцедрево» — задание чернокнижников Альянса, которое уводит их вглубь Ясеневого леса за ветвью древнего...",kw={"anathera","ashenvale","barrens","dark strand","gakin the darkbinder","heartswood","latherion","ordil'aran","succubus","takar the seer","анатера","ясеневый лес","степи","темная нить","гакин темнопряд","сердцедрево","латерион","ордил'аран","суккуб","такар провидец"},ang={["class:Warlock"]="Получение частицы Сердцедрева — важная веха для начинающих чернокнижников: она позволяет призвать и подчинить суккуба, который на поле боя манипулирует разумом врагов.",["faction:Alliance"]="Поход в Калимдор подвергает молодых заклинателей Альянса опасностям спорных диких земель, враждебных застав Орды и древних руин ночных эльфов.",["race:Human"]="Скрытые чернокнижники Штормграда часто полагаются на дальних разведчиков вроде Такара Провидца, чтобы найти реликвии древнего Калимдора, которые человеческие маги никогда не описывали."},sec={{t="Памятник трагической любви",b="По словам Такара Провидца, дерево Сердцедрево выросло на месте, где десять тысяч лет назад, во время Войны Древних, вместе пали двое влюбленных ночных эльфов — Анатера и Латерион. Питаемое их последними вздохами и вечной преданностью, дерево выросло чистым символом бессмертной любви. Для смертных это священный трагический памятник, но для приверженцев темных искусств сконцентрированная эмоциональная энергия — мощное магическое топливо."},{t="Приманка для суккуба",b="Суккубы питаются смертными страстями, желанием и душевными муками. Такар понимает, что обычные соблазны бледнеют рядом с артефактом, пропитанным тысячелетиями чистой, неугасающей преданности. Частица Сердцедрева дает Гакину Темнопряду именно тот катализатор, который нужен, чтобы выманить одного из этих хитрых демонов через Пустоту в круг призыва в Квартале магов Штормграда."},{t="Руины Ордил'Арана",b="Дерево растет среди Руин Ордил'Арана на северо-западе Ясеневого леса. Но чтобы добыть его, придется противостоять не только диким зверям и враждебным землям, но и сектантам Темной Нити, занявшим эльфийские руины. Когда древесина будет добыта, ее нужно доставить через моря обратно в «Забитый ягненок» в Штормграде, чтобы начать ритуал подчинения."}},faq={{q="Почему чернокнижникам нужно Сердцедрево, чтобы призвать суккуба?",a="Суккубы — демоны, которых привлекают страсть, желание и сильные эмоциональные узы. Сердцедрево проросло там, где десять тысяч лет назад вместе погибли двое преданных друг другу ночных эльфов. Их неугасшая страсть пропитала древесину, создав идеальную духовную приманку, чтобы провести суккуба через Пустоту.",al={"why heartswood","succubus bait","why wood for succubus","зачем сердцедрево","приманка для суккуба","зачем дерево для суккуба"}},{q="Где растет дерево Сердцедрево?",a="Оно находится в Руинах Ордил'Арана на северо-западе Ясеневого леса, неподалеку к югу от Темных берегов. Эта местность попала в руки зловещих сектантов.",al={"heartswood location","where is the heartswood","where to find heartswood","где сердцедрево","где находится сердцедрево","где найти сердцедрево"}},{q="Кто такие Анатера и Латерион?",a="Это двое ночных эльфов, которые сражались бок о бок во время Войны Древних. Когда они вместе пали на поле боя, на том самом месте, где они сделали последние вздохи, выросло Сердцедрево — памятник их нерушимой любви.",al={"anathera and latherion","who were the lovers","lovers of ashenvale","анатера и латерион","кто были влюбленные","влюбленные ясеневого леса"}},{q="Кто такой Такар Провидец?",a="Такар — одаренный человек-провидец, союзник чернокнижников Штормграда. Он живет уединенным отшельником на юге Степей возле Лагеря Таурахо и с помощью мистического зрения проникает сквозь туман времени, разыскивая забытые реликвии для Гакина Темнопряда.",al={"who is takar","takar the seer","barrens hermit","кто такой такар","такар провидец","отшельник степей"}},{q="Как чернокнижнику Альянса безопасно добраться до Ясеневого леса из Степей?",a="Путникам Альянса, идущим из Степей, нужно обходить хорошо охраняемый форпост Орды — Заставу Мор'шан. Чернокнижники часто проскальзывают через неохраняемую брешь в частоколе к востоку от главных ворот, идут по верхней дороге через Когтистые горы или переплывают пограничную реку.",al={"how to get to ashenvale","bypassing morshan","avoiding horde rampart","как попасть в ясеневый лес","обход мор'шан","обойти заставу орды"}},{q="Что происходит после того, как Гакин получает Сердцедрево?",a="Гакин использует древесину, чтобы подготовить ритуал в катакомбах под «Забитым ягненком» в Штормграде. Он чертит круг призыва, чтобы вытянуть суккуба из Круговерти Пустоты, а чернокнижнику поручает победить и подчинить ее.",al={"what next after heartswood","what does gakin do with heartswood","что дальше после сердцедрева","что гакин делает с сердцедревом"}}},fp="10,301,25.441.0,20.398.0,23.359.1,53.288.0,36.177.0,32.249.0,22.254.0,73.271.0,49.228.0"}
P.entries["quest:1739"] = {n="Связывание",s="«Связывание» — заключительный обряд посвящения для чернокнижников Альянса, желающих подчинить суккуба в Штормграде. С помощью зачарованной сердцевины, добытой из Сердцедрева, чернокнижник входит в круг призыва под «Забитым ягненком», чтобы извлечь демона и физически одолеть его. После поражения воля демона скована, и он обязан служить призвавшему.",h="«Связывание» — заключительный обряд посвящения для чернокнижников Альянса, желающих подчинить суккуба в...",kw={"binding","crypt","darkbinder","gakin","heartswood","slaughtered lamb","stormwind","succubus","summoning circle","связывание","склеп","темнопряд","гакин","сердцедрево","забитый ягненок","штормград","суккуб","круг призыва"},ang={["class:Warlock"]="Этот обряд — важная веха для чернокнижников-людей и гномов: от управления безмозглыми бесами и демонами Бездны они переходят к повелеванию разумными, расчетливыми демонами.",["faction:Alliance"]="Само существование этого ритуала глубоко под Штормградом показывает, как Альянс тайно терпит магию Тьмы в укромных нишах вопреки доктринам Церкви."},sec={{t="Спуск в склеп",b="Под половицами «Забитого ягненка» в Квартале магов Штормграда скрыт огромный склеп, посвященный запретным искусствам. Вдали от бдительных глаз городской стражи и Собора Света тайный круг чернокнижников города проводит здесь свои опаснейшие ритуалы. Высеченные в камне круги призыва направляют первозданные силы Пустоты, позволяя честолюбивым посвященным прорвать завесу между мирами."},{t="Подчинение искусительницы",b="Призыв суккуба требует гораздо большего, чем просто произнесение заклинаний. Чернокнижник должен принести фокус — здесь это подготовленная сердцевина сердцедрева — и совершить у круга ритуал прорыва. Суккубы, как известно, развращают, соблазняют и подавляют даже закаленный разум. Чтобы установить полное господство, призывающий должен сразить тварь в одиночном бою, изгнав ее физическую форму обратно в Круговерть Пустоты и закрепив истинную связь с ней."},{t="Тайны Гакина",b="Убив призванное существо, торжествующий посвященный приносит истощенную сердцевину Гакину Темнопряду. Доказав и силу духа, и боевое мастерство, ученик получает основополагающие знания, необходимые, чтобы призывать суккуба через пустоту, когда потребуется. Этот ритуал знаменует превращение чернокнижника Альянса в опытного мастера, способного управляться с непокорными разумными демонами."}},faq={{q="Где проходит призыв?",a="Ритуал проходит в глубоких катакомбах под «Забитым ягненком» — неприметной таверной в Квартале магов Штормграда. Чернокнижники спускаются по винтовой лестнице мимо трактирного погреба в подземное святилище с арканными кругами призыва.",al={"where do i summon","succubus summoning location","crypt location","где призывать","место призыва суккуба","где склеп"}},{q="Для чего нужна сердцевина сердцедрева?",a="Сердцевина сердцедрева служит якорем и катализатором. Она взята из Сердцедрева — дерева, выросшего в Ясеневом лесу там, где во время Войны Древних пали двое влюбленных ночных эльфов, — и дает точный духовный резонанс, нужный, чтобы открыть местный разрыв и выманить суккуба через Круговерть Пустоты.",al={"why heartswood core","what does heartswood do","зачем сердцевина сердцедрева","для чего сердцедрево"}},{q="Почему чернокнижник должен убить суккуба?",a="Демоны Пустоты подчиняются только превосходящей воле и силе. Суккуб специализируется на психологическом манипулировании и подчинении разума; позволить ей явиться без немедленного поражения — значит навлечь гибель. Убийство существа в бою утверждает господство, насильственно запечатлевая власть чернокнижника в духе, пока он вновь собирается в Пустоте.",al={"why do i fight the succubus","why kill the demon to bind it","зачем драться с суккубом","зачем убивать демона для связывания"}},{q="Кто такой Гакин Темнопряд?",a="Гакин Темнопряд — старший чернокнижник, живущий в «Забитом ягненке», который руководит обучением практиков Альянса в Штормграде. Он координирует тайное добывание артефактов демонологии и оценивает, хватит ли послушникам силы воли, чтобы подчинять демонические сущности.",al={"who is gakin","gakin darkbinder lore","кто такой гакин","гакин темнопряд предания"}},{q="Кто такая Сурена, о которой говорит Гакин?",a="Сурена Каледон была бывшей ученицей Гакина, сбежавшей с Братством Справедливости; ее ожерелье вы нашли ранее. Гакин с усмешкой гадает, не была ли она суккубом в обличье человека, посланным исказить его разум, но затем решает, что слишком ее переоценивает.",al={"surena reference","who was surena","упоминание сурены","кто была сурена"}},{q="Разрешены ли суккубы на улицах Штормграда?",a="Открытая демонология строго запрещена Церковью Священного Света и властями королевства. Хотя по игровой механике подчиненные демоны могут следовать за чернокнижниками по городу, в преданиях эта практика ограничена тенями, подвалами и укромными святилищами, такими как склепы «Забитого ягненка».",al={"can guards see my succubus","is demon summoning legal in stormwind","видит ли стража моего суккуба","законен ли призыв демонов в штормграде"}}},fp="11,370,22.421.0,26.440.0,15.398.1,36.258.0,43.307.0,39.356.0,28.297.0,34.235.0,50.298.0"}
P.entries["quest:174"] = {n="Взгляни на звезды",s="«Взгляни на звезды» начинает затею Виктора Призм’Антраса заглянуть за жуткий полог Сумеречного леса. Полагая, что темное проклятие леса объясняется научно, а не тайной магией и суевериями, Виктор поручает вам собрать детали для телескопа, разработанного его соратником-гномом.",h="«Взгляни на звезды» начинает затею Виктора Призм’Антраса заглянуть за жуткий полог Сумеречного леса.",kw={"bronze tube","cog","darkshire","duskwood","look to the stars","telescope","viktori prism'antras","бронзовая трубка","зубец","темнолесье","сумеречный лес","взгляни на звезды","телескоп","виктор призм’антрас"},ang={["faction:Alliance"]="Пока патрули Ночного Дозора отражают ужасы на дорогах Темнолесья, проект Виктора — маленькая упрямая надежда города понять, что отравило их дом.",["profession:Engineering"]="Все предприятие держится на гномьих чертежах и искусной работе с металлом и дает мастерам-изобретателям возможность напрямую помочь астрономическим изысканиям Виктора.",["race:Gnome"]="Виктор полагается на изобретательность своего соратника-гнома Зубца, что показывает, как гномье ремесло приносит порядок и разум даже в самые темные уголки королевства."},sec={{t="Поиски в небесах",b="Среди мрака и страха, окутавших Темнолесье, Виктор Призм’Антрас смотрит на беды Сумеречного леса совсем иначе. Вместо того чтобы объяснять порчу земли черной магией, проклятиями или неупокоенными мертвецами, Виктор подозревает, что высшие истины скрыты высоко над кронами. По чертежам своего партнера-гнома Зубца он берется построить оптический прибор, способный заглянуть в небеса."},{t="Вопрос инженерии",b="Чтобы начать сборку прибора для наблюдения за звездами, Виктору нужен прочный каркас. Следуя указаниям Зубца, он просит путников раздобыть обработанную бронзовую трубку. Этот первый шаг опирается на изобретательность смертных механиков, а не на колдовство, и подчеркивает упрямую уверенность Виктора, что практическое ремесло и наблюдение могут пролить свет там, где мистика потерпела неудачу."}},faq={{q="Кто такой Виктор Призм’Антрас?",a="Виктор Призм’Антрас — ученый житель Темнолесья. В отличие от многих местных, парализованных страхом или одержимых суевериями, он ищет рациональные объяснения порче, охватившей Сумеречный лес, изучая звезды.",al={"viktori","who gives look to the stars","viktori prismantras","виктор","кто дает взгляни на звезды","виктор призм’антрас"}},{q="Зачем Виктору строить телескоп?",a="Виктор верит, что за магией есть осязаемая истина, объясняющая странное превращение Сумеречного леса. Он надеется, что взгляд в небо через телескоп откроет то, что упустили местные легенды и заклинатели.",al={"why look at stars","why bronze tube duskwood","telescope quest darkshire","зачем смотреть на звезды","зачем бронзовая трубка сумеречный лес","задание телескоп темнолесье"}},{q="Кто такой Зубец?",a="Зубец — гном-инженер и друг Виктора. Он составил механические чертежи, необходимые для постройки прибора для наблюдения за звездами.",al={"cog gnome","who designed telescope","зубец гном","кто спроектировал телескоп"}},{q="Где достать бронзовую трубку?",a="Бронзовую трубку обычно изготавливают инженеры со средним опытом. Путники, не владеющие инженерным делом, часто получают ее по обмену, на аукционе или у странствующих торговцев-инженеров, у которых оказался запасной экземпляр.",al={"how to get bronze tube","bronze tube location","where find bronze tube","как получить бронзовую трубку","где бронзовая трубка","где найти бронзовую трубку"}},{q="Это часть длинной цепочки заданий?",a="Да. Это задание — первый шаг многоэтапной работы по сборке и настройке прибора Виктора для наблюдения за звездами в Темнолесье.",al={"look to the stars chain","how many look to the stars quests","цепочка взгляни на звезды","сколько заданий взгляни на звезды"}},{q="Почему Виктор ищет естественные объяснения в Сумеречном лесу?",a="Хотя лес кишит нежитью и темными чарами, Виктор считает, что превращением все же могут управлять фундаментальные космические или природные законы, и потому ищет ответы в изучении небес.",al={"why scientific explanation duskwood","magic vs science duskwood","научное объяснение сумеречный лес","магия против науки сумеречный лес"}}},fp="17,288,19.432.0,23.382.0,28.217.0,43.230.0,11.130.0,36.237.0,35.128.0,60.201.0"}
P.entries["quest:1740"] = {n="Шар Соран'рука",s="Шар Соран'рука — испытание для чернокнижников, которое дает отшельник Доан Кархан на юге Степей. Начинающие чернокнижники разыскивают по всему Азероту разбитые демонические реликвии, чтобы собрать сосуд, в котором заключена сущность опозоренного демона.",h="Шар Соран'рука — испытание для чернокнижников, которое дает отшельник Доан Кархан на юге Степей.",kw={"blackfathom","demon","doan karhan","orb of soran'ruk","orb of zargain","shadowfang","soranruk","warlock","непроглядная пучина","демон","доан кархан","шар соран'рука","сфера заргейна","крепость темного клыка","соран'рук","чернокнижник"},ang={["class:Warlock"]="Восстановление Соран'рука — важная веха для чернокнижников: оно учит их, как Легион держит в повиновении собственных созданий и как связанных демонов можно превратить в действующие орудия.",["faction:Horde"]="Доан Кархан живет в суровых Степях, поэтому южные равнины — важная цель для странствующих чародеев, ищущих тайные знания."},sec={{t="Сосуды опозоренных",b="В иерархии Пылающего Легиона за неудачу наказывают вечно. Когда младшие демоны теряют расположение своих повелителей, их души связывают и заточают в кристаллические сферы. Затем эти артефакты раздают смертным чародеям и чернокнижникам Легиона как проводники необузданной, порабощенной силы. Даже расколотая на осколки, заключенная в них демоническая сущность сохраняет могучую магическую силу."},{t="Рассеяны по континентам",b="Сфера Соран'рука не осталась целой. Ее обломки разбросаны по темным уголкам обоих главных континентов. Одна половина была разбита еще сильнее и досталась культистам Сумеречного Молота в сырых пещерах Непроглядной Пучины в Ясеневом лесу. Более крупная целая половина пересекла море и оказалась в Серебряном бору, где ее присвоил один из чародеев в населенных призраками руинах Крепости Темного Клыка. Доан Кархан, всю жизнь изучающий сферы Легиона и ранее собравший Сферу Заргейна, использует найденные осколки, чтобы восстановить Соран'рука в рабочий предмет."}},faq={{q="Что такое Шар Соран'рука?",a="Соран'рук был демоном Пылающего Легиона, потерявшим расположение хозяев. По демоническому обычаю его дух заточили в магическую сферу и передали смертным чернокнижникам. Позже сфера была разбита, но даже ее осколки хранят силу плененного демона.",al={"soranruk lore","what is soranruk","who was soranruk","соран'рук предания","что такое соран'рук","кто такой соран'рук"}},{q="Кто такой Доан Кархан?",a="Доан Кархан — нелюдимый чернокнижник, живущий на юге Степей и посвятивший жизнь изучению и восстановлению сфер Пылающего Легиона. Он много лет собирал собственный артефакт, Сферу Заргейна, и помогает начинающим чернокнижникам собрать Соран'рука.",al={"who is doan karhan","doan karhan backstory","кто такой доан кархан","доан кархан история"}},{q="Почему шар разбит между двумя разными подземельями?",a="Исходный шар раскололся на две основные части. Одна была разбита на мелкие осколки, которыми пользовались культисты Сумеречного Молота в Непроглядной Пучине, а крупный остаток забрал чародей в темных стенах Крепости Темного Клыка.",al={"why are pieces in bfd and sfk","where are soranruk fragments","осколки в непроглядной пучине и крепости","где осколки соран'рука"}},{q="Кто может выполнить это задание?",a="Это задание выполняют только чернокнижники, стремящиеся развить свое мастерство и овладеть артефактами, созданными из заточенных демонических духов.",al={"who can do this quest","is orb of soranruk warlock only","кто может выполнить задание","шар соран'рука только для чернокнижника"}},{q="Что делает Доан Кархан с найденными осколками?",a="Доан Кархан изучает осколки для своих исследований реликвий Легиона, а затем собирает их в полностью восстановленный магический предмет, форму которого определяет чернокнижник.",al={"what happens after collecting shards","reforming soranruk","что после сбора осколков","восстановление соран'рука"}},{q="Что такое Сфера Заргейна?",a="Сфера Заргейна — демоническая сфера-темница, которую Доан Кархан много лет разыскивал и восстанавливал для себя. В ней заключен другой опозоренный демон Легиона.",al={"orb of zargain","zargain lore","сфера заргейна","заргейн предания"}}},fp="20,247,24.444.0,27.600.0,29.264.0,19.280.0,52.248.0,28.137.0,54.184.0,27.170.0"}
P.entries["quest:175"] = {n="Взгляни на звезды",s="Следуя чертежам механика Зубца, Виктор Призм’Антрас ищет отражающую поверхность, чтобы собрать телескоп для обсерватории в Темнолесье. Он отправляет путников на юг Сумеречного леса на поиски Мэри, местной жительницы, которую помнят по зеркалу, которое она носила с собой.",h="Следуя чертежам механика Зубца, Виктор Призм’Антрас ищет отражающую поверхность, чтобы собрать телескоп для...",kw={"blind mary","darkshire","duskwood","look to the stars","looking glass","mary","telescope","tranquil gardens","viktori prism'antras","слепая мэри","темнолесье","сумеречный лес","взгляни на звезды","зеркало","мэри","телескоп","безмятежное кладбище","виктор призм’антрас"},ang={["faction:Alliance"]="Помощь Виктору в постройке телескопа дарит редкий проблеск любопытства и прогресса в городе, охваченном ужасом и гнилью.",["profession:Engineering"]="Сборка телескопа требует точных оптических параметров и опирается на гномьи чертежи, чтобы отражать и усиливать слабый свет звезд."},sec={{t="Отражающая поверхность",b="Раздобыв бронзовую трубу для телескопа, Виктор Призм’Антрас переходит к следующему пункту чертежей Зубца: нужно надежное зеркало, чтобы направлять и отражать свет в приборе. Вместо того чтобы выплавлять хорошее посеребренное стекло с нуля при нехватке всего в Темнолесье, Виктор вспоминает Мэри, местную жительницу, известную по всей округе тем, что она всегда носила с собой зеркало."},{t="Поиски на юге",b="Прежний дом Мэри находится глубоко на юге Сумеречного леса, к северу от населенного призраками Безмятежного кладбища. Чтобы найти ее, приключенцам придется выйти за безопасные границы патрулей Ночного Дозора и войти в оскверненные рощи, где кишат голодные волки, дикие пауки и бродячая нежить."},{t="Печальная судьба",b="Добравшись до скромной хижины Мэри на юге, путники узнают мрачную правду о падении Сумеречного леса. Женщина, которую помнил Виктор, больше не живая жительница, а Слепая Мэри — блуждающий дух, задержавшийся возле старого дома и соседнего кладбища и привязанный к воспоминаниям и вещам прежней жизни."}},faq={{q="Что строит Виктор Призм’Антрас?",a="Виктор строит астрономический телескоп в своей хижине на холме в Темнолесье по чертежам механика по имени Зубец.",al={"viktori telescope","look to the stars project","what is viktori making","телескоп виктора","взгляни на звезды","что делает виктор"}},{q="Зачем Виктору зеркало?",a="По оптическим чертежам Зубца нужно зеркало, которое отражает и фокусирует свет в корпусе телескопа. Виктор помнит, что Мэри носила зеркало, и надеется получить его для сборки.",al={"why need mirror","reflective surface telescope","зачем нужно зеркало","отражающая поверхность телескоп"}},{q="Где найти Мэри?",a="Мэри живет в разрушенном доме на юго-востоке Сумеречного леса, к северу от Безмятежного кладбища.",al={"where is mary","mary location duskwood","find blind mary","где мэри","мэри сумеречный лес","найти слепую мэри"}},{q="Кто такая Мэри?",a="Мэри жила на юге Сумеречного леса до того, как земли поглотила проклятая тьма, и была известна в Темнолесье тем, что всегда носила с собой зеркало. Что с ней стало, вам предстоит узнать в ее старом доме у Безмятежного кладбища.",al={"who is blind mary","blind mary backstory","кто такая слепая мэри","слепая мэри история"}},{q="Осталось ли у Мэри зеркало?",a="Когда к ней подходят, Мэри признает, что когда-то у нее было зеркало, но теперь его нет, и она может лишь указать, куда оно делось.",al={"does mary have mirror","blind mary looking glass","есть ли у мэри зеркало","зеркало слепой мэри"}},{q="Какие опасности окружают дом Мэри?",a="Юго-восточные леса и соседнее Безмятежное кладбище кишат враждебной нежитью, дикими сумеречными летучими мышами, ядовитыми пауками и бешеными волками, нападающими на путников к югу от Темнолесья.",al={"hazards near mary","tranquil gardens cemetery threats","опасности возле мэри","угрозы безмятежного кладбища"}}},fp="17,265,20.388.0,19.282.0,17.298.1,38.138.0,38.189.0,24.109.0,12.246.1,39.144.1,37.199.0"}
P.entries["quest:1758"] = {n="Фолиант заговора",s="Задание «Фолиант заговора» отправляет начинающего чернокнижника Альянса с высот над Кабестаном обратно в библиотеку Стальгорна. Чтобы призвать и подчинить прожорливого охотника Скверны, нужно найти легендарное руководство, написанное первыми чернокнижниками, покорившими это существо.",h="Задание «Фолиант заговора» отправляет начинающего чернокнижника Альянса с высот над Кабестаном обратно в...",kw={"felhunter","hall of explorers","ironforge","krom stoutarm","ratchet","strahad farsan","tome of the cabal","warlock","охотник скверны","зал исследователей","стальгорн","кром крепкорук","кабестан","страхад фарсан","фолиант заговора","чернокнижник"},ang={["class:Warlock"]="Получение Фолианта заговора — ключевой обряд посвящения для практикующего темные искусства, который стремится овладеть охотниками Скверны: он выходит за рамки младших прислужников и переходит к истинной демонологии, направленной против магии.",["faction:Alliance"]="Практикам Альянса приходится возвращаться с границ Калимдора в Зал Исследователей в Стальгорне, чтобы обратиться к знаниям дворфов за запретными темными текстами.",["race:Dwarf"]="Кром Крепкорук доказывает, что не каждый дворф в Зале Исследователей откапывает артефакты Титанов — некоторые втайне собирают предания о Пылающей Тьме."},sec={{t="Зверь, питающийся магией",b="Подчинение беса, демона Бездны или суккуба требует ритуала, но охотник Скверны представляет совсем иную опасность. Охотники Скверны не просто служат Пылающему Легиону — они охотятся на магическую энергию и пожирают ее. Обычный круг призыва рассыплется перед ним, высосав магию призывателя еще до того, как возникнет связь. Страхад Фарсан, наблюдающий за Кабестаном из своего убежища в Степях, не позволит новичку попытаться на такое связывание без подготовки."},{t="Первое связывание",b="Чтобы безопасно призвать и подчинить охотника Скверны, послушнику нужны магические формулы из Фолианта заговора. Рукопись, написанная первым смертным заговором чернокнижников, сумевших без посторонней помощи подчинить охотника Скверны, описывает геомантию, материалы и руны связывания, необходимые, чтобы выдержать голод существа. К несчастью для Страхада и его круга, их экземпляр этого труда давно утерян."},{t="Собиратель из Дун Морога",b="Не имея возможности предоставить текст сам, Страхад посылает чернокнижников Альянса через Великое море в Зал Исследователей в Стальгорне. Там обитает Кром Крепкорук, странствующий дворф-чернокнижник, проводящий старость за изучением древних рукописей и библиотечных записей. Если где-то в Восточных королевствах и сохранился след утерянного гримуара, он погребен в тщательных каталогах Крома."}},faq={{q="Зачем мне искать Фолиант заговора?",a="В Фолианте заговора содержатся точные указания первых смертных чернокнижников, которые призвали и подчинили охотника Скверны без посторонней помощи. Обычных ритуалов призыва недостаточно, чтобы заточить демона, питающегося магической энергией.",al={"what is tome of cabal","why find book","tome of cabal purpose","что такое фолиант заговора","зачем искать книгу","назначение фолианта заговора"}},{q="Кто такой Кром Крепкорук?",a="Кром Крепкорук — странствующий дворф-чернокнижник, живущий в библиотеке Зала Исследователей в Стальгорне. Он проводит дни среди пыльных томов, каталогизируя древние исторические записи.",al={"where is krom","who is krom stoutarm","krom ironforge","где кром","кто такой кром крепкорук","кром стальгорн"}},{q="Почему Страхад Фарсан находится в Степях?",a="Страхад Фарсан — опытный человек-чернокнижник, живущий в тихом нейтральном убежище на утесах над Кабестаном. Вдали от бдительных глаз Кирин-Тора и властей Штормграда он обучает могущественной демонологии и Альянс, и Орду.",al={"strahad location","why ratchet","who is strahad","где страхад","почему кабестан","кто такой страхад"}},{q="Что будет после разговора с Кромом Крепкоруком?",a="Кром Крепкорук вспоминает упоминания о фолианте в старых каталогах. Он поручит вам разыскать его утерянные части и добыть редкие реагенты, нужные для восстановления гримуара.",al={"next quest","after krom","tome of cabal next step","следующее задание","после крома","фолиант заговора следующий шаг"}},{q="Могут ли чернокнижники Орды выполнить это задание?",a="Это путешествие в Стальгорн предназначено только для чернокнижников Альянса. Чернокнижникам Орды Страхад дает равноценное задание — найти знающих людей на землях Орды.",al={"horde version","is this alliance only","версия для орды","только ли для альянса"}},{q="Какого демона дает эта цепочка заданий?",a="Вся цепочка заданий «Фолиант заговора» завершается ритуальным боем с призванным охотником Скверны и учит чернокнижника призывать и подчинять его как постоянного питомца.",al={"which demon","felhunter quest","what pet do i get","какой демон","задание охотник скверны","какого питомца я получу"}}},fp="17,266,27.470.0,17.439.0,25.399.0,44.244.0,21.197.0,37.269.0,44.198.1,33.203.0,38.180.0"}
P.entries["quest:176"] = {n="Разыскивается:  \"Дробитель\"",s="«Разыскивается: „Дробитель“» — объявление Альянса о награде за голову огромного свирепого вождя гноллов, вывешенное у Златоземья. Дробитель рыщет в юго-западных чащах Элвиннского леса и жестоко сорвал все попытки местных властей расправиться с ним.",h="«Разыскивается: „Дробитель“» — объявление Альянса о награде за голову огромного свирепого вождя гноллов...",kw={"bounty","dughan","elwynn","forest's edge","gnoll","goldshire","hogger","wanted","награда","дугхан","элвинн","лесная опушка","гнолл","златоземье","дробитель","разыскивается"},ang={["faction:Alliance"]="Победа над Дробителем считается обрядом посвящения для молодых героев Альянса, проверяющих свою доблесть в защите сердца земель Штормграда.",["race:Human"]="Для людей Элвинна убийство Дробителя означает безопасность усадеб и торговли на дорогах, которые месяцами терроризировали засады гноллов."},sec={{t="Угроза в лесу",b="Пока Элвиннский лес страдает от бандитов и нашествия кобольдов, племена гноллов на юге стали смелее и организованнее под жестоким предводительством Дробителя. Он намного крупнее обычных гноллов Речной Лапы и разбил лагерь возле Лесной опушки, устраивая засады на путников и громя отряды местного ополчения, посланные его усмирить."},{t="Отчаяние Златоземья",b="Армия Штормграда растянута и не может выделить регулярные силы для охраны окраин столицы, поэтому маршал Дугхан необычным шагом объявил открытую награду за голову зверя. Чтобы одолеть Дробителя, нужно проникнуть в глубь враждебной территории гноллов, а его свирепость создала ему славу самой смертельной угрозы для начинающих искателей приключений в Элвинне."}},faq={{q="Кто такой Дробитель?",a="Дробитель — необычайно крупный и свирепый вождь гноллов, терроризирующий юго-запад Элвиннского леса. Он командует местными стаями возле Лесной опушки и жестоко разбил все прежние попытки стражи Штормграда схватить или убить его.",al={"who is hogger","hogger lore","what is hogger","кто такой дробитель","дробитель предания","что такое дробитель"}},{q="Где найти Дробителя?",a="Дробитель бродит среди лагерей гноллов на юго-западе Элвиннского леса, возле южных границ, известных как Лесная опушка, к северу от реки, отделяющей лес от Западного Края и Сумеречного леса.",al={"hogger location","where is hogger","find hogger","дробитель местонахождение","где дробитель","найти дробителя"}},{q="Почему за Дробителя назначена награда?",a="Армия Штормграда назначила награду за Дробителя, потому что он громит местные патрули и смертельно опасен для путников. Поскольку регулярные войска растянуты по всему королевству, маршал Дугхан обратился к независимым искателям приключений и охотникам за головами, чтобы устранить угрозу.",al={"why kill hogger","wanted poster hogger","who put bounty on hogger","зачем убивать дробителя","объявление дробитель","кто назначил награду за дробителя"}},{q="Кто принимает доказательство смерти Дробителя?",a="Доказательство гибели зверя — Коготь большого гнолла — нужно принести прямо маршалу Дугхану, который командует местным гарнизоном в Златоземье.",al={"turn in hogger","where to turn in hogger","who wants hogger claw","сдать дробителя","куда сдать дробителя","кому нужен коготь дробителя"}},{q="Чем Дробитель опаснее других гноллов?",a="В отличие от обычных гноллов Элвинна, Дробитель обладает огромной статью и жестокостью. Он бьет заметно сильнее и выдерживает гораздо больше урона, часто сокрушая одиночек, которые его недооценили.",al={"is hogger strong","why is hogger elite","силен ли дробитель","почему дробитель элитный"}},{q="Почему стража Штормграда не справляется с Дробителем сама?",a="Военные ресурсы королевства сильно истощены и связаны обороной главных границ и делами, связанными с пропажей короля Вариана Ринна. Небольшому отряду маршала Дугхана в Златоземье не хватает людей, чтобы безопасно выследить столь стойкое чудовище.",al={"why doesn't dughan kill hogger","where is stormwind army","почему дугхан не убьет дробителя","где армия штормграда"}}},fp="16,253,21.347.0,23.369.0,14.234.0,26.184.0,32.274.0,41.151.0,52.226.0,56.251.0"}
P.entries["quest:177"] = {n="Взгляни на звезды",s="В этом задании искателям приключений нужно вернуть выброшенное зеркало Слепой Мэри для астронома Виктора Призм’Антраса. Хрупкое зеркало досталось Безумному вурдалаку, который бродит по заброшенному Безмятежному кладбищу на юге Сумеречного леса.",h="В этом задании искателям приключений нужно вернуть выброшенное зеркало Слепой Мэри для астронома Виктора...",kw={"blind mary","cog","darkshire","insane ghoul","look to the stars","mary's looking glass","telescope","tranquil gardens cemetery","viktori prism'antras","слепая мэри","темнолесье","безумный вурдалак","взгляни на звезды","зеркало мэри","телескоп","безмятежное кладбище","виктор призм’антрас"},ang={["class:Priest"]="Жрецы, ступающие по оскверненной земле Безмятежного кладбища, видят ужасное поругание над мертвыми Сумеречного леса, где павшие селяне превратились в безумных падальщиков.",["faction:Alliance"]="Возвращение утраченных городских реликвий из рук голодной нежити показывает горькую судьбу жителей Сумеречного леса, брошенных на опасной окраине Королевства Штормград.",["profession:Engineering"]="Инженеры оценят самодельную оптику Виктора, превращающего обычные полированные ручные зеркала в отражающие детали астрономического прибора."},sec={{t="Реликвия лучших времен",b="Прежде чем подкрадывающийся мрак поглотил Большую деревню и превратил ее в плачущий дух, Слепая Мэри дорожила резным зеркалом. После ужасного происшествия, отнявшего у нее зрение и рассудок, она выбросила память о былом в грязь за семейным амбаром. Это зеркало как раз нужно Виктору Призм’Антрасу для большого телескопа в Темнолесье, но его утащили во мрак задолго до того, как астроном мечтал изучать небеса."},{t="Кладбищенский мародер",b="Зеркало подобрал Безумный вурдалак, рыскавший за разрушенными фермами. Гонимый на юг неутолимым голодом, несчастная нежить унесла зеркало на Безмятежное кладбище и поселилась в заброшенной часовне среди заросших надгробий. Чтобы вернуть хрупкое стекло, придется пройти мимо пожирающих плоть тварей южных лесов и вырвать потерянное сокровище Мэри из гниющих когтей."}},faq={{q="Зачем Виктору зеркало Мэри?",a="Виктор Призм’Антрас собирает мощный телескоп в своей хижине на холме в Темнолесье. Ему нужны качественные отражающие линзы и зеркала, чтобы собрать тусклый свет звезд, а любимая семейная реликвия Мэри точно подходит по оптическим требованиям его изобретения.",al={"viktori mirror","why looking glass","what is the mirror for","зеркало виктора","зачем зеркало","для чего нужно зеркало"}},{q="Кто такой Безумный вурдалак, укравший зеркало?",a="Безумный вурдалак — нежить-падальщик, собиравшая безделушки в заброшенных усадьбах возле дома Мэри. Он бежал на юг и укрылся в разрушенной часовне на Безмятежном кладбище.",al={"where is the insane ghoul","who has the looking glass","ghoul in chapel","где безумный вурдалак","у кого зеркало","вурдалак в часовне"}},{q="Почему Слепая Мэри выбросила свое зеркало?",a="Мэри дорожила зеркалом до «происшествия», отнявшего у нее зрение, истерзавшего разум и превратившего ее в неупокоенную тень. После той катастрофы она не могла ни смотреть на него, ни держать в руках и в отчаянии бросила его за амбаром.",al={"why did mary throw it away","blind mary mirror","mary looking glass incident","почему мэри выбросила зеркало","зеркало слепой мэри","происшествие с зеркалом мэри"}},{q="Где находится Безмятежное кладбище?",a="Безмятежное кладбище лежит на юго-востоке Сумеречного леса, к югу от главной дороги. Когда-то это было мирное кладбище Большой деревни, а теперь там кишат агрессивные вурдалаки, скелеты и падальщики.",al={"tranquil gardens location","where is cemetery","безмятежное кладбище местонахождение","где кладбище"}},{q="Кто такой Зубец?",a="Зубец — гном-изобретатель, живущий в Темнолесье. Виктор полагается на инженерные знания Зубца, чтобы оценить и помочь собрать тонкие механизмы своей машины для наблюдения за звездами.",al={"who is cog","viktori cog","кто такой зубец","виктор зубец"}},{q="Что будет после того, как вернуть зеркало Виктору?",a="Получив отражающее устройство, Виктор радуется успехам в работе над прибором. Затем он приступает к последнему этапу сборки телескопа и просит принести еще один важный компонент, чтобы завершить систему линз.",al={"look to the stars next quest","what comes next","взгляни на звезды следующее задание","что дальше"}}},fp="17,249,22.467.0,23.420.0,43.261.0,46.205.0,48.237.0,39.221.0,11.184.0,51.228.1"}
P.entries["quest:1782"] = {n="Доспехи Фьюрена",s="«Доспехи Фьюрена» — завершение пути начинающего воина, который помогает мастеру-кузнецу Фьюрену Длиннобороду в Штормграде. Собрав клыки пауков, рога химер и флакон флогистона, герой помогает Длиннобороду выковать прочную кольчугу, закаленную огнем. В благодарность за помощь Длиннобород награждает воина готовой кольчугой и обещает поделиться своими новыми металлургическими приемами со всем Альянсом.",h="«Доспехи Фьюрена» — завершение пути начинающего воина, который помогает мастеру-кузнецу Фьюрену Длиннобороду...",kw={"alliance warrior","blacksmithing","fire hardened mail","furen longbeard","furen's armor","mail armor","stormwind","воин альянса","кузнечное дело","закаленная огнем кольчуга","фьюрен длиннобород","доспехи фьюрена","кольчужные доспехи","штормград"},ang={["class:Warrior"]="Для юных воинов Альянса доспехи особой закалки от Фьюрена — обряд посвящения и необходимая защита в первых походах на передовой.",["faction:Alliance"]="Крепкое вооружение необходимо, чтобы регулярные войска Альянса выживали в борьбе с постоянными угрозами со стороны Братства Справедливости, гноллов и враждебных стихийных сил.",["profession:Blacksmithing"]="Удачный опыт Фьюрена показывает традицию сотрудничества кузнецов Альянса, которые делятся особыми металлургическими открытиями, поднимая уровень мастерства в Штормграде и Стальгорне."},sec={{t="Прорыв мастера",b="Фьюрен Длиннобород, уважаемый дворфийский оружейник из Штормграда, посвятил свое ремесло расширению возможностей защитной металлургии Альянса. Поручив стойкому герою добыть редкие клыки, рога и флогистон, Длиннобород хотел испытать передовые приемы закалки кольчуг, устойчивых к жгучему жару и сокрушительным ударам. Работа увенчалась огромным успехом и утвердила Длиннобороду славу одного из лучших мастеров-бронников Альянса."},{t="Делиться мастерством",b="Когда Фьюрен вручает готовую закаленную огнем кольчугу герою, собравшему материалы, он выражает глубокую благодарность за сотрудничество. Опыты не только дали один прочный доспех, но и расширили его понимание защитной ковки. В духе общности кузнецов Стальгорна и Штормграда Длиннобород решает разослать свои записи и открытия другим кузнецам Альянса, чтобы его прорыв усилил бойцов передовой по всей фракции."}},faq={{q="Кто такой Фьюрен Длиннобород?",a="Фьюрен Длиннобород — мастер-бронник из дворфов, работающий в городе Штормград. Он много работает с боевыми орденами Альянса, особенно с воинами, которым нужны особые доспехи высокого качества.",al={"who is furen","furen longbeard","stormwind smith furen","кто такой фьюрен","фьюрен длиннобород","кузнец фьюрен штормград"}},{q="Какие доспехи создал Фьюрен?",a="Благодаря многочисленным опытам с редкими клыками, рогами и флогистоном Фьюрен выковал закаленный огнем хауберк — кольчужный нагрудник. Он создал его так, чтобы тот выдерживал яростные атаки и сильный жар на поле боя.",al={"what armor does furen make","fire hardened mail","furen's reward","какие доспехи делает фьюрен","закаленная огнем кольчуга","награда фьюрена"}},{q="Куда Фьюрен Длиннобород отправляет свои кузнечные открытия?",a="Фьюрен обещает отправить свои технические выводы и записи другим кузнецам Альянса, чтобы преимущества новых методов закалки получили оружейные и кузницы по всему королевству.",al={"furen's notes","who gets furen's designs","alliance blacksmiths","записи фьюрена","кто получит чертежи фьюрена","кузнецы альянса"}},{q="Почему воина попросили собрать реагенты для Фьюрена?",a="Фьюрену были нужны редкие и нестабильные компоненты для испытания новых кузнечных приемов. Не имея возможности покинуть кузницу, чтобы охотиться на пауков Болотины и химер Когтистых гор, он положился на амбициозного воина.",al={"why gather reagents for furen","fire hardened mail quest materials","зачем собирать реагенты для фьюрена","материалы задания закаленная огнем кольчуга"}},{q="Где куются и вручаются эти доспехи?",a="Обмен происходит прямо в кузнице Фьюрена Длинноборода в городе Штормград, где он выполняет последние удары молотом и закалку кольчуги.",al={"where is furen longbeard","turn in location","furen location","где фьюрен длиннобород","место сдачи","где находится фьюрен"}},{q="Приносит ли эта работа пользу другим бойцам Альянса?",a="Да. Фьюрен отмечает, что опыт работы с этими материалами будет передан другим бронникам Альянса, и надеется, что это побудит других кузнецов создавать и поставлять отличное снаряжение солдатам Альянса.",al={"alliance benefit","furen's breakthrough","польза для альянса","прорыв фьюрена"}}},fp="13,426,23.485.0,17.494.0,23.201.0,36.214.0,57.204.0,55.237.0,41.155.0,47.223.0"}
P.entries["quest:179"] = {n="Дворфские экипировщики",s="«Дворфские экипировщики» — вводное задание на выживание в Холодной долине, которое выдает Стен Крепкорук. За истребление местных волков и добычу их жесткого мяса для зимних запасов новобранцы получают прочные перчатки, защищающие от обморожения в лютом холоде Дун Морога.",h="«Дворфские экипировщики» — вводное задание на выживание в Холодной долине, которое выдает Стен Крепкорук.",kw={"anvilmar","coldridge valley","dun morogh","dwarven outfitters","frostbite","gloves","sten stoutarm","tough wolf meat","старая наковальня","холодная долина","дун морог","дворфские экипировщики","обморожение","перчатки","стен крепкорук","жесткое волчье мясо"},ang={["race:Dwarf"]="Для юных дворфов клана Бронзобородов, впервые выходящих в Холодную долину, это задание — ранний урок самостоятельности на границе: заслужи свое место, обеспечивай лагерь и уважай горный холод.",["race:Gnome"]="Найдя приют у родственников-дворфов в Дун Мороге, гномы быстро понимают, что выжить у Старой Наковальни помогает не только острый ум, но и практичная горная одежда."},sec={{t="Честный обмен в Холодной долине",b="В горном проходе Холодной долины стоит жестокий холод, и неподготовленные путники быстро понимают, что обычная экипировка не спасает от стихии. У Старой Наковальни Стен Крепкорук предлагает новобранцам простую пограничную сделку: отправиться в снежные сугробы, перебить рыскающих волков и принести куски жесткого мяса для снабжения лагеря. Взамен он дает настоящие перчатки для холодной погоды, чтобы юные герои не остались без пальцев."},{t="Жить за счет долины",b="Волки — вечная опасность для дворфийских разведчиков и юных гномов, обучающихся в долине, но они же и ценный ресурс. Их мясо кормит гарнизон Старой Наковальни, а сокращение их числа делает тропы между лагерями немного безопаснее. Договоренность Крепкорука служит двум целям: проверяет умение новобранца обращаться с местными зверями и пополняет запасы еды на суровые ночи."}},faq={{q="Кто такой Стен Крепкорук?",a="Стен Крепкорук — дворф, стоящий у Старой Наковальни в Холодной долине. Он присматривает за недавно прибывшими новобранцами и следит, чтобы у них было снаряжение для выживания в холоде Дун Морога, предлагая полезные вещи в обмен на охоту на местную дичь.",al={"sten stoutarm","who gives dwarven outfitters","anvilmar outfitter","стен крепкорук","кто выдает дворфские экипировщики","экипировщик старой наковальни"}},{q="Зачем Стену волчье мясо?",a="Лагерь у Старой Наковальни полагается на местную охоту, чтобы пополнять запасы. Волчье мясо — выносливая и надежная пища для солдат и наставников, живущих в уединенной заснеженной долине.",al={"why wolf meat","tough wolf meat","what is the meat for","зачем волчье мясо","жесткое волчье мясо","для чего мясо"}},{q="Где найти волков для этого задания?",a="Волки бродят по заснеженным полянам по всей Холодной долине, особенно сразу за главным двором Старой Наковальни и вдоль троп к отдаленным лагерям.",al={"where are wolves","wolf locations coldridge","where to get meat","где волки","волки холодная долина","где взять мясо"}},{q="Какую награду дает Стен?",a="Стен награждает новобранцев надежной парой теплых перчаток, созданных, чтобы защищать от обморожения и укрывать руки бойца от лютых ветров Дун Морога.",al={"dwarven outfitters reward","what gloves do you get","quest reward","награда дворфские экипировщики","какие перчатки дают","награда за задание"}},{q="Считается ли волчье мясо хорошей едой у дворфов?",a="Жесткое волчье мясо грубое и жилистое, но в суровом горном климате Дун Морога дворфы ценят сытную пищу выше изысканных блюд. Тушеное или жареное на костре, оно хорошо служит гарнизону.",al={"is wolf meat tasty","dwarf wolf meat","eating wolf","вкусное ли волчье мясо","дворфы волчье мясо","есть волка"}},{q="Могут ли гномы выполнить это задание?",a="Да. Гномы, обучающиеся вместе с дворфами-союзниками в Холодной долине, сталкиваются с теми же пронизывающими ветрами и так же остро нуждаются в теплой одежде.",al={"gnome dwarven outfitters","can gnomes get gloves","gnome cold weather","гномы дворфские экипировщики","могут ли гномы получить перчатки","гномы холод"}}},fp="18,283,25.471.0,21.438.0,21.262.0,29.195.0,43.175.0,30.166.0,48.221.0,29.145.0"}
P.entries["quest:1791"] = {n="Ветростраж",s="«Ветростраж» — наставление, направляющее опытных воинов к уединенному тролльскому шаману далеко на севере. Доказав доблесть в испытании Побоища и освоив стойку берсерка, воины ищут оружие, достойное их растущей ярости.",h="«Ветростраж» — наставление, направляющее опытных воинов к уединенному тролльскому шаману далеко на севере.",kw={"alterac mountains","bath'rah","berserker stance","cyclonian","fray island","klannoc macleod","tarren mill","the affray","the windwatcher","альтеракские горы","бат'ра","стойка берсерка","циклониан","остров битв","кланнок маклеод","мельница таррен","побоище","ветростраж"},ang={["class:Warrior"]="Этот обряд связывает ваше мастерство в стойке берсерка, полученное на Острове Битв, с поиском легендарного оружия, выкованного силой стихий.",["race:Troll"]="Поиски Бат'ры показывают, что даже среди разрушенных руин Лордерона тролли-шаманы и оружейники хранят мистические знания, которым поклоняются воины всех народов."},sec={{t="Оружие для берсерка",b="Пережив жестокое испытание выносливости на Побоище на Острове Битв, воины получают от Кланнока Маклеода суровую дисциплину стойки берсерка. Но одной боевой дисциплине нужно столь же славное оружие. Понимая это, Кланнок отправляет многообещающих бойцов с побережья Степей через континенты на поиски одинокого мастера, способного выковать необычайное оружие."},{t="Отшельник на берегу реки",b="Задание ведет путников в спорные долины северного Лордерона, в туманное пограничье между Альтеракскими горами и зараженными Западными Чумными землями. У реки, текущей на север мимо Мельницы Таррен, среди каменных руин живет в одиночестве тролль-отшельник Бат'ра Ветростраж. Бат'ра — не простой отшельник: он талантливый оружейник и владеет мощным стихийным шаманизмом, ожидая воинов, готовых создать нечто поистине великое."}},faq={{q="Кто посылает вас искать Ветростража?",a="Кланнок Маклеод, мастер боевых испытаний на Острове Битв у восточного побережья Степей, посылает вас в это путешествие, когда вы одолели Побоище и освоили стойку берсерка.",al={"quest giver","who gives the windwatcher","klannoc macleod quest","персонаж, выдающий задания","кто выдает ветростража","задание кланнока маклеода"}},{q="Кто такой Бат'ра Ветростраж?",a="Бат'ра — загадочный тролль-отшельник, мастер-оружейник и могучий шаман, живущий в уединении в глуши между Альтеракскими горами и Западными Чумными землями.",al={"who is bathrah","bathrah the windwatcher lore","bath'rah identity","кто такой бат'ра","бат'ра ветростраж предания","личность бат'ры"}},{q="Где именно находится Бат'ра?",a="Бат'ра разбил лагерь на восточном берегу реки, текущей на север мимо Мельницы Таррен, у древних руин на границе Альтерака и Западных Чумных земель.",al={"where is bath'rah","bathrah location","find bathrah","где бат'ра","местонахождение бат'ры","найти бат'ру"}},{q="Почему Кланнок посылает воинов к Бат'ре?",a="Кланнок понимает, что воину, освоившему яростную стойку берсерка, нужно исключительное оружие, чтобы направить эту ярость, а Бат'ра обладает редкими знаниями о стихиях и кузнечном деле, чтобы его выковать.",al={"why go to bathrah","what is the purpose of this quest","windwatcher purpose","зачем идти к бат'ре","в чем цель задания","цель ветростража"}},{q="Что будет после разговора с Бат'рой?",a="Разговор с Бат'рой сразу ведет к заданию о схватке с бурным элементалем Циклонианом и сборе редких материалов для создания мощного боевого оружия.",al={"what is next after the windwatcher","cyclonian next quest","windwatcher continuation","что после ветростража","следующее задание циклониан","продолжение ветростража"}},{q="Безопасно ли это путешествие для странника из Степей?",a="Оно весьма опасно. Путь ведет через предгорья Хилсбрада в спорные северные земли рядом с укрытиями Синдиката, агрессивными горными хищниками и смертельной заразой Западных Чумных земель.",al={"is it dangerous","tarren mill river danger","опасно ли это","опасность реки мельницы таррен"}}},fp="15,283,24.410.0,27.517.0,38.202.0,32.171.0,34.175.0,43.210.0,40.163.1,60.223.0"}
P.entries["quest:1793"] = {n="Фолиант Отваги",s="Фолиант Отваги — основополагающее испытание для паладинов Альянса, вступающих в пору зрелости. Под руководством наставников-паладинов в Штормграде и Стальгорне посвящаемым предстоит доказать, что их мужество и преданность защите невинных не уступают их воинскому мастерству.",h="Фолиант Отваги — основополагающее испытание для паладинов Альянса, вступающих в пору зрелости.",kw={"cathedral of light","duthorian rall","holy light","ironforge","paladin trial","silver hand","tiza battleforge","tome of valor","собор света","даториан ралл","свет","стальгорн","испытание паладина","серебряная длань","тиза боевой горн","фолиант отваги"},ang={["class:Paladin"]="Этот обряд знаменует переход от простого служки к доверенному защитнику Света и призывает вас поставить бескорыстный долг выше личной безопасности.",["faction:Alliance"]="Испытания Фолианта готовят защитников, способных оборонять поселения Альянса от растущих угроз — от местных разбойников до чудовищных захватчиков.",["race:Dwarf"]="Паладины Стальгорна под руководством наставников вроде Тизы Боевого Горна видят в Фолианте Отваги подтверждение того, что дворфийскую стойкость укрепляет священная цель.",["race:Human"]="Это испытание, проходящее под бдительным надзором Даториана Раллы в Соборе Света, отражает неизменную преданность Штормграда основополагающим идеалам Серебряной Длани."},sec={{t="Мерило паладина",b="Чтобы владеть Светом в бою, нужны не только тяжелые доспехи и воинская дисциплина. Когда молодые паладины достигают новых высот в обучении, наставники в Соборе Света и Зале Тайн требуют доказательств их внутренней стойкости. Уроки Фолианта Отваги проверяют готовность посвящаемого противостоять ужасающему злу — от драконов до демонов — не дрогнув и не бросив тех, кто не может себя защитить."},{t="Добродетели ордена",b="Храбрость перед лицом смертельной угрозы считается для святого воина столь же необходимой, как оружие и щит. Через испытания Фолианта Отваги паладины узнают, что грубая сила пуста без непоколебимой клятвы защищать беспомощных. Столкновение с настоящей опасностью гарантирует, что, когда тьма падет на Альянс, его защитники устоят, а не сломятся."}},faq={{q="Для чего нужен Фолиант Отваги?",a="Фолиант Отваги — обряд посвящения для становящихся паладинов Альянса. Наставники Света создали его, чтобы убедиться, что посвящаемый обладает подлинным мужеством и бескорыстным стремлением защищать слабых, прежде чем продвинуться в ордене.",al={"what is tome of valor","tome of valor purpose","why do tome of valor","что такое фолиант отваги","назначение фолианта отваги","зачем нужен фолиант отваги"}},{q="Кто направляет паладинов на это испытание?",a="Посвящаемых на это испытание обычно призывают старшие паладины в столицах Альянса, например Даториан Ралл в Соборе Света Штормграда или Тиза Боевой Горн в Зале Тайн Стальгорна.",al={"who gives tome of valor","tome of valor questgiver","who starts tome of valor","кто дает фолиант отваги","кто выдает задание фолиант отваги","кто начинает фолиант отваги"}},{q="Куда ведет это испытание?",a="Первый призыв служит началом череды особых заданий, проверяющих стойкость паладина: они выводят его в поле, где он сталкивается с настоящей опасностью, защищая королевство и невинных.",al={"what comes after tome of valor","tome of valor follow up","tome of valor quest chain","что после фолианта отваги","продолжение фолианта отваги","цепочка заданий фолиант отваги"}},{q="Почему паладинам так важна храбрость?",a="Свет отзывается на веру и волю. Перед лицом подавляющих ужасов, таких как демоны или драконы, страх может сломить дух воина; мужество позволяет паладину оставаться надежным щитом для других даже в самых тяжелых обстоятельствах.",al={"why valor","why courage matters to paladins","зачем отвага","почему мужество важно паладинам"}},{q="Проходят ли паладины-дворфы и люди одно и то же испытание?",a="Хотя паладины-дворфы обучаются в Стальгорне, а люди — в Соборе Света Штормграда, обе традиции следуют одним и тем же основным добродетелям: мужеству, долгу и защите беспомощных во имя Света.",al={"is it different for dwarfs","ironforge tome of valor","stormwind tome of valor","отличается ли для дворфов","фолиант отваги стальгорн","фолиант отваги штормград"}},{q="Какие основные уроки заключены в испытании?",a="Испытание строится на трех основных обязанностях: овладеть несгибаемой храбростью вопреки любым шансам, деятельно оберегать слабых от вреда и сохранять веру перед лицом ужаса.",al={"tome of valor lessons","what does the tome teach","уроки фолианта отваги","чему учит фолиант"}}},fp="17,264,24.434.0,20.366.0,41.255.0,35.201.0,27.195.0,50.234.0,52.205.0,44.197.0"}
P.entries["quest:1795"] = {n="Связывание",s="Связывание — завершающий обряд для чернокнижников, стремящихся подчинить охотника Скверны. Под надзором загадочного призывателя Страхада Фарсана над Кабестаном в ритуале используется восстановленный Фолиант заговора, чтобы вырвать агрессивного демонического хищника из Пустоты и покорить его в поединке.",h="Связывание — завершающий обряд для чернокнижников, стремящихся подчинить охотника Скверны.",kw={"barrens","felhunter","ratchet","strahad farsan","summoning","the binding","tome of the cabal","warlock","степи","охотник скверны","кабестан","страхад фарсан","призыв","связывание","фолиант заговора","чернокнижник"},ang={["class:Warlock"]="Покорение охотника Скверны — важная веха для любого чернокнижника: он получает особого хищника, борющегося с магией, способного пожирать заклинания и подавлять вражеских заклинателей.",["faction:Alliance"]="Чернокнижников Альянса отправляют из безопасного Штормграда через море в суровую нейтральную гавань Кабестан, где под бдительным взором Страхада они завершают опасный ритуал призыва.",["faction:Horde"]="Чернокнижники Орды отправляются в самое сердце Степей, чтобы доказать свою власть над Пустотой, и на нейтральной земле предстают перед Страхадом, чтобы подчинить гончую."},sec={{t="Круг заговора",b="На утесах над гоблинским портом Кабестан Страхад Фарсан проводит одни из самых опасных демонологических испытаний в Калимдоре. После того как чернокнижник соберет разрозненные фрагменты и реагенты, нужные для воссоздания древнего Фолианта заговора, Страхад подготавливает место связывания. Он чертит внутреннюю охранную руну, а его верные послушники направляют силу через зачарованные жезлы, замыкая внешний круг, чтобы все, что явится, оставалось отделенным от поселения внизу."},{t="Покорение охотника",b="Обратившись к заклинаниям, начертанным в Фолианте заговора, посвящаемый открывает мост в Круговерть Пустоты. Охотники Скверны — ненасытные демонические гончие, которые жаждут тайной силы и питаются магической энергией. Призванного зверя нельзя уговорить или мягко подчинить: его нужно жестоко усмирить и сломить в бою, прежде чем он признает чернокнижника законным хозяином. Выжив в схватке, призыватель доказывает, что готов использовать гончую против вражеских заклинателей."}},faq={{q="Для чего нужен этот ритуал?",a="Ритуал позволяет чернокнижнику призвать охотника Скверны и подчинить его своей воле. Читая из завершенного Фолианта заговора в круге призыва Страхада Фарсана, чернокнижник вызывает демонического хищника из Пустоты и побеждает его в бою, обретая его вечное служение.",al={"why do this quest","felhunter quest goal","binding purpose","зачем это задание","цель задания охотник скверны","назначение связывания"}},{q="Кто такой Страхад Фарсан?",a="Страхад Фарсан — опытный чернокнижник-человек, работающий в башне над Кабестаном в Степях. Благодаря его обширным знаниям темных искусств призыва наставники и Альянса, и Орды тайно отправляют к нему самых многообещающих учеников изучать сложные обряды связывания.",al={"who is strahad","strahad farsan lore","quest giver strahad","кто такой страхад","страхад фарсан предание","страхад выдает задание"}},{q="Почему чернокнижник должен убить демона, а не поработить его?",a="Охотник Скверны — агрессивный хищник, пожирающий магию и признающий лишь полное превосходство. Ритуал требует, чтобы чернокнижник одолел демона в физическом и магическом бою, сломив его свирепость и запечатлев свою власть над его духом, чтобы он повиновался при будущих призывах.",al={"why kill felhunter","can i enslave felhunter","felhunter combat","зачем убивать охотника скверны","можно ли поработить охотника скверны","бой с охотником скверны"}},{q="Могут ли чернокнижники и Альянса, и Орды проводить этот ритуал здесь?",a="Да. Хотя предыдущие задания по воссозданию Фолианта заговора различаются в зависимости от фракции, чернокнижников и Альянса, и Орды в итоге направляют к Страхаду Фарсану над Кабестаном для финального призыва.",al={"is this horde only","is this alliance only","who gets this quest","только для орды","только для альянса","кто получает это задание"}},{q="Что будет, если охотник Скверны победит призывателя?",a="Если призыватель падет, демон изгоняется обратно в Пустоту, и ритуал не удается. Однако Страхад позволяет выжившим после поражения чернокнижникам получить новый Фолиант заговора и повторить призыв, когда они будут должным образом готовы.",al={"what if i die","failing the binding","can i retry the ritual","что если я умру","провал связывания","можно ли повторить ритуал"}},{q="Чем охотники Скверны отличаются от других демонов?",a="Охотники Скверны — демонические гончие, выслеживающие добычу по магическим излучениям. Они не полагаются лишь на грубую силу или заклинания Тьмы, а превосходно чуют колдовство, пожирают действующие чары и сбивают вражеских заклинателей, что делает их бесценными спутниками против магов-соперников.",al={"what does a felhunter do","felhunter lore","why felhunters","что делает охотник скверны","охотник скверны предания","зачем охотники скверны"}}},fp="11,301,18.506.0,22.507.0,35.285.0,22.302.0,66.283.0,62.227.0,51.257.0,54.293.0"}
P.entries["quest:1796"] = {n="Материалы для зачарованной золотой кроводежды",s="Менара Расщепительница Бездны поручает начинающим чернокнижникам в Степях раздобыть Одеяния Тайны — основу для мощного магического облачения. Это первый шаг в создании Зачарованной золотой кроводежды: подготовка сосуда, способного выдержать темные чары.",h="Менара Расщепительница Бездны поручает начинающим чернокнижникам в Степях раздобыть Одеяния Тайны — основу...",kw={"barrens","bloodrobe","enchanted gold bloodrobe","menara voidrender","robes of arcana","tailoring","warlock quest","степи","кроводежда","зачарованная золотая кроводежда","менара расщепительница бездны","одеяния тайны","портняжное дело","задание чернокнижника"},ang={["class:Warlock"]="Создание Зачарованной золотой кроводежды — важный обряд для чернокнижников, учащий тому, что могущественные артефакты нужно ковать на прочной, тщательно подготовленной основе.",["profession:Tailoring"]="Задание требует редкого мастерства умелого портного, освоившего выкройку Одеяний Тайны, с использованием паучьего шелка и множества рулонов тонкого шелка.",["race:Orc"]="Для чернокнижников-орков, работающих в тени демонического прошлого своей расы, сбор материалов для неприметных одеяний — более тихое овладение энергией Скверны вдали от посторонних глаз.",["race:Undead"]="Отрекшиеся нередко отправляются далеко в выжженные солнцем Степи, чтобы перенять у Менары приемы и укрепить свои хрупкие смертные оболочки против собственных нестабильных искусств."},sec={{t="Сосуд Тайны",b="Прежде чем темную магию можно будет связать с тканью, само одеяние должно быть достойно такой силы. Менара Расщепительница Бездны велит чернокнижникам, стремящимся к большей мощи, раздобыть Одеяния Тайны. Как объясняет Менара, возможности любой магической реликвии зависят от мастерства, редкости и труда, вложенных в ее основу. Простые лохмотья расползутся под напряжением глубоких чар, поэтому тонко сшитое, восприимчивое одеяние незаменимо."},{t="Мастерство и амбиции",b="Хотя Менара особенно восхищается теми, кто способен соткать одеяние собственными руками, амбиции без жалости она ценит выше гордости. Сошьет ли чернокнижник шелк сам, закажет ли у умелого мастера или купит на рынке, итог один: готовое одеяние, которое можно переделать в особое орудие власти над Скверной."}},faq={{q="Почему Менаре Расщепительнице Бездны нужны именно Одеяния Тайны?",a="Мощные чары требуют одеяния, сотканного с исключительным мастерством из редких материалов. Менара использует Одеяния Тайны как чистую, восприимчивую основу, способную удержать нестабильные магические силы, которые скоро будут в нее заключены.",al={"why robes of arcana","why this robe","robe purpose","зачем одеяния тайны","зачем это одеяние","назначение одеяния"}},{q="Где находится Менара Расщепительница Бездны?",a="Менара Расщепительница Бездны живет в гоблинском порту Кабестан в Степях, где обучает чернокнижников, стремящихся усовершенствовать свое искусство и создавать особое снаряжение.",al={"menara voidrender location","where is menara","menara voidrender where","где менара расщепительница бездны","где найти менару","местонахождение менары"}},{q="Нужно ли мне самому сшить Одеяния Тайны?",a="Нет. Хотя Менара уважает усердие тех, кто создает одеяние сам, она принимает одеяния, полученные обменом или купленные у других мастеров. Для чернокнижника любой практичный способ добыть сосуд приемлем.",al={"do i need tailoring","can i buy the robes","tailoring required","нужно ли портняжное дело","можно ли купить одеяния","требуется ли портняжное дело"}},{q="Откуда берется выкройка Одеяний Тайны?",a="Выкройка — редкая добыча, выпадающая в основном с сектантов и темных заклинателей, таких как призыватели Бездны из Темной Нити в Башне Алталакса на Темных берегах или чародеи Братства Справедливости в Сумеречном лесу.",al={"robes of arcana pattern","how to get pattern","tailoring recipe location","выкройка одеяния тайны","как получить выкройку","где найти рецепт портняжного дела"}},{q="Что происходит с Одеяниями Тайны после сдачи?",a="Менара забирает одеяние себе как сырье для последующего ритуала наделения силой. Если вы носите его при завершении задания, она тут же снимает его, и вы остаетесь без нагрудной брони до окончания следующих этапов.",al={"do i lose the robes","robe gone","what happens to robe","теряю ли я одеяния","одеяние пропало","что с одеянием"}},{q="Что такое Зачарованная золотая кроводежда?",a="Это особое облачение, созданное для чернокнижников среднего ранга. Наделенное темными компонентами и защитными чарами, оно повышает стойкость заклинателя и запасы темной энергии.",al={"what is bloodrobe","bloodrobe lore","enchanted gold bloodrobe","что такое кроводежда","кроводежда предания","зачарованная золотая кроводежда"}}},fp="43,292,18.443.0,18.366.0,61.234.0,35.159.0,47.225.0,53.191.0,58.255.0,37.182.0"}
P.entries["quest:1798"] = {n="В поисках Страхада",s="«На поиски Страхада» — задание чернокнижников Альянса, которое отправляет практиков темных искусств из Штормграда через Великое море в Степи. Там, под взглядом гоблинского порта Кабестан, они ищут знаний Страхада Фарсана, чтобы научиться призывать охотников Скверны. Оно отмечает переход чернокнижника к более высоким и опасным ступеням подчинения демонов.",h="«На поиски Страхада» — задание чернокнижников Альянса, которое отправляет практиков темных искусств из...",kw={"felhunter","gakin the darkbinder","ratchet","seeking strahad","stormwind","strahad farsan","the barrens","warlock","охотник скверны","гакин темнопряд","кабестан","на поиски страхада","штормград","страхад фарсан","степи","чернокнижник"},ang={["class:Warlock"]="Это задание — важная веха в росте чернокнижника: от простых демонов и суккубов к хитрому охотнику Скверны, пожирающему магию.",["faction:Alliance"]="Призывателям Альянса путь предстоит неблизкий: через Великое море прямо в суровое сердце Калимдора, где господствует Орда."},sec={{t="Зов за морем",b="Within the subterranean enclave of the Slaughtered Lamb in Stormwind, Gakin the Darkbinder oversees the development of budding warlocks. Yet mastering the predatory felhunter demands materials, relics, and rites beyond what the modest cellar in the Mage Quarter can provide. Recognizing his pupil has grown in power, Gakin directs them away from the safety of the kingdom toward Kalimdor, initiating a journey that bridges the secret circles of human demonology across continents."},{t="Отшельник из Кабестана",b="Цель пути — засушливые холмы над гоблинской гаванью Кабестан. Там живет Страхад Фарсан, человек-чернокнижник и соратник Гакина по тайному заговору. Действуя на нейтральной земле, Страхад относительно свободен от любопытных глаз судей Альянса, церковных инквизиторов и часовых Орды. Его присутствие в Степях служит опорой для честолюбивых призывателей, готовых подчинить демонов, пожирающих ману."}},faq={{q="Кто посылает вас на поиски Страхада?",a="Gakin the Darkbinder, the warlock trainer secluded in the crypt beneath the Slaughtered Lamb in Stormwind's Mage Quarter, sends you on this journey once you are ready to learn how to summon a felhunter.",al={"who gives seeking strahad","quest giver","gakin","кто дает на поиски страхада","персонаж, выдающий задания","гакин"}},{q="Где находится Страхад Фарсан?",a="Страхад Фарсан живет в Степях, на высотах над гоблинским портовым городом Кабестан.",al={"strahad location","where is strahad","find strahad","где страхад","местонахождение страхада","найти страхада"}},{q="Почему чернокнижнику Альянса приходится ехать так далеко, в Степи?",a="В Штормграде у Гакина нет особых реагентов и знаний, нужных для обрядов призыва охотника Скверны. Страхад Фарсан располагает нужными знаниями и материалами, обосновавшись на нейтральной земле Кабестана вдали от местного надзора.",al={"why go to barrens","why kalimdor","why ratchet","зачем в степи","зачем в калимдор","зачем в кабестан"}},{q="Какую способность открывает это задание?",a="Это задание — первый шаг цепочки, ведущей к Фолианту заговора и ритуалу подчинения, необходимому, чтобы призвать охотника Скверны в спутники.",al={"what pet is this for","what do i get","felhunter quest","для какого питомца","что я получу","задание охотника скверны"}},{q="Враждебен ли Страхад Фарсан к Орде?",a="Нет. Страхад живет на нейтральной гоблинской земле и обучает чернокнижников и Альянса, и Орды, ищущих тайны призыва охотников Скверны, поддерживая связи с разными заговорами.",al={"is strahad alliance only","horde strahad","страхад только для альянса","страхад орда"}},{q="Что происходит после разговора со Страхадом?",a="Поприветствовав вас, Страхад поручает вам собрать составляющие для ритуала подчинения, начиная многоступенчатую цепочку заданий, связанную с Фолиантом заговора.",al={"next quest","what after seeking strahad","tome of the cabal","следующее задание","что после на поиски страхада","фолиант заговора"}}},fp="15,369,24.480.0,21.455.0,30.202.0,32.115.0,71.262.0,47.147.0,39.195.0,40.170.0"}
P.entries["quest:18"] = {n="Братство воров",s="«Братство воров» — одно из первых поручений, которое дает заместитель судьи Виллем у Аббатства Североземья. Оно отправляет молодых новобранцев Альянса за восточную реку, чтобы отбросить наступающую шайку разбойников, известных как Братство Справедливости. Красные мешковинные банданы воров дают властям Штормграда первое осязаемое свидетельство организованного присутствия этой группы в долине.",h="«Братство воров» — одно из первых поручений, которое дает заместитель судьи Виллем у Аббатства Североземья.",kw={"bandanas","brotherhood of thieves","defias","deputy willem","elwynn","northshire","stormwind army","банданы","братство воров","братство справедливости","заместитель судьи виллем","элвиннский лес","североземье","армия штормграда"},ang={["class:Rogue"]="Встреча с Братством Справедливости дает начинающим разбойникам представление о том, как организованные преступные сети действуют в тени человеческих земель.",["faction:Alliance"]="Власти Штормграда полагаются на новоприбывших новобранцев Альянса, чтобы поддерживать мир в Североземье, пока регулярные войска королевства растянуты.",["race:Human"]="Для людей, начинающих обучение в Североземье, столкновение с Братством Справедливости — первое суровое напоминание о том, что безопасность королевства Штормград подтачивается изнутри."},sec={{t="Бандиты в долине",b="Долина Североземья долго считалась тихой гаванью в Элвиннском лесу: ее охраняли стражи Штормграда, а в ней обучали новобранцев и клириков Света. Но недавно дисциплина по периметру ослабла. Бродяги и воры перешли восточную реку, затаились у леса и разбили небольшие лагеря прямо под носом у аббатства. Заместитель судьи Виллем, отвечающий за местный порядок, понимает, что стража не может выделить людей, чтобы охранять каждый уголок долины без помощи добровольцев."},{t="Багровый знак",b="От обычных грабителей этих разбойников отличают согласованность и единая одежда. Они называют себя Братством Справедливости и отмечают принадлежность красными мешковинными банданами, повязанными на лицо. Приказывая новобранцам выследить разбойников и добыть их маски, заместитель судьи Виллем стремится сдержать их дерзкое наступление и выяснить, насколько глубоко Братство Справедливости проникло в сердце королевства."}},faq={{q="Что представляет собой Братство Справедливости?",a="Братство Справедливости — организованная группировка разбойников и преступников, действующая сейчас в Элвиннском лесу и Западном Крае. Хотя власти Североземья поначалу видят в них лишь дерзких воров, они носят одинаковые красные мешковинные маски и подчиняются согласованному руководству.",al={"who are the defias","what is defias brotherhood","defias lore","кто такое братство справедливости","что за братство справедливости","предания братства справедливости"}},{q="Почему заместитель судьи Виллем просит помощи у новобранцев, а не у Армии Штормграда?",a="Армия Штормграда и местная стража растянуты по всему королевству. Из-за волнений в соседних землях и ослабленного руководства в Штормграде местным помощникам приходится полагаться на рвущихся в бой добровольцев и новобранцев, чтобы изгнать наступающих бандитов.",al={"why willem needs help","where are stormwind guards","why no army","зачем виллему помощь","где стража штормграда","почему не армия"}},{q="Откуда приходят эти воры?",a="В Североземье воры собрались за рекой к востоку от аббатства и рыщут по окраинам местных ферм и стоянок возле виноградника.",al={"where are the bandits","defias location northshire","где бандиты","братство справедливости в североземье"}},{q="Почему воры носят красные мешковинные банданы?",a="Красная мешковинная бандана — общий знак Братства Справедливости: она скрывает личности и показывает принадлежность другим преступникам, действующим на землях людей.",al={"why red bandanas","meaning of red masks","red burlap","почему красные банданы","значение красных масок","красная мешковина"}},{q="Что происходит после выполнения этого задания?",a="Заместитель судьи Виллем и местные быстро понимают, что угроза бандитов простирается дальше в Североземье, и новобранцы помогают Милли Осворт с погубленным урожаем и выслеживают главаря по имени Гаррик Тихокрад.",al={"what comes next","after brotherhood of thieves","что дальше","после братства воров"}},{q="Знает ли заместитель судьи Виллем, кто возглавляет Братство Справедливости?",a="Пока Виллем не понимает всего размаха организации. Он знает лишь, что они называют себя Братством Справедливости, и подозревает, что их присутствие у аббатства сулит Штормграду беду.",al={"does willem know vancleef","who leads defias northshire","знает ли виллем ванклифа","кто возглавляет братство справедливости в североземье"}}},fp="22,393,21.543.0,17.440.0,31.267.0,82.264.0,36.162.0,44.197.0,41.217.0,45.203.0"}
P.entries["quest:180"] = {n="Разыскивается: лейтенант Фангор",s="«Разыскивается: лейтенант Фангор» — местная награда, объявленная в Приозерье мировым судьей Соломоном. Она призывает искателей приключений выследить лейтенанта Фангора, свирепого вожака гноллов Темношкуров, вторгшихся в Красногорье. Его гибель наносит прямой удар по мятежному чародею Морганту, которому служат гноллы.",h="«Разыскивается: лейтенант Фангор» — местная награда, объявленная в Приозерье мировым судьей Соломоном.",kw={"fangore","gnoll","lakeshire","lieutenant fangore","magistrate solomon","morganth","redridge","shadowhide","фангор","гнолл","приозерье","лейтенант фангор","мировой судья соломон","моргант","красногорье","темношкуры"},ang={["faction:Alliance"]="Приозерье — важный оплот Альянса в Красногорье; расправа над Фангором не дает поселению оказаться в полной изоляции.",["race:Human"]="Защитники-люди на себе ощущают пренебрежение Штормграда в Красногорье, и личное вмешательство против вожаков гноллов становится для них делом выживания родных мест."},sec={{t="Город в осаде",b="Приозерье в отчаянном положении. Армия Штормграда растянута, король Вариан Ринн загадочным образом исчез, и верховный лорд Болвар Фордрагон оставил пограничные поселения вроде Красногорья заботиться о себе самим. Клан Темношкуров становится все наглее: грабит торговые пути, жжет фермы и подступает к самой окраине города. Мировой судья Соломон полагается на объявленные награды, чтобы привлечь наемные клинки там, куда не идут королевские солдаты."},{t="Лейтенант Морганта",b="Лейтенант Фангор — не просто хищный зверь: он выполняет приказы Морганта, мятежного темного чародея, обитающего в холмах Красногорья. Под командованием Фангора гноллы Темношкуры согласуют свои удары, а не бьются разрозненными мародерами, грозя полностью отрезать Приозерье от Элвиннского леса. Отсеченная лапа Фангора дает мировому судье Соломону доказательство того, что грубый авангард Морганта сломлен."}},faq={{q="Кто такой лейтенант Фангор?",a="Лейтенант Фангор — могущественный предводитель клана гноллов Темношкуров, обитающего в Красногорье. Он направляет набеги гноллов и исполняет волю Морганта, темного чародея, угрожающего Приозерью.",al={"lieutenant fangore","who is fangore","fangore lore","лейтенант фангор","кто такой фангор","предания о фангоре"}},{q="Кто объявил награду за лейтенанта Фангора?",a="Награду объявил мировой судья Соломон, глава Приозерья, пытающийся обезопасить границы Красногорья от враждебных гноллов и темных чародеев.",al={"who posted the bounty","who wants fangore dead","magistrate solomon fangore","кто объявил награду","кто хочет смерти фангора","мировой судья соломон фангор"}},{q="Почему Штормград не посылает солдат разобраться с гноллами?",a="Штормград парализован внезапным исчезновением короля Вариана Ринна и внутренними беспорядками. Верховный лорд Болвар Фордрагон и Дом знати отказались посылать отряды регулярной армии в отдаленные города вроде Приозерья, и мировому судье Соломону приходится нанимать искателей приключений.",al={"why no stormwind guard","where are stormwind soldiers","why isn't the army helping","почему нет стражи штормграда","где солдаты штормграда","почему армия не помогает"}},{q="Какое доказательство нужно для получения награды?",a="Мировой судья Соломон требует отсеченную лапу лейтенанта Фангора как вещественное доказательство гибели предводителя Темношкуров.",al={"fangore proof","fangores paw","what item for turn in","доказательство фангора","лапа фангора","что сдать"}},{q="Кто такой Моргант и почему Фангор ему подчиняется?",a="Моргант — мятежный человек-чародей, практикующий темную магию в башне в Красногорье. Он подчинил гноллов Темношкуров своей воле, используя лейтенанта Фангора как исполнителя, чтобы терроризировать окрестности.",al={"who is morganth","why do gnolls follow morganth","fangore morganth","кто такой моргант","почему гноллы слушаются морганта","фангор моргант"}},{q="Кто такие гноллы Темношкуры?",a="Клан Темношкуров — свирепое племя гноллов, населяющее скалы и леса Красногорья. Известные агрессивностью и жестокими засадами, они уже годами терзают поселенцев Приозерья.",al={"shadowhide clan","redridge gnolls","shadowhide lore","клан темношкуров","гноллы красногорья","предания о темношкурах"}}},fp="26,333,18.465.0,21.441.0,26.209.0,45.174.0,57.282.0,43.127.0,48.222.0,31.219.0"}
P.entries["quest:1801"] = {n="Фолиант заговора",s="Это задание отправляет чернокнижников Орды из лагеря Страхада Фарсана в Степях в Подгород на поиски древних знаний о демонологии. Чтобы призвать и подчинить охотника Скверны, посвященный должен найти утерянный Фолиант заговора, начав с картографа Йораха Аннисона. Это важный шаг к овладению высшим призывом демонов.",h="Это задание отправляет чернокнижников Орды из лагеря Страхада Фарсана в Степях в Подгород на поиски древних...",kw={"barrens","felhunter","jorah annison","ratchet","strahad farsan","tome of the cabal","undercity","warlock quest","степи","охотник скверны","йорах аннисон","кабестан","страхад фарсан","фолиант заговора","подгород","задание чернокнижника"},ang={["class:Warlock"]="Этот обряд посвящения обязателен для чернокнижников Орды, желающих приручить охотника Скверны: он требует путешествовать между Калимдором и Восточными королевствами, чтобы собрать забытые компоненты ритуала.",["faction:Horde"]="Задание показывает сотрудничество темных заклинателей Калимдора и оккультных ученых Отрекшихся, живущих под руинами Лордерона."},sec={{t="В поисках древних знаний",b="Призыв охотника Скверны — не мелкий фокус магии Скверны: эти хищные твари пожирают магическую энергию и сопротивляются обычным кругам призыва. Страхад Фарсан объясняет, что для этого посвященному нужны особые круги и древний гримуар — Фолиант заговора. Книга, написанная первым орденом чернокнижников, подчинившим охотника Скверны без посторонней помощи, содержит точные обряды и печати для порабощения столь опасного демона."},{t="Картограф из Подгорода",b="Поскольку экземпляры Фолианта заговора давно утеряны для чернокнижников Калимдора, Страхад отправляет ученика за море к Йораху Аннисону в Подгород. Хотя тот числится королевским картографом, составляющим карты Лордерона, Аннисон обладает исключительными знаниями о древних и малоизвестных текстах. Как признается он сам, он презирает простое ремесло картографа и куда больше жаждет редких хроник, оккультных повествований и трактатов о темной магии."}},faq={{q="Что такое Фолиант заговора?",a="Фолиант заговора — редкий оккультный гримуар, написанный первыми чернокнижниками, сумевшими призвать и подчинить охотника Скверны без посторонней помощи. В нем содержатся точные указания, обереги и обряды, нужные, чтобы безопасно привести в Азерот одного из этих зверей, пожирающих магию.",al={"tome of the cabal lore","what is this book","tome of cabal","предания о фолианте заговора","что это за книга","фолиант заговора"}},{q="Почему Страхад Фарсан посылает вас в Подгород?",a="У Страхада и его служителей в Степях нет экземпляра Фолианта заговора. Он знает, что Йорах Аннисон, картограф из Подгорода, — знаток редких и древних книг и, возможно, знает, где найти утерянные страницы или тома.",al={"why go to undercity","strahad farsan undercity","why see jorah","зачем в подгород","страхад фарсан подгород","зачем к йораху"}},{q="Кто такой Йорах Аннисон?",a="Йорах Аннисон — ученый из Отрекшихся, работающий в Подгороде. Хотя официально он занимается картографией и составлением карт, его истинная страсть — малоизвестные тексты, некромантические трактаты и древняя литература.",al={"who is jorah","jorah annison lore","кто такой йорах","предания об йорахе аннисоне"}},{q="Зачем нужна особая книга, чтобы призвать охотника Скверны?",a="Охотники Скверны питаются тайной и магической энергией, поэтому направлять их через обычные круги демонов трудно и опасно. Фолиант заговора описывает особые меры защиты, необходимые, чтобы подчинить их, пока они не поглотили призывателя.",al={"why felhunter need book","why is felhunter hard to summon","зачем охотнику скверны книга","почему трудно призвать охотника скверны"}}},fp="17,352,28.467.0,29.487.0,30.273.0,50.237.0,21.209.0,51.254.0"}
P.entries["quest:1802"] = {n="Фолиант заговора",s="В этом задании чернокнижнику Альянса предстоит разыскать разрозненные, поврежденные половины единственного гримуара — Фолианта заговора. Возвращение недостающих страниц из дальних земель необходимо, чтобы расшифровать темные обряды, нужные для подчинения охотника Скверны.",h="В этом задании чернокнижнику Альянса предстоит разыскать разрозненные, поврежденные половины единственного...",kw={"azurelode mine","felhunter","ironforge","krom stoutarm","moldy tome","splithoof hold","strahad farsan","tattered manuscript","tome of the cabal","лазуритовый рудник","охотник скверны","стальгорн","кром крепкорук","заплесневелый фолиант","оплот треснувшего копыта","страхад фарсан","потрепанный манускрипт","фолиант заговора"},ang={["class:Warlock"]="Возвращение разорванных половин этого гримуара — обряд посвящения, открывающий важнейшие ритуалы призыва, нужные, чтобы извлечь охотника Скверны из Пустоты и подчинить его.",["faction:Alliance"]="Практики Альянса полагаются на связи в Стальгорне, такие как Кром Крепкорук, чтобы выслеживать редкие демонические реликвии на разных континентах, не вызывая открытых подозрений церкви или короны."},sec={{t="Разделенный гримуар",b="Фолиант заговора был переписан лишь в одном экземпляре, и его бурная история не дала ему уцелеть целым. Разорванный и испорченный, он был разбросан по совершенно разным уголкам мира. Одна часть — потрепанный манускрипт, вырванный прямо из переплета, — каким-то образом пересекла море и оказалась в суровых каньонах Калимдора, в руках кланов кентавров. Остальную часть собирались перевезти морем с берегов Лордерона в Каз Модан, но корабль потерпел крушение, не дойдя до порта."},{t="Через море и каньон",b="Чтобы собрать гримуар, нужно пережить две опасные задачи. Страницы, потерянные на море, вынесло на берег Хилсбрада к западу от Южнобережья, где обломки и отсыревшие реликвии достались прибрежным мурлокам возле Лазуритового рудника. Засушливую же половину придется добыть, проникнув в Оплот Треснувшего Копыта в Тысяче Игл и спустившись в пещеры кентавров, чтобы забрать манускрипт из древнего сундука. Только соединив эти половины, Кром Крепкорук сможет осмотреть утраченный текст, прежде чем он вернется к Страхаду Фарсану."}},faq={{q="Что такое Фолиант заговора?",a="Это редкий, единственный в своем роде демонический гримуар, содержащий тайные знания, необходимые чернокнижникам. В нем собраны сложные заклинания и ритуалы подчинения, нужные, чтобы призвать и покорить охотника Скверны из Круговерти Пустоты.",al={"tome of the cabal lore","what is this book","tome cabal","предания фолианта заговора","что это за книга","фолиант заговора"}},{q="Кто такой Кром Крепкорук и зачем ему фолиант?",a="Кром Крепкорук — дворф из Стальгорна, погруженный в изучение редких и забытых текстов. В обмен на то, что он расскажет чернокнижникам Альянса, где оказались разорванные части фолианта, он просит лишь возможности изучить содержимое лично, когда части будут найдены.",al={"who is krom stoutarm","why does krom want the book","krom stoutarm ironforge","кто такой кром крепкорук","зачем крому книга","кром крепкорук стальгорн"}},{q="Где оказались две части книги?",a="Заплесневелый фолиант вынесло на берег Хилсбрада к западу от Южнобережья, рядом с Лазуритовым рудником, и его подобрали прибрежные мурлоки. Потрепанный манускрипт оказался в Калимдоре, в Оплоте Треснувшего Копыта, в потрепанном сундуке в глубине пещеры кентавров в Тысяче Игл.",al={"where are the tome pieces","book locations","tattered manuscript location","где части фолианта","местонахождение книги","где потрепанный манускрипт"}},{q="Почему фолиант вообще был разорван?",a="Фолиант заговора был переписан лишь в одном экземпляре. Когда-то в его туманном прошлом его намеренно испортили: большую часть вырвали из переплета и увезли в Калимдор, а остальное было потеряно в море во время злополучного плавания в Гавань Менетилов.",al={"why was the book ripped","who vandalized the tome","почему книга разорвана","кто испортил фолиант"}},{q="Кто такой Страхад Фарсан и какое он имеет отношение к заданию?",a="Страхад Фарсан — опытный чернокнижник, живущий неподалеку от Кабестана в Степях. Он направляет начинающих призывателей за фолиантом, чтобы они могли изучить обряды, необходимые для призыва и подчинения охотника Скверны под его руководством.",al={"who is strahad","strahad farsan","strahad connection","кто такой страхад","страхад фарсан","связь со страхадом"}},{q="Почему Заплесневелый фолиант покрыт морской грязью?",a="Книга находилась на корабле, шедшем к Гавани Менетилов от берегов Лордерона, который так и не достиг цели. Обломки корабля прибило к берегу Хилсбрада, где отсыревшие, заплесневелые страницы подобрали прибрежные мурлоки возле Лазуритового рудника.",al={"why is moldy tome wet","hillsbrad tome murlocs","почему заплесневелый фолиант мокрый","фолиант хилсбрад мурлоки"}}},fp="17,262,18.560.0,21.545.0,30.227.0,51.262.0,44.274.0,47.281.0,66.214.0,43.247.0"}
P.entries["quest:1803"] = {n="Фолиант заговора",s="В этом задании чернокнижникам Орды предстоит воссоединить разделенные половины древнего Фолианта заговора для Йораха Аннисона в Подгороде. Некогда хранившийся в королевстве Лордерон, гримуар был разорван и разбросан по миру, а затем полностью утерян. Чтобы найти его отсыревшие и потрепанные остатки, нужно пересечь враждебные воды Восточных королевств и забраться вглубь земель кентавров в Калимдоре.",h="В этом задании чернокнижникам Орды предстоит воссоединить разделенные половины древнего Фолианта заговора для...",kw={"galak","jorah annison","lordaeron","moldy tome","southshore","splithoof hold","tattered manuscript","thousand needles","tome of the cabal","warlock quest","галак","йорах аннисон","лордерон","заплесневелый фолиант","южнобережье","оплот треснувшего копыта","потрепанный манускрипт","тысяча игл","фолиант заговора","задание чернокнижника"},ang={["class:Warlock"]="Возвращение Фолианта заговора — обряд посвящения для чернокнижников среднего уровня: вы собираете утраченные тайные знания Лордерона, чтобы расширить свой арсенал призыва.",["faction:Horde"]="Поиски манускрипта ведут вас через каньоны Тысячи Игл, где силы Орды, расквартированные на Заставе Вольного Ветра, ведут непрекращающуюся войну с местными кентаврами.",["race:Undead"]="Фолиант хранился в Лордероне до падения королевства, поэтому его возвращение — это возвращение тайного наследия из прежней, человеческой жизни Отрекшихся."},sec={{t="Разделенное наследие",b="Фолиант заговора некогда хранился в стенах библиотеки старого королевства Лордерон. Незадолго до падения королевства зловещий гримуар намеренно испортили, лишили почти половины страниц и разорвали на две части. Оставшийся переплетенный текст собирались отправить на юг, в дворфийские залы Стальгорна, но судьба распорядилась иначе: корабль разбился у скалистого побережья к западу от Южнобережья, и страницы остались гнить на мелководье под присмотром мурлоков-собирателей."},{t="Разбросанный по континентам",b="Испорченная половина фолианта забрела еще дальше. Похищенная из Лордерона, она добралась до южного Калимдора и попала в грубые руки кентавров Галака в глубине Оплота Треснувшего Копыта в Тысяче Игл. Чтобы вернуть весь текст, чернокнижнику нужно обыскать сырой берег Хилсбрада в поисках Заплесневелого фолианта и проникнуть в пыльные, дикие каньоны кентавров за Потрепанным манускриптом. Когда обе части будут принесены Йораху Аннисону, легендарный темный текст вновь станет единым, читаемым томом."}},faq={{q="Что такое Фолиант заговора?",a="Это тайный демонический гримуар, некогда хранившийся в столице Лордерона. Он содержит продвинутые ритуалы чернокнижников, но был испорчен и разделен на две части, а затем потерян на двух разных континентах.",al={"tome of the cabal lore","what is this book","tome of cabal","предания фолианта заговора","что это за книга","фолиант заговора"}},{q="Почему одна часть книги оказалась возле Южнобережья?",a="После того как книгу испортили, уцелевшую переплетенную часть собирались передать ученым Стальгорна. Однако корабль, перевозивший ее, разбился у побережья к западу от Южнобережья, и гримуар остался среди местных мурлоков.",al={"why southshore","moldy tome origin","coast west of southshore","почему южнобережье","происхождение заплесневелого фолианта","побережье к западу от южнобережья"}},{q="Как страницы оказались у кентавров в Тысяче Игл?",a="Примерно половину страниц вырвали из оригинального фолианта в Лордероне и тайно вывезли. Через торговлю, грабеж или переходя из рук в руки, этот потрепанный манускрипт в конце концов оказался в глубине Оплота Треснувшего Копыта, в сундуке у кентавров Галака.",al={"why centaur have it","thousand needles pages","splithoof hold book","почему он у кентавров","страницы тысяча игл","книга оплот треснувшего копыта"}},{q="Кто такой Йорах Аннисон?",a="Йорах Аннисон — Отрекшийся чернокнижник, обосновавшийся в Магическом квартале Подгорода. Он наставляет молодых чернокнижников Орды в поисках забытых, запретных знаний, чтобы углубить их власть над демоническими силами.",al={"jorah annison lore","who is jorah","предания йорах аннисон","кто такой йорах"}},{q="Кто вообще испортил фолиант?",a="Точная личность виновника остается неизвестной. Сам Йорах Аннисон сокрушается о вандализме и спрашивает, кто мог совершить такое злодеяние против текста столь глубокой тайной силы.",al={"who tore the book","who stole the pages","tome vandal","кто разорвал книгу","кто украл страницы","вандал фолианта"}},{q="Что делает Йорах с книгой, когда вы приносите обе части?",a="Получив и Заплесневелый фолиант, и Потрепанный манускрипт, Йорах Аннисон собирает части в единый том и просматривает его страницы, готовя вас к следующим шагам в ваших демонических обрядах.",al={"what happens after turn in","restored tome","что будет после сдачи","восстановленный фолиант"}}},fp="17,405,16.528.0,27.563.1,30.206.0,44.241.0,62.248.0,21.210.0,43.189.0,64.204.0"}
P.entries["quest:1804"] = {n="Фолиант заговора",s="Это задание — последняя подготовка чернокнижников Альянса, стремящихся подчинить охотника Скверны. Собрав воедино разрозненный Фолиант заговора, чернокнижник должен добыть жезлы направления у орков Драконьей Пасти в Болотине и вернуться к Страхаду Фарсану, живущему над Кабестаном.",h="Это задание — последняя подготовка чернокнижников Альянса, стремящихся подчинить охотника Скверны.",kw={"barrens","dragonmaw","felhunter","krom stoutarm","ratchet","rods of channeling","strahad farsan","tome of the cabal","wetlands","степи","драконья пасть","охотник скверны","кром крепкорук","кабестан","жезлы направления","страхад фарсан","фолиант заговора","болотина"},ang={["class:Warlock"]="Укрощение охотника Скверны — важнейший обряд посвящения, возвышающий чернокнижника от простых союзов с бесами и демонами Бездны до власти над хищными демонами, созданными, чтобы пожирать тайную магию.",["faction:Alliance"]="Это задание отправляет призывателей Альянса путешествовать между Стальгорном, туманными топями Болотины и нейтральным гоблинским портом Кабестан в Калимдоре.",["race:Dwarf"]="Даже темные искусства зависят от мастерства сохранения, которым славится Зал Исследователей Стальгорна, где Кром Крепкорук собирает разрушенные реликвии воедино."},sec={{t="Неохотная передача",b="В Зале Исследователей Стальгорна Кром Крепкорук тщательно сшил обгоревшие и заплесневелые остатки Фолианта заговора. Неохотно расставаясь с таким редким образцом темной учености, ученый дворф берет обещание будущей копии и передает свежее послание от Страхада Фарсана. В фолианте записаны обряды, нужные, чтобы пробить брешь в Пустоту, но один лишь пергамент провести ритуал не может."},{t="Похищенные реликвии Драконьей Пасти",b="Прежде чем послушники Страхада смогут помочь в подчинении демона столь ненасытного, как охотник Скверны, им нужны фокусирующие предметы для стабилизации призванных энергий. Кром направляет чернокнижника в Болотину, где заклинатели клана Драконьей Пасти владеют жезлами направления. Вырвав эти фокусы из рук враждебных орков, вы получите проводник, необходимый кругу Страхада для управления разломом."},{t="Обратно в Степи",b="Доставка восстановленного гримуара и жезлов чародеев в башню Страхада высоко над Кабестаном завершает изнурительную сборку. Когда инструменты добыты, а текст переведен, Страхад готовится начать опасный обряд подчинения, проверяя, хватит ли призывателю силы воли, чтобы укротить гончую Пылающего Легиона."}},faq={{q="Зачем Страхаду жезлы направления?",a="Призыв и подчинение охотника Скверны слишком бурны для одинокого чернокнижника без опоры. Послушники Страхада должны поддерживать и направлять круг призыва во время ритуала, а эти жезлы направляют и стабилизируют нужные энергии, не давая порталу рухнуть или выйти из-под контроля.",al={"why rods of channeling","rods of channeling purpose","what are the rods for","зачем жезлы направления","назначение жезлов направления","для чего нужны жезлы"}},{q="Где найти жезлы направления?",a="Жезлы находятся у орков-заклинателей клана Драконьей Пасти, живущих в Болотине, особенно вокруг занятых ими болот и руин.",al={"where to get rods of channeling","who drops rods of channeling","rods of channeling location","где взять жезлы направления","с кого падают жезлы направления","местонахождение жезлов направления"}},{q="Почему Кром Крепкорук участвует в ритуале чернокнижников?",a="Krom Stoutarm is a master researcher in Ironforge with the specialized skills needed to translate, preserve, and physically reconstruct ancient, damaged manuscripts. His fascination with rare antiquities led him to restore the corrupted pages of the Tome of the Cabal.",al={"why krom","why is an ironforge dwarf helping a warlock","krom stoutarm warlock","почему кром","почему дворф из стальгорна помогает чернокнижнику","кром крепкорук чернокнижник"}},{q="Что происходит после передачи фолианта и жезлов Страхаду?",a="Страхад тут же пускает собранные предметы в дело и начинает обряд подчинения на вершине своей башни, где вы лично должны сразиться с призванным охотником Скверны и покорить его.",al={"what happens next","next quest after tome of the cabal 3","what does strahad do","что дальше","следующее задание после фолианта заговора 3","что делает страхад"}},{q="Кто такой Страхад Фарсан?",a="Страхад Фарсан — могущественный чернокнижник, живущий в одинокой башне на утесах над портовым городом Кабестан в Степях. Опытные чернокнижники по всему Калимдору и Восточным королевствам признают его мастерство в демонологии.",al={"strahad farsan lore","who is strahad","guy above ratchet","предания страхад фарсан","кто такой страхад","тип над кабестаном"}},{q="Использует ли Фолиант заговора и Орда?",a="Чернокнижники Орды следуют собственной версии обрядов Фолианта заговора, но их поиски ведут к другим контактам в Калимдоре и Подгороде, а не к Крому Крепкоруку в Стальгорне.",al={"horde tome of the cabal","do orcs do this quest","фолиант заговора орды","выполняют ли орки это задание"}}},fp="17,278,19.436.0,30.375.0,19.338.1,41.284.0,39.144.0,51.268.0,55.165.1,22.242.0,51.209.0"}
P.entries["quest:1805"] = {n="Фолиант заговора",s="Это задание — завершающий подготовительный этап на пути чернокнижника Орды к призыву и подчинению охотника Скверны. Помогши Йораху Аннисону восстановить древний Фолиант заговора, чернокнижник должен отправиться на вражескую территорию, добыть три жезла направления потока и доставить их Страхаду Фарсану в Кабестан.",h="Это задание — завершающий подготовительный этап на пути чернокнижника Орды к призыву и подчинению охотника...",kw={"angerfang encampment","dragonmaw","felhunter","jorah annison","ratchet","rod of channeling","strahad farsan","tome of the cabal","wetlands","лагерь злого клыка","драконья пасть","охотник скверны","йорах аннисон","кабестан","жезл направления потока","страхад фарсан","фолиант заговора","болотина"},ang={["class:Warlock"]="Это испытание проверяет вашу решимость добыть опасные ритуальные реагенты на вражеских землях и доказывает, что у вас хватает знаний и смелости подчинить хищного охотника Скверны своей воле.",["faction:Horde"]="Изгои Драконьей Пасти в Болотине остаются заклятыми врагами Орды Тралла, поэтому насильственное возвращение их жезлов — двойная победа для интересов Орды.",["race:Orc"]="Расправа над отступниками из клана Драконьей Пасти в Болотине — суровое напоминание о темном, нераскаявшемся пути, который Орда стремилась оставить позади.",["race:Undead"]="Научная работа Йораха Аннисона в Подгороде отражает традицию чернокнижников Отрекшихся изучать запретные тайные тексты ради практического господства над магией."},sec={{t="Тайны Восстановленного фолианта",b="В Подгороде ученый из Отрекшихся Йорах Аннисон изучает фрагменты найденного Фолианта заговора, складывая воедино его зловещие строки. Довольный редкой интеллектуальной добычей, Йорах передает срочное поручение от Страхада Фарсана. Чтобы подчинить демонического хищника вроде охотника Скверны, одних знаний мало: чернокнижнику нужны точные орудия силы, способные направить яростную демоническую энергию в круг призыва."},{t="Путь в Болотину",b="Страхаду нужны три жезла направления потока — особые проводники, которые носят орки-изгои из клана Драконьей Пасти. Вдали от родных земель Орды эти орки Драконьей Пасти обитают среди руин Лагеря Злого Клыка в сырых топях Болотины. Чтобы выследить их, придется войти в спорные земли, где правят враждебные остатки клана: они презирают нынешнюю Орду не меньше, чем безжалостно убивают исследователей Альянса."},{t="Возвращение в Кабестан",b="Добыв жезлы и сохранив Восстановленный фолиант, чернокнижник возвращается через море к башне Страхада Фарсана над Кабестаном. Страхад встречает вернувшегося заклинателя мрачным удовлетворением. Все составляющие ритуала призыва собраны, и впереди опасное испытание воли в схватке с неукрощенным существом из Круговерти Пустоты."}},faq={{q="Для чего нужно это задание?",a="Это третий шаг в цепочке заданий чернокнижника Орды на пути к умению призывать охотника Скверны. Нужно доставить восстановленный Фолиант заговора и три жезла направления потока Страхаду Фарсану над Кабестаном.",al={"why do this quest","quest purpose","what is tome of the cabal for","зачем выполнять это задание","цель задания","для чего нужен фолиант заговора"}},{q="Кто такой Йорах Аннисон?",a="Йорах Аннисон — чернокнижник и ученый из Отрекшихся, обосновавшийся в Магическом квартале Подгорода. Он изучает тайные и темные тексты и помогает собратьям, собирая воедино разбитые гримуары, такие как Фолиант заговора.",al={"who is jorah","jorah annison lore","кто такой йорах","йорах аннисон предания"}},{q="Зачем нужны жезлы направления потока?",a="Призыв и подчинение охотника Скверны требуют точного метафизического контроля. Жезлы служат проводниками, которые стабилизируют и формируют круг призыва, чтобы чернокнижник покорил демона, а не был им пожран.",al={"why rods of channeling","rods purpose","зачем жезлы направления потока","назначение жезлов"}},{q="Где находятся орки Драконьей Пасти для этого задания?",a="Клан Драконьей Пасти удерживает Лагерь Злого Клыка в Болотине — землях, где преобладает Альянс, за морем в Каз Модане. Желанные жезлы носят их заклинатели костей.",al={"where to find dragonmaw","dragonmaw location wetlands","angerfang encampment","где найти драконью пасть","драконья пасть болотина","лагерь злого клыка"}},{q="Кто такой Страхад Фарсан?",a="Страхад Фарсан — влиятельный человек-чернокнижник, союзник темных заклинателей Орды. Он живет в уединенной башне на утесах над гоблинским портом Кабестан в Степях.",al={"who is strahad","strahad farsan ratchet","кто такой страхад","страхад фарсан кабестан"}},{q="Что происходит после выполнения этого задания?",a="Эта доставка напрямую ведет к заданию «Связывание», где Страхад велит чернокнижнику начертить круг призыва и сразиться с призванным охотником Скверны в магическом бою, чтобы подчинить его.",al={"what comes next","next quest after tome","что дальше","следующее задание после фолианта"}}},fp="17,320,33.453.0,25.411.0,17.365.1,34.199.0,21.231.0,34.222.0,52.199.0,22.192.0,41.191.1"}
P.entries["quest:1806"] = {n="Испытание доблести",s="Испытание доблести завершается у кузни Джордана Стилвелла за пределами Стальгорна в Дун Мороге. Собрав опасные компоненты по всем Восточным королевствам и Калимдору, паладин ждет, пока кузнец выковывает могучий боевой молот. Это знаменует превращение ученика в признанного защитника Света.",h="Испытание доблести завершается у кузни Джордана Стилвелла за пределами Стальгорна в Дун Мороге.",kw={"bosch verigan","dun morogh","forge","hammer","ironforge","jordan stilwell","paladin","test of righteousness","verigan","бош вериган","дун морог","кузня","молот","стальгорн","джордан стилвелл","паладин","испытание доблести","вериган"},ang={["class:Paladin"]="Этот обряд посвящения вознаграждает ваши опасные странствия по дальним землям Боевой перчаткой Веригана — знаковым оружием, посвященным защите справедливости.",["profession:Blacksmithing"]="Работа Джордана Стилвелла у наковальни показывает, как мастерство способно вложить священную цель в сырую сталь и найденные материалы.",["race:Dwarf"]="Выкованный здесь молот увековечивает память о Боше Веригане, почтенном паладине-дворфе, воплотившем стойкость Каз Модана."},sec={{t="Дань кузнеца",b="Мастер-кузнец Джордан Стилвелл трудится у врат Стальгорна. Он признает, что немного завидует странствующим паладинам, но глубоко гордится тем, что поддерживает их дело молотом и наковальней. Получив редкие материалы из мрачных склепов, затонувших руин и опасных шахт, Стилвелл исполняет обещание и выковывает оружие, достойное настоящего защитника."},{t="Наследие Бозха Веригана",b="Готовый боевой молот получает имя «Боевая перчатка Веригана» в честь Боша Веригана, почтенного паладина-дворфа и близкого друга Джордана Стилвелла. Передавая это священное оружие в руки молодого защитника от себя и жены, Стилвелл следит за тем, чтобы память и доблесть павшего друга жили в борьбе с тьмой, угрожающей Азероту."}},faq={{q="Что происходит на этом этапе задания?",a="Джордан Стилвелл подходит к наковальне и бьет по раскаленному металлу, соединяя компоненты, которые вы собрали в тяжких испытаниях. Закончив работу в кузне, он возвращается и вручает вам готовое оружие.",al={"test of righteousness ending","jordan forging weapon","verigan cutscene","окончание испытания доблести","джордан кует оружие","сцена с веригана"}},{q="Кто такой Бош Вериган?",a="Бош Вериган был уважаемым паладином-дворфом и близким другом Джордана Стилвелла. Джордан назвал новый двуручный молот в его память, чтя его преданность Свету.",al={"who is verigan","verigans fist namesake","bosch verigan","кто такой вериган","в честь кого боевая перчатка веригана","бош вериган"}},{q="Где происходит ковка?",a="Ковка происходит сразу за великими вратами Стальгорна на заснеженных пиках Дун Морога, где у Джордана Стилвелла стоят кузня и наковальня.",al={"jordan stilwell location","where is the forge","dun morogh anvil","где джордан стилвелл","где кузня","наковальня дун морог"}},{q="Зачем Джордану понадобились редкие материалы со всего мира?",a="Джордан задумал оружие исключительного равновесия и священного резонанса. Чтобы выковать то, что выдержит священный гнев паладина, ему требовались редкие руды, дерево и самоцветы, которые можно добыть лишь в опасных местах по всему миру.",al={"why gathering materials","quest components test of righteousness","зачем собирать материалы","компоненты задания испытание доблести"}},{q="Сражается ли Джордан Стилвелл сам?",a="Джордан Стилвелл — кузнец, а не странствующий воин. Хотя он признается, что порой завидует искателям приключений, бродящим по свету, свое истинное предназначение и гордость он находит в ковке оружия для защитников Света.",al={"is jordan a warrior","jordan stilwell fighter","джордан воин","джордан стилвелл боец"}},{q="Что значит получение этого молота для паладина?",a="Получение молота означает успешное завершение долгих испытаний паладина. Оно доказывает, что владелец обладает мужеством, упорством и священной убежденностью, нужными, чтобы защищать Свет в самых опасных уголках Азерота.",al={"verigans fist meaning","paladin rite of passage","значение боевой перчатки веригана","обряд посвящения паладина"}}},fp="25,320,17.391.0,27.358.0,43.211.0,21.190.0,35.152.0,59.243.0,50.225.0,54.228.0"}
P.entries["quest:181"] = {n="Взгляни на звезды",s="Это задание — последняя глава в стремлении Виктора Призм’Антраса собрать прибор для наблюдения за звездами в Темнолесье. Конструкция телескопа почти готова, и Виктор отправляет путников в опасную Лощину Вул'Гол за линзой, достаточно большой для его устройства, — моноклем огра Зарк'Вула.",h="Это задание — последняя глава в стремлении Виктора Призм’Антраса собрать прибор для наблюдения за звездами в...",kw={"cog","darkshire","look to the stars","monocle","telescope","viktori prism'antras","vul'gol ogre mound","zzarc'vul","зубец","темнолесье","взгляни на звезды","монокль","телескоп","виктор призм’антрас","лощина вул'гол","зарк'вул"},ang={["faction:Alliance"]="Темнолесье едва выживает среди ужасов и чудовищ, и стремление Виктора к познанию небес остается стойким, пусть и чудаковатым, маяком упорства мирных жителей.",["profession:Engineering"]="Маги и механики одинаково ценят дерзость замены линзы огромным моноклем огра ради фокусного расстояния астрономической линзы.",["race:Gnome"]="Устройство опирается на чертежи, созданные гномьим мастерством, и требует изобретательной импровизации — например, превращения грубой оправы в точную оптику."},sec={{t="Последняя деталь",b="На протяжении всей постройки телескопа Виктор Призм’Антрас опирался на чертежи гнома-инженера Зубца Мишурного Прядильщика. Латунные трубы и прочные крепления можно было найти или собрать из местных запасов, но прибору требовалась исключительно крупная фокусирующая линза. Обычным лупам и оптике от штормградских торговцев не хватало диаметра, которого требовал замысел Зубца, и Виктор обратил взгляд на неожиданный и опасный вариант."},{t="Окуляр огра",b="В тени южных холмов лежит Лощина Вул'Гол — лагерь, кишащий враждебными ограми. Среди них живет Зарк'Вул, особый огр, носящий стеклянный монокль, достаточно большой для линзы обсерватории. Проникнув вглубь лощины и забрав окуляр у Зарк'Вула, можно исполнить чертежи Зубца, и тогда Виктор закончит телескоп и взглянет в небеса над темным пологом Сумеречного леса."}},faq={{q="Кто такой Виктор Призм’Антрас?",a="Виктор Призм’Антрас — астроном и ученый, живущий в хижине на холме в Темнолесье. Несмотря на мрак, окутавший Сумеречный лес, он продолжает стремиться достроить телескоп обсерватории, чтобы изучать звезды.",al={"who is viktori","viktori prism'antras","кто такой виктор","виктор призм’антрас"}},{q="Где найти Зарк'Вула?",a="Зарк'Вул обитает на юге Сумеречного леса в Лощине Вул'Гол. Он бродит по лагерю и сети пещер лощины, поэтому искателям приходится пробираться через сильно охраняемые земли огров.",al={"zzarc'vul location","where is the ogre","ogre monocle location","где зарк'вул","где огр","где монокль огра"}},{q="Почему у огра есть монокль?",a="Хотя огры не славятся тягой к наукам и тонкой оптике, Зарк'Вул носит огромный монокль. Его необычные размеры делают его единственной линзой в округе, достаточно большой для чертежей телескопа Зубца.",al={"why ogre monocle","ogre's monocle lore","зачем огру монокль","предания о монокле огра"}},{q="Что будет, когда устройство завершено?",a="Добыв монокль, Виктор может установить последний оптический элемент. Когда телескоп полностью собран, Виктор сможет продолжить изучение небес, не мешая унылой лесной земле внизу.",al={"telescope finished","quest conclusion","телескоп готов","завершение задания"}},{q="Кто разработал телескоп?",a="Чертежи устройства предоставил инженер по имени Зубец. Его сложный замысел требовал особых деталей, металлического каркаса и линзы, намного больше обычных очков дворфов или гномов.",al={"cog blueprints","who built telescope","чертежи зубца","кто построил телескоп"}},{q="Безопасно ли входить в Лощину Вул'Гол в одиночку?",a="Нет. Лощина Вул'Гол густо населена враждебными ограми, которые часто патрулируют группами или охраняют узкие тропы. Проникновение вглубь лощины на поиски Зарк'Вула крайне опасно для одиночек.",al={"vul'gol difficulty","ogre mound safe","сложность вул'гол","безопасна ли лощина огров"}}},fp="17,312,15.508.0,19.438.1,28.210.0,27.220.0,35.226.0,42.197.0,27.202.0,42.212.0"}
P.entries["quest:1818"] = {n="Разговор с Диллинджером",s="«Разговор с Диллинджером» — военный приказ Орды, выдаваемый в Подгороде. Остил де Мон направляет боеспособных бойцов к Стражу смерти Диллинжеру в Брилл для опасного боевого задания во имя леди Сильваны.",h="«Разговор с Диллинджером» — военный приказ Орды, выдаваемый в Подгороде.",kw={"austil de mon","brill","deathguard dillinger","speak with dillinger","tirisfal glades","ulag the cleaver","undercity","остил де мон","брилл","страж смерти диллинжер","разговор с диллинджером","тирисфальские леса","улаг колун","подгород"},ang={["class:Warrior"]="Командиры Стражей смерти превыше всего ценят воинскую стойкость, поэтому это поручение — прямая проверка ваших боевых способностей на передовой.",["faction:Horde"]="Отклик на призывы к обороне Подгорода укрепляет солидарность между союзниками Калимдора и недавно принятыми в Орду Отрекшимися.",["race:Undead"]="Для недавно освободившихся Отрекшихся ответ на призыв Диллинжера — важный шаг к тому, чтобы доказать свою преданность Темной Госпоже и защите Тирисфаля."},sec={{t="Вызов на передовую",b="В подземных залах Подгорода Остил де Мон внимательно высматривает многообещающих бойцов, готовых служить Темной Госпоже. Когда Стражам смерти на поверхности нужны умелые руки, де Мон отправляет неопытных искателей приключений из королевской столицы в поле. Страж смерти Диллинжер, отвечающий за безопасность на западных окраинах Брилла, ищет человека с боевым мастерством для срочного дела."},{t="Проверка верных",b="Брилл находится прямо на передовой Тирисфальских лесов, где Отрекшиеся должны постоянно доказывать свое боевое превосходство над враждебными угрозами. Пост Диллинжера возле деревенского кладбища позволяет ему удобно отражать местные вторжения. Для молодого воина явка к Диллинжеру — не просто поручение, а официальная проверка боевых навыков и политической верности только что созданному народу Отрекшихся."}},faq={{q="Кто посылает меня на это задание?",a="Остил де Мон из Подгорода подбирает будущих солдат и отправляет их на помощь Стражу смерти Диллинжеру.",al={"quest giver","austil de mon","who starts speak with dillinger","персонаж, выдающий задания","остил де мон","кто начинает разговор с диллинджером"}},{q="Где найти Стража смерти Диллинжера?",a="Страж смерти Диллинжер стоит на западной окраине Брилла в Тирисфальских лесах, возле входа на кладбище.",al={"dillinger location","where is dillinger","find dillinger","где диллинжер","местоположение диллинжера","найти диллинжера"}},{q="Зачем нужно являться к Диллинжеру?",a="Диллинжеру нужен боеспособный воин для боевого задания по защите Брилла, чтобы доказать свою преданность делу Отрекшихся.",al={"why speak with dillinger","dillinger purpose","зачем говорить с диллинжером","цель диллинжера"}},{q="Какое поручение приготовил Диллинжер?",a="Когда вы явитесь к Стражу смерти Диллинжеру, он поручит вам выследить опасного врага по имени Улаг Колун.",al={"what does dillinger want","next quest dillinger","чего хочет диллинжер","следующее задание диллинжера"}},{q="Получают ли этот приказ другие расы Орды?",a="Любой воин Орды, заслуживший доверие чиновников Подгорода, может взяться за это задание, хотя оно в основном предназначено для проверки новобранцев, защищающих Тирисфальские леса.",al={"is this undead only","can orcs do this","только для нежити","могут ли орки"}},{q="Почему этот приказ выдают в Подгороде, а не в Брилле?",a="Остил де Мон служит в столице вербовщиком и направляет новых умелых бойцов к командирам на передовой, которым срочно нужна сила.",al={"why undercity start","austil de mon role","почему подгород","роль остила де мона"}}},fp="20,221,22.434.0,20.419.0,29.117.0,40.111.0,46.129.0,45.117.1,40.168.0,62.153.0"}
P.entries["quest:1819"] = {n="Улаг Колун",s="«Улаг Колун» — обряд посвящения молодых воинов Отрекшихся в Тирисфальских лесах. Страж смерти Диллинжер поручает вам освободить и казнить порабощенного воина Плети, заточенного в северном мавзолее, проверив свою воинскую решимость и заслужив уважение Стражей смерти.",h="«Улаг Колун» — обряд посвящения молодых воинов Отрекшихся в Тирисфальских лесах.",kw={"brill","deathguard dillinger","dillinger","mausoleum","scourge","skull stone","ulag","ulag the cleaver","брилл","страж смерти диллинжер","диллинжер","мавзолей","плеть","камень-череп","улаг","улаг колун"},ang={["class:Warrior"]="Это испытание — ранняя проверка для воинов Отрекшихся, где вы проверите свою отвагу в бою с сильным подконтрольным чемпионом Плети.",["race:Undead"]="Судьба Улага показывает ужасную реальность власти Плети и трагическую разницу между Отрекшимися, обретшими свободу, и теми, чей разум остается порабощен Королем-личом."},sec={{t="Пленный раб Плети",b="Когда Плеть захлестнула Лордерон, Отрекшимся удалось захватить необычного воина-нежить, назвавшегося Улагом Колуном. Хотя разум Улага оставался ясным и сознательным, его дух был безраздельно подчинен психической власти Короля-лича. Желая понять, как Плеть подавляет свободную волю, Отрекшиеся держали его под магической печатью в мавзолее к северу от Брилла, надеясь разорвать духовные цепи."},{t="Испытание палача",b="Все попытки освободить Улага от ментальной хватки Короля-лича потерпели неудачу. Поняв, что истинная свобода возможна лишь через уничтожение, Страж смерти Диллинжер превратил пленника в боевое испытание для восходящих воинов Отрекшихся. Задев камень-череп у склепа, воин разрушает защитные чары, освобождает Улага из заточения и дарует ему покой острием топора."}},faq={{q="Кто такой Улаг Колун?",a="Улаг Колун — воин-нежить, захваченный Отрекшимися во время вторжения Плети в Тирисфальские леса. Он уникален тем, что сохранил свободный разум и личность, но оставался полностью подчинен ментальной команде Короля-лича.",al={"ulag lore","who is ulag","ulag the cleaver identity","предыстория улага","кто такой улаг","личность улага колуна"}},{q="Почему Улага заточили под мавзолеем?",a="Ученые и солдаты Отрекшихся заточили его под магической печатью, чтобы изучить, как действует контроль разума Короля-лича. Они надеялись найти способ разорвать психическую связь, но их опыты не удались.",al={"why is ulag locked up","mausoleum prisoner tirisfal","почему улаг заперт","узник мавзолея тирисфаль"}},{q="Почему Стражи смерти хотят убить Улага сейчас?",a="Признав, что не смогли освободить Улага от хватки Короля-лича, Отрекшиеся решили, что смерть — единственное оставшееся милосердие. Страж смерти Диллинжер решил использовать казнь как проверку воинской отваги и дисциплины для начинающих воинов.",al={"why kill ulag","reason to slay ulag","зачем убивать улага","причина убить улага"}},{q="Как вызвать Улага?",a="Он заточен под мавзолеем к северу от Брилла. Если взаимодействовать с камнем-черепом у гробницы, магическая печать падает, и Улаг встает и нападает.",al={"how to summon ulag","where is ulag","ulag skull stone","как вызвать улага","где улаг","камень-череп улага"}},{q="Кто выдает задание убить Улага?",a="Страж смерти Диллинжер, охраняющий западную дорогу из Брилла в Тирисфальских лесах, дает это поручение воинам Отрекшихся, ищущим дальнейшего обучения.",al={"quest giver ulag","who sends me to ulag","кто дает задание улага","кто посылает к улагу"}},{q="Что происходит после победы над Улагом?",a="Убедившись в гибели Улага, Страж смерти Диллинжер признает вашу доблесть и отправляет вас поговорить с Колманом Фартингом в Брилл, чтобы продолжить обучение.",al={"after ulag","ulag quest follow up","после улага","продолжение задания улага"}}},fp="16,280,22.455.0,23.417.0,24.233.0,44.246.0,44.236.0,21.178.0,33.174.0,36.156.0"}
P.entries["quest:182"] = {n="Пещера троллей",s="Это задание выдает горный стрелок Грелин Белобород: искателей приключений посылают истребить молодых троллей Мерзлогривов, собравшихся в южных пещерах Холодной долины. Пока Сенат Стальгорна занят растущим кризисом из-за троггов, разведчики-одиночки и добровольцы должны справиться с пограничными стычками, пока тролли не закрепились окончательно.",h="Это задание выдает горный стрелок Грелин Белобород: искателей приключений посылают истребить молодых троллей...",kw={"coldridge valley","dun morogh","frostmane","grelin whitebeard","troggs","trolls","whelp","холодная долина","дун морог","мерзлогрив","грелин белобород","трогги","тролли","детеныш"},ang={["class:Hunter"]="Скалы вокруг южной пещеры — суровая школа для молодых следопытов, учащихся выгонять враждебную добычу с горных высот.",["race:Dwarf"]="Для молодых дворфов Бронзобородов, впервые вышедших в снега, расправа над отрядами Мерзлогривов — вопрос и безопасности границ, и древней горной вражды.",["race:Gnome"]="Найдя приют в Дун Мороге после падения Гномрегана, гномы охотно дают свой ум и оружие, чтобы избавить дворфов-хозяев от окружающих угроз."},sec={{t="Глаза в холоде",b="Пока регулярные силы Стальгорна заняты отражением вторжений троггов с каменными челюстями на снежных полях, южные подступы нельзя оставлять без охраны. Горные власти направили Грелина Белоборода и его брата Сенира, чтобы выяснить, не представляют ли местные ледяные тролли непосредственной угрозы для сердца страны. Грелин в одиночку наблюдает за их передвижениями с утеса над замерзшей долиной."},{t="Упреждающий удар",b="Разведка Грелина показала, что местный клан Мерзлогривов начал обживать глубокую пещеру на южном хребте Холодной долины. Считая полную мобилизацию напрасной тратой сил дворфов, разведчик предпочел нанять местных добровольцев, чтобы истребить агрессивных детенышей. Сокращение числа молодых бойцов нарушает устройство их лагеря, пока Мерзлогривы не начали согласованные набеги на близлежащие дворфийские хутора."}},faq={{q="Почему Стальгорн не посылает регулярных солдат против этих троллей?",a="Сенат Стальгорна и дворфийская армия измотаны внезапным разрушительным вторжением троггов по всему Дун Морогу. Мелкие угрозы вроде небольших отрядов троллей поручены разведчикам вроде Грелина Белоборода, которые нанимают независимых искателей приключений.",al={"why no dwarven army","where are the guards","why hire adventurers","почему нет дворфийской армии","где стража","почему нанимают искателей приключений"}},{q="Кто такие тролли Мерзлогривы?",a="Мерзлогривы — коренное племя ледяных троллей, живущее в холодных скалах Дун Морога. Издавна враждебные Бронзобородам, они постоянно сталкиваются с горными пехотинцами из-за охотничьих угодий, территорий и древних горных перевалов.",al={"frostmane clan","dun morogh trolls","who are the frostmanes","клан мерзлогривов","тролли дун морога","кто такие мерзлогривы"}},{q="Где находится пещера троллей?",a="Пещера скрыта на южном горном хребте Холодной долины, к югу от наблюдательного лагеря Грелина Белоборода.",al={"troll cave location","where is the cave","where are the whelps","где пещера троллей","где пещера","где детеныши"}},{q="Кто такой Грелин Белобород?",a="Грелин Белобород — разведчик Стальгорна, расположившийся в Холодной долине. Вместе с братом Сениром, который следит за другими уголками Дун Морога, Грелин отслеживает враждебные популяции троллей и докладывает вождям дворфов.",al={"grelin","quest giver","whitebeard","грелин","персонаж, выдающий задания","белобород"}},{q="Почему Грелин нацелился именно на детенышей Мерзлогривов?",a="Лагерь на юге Холодной долины — растущее поселение, полное молодых воинов. Уничтожение растущих бойцов не дает племени стать достаточно сильным, чтобы угрожать дворфийским линиям снабжения.",al={"why whelps","why target young trolls","почему детеныши","почему молодые тролли"}},{q="Что происходит после истребления в пещере?",a="Вернувшись, вы обнаруживаете, что тролли ночью отомстили: разграбили лагерь Грелина и украли его личный полевой дневник, и теперь его нужно срочно вернуть из глубин их логова.",al={"what next","troll cave follow up","что дальше","продолжение пещеры троллей"}}},fp="14,348,16.431.0,19.464.0,70.270.0,29.237.0,32.120.0,25.216.0,53.218.0,36.197.1"}
P.entries["quest:1820"] = {n="Разговор с Колманом",s="«Разговор с Колманом» — переходное задание в Тирисфальских лесах для бойцов, проявивших себя в борьбе с Плетью. Страж смерти Диллинжер направляет умелых воинов с городской площади в местную таверну помочь Колману Фартингу в личных и фракционных расчетах.",h="«Разговор с Колманом» — переходное задание в Тирисфальских лесах для бойцов, проявивших себя в борьбе с...",kw={"agamand","brill","coleman farthing","deathguard dillinger","forsaken","gallow's end tavern","horde","tirisfal glades","агамонд","брилл","колман фартинг","страж смерти диллинжер","отрекшиеся","таверна конец виселицы","орда","тирисфальские леса"},ang={["faction:Horde"]="Для путников, помогающих защитить Лордерон, связи с местными жителями Брилла дают важную опору для действий по всем Тирисфальским лесам.",["race:Undead"]="Многие Отрекшиеся хранят личные обиды наряду с верностью Темной Госпоже; поручения Колмана Фартинга отражают, как личные потери и защита страны переплетены в Тирисфале."},sec={{t="Слово стражника",b="Помогая сдерживать серьезные местные угрозы, например упокоив опасные остатки Плети вроде Улага Колуна, искатели приключений заслуживают личное доверие Стража смерти Диллинжера. Как один из часовых на дорогах в Брилл, Диллинжер судит, кто способен на большее, чем обычное патрулирование периметра, и направляет умелых бойцов к горожанам, нуждающимся в особой помощи."},{t="Личная вендетта",b="Не каждый конфликт в Тирисфальских лесах ведется по приказу высшего командования из Подгорода. По всему разрушенному королевству Лордерон выжившая нежить хранит глубокие обиды, связанные с землями, семьями и состояниями, которые они оставили. Колман Фартинг выжидает в таверне «Конец виселицы» в поисках орудия мести угрозам, затаившимся возле бывших поселений, таких как Мельницы Агамондов."}},faq={{q="Где найти Колмана Фартинга?",a="Колман Фартинг ждет в таверне «Конец виселицы» на восточной стороне города Брилл в Тирисфальских лесах.",al={"coleman farthing location","where is coleman farthing","find farthing brill","где колман фартинг","местоположение колмана фартинга","найти фартинга брилл"}},{q="Кто посылает вас поговорить с Колманом?",a="Страж смерти Диллинжер, охраняющий входную дорогу в Брилл, посылает вас поговорить с Колманом после того, как вы докажете свое боевое мастерство.",al={"who gives speak with coleman","dillinger quest","кто дает разговор с колманом","задание диллинжера"}},{q="Какая работа есть у Колмана Фартинга?",a="Колман ищет умелого бойца в качестве орудия мести врагам Отрекшихся, в частности по делам вокруг старых владений Агамондов.",al={"what does coleman want","coleman farthing task","чего хочет колман","задание колмана фартинга"}},{q="Что требуется выполнить перед получением этого задания?",a="Страж смерти Диллинжер направляет вас к Колману, только когда вы докажете Отрекшимся свою верность и боевые навыки, победив Улага Колуна.",al={"prereqs for speak with coleman","ulag requirement","требования разговора с колманом","требование улага"}},{q="Дает ли это задание значительные награды сразу?",a="Это задание лишь сводит вас с Фартингом в таверне и открывает его личные поручения, а не дает значительное снаряжение или деньги само по себе.",al={"speak with coleman rewards","is it worth doing","награды разговора с колманом","стоит ли выполнять"}},{q="Что такое таверна «Конец виселицы»?",a="Таверна «Конец виселицы» — главный трактир Брилла, место встреч, отдыха и неформальный центр частных заказов среди местной нежити.",al={"brill tavern","gallows end tavern","таверна брилла","таверна конец виселицы"}}},fp="18,283,21.406.0,18.413.0,34.123.0,33.132.0,45.174.0,57.145.0,53.164.0,32.162.0"}
P.entries["quest:1821"] = {n="Наследие Агамондов",s="Колман Фартинг поручает искателям приключений разграбить Семейную усыпальницу Агамондов на северной окраине Мельниц Агамондов. Движимый горькой обидой за свою смертную гибель, он хочет отобрать у бывших хозяев их родовое оружие и лишить их последних остатков достоинства.",h="Колман Фартинг поручает искателям приключений разграбить Семейную усыпальницу Агамондов на северной окраине...",kw={"agamand family crypt","agamand heirlooms","agamand mills","coleman farthing","heirloom weapon","scourge","tirisfal glades","семейная усыпальница агамондов","наследие агамондов","мельницы агамондов","колман фартинг","фамильное оружие","плеть","тирисфальские леса"},ang={["class:Rogue"]="Незаметно проскользнуть мимо притаившихся вурдалаков и похитить древнее оружие из охраняемых склепов — вторая натура скрытных лазутчиков.",["faction:Horde"]="Зачистка усыпальницы подрывает укоренившуюся власть Плети на севере Тирисфальских лесов и делает эти земли безопаснее для путников Орды.",["race:Undead"]="Горькое задание Колмана Фартинга олицетворяет застарелые обиды и незажившие раны, которые многие Отрекшиеся пронесли из смертной жизни в нежизнь."},sec={{t="Горькая обида слуги",b="До того как Третья война опустошила Лордерон, Колман Фартинг служил богатому и влиятельному семейству Агамондов на их обширных мельницах в Тирисфальских лесах. Что бы ни произошло при падении их поместья, Фартинг целиком винит в своей смерти бывших господ. Теперь, поднятый из мертвых среди Отрекшихся, он со злорадным удовлетворением наблюдает за падением Агамондов и радуется тому, что некогда гордый род превратился в безмозглых приспешников, порабощенных Королем-личом."},{t="Осквернение усыпальницы",b="Чтобы окончательно уничтожить остатки величия семьи, Фартинг посылает искателей приключений в Семейную усыпальницу Агамондов, укрытую под северными утесами мельниц. В ее населенных призраками каменных залах бродят беспокойные мертвецы и остатки Плети. Фартинг требует достать четыре легендарные реликвии — фамильные меч, топор, кинжал и палицу Агамондов, — чтобы наследие их рода лишилось последней чести."}},faq={{q="Кем был Колман Фартинг при жизни?",a="Колман Фартинг был слугой богатого семейства Агамондов на Мельницах Агамондов до вторжения Плети в Лордерон. Он погиб во время катастрофы и винит в своей смерти хозяев; эта сильная обида сохранилась и в нежизни.",al={"who is coleman farthing","coleman backstory","farthing history","кто такой колман фартинг","предыстория колмана","история фартинга"}},{q="Почему Колману Фартингу нужно наследие?",a="Фартинг жаждет полной мести бывшим хозяевам. Похитив из семейной гробницы родовые меч, топор, кинжал и палицу, он хочет лишить павший род последних остатков чести и памяти.",al={"why steal heirlooms","coleman motive","why take weapons","зачем красть наследие","мотив колмана","зачем брать оружие"}},{q="Что случилось с семейством Агамондов?",a="Семейство Агамондов погибло, когда Плеть прошла по Тирисфальским лесам. Вместо покоя в смерти они были подняты как безмозглые нежить-рабы, подчиненные воле Короля-лича, и бродят по своим разрушенным мельницам и усыпальнице.",al={"agamand fate","are agamands alive","what are agamands now","судьба агамондов","живы ли агамонды","кто такие агамонды теперь"}},{q="Где находится Семейная усыпальница Агамондов?",a="Усыпальница находится на северной окраине Мельниц Агамондов, вырублена в скалистых утесах над зачумленными фермами на севере Тирисфальских лесов.",al={"crypt location","where is crypt","agamand crypt map","расположение усыпальницы","где усыпальница","карта усыпальницы агамондов"}},{q="Какое оружие хранится в усыпальнице?",a="В усыпальнице хранятся четыре отдельных родовых оружия: Фамильный меч Агамондов, Фамильный топор Агамондов, Фамильный кинжал Агамондов и Фамильная палица Агамондов.",al={"which heirlooms","four heirlooms","agamand weapons","какое наследие","четыре реликвии","оружие агамондов"}},{q="Почему Отрекшиеся нападают на Агамондов, если те тоже нежить?",a="Отрекшиеся обладают свободной волей и сражаются за собственное выживание, а нежить Агамондов остается безмозглыми рабами Плети, служащими Королю-личу, которого Отрекшиеся ненавидят.",al={"undead vs undead","why fight agamands","forsaken scourge conflict","нежить против нежити","почему сражаться с агамондами","конфликт отрекшихся и плети"}}},fp="17,272,25.468.0,21.443.0,33.266.0,45.219.0,36.230.0,42.144.0,39.181.0,63.180.0"}
P.entries["quest:1824"] = {n="Испытание на Полях Великанов",s="«Испытание на Полях Великанов» — воинское задание обряда, которое выдает Руга Тотем Гнева в Лагере Таурахо. В рамках обучения стремящиеся к мастерству воины отправляются на юг, в кишащие холмы Полей Великанов, чтобы убивать чужеродных насекомоподобных захватчиков. Кандидатам нужно собрать несколько еще подергивающихся усиков и поспешно доставить их обратно, пока биологическое доказательство не потеряло силу.",h="«Испытание на Полях Великанов» — воинское задание обряда, которое выдает Руга Тотем Гнева в Лагере Таурахо.",kw={"barrens","camp taurajo","field of giants","ruga ragetotem","silithid","twitching antenna","warrior trial","степи","лагерь таурахо","поля великанов","руга тотем гнева","силитид","подергивающийся усик","испытание воина"},ang={["class:Warrior"]="Это испытание — важный обряд посвящения около двадцатого уровня: оно проверяет умение воина быстро расправляться с роящимися противниками и сохранять физическую выносливость в жестких временных рамках.",["faction:Horde"]="Орда настороженно следит за растущим присутствием силитидов на юге Степей и считает отдельные учебные испытания передовой разведкой против подкрадывающейся угрозы.",["race:Tauren"]="Для тауренов-защитников очистка оскверненных Полей Великанов помогает защитить их охотничьи угодья вокруг Лагеря Таурахо от неестественного чужеродного улья."},sec={{t="Испытание скорости и стали",b="Наставники воинов Орды редко довольствуются одним лишь боевым мастерством, не проверив выносливость и расторопность. Руга Тотем Гнева бросает вызов растущим воинам в Лагере Таурахо: они должны проявить себя против незнакомого противника. Стремящимся мало просто убить наступающих тварей — они должны срезать свежие усики и вернуться в Таурахо в течение получаса, пока добытая ткань не перестала дергаться, а для этого нужно быстро пересечь юг Степей."},{t="Непрошеные гости",b="Цель испытания — ульи силитидов, разрастающиеся на Полях Великанов под огромными окаменевшими ребрами. Эти ползающие хитиновые насекомые недавно появились в Степях и тревожат таурен-охотников и шаманов, следящих за саваннами. Руга с тревогой отмечает, что их появление не сулит Калимдору ничего хорошего, и потому истребление служит двойной цели: проверить боевые инстинкты молодого воина и собрать сведения о надвигающейся экологической угрозе."}},faq={{q="Почему на сбор усиков дается ограниченное время?",a="Руга Тотем Гнева требует, чтобы усики еще подергивались, когда их принесут в Лагерь Таурахо, поэтому у воинов есть всего тридцать минут на охоту и дорогу назад. Свежесть доказывает, что стремящийся быстро одолел силитида в прямом бою, а не собирал панцири с мертвых.",al={"why timed","twitching antennae timer","how much time","почему на время","таймер подергивающихся усиков","сколько времени"}},{q="Какие существа обитают на Полях Великанов?",a="Поля Великанов наводнены силитидами — странной и агрессивной расой насекомоподобных землекопов. Они вырыли огромные холмы и ульи под древними окаменелостями, нарушив местную экологию и встревожив Орду.",al={"what are the bugs","field of giants mobs","what are silithid","что за жуки","монстры полей великанов","кто такие силитиды"}},{q="Кто такая Руга Тотем Гнева?",a="Руга Тотем Гнева — таурен, наставник воинов в Лагере Таурахо на юге Степей. Он руководит испытаниями, проверяющими умение, стойкость и скорость воинов Орды, стремящихся повысить свое положение.",al={"ruga","who gives quest","ruga ragetotem lore","руга","кто выдает задание","руга тотем гнева предыстория"}},{q="Где находятся Поля Великанов?",a="Поля Великанов лежат прямо к югу от Лагеря Таурахо, по обе стороны дороги перед южным перевалом, ведущим в Тысячу Игл. Их можно узнать по огромным скелетным ребрам и холмам силитидов.",al={"where is field of giants","field of giants location","where do i find the bugs","где поля великанов","расположение полей великанов","где найти жуков"}},{q="Куда ведет эта цепочка обучения дальше?",a="Когда воин вовремя вернет подергивающиеся усики, Руга направит его к Тун'гриму Огневзору, старому оркскому кузнецу, живущему на холме к востоку от Перекрестка, который выкует доспехи для проверенных воинов.",al={"next quest","what comes after","warrior chain continuation","следующее задание","что дальше","продолжение цепочки воина"}},{q="Почему тауренов беспокоят насекомые?",a="Силитиды — неестественные пришельцы в Степях. Руга говорит, что их появление не сулит земле добра: он подозревает, что их агрессивное рытье и расширение предвещают куда более страшную опасность, пробуждающуюся под песками.",al={"why do tauren care","insect herald","silithid threat","почему тауренам важно","предвестник насекомых","угроза силитидов"}}},fp="28,361,25.458.0,19.485.0,42.297.0,43.221.0,22.208.0,37.205.0,41.226.0,47.220.0"}
P.entries["quest:1825"] = {n="Разговор с Тун'гримом",s="Это поручение направляет растущих воинов Орды к Тун'гриму Огневзору, прославленному оркскому кузнецу, разбившему лагерь в Степях. Доказав себя в тяжелых физических испытаниях, воины получают приглашение заказать особые доспехи в признание их доблести. Задание служит важным звеном между общим испытанием воинов и изготовлением Доспехов Жестокости.",h="Это поручение направляет растущих воинов Орды к Тун'гриму Огневзору, прославленному оркскому кузнецу...",kw={"barrens","brutal armor","crossroads","firegaze","ragetotem","ruga","thun'grim","warrior","степи","доспехи жестокости","перекресток","огневзор","тотем гнева","руга","тун'грим","воин"},ang={["class:Warrior"]="Это задание — важный обряд посвящения, возводящий вас из новичка в признанного чемпиона, достойного доспехов, выкованных на заказ.",["faction:Horde"]="Оружейники Орды гордятся тем, что вооружают своих самых свирепых защитников, следя за тем, чтобы воины на передовой носили снаряжение, достойное их боевых подвигов.",["profession:Blacksmithing"]="Тун'грим Огневзор воплощает традиционную оркскую кузнечную философию, по которой доспехи мастера нужно заслужить боевыми испытаниями, а не просто деньгами."},sec={{t="Зов кузнеца",b="Проявив себя против ульев силитидов в «Испытании на Полях Великанов», воины Орды получают от Руги Тотема Гнева не только похвалу. Весть об их выносливости и боевом мастерстве быстро доходит до Тун'грима Огневзора, известного оркского кузнеца, чей лагерь стоит на гряде к востоку от Перекрестка. Признав воина, достойного его искусства, Тун'грим дает знать, что хочет выковать ему исключительные латные боевые доспехи."},{t="Мерило мастера",b="Тун'грим Огневзор кует не для простых солдат. Для оружейника с такой репутацией сталь должна соответствовать духу того, кто понесет ее в бой. Дойти до его лагеря значит, что воин вышел за рамки простой ополченской муштры и готов взяться за изнурительные особые задачи по добыче редких материалов для ремесла по всему Калимдору."}},faq={{q="Кто такой Тун'грим Огневзор?",a="Thun'grim Firegaze is an esteemed orc blacksmith camped atop a rocky ridge just east of the Crossroads in the Barrens. He crafts custom, formidable armor for Horde warriors who have proven their valor through dangerous trials.",al={"who is thungrim","thungrim lore","thungrim firegaze","кто такой тун'грим","предыстория тун'грима","тун'грим огневзор"}},{q="Почему Руга Тотем Гнева посылает меня к нему?",a="Руга Тотем Гнева видит, что вы переросли простые испытания, выжив среди силитидов на юге Степей. Он направляет вас к Тун'гриму, чтобы мастер-кузнец мог наградить вас за службу Орде, выковав особый комплект доспехов.",al={"why speak with thungrim","ruga sending me","зачем говорить с тун'гримом","руга посылает меня"}},{q="Где найти лагерь Тун'грима?",a="Тун'грим разбил лагерь на высоких утесах к востоку от Перекрестка в Степях, откуда открывается вид на сухую саванну.",al={"where is thungrim","thungrim location","find thungrim firegaze","где тун'грим","расположение тун'грима","найти тун'грима огневзора"}},{q="Что происходит после разговора с Тун'гримом?",a="Встреча с Тун'гримом начинает цепочку заданий «Доспехи Жестокости»: воины отправляются в дальние земли за прочными материалами, такими как дымчатые железные слитки и железные бруски, чтобы изготовить доспехи из кольчуги на заказ.",al={"next quest after thungrim","what does thungrim want","следующее задание после тун'грима","что хочет тун'грим"}},{q="Доступно ли это задание всем классам?",a="Нет. Это задание и связанная с ним цепочка доспехов входят исключительно в программу боевой подготовки, предназначенную для воинов Орды.",al={"can non warriors do this","is this warrior only","могут ли не воины","только для воинов"}},{q="Какое испытание требовалось до этой встречи?",a="До этого поручения воины должны были отправиться на юг Степей и пройти «Испытание на Полях Великанов», собрав подергивающиеся усики силитидов, чтобы показать свою боевую выносливость.",al={"prerequisite quest","what did i do before this","предыдущее задание","что я делал раньше"}}},fp="20,365,21.456.0,19.360.0,26.226.0,39.239.0,34.116.0,43.192.0,39.124.0,44.189.0"}
P.entries["quest:183"] = {n="Охотник на вепрей",s="Охотник на вепрей — одно из первых поручений, которое дает охотник-дворф Талин Остроглаз в Холодной долине. Из-за резкого роста числа скальных вепрей леса стали слишком опасными, и молодым новобранцам поручено проредить агрессивных зверей, чтобы опытные охотники могли спокойно выслеживать добычу.",h="Охотник на вепрей — одно из первых поручений, которое дает охотник-дворф Талин Остроглаз в Холодной долине.",kw={"anvilmar","boar hunter","coldridge valley","crag boar","dun morogh","hunting","talin keeneye","старая наковальня","охотник на вепрей","холодная долина","скальный вепрь","дун морог","охота","талин остроглаз"},ang={["class:Hunter"]="Талин Остроглаз воплощает прямой подход дворфов к выслеживанию: цельтесь точно, уважайте зверей и расчищайте заросли, когда дичь становится слишком враждебной.",["race:Dwarf"]="Жизнь в горах означает соседство со свирепыми зверями. Истребление задиристых скальных вепрей вокруг Старой Наковальни — обряд посвящения для каждого юного дворфа, делающего первые шаги за пределами кузни.",["race:Gnome"]="Для беженцев-гномов, недавно прибывших из Гномрегана, встреча со свирепыми кабанами Дун Морога — суровое практическое знакомство с жизнью в диких землях дворфов."},sec={{t="Тесная долина",b="Холодная долина обычно — тихое защищенное место, где обучаются молодые горцы и ученые Стальгорна. Однако в суровом зимнем климате дикие звери часто становятся беспокойными и слишком многочисленными. Талин Остроглаз, опытный охотник, стоящий у Старой Наковальни, замечает, что агрессивные мелкие скальные вепри размножились так быстро, что представляют настоящую угрозу для любого, кто бродит по заснеженным тропам."},{t="Забота о снегах",b="Охота — основа жизни дворфов: она дает мясо, шкуры и необходимую практику в обращении с дикой природой. Но когда дичь становится помехой и нападает при виде человека, необходимо сократить ее численность, чтобы восстановить равновесие. Сокращая число скальных вепрей на склонах долины, молодые авантюристы доказывают свою боевую готовность, а местные охотники получают возможность заниматься своим ремеслом, не опасаясь быть подавленными числом."}},faq={{q="Кто такой Талин Остроглаз?",a="Талин Остроглаз — охотник-дворф, живущий в Холодной долине неподалеку от Старой Наковальни. Он проводит дни, выслеживая дичь в снегу, и помогает обучать начинающих авантюристов практическим основам борьбы с враждебными зверями.",al={"talin keeneye","who gives the boar hunter quest","boar hunter npc","талин остроглаз","кто дает задание охотник на вепрей","охотник на вепрей нпс"}},{q="Почему скальные вепри — такая проблема?",a="Мелкие скальные вепри в Холодной долине расплодились необычайно сильно и нападают на любого, кого увидят, без всякого повода. Из-за их многочисленности обычные путешествия и охота становятся опасными для местных жителей.",al={"why kill boars","boar problem coldridge","why are boars dangerous","зачем убивать вепрей","проблема вепрей холодная долина","чем опасны вепри"}},{q="Где можно найти скальных вепрей?",a="Мелкие скальные вепри бродят по открытым заснеженным равнинам и редким лесам вокруг Старой Наковальни по всей Холодной долине.",al={"where are the boars","crag boar location","small crag boar map","где вепри","где найти скальных вепрей","мелкий скальный вепрь карта"}},{q="Связано ли это задание с более крупной угрозой в долине?",a="Нет. В отличие от нашествий троггов, тревожащих форпосты дворфов, это задание — просто борьба с местной живностью, чтобы тропы оставались безопасными, а Талин мог спокойно охотиться.",al={"is there a follow up quest","boar hunter chain","story behind boars","есть ли продолжение задания","цепочка охотник на вепрей","история вепрей"}},{q="Чем скальные вепри приспособлены к Дун Морогу?",a="Скальные вепри — выносливые свиньи с толстой шкурой, приспособленные к лютым морозам Дун Морога. Их агрессивный нрав и острые клыки позволяют им добывать пищу в мерзлой земле и отбиваться от горных хищников.",al={"crag boar lore","dwarf boars","dun morogh wildlife","предания о скальных вепрях","вепри дворфов","дикая природа дун мороге"}},{q="Почему Талин Остроглаз не убьет вепрей сам?",a="Талин говорит, что агрессивных вепрей так много, что его неспешная охота стала неприятно опасной. Он привлекает рвущихся в бой новых авантюристов, проходящих через Старую Наковальню, чтобы проредить стаю и вернуться к обычному выслеживанию.",al={"why does talin need help","talin lazy","why can't talin hunt them","почему талину нужна помощь","талин ленивый","почему талин не может охотиться сам"}}},fp="15,279,16.412.0,17.384.0,21.214.0,38.203.0,34.120.0,57.168.0,43.215.0,49.224.0"}
P.entries["quest:1838"] = {n="Доспехи Жестокости",s="Доспехи Жестокости — обряд посвящения воинов Орды, который проводит почти слепой кузнец Тун'грим Огневзор на севере Степей. Желая выковать доспехи, достойные восходящего чемпиона, Тун'грим отправляет опытных воинов в дальние земли за редкими реагентами и необычными плавильными средствами. Выполнение его свитка начинает ковку полного комплекта жестоких боевых доспехов.",h="Доспехи Жестокости — обряд посвящения воинов Орды, который проводит почти слепой кузнец Тун'грим Огневзор на...",kw={"barrens","brutal armor","brutal hauberk","phlogiston","powdered azurite","smoky iron ingot","thun'grim firegaze","warrior quest","степи","доспехи жестокости","хауберк жестокости","флогистон","порошок азурита","слиток дымчатого железа","тун'грим огневзор","задание воина"},ang={["class:Warrior"]="Это задание — важная веха для воинов Орды: оно доказывает их доблесть и выносливость на разных континентах и позволяет получить боевые доспехи, выкованные на заказ.",["faction:Horde"]="Комплекты Доспехов Жестокости — свидетельство единства Орды: в одном боевом наборе сочетаются разные кузнечные традиции кузнецов-орков, тауренов, троллей и Отрекшихся.",["profession:Blacksmithing"]="Свиток Тун'грима демонстрирует передовую металлургическую алхимию: дымчатое железо, порошок азурита и флогистон сочетаются, чтобы улучшить обычную плавку железа."},sec={{t="Призвание мастера",b="Опытный кузнец-орк Тун'грим Огневзор, живущий на скалистых холмах севера Степей, чутко прислушивается к ветрам войны. Хотя его зрение слабеет и затуманено, его слава у горна остается непревзойденной. Услышав о воине, чья сила и доблесть превосходят силы обычных солдат, Тун'грим решает выковать прочный кольчужный комплект, способный выдержать самые жестокие схватки Калимдора и Восточных королевств."},{t="Поиски на разных континентах",b="Для ковки доспехов такого уровня нужно куда больше, чем обычная руда. С трудом работая при свете огня слабыми глазами, Тун'грим пишет точный свиток с перечнем компонентов для основной нагрудной части. Требуется обычное очищенное железо, редкие слитки дымчатого железа, которые носят с собой роющие кобольды, порошок азурита, обработанный шахтерами за морем, и нестабильный флакон флогистона. Лишь воин, готовый вынести дальние испытания, может надеяться увидеть, как доспех оживет."},{t="Первый удар молота",b="Доставка этих редких припасов — лишь начало замысла Тун'грима. Приняв материалы и разжегши горн, чтобы выковать хауберк жестокости, старый кузнец понимает, что один мастер не в силах завершить столь амбициозный комплект. Для создания полного набора нужно обратиться к искусным мастерам других рас Орды — тауренскому мастеру шлемов, тролльскому мастеру рукавиц и отрекшемуся мастеру наголенников на разных континентах."}},faq={{q="Кто такой Тун'грим Огневзор?",a="Тун'грим Огневзор — уважаемый опытный кузнец-орк, живущий на холме с видом на север Степей. Несмотря на слабеющее зрение, у наковальни его чутье остается острым, и он создает мощные боевые латы на заказ для воинов Орды, заслуживших славу доблестью.",al={"who is thungrim","thun'grim firegaze lore","thungrim backstory","кто такой тун'грим","тун'грим огневзор предания","тун'грим история"}},{q="Что такое Доспехи Жестокости?",a="Доспехи Жестокости — знаменитый комплект закаленной в боях кольчуги, созданный специально для опытных воинов Орды. Он выкован общими усилиями кузнецов Орды, и для каждой части необходимы опасные путешествия за редкими алхимическими реагентами, очищенной рудой и древними приемами.",al={"what is brutal armor","brutal armor set lore","warrior armor chain","что такое доспехи жестокости","комплект доспехов жестокости предания","цепочка доспехов воина"}},{q="Зачем Тун'гриму такие необычные ингредиенты?",a="Обычное железо слишком хрупко, чтобы выдержать тяжелые удары, которые обрушиваются на чемпиона в первых рядах. Необычные реагенты, такие как порошок азурита, слитки дымчатого железа и нестабильный флогистон, служат флюсом и закаливающими средствами, позволяя Тун'гриму наделить металл огромной стойкостью и силой.",al={"why powdered azurite","why phlogiston","what are the reagents for","зачем порошок азурита","зачем флогистон","для чего нужны реагенты"}},{q="Выковывает ли Тун'грим весь комплект сам?",a="Нет. Центральный хауберк Тун'грим создает сам, но направляет воина к другим кузнецам Орды — среди них Орм Каменное Копыто, Ула'елек и Велора Нители — чтобы они изготовили шлем, рукавицы и поножи под стать хауберку.",al={"does thungrim make all of it","who makes the brutal armor pieces","тун'грим делает все сам","кто делает части доспехов жестокости"}},{q="Куда ведет эта цепочка заданий дальше?",a="Выполнение этого испытания напрямую ведет к ковке хауберка жестокости и открывает возможность обратиться к кузнецам в Громовом Утесе, Деревне Сен'джин и Подгороде, чтобы собрать остальные жестокие боевые латы.",al={"what comes after brutal armor","brutal armor follow up","что после доспехов жестокости","продолжение доспехов жестокости"}},{q="Почему воину приходится ехать так далеко за этими материалами?",a="Это испытание проверяет и воинскую стойкость, и находчивость. Чтобы доказать, что он достоин доспехов мастерской ковки, воин должен пройти по вражеской территории, спуститься в опасные шахты и собрать компоненты, которых нелегко достать.",al={"why travel to eastern kingdoms","why so many materials","зачем ехать в восточные королевства","зачем так много материалов"}}},fp="12,365,18.438.0,26.474.0,30.423.1,26.284.0,21.277.0,49.286.0,44.234.1,38.221.1,61.236.0"}
P.entries["quest:1839"] = {n="Ула'елек и рукавицы Жестокости",s="Это задание направляет восходящих воинов Орды с высот Степей обратно на побережье Дуротара. Посланные кузнецом Тун'гримом Огневзором, вы должны найти мастера из племени Черного Копья Ула'елека в Деревне Сен'джин, чтобы выковать свои Рукавицы Жестокости.",h="Это задание направляет восходящих воинов Орды с высот Степей обратно на побережье Дуротара.",kw={"brutal gauntlets","darkspear","durotar","sen'jin village","the barrens","thun'grim firegaze","ula'elek","warrior","рукавицы жестокости","черное копье","дуротар","деревня сен'джин","степи","тун'грим огневзор","ула'елек","воин"},ang={["class:Warrior"]="Цепочка заданий Доспехов Жестокости — важный обряд посвящения для воинов Орды, знаменующий их превращение в закаленных в боях чемпионов первых рядов.",["faction:Horde"]="Совместная работа мастеров-орков в Степях и кузнецов-троллей в Дуротаре показывает сотрудничество, скрепляющее молодую коалицию Тралла.",["race:Troll"]="Визит к Ула'елеку подчеркивает вклад племени Черного Копья в военные усилия Орды благодаря искусной кузнечной работе и духовной связи."},sec={{t="Путь к побережью",b="Доказав свою доблесть в Степях и взявшись за сбор комплекта Доспехов Жестокости, воины получают от Тун'грима Огневзора направление на восток. Вместо того чтобы выковывать каждую часть на своей горной вершине, опытный кузнец-орк полагается на сеть искусных мастеров по землям Орды. Чтобы изготовить тяжелые латные рукавицы для наступающего чемпиона, он посылает бойцов к скалистому южному берегу Дуротара."},{t="Глаза лоа",b="В Деревне Сен'джин тролль-бронник Ула'елек трудится среди своих сородичей из племени Черного Копья. Он вовсе не застигнут врасплох: Ула'елек сообщает, что Тун'грим уже прислал весть о ваших деяниях, а главное — сами духи наблюдали за вашими победами в бою. Для воина, занявшего место среди элиты Орды, мастерство и признание духов идут рука об руку."}},faq={{q="Кто дает задание «Ула'елек и рукавицы Жестокости»?",a="Задание дает Тун'грим Огневзор, уважаемый оружейник-орк, живущий на вершине гор в Степях.",al={"quest giver","who starts ula'elek and the brutal gauntlets","thun'grim firegaze quest","персонаж, выдающий задание","кто начинает ула'елек и рукавицы жестокости","задание тун'грим огневзор"}},{q="Где найти Ула'елека?",a="Ула'елек находится в Деревне Сен'джин на южном побережье Дуротара.",al={"ula'elek location","where is ula'elek","ulaelek senjin","где ула'елек","ула'елек местонахождение","ула'елек сен'джин"}},{q="Что такое комплект Доспехов Жестокости?",a="Доспехи Жестокости — особый комплект кольчужной и латной брони, созданный специально для опытных воинов Орды примерно к тридцатому уровню и выкованный союзными кузнецами по всему Калимдору.",al={"brutal armor","what are brutal gauntlets","warrior class armor 30","доспехи жестокости","что такое рукавицы жестокости","доспехи воина 30 уровня"}},{q="Что происходит после встречи с Ула'елеком?",a="Поприветствовав вас и признав ваши деяния в бою, Ула'елек поручит вам собрать необычные материалы для изготовления Рукавиц Жестокости, начиная с Копыт сатиров.",al={"next quest","after speaking to ula'elek","satyr hooves quest","следующее задание","после разговора с ула'елеком","задание копыта сатиров"}},{q="Why does Thun'grim send you to a troll armorsmith?",a="Тун'грим распределяет ковку комплекта Доспехов Жестокости между лучшими специализированными кузнецами Орды, доверяя изготовление рукавиц мастерам племени Черного Копья, таким как Ула'елек.",al={"why ula'elek","why go to sen'jin village","troll smith brutal armor","почему ула'елек","почему идти в деревню сен'джин","тролль-кузнец доспехи жестокости"}},{q="Есть ли у игроков Альянса аналог этого задания?",a="Воины Альянса проходят похожее боевое испытание, чтобы изготовить собственные доспехи для своего класса, но цепочка Доспехов Жестокости и работа Ула'елека доступны только Орде.",al={"alliance brutal gauntlets","alliance equivalent","рукавицы жестокости альянс","аналог для альянса"}}},fp="33,247,22.423.0,19.383.0,54.108.0,26.87.0,29.179.0,37.185.0,50.160.0,53.176.0"}
P.entries["quest:184"] = {n="Документ Хмуроброва",s="Документ Хмуроброва — похищенный земельный акт, который носят с собой воры из Братства Справедливости в Элвиннском лесу. Если вернуть документ изгнанному Фермеру Хмуроброву у границы Западного Края, у бежавшей четы появится единственная надежда когда-нибудь вернуть отнятую усадьбу.",h="Документ Хмуроброва — похищенный земельный акт, который носят с собой воры из Братства Справедливости в...",kw={"defias","elwynn","furlbrow","theodore furlbrow","verna furlbrow","westfall","westfall deed","братство справедливости","элвинн","хмуробров","теодор хмуробров","верна хмуробров","западный край","документ западного края"},ang={["class:Paladin"]="Возвращая украденные документы обездоленным беженцам, паладин следует священному обету защищать беззащитных и нести справедливость в беззаконные пограничные земли.",["faction:Alliance"]="Беда Хмуробровых показывает неспособность штормградской короны защитить своих налогоплательщиков за укрепленными стенами столицы."},sec={{t="Улика на краденой бумаге",b="Сражаясь с разбойниками из Братства Справедливости в Элвиннском лесу, путники нередко находят помятый земельный акт, подписанный Теодором и Верной Хмуробров. На обороте пергамента неровным почерком записан замысел бандитов: выгнав пожилого фермера с его земли, они тайком переправили документ через реку в Элвинн, чтобы использовать его как образец для подделки актов на другие захваченные земли. В записке также сказано, что Хмуробровов видели на дороге сразу за границей: их задержала сломанная повозка."},{t="Беды фермеров Западного Края",b="Потеря Хмуробровых — символ трагедии, охватившей Западный Край. Пока армия Штормграда далеко, а ресурсы королевства истощены, Братство Справедливости изгнало десятки семей с родовой земли, применяя силу и юридические уловки, чтобы укрепить власть над житницей королевства. Хотя Теодор и Верна покидают ферму ради собственной безопасности, законный акт остается их единственным доводом против мятежников, если в провинции когда-нибудь восстановят порядок."}},faq={{q="Где найти этот документ?",a="Документ выпадает из разных членов Братства Справедливости, что бродят по югу и западу Элвиннского леса, например возле Лагеря Джерода или в местных лагерях.",al={"deed drop","how to get furlbrows deed","where does the deed drop","выпадение документа","как получить документ хмуроброва","где выпадает документ"}},{q="Где находится Фермер Хмуробров?",a="Фермер Хмуробров с женой Верной застряли у сломанной повозки на главной дороге сразу за границей Западного Края, вскоре после моста к западу от Элвиннского леса.",al={"furlbrow location","where to turn in furlbrows deed","where is the farmer","местонахождение хмуроброва","куда сдать документ хмуроброва","где фермер"}},{q="Зачем Братству Справедливости вообще понадобился этот документ?",a="Записка на обороте показывает, что бандиты хотели использовать подлинный документ Хмуроброва как образец для подделки прав на другие владения в округе и закрепить власть над захваченными фермами с помощью фальшивых бумаг.",al={"why did bandits steal the deed","why do defias want deeds","зачем бандиты украли документ","зачем братству справедливости документы"}},{q="Вернутся ли Хмуробровы на свою ферму?",a="Вряд ли скоро. Супруги бегут из края из-за беззакония и нападений бандитов. Однако документ у них в руках, и если Западный Край когда-нибудь будет усмирен, они смогут законно вернуть землю.",al={"are furlbrows going home","what happens to the furlbrow farm","вернутся ли хмуробровы домой","что будет с фермой хмуробровых"}},{q="Почему Штормград не защищает эти фермы?",a="Штормград парализован внезапным исчезновением короля Вариана Ринна и внутренними политическими раздорами. Королевские силы сосредоточены в столице, и дальние земли вроде Западного Края предоставлены сами себе в борьбе с растущим Братством Справедливости.",al={"why no guards in westfall","why is stormwind ignoring westfall","почему нет стражи в западном крае","почему штормград игнорирует западный край"}},{q="Как в этом задании связаны Элвинн и Западный Край?",a="Задание ведет искателей приключений из Элвиннского леса через реку в Западный Край и показывает, как далеко в центральные земли королевства дотянулась сеть Братства Справедливости.",al={"why was deed in elwynn","connection between zones","почему документ в элвиннском лесу","связь между зонами"}}},fp="15,251,22.516.0,32.511.0,26.182.0,25.170.0,52.223.0,42.207.0,43.256.0,65.189.0"}
P.entries["quest:1840"] = {n="Орм Каменное Копыто и шлем Жестокости",s="Это поручение отправляет набирающих силу воинов Орды в Громовой Утес к Орму Каменному Копыту, мастеру-кузнецу. По рекомендации Тун'грима Огневзора, Орм обладает мастерством, нужным для ковки шлема Жестокости.",h="Это поручение отправляет набирающих силу воинов Орды в Громовой Утес к Орму Каменному Копыту, мастеру-кузнецу.",kw={"armor quest","brutal helm","orm stonehoof","thun'grim firegaze","thunder bluff","warrior","задание доспехи","шлем жестокости","орм каменное копыто","тун'грим огневзор","громовой утес","воин"},ang={["class:Warrior"]="Это задание знаменует переход к тяжелой защите головы: воинов отправляют к одному из лучших мастеров-кузнецов Орды.",["faction:Horde"]="Задание показывает сотрудничество орочьих мастеров оружия в Степях и таурен-ремесленников высоко на Громовом Утесе."},sec={{t="Рекомендация в железе",b="Проявив доблесть и собрав части Доспехов Жестокости в Степях, воины направляются выше, в город на плато — Громовой Утес. Тун'грим Огневзор, сам искусный оружейник, признает свои пределы и отправляет своих бойцов к Орму Каменному Копыту. Мастерство Орма известно по всему Калимдору, особенно его умение создавать прочные боевые шлемы из редких свирепых трофеев."},{t="Мастер у озерца",b="Орм живет и работает на высоких утесах Мулгора, у тихих вод под огромным центральным тотемом города. Когда воин приходит с вестью от Тун'грима, Орм отрывается от обычной работы, чтобы обсудить сложные составляющие, нужные для шлема, по-настоящему достойного передовой Орды."}},faq={{q="Кто такой Орм Каменное Копыто?",a="Орм Каменное Копыто — искусный таурен-оружейник, живущий в Громовом Утесе. Известный своим мастерством, он помогает воинам, которых присылает Тун'грим Огневзор, создавать особые боевые шлемы.",al={"orm stonehoof","who is orm","орм каменное копыто","кто такой орм"}},{q="Где найти Орма Каменное Копыто?",a="Он находится в сердце Громового Утеса, у водоема рядом с огромным центральным тотемом города.",al={"where is orm","orm stonehoof location","find orm","где орм","местонахождение орма каменное копыто","найти орма"}},{q="Почему Тун'грим Огневзор посылает вас в Громовой Утес?",a="Хотя Тун'грим может выковать нагрудник и другие части набора Жестокости, он признает, что Орм Каменное Копыто обладает точным мастерством, нужным для создания шлема Жестокости.",al={"why thunder bluff","why see orm","почему громовой утес","зачем идти к орму"}},{q="Что такое шлем Жестокости?",a="Шлем Жестокости — знаменитый шлем, который куют для воинов Орды, достигших ранга ветерана. Для него нужны опасные материалы от зверей со всего Калимдора.",al={"brutal helm quest","what is brutal helm","задание шлем жестокости","что такое шлем жестокости"}},{q="Что Орм попросит дальше?",a="После разговора с Ормом он велит вам собрать нужные звериные трофеи для шлема, начиная с охоты на химер в глуши ради Рога химеры.",al={"next quest","after orm stonehoof","chimaeric horn quest","следующее задание","после орма каменное копыто","задание рог химеры"}},{q="Может ли любой класс взять это задание?",a="Нет. Эта цепочка заданий доступна только воинам, достаточно продвинувшимся в боевой подготовке и выполнившим первые задания Тун'грима по доспехам.",al={"is this warrior only","who can do this quest","только для воинов","кто может выполнить это задание"}}},fp="33,213,24.405.0,23.328.0,21.185.0,33.119.0,54.180.0,24.168.0,27.164.1,30.146.0"}
P.entries["quest:1842"] = {n="Копыта сатиров",s="Копыта сатиров — задание, которое выдает тролль-ремесленник Ула'елек в Деревне Сен'джин. Чтобы выковать пару усиленных рукавиц Жестокости, воинам предстоит отправиться на север, в Ясеневый лес, охотиться на сатиров и добывать их магически раздутые нерасщепленные копыта.",h="Копыта сатиров — задание, которое выдает тролль-ремесленник Ула'елек в Деревне Сен'джин.",kw={"ashenvale","brutal gauntlets","durotar","hooves","satyr","sen'jin village","ula'elek","uncloven","ясеневый лес","рукавицы жестокости","дуротар","копыта","сатир","деревня сен'джин","ула'елек","нерасщепленные"},ang={["class:Warrior"]="Это задание — часть обряда продвижения воина: оно проверяет боевую стойкость в схватках с коварными демонами-засадниками ради личных доспехов.",["faction:Horde"]="Эта охота уводит воинов Орды из засушливых равнин Дуротара вглубь спорных земель ночных эльфов в Ясеневом лесу.",["race:Troll"]="Методы Ула'елека показывают практичность ремесла Черного Копья: он вытягивает чистую сущность из павших магических врагов, а не полагается лишь на обычную ковку."},sec={{t="Использование оскверненной сущности",b="Чтобы выковать доспехи, способные соперничать с самыми жестокими силами Калимдора, ремесленник из Черного Копья Ула'елек ищет нечто большее, чем обычные железо и кожа. Он посылает будущих воинов на север, в древние чащи Ясеневого леса, где в местных кругах сатиров гноится остаточная демоническая порча."},{t="Раздутая магия Ясеневого леса",b="По словам Ула'елека, сатиры на северо-востоке Ясеневого леса живут за счет скрытой чистоты леса, обращая ее в мерзкую силу. Те демоны, что глубже всего упились этой чужой жизнью, обретают неестественные раздутые копыта, утратившие природное раздвоение. Ула'елек намерен вытянуть эту сосредоточенную магическую энергию и вплести ее прямо в создаваемые им рукавицы."}},faq={{q="Зачем Ула'елеку копыта сатиров?",a="Ула'елеку нужны копыта, чтобы усилить создаваемые им рукавицы Жестокости. Он намерен выкачать сосредоточенную магию леса, которую сатиры высосали и извратили в своих раздутых ногах.",al={"why satyr hooves","hoof purpose","what are the hooves for","зачем копыта сатиров","назначение копыт","для чего нужны копыта"}},{q="Где обитают сатиры?",a="Они живут на северо-востоке Ясеневого леса, среди оскверненных древних руин, и питаются остаточной магической энергией глубокого леса.",al={"where are satyrs","satyr location","where to find satyr hooves","где сатиры","местонахождение сатиров","где найти копыта сатиров"}},{q="Чем особенно нерасщепленное копыто?",a="Отсутствие раздвоения означает, что сатир объелся чрезмерным количеством чистой магии Ясеневого леса, и его конечности распухли от украденной силы.",al={"uncloven hoof lore","why uncloven","swollen hooves","нерасщепленное копыто","почему нерасщепленное","раздутые копыта"}},{q="Кто такой Ула'елек?",a="Ула'елек — искусный тролль из племени Черного Копья, мастер по доспехам, живущий в Деревне Сен'джин на юге Дуротара и известный помощью воинам в создании доспехов для испытаний.",al={"who is ulaelek","quest giver","troll in senjin","кто такой ула'елек","персонаж, выдающий задания","тролль в сен'джин"}},{q="Какие доспехи кует Ула'елек?",a="Он готовится выковать пару Рукавиц Жестокости — тяжелой защиты для рук, наделенной украденной магической силой, для растущих воинов Орды.",al={"what are brutal gauntlets","gauntlet quest","reward armor","что такое рукавицы жестокости","задание рукавицы","награда доспехи"}},{q="Служат ли здешние сатиры Пылающему Легиону?",a="Да. Сатиры — древние ночные эльфы, преображенные демоническими договорами, а уцелевшие круги в лесах Калимдора продолжают практиковать скверну в услужении демонам.",al={"satyr allegiance","are satyrs legion","верность сатиров","служат ли сатиры легиону"}}},fp="12,253,28.286.0,30.413.0,36.195.0,27.145.0,36.161.0,16.157.0,31.140.0,44.180.0"}
P.entries["quest:1843"] = {n="Рукавицы Жестокости",s="Рукавицы Жестокости — вершина мастерства ремесленника для закаленных воинов Орды. Собрав редкие компоненты в дальних землях, мастер Ула'елек изготавливает внушительную пару рукавиц, призванных принести честь и создателю, и владельцу.",h="Рукавицы Жестокости — вершина мастерства ремесленника для закаленных воинов Орды.",kw={"armor forging","brutal gauntlets","durotar","horde","satyr hooves","ula'elek","warrior armor","ковка доспехов","рукавицы жестокости","дуротар","орда","копыта сатиров","ула'елек","доспехи воина"},ang={["class:Warrior"]="Эти рукавицы знаменуют переход воина к дисциплинированному боевому лидерству: это надежная защитная часть снаряжения, выкованная для тяжелых ближних схваток.",["faction:Horde"]="Мастерство Орды опирается на непрерывную традицию и воинскую гордость, и герои несут в бой духовный вес и честь своих мастеров."},sec={{t="Шедевр мастера",b="Ковка доспехов для закаленного воина первой линии — это не просто работа с металлом, а духовное дело для ремесленников Орды. Ула'елек, мастер из Дуротара, вкладывает в эти рукавицы Жестокости свой род и умение. Используя прочные трофеи, добытые у опасных противников, он создает доспехи, способные выдержать яростные удары и усилить натиск владельца."},{t="Честь предков",b="В традициях орков и троллей прекрасное оружие и доспехи несут в бой славу кузни и дух мастера. Вручая готовые рукавицы воину, Ула'елек доверяет ему наследие своих предков. От героя, надевшего их в бой, ждут храбрости, воинской дисциплины и силы, достойной мастерства создателя."}},faq={{q="Кто такой Ула'елек?",a="Ула'елек — мастер из Дуротара, который помогает воинам Орды получить прочные доспехи высокого качества, сделанные по мерке. Он требует редкие материалы, чтобы его кузнечное дело воздавало честь и ремеслу, и традициям предков.",al={"ulaelek","who gives brutal gauntlets","quest giver","ула'елек","кто дает рукавицы жестокости","персонаж, выдающий задания"}},{q="Зачем для этих рукавиц нужны копыта сатиров?",a="В распухших нерасщепленных копытах сатиров хранится сила, которую они вытянули из магии Ясеневого леса. Ула'елек извлекает эту силу из копыт и вкладывает в свою работу, поэтому рукавицы обладают мощной магией.",al={"why satyr hooves","satyr parts","materials used","зачем копыта сатиров","части сатиров","материалы"}},{q="Что значит для Ула'елека то, что воин носит эти рукавицы?",a="Для Ула'елека эти рукавицы — вершина мастерства. Вручить их достойному воину — большая честь для его ремесла и предков, ведь его труд напрямую связан с боевыми победами Орды.",al={"honor ancestors","ula'elek honor","честь предков","честь ула'елека"}},{q="Где происходит это задание?",a="Ковка завершается в Дуротаре, засушливом сердце земель орков и троллей Черного Копья, где Ула'елек осматривает добытые материалы и вручает готовые доспехи.",al={"location","where is brutal gauntlets turned in","местоположение","где сдать рукавицы жестокости"}},{q="Это испытание предназначено для всех искателей приключений?",a="Этот путь создан для воинов первой линии, доказавших выносливость и преданность боевому делу; он отмечает их переход к более зрелым боевым ролям в Орде.",al={"is this warrior only","class requirement","только для воинов","требования к классу"}},{q="Что будет после получения рукавиц?",a="Вручение рукавиц завершает это ремесленное испытание, и воин полностью готов к встрече с более серьезными угрозами на истерзанных войной полях сражений Азерота.",al={"next quest","brutal gauntlets follow up","следующее задание","продолжение рукавиц жестокости"}}},fp="16,262,25.416.0,15.367.0,16.212.0,49.203.0,52.214.0,32.168.0,43.180.0,41.182.0"}
P.entries["quest:1845"] = {n="Шлем Жестокости",s="Шлем Жестокости — завершение трудного воинского испытания, которым руководит Орм Каменное Копыто на вершине Громового Утеса. Собрав редкие трофеи зверей по всему Калимдору, начинающий воин получает внушительный рогатый шлем в знак своей силы.",h="Шлем Жестокости — завершение трудного воинского испытания, которым руководит Орм Каменное Копыто на вершине...",kw={"brutal helm","chimaeric horn","earthmother","hunter rise","orm stonehoof","thunder bluff","warrior","шлем жестокости","рог химеры","мать-земля","громовой утес","орм каменное копыто","воин"},ang={["class:Warrior"]="Этот обряд — важная веха для воинов Орды: они переходят к тяжелым доспехам, выкованным из свирепых зверей и благословленным опытными наставниками.",["faction:Horde"]="Испытание доспехами Жестокости гарантирует, что герои под знаменем Орды обладают физической выносливостью и охотничьим мастерством, которых требуют от них вожди.",["race:Tauren"]="Шлем, вручаемый в Громовом Утесе, отражает традицию таурен превращать охотничьи трофеи в защитное боевое снаряжение по милости Матери-Земли."},sec={{t="Обряд воина",b="Орм Каменное Копыто — суровый кузнец в Громовом Утесе, который ведет воинов Орды через тяжелые обряды посвящения. Эти испытания требуют доказать боевые способности: новички отправляются на опасные земли, охотятся на свирепых существ и добывают редкие трофеи. Лишь те, кто отвечает строгим требованиям Орма, удостаиваются встречи для завершения своих доспехов."},{t="Дар Матери-Земли",b="Принеся редкий рог химеры Орму Каменному Копыту, воин доказывает свою решимость перед лицом дикой природы. В знак признания Орм вручает Шлем Жестокости — тяжелый грозный латный шлем, созданный в честь зверя и для усиления владельца в бою на передовой. Вручая его, Орм призывает благословение Матери-Земли, предвидя великие дела, которые предстоит совершить воину по всему Азероту."}},faq={{q="Кто выдает Шлем Жестокости?",a="Орм Каменное Копыто, почтенный кузнец-таурен из Громового Утеса, вручает Шлем Жестокости воинам Орды, прошедшим его испытания.",al={"who gives brutal helm","brutal helm npc","orm stonehoof quest","кто дает шлем жестокости","персонаж шлема жестокости","задание орма каменное копыто"}},{q="Какое задание нужно выполнить перед получением шлема?",a="Вы должны пройти испытание «Рог химеры»: нужно охотиться на свирепых зверей в дикой местности и доставить их рог Орму Каменному Копыту в Громовой Утес.",al={"prereq for brutal helm","chimaeric horn quest","предыдущее задание шлема жестокости","задание рог химеры"}},{q="Где находится Орм Каменное Копыто?",a="Орм Каменное Копыто находится возле водоема у великого центрального тотема в городе на высокой плоскогорной скале — Громовом Утесе.",al={"orm stonehoof location","where is orm stonehoof","местоположение орма каменное копыто","где орм каменное копыто"}},{q="Почему Орм Каменное Копыто призывает Мать-Землю?",a="Как таурен, Орм почитает Мать-Землю как создательницу и духовную хранительницу мира. Благословение над готовым шлемом воина отражает традиционное убеждение таурен: сила в бою должна быть уравновешена духовным почтением.",al={"why mention earthmother","earthmother lore","почему упоминается мать-земля","предания о матери-земле"}},{q="Открыто ли это испытание для любого искателя приключений?",a="Нет. Это испытание и награды в виде доспехов Жестокости предназначены только воинам Орды, доказывающим свою доблесть в классовых заданиях.",al={"can anyone get brutal helm","brutal helm class","может ли любой получить шлем жестокости","класс шлема жестокости"}},{q="В чем значение комплекта доспехов Жестокости?",a="Части доспехов Жестокости олицетворяют путь воина от новичка до элитного героя Орды; они созданы из материалов, добытых у самых свирепых хищников Калимдора.",al={"brutal armor lore","why is it called brutal helm","предания о доспехах жестокости","почему шлем называется жестокости"}}},fp="11,259,16.365.0,27.412.0,27.130.0,53.168.0,31.105.0,46.254.0,37.127.0,49.188.0"}
P.entries["quest:1846"] = {n="Берцовые кости",s="Берцовые кости — задание воинов Орды, которое выдает оружейница Велора Нители в Подгороде. Чтобы создать прочные Набедренники Жестокости, воины отправляются на юг Болотины за исключительно толстыми берцовыми костями у враждебных орков клана Драконьей Пасти.",h="Берцовые кости — задание воинов Орды, которое выдает оружейница Велора Нители в Подгороде.",kw={"angerfang encampment","brutal legguards","dragonmaw","shinbones","thandol span","undercity","velora nitely","wetlands","лагерь злого клыка","набедренники жестокости","драконья пасть","берцовые кости","мост тандола","подгород","велора нители","болотина"},ang={["class:Warrior"]="Это испытание проверяет и физическую стойкость воина в поле, и его готовность добывать мрачные материалы ради превосходных доспехов.",["faction:Horde"]="Уничтожение мятежного клана Драконьей Пасти в Каз Модане ослабляет опасный остаток Старой Орды и усиливает героев новой коалиции Тралла.",["race:Orc"]="Для орков, верных Оргриммару, истребление нераскаявшихся Драконьей Пасти — суровое напоминание о скверном прошлом их народа и о жестокой цене искупления.",["race:Undead"]="Прагматичное использование Велорой Нители останков гуманоидов отражает образ мыслей Отрекшихся: обращать в оружие любой доступный ресурс, каким бы жутким он ни был."},sec={{t="Жуткий каркас",b="Ковка доспехов для закаленного воина первой линии требует необычных материалов. Для изготовления Набедренников Жестокости оружейница из Отрекшихся Велора Нители требует каркас из толстой прочной кости. Вместо обычных зверей она направляет начинающих воинов к оркам Драконьей Пасти в Болотине, чья плотная костная структура дает необходимую стойкость против тяжелых ударов в бою."},{t="Проверка костного мозга",b="Добыть кости у Драконьей Пасти — лишь половина испытания. Велора велит воинам вручную проверять каждую кость, взятую в поле: любой образец, ломающийся в голых руках, для кузни совершенно бесполезен. Воинам придется прочесать лагеря изгнанников среди скал Болотины, ломая слабые кости, пока не уцелеют восемь по-настоящему прочных."}},faq={{q="Почему Велоре Нители нужны именно берцовые кости орков?",a="Велоре нужен плотный толстый материал в качестве опорного каркаса для Набедренников Жестокости. Она считает орков Драконьей Пасти из Болотины особенно подходящими: их тяжелый мощный скелет дает куда больше жесткости, чем обычная дичь или найденные останки.",al={"why orc shinbones","why dragonmaw bones","velora bone armor","почему кости орков","почему кости драконьей пасти","доспехи из костей велоры"}},{q="Почему орки Драконьей Пасти — законная добыча для воинов Орды?",a="Остатки клана Драконьей Пасти, засевшие в Болотине, — враждебные изгнанники, цепляющиеся за темное наследие Второй войны. Они не подчиняются современной Орде Тралла, а потому считаются врагами государства и законной добычей искателей приключений Орды.",al={"are dragonmaw in the horde","why fight dragonmaw","dragonmaw horde standing","драконья пасть в орде","почему сражаться с драконьей пастью","драконья пасть и орда"}},{q="Где искать орков Драконьей Пасти для этого задания?",a="Они обитают в Болотине, к югу через Мост Тандола от Нагорья Арати. Воины обычно охотятся на них у горных утесов Лагеря Злого Клыка, к юго-западу от главной северной дороги.",al={"dragonmaw location","where to find dragonmaw shinbones","angerfang encampment location","местоположение драконьей пасти","где найти берцовые кости","лагерь злого клыка"}},{q="Почему в ходе задания ломается так много костей?",a="Велоре подходят только самые плотные костные каркасы для ковки доспехов. По ее указаниям воины проверяют каждую кость руками; любая кость, сломавшаяся под грубой силой, отбрасывается как слишком хрупкая, чтобы защитить ноги воина в бою.",al={"broken shinbones","why do shinbones snap","sturdy bone test","сломанные берцовые кости","почему ломаются кости","проверка прочной кости"}},{q="Кто такая Велора Нители?",a="Велора Нители — оружейница из Отрекшихся, работающая в Подгороде. Грубая, мрачно-сухая и склонная к жутковатым шуткам, она помогает воинам Орды изготавливать особое боевое снаряжение для закаленных ветеранов.",al={"velora nitely lore","who is velora","undercity armorer","велора нители","кто такая велора","оружейница подгорода"}},{q="Какая часть доспехов выковывается из этих костей?",a="The collected bones form the internal framing for the Brutal Legguards, a durable set of mail legguards created for mid-level Horde warriors.",al={"shinbones reward","what are the shinbones for","brutal legguards craft","награда за берцовые кости","для чего берцовые кости","создание набедренников жестокости"}}},fp="19,266,19.437.0,18.377.0,55.285.0,56.245.0,44.222.0,51.239.0,21.229.0,44.141.0"}
P.entries["quest:1848"] = {n="Хауберк жестокости",s="Хауберк жестокости — завершение трудного обряда посвящения для воинов Орды в Степях. Собрав редкие материалы и проявив себя в схватках с опасными врагами по всему миру, воины приносят добычу нелюдимому кузнецу Тун'гриму Огневзору. В награду он выковывает прочную кольчугу, способную выдержать самые жестокие сражения.",h="Хауберк жестокости — завершение трудного обряда посвящения для воинов Орды в Степях.",kw={"brutal armor","brutal hauberk","crossroads","orcish smithing","the barrens","thun'grim firegaze","warrior mail","доспехи жестокости","хауберк жестокости","перекресток","орочья кузнечность","степи","тун'грим огневзор","кольчуга воина"},ang={["class:Warrior"]="Хауберк жестокости — важная веха для молодых воинов Орды: он знаменует переход от неопытного новобранца к закаленному бойцу в кольчуге, сделанной на заказ.",["faction:Horde"]="Изготовленный из добытых в бою трофеев, собранных в глуши Калимдора, хауберк отражает основные добродетели Орды — воинскую самостоятельность и силу.",["profession:Blacksmithing"]="Наблюдая за работой Тун'грима, можно изучить традиционное орочье кузнечное дело, где боевой дух и стойкость вкладываются прямо в сталь."},sec={{t="Шедевр кузнеца",b="Тун'грим Огневзор, живущий на скалистых холмах северных Степей, кует доспехи не для каждого. Нелюдимый орк требует, чтобы будущие воины обошли дальние земли и добыли прочные части зверей, редкий металл и алхимические реагенты, прежде чем он раздует меха. Готовый хауберк — не просто защитное снаряжение, а непреходящий знак выносливости и стойкости, который признают закаленные бойцы всей Орды."},{t="Выкован в трудностях",b="Задание Тун'грима намеренно сурово. Настоящие оружие и доспехи Орды должны с самого начала впитать пот и кровь владельца. Вручая готовый хауберк жестокости, кузнец не расточает пышных похвал — лишь ждет, что доспехи пройдут испытание в жестоком бою и вернутся с историями о крови и чести."}},faq={{q="Что такое хауберк жестокости?",a="Хауберк жестокости — прочный нагрудник, изготовленный на заказ орком-кузнецом Тун'гримом Огневзором. Это главная награда для воинов Орды, доказавших боевое мастерство добычей редких материалов в нескольких опасных землях.",al={"what is brutal hauberk","brutal hauberk quest","who makes brutal hauberk","что такое хауберк жестокости","задание хауберк жестокости","кто делает хауберк жестокости"}},{q="Кто такой Тун'грим Огневзор?",a="Тун'грим Огневзор — нелюдимый кузнец-ветеран, живущий на горном отроге в северных Степях, к востоку от дороги между Перекрестком и Оргриммаром. Он испытывает начинающих воинов и, когда они доказывают свою доблесть, выковывает им особые доспехи.",al={"who is thun grim","thungrim firegaze","where is thungrim","кто такой тун'грим","тун'грим огневзор","где тун'грим"}},{q="Почему Тун'грим требует столько усилий, прежде чем выковать доспехи?",a="Традиции воинов Орды ценят трудности не меньше боевого мастерства. Тун'грим считает, что кольчуга высокого качества пропадает зря, если ее получает тот, кто не пролил собственную кровь и не потрудился добыть редкие компоненты для ее ковки.",al={"why gather so many materials","brutal armor requirements","thungrim trials","зачем собирать столько материалов","требования доспехов жестокости","испытания тун'грима"}},{q="Куда ведет цепочка заданий дальше?",a="Это задание — последний шаг испытаний Доспехов Жестокости. Когда Тун'грим вручит вам готовый хауберк, его работа для вас закончена, и вы сможете носить доспехи в боях по всему Калимдору и Восточным королевствам.",al={"what comes after brutal hauberk","next quest after brutal hauberk","is there a follow up","что после хауберка жестокости","следующее задание после хауберка жестокости","есть ли продолжение"}},{q="Доступно ли задание о хауберке жестокости Альянсу?",a="Нет. Хауберк жестокости — испытание исключительно для Орды. Воины Альянса проходят иной воинский обряд, связанный с кузнецами Стальгорна и окрестных дворфийских земель, чтобы выковать собственные особые доспехи.",al={"can alliance get brutal hauberk","alliance equivalent","is this horde only","может ли альянс получить хауберк жестокости","аналог для альянса","только ли для орды"}},{q="Где в Степях можно найти Тун'грима?",a="Тун'грим живет на высоком хребте в северных Степях, к югу от Реки Строптивой и чуть восточнее главной горной дороги, ведущей на север к Дуротару.",al={"thungrim location","where is thungrim in barrens","how to find thun grim","местонахождение тун'грима","где тун'грим в степях","как найти тун'грима"}}},fp="14,363,21.433.0,18.356.0,27.241.0,26.255.0,68.223.0,38.233.0,54.212.0,44.169.0"}
P.entries["quest:1858"] = {n="Изувеченная Длань",s="Это испытание для разбойников — последнее посвящение в ряды Изувеченной Длани в Оргриммаре. Терзок поручает начинающим разбойникам открыть найденную сумку, выкрав ключ у ничего не подозревающего сообщника.",h="Это испытание для разбойников — последнее посвящение в ряды Изувеченной Длани в Оргриммаре.",kw={"cleft of shadow","gamon","orgrimmar","pickpocket","rogue","shattered hand","tazan","therzok","расселина теней","гамон","оргриммар","карманная кража","разбойник","изувеченная длань","тазан","терзок"},ang={["class:Rogue"]="Этот обряд обучает основам ремесла разбойника: выслеживать ничего не подозревающую цель в тесных помещениях, незаметно красть ключ и добывать важные сведения.",["faction:Horde"]="Под воинской честью новой Орды Тралла скрывается необходимость тайной разведки, которой тихо руководит Изувеченная Длань в глубинах Оргриммара."},sec={{t="Проверка скрытности",b="Добыв запертую сумку Тазана, начинающие разбойники обнаруживают, что без ключа она бесполезна. Вместо того чтобы взламывать сложный замок грубой силой, Изувеченная Длань требует подлинного мастерства. Терзок направляет посвящаемых к Гамону — рассеянному пьянице из тауренов, который бывает в оргриммарской таверне и ранее помогал Тазану, что делает его идеальной целью для тихой кражи."},{t="Добро пожаловать в тень",b="Если вытащить ключ у Гамона, не переполошив всю таверну, посвящаемый сможет открыть сумку и забрать дневник Тазана. Принеся украденное Терзоку в Расселину Теней, он соответствует строгим меркам гильдии. Когда дело сделано чисто, кандидата официально принимают в число признанных агентов Изувеченной Длани."}},faq={{q="Кто такой Гамон и почему у него ключ?",a="Гамон был помощником Тазана — агента, чью сумку изучает Терзок. Пока Тазан носил сумку, ключ он оставил у Гамона, ничего не подозревающего пьяницы, который целыми днями пьет в центральной таверне Оргриммара.",al={"why gamon","who has the key","gamon key","почему гамон","у кого ключ","ключ гамона"}},{q="Что внутри сумки Тазана?",a="В запертой сумке лежит дневник Тазана. В нем подробно изложены сведения, интересующие Терзока и Изувеченную Длань; их добыча доказывает умение посвящаемого добывать важную информацию в тайных условиях.",al={"tazan's logbook","satchel contents","what is in the satchel","дневник тазана","содержимое сумки","что в сумке"}},{q="Что такое Изувеченная Длань в Оргриммаре?",a="Изначально печально известный орочий клан из Дренора, прославившийся самоистязанием и жестокостью, Изувеченная Длань в Оргриммаре превратилась в главную гильдию убийц, шпионов и разбойников Орды, действующую из подземной Расселины Теней.",al={"what is shattered hand","shattered hand rogues","orgrimmar rogues","что такое изувеченная длань","разбойники изувеченной длани","разбойники оргриммара"}},{q="Где действует Терзок?",a="Терзок действует из Расселины Теней — сумрачной сети пещер под скалистыми хребтами Оргриммара, где вдали от дневного света процветают чернокнижники, разбойники и искусство теней.",al={"where is therzok","therzok location","cleft of shadow rogue trainer","где терзок","местонахождение терзока","учитель разбойников расселина теней"}},{q="Почему Терзок просто не взломает сумку?",a="Сумка снабжена сложным замком, но важнее другое: это проверка дисциплины разбойника. Изувеченная Длань ценит точную кражу и ловкость выше шумного разрушения.",al={"why pickpocket","why need key","зачем красть из карманов","зачем нужен ключ"}},{q="Что будет после этого задания?",a="Это поручение завершает цепочку посвящения. Передав дневник Тазана, вы официально становитесь признанным членом Изувеченной Длани и получаете инструменты для будущих тайных дел.",al={"shattered hand reward","end of chain","награда изувеченной длани","конец цепочки"}}},fp="18,216,18.387.0,22.353.0,42.243.0,31.216.0,40.250.0,27.179.0,48.194.0,30.223.1"}
P.entries["quest:1859"] = {n="Терзок",s="«Терзок» — вызов для многообещающих разбойников Орды, действующих возле Долины Испытаний и Деревни Сен'джин. Учитель разбойников Каплак замечает вашу склонность к насилию и скрытности и тайно направляет вас в пещерную Расселину Теней на встречу с агентом Изувеченной Длани.",h="«Терзок» — вызов для многообещающих разбойников Орды, действующих возле Долины Испытаний и Деревни Сен'джин.",kw={"assassin","cleft of shadow","durotar","kaplak","orgrimmar","rogue","shattered hand","therzok","убийца","расселина теней","дуротар","каплак","оргриммар","разбойник","изувеченная длань","терзок"},ang={["class:Rogue"]="Этот вызов означает ваше официальное вступление в Изувеченную Длань и связывает вашу одиночную работу в Дуротаре с организованной шпионской сетью по всей Орде.",["faction:Horde"]="Пока Тралл проповедует честь и боевой дух, существование Терзока и его сети доказывает, что Орда понимает практическую необходимость невидимых клинков и тайных собирателей сведений."},sec={{t="Тайный вызов",b="Не все слуги новой Орды сражаются открыто, днем, под знаменем чести Тралла. Когда молодые разбойники начинают заслуживать имя в Дуротаре, Каплак отводит их в сторону и говорит вполголоса. Слух об агенте, сочетающем смертоносность с готовностью обходить правила открытой войны, быстро доходит до подпольной гильдии в Оргриммаре."},{t="В Расселину Теней",b="Каплак отправляет посвящаемого глубоко под красные каменные утесы Оргриммара, в Расселину Теней. Вдали от бдительных глаз городских стражей Терзок ждет во мраке. Эта встреча — точка посвящения, которая приводит одиноких карманников и мастеров засад в стройные ряды Изувеченной Длани — тайной сети, служащей кинжалами Орды во тьме."}},faq={{q="Кто такой Терзок?",a="Терзок — агент Изувеченной Длани, обосновавшийся в подземной Расселине Теней в Оргриммаре. Он проверяет многообещающих молодых разбойников, прибывающих с тренировочных земель Дуротара, и принимает их на службу гильдии.",al={"who is therzok","therzok lore","npc therzok","кто такой терзок","предыстория терзока","персонаж терзок"}},{q="Почему Каплак отправляет меня к нему?",a="Каплак видит, что вы сочетаете боевое мастерство с талантом к скрытности и обману. Зная, что Изувеченная Длань постоянно ищет способных плутов для пополнения рядов, он передает вам просьбу Терзока о вербовке.",al={"why send me to therzok","kaplak quest","why go to orgrimmar","почему идти к терзоку","задание каплака","зачем идти в оргриммар"}},{q="Что такое Изувеченная Длань в Оргриммаре?",a="Хотя название восходит к древнему клану Дренора, в современном Оргриммаре Изувеченная Длань — тайная гильдия убийц, шпионов и воров на службе Орды. Они выполняют необходимые, но морально сомнительные задачи, которые честные воины Тралла не могут исполнять открыто.",al={"what is shattered hand","shattered hand orgrimmar","horde rogue guild","что такое изувеченная длань","изувеченная длань оргриммар","гильдия разбойников орды"}},{q="Где находится Расселина Теней?",a="Расселина Теней — обширная пещера под центральной частью Оргриммара; к ней ведут темные проходы из Аллеи Силы и Аллеи Чести. В ней обитают городские чернокнижники и разбойники, скрытые от посторонних глаз.",al={"where is cleft of shadow","how to find therzok","cleft of shadow location","где расселина теней","как найти терзока","местонахождение расселины теней"}},{q="Что будет после встречи с Терзоком?",a="После приветствия Терзок сразу знакомит вас с обязанностями на службе Изувеченной Длани и дает поручения, чтобы проверить вашу способность, скрытность и верность сети.",al={"next quest","what does therzok want","after therzok","следующее задание","что хочет терзок","после терзока"}},{q="Получают ли это задание не разбойники?",a="Нет. Это задание предлагают только разбойникам, достигшим определенного уровня опыта; оно знаменует их переход от местных стычек к статусу полноправных агентов разведывательной сети Орды.",al={"can other classes do this","is this rogue only","rogue quest","могут ли другие классы","только ли для разбойников","задание разбойника"}}},fp="7,282,19.368.0,24.369.0,15.228.0,31.243.0,40.284.0,37.237.0,33.190.0,33.200.0"}
P.entries["quest:1860"] = {n="Поговорите с Джиннией",s="«Поговорите с Джиннией» — вводный вызов для начинающих магов Альянса, закончивших начальное обучение в Элвиннском лесу. Наставник Залдимар Вефхеллт в Златоземье направляет посвящаемых прямо к Джиннии Пушка в Святилище волшебника в Штормграде.",h="«Поговорите с Джиннией» — вводный вызов для начинающих магов Альянса, закончивших начальное обучение в...",kw={"elwynn forest","goldshire","jennea cannon","mage quarter","speak with jennea","stormwind","wizard's sanctum","zaldimar wefhellt","элвиннский лес","златоземье","джинния пушка","квартал магов","поговорите с джиннией","штормград","святилище волшебника","залдимар вефхеллт"},ang={["class:Mage"]="Это поручение означает ваш переход от деревенского чародейства в Златоземье к официальной работе с высшими магами Святилища волшебника в Штормграде.",["faction:Alliance"]="Безопасность Элвиннского леса и Штормграда держится не только на пехоте, но и на тайной бдительности, которую напрямую направляет магическая академия столицы."},sec={{t="Зов в Святилище волшебника",b="Когда ученик-маг в Златоземье достаточно овладевает простыми заклинаниями, Залдимар Вефхеллт понимает, что полевое обучение у местных наставников исчерпано. Чтобы не засиживаться в деревушках Элвинна, многообещающих чародеев направляют в сам Штормград. В сердце Квартала магов возвышается Святилище волшебника — обширное убежище тайных исследований и обучения, где старшие чародеи королевства согласуют более широкие магические дела."},{t="Дела безопасности королевства",b="Залдимар подчеркивает, что явка в Штормград — не просто обычное учебное повышение: возникло особое дело, напрямую влияющее на безопасность Элвиннского леса и Штормграда. По прибытии ученик докладывает Джиннии Пушка — опытному магу, надзирающему за важными местными поручениями. Хотя Джинния осторожна и сдержанна в раскрытии великих тайн только что прибывшему ученику, явка к ней означает начало прямой службы ордену волшебников."}},faq={{q="Кто посылает меня с этим заданием?",a="Залдимар Вефхеллт, человек-наставник магов в таверне Гордость Льва в Златоземье, выдает это задание, когда вы достигаете достаточного уровня владения тайной магией.",al={"quest giver","who gives quest","zaldimar","персонаж, выдающий задание","кто дает задание","залдимар"}},{q="Где найти Джиннию Пушка?",a="Джинния Пушка находится в Святилище волшебника в центре Квартала магов Штормграда. Ее можно застать за занятиями в таинственных залах святилища.",al={"jennea cannon location","where is jennea","find jennea","где джинния пушка","где джинния","найти джиннию"}},{q="Что такое Святилище волшебника?",a="Святилище волшебника — выдающаяся магическая башня в Квартале магов Штормграда. Это главная академия, библиотека и оперативная база магов и ученых-чародеев королевства.",al={"what is wizards sanctum","mage tower stormwind","что такое святилище волшебника","башня магов штормград"}},{q="Почему Залдимар посылает меня к Джиннии, а не решает все сам?",a="Залдимар обучает молодых магов основам в Златоземье, но более крупными региональными угрозами и особыми задачами, затрагивающими королевство, занимаются ученые более высокого ранга, такие как Джинния Пушка, из столицы.",al={"why go to stormwind","why jennea","зачем идти в штормград","почему джинния"}},{q="Что будет после доклада Джиннии Пушка?",a="Когда вы доложите Джиннии, она поручит вам расследовать загадочные магические аномалии вокруг Зеркального озера в Элвиннском лесу.",al={"what next","follow up quest","next step","что дальше","продолжение задания","следующий шаг"}},{q="Доступно ли это задание любому классу?",a="Нет. Это задание только для магов — обряд посвящения класса, выводящий ученика из деревенского обучения в официальные ряды тайного общества Штормграда.",al={"can non mages do this","mage only","class requirement","могут ли не маги выполнить","только для магов","требование класса"}}},fp="17,310,30.503.0,27.490.0,27.159.0,31.170.0,29.189.0,67.208.0,46.135.1,37.190.0"}
P.entries["quest:1861"] = {n="Зеркальное озеро",s="Зеркальное озеро — вводное задание-расследование для начинающих магов Альянса, обучающихся в Квартале магов Штормграда. По поручению Джинния Пушка ученики отправляются к юго-западу от городских ворот, чтобы взять пробы воды водопада Зеркального озера и проверить ее на остаточное магическое заражение.",h="Зеркальное озеро — вводное задание-расследование для начинающих магов Альянса, обучающихся в Квартале магов...",kw={"arcane taint","elwynn forest","jennea cannon","ley lines","mirror lake","water sample","wizards sanctum","тайная порча","элвиннский лес","джинния пушка","силовые линии","зеркальное озеро","образец воды","святилище волшебника"},ang={["class:Mage"]="Это задание знаменует переход ученика от чтения пыльных томов в Святилище волшебника к исследованию реальных тайных явлений; наградой служит его первый магический посох или предмет для левой руки.",["faction:Alliance"]="Забота о природных ресурсах Элвинна — один из тихих способов, которыми маги Святилища волшебника оберегают сердце королевства.",["race:Human"]="Зеркальное озеро питает окрестные поля и водотоки Элвинна, поэтому его чистота жизненно важна для повседневного здоровья жителей Штормграда."},sec={{t="Силовые линии и переменчивые потоки",b="За последние десятилетия Азерот пережил катастрофические магические конфликты — от открытия Темного портала до Третьей войны и битвы у горы Хиджал. Эти потрясения вырвали древние тайные потоки из прежде устойчивых русел. В Святилище волшебника в Штормграде маги вроде Джинния Пушка пристально следят за этими сдвигами, опасаясь, что сместившиеся потоки тайной силы могут просочиться в окрестные земли и испортить местные экосистемы."},{t="Проверка воды",b="Зеркальное озеро лежит под утесами к юго-западу от ворот Штормграда и служит главным природным водоемом, питаемым горными водопадами. Поскольку окрестные земли зависят от этих вод, Джинния посылает начинающих магов со стеклянной колбой прямо к подножию водопада. Собранные свежие брызги позволяют Святилищу провести тонкие проверки с помощью ясновидения и реагентов и выяснить, не начала ли дикая магия просачиваться в общественный водопровод."}},faq={{q="Зачем Джинния Пушка нужна проба воды из Зеркального озера?",a="Огромные магические войны по всему Азероту разорвали естественные потоки силовых линий. Джинния Пушка опасается, что неустойчивые тайные энергии просачиваются в грунтовые воды вокруг Штормграда, что может навредить любому, кто пьет из озера.",al={"why mirror lake water","jennea water sample","what is this quest for","зачем вода зеркального озера","проба воды джинния","для чего это задание"}},{q="Где именно находится Зеркальное озеро?",a="Зеркальное озеро расположено на северо-западе Элвиннского леса, у высоких обрывов к юго-западу от главных ворот Штормграда. Нужную пробу берут из водоема у подножия каскадного водопада.",al={"where is mirror lake","mirror lake location","find mirror lake","где зеркальное озеро","расположение зеркального озера","найти зеркальное озеро"}},{q="Что случится, если вода заражена?",a="Jennea fears that drinking magically tainted water for too long could harm those who rely on the lake. The precise effects are not yet known.",al={"is the water poisoned","what if water has magic","magical taint effects","отравлена ли вода","что если в воде магия","последствия магического заражения"}},{q="Кто может взяться за это поручение?",a="Это поручение предназначено именно для начинающих магов Альянса и служит одним из первых их практических заданий от имени Святилища волшебника.",al={"who gets mirror lake quest","is mirror lake mage only","кто получает задание зеркальное озеро","только ли для магов"}},{q="Ведет ли это задание к дальнейшим расследованиям?",a="Оно завершает первое прямое поручение, начатое вызовом Джинния Пушка: ученик получает свой первый настоящий магический инструмент и обязанность следить за магическими возмущениями в королевстве.",al={"what comes after mirror lake","mirror lake quest chain","что после зеркального озера","цепочка заданий зеркальное озеро"}},{q="Что вообще вызвало нестабильность магических потоков?",a="Дженна объясняет изменившиеся течения огромными мистическими битвами в мире, не называя конкретного сражения или события.",al={"why are ley lines damaged","mystic struggles meaning","what broke the magic","почему повреждены силовые линии","магические потрясения значение","что сломало магию"}}},fp="11,279,31.453.0,18.464.0,60.237.0,29.215.0,37.141.0,31.177.0,47.214.0,67.127.0"}
P.entries["quest:1879"] = {n="Поговорите с Бинк",s="«Поговорите с Бинк» — вызов Альянса, направляющий начинающих магов из Дун Морога в столицу, Стальгорн. По поручению Магиса Искроплаща многообещающие заклинатели отправляются помогать Бинк, исследовательнице тайной магии из Зала Тайн.",h="«Поговорите с Бинк» — вызов Альянса, направляющий начинающих магов из Дун Морога в столицу, Стальгорн.",kw={"bink","dun morogh","hall of mysteries","ironforge","mage","magis sparkmantle","mystic ward","бинк","дун морог","зал тайн","стальгорн","маг","магис искроплащ","мистический квартал"},ang={["class:Mage"]="Этот вызов знаменует ваш переход от начального обучения в долине к более широким делам ученых магов Стальгорна.",["faction:Alliance"]="Совместные занятия в Зале Тайн показывают тесное сочетание гномьего ума и дворфийского гостеприимства под знаменем Альянса.",["race:Gnome"]="Бинк и Магис Искроплащ продолжают гномью традицию тайной магии в гостеприимных залах Стальгорна после потери Гномрегана."},sec={{t="Зов коллеги",b="Начинающие маги, обучающиеся в холодных скалах Дун Морога, рано или поздно привлекают внимание Магиса Искроплаща. Видя, что ученик перерос простые упражнения возле Караноса, Искроплащ передает просьбу своей коллеги Бинк. Просьба точна и непреклонна: Бинк нужен специалист по тайной магии, и она не доверит дело тому, кто не владеет магией."},{t="Зал Тайн",b="Поручение приводит молодых магов в Мистический квартал Стальгорна, где ученые, жрецы и маги собираются под высокими каменными сводами Зала Тайн. Здесь Бинк ведет свои исследования и оценивает прибывших учеников зорким взглядом. По ее мнению, сырой потенциал — лишь начало: недисциплинированный заклинатель в тайных делах быстро становится угрозой, а не подспорьем."}},faq={{q="Кто выдает это задание?",a="Магис Искроплащ предлагает это задание начинающим магам Альянса, продвинувшимся в начальном обучении в Дун Мороге.",al={"quest giver","where to start","who starts speak with bink","кто выдает задание","с чего начать","кто начинает поговорите с бинк"}},{q="Где найти Бинк?",a="Бинк находится в Зале Тайн, в Мистическом квартале в северной части Стальгорна.",al={"bink location","where is bink","find bink","где бинк","местонахождение бинк","найти бинк"}},{q="Почему Бинк нужен только маг?",a="Бинк проводит исследование, напрямую связанное с тайной энергией и чувствительным измерительным оборудованием. Она считает, что не маги плохо подходят для работы с магическими тонкостями и опасностями.",al={"why mages only","mage requirement","bink only wants mages","почему только маги","требование к магам","бинк нужны только маги"}},{q="Что происходит после встречи с Бинк?",a="Поприветствовав вас и оценив ваши способности, Бинк привлекает вас к своим исследованиям, и вы переходите к заданию «Мага-гизмонитор».",al={"next quest","bink follow up","what comes after speak with bink","следующее задание","продолжение бинк","что после поговорите с бинк"}},{q="Доступно ли это задание не магам?",a="Нет. Это задание создано исключительно для магов как переход от местного начального обучения к особым поручениям в столице.",al={"can other classes do this","is this mage only","mage specific","могут ли другие классы","только для магов","задание для мага"}},{q="Что такое Зал Тайн?",a="Зал Тайн — центр тайных и священных наук Стальгорна; здесь работают наставники, ученые и исследователи, представляющие магические искусства как дворфов, так и гномов.",al={"ironforge hall of mysteries","what is hall of mysteries","зал тайн стальгорн","что такое зал тайн"}}},fp="15,259,21.388.0,21.404.0,21.113.0,22.108.0,31.192.0,32.141.0,52.134.0,30.172.0"}
P.entries["quest:1881"] = {n="Разговор с Анастасией",s="«Разговор с Анастасией» — вводный вызов, направляющий многообещающих магов Отрекшихся к Анастасии Хартвелл в Подгороде. По поручению наставника магов Кейна Песнь Пламени молодой заклинатель призывается в Магический квартал для важной работы на благо магов Отрекшихся. Этот краткий вызов открывает путь к расследованиям в оскверненных землях Тирисфальских лесов.",h="«Разговор с Анастасией» — вводный вызов, направляющий многообещающих магов Отрекшихся к Анастасии Хартвелл в...",kw={"anastasia hartwell","balnir farmstead","cain firesong","mage quest","magic quarter","undercity","анастасия хартвелл","ферма балнира","кейн песнь пламени","задание мага","магический квартал","подгород"},ang={["class:Mage"]="Это задание знаменует ваш переход от базового обучения тайной магии к активной службе магам Подгорода.",["race:Undead"]="Для тайных магов Отрекшихся ответ на зов Хартвелл — возможность использовать интеллектуальное прошлое Лордерона против его нынешних опасностей."},sec={{t="Зов в Магический квартал",b="Пока начинающие заклинатели оттачивают первые таланты под руководством Кейна Песни Пламени, их вскоре направляют вглубь столицы. Маги Отрекшихся держат особый анклав в Магическом квартале Подгорода, где организуют и тайные исследования, и стратегическую оборону по всему Лордерону. Кейн Песнь Пламени выступает оценщиком: он отсеивает простых новичков и направляет по-настоящему одаренных прямо к старшим магам, которым нужны умелые помощники."},{t="Амбиции Анастасии Хартвелл",b="Анастасия Хартвелл — одна из видных наставниц магов в Подгороде. Вместо того чтобы оставлять многообещающих учеников изучать простые заклинания в безопасности, она не медлит и привлекает их к службе территориальным и практическим интересам Отрекшихся. Ответить на ее зов — и обряд посвящения для чародеев, и приобщение к мрачным, прагматичным магическим занятиям, определяющим нежить после Плети."}},faq={{q="Кто посылает вас поговорить с Анастасией Хартвелл?",a="Кейн Песнь Пламени, наставник магов Отрекшихся, посылает вас к ней, признав, что ваши тайные способности достаточно развиты, чтобы помогать в более сложных делах в столице.",al={"who gives speak with anastasia","quest giver speak with anastasia","cain firesong summons","кто дает разговор с анастасией","кто выдает задание разговор с анастасией","вызов кейна песнь пламени"}},{q="Где можно найти Анастасию Хартвелл?",a="Анастасия Хартвелл находится в Магическом квартале Подгорода, где руководит чародеями Отрекшихся и обучает их.",al={"where is anastasia hartwell","anastasia hartwell location","find anastasia","где анастасия хартвелл","местонахождение анастасии хартвелл","найти анастасию"}},{q="Для чего нужен этот вызов?",a="Анастасии нужен умелый заклинатель для практических задач за городскими стенами, начиная с поручений в Тирисфальских лесах, например расследования на Ферме Балнира.",al={"why does she want me","speak with anastasia purpose","what does anastasia need","зачем я ей нужен","цель разговора с анастасией","что нужно анастасии"}},{q="Какое задание идет после «Разговора с Анастасией»?",a="Доклад Анастасии напрямую ведет к заданию «Усадьба Балнира»: вас отправляют в восточную часть Тирисфальских лесов собирать львиный зев в саду усадьбы.",al={"what quest comes next","next quest after speak with anastasia","speak with anastasia followup","какое задание дальше","следующее задание после разговора с анастасией","продолжение разговора с анастасией"}},{q="Ограничено ли это задание определенными классами?",a="Да, это задание предназначено именно для магов Отрекшихся и служит ступенью в развитии класса, когда они достигают начальной умелости около десятого уровня.",al={"is this a mage only quest","who can do speak with anastasia","class requirement","только ли для магов","кто может выполнить разговор с анастасией","требование к классу"}},{q="Почему маги Отрекшихся держат отдельные покои в Подгороде?",a="Магический квартал дает чародеям, чернокнижникам и исследователям Отрекшихся особое убежище, где они могут учиться и колдовать вдали от физических кварталов, продолжая довоенные традиции Третьей войны в недрах Лордерона.",al={"why magic quarter","forsaken mages undercity","почему магический квартал","маги отрекшихся подгород"}}},fp="20,370,27.494.0,29.442.0,47.178.0,38.152.0,36.183.0,40.160.0,41.163.0,67.227.0"}
P.entries["quest:1882"] = {n="Усадьба Балнира",s="«Усадьба Балнира» — одно из первых испытаний для молодых магов из числа Отрекшихся, которое выдает Анастасия Хартвелл в Квартале магов Подгорода. Посвящаемых отправляют в восточные Тирисфальские леса собрать львиный зев на заброшенной ферме, расположенной опасно близко к границе Чумных земель. Образцы цветов служат барометрами надвигающейся магической порчи, распространяющейся с востока, опустошенного Плетью.",h="«Усадьба Балнира» — одно из первых испытаний для молодых магов из числа Отрекшихся, которое выдает Анастасия...",kw={"anastasia","balnir","farmstead","hartwell","mage","plaguelands","snapdragons","tirisfal","undercity","анастасия","балнир","усадьба","хартвелл","маг","чумные земли","львиный зев","тирисфаль","подгород"},ang={["class:Mage"]="Это раннее испытание учит начинающих магов, что изучение тайной магии необходимо для наблюдения за чужеродной магической порчей и защиты от нее.",["profession:Herbalism"]="Львиный зев Балнира показывает, как растения могут служить прямыми накопителями и индикаторами магического загрязнения.",["race:Undead"]="Для Отрекшихся защита границ Тирисфальских лесов от наступающей Плети — вопрос выживания и суверенитета."},sec={{t="Магический барометр",b="Хотя Королевское фармацевтическое общество часто изучает действие некромантии и распада, маги Отрекшихся тоже внимательно следят за пограничными землями. Анастасия Хартвелл поручает начинающим магам отправиться на Ферму Балнира в восточных Тирисфальских лесах. Львиный зев, растущий в садах фермы, от природы чувствителен к смене магических потоков и впитывает окружающие энергии из почвы и воздуха. Исследуя эти цветы, чародеи-ученые Подгорода могут определить, просочилась ли порча, несущая заразу из владений Короля-лича, через преграду в сам Тирисфаль."},{t="Восточная граница",b="Усадьба Балнира расположена на окраине лесов, неуютно близко к изуродованным чумой пустошам Западных Чумных земель. Отрекшиеся понимают, что чума Короля-лича — необузданная и разрушительная сила, которая буквально гноит землю. Хотя Отрекшиеся сами используют темные искусства, неподконтрольная порча Плети угрожает их границам и безопасности. Анастасия намерена передать собранный львиный зев фармацевтам, объединив магические наблюдения с алхимическими исследованиями ради защиты отвоеванного сердца Лордерона."}},faq={{q="Почему Анастасии Хартвелл нужен именно львиный зев?",a="Львиный зев с фермы Балнира обладает особой природной чувствительностью к окружающим магическим силам. Поскольку он впитывает энергию прямо из земли и воздуха, его изучение позволяет магам Отрекшихся определить, не заражают ли Тирисфальские леса магическая и некромантическая порча соседних Чумных земель.",al={"why snapdragons","balnir snapdragons purpose","what are snapdragons for","зачем львиный зев","львиный зев балнира","для чего нужен львиный зев"}},{q="Где находится Усадьба Балнира?",a="Усадьба находится в восточных Тирисфальских лесах, ближе к границе, где леса подходят к зараженному рубежу Западных Чумных земель. Львиный зев растет на заросших грядках и в садах вокруг полуразрушенных построек фермы.",al={"balnir farmstead location","where is balnir farm","find balnir farmstead","где усадьба балнира","расположение усадьбы балнира","где ферма балнира","найти усадьбу балнира"}},{q="Кто такая Анастасия Хартвелл?",a="Анастасия Хартвелл — известная маг из числа Отрекшихся и учитель, живущая в Квартале магов Подгорода. Она наставляет новоявленных магов-нежить, обучая их дисциплине, арканному равновесию и практической защите границ от враждебных сил.",al={"anastasia hartwell lore","who is anastasia","анастасия хартвелл","кто такая анастасия"}},{q="Почему маги Отрекшихся стремятся остановить чуму?",a="Хотя Отрекшиеся сами экспериментируют с чумой и порчей, заразная магия Плети Короля-лича считается неконтролируемой аберрацией. Если ее не остановить, порча Плети поглотит Тирисфальские леса целиком и подорвет независимость Отрекшихся.",al={"why stop the plague","do forsaken hate the plague","зачем остановить чуму","ненавидят ли отрекшиеся чуму"}},{q="Что происходит с цветами после того, как вы их соберете?",a="Получив львиный зев, Анастасия готовится передать его фармацевтам Подгорода. Алхимики и маги вместе вскрывают образцы, чтобы оценить, насколько глубоко Плеть заразила почву и растения.",al={"what does anastasia do with the flowers","who gets the snapdragons","что анастасия делает с цветами","кому достается львиный зев"}},{q="Это задание только для магов?",a="Да. Это особое классовое задание, предназначенное исключительно для молодых магов из числа Отрекшихся, которые закончили первые уроки в Могильнике и прибыли в столицу, чтобы доказать свое понимание тайной теории.",al={"is balnir farmstead mage only","mage class quest","усадьба балнира только для магов","задание мага"}}},fp="20,416,19.614.0,18.566.0,58.297.0,38.248.0,26.261.0,53.269.0,51.231.0,34.219.0"}
P.entries["quest:1886"] = {n="Стражи смерти",s="Это задание — испытание для посвящаемых, желающих вступить в Стражи смерти, тайное и смертоносное подразделение, подчиняющееся лорду Вариматрасу в Подгороде. Его выдает Меннит Каркад в Квартале разбойников; миссия требует безжалостной инициативы, чтобы перехватить странствующего посыльного. Выполнение открывает путь к более глубоким тайным замыслам в державе Отрекшихся.",h="Это задание — испытание для посвящаемых, желающих вступить в Стражи смерти, тайное и смертоносное...",kw={"astor hadren","deathstalkers","mennet carkad","rogues' quarter","silverpine","undercity","varimathras","астор хадрен","стражи смерти","меннит каркад","квартал разбойников","серебряный бор","подгород","вариматрас"},ang={["class:Rogue"]="Для разбойников из числа Отрекшихся вступление в Стражи смерти — высшая ступень государственной службы, превращающая уличных мошенников в присягнувшие орудия Вариматраса и Темной Госпожи.",["faction:Horde"]="Стражи смерти действуют в глубокой тайне, благодаря чему Отрекшиеся сохраняют важные разведывательные сети, а южные союзники Орды остаются почти в неведении об их неблаговидных внутренних делах.",["race:Undead"]="Стражи смерти — железная хватка внутренней безопасности Лордерона: они бдительно и подозрительно следят как за внешними врагами, так и за возможными предателями среди Отрекшихся."},sec={{t="Испытание в тенях",b="Стражи смерти принимают в свои ряды не всех. Этот тайный орден подчиняется непосредственно повелителю ужаса Вариматрасу и служит одновременно тайной полицией и элитным корпусом убийц Отрекшихся. Чтобы привлечь их внимание, кандидат должен проявить хитрость, скрытность и готовность без колебаний устранять цели. В темных уголках Квартала разбойников куратор Меннит Каркад устраивает посвятительное испытание, призванное отсеять слабых и излишне щепетильных."},{t="Перехват",b="Цель посвящаемого — Астор Хадрен, курьер, путешествующий по дороге между Подгородом и Серебряным бором. Каркад не дает тактических советов, полностью оставляя выбор способа заполучить личное рекомендательное письмо Хадрена на усмотрение агента. Задача сводится к тому, чтобы перехватить Астора, завладеть его бумагами и дать Стражам смерти возможность выдать новобранца за ожидаемого посланника к агенту по имени Андрон."}},faq={{q="Кто такие Стражи смерти?",a="Стражи смерти — элитное подразделение скрытности и убийств Отрекшихся. Их штаб находится в Квартале разбойников Подгорода; они занимаются шпионажем, тайными казнями и сбором сведений и подчиняются напрямую лорду Вариматрасу.",al={"deathstalkers lore","what are deathstalkers","undead rogues","стражи смерти","кто такие стражи смерти","разбойники нежити"}},{q="Кто такой Меннит Каркад?",a="Меннит Каркад — куратор Стражей смерти, работающий в Квартале разбойников Подгорода. Он руководит первыми испытаниями и проверяет новобранцев, надеющихся вступить в их тайные ряды.",al={"mennet carkad role","who gives quest","роль меннита каркада","кто дает задание"}},{q="Зачем Менниту нужно письмо Астора Хадрена?",a="Астор Хадрен — курьер, ездящий между Серебряным бором и Подгородом. Заполучив его рекомендательное письмо, Стражи смерти могут подменить Хадрена своим новым агентом, чтобы обмануть сообщника по имени Андрон.",al={"astor hadren letter","why intercept messenger","astor letter of introduction","письмо астора хадрена","зачем перехватывать посыльного","рекомендательное письмо астора"}},{q="Куда путешествует Астор Хадрен?",a="Астор Хадрен ходит по пути, соединяющему Подгород и Серебряный бор, и доставляет корреспонденцию между областями по поручению своих знакомых.",al={"astor hadren route","astor hadren location","where is astor","маршрут астора хадрена","где найти астора хадрена","где астор"}},{q="Кто такой лорд Вариматрас?",a="Вариматрас — повелитель ужаса из рода нафрезимов, заключивший союз с королевой Сильваной Ветрокрылая, чтобы сохранить собственное существование. Из Королевского квартала он руководит безопасностью, обороной и тайными операциями Подгорода.",al={"varimathras role","dreadlord in undercity","роль вариматраса","повелитель ужаса в подгороде"}},{q="Что происходит после этого испытания?",a="Прохождение испытания подтверждает мастерство агента и ведет к тайному заданию по выдаче себя за другого: доставить бумаги Астора и проникнуть в дела Андрона.",al={"what comes next","deathstalkers questline continuation","что дальше","продолжение цепочки стражей смерти"}}},fp="17,363,21.480.0,16.414.1,26.240.0,21.173.0,43.231.0,31.151.0,24.201.0,30.158.1"}
P.entries["quest:1898"] = {n="Стражи смерти",s="Это тайное задание отправляет агента под прикрытием в мрачные глубины Подгорода допросить ничего не подозревающего заговорщика. Выполняя приказ лорда Вариматраса, вы выдаете себя за ожидаемого посыльного, чтобы раскрыть измену в самой столице Отрекшихся.",h="Это тайное задание отправляет агента под прикрытием в мрачные глубины Подгорода допросить ничего не...",kw={"andron gant","apothecarium","astor hadren","deathstalkers","espionage","forsaken","mennet carkad","undercity","varimathras","андрон гант","апотекариум","астор хадрен","стражи смерти","шпионаж","отрекшиеся","меннит каркад","подгород","вариматрас"},ang={["class:Rogue"]="Проникновение в шпионскую сеть под личиной мертвеца, чтобы заманить неосторожного заговорщика, — прием прямо из учебника Стражей смерти.",["faction:Horde"]="Под поверхностью Подгорода скрывается гнездо политических интриг, и это доказывает: даже в землях Орды доверие — редкость.",["race:Undead"]="Для Отрекшихся бдительность — это выживание. Любой гражданин, уличенный в помощи сторонним группировкам, рискует быть немедленно уничтоженным тайной полицией Темной Госпожи."},sec={{t="Паутина обмана",b="Стражи смерти не просто устраняют внешние угрозы для Отрекшихся, но и безжалостно следят за собственными гражданами. Повинуясь подозрениям лорда Вариматраса, Страж смерти Меннит Каркад приводит в действие план проникновения. Имея поддельное или добытое рекомендательное письмо Астора Хадрена, вы должны усыпить подозрения местного торговца по имени Андрон Гант."},{t="Лавка возле Апотекариума",b="Андрон Гант торгует в лавке неподалеку от едких испарений и булькающих котлов Апотекариума. Меннит считает лавочника глупым и невнимательным, не способным раскусить самозванца. Предъявленное письмо подтверждает вашу личину посыльного, и Гант охотно ослабляет бдительность и сам рассказывает о своих делах с неизвестной третьей стороной."}},faq={{q="Кто такой Андрон Гант?",a="Андрон Гант — лавочник из Подгорода, чья лавка находится возле Апотекариума. Он привлек внимание Стражей смерти и лорда Вариматраса: его подозревают в передаче сведений и помощи неизвестной внешней группировке.",al={"andron gant","who is gant","where is andron gant","андрон гант","кто такой гант","где найти андрона ганта"}},{q="Почему лорд Вариматрас интересуется этим торговцем?",a="Вариматрас подозревает Ганта в сотрудничестве с организацией за пределами Отрекшихся. Чтобы защитить город и пресечь возможную подрывную деятельность, повелитель ужаса требует неопровержимых доказательств связей и намерений Ганта.",al={"why varimathras cares","varimathras andron gant","why spy on andron","почему вариматрас интересуется","вариматрас андрон гант","зачем следить за андроном"}},{q="Как игрок обманывает Андрона Ганта?",a="Меннит Каркад снабжает вас рекомендательным письмом Астора. Гант ждал посыльного, а Стражи смерти считают его не слишком сообразительным, поэтому достаточно показать ему бумаги, чтобы завоевать его доверие.",al={"astors letter","how to trick andron gant","messenger disguise","письмо астора","как обмануть андрона ганта","маскировка посыльного"}},{q="Что за группа — Стражи смерти?",a="Стражи смерти — элитный орден разбойников и тайная разведывательная служба Отрекшихся. Действуя из тени под началом королевы Сильваны и лорда Вариматраса, они выявляют измену, саботируют планы врагов и устраняют внутренние угрозы.",al={"deathstalkers lore","who are deathstalkers","undercity rogues","стражи смерти предания","кто такие стражи смерти","разбойники подгорода"}},{q="Где можно найти Андрона Ганта?",a="Он живет в своей лавке у входа в квартал Апотекариума в Подгороде и ведет дела под пристальным надзором Королевского фармацевтического общества и Стражей смерти.",al={"andron gant location","where is gant shop","где андрон гант","расположение андрона ганта","где лавка ганта"}},{q="Что происходит после того, как Гант принимает письмо?",a="Гант принимает письмо без подозрений и считает вас обычным посыльным. Он тут же намекает на продолжение сотрудничества с общими знакомыми, что позволяет добыть новые доказательства его предательства.",al={"what does gant do","gant reaction","что делает гант","реакция ганта"}}},fp="17,276,15.416.0,30.377.1,19.228.0,52.214.0,40.225.0,33.235.0,31.189.0,43.228.1"}
P.entries["quest:1899"] = {n="Стражи смерти",s="Это поручение — важный шаг в оформлении соглашения между осведомителем Андроном Гантом и Стражами смерти Подгорода. Заручившись его поддержкой, агент доставляет подробный гроссбух Ганта прямо в руки Меннита Каркада в Квартале разбойников. Обмен знаменует переход от простых расспросов к более глубоким тайным операциям на благо государства Отрекшихся.",h="Это поручение — важный шаг в оформлении соглашения между осведомителем Андроном Гантом и Стражами смерти...",kw={"andron gant","assassins","deathstalkers","espionage","ledger","mennet carkad","rogues' quarter","undercity","андрон гант","убийцы","стражи смерти","шпионаж","гроссбух","меннит каркад","квартал разбойников","подгород"},ang={["class:Rogue"]="Для начинающего разбойника в Подгороде доставка секретных поручений для Меннита Каркада — основное испытание на осмотрительность: оно доказывает, что агент способен обращаться с тайными ресурсами, не привлекая лишнего внимания.",["race:Undead"]="Для нежити внутренняя безопасность Подгорода — вопрос выживания: помощь Стражам смерти напрямую укрепляет власть Темной Госпожи над столицей и против живых лазутчиков, и против соперников из числа нежити."},sec={{t="Посыльный в тени",b="Стражи смерти полагаются не только на грубую силу или магию тени: их операции во многом зависят от обычных гроссбухов, записанных имен и тщательной слежки. Андрон Гант из Подгорода соглашается передать личный гроссбух, набитый сведениями, которых так жаждут убийцы. Вместо того чтобы иметь дело с самим смертоносным ядром организации, Гант доверяется посреднику-посыльному, проявляя осторожность, обычную для любого, кто торгует сведениями среди мертвецов."},{t="Сведения в Квартале разбойников",b="Когда гроссбух доставлен Менниту Каркаду в Квартале разбойников, он оказывается куда информативнее, чем ожидали Стражи смерти. Вместо беглых заметок записи Ганта дают конкретные зацепки, позволяющие Каркаду расширить рамки расследований. В обстановке такой параноидальной и расколотой, как в государстве Отрекшихся, проверенные письменные следы необходимы, чтобы выявлять внутреннюю измену и следить за внешними угрозами, пока они не ударили по столице."}},faq={{q="Что записано в Гроссбухе Андрона?",a="В гроссбухе содержатся секретные сведения и записи, собранные Андроном Гантом. Точное содержание не оглашается, но Меннит Каркад отмечает, что там гораздо больше подробностей и ценных сведений, чем Стражи смерти рассчитывали получить.",al={"andron ledger contents","what does the ledger say","deathstalker ledger","содержимое гроссбуха андрона","что в гроссбухе","гроссбух стражей смерти"}},{q="Кто такие Стражи смерти?",a="Стражи смерти — главная тайная организация и гильдия убийц Отрекшихся. Их штаб находится в Квартале разбойников Подгорода; они служат глазами, ушами и скрытыми кинжалами леди Сильваны Ветрокрылой и занимаются шпионажем, разведкой и целевыми убийствами по всему Лордерону.",al={"deathstalker lore","who are deathstalkers","undercity rogues","стражи смерти предания","кто такие стражи смерти","разбойники подгорода"}},{q="Почему Гант хочет в будущем работать с тем же посыльным?",a="В мрачной атмосфере недоверия, царящей в Подгороде, редко найдешь агента, который доставит секретные бумаги, не украв и не подменив их. Гант прямо просит вести будущие дела через того же посыльного, чтобы снизить риски и сохранить сложившийся порядок работы.",al={"why does gant like you","andron gant trust","gant courier","почему гант доверяет вам","доверие андрона ганта","посыльный ганта"}},{q="Кто такой Меннит Каркад?",a="Меннит Каркад — опытный агент Стражей смерти, расквартированный в Квартале разбойников. Он координирует местных агентов, собирает полевые сведения у осведомителей вроде Андрона Ганта и руководит тайными заданиями в столице и окрестных землях.",al={"mennet carkad lore","who is carkad","меннит каркад предания","кто такой каркад"}},{q="Где находится Квартал разбойников?",a="Квартал разбойников — южный район Подгорода. Это главная база скрытных агентов, воров и убийц Отрекшихся, где есть тренировочные площадки и темные ниши вдали от людных площадей верхних руин.",al={"rogues quarter location","where is rogues quarter","undercity rogues quarter","расположение квартала разбойников","где квартал разбойников","квартал разбойников подгород"}},{q="Зачем Отрекшимся внутренняя разведка?",a="Окруженному со всех сторон Плетью, Алым орденом и настороженными остатками Альянса молодому государству Отрекшихся постоянно угрожают проникновение и мятеж. Стражи смерти выкорчевывают измену в границах Лордерона, чтобы молодой режим выжил.",al={"why deathstalkers exist","forsaken spies","undercity intelligence","зачем нужны стражи смерти","шпионы отрекшихся","разведка подгорода"}}},fp="17,408,24.503.0,35.465.1,27.270.0,26.299.0,55.305.0,21.265.0,37.248.0,57.274.0"}
P.entries["quest:19"] = {n="Тарил'зун",s="Маршал Маррис назначает награду за голову Тарил'зуна, хитрого предводителя гонцов Черной горы, терроризирующих дороги возле Крепости Каменной Стражи. Его гибель — важный шаг к разрушению власти клана Черной горы над северным Красногорьем. Доставка его отрубленной головы в Приозерье станет трудной победой для осажденной городской стражи.",h="Маршал Маррис назначает награду за голову Тарил'зуна, хитрого предводителя гонцов Черной горы...",kw={"blackrock","lakeshire","marshal marris","outrunners","redridge","stonewatch","stonewatch keep","tharil'zun","tharilzun","черная гора","приозерье","маршал маррис","гонцы","красногорье","каменная стража","крепость каменной стражи","тарил'зун"},ang={["faction:Alliance"]="Приозерье остается почти в изоляции, без прямой помощи из Штормграда, поэтому награда за голову Тарил'зуна — жизненно важная местная мера, чтобы город не оказался в осаде.",["race:Human"]="Присутствие Черной горы в Красногорье — болезненное напоминание о Первой и Второй войне, а убийство Тарил'зуна возвращает земли, отнятые у королевства.",["race:Orc"]="Тарил'зун принадлежит к темным остаткам Старой Орды под знаменем Черной горы и служит хозяевам, отвергающим новый порядок Тралла за морем."},sec={{t="The Road to Stonewatch",b="Извилистый перевал между Приозерьем и Крепостью Каменной Стражи превратился в череду внезапных засад. Гонцы и ренегаты Черной горы рыщут по скалистым хребтам, отрезая разведчиков и угрожая любому подкреплению, идущему к крепости. Маршал Маррис называет Тарил'зуна командиром, организующим эти согласованные нападения, и заявляет, что его уничтожение необходимо, чтобы Приозерье не оказалось в полном кольце."},{t="Обезглавить гонцов",b="Tharil'zun represents a dangerous breed of battlefield leader: vicious, crafty, and capable of coordinating the disparate orc raiders into an effective raiding force. Taking his head inside the shadow of Stonewatch requires cutting through entrenched Blackrock outposts. His death breaks the cohesion of the outrunner patrols, clearing a path for the Alliance to confront the garrison entrenched within the keep itself."}},faq={{q="Кто такой Тарил'зун?",a="Тарил'зун — грозный орочий командир клана Черной горы, который возглавляет гонцов и ренегатов, устраивающих засады на тропах между Приозерьем и Крепостью Каменной Стражи.",al={"who is tharilzun","tharil'zun lore","tharilzun boss","кто такой тарил'зун","тарил'зун предания","тарил'зун босс"}},{q="Где можно найти Тарил'зуна?",a="Тарил'зун расположился возле Крепости Каменной Стражи на северо-востоке Красногорья и командует гонцами, патрулирующими окрестные перевалы и форпосты.",al={"where is tharil'zun","tharilzun location","find tharil'zun","где тарил'зун","местонахождение тарил'зуна","найти тарил'зуна"}},{q="Почему маршал Маррис хочет получить его голову?",a="Маррис считает Тарил'зуна хитрым тактиком, направляющим засады, которые терзают Красногорье. Требование головы гарантирует, что руководство гонцов будет уничтожено, и служит неоспоримым доказательством устранения угрозы.",al={"why kill tharilzun","tharilzun bounty reason","зачем убивать тарил'зуна","награда за тарил'зуна"}},{q="Что происходит после победы над Тарил'зуном?",a="Гибель Тарил'зуна лишает гонцов слаженности, и защитники Приозерья и искатели приключений могут проникнуть глубже в Крепость Каменной Стражи, чтобы сразиться с главным гарнизоном Черной горы.",al={"quest after tharilzun","what follows tharil'zun","задание после тарил'зуна","что дальше после тарил'зуна"}},{q="Почему орки Черной горы оказались в Красногорье?",a="Остатки клана Черной горы продвинулись на юг из Пылающих степей в Красногорье и укрепили старые человеческие форпосты вроде Крепости Каменной Стражи, чтобы угрожать Восточным королевствам, пока армия Штормграда растянута.",al={"why are blackrock orcs in redridge","stonewatch orcs background","почему орки черной горы в красногорье","предыстория орков каменной стражи"}},{q="What prerequisite must be completed before hunting Tharil'zun?",a="Маршал Маррис требует, чтобы искатели приключений сначала доказали свою доблесть, проредив силы захватчиков в задании «Угроза Черной горы», и лишь потом отправляет их за самим Тарил'зуном.",al={"tharilzun prereq","how to unlock tharilzun quest","предварительное задание тарил'зуна","как открыть задание тарил'зуна"}}},fp="10,342,22.432.0,27.419.0,18.176.0,30.144.0,38.216.0,42.185.0,45.218.0,62.173.0"}
P.entries["quest:1918"] = {n="Оскверненная стихия",s="Убив взбудораженных водных элементалей у Озера Мистраль, искатели приключений находят мерзкую светящуюся сферу с оскверненной водой. Пытаясь понять, что отравило озеро и его духов стихий, они относят образец Мастоку Райльшипу на Заставу Расщепленного Дерева.",h="Убив взбудораженных водных элементалей у Озера Мистраль, искатели приключений находят мерзкую светящуюся...",kw={"ashenvale","befouled water globe","corrupted elementals","earthen ring","mastok wrilehiss","mystral lake","splintertree post","ясеневый лес","оскверненная водяная сфера","оскверненные элементали","служители земли","масток райльшип","озеро мистраль","застава расщепленного дерева"},ang={["class:Shaman"]="Искаженное состояние духов Озера Мистраль вызывает серьезную тревогу у шаманов: они слышат боль стихий и понимают, что необходимо вмешательство Служителей Земли.",["faction:Horde"]="Заставе Расщепленного Дерева нельзя допускать, чтобы у нее под боком росла хаотичная стихийная угроза, пока часовые Альянса и фурболги угрожают снабжающим путям Орды.",["race:Tauren"]="Странники-таурены ощущают глубокий культурный долг исцелять оскверненные воды земли, поэтому восстановление Озера Мистраль становится для них неотложной духовной задачей."},sec={{t="Оскверненные воды Озера Мистраль",b="Озеро Мистраль, лежащее на юго-востоке Ясеневого леса, оказалось в бедственном положении. Водные элементали, обитающие на его мелководье, стали яростно агрессивными и заметно осквернились. После гибели от них остаются не чистая сущность стихии, а странные, ярко светящиеся сферы с гнилой жидкостью. Скверна, поразившая озеро, сосредоточена внутри этих сфер, а значит, беспокойство элементалей — это нечто гораздо большее, чем обычная защита территории."},{t="В поисках совета на Заставе Расщепленного Дерева",b="Не понимая, какая скверная магия здесь действует, разведчики Орды обращаются за советом к гарнизону Заставы Расщепленного Дерева. Масток Райльшип, один из начальников форпоста, поначалу испытывает отвращение к мерзкому образцу, который ему принесли. Будучи солдатом, а не ученым, Масток быстро понимает, что обычная сталь не вылечит больную воду, и направляет искателя приключений к знатокам стихий — Служителям Земли."}},faq={{q="Что находится внутри Оскверненной водяной сферы?",a="Сфера содержит отвратительный концентрированный образец скверны, которая сейчас отравляет Озеро Мистраль. Она образуется из остатков убитых элементалей, что показывает: их духовная порча материальна и сильна.",al={"befouled globe contents","what is in the water globe","mystral lake water globe","содержимое оскверненной сферы","что внутри водяной сферы","водяная сфера озера мистраль"}},{q="Где начинается это задание?",a="Задание начинается с предмета, который выпадает при борьбе с разъяренными или оскверненными водными элементалями на Озере Мистраль в центрально-южной части Ясеневого леса.",al={"where do i find the water globe","how to start the befouled element","quest start","где найти водяную сферу","как начать оскверненная стихия","начало задания"}},{q="Почему Масток Райльшип не хочет иметь с этим дела?",a="Масток Райльшип — офицер Орды, занятый вопросами военного выживания и снабжения на Заставе Расщепленного Дерева. Он не умеет определять причины порчи магических вод, поэтому советует вместо этого обратиться к Служителям Земли.",al={"who is mastok","why talk to mastok","mastok wrilehiss role","кто такой масток","зачем говорить с мастоком","масток райльшип роль"}},{q="Чем это интересно Служителям Земли?",a="Служители Земли — орден шаманов, посвятивший себя изучению стихий, их умиротворению и восстановлению их гармонии. Оскверненные элементали, подобные тем, что живут на Озере Мистраль, напрямую подпадают под их духовную ответственность.",al={"why earthen ring","earthen ring connection","who are the earthen ring","почему служители земли","связь со служителями земли","кто такие служители земли"}},{q="Куда ведет расследование дальше?",a="Масток направляет вас к Дже'неу Санкри, шаману Служителей Земли, который находится на западном берегу Ясеневого леса у Форта Зорам'гар и может как следует осмотреть оскверненную реликвию.",al={"what comes next","next quest after befouled element","where do i go next","что дальше","следующее задание после оскверненной стихии","куда идти дальше"}}},fp="20,271,30.469.0,30.429.1,40.219.0,28.140.0,53.222.0,44.208.0,39.175.1"}
P.entries["quest:1938"] = {n="Трактат Ура по темной магии",s="«Трактат Ура по темной магии» — задание, которое выдает Верховный колдун Андромат в Квартале магов Штормграда. Он поручает искателям приключений вернуть запретный запечатанный магией том у мага-отступника Морганта, бежавшего с ним в Башню Илгалара в Красногорье.",h="«Трактат Ура по темной магии» — задание, которое выдает Верховный колдун Андромат в Квартале магов Штормграда.",kw={"andromath","ilgalar","morganth","shadow magic","stormwind","treatise","ur","wizards sanctum","андромат","илгалар","моргант","темная магия","штормград","трактат","ур","святилище волшебника"},ang={["class:Mage"]="Маги Штормграда серьезно относятся к внутренним дисциплинарным вопросам и поручают доверенным чародеям устранять опасные последствия того, что собрат обратился к запретной темной магии.",["class:Warlock"]="Пока Кирин-Тор и маги Штормграда боятся трактатов Ура о тенях, чернокнижники нередко жаждут тех самых сил внепланарного призыва и темного колдовства, что запечатаны в них.",["faction:Alliance"]="Возвращение украденного тома защищает границы Красногорья от растущей магической угрозы Морганта и оберегает королевство Штормград от беспризорной магии."},sec={{t="Раскол в Башне",b="Давным-давно три многообещающих мага учились вместе в Святилище волшебника в Штормграде. Со временем один из них, Моргант, поддался искушению темных искусств и магии Тени. Несмотря на отчаянные предостережения сверстников, убеждавших его отказаться от столь губительной силы, он не захотел расстаться со своей одержимостью. Его официально изгнали из магического ордена города, но он ушел не с пустыми руками — он похитил опасный труд, написанный Уром, печально известным верховным магом, чьи исследования выходили за рамки традиционных тайных искусств."},{t="Логово павшего мага",b="Моргант устроил новое убежище вдали от пристального внимания Штормграда, захватив Башню Илгалара на вершинах Красногорья. Верховный колдун Андромат не может допустить, чтобы столь опасные знания оставались в руках изгоя, занимающегося запретным колдовством. Поручая искателям приключений из Альянса прорвать оборону башни, Андромат стремится вернуть том, пока не пали его защитные чары."},{t="Нетронутые печати",b="Когда трактат найден в библиотеке Илгалара и возвращен в Святилище волшебника, Андромат испытывает огромное облегчение. Он опасался, что Моргант уже разрушил защитные чары или спрятал книгу в недоступном месте. К счастью, магические печати на трактате Ура выдержали и не позволили колдуну-отступнику освободить губительные тайны, заключенные на его страницах."}},faq={{q="Кто написал трактат?",a="Трактат написал Ур, легендарный маг Даларана, известный своими эзотерическими исследованиями внепланарных существ и темной магии.",al={"who is ur","author of the treatise","urs treatise author","кто такой ур","автор трактата","автор трактата ура"}},{q="Кто украл «Трактат Ура по темной магии»?",a="Моргант, бывший маг Штормграда, украл книгу, когда поддался темной магии и был изгнан из Святилища волшебника.",al={"who stole the book","who took the treatise","morganth book","кто украл книгу","кто взял трактат","моргант книга"}},{q="Где хранится книга?",a="Книга хранится в библиотеке Башни Илгалара, высоко в Красногорье, где Моргант устроил свое новое убежище.",al={"where is the treatise","tower of ilgalar book location","where is urs treatise found","где трактат","где книга в башне илгалара","где найти трактат ура"}},{q="Удалось ли Морганту прочесть книгу?",a="Нет. Когда трактат возвращают Верховному колдуну Андромату, он подтверждает, что защитные печати на книге выдержали, а значит, Моргант так и не сумел ее открыть.",al={"did morganth open the book","was the treatise opened","are the seals broken","открыл ли моргант книгу","был ли трактат открыт","сломаны ли печати"}},{q="Почему маги Штормграда хотят вернуть книгу?",a="Том содержит глубокие тайны темной магии, способные погубить неподготовленного. Маги Штормграда считают слишком опасным оставлять его в руках отступника вроде Морганта.",al={"why recover the book","why is the treatise dangerous","andromath goal","зачем вернуть книгу","почему трактат опасен","цель андромата"}},{q="Кто выдает это задание?",a="Задание предлагает Верховный колдун Андромат, находящийся в Святилище волшебника в Квартале магов Штормграда.",al={"quest giver","where to get urs treatise quest","andromath quest","персонаж, выдающий задание","где взять задание трактат ура","задание андромата"}}},fp="29,282,21.515.0,22.395.0,12.383.1,23.135.0,40.123.0,23.145.0,37.174.1,49.186.0,21.118.0"}
P.entries["quest:1940"] = {n="Безупречная паутина",s="«Безупречная паутина» — посвятительное задание для растущих магов Альянса, поручаемое Верховным колдуном Андроматом в Штормграде. Чтобы заслужить одеяние, подобающее положению адепта, чародея отправляют в темные чащи Сумеречного леса собирать лучший шелк с пауков-падальщиков. Собранные мотки доставляют портному Уинн Ларсон в Квартале магов для изготовления зачарованных одеяний.",h="«Безупречная паутина» — посвятительное задание для растущих магов Альянса, поручаемое Верховным колдуном...",kw={"andromath","carrion recluse","duskwood","larson clothiers","mage robes","pristine spider silk","wizard's sanctum","wynne larson","андромат","паук-падальщик","сумеречный лес","магазин ларсона","одеяния магов","безупречная паутина","святилище волшебника","уинн ларсон"},ang={["class:Mage"]="Этот обряд посвящения связывает ученичество и истинное адептство, гарантируя, что каждый маг Штормграда носит одеяние из нитей, добытых преодолением опасностей лично им.",["faction:Alliance"]="Сумеречный лес остается опасным рубежом для подданных Штормграда: магам приходится покидать убежище столицы, чтобы добыть редкие местные ресурсы.",["profession:Tailoring"]="Методы Уинн Ларсон показывают, как высококачественные волокна диких чудовищ можно превратить в магически восприимчивые ткани, намного превосходящие обычную овечью шерсть или лен."},sec={{t="Облачение адепта",b="В Святилище волшебника признание измеряется не только мастерством в тайной магии, но и облачением, которое носят ее практики. Верховный колдун Андромат видит, когда ученик перерос обычную работу подмастерья, и велит ему заказать одеяние, подобающее адепту. Вместо простой покупки готовых вещей маг должен доказать и умение действовать вне стен, и разборчивость, добыв безупречный чистый шелк прямо у опасных тварей."},{t="Станок Сумеречного леса",b="Нужный материал не найти на обычных торговых прилавках. Его необходимо осторожно извлечь у ядовитых пауков-падальщиков, бродящих в призрачном сумраке Сумеречного леса. Когда восемь отборных образцов собраны, их приносят через весь город в магазин Ларсона в Квартале магов, где портной Уинн Ларсон готова спрясть тонкие нити в одеяние с магическим значением."}},faq={{q="Кто посылает магов с этим поручением?",a="Верховный колдун Андромат, возглавляющий Святилище волшебника в Штормграде, предлагает это задание чародеям, доказавшим свою преданность.",al={"who gives pristine spider silk","quest giver pristine spider silk","andromath quest","кто дает безупречную паутину","персонаж, выдающий задание безупречная паутина","задание андромата"}},{q="Где собирают паутину?",a="Шелк собирают у пауков-падальщиков, обитающих в призрачных лесах и затянутых паутиной прогалинах Сумеречного леса.",al={"where do i get pristine silk","spider location","carrion recluse location","где взять безупречную паутину","где пауки","где паук-падальщик"}},{q="Кто изготавливает одеяние из шелка?",a="Ткачеством и пошивом занимается Уинн Ларсон, профессиональный портной, работающая в магазине Ларсона в Квартале магов Штормграда.",al={"who weaves the silk","wynne larson","larson clothiers","кто ткет шелк","уинн ларсон","магазин ларсона"}},{q="Почему маги используют паутину для одеяний?",a="Безупречная паутина обладает природной прочностью и исключительно тонким плетением, позволяя создавать легкую ткань, способную удерживать тонкие чары и не обременять чародея.",al={"why spider silk","spider silk magic robes","почему паутина","магические одеяния из паутины"}},{q="Что происходит после доставки паутины?",a="Осмотрев шелк и поработав за станком, Уинн вручает магу готовое Одеяние волшебного плетения.",al={"next quest after pristine spider silk","what happens next","следующее задание после безупречной паутины","что дальше"}},{q="Подойдет ли любая паутина из Сумеречного леса?",a="Нет. Для тонких чар, вплетаемых в магазине Ларсона, нужны именно безупречные образцы, осторожно добытые у пауков-падальщиков; грубая паутина не принимается.",al={"can i use regular spider silk","pristine vs normal silk","можно ли обычную паутину","безупречная или обычная паутина"}}},fp="20,381,22.460.0,20.400.0,35.146.0,28.117.0,34.131.0,42.185.0,37.113.0,44.163.0"}
P.entries["quest:1941"] = {n="Одеяние из ткани маны",s="Одеяние из ткани маны завершает масштабный заказ портного в самом сердце Штормграда. Уинн Ларсон представляет готовое зачарованное облачение из тонких материалов — гордую витрину семейной лавки. Для начинающих заклинателей оно служит первым знаком преданности тайным искусствам и качества человеческого мастерства.",h="Одеяние из ткани маны завершает масштабный заказ портного в самом сердце Штормграда.",kw={"apprentice robe","clothier","larson clothiers","mage quarter","manaweave robe","stormwind","tailor","wynne larson","одеяние ученика","портной","одежда ларсон","квартал магов","одеяние из ткани маны","штормград","портняжное дело","уинн ларсон"},ang={["class:Mage"]="Для ученика мага, постигающего науку в башнях Штормграда, пошитое одеяние из ткани маны означает переход к серьезным полевым исследованиям и самостоятельному колдовству.",["faction:Alliance"]="Снаряжение многообещающих героев из местных лавок столицы укрепляет престиж и самодостаточность Штормграда в неспокойных землях.",["profession:Tailoring"]="Работа Уинн Ларсон показывает высокий уровень человеческого портновского мастерства: как обычные материалы можно соткать так, чтобы направлять и усмирять неустойчивую тайную силу."},sec={{t="Одежда Ларсон",b="В шумном Квартале магов Штормграда лавка «Одежда Ларсон» обслуживает владеющих тайными искусствами, которым нужны наряды для направления неустойчивых энергий. Создание тонких волшебных облачений требует редких материалов, тщательного шитья и острого глаза к нитям, которые не распустятся от магического резонанса. Уинн Ларсон лично гордится каждой вещью, покидающей ее лавку, и считает каждое одеяние, надетое в походе, живым свидетельством имени Ларсон."},{t="Тканое колдовство",b="Одеяние из ткани маны создано для помощи ученикам магов: удобство, подвижность и практичная прочность, нужные в спорных землях. Когда все необходимые компоненты доставлены, Уинн сама делает последний стежок и представляет вещь не как простую сделку, а как шедевр, который должен привлекать взгляды и рекламировать портновское мастерство Ларсон по всему королевству."}},faq={{q="Кто создает Одеяние из ткани маны?",a="Уинн Ларсон создает это одеяние в лавке «Одежда Ларсон» в Квартале магов Штормграда.",al={"who makes manaweave robe","wynne larson robe","larson clothiers","кто делает одеяние из ткани маны","уинн ларсон одеяние","одежда ларсон"}},{q="Почему Уинн Ларсон хочет, чтобы вы носили одеяние с гордостью?",a="Уинн считает это одеяние одним из лучших своих творений. Она просит искателей приключений рассказывать об «Одежде Ларсон», когда другие восхищаются работой, — так они служат живой рекламой ее лавки.",al={"why tell people larson","larson advertising","wynne dialogue","зачем рассказывать про ларсон","реклама ларсон","диалог уинн"}},{q="Где находится лавка «Одежда Ларсон»?",a="Лавка находится в Квартале магов Штормграда, рядом с академиями и святилищами, где собираются заклинатели Альянса.",al={"larson shop location","where is wynne larson","mage quarter tailoring shop","где лавка ларсон","где уинн ларсон","портной в квартале магов"}},{q="Что за одежда — Одеяние из ткани маны?",a="Это зачарованное тканевое одеяние для практикующих магию: оно сшито для направления тайных энергий и удобно в опасных путешествиях.",al={"manaweave robe lore","what is manaweave robe","what does the robe do","одеяние из ткани маны предания","что такое одеяние из ткани маны","что делает одеяние"}},{q="Это часть длинной цепочки заданий?",a="Да, выполнение этого заказа — последний шаг цепочки заданий портного, в которой вы помогаете Уинн Ларсон с материалами для ее работы.",al={"manaweave chain","robe quest chain","questline end","цепочка ткани маны","цепочка заданий одеяния","конец цепочки"}},{q="Какая фракция может взять это задание?",a="Задание предназначено только для Альянса, так как Уинн Ларсон работает целиком в столице — Штормграде.",al={"alliance or horde robe","can horde get manaweave robe","faction requirement","альянс или орда одеяние","может ли орда получить одеяние из ткани маны","требование фракции"}}},fp="14,347,16.468.0,13.412.0,30.95.0,59.208.0,34.134.0,41.159.0,35.135.0,38.123.0"}
P.entries["quest:1942"] = {n="Одеяние волшебного плетения",s="Одеяние волшебного плетения — итог целеустремленной работы в Штормграде. Добыв в диких землях редкий паучий шелк, искатель приключений приносит его искусной портнихе Уинн Ларсон. Результат — тонкая волшебная ткань, пригодная и для опасных странствий, и для светских приемов.",h="Одеяние волшебного плетения — итог целеустремленной работы в Штормграде.",kw={"astral knot garment","cloth armor","mage quarter","pristine spider silk","silk robe","stormwind","tailoring","wynne larson","одеяние волшебного плетения","тканевая броня","квартал магов","чистый паучий шелк","шелковое одеяние","штормград","портняжное дело","уинн ларсон"},ang={["class:Mage"]="Одеяние волшебного плетения сочетает тайное достоинство Квартала магов Штормграда с практичными чарами, нужными в пути за укрепленными стенами королевства.",["faction:Alliance"]="Ремесленники Штормграда гордятся тем, что снабжают героев Альянса снаряжением, пригодным и для королевских залов, и для опасных передовых.",["profession:Tailoring"]="Работа Уинн Ларсон — вершина обращения с чистым паучьим шелком: она показывает, как сырье из чудовищ превращается в великолепную моду."},sec={{t="Остроумие ткача",b="В шумном Квартале магов Штормграда портные и швеи обслуживают тайную элиту и приезжую знать. Уинн Ларсон — одна из таких мастериц, известная умением превращать чистый паучий шелк в прочные зачарованные облачения. Известная своим игривым чувством юмора, она шутит, что оставляет лишние обрезки драгоценного шелка для своего гардероба, прежде чем отдать искусно сшитую вещь."},{t="Универсальная элегантность",b="Одеяние волшебного плетения ценят заклинатели, носящие ткань, которым нужны и прочность, и изящество. Сотканное из тонкого, но стойкого шелка опасных паукообразных, оно рассчитано на тяготы боя и при этом сохраняет безупречный вид, ожидаемый на торжественных банкетах в Крепости Штормграда."}},faq={{q="Что такое Одеяние волшебного плетения?",a="Это искусно сшитое одеяние, созданное Уинн Ларсон в Штормграде. Оно сделано из чистого паучьего шелка и предназначено для носящих ткань заклинателей — и в приключениях, и на светских приемах.",al={"what is astral knot garment","astral knot robe","astral knot vestments","что такое одеяние волшебного плетения","мантия волшебного плетения","облачение волшебного плетения"}},{q="Кто создает Одеяние волшебного плетения?",a="Уинн Ларсон, портная из Квартала магов Штормграда, создает эту вещь, получив необходимые редкие материалы.",al={"who makes astral knot","wynne larson quest","astral knot tailor","кто делает волшебное плетение","задание уинн ларсон","портной волшебного плетения"}},{q="Какие материалы нужны для этого одеяния?",a="Нужен чистый паучий шелк, добытый у смертоносных пауков в диких землях мира; его сплетают приемами, сохраняющими природную прочность шелка и его способность к зачарованию.",al={"materials for astral knot","spider silk needed","how is it made","материалы для волшебного плетения","нужен паучий шелк","как это делается"}},{q="Почему Уинн Ларсон шутит, что оставляет лишний шелк себе?",a="Чистый паучий шелк исключительно редок и ценится среди портных. Уинн шутит, что сшила вещь покороче, чтобы припрятать обрезки, но готовую работу отдает полностью.",al={"did she steal my silk","wynne larson joke","short robe","украла ли она мой шелк","шутка уинн ларсон","короткое одеяние"}},{q="Где в Штормграде происходит это шитье?",a="Уинн Ларсон находится в Квартале магов Штормграда — районе ученых, магов и портных, разбирающихся в зачарованных тканях.",al={"where is wynne larson","astral knot location","where to turn in astral knot","где уинн ларсон","где волшебное плетение","куда сдавать волшебное плетение"}},{q="Кто обычно носит Одеяние волшебного плетения?",a="Маги Альянса получают это одеяние и предпочитают его за легкое защитное плетение и достойный вид.",al={"who uses astral knot","what class is this for","who wears it","кто носит волшебное плетение","для какого класса","кто носит"}}},fp="19,317,14.408.0,18.327.0,32.228.0,35.136.0,53.212.0,56.207.0,50.158.0,44.99.0"}
P.entries["quest:1944"] = {n="Воды Ксавиана",s="«Воды Ксавиана» — задание мага Орды от Дейно в Оргриммаре. Желая проникнуть в древние тайны эльфов, она поручает ученику отправиться в руины Ксавиана в Ясеневом лесу и набрать пробу из самого высокого водопада.",h="«Воды Ксавиана» — задание мага Орды от Дейно в Оргриммаре.",kw={"ashenvale","deino","flask","mage quest","orgrimmar","satyr","splintertree","waters of xavian","xavian","ясеневый лес","дейно","фляга","задание мага","оргриммар","сатир","застава расщепленного дерева","воды ксавиана","ксавиан"},ang={["class:Mage"]="Это задание — особый обряд обучения для магов Орды, проверяющий их способность выходить во враждебные дебри за неукрощенными тайными реагентами.",["faction:Horde"]="Застава Расщепленного Дерева — ближайший опорный пункт Орды в восточной части Ясеневого леса для вылазок в кишащие сатирами земли вокруг Ксавиана."},sec={{t="Любопытство мага",b="В темных расщелинах Аллеи Духов тролльша-маг Дейно ищет по всему Калимдору остатки первозданной тайной энергии. Ее взгляд обращается к Ксавиану — древнему городу ночных эльфов, скрытому в восточных кронах Ясеневого леса. Ученые легенды гласят, что до Раскола город был полон магических знаний, а его воды хранят мощные тайные свойства, которые современные заклинатели жаждут изучить."},{t="Руины Ксавиана",b="Добраться до источника этих вод непросто. Ксавиан больше не принадлежит мирным эльфийским мудрецам: он лежит в руинах и захвачен одичавшими, оскверненными сатирами, яростно оберегающими свои земли от чужаков. Любопытным магам приходится миновать Сатирнаар и пробираться по опасным водам, избегая и бродящих зверей, и демонических стражей, чтобы наполнить флягу Дейно у подножия высокого водопада города."}},faq={{q="Кто такая Дейно?",a="Дейно — тролльша-маг, наставница и ученая из Аллеи Духов в Оргриммаре. Она обучает магов Орды и изучает реликвии древней магии Калимдора.",al={"who gives waters of xavian","deino orgrimmar","кто дает воды ксавиана","дейно оргриммар"}},{q="Где находится Ксавиан?",a="Ксавиан — древний разрушенный город на северо-востоке Ясеневого леса, к северу от Заставы Расщепленного Дерева и чуть северо-западнее оплота сатиров Сатирнаар.",al={"xavian location","where is xavian","finding xavian","где ксавиан","местонахождение ксавиана","поиск ксавиана"}},{q="Зачем Дейно эта вода?",a="Ученые рассказы гласят, что Ксавиан хранил огромные магические знания, а его воды, как считается, сохраняют остаточную тайную силу. Дейно хочет свежую пробу из источника водопада, чтобы изучить ее свойства.",al={"why get xavian water","purpose of xavian water","зачем вода ксавиана","для чего вода ксавиана"}},{q="Какие опасности охраняют руины Ксавиана?",a="Руины кишат сатирами — демоническими, оскверненными существами, которые ненавидят чужаков и яростно охраняют свои земли от любопытных магов.",al={"xavian enemies","who controls xavian","враги ксавиана","кто правит ксавианом"}},{q="Где именно набирают пробу воды?",a="Пробу нужно зачерпнуть флягой Дейно из водоема у самого подножия высочайшего водопада в руинах Ксавиана.",al={"waterfall location","where to fill flask","xavian waterfall","где водопад","где наполнить флягу","водопад ксавиана"}},{q="Что будет после возвращения пробы Дейно?",a="Довольная пробой воды, Дейно отправляет мага на следующий этап изучения, связанный с дриадами Ясеневого леса, — задание «Смеющиеся сестры».",al={"waters of xavian followup","next quest after waters of xavian","продолжение вод ксавиана","следующее задание после вод ксавиана"}}},fp="16,230,18.440.0,19.426.0,13.165.0,24.152.0,31.207.0,39.147.0,44.129.0,52.147.1"}
P.entries["quest:1945"] = {n="Смеющиеся сестры",s="«Смеющиеся сестры» — задание Орды, которое отправляет магов в самое сердце Ясеневого леса за зачарованными прядями волос диких дриад. Материал предназначен для Кил'халы, опытной портнихи-тролля на Перекрестке, которая сплетет из него усиленное одеяние мага. Охота на дочерей Кенария подчеркивает неослабевающую вражду между заклинателями Орды и местными защитниками древнего леса.",h="«Смеющиеся сестры» — задание Орды, которое отправляет магов в самое сердце Ясеневого леса за зачарованными...",kw={"ashenvale","crossroads","deino","dryad","hair","kil'hala","laughing sisters","raynewood","warlock robe","ясеневый лес","перекресток","дейно","дриада","волосы","кил'хала","смеющиеся сестры","ночные леса","одеяние мага"},ang={["class:Mage"]="Этот обряд посвящения учит начинающих магов, что даже священных лесных духов Ясеневого леса можно использовать как источник материалов для тайного ремесла.",["faction:Horde"]="Уничтожение дриад Ясеневого леса обостряет конфликт между экспансией Орды и священными хранителями леса, подчиняющимися ночным эльфам.",["profession:Tailoring"]="Задание показывает редкое искусство вплетения живых магических волокон в тканую броню — высокую технику, которую Кил'хала применяет на Перекрестке."},sec={{t="Плетение тайной магии",b="После того как начинающие маги раздобыли оскверненную воду у Ксавиана, Дейно в Оргриммаре направляет их помочь в создании собственных зачарованных облачений. Тайное портняжное дело такого рода требует материалов, наполненных чистой магической сущностью. Волосы дриад, естественно пронизанные первозданной жизненной силой леса, обладают нужными свойствами, чтобы вплести их в сложные магические одеяния, способные защищать и усиливать силы заклинателя."},{t="Охота у Приюта в Ночных Лесах",b="Чтобы добыть эти пряди, магам предстоит отправиться на юг, к Приюту в Ночных Лесах в Ясеневом лесу. Смеющиеся сестры — ловкие лесные дриады, союзницы ночных эльфов, — яростно охраняют эти рощи от наступающих дровосеков и чужаков. Поскольку эти лесные духи никогда не отдадут свои волосы заклинателям Орды добровольно, добыча неизбежно оплачивается кровью под сенью древних деревьев."},{t="Право Ткача",b="Собранные пряди относят на юг, через границу, в пыльное поселение Перекресток в Степях. Там портниха-тролль Кил'хала принимает эту дань без сожаления. Слегка иронично признавая утрату лесных созданий, Кил'хала не медлит и пускает зачарованные нити в дело, понимая, что власть в Орде часто требует непреклонной решимости."}},faq={{q="Кто выдает задание на охоту на Смеющихся сестер?",a="Дейно, маг-тролль из Приюта Темного Шиповника в Оргриммаре, посылает магов с этим поручением как награду и подготовку к созданию их классовых одеяний.",al={"who gives laughing sisters quest","laughing sisters quest giver","deino quest","кто выдает задание смеющиеся сестры","персонаж, выдающий задание смеющиеся сестры","задание дейно"}},{q="Кто такие смеющиеся сестры?",a="Смеющиеся сестры — дриады, дочери полубога Кенария. Верхняя половина тела у них, как у ночных эльфиек, а нижняя — как у фавнов; они защищают леса и священные поляны Ясеневого леса.",al={"what is a laughing sister","laughing sister dryad","are laughing sisters dryads","кто такие смеющиеся сестры","смеющаяся сестра дриада","смеющиеся сестры дриады ли"}},{q="Где можно найти смеющихся сестер?",a="Они бродят по лесистым местностям близ Приюта в Ночных Лесах и поляны Смеющихся сестер в центре Ясеневого леса, неподалеку от торгового тракта.",al={"laughing sisters location","where are laughing sisters","where to find laughing sisters","смеющиеся сестры расположение","где смеющиеся сестры","где найти смеющихся сестер"}},{q="Зачем Кил'хале волосы дриад?",a="Волосы дриад пропитаны природным волшебством, что делает их идеальной нитью, из которой Кил'хала ткет особые, магически созвучные одеяния для тайных искусств.",al={"why dryad hair","why laughing sister hair","what is the hair for","зачем волосы дриад","зачем волосы смеющихся сестер","для чего волосы"}},{q="Куда доставить волосы после сбора?",a="Доставьте волосы Кил'хале, искусной портнихе на оживленном форпосте Перекресток в Степях.",al={"where is kilhala","turn in laughing sisters","crossroads tailor warlock","где кил'хала","сдать смеющиеся сестры","портниха перекресток"}},{q="Что происходит после того, как Кил'хала берет волосы?",a="Получив волосы, Кил'хала ненадолго занимается материалом, а затем предлагает следующее задание — «Одеяние из кружева Пустоты», — чтобы завершить одеяние.",al={"next quest after laughing sisters","after laughing sisters","nether lace garment follow up","следующее задание после смеющиеся сестры","после смеющихся сестер","одеяние из кружева пустоты продолжение"}}},fp="16,400,18.441.0,18.412.0,24.410.0,51.141.0,30.199.0,40.135.0,34.164.0,49.117.0,43.160.0"}
P.entries["quest:1946"] = {n="Одеяние из кружева Пустоты",s="«Одеяние из кружева Пустоты» завершает особую работу портнихи Кил'халы в Степях. Вплетая собранные волосы дриад в тонкую ткань, портниха создает зачарованное одеяние, подходящее для заклинателей.",h="«Одеяние из кружева Пустоты» завершает особую работу портнихи Кил'халы в Степях.",kw={"ashenvale","barrens","crossroads","deino","kil'hala","laughing sisters","mage","nether-lace","ясеневый лес","степи","перекресток","дейно","кил'хала","смеющиеся сестры","маг","кружево пустоты"},ang={["class:Mage"]="Одеяние из кружева Пустоты служит важной вехой для растущих магов, соединяя испытания в глуши Ясеневого леса с мастерством Кил'халы под руководством Дейно.",["faction:Horde"]="Добыча компонентов в священных лесах Калимдора для снаряжения заклинателей Орды показывает непрекращающееся противостояние между Ордой и лесными защитниками Ясеневого леса.",["profession:Tailoring"]="Работа Кил'халы показывает, как экзотические реагенты вроде волос дриад можно превратить в ткани со встроенной магической защитой."},sec={{t="Плетение кружева Пустоты",b="Кил'хала, работающая на Перекрестке в Степях, берется за тонкий процесс изготовления кружева Пустоты. Для него нужны редкие, магически созвучные компоненты — а именно пряди, добытые у дриад, известных как смеющиеся сестры в Ясеневом лесу, — и портниха вплетает природное волшебство леса прямо в удобную, прочную ткань."},{t="Услуги для Оргриммара",b="Помимо простой работы по ремеслу, у Кил'халы есть личные причины заботиться о качестве одеяния. Он особенно стремится заслужить расположение Дейно, уважаемого мага-тролля, живущего в Аллее Духов в Оргриммаре. Создавая превосходные одеяния для начинающих заклинателей, Кил'хала надеется заручиться благосклонностью Дейно и сохранить ее."}},faq={{q="Что такое кружево Пустоты?",a="Кружево Пустоты — зачарованная ткань, изготовленная Кил'халой. Она соткана из магических материалов, а именно из прядей смеющихся сестер, поэтому прочна и от природы наполнена тайным созвучием.",al={"nether lace cloth","what is nether lace garment","кружево пустоты ткань","что такое одеяние из кружева пустоты"}},{q="Кто изготавливает «Одеяние из кружева Пустоты»?",a="Кил'хала, умелый портной Орды, находящийся на Перекрестке в Степях, изготавливает одеяние, когда ему приносят необходимые волосы дриад из Ясеневого леса.",al={"who makes nether lace","kil hala nether lace","кто делает кружево пустоты","кил'хала кружево пустоты"}},{q="Почему Кил'хала упоминает Дейно?",a="Deino is an influential troll mage trainer residing in Orgrimmar's Valley of Spirits. Kil'hala is eager to stay on her good side and hopes your satisfaction with his tailoring will reflect favorably upon him.",al={"who is deino","why mention deino","кто такой дейно","почему упоминает дейно"}},{q="Откуда взялись материалы для одеяния?",a="Основной материал — волосы смеющихся сестер, неуловимых дриад, обитающих в чащах Ясеневого леса.",al={"nether lace materials","dryad hair cloth","материалы кружева пустоты","ткань из волос дриад"}},{q="Для кого предназначено это одеяние?",a="Оно изготовлено в первую очередь для заклинателей, особенно для обучающихся магов, которым нужны одеяния, направляющие тайную энергию и не стесняющие движений.",al={"who uses nether lace garment","nether lace class","кто носит одеяние из кружева пустоты","кружево пустоты класс"}},{q="Где находится Кил'хала?",a="Кил'хала живет на Перекрестке — главном поселении в сердце Степей, стоящем на пересечении дорог.",al={"kil hala location","where is kil hala","кил'хала расположение","где кил'хала"}}},fp="19,223,23.343.0,20.351.0,20.207.0,35.155.0,32.208.0,50.126.0,29.151.0,26.107.0"}
P.entries["quest:1950"] = {n="Волшебное слово",s="Волхв Тирт запер важную книгу заклинаний в магически запечатанном сундуке, но не может вспомнить слово, которое его открывает. Чтобы достать том, вы должны найти его пропавшего ученика где-то у трассы на Мерцающей равнине и вытянуть из него забытые слова.",h="Волхв Тирт запер важную книгу заклинаний в магически запечатанном сундуке, но не может вспомнить слово...",kw={"get the scoop","johnson","magus tirth","mirage raceway","shimmering flats","strongbox","thousand needles","wand quest","волшебное слово","джонсон","волхв тирт","виражи на миражах","мерцающая равнина","сундук","тысяча игл","задание на палочку"},ang={["class:Mage"]="Общение с Тиртом дает забавный, но поучительный взгляд на опасности превращений и рассеянность, которая может поражать могущественных ученых."},sec={{t="Волхв и его память",b="Волхв Тирт — эксцентричный заклинатель, живущий на растрескавшемся соляном дне Мерцающей равнины в Тысяче Игл. Он обладает тайными знаниями и книгами, которых отчаянно ищут растущие маги, но иметь с ним дело приходится терпеливо. Тирт сильно полагается на помощника в бытовых мелочах, включая произносимые пароли к его тайным хранилищам. Получив поручение достать книгу силы, посетители быстро узнают, что Тирт запер том за магическими словами, которые совершенно выскользнули из его памяти."},{t="Куриная напасть",b="Найти ученика Тирта, Джонсона, не так просто, как побродить по загонам Виражей на Миражах. Расспросив гоблинов и гномов, управляющих трассой, узнаешь, что Джонсон пал жертвой типичной опасности службы у взбалмошного волшебника — превращения. Проклятый хозяином в обычную курицу, Джонсон бродит по соляной равнине и не может говорить, пока проходящий путник не подойдет достаточно близко, чтобы развеять магический туман, и тогда он кудахчет недостающий пароль."}},faq={{q="Кто такой Волхв Тирт?",a="Волхв Тирт — нелюдимый волшебник-человек, живущий близ Виражей на Миражах на Мерцающей равнине в Тысяче Игл. Он владеет глубокими тайными знаниями, которых ищут маги, желающие отточить свое мастерство.",al={"tirth lore","who is magus tirth","tirth shimmer flats","предания тирт","кто такой волхв тирт","тирт мерцающая равнина"}},{q="Зачем Тирту пароль от собственного сундука?",a="Тирт запер сундук магией, используя произносимую фразу, и полагался на помощника, который помнил бытовые мелочи вроде паролей. Верный своей рассеянной натуре, он забыл слова, как только ученик исчез.",al={"why tirth forgot","tirth strongbox password","почему тирт забыл","пароль сундука тирта"}},{q="Куда делся ученик?",a="Джонсон убежал недалеко. Он бродит возле трассы к востоку от лагеря Тирта, но найти его непросто, ведь Тирт превратил его в курицу.",al={"find tirth assistant","where is apprentice johnson","johnson location","найти помощника тирта","где ученик джонсон","джонсон местонахождение"}},{q="Почему ученика превратили в курицу?",a="Тирт наложил на Джонсона проклятие, а потом забыл об этом. Узнав о судьбе помощника, Тирт смутно решает, что тот заслужил это как неблагодарный ученик.",al={"why johnson chicken","tirth polymorph apprentice","почему джонсон курица","тирт превратил ученика"}},{q="Что лежит в сундуке Тирта?",a="В магически запечатанном сундуке лежит книга с ритуалами и указаниями, необходимыми для дальнейшего обучения мага и создания магических предметов.",al={"tirth strongbox contents","what book is in the chest","содержимое сундука тирта","какая книга в сундуке"}},{q="Кто может взяться за это задание?",a="Это поручение — часть особого испытания только для магов, которым нужны особые наставления и материалы для создания мощной волшебной палочки.",al={"can non mages do get the scoop","is this quest mage only","могут ли не маги взять волшебное слово","задание только для магов"}}},fp="13,283,22.549.0,9.526.1,19.201.0,48.218.0,28.167.1,45.186.1,33.143.0,28.138.0"}
P.entries["quest:1959"] = {n="Задание Анастасии",s="«Задание Анастасии» — вызов, обращенный к начинающим магам Орды в Калимдоре и Восточных королевствах. Анастасия Хартвелл, известная чародейка из Магического квартала Подгорода, обнаружила в городе неизвестное магическое возмущение и ищет способных заклинателей для расследования.",h="«Задание Анастасии» — вызов, обращенный к начинающим магам Орды в Калимдоре и Восточных королевствах.",kw={"anastasia hartwell","cain firesong","investigate the alchemist shop","mage","magic quarter","report to anastasia","thurston xane","un'thuwa","undercity","uthel'nay","анастасия хартвелл","кейн песнь пламени","лавка алхимика","маг","магический квартал","задание анастасии","терстон ксейн","ун'тува","подгород","утел'най"},ang={["class:Mage"]="Это задание — важная веха для магов Орды: оно выводит заклинателей из региональных учебных застав и знакомит с более глубокими тайнами магии — и опасностями, — назревающими под руинами Лордерона.",["faction:Horde"]="Вызов показывает совместный обмен между Отрекшимися и всей Ордой, использующий магические таланты всех входящих рас для защиты общих интересов.",["race:Undead"]="Маги из числа Отрекшихся призваны домой, в Магический квартал Подгорода, чтобы помочь защитить свое юное королевство от невидимых тайных угроз внутри его стен."},sec={{t="Зов тайной магии",b="Слух быстро расходится среди заклинателей Орды. Учатся ли они на уступах Громового Утеса, в пыльном зное Дуротара или среди руин Лордерона, маги с достаточным талантом получают четкое указание. Тайные мастера Подгорода ощутили необъяснимое возмущение, расходящееся по их владениям, и им нужна помощь на месте."},{t="Маг Подгорода",b="Анастасия Хартвелл ведает тайными делами в Магическом квартале Подгорода. По прибытии она подтверждает тревожную новость: в подземном городе зафиксированы аномальные энергии. Поскольку природа магии совершенно неизвестна — не доказано, что она безвредна или откровенно враждебна, — ей нужен адепт, который тихо исследует ее источник, начав с Апотекариума города."}},faq={{q="Кто такая Анастасия Хартвелл?",a="Анастасия Хартвелл — маг и наставница тайных искусств из числа Отрекшихся, живущая в Магическом квартале Подгорода. Она наставляет молодых заклинателей и внимательно следит за магическими аномалиями в столице Отрекшихся.",al={"anastasia hartwell lore","who is anastasia","hartwell undercity","анастасия хартвелл предания","кто такая анастасия","хартвелл подгород"}},{q="Где находится Анастасия Хартвелл?",a="Она живет в Магическом квартале Подгорода, в северной дуге подземного города. Ее можно найти среди других наставников заклинателей и исследователей тайной магии.",al={"where is anastasia","hartwell location","anastasia undercity map","где анастасия","хартвелл расположение","анастасия подгород карта"}},{q="Почему магов из Громового Утеса или Степей вызывают в Подгород?",a="Хотя Отрекшиеся воспитывают собственных тайных специалистов, необычные магические аномалии угрожают всему присутствию Орды в Лордероне. Наставники в Калимдоре посылают своих многообещающих учеников в Подгород, чтобы помочь и получить практический опыт работы со сложными магическими явлениями.",al={"why travel to undercity","why report to anastasia","thunder bluff mage quest","зачем ехать в подгород","зачем идти к анастасии","задание магов громового утеса"}},{q="Какое возмущение расследует Анастасия?",a="Маги обнаружили необъяснимые магические колебания в городе. На момент этого вызова Анастасия Хартвелл еще не определила, враждебна ли энергия, случайна или безвредна, и потому начала осторожное расследование.",al={"what disturbance","magical disturbance undercity","what is wrong in undercity","какое возмущение","магическое возмущение подгород","что не так в подгороде"}},{q="Кто выдает это задание?",a="Этот вызов могут выдать разные наставники магов Орды, когда заклинатель набирается достаточно опыта: Утел'най в Оргриммаре, Терстон Ксейн в Громовом Утесе, Кейн Песнь Пламени в Брилле и Ун'Тува в деревне Сен'джин.",al={"who starts report to anastasia","quest starters report to anastasia","кто начинает задание анастасии","кто выдает задание анастасии"}},{q="Что происходит после доклада Анастасии?",a="Когда вы поговорите с Анастасией и получите инструктаж, она сразу направит вас глубже исследовать возмущение, начав с расследования в Апотекариуме города в задании «Лавка алхимика».",al={"next quest after report to anastasia","report to anastasia follow up","следующее задание после задания анастасии","задание анастасии продолжение"}}},fp="19,292,20.385.0,25.418.0,26.229.0,36.183.0,80.273.0,52.238.0,21.220.0,42.221.0"}
P.entries["quest:1960"] = {n="Лавка алхимика",s="«Лавка алхимика» — задание в Подгороде для магов Орды, которым поручено устранить магическую аномалию в Апотекариуме. Под руководством Анастасии Хартвелл маги выслеживают и ловят невидимых существ из чистой магической энергии, бегающих по лавке Алджернона.",h="«Лавка алхимика» — задание в Подгороде для магов Орды, которым поручено устранить магическую аномалию в...",kw={"algernon","anastasia hartwell","apothecarium","cantation of manifestation","containment coffer","magic quarter","rift spawn","undercity","алджернон","анастасия хартвелл","апотекариум","свиток заклятия проявления","ларец для удержания","магический квартал","дух разлома","подгород"},ang={["class:Mage"]="Это задание проверяет владение чистыми тайными силами: вместо грубой разрушительной мощи требуются особые заклятия проявления и сосуды для удержания.",["race:Undead"]="Хотя апотекарии Отрекшихся занимаются главным образом алхимией и созданием чумы, это задание показывает бдительность магов Подгорода, охраняющих город от магического проникновения."},sec={{t="Беспорядок в Апотекариуме",b="Подгород не понаслышке знаком с неестественными явлениями, но недавно в Апотекариуме возникла проблема исключительно магического происхождения. В алхимической лавке Алджернона обнаружили невидимых магических существ, беззвучно скользящих между кипящих котлов и ядовитых реагентов. Поняв, что в потоке магии образовалась неестественная брешь, наставница магов Подгорода Анастасия Хартвелл направляет подающих надежды учеников исследовать и обезвредить этих существ, пока не случилась катастрофа."},{t="Проявление и поимка",b="Поскольку существа невидимы и состоят целиком из необузданной тайной силы, обычные способы выслеживания бесполезны. Анастасия снабжает учеников особым Свитком заклятия Проявления, снимающим с существ невидимость, а также прочными ларцами для их удержания. Когда существа проявятся, этих нестабильных духов разлома нужно сразить и надежно запечатать в ларцах, пока они не распались дальше и не навредили работающим алхимикам."},{t="Несчастный случай или магическая атака?",b="Когда экземпляры пойманы, Анастасию начинает беспокоить их происхождение. Самопроизвольный разрыв в потоке магии — уже тревожно, но намеренная брешь означала бы согласованную магическую атаку на столицу Отрекшихся. Пойманных существ передают на изучение, чтобы выяснить, стал ли Апотекариум жертвой магической случайности или находится на передовой целенаправленной угрозы."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Анастасия Хартвелл, учитель магов, находящаяся в Магическом квартале Подгорода.",al={"quest giver","where to start","anastasia location","персонаж, выдающий задания","где начать","где найти анастасию"}},{q="Где происходит беспорядок?",a="Беспорядок сосредоточен вокруг алхимической лавки Алджернона в районе Апотекариума в Подгороде.",al={"where do i go","alchemist shop location","where is algernon","куда идти","где лавка алхимика","где алджернон"}},{q="Что за существа бродят по лавке?",a="Это духи разлома — невидимые существа из сгустков магической энергии, появившиеся из-за аномалии в местном потоке магии.",al={"what are the monsters","invisible creatures","rift spawns","что за монстры","невидимые существа","духи разлома"}},{q="Как поймать этих существ?",a="Нужно прочесть в лавке Свиток заклятия Проявления, чтобы показать духов разлома, ослабить их заклинаниями, а затем использовать ларец для удержания и заточить их внутри.",al={"how to catch them","using the coffer","how to complete","как поймать","как использовать ларец","как выполнить"}},{q="Почему Анастасия хочет поймать этих существ живыми?",a="Анастасии и ученым Подгорода нужны живые экземпляры, чтобы определить, был ли разрыв в магии естественным случайным разломом или намеренной атакой на город внешней магической силы.",al={"why capture them","containment coffers purpose","why study them","зачем ловить","зачем нужны ларцы","зачем изучать"}},{q="Могут ли выполнять это задание другие классы, кроме магов?",a="Нет, это задание входит в начальную линейку обучения, доступную только магам Орды.",al={"mage only","who can take this quest","только маг","кто может взять задание"}}},fp="30,277,33.479.0,29.435.0,27.417.1,46.109.0,33.123.0,42.144.0,33.168.0,55.195.0,43.101.0"}
P.entries["quest:1961"] = {n="Сбор материалов",s="«Сбор материалов» — обряд посвящения для начинающих магов Орды, обучающихся в Подгороде. По заданию Анастасии Хартвелл ученики отправляются в Серебряный бор, чтобы добыть тайные самоцветы у волшебников Даларана и собрать компоненты для своих первых настоящих мантий мага.",h="«Сбор материалов» — обряд посвящения для начинающих магов Орды, обучающихся в Подгороде.",kw={"ambermill","anastasia hartwell","dalaran mana gem","gathering materials","josef gregorian","linen cloth","magic quarter","spellfire robes","undercity","янтарная мельница","анастасия хартвелл","самоцвет маны даларана","сбор материалов","джозеф грегориан","льняная ткань","магический квартал","одеяние из чароткани","подгород"},ang={["class:Mage"]="Это задание — важная веха для магов Орды: они переходят от простой одежды ученика к сшитым на заказ одеяниям, в которые вплетена захваченная тайная сила.",["profession:Tailoring"]="Задание показывает, как обычную льняную ткань можно соединить с мощными самоцветами маны и создать прочную зачарованную одежду.",["race:Undead"]="Задание иллюстрирует безжалостный взгляд Отрекшихся: прежнее родство с чародеями Даларана не дает пощады, если эти живые волшебники слишком слабы, чтобы удержать Серебряный бор."},sec={{t="Обряд тайного положения",b="В магических кельях Магического квартала начинающие маги должны доказать мастерство не только в чтении заклинаний. Чтобы заслужить первое настоящее одеяние — знак их положения и личной ценности, — Анастасия Хартвелл посылает учеников добыть сырье для зачарованной ткани: отрез простого льна и набор мощных даларанских самоцветов маны."},{t="Прагматизм Отрекшихся",b="Самоцветы маны нельзя просто купить или сотворить: их нужно отнять у магов Даларана, расположившихся по всему Серебряному бору, особенно у Янтарной мельницы. Анастасия Хартвелл с холодным безразличием замечает, что хотя тайные учения Даларана близки их собственным, для сентиментальных колебаний в Подгороде нет места. По мнению Отрекшихся, если живые волшебники не способны защитить свои реликвии, они теряют и сокровища, и жизнь."},{t="Портной Магического квартала",b="Собранные ткань и самоцветы относят Джозефу Грегориану, портному из Магического квартала. Грегориан охотно признает, что у него нет магического дара, чтобы оценить чистоту зачарованных камней Даларана, но он обладает редким мастерством, позволяющим вплести их силу прямо в ткань одеяния."}},faq={{q="Для чего нужно задание «Сбор материалов»?",a="Задание служит посвящением для магов Орды. Выполнив его, маг передает портному Джозефу Грегориану нужные компоненты — лен и самоцветы маны, — чтобы тот сшил первое официальное зачарованное одеяние ученика.",al={"why do gathering materials","gathering materials quest purpose","mage robe quest undercity","зачем сбор материалов","для чего задание сбор материалов","задание мантия мага подгород"}},{q="Почему Анастасия Хартвелл посылает вас за магами Даларана?",a="У волшебников Даларана в Серебряном бору есть очищенные самоцветы маны, способные направлять мощные магические потоки. Хартвелл смотрит на этих живых магов прагматично: несмотря на общие интеллектуальные корни, слабость в бою означает, что их жизни и имущество принадлежат Отрекшимся.",al={"why kill dalaran mages","dalaran mana gems lore","why silverpine mages","зачем убивать магов даларана","самоцветы маны даларана","зачем маги серебряного бора"}},{q="Где находятся волшебники Даларана?",a="Их можно встретить в Серебряном бору: они занимают форпосты и земли к юго-востоку от Гробницы, вокруг поселения Янтарная мельница.",al={"where to find dalaran mana gems","silverpine mages location","ambermill mages","где найти самоцветы маны даларана","где маги серебряного бора","маги янтарной мельницы"}},{q="Кто такой Джозеф Грегориан?",a="Джозеф Грегориан — портной из числа Отрекшихся, работающий в Магическом квартале Подгорода. Хотя он ремесленник, а не заклинатель, он мастерски шьет зачарованные одеяния, например одеяние из чароткани.",al={"josef gregorian undercity","who is the tailor in magic quarter","gregorian tailor","джозеф грегориан подгород","кто портной в магическом квартале","портной грегориан"}},{q="Какое одеяние шьют из этих материалов?",a="Джозеф Грегориан использует лен и даларанские самоцветы маны, чтобы сшить Одеяние из чароткани — классическую одежду, отмечающую переход ученика в ряды настоящих магов.",al={"what robe do you get","spellfire robes reward","gathering materials reward robe","какое одеяние дают","награда одеяние из чароткани","награда сбор материалов одеяние"}},{q="Почему Анастасии не слишком приятно убивать магов Даларана?",a="Многие заклинатели из числа Отрекшихся, включая саму Хартвелл, при жизни обучались по даларанским традициям и разделяют сходные интеллектуальные и магические взгляды. Несмотря на это родство, выживание и необходимость берут верх над чувствами.",al={"hartwell dalaran feelings","forsaken mages vs dalaran","anastasia hartwell lore","хартвелл и даларан","отрекшиеся маги и даларан","анастасия хартвелл предания"}}},fp="19,297,25.384.0,26.464.0,31.334.0,43.208.0,57.284.0,38.149.0,23.214.0,44.158.0,67.222.0"}
P.entries["quest:1962"] = {n="Одеяние из чароткани",s="«Одеяние из чароткани» — завершающий обряд в обучении юных магов Орды в Подгороде, который проводит портной Джозеф Грегориан. Собрав редкие компоненты по всему краю, ученик получает в награду особое зачарованное облачение, свидетельствующее о растущем мастерстве в тайных искусствах.",h="«Одеяние из чароткани» — завершающий обряд в обучении юных магов Орды в Подгороде, который проводит портной...",kw={"arcane robes","gathering materials","josef gregorian","mage quest","magic quarter","spellfire robes","undercity","тайные одеяния","сбор материалов","джозеф грегориан","задание мага","магический квартал","одеяние из чароткани","подгород"},ang={["class:Mage"]="Получение этого одеяния — ранний обряд посвящения для магов Орды: они получают сшитую на заказ одежду, способную выдерживать нестабильные огненные и тайные энергии.",["profession:Tailoring"]="Задание показывает, как обычную ткань усиливают редкими реагентами, чтобы она выдерживала и усиливала мощные магические потоки.",["race:Undead"]="Заклинатели Отрекшихся в Подгороде хранят даларанскую тайную дисциплину, сочетая старые магические традиции с новым существованием среди руин Лордерона."},sec={{t="Облачение мага",b="Ученикам, постигающим тайные искусства в Лордероне, обычные плащи и простая одежда почти не помогают направлять сырые потусторонние силы и защищаться от них. Джозеф Грегориан, портной из Магического квартала Подгорода, ткет настоящее магическое облачение из особых материалов, которые собирают заклинатели Орды. Последние стежки Одеяния из чароткани означают переход ученика от простых заклинаний к состоявшемуся мастеру тайных и огненных искусств."},{t="Вплетенная сила",b="Создать одежду, способную безопасно направлять магию высокой интенсивности, — непростая задача. Для таких одеяний нужно не просто портняжное мастерство, а особые алхимические и тайные компоненты, добытые в опасных испытаниях. Когда эти припасы собраны и принесены в мастерскую Грегориана, портной тут же ткет из них одеяние, вручая будущему магу ощутимый знак статуса и защиту."}},faq={{q="Для чего нужно задание «Одеяние из чароткани»?",a="Это завершающий шаг раннего обряда магов Орды: после сбора портняжных компонентов для портного Джозефа Грегориана маг получает в награду особо зачарованное одеяние.",al={"spellfire robes purpose","what do spellfire robes do","why do this quest","зачем одеяние из чароткани","что дает одеяние из чароткани","зачем делать это задание"}},{q="Кто такой Джозеф Грегориан?",a="Джозеф Грегориан — портной из числа Отрекшихся, работающий в портняжной лавке Магического квартала Подгорода. Он шьет первую настоящую классовую одежду для новоиспеченных магов, которых к нему направляет Анастасия Хартвелл.",al={"who is josef","who makes the robe","josef gregorian undercity","кто такой джозеф","кто шьет одеяние","джозеф грегориан подгород"}},{q="Где происходит это задание?",a="Все действие происходит в Магическом квартале Подгорода, прямо в портняжной лавке Джозефа Грегориана.",al={"spellfire robes location","where to turn in spellfire robes","где одеяние из чароткани","куда сдавать одеяние из чароткани"}},{q="Почему для этого задания не нужно никуда идти и что-то делать?",a="Вся работа была выполнена в предыдущем задании — «Сбор материалов». Когда вы передаете реагенты Джозефу, он ненадолго садится за работу и сразу вручает готовое одеяние.",al={"why is it instant","how to complete spellfire robes","auto complete robe","почему мгновенно","как выполнить одеяние из чароткани","автозавершение одеяние"}},{q="Могут ли получить это одеяние другие классы, кроме магов?",a="Нет. Вся цепочка заданий и итоговое зачарованное облачение доступны только магам, союзным Орде.",al={"is this mage only","can warlock get this","who can do spellfire robes","только для магов","может ли чернокнижник получить","кто может получить одеяние из чароткани"}},{q="Какие материалы нужны для изготовления этого одеяния?",a="Одеяние шьют из редких припасов, собранных в предыдущем задании: это льняная ткань и даларанские самоцветы маны, отнятые у магов Кирин-Тора в Серебряном бору.",al={"what goes into the robe","robe ingredients","gathering materials turn in","из чего делают одеяние","ингредиенты одеяния","сдача сбора материалов"}}},fp="15,301,17.487.0,11.426.0,49.191.0,23.199.0,33.120.0,62.209.0,48.110.0,49.183.0"}
P.entries["quest:1963"] = {n="Изувеченная Длань",s="Это испытание для разбойников, которое выдает Терзок в Расселине Теней, проверяет новичков, желающих вступить в тайное общество Изувеченной Длани. Чтобы доказать свою смертоносную эффективность, начинающие разбойники должны выследить тролля-контрабандиста Тазана и завладеть его запертой сумкой.",h="Это испытание для разбойников, которое выдает Терзок в Расселине Теней, проверяет новичков, желающих вступить...",kw={"cleft of shadow","orgrimmar","ratchet","rogue","satchel","shattered hand","tazan","therzok","расселина теней","оргриммар","кабестан","разбойник","сумка","изувеченная длань","тазан","терзок"},ang={["class:Rogue"]="Этот обряд посвящает молодых разбойников Орды в ряды Изувеченной Длани, делая упор на безжалостную эффективность, убийства и полезность, а не на открытый бой.",["faction:Horde"]="Изувеченная Длань отражает внутреннее идеологическое противостояние в Оргриммаре, где тайные группировки тихо оспаривают осторожное видение Тралла для молодой Орды."},sec={{t="Тени в Расселине",b="Под шумными улицами Оргриммара лежит подземный мрак Расселины Теней. Здесь действует Изувеченная Длань — тайный орден убийц и воров, уходящий корнями в старые орочьи традиции. Пока вождь Тралл проповедует честь, дипломатию и осторожность в управлении молодой Ордой, руководство Изувеченной Длани считает, что такая нерешительность ослабляет их народ. Они стремятся вернуть военное превосходство тайным насилием, используя ножи и яд там, где может не удаться атака на поле боя."},{t="Судьба контрабандиста",b="Чтобы отсеять неуклюжих и слабых, куратор Терзок дает простое поручение: убить Тазана, тролля-отступника, действующего в Степях близ Кабестана. Тазан торговал с береговыми пиратами и владеет важными сведениями, нужными обществу. Добыв его запертую сумку, разбойник доказывает, что способен выслеживать добычу за пределами городских стен, хотя для извлечения содержимого потребуется еще больше мастерства."}},faq={{q="Что такое Изувеченная Длань в Оргриммаре?",a="Изувеченная Длань — тайное общество разбойников, разведчиков и убийц Орды, действующее из Расселины Теней в Оргриммаре. Исторически это древний орочий клан, известный жестоким самоувечьем, а в современной Орде он служит теневой сетью разведки и «мокрых дел», предпочитая безжалостный прагматизм осторожной дипломатии Тралла.",al={"who are shattered hand","shattered hand rogues","shattered hand purpose","кто такие изувеченная длань","разбойники изувеченной длани","цель изувеченной длани"}},{q="Кто такой Терзок?",a="Терзок — куратор Изувеченной Длани, расположившийся в Расселине Теней. Он испытывает будущих разбойников, проверяя, достаточно ли они хитры и смертоносны для службы обществу, и открыто скептически относится к сдержанности Тралла.",al={"therzok role","who is questgiver","therzok orgrimmar","терзок роль","кто выдает задание","терзок оргриммар"}},{q="Почему Терзок хочет смерти Тазана?",a="Тазан — тролль-контрабандист, ведущий незаконную торговлю с пиратами Южных морей близ порта Кабестан. Помимо контрабанды, Тазан носит в сумке важные сведения, которые Изувеченная Длань хочет получить для своих тайных операций.",al={"why kill tazan","tazan lore","what did tazan do","зачем убивать тазана","тазан предания","что сделал тазан"}},{q="Где находится Тазан?",a="Тазан действует в Степях, скрываясь у побережья рядом с пиратскими стоянками к югу от Кабестана.",al={"tazan location","where is tazan","find tazan","тазан местонахождение","где тазан","найти тазана"}},{q="Что происходит после того, как сумка Тазана добыта?",a="Когда сумку приносят Терзоку, оказывается, что она заперта. Терзок доволен гибелью Тазана, но ему нужны сведения внутри, и он использует ситуацию как следующее испытание умения разбойника вскрывать замки.",al={"next quest","locked satchel","what to do with satchel","следующее задание","запертая сумка","что делать с сумкой"}},{q="Знает ли Тралл о методах Изувеченной Длани?",a="Хотя Изувеченная Длань номинально служит Орде, ее члены действуют в основном из тени и презирают осторожное руководство Тралла. Они тихо развивают собственные разведсети, чтобы устранять предполагаемые угрозы раньше, чем дипломатия Вождя затормозит действия.",al={"thrall and shattered hand","does warchief approve","thrall rogues","тралл и изувеченная длань","одобряет ли вождь","тралл разбойники"}}},fp="18,266,20.505.0,17.421.1,40.345.0,15.226.0,33.250.0,23.97.0,46.211.1,52.286.0"}
P.entries["quest:1978"] = {n="Стражи смерти",s="Это поручение знаменует официальное принятие способного агента в ряды Стражей смерти — ордена убийц и шпионов Отрекшихся. Доставив Гроссбух Андрона лично Вариматрасу, посыльный приносит доказательства тайной деятельности Синдиката высшему руководству Подгорода.",h="Это поручение знаменует официальное принятие способного агента в ряды Стражей смерти — ордена убийц и шпионов...",kw={"alterac","andron's ledger","deathstalkers","hall of the dark lady","mennet carkad","syndicate","undercity","varimathras","альтерак","гроссбух андрона","стражи смерти","зал темной госпожи","меннит каркад","синдикат","подгород","вариматрас"},ang={["class:Rogue"]="Это посвящение — официальный вход в особый разбойничий кадр Отрекшихся, превращающий простых карманников в государственных агентов разведки.",["faction:Horde"]="Хотя это внутреннее дело безопасности Отрекшихся, наблюдение за человеческими остатками Альтерака защищает северные земли Орды от подрывных диверсий.",["race:Undead"]="Для Отрекшихся посвящение в Стражи смерти — прямая клятва оберегать хрупкий суверенитет Лордерона от выживших людей и затаившихся предателей."},sec={{t="Посвящение в тени",b="После того как были найдены изобличающие записи Андрона Ганта, Меннит Каркад официально принимает агента в Стражи смерти. Организация служит глазами, ушами и кинжалами леди Сильваны по всему Лордерону, полагаясь на разведывательные сети, безжалостную эффективность и скрытность, чтобы устранять угрозы до их появления. Официальное признание в ордене — важная веха для любого начинающего разбойника или разведчика в Подгороде."},{t="Связь с Синдикатом",b="Добыча этого тайного расследования — Гроссбух Андрона, раскрывающий преступные связи местных агентов с Синдикатом. Некогда благородная аристократия павшего человеческого королевства Альтерак, Синдикат после краха своего государства во Второй войне обратился к разбою и подрывной деятельности. Каркад выражает удивление и презрение тем, как низко пали бывшие лорды Альтерака, опустившиеся до мелких заговоров ради возврата власти."},{t="Аудиенция у повелителя ужаса",b="Из-за деликатности сведений книга передается лично Вариматрасу в Королевском квартале Подгорода. Командир-натрезим руководит тактической разведкой Отрекшихся при Сильване Ветрокрылой. Довольный инициативой Стражей смерти, Вариматрас приветствует способности агента, замечая, что его разведка всегда найдет применение тому, кто добивается результата."}},faq={{q="Кто такие Стражи смерти?",a="Стражи смерти — главный орден шпионажа, разведки и убийств Отрекшихся. Их штаб находится в Квартале разбойников Подгорода; они действуют по всему Лордерону, устраняя политических соперников, проникая во враждебные группировки и защищая государство Отрекшихся от внешней и внутренней подрывной деятельности.",al={"who are the deathstalkers","deathstalker lore","forsaken assassins","кто такие стражи смерти","стражи смерти предания","убийцы отрекшихся"}},{q="Почему здесь замешан Синдикат?",a="Захваченный гроссбух раскрывает тайные связи с Синдикатом — изгнанной аристократией Альтерака, перешедшей к организованному разбою. Отрекшиеся внимательно следят за остатками альтеракцев на своей территории, поскольку агенты Синдиката постоянно ищут возможность вернуть потерянные земли и грабить ресурсы на севере Лордерона.",al={"why syndicate","alterac connection","syndicate ledger","почему синдикат","связь с альтераком","гроссбух синдиката"}},{q="Почему нужно докладывать прямо Вариматрасу?",a="Вариматрас — тактический советник королевы Сильваны, отвечающий за безопасность и разведку Подгорода. Важные открытия о чужих заговорах, такие как тайные операции Синдиката, требуют рассмотрения на высшем уровне для координации широких военных и дипломатических мер.",al={"why varimathras","who is varimathras","dreadlord role","почему вариматрас","кто такой вариматрас","роль повелителя ужаса"}},{q="Кем был Меннит Каркад?",a="Меннит Каркад — старший куратор и связной Стражей смерти в Подгороде. Он руководит полевыми агентами, оценивает новичков и разбирает собранные сведения, прежде чем передать важные находки по цепочке командования.",al={"mennet carkad role","quest giver carkad","меннит каркад роль","каркад выдает задание"}},{q="Где проходит эта аудиенция?",a="Аудиенция проходит в Зале Темной Госпожи в Королевском квартале в глубине Подгорода. Вариматрас стоит рядом с королевой Сильваной Ветрокрылой в сердце власти Отрекшихся.",al={"where is varimathras","hall of the dark lady location","где вариматрас","зал темной госпожи расположение"}},{q="Что происходит после вступления в Стражи смерти?",a="Когда ваши полномочия подтверждены, а надежность доказана перед Меннитом Каркадом и Вариматрасом, вас признают доверенным полевым агентом Отрекшихся, что открывает путь к будущим заданиям по разведке и устранению в спорных землях Лордерона.",al={"deathstalker questline continuation","what next","продолжение цепочки стражей смерти","что дальше"}}},fp="17,326,26.441.0,24.431.1,27.427.0,27.311.0,30.341.0,35.327.0,22.243.0,36.206.0,45.277.0"}
P.entries["quest:199"] = {ang={["profession:Engineering"]="Инженер сразу чует опасность, осматривая летучие порошки, намеренно заложенные в точках конструкционного напряжения крупной плотины.",["race:Dwarf"]="Каменная Плотина — одно из венцов зодчества дворфов Стальгорна. Любая угроза ее целостности бьет прямо по безопасности и гордости Каз Модана.",["race:Gnome"]="Гномы ценят точность дворфийских гражданских сооружений, поэтому химическая природа этого грубого саботажа вызывает особую тревогу."},sec={{t="Подозрительная находка",b="Каменная Плотина — монументальный триумф дворфийской инженерии, сдерживающий огромные воды озера. Однако слухи о саботаже привлекли внимание к окрестному берегу. У самой воды стоит неуместная бочка со зловещим веществом — странным едким порошком, которому явно не место среди обычных материалов для обслуживания плотины."},{t="Тревога на плотине",b="Taking a sample of the unknown powder and presenting it to Chief Engineer Hinderweir VII confirms the worst fears of the Loch Modan authorities. The engineer immediately recognizes that an outside force is plotting against the dam, shifting the investigation from mere suspicion to an urgent matter of regional defense."}},faq={{q="Что за порошок со странным запахом?",a="Порошок со странным запахом из бочки — взрывчатое или алхимическое вещество, подложенное у основания Каменной Плотины. Это прямое свидетельство того, что враг замышляет разрушить или повредить великую преграду.",al={"strange powder","what is in the barrel","suspicious barrel powder","странный порошок","что в бочке","порошок из подозрительной бочки"}},{q="Who is Chief Engineer Hinderweir VII?",a="Chief Engineer Hinderweir VII is the dwarven master engineer overseeing the maintenance, integrity, and safety of the Stonewrought Dam in Loch Modan.",al={"who is hinderweir","chief engineer hinderweir","dam engineer"}},{q="Где находится подозрительная бочка?",a="Подозрительная бочка спрятана на берегу у основания Каменной Плотины на севере Лок Модана.",al={"barrel location","where is the barrel","barrel loch modan","местонахождение бочки","где бочка","бочка лок модан"}},{q="Почему целью выбрана Каменная Плотина?",a="Каменная Плотина сдерживает огромное водохранилище Лок Модана. При прорыве катастрофический паводок обрушился бы на Болотину, нарушив торговые пути Альянса и разорив дворфийские владения по всему Каз Модану.",al={"why destroy the dam","dam sabotage","threat to loch modan","зачем разрушать плотину","саботаж плотины","угроза лок модану"}},{q="Кто оставил здесь подозрительную бочку?",a="The barrel was placed by agents seeking to destabilize dwarven lands, prompting Chief Engineer Hinderweir to launch a broader investigation into who is behind the plot.",al={"who planted the barrel","saboteurs","who put the powder","кто подложил бочку","диверсанты","кто положил порошок"}},{q="Что делать после сбора порошка?",a="Take the sample directly to Chief Engineer Hinderweir VII atop the Stonewrought Dam so he can inspect the substance and prepare a response.",al={"what next","turn in powder","who to talk to","что дальше","сдать порошок","с кем поговорить"}}},fp="19,308,22.377.0,16.319.1,36.233.0,37.149.0,37.124.0,43.226.0,36.168.0,45.139.0"}
P.entries["quest:1998"] = {n="Фенвик Татрос",s="Меннит Каркад поручает перспективным разбойникам Подгорода выследить Фенвика Татроса по прямому приказу лорда Вариматраса. Татроса подозревают в организации независимых отрядов нежити на берегах Серебряного бора. Устранение Татроса доказывает Стражам смерти мужество агента и открывает путь к более сложному обучению торговому ремеслу.",h="Меннит Каркад поручает перспективным разбойникам Подгорода выследить Фенвика Татроса по прямому приказу лорда...",kw={"deathstalkers","fenwick thatros","lake lordamere","mennet carkad","rogues' quarter","silverpine forest","undercity","varimathras","стражи смерти","фенвик татрос","озеро лордамер","меннит каркад","квартал разбойников","серебряный бор","подгород","вариматрас"},ang={["class:Rogue"]="Этот контракт — проверка для разбойников Отрекшихся: он подтверждает их скрытность и смертоносность, прежде чем им доверят более тонкие инструменты ремесла Стражей смерти.",["race:Undead"]="Отрекшиеся не могут терпеть, чтобы соперничающие фракции нежити заявляли о суверенитете так близко к Столице, поэтому голова Татроса — политическая необходимость."},sec={{t="Приказ повелителя ужаса",b="В темных коридорах Квартала разбойников Меннит Каркад ведет внутренние контракты и обучение Стражей смерти — тайной разведывательной службы Отрекшихся. Когда лорд Вариматрас присылает приоритетную цель, такое задание не поручают новичкам легкомысленно. Фенвик Татрос привлек внимание повелителя ужаса, закрепившись среди мятежной нежити в Серебряном бору. Если оставить его без внимания, независимое руководство нежити может поставить под угрозу объединение Отрекшихся на прежних землях Лордерона."},{t="Ветхий причал на Лордамере",b="По данным разведки Стражей смерти, Татрос прячется не в глубоких крепостях или склепах. Разведчики обнаружили его возле ветхого причала на берегу озера Лордамер в Серебряном бору. Чтобы расправиться с ним там, нужно пройти через спорные дикие земли, где властвуют свирепые звери, гноллы-гнилошкуры и остатки Плети. Принесенная отрубленная голова — осязаемое доказательство, которого требует Вариматрас, прежде чем допустить агента к более глубоким тайным операциям."}},faq={{q="Кто такой Фенвик Татрос?",a="Фенвик Татрос — предводитель нежити, действующий на берегах озера Лордамер в Серебряном бору. В отличие от Отрекшихся, служащих леди Сильване, Татрос командует отрядами нежити, не подчиняющимися Подгороду или враждебными ему, поэтому лорд Вариматрас выбрал его для казни.",al={"fenwick lore","who is thatros","fenwick thatros background","фенвик татрос","кто такой татрос","предыстория фенвика татроса"}},{q="Почему Вариматрас хочет смерти Фенвика Татроса?",a="Вариматрас считает Татроса растущей угрозой: он может сплотить блуждающую нежить Серебряного бора против Отрекшихся. Чтобы обезопасить границы вокруг Подгорода, любых соперников, угрожающих безраздельной власти Сильваны над регионом, необходимо быстро устранять.",al={"varimathras thatros","why kill fenwick","вариматрас татрос","зачем убивать фенвика"}},{q="Кто такие Стражи смерти?",a="Стражи смерти — главная служба шпионажа, убийств и разведки Отрекшихся. Они базируются в Квартале разбойников в Подгороде и действуют по всему Лордерону: устраняют внутренние угрозы, шпионят за соперничающими фракциями и обеспечивают контроль над землями для Темной Госпожи.",al={"deathstalkers lore","what are deathstalkers","undead rogues faction","стражи смерти","кто такие стражи смерти","фракция разбойников-нежити"}},{q="Где находится Фенвик Татрос?",a="По донесениям Стражей смерти, Татрос находится возле разрушенного ветхого причала на берегу озера Лордамер в северо-восточной части Серебряного бора.",al={"where is fenwick","fenwick dock location","thatros lake lordamere","где фенвик","причал фенвика","татрос озеро лордамер"}},{q="Что дает выполнение этого задания у Стражей смерти?",a="Устранение Татроса доказывает способности агента и его преданность Менниту Каркаду и Стражам смерти. Убедившись в вашей надежности, Каркад предлагает продолжить ваше обучение теневому искусству с помощью специальных уроков ремесла.",al={"fenwick reward lore","what comes after fenwick","награда за фенвика","что после фенвика"}},{q="Кто такой Меннит Каркад?",a="Меннит Каркад — учитель разбойников и куратор Стражей смерти в Квартале разбойников Подгорода. Он руководит полевыми агентами и поручает задания, напрямую связанные с безопасностью державы Отрекшихся.",al={"mennet carkad","who gives fenwick quest","меннит каркад","кто выдает задание про фенвика"}}},fp="15,348,28.525.0,30.480.0,23.290.0,47.256.0,26.279.0,33.129.0,62.236.0,21.206.0"}
P.entries["quest:2"] = {n="Коготь гиппогрифа Острокогтя",s="«Коготь гиппогрифа Острокогтя» — трофейное задание о победе над свирепым гиппогрифом Острым Когтем в Ясеневом лесу. Отнесите отрубленный коготь Сенани Громовое Сердце на Заставу Расщепленного Дерева — это докажет ваше мастерство и защитит снабжение Орды в древнем лесу.",h="«Коготь гиппогрифа Острокогтя» — трофейное задание о победе над свирепым гиппогрифом Острым Когтем в Ясеневом...",kw={"ashenvale","ashenvale hunt","hippogryph","peons","senani thunderheart","sharptalon","splintertree post","warsong","ясеневый лес","большая охота","гиппогриф","пеоны","сенани громовое сердце","острый коготь","застава расщепленного дерева","песнь войны"},ang={["class:Hunter"]="Победа над легендарным воздушным хищником вроде Острого Когтя — высшее испытание в выслеживании и меткости под густыми кронами Ясеневого леса.",["faction:Horde"]="Победа над Острым Когтем обеспечивает безопасные тропы для лесозаготовок Песни Войны и защищает беззащитных пеонов, ходящих между дальними заставами и Заставой Расщепленного Дерева.",["race:Orc"]="Избавление леса от воздушных ужасов облегчает тяжелую лесозаготовительную кампанию клана Песни Войны.",["race:Tauren"]="Следование обрядам охоты под руководством Сенани Громовое Сердце отражает традиционное почтение тауренов к испытанию себя в схватке с самыми свирепыми зверями природы."},sec={{t="Бич лесных троп",b="Пока Орда пытается добыть ресурсы в Ясеневом лесу, местная фауна оказывается не менее опасной, чем стражи ночных эльфов. Острый Коготь, печально известный агрессивный гиппогриф, терроризировал кроны деревьев и тропы к Заставе Расщепленного Дерева. Зверь нападал на беззащитных пеонов и посыльных, ходивших между дальними лесозаготовительными лагерями и заставой, серьезно мешая действиям Орды в регионе."},{t="Доказательство охоты",b="Под руководством таурена-охотницы Сенани Громовое Сердце охотники Орды очищают подкроновые земли Ясеневого леса от самых опасных хищников. Отрубленный огромный коготь Острого Когтя — неопровержимое доказательство гибели небесного ужаса. Доставка трофея на Заставу Расщепленного Дерева приносит почет среди защитников заставы и облегчение напуганным работникам, которым приходится ходить по лесу."}},faq={{q="Кто такой Острый Коготь?",a="Острый Коготь — именной хищный гиппогриф, обитающий в Ясеневом лесу. Известный свирепостью, он беспощадно устраивал засады на путников в древних лесах.",al={"who is sharptalon","sharptalon mob","what kind of beast is sharptalon","кто такой острый коготь","острый коготь моб","что за зверь острый коготь"}},{q="Зачем Сенани Громовое Сердце нужен коготь?",a="Сенани Громовое Сердце руководит Большой охотой с Заставы Расщепленного Дерева. Коготь служит вещественным доказательством того, что крупный хищник, угрожавший работникам и путям снабжения Орды, уничтожен.",al={"why turn in claw","senani thunderheart trophy","purpose of sharptalon's claw","зачем сдавать коготь","трофей сенани громовое сердце","для чего коготь гиппогрифа острокогтя"}},{q="Куда сдавать «Коготь гиппогрифа Острокогтя»?",a="Коготь сдают Сенани Громовое Сердце — таурену на Заставе Расщепленного Дерева в восточной части Ясеневого леса.",al={"where turn in","who takes the claw","claw hand in location","куда сдать","кто принимает коготь","где сдать коготь"}},{q="Чем убийство Острого Когтя помогает Орде?",a="Острый Коготь регулярно нападал на пеонов, ходивших между дальними лесопилками и Заставой Расщепленного Дерева. Гибель зверя делает перевозку припасов, древесины и гонцов безопаснее.",al={"why kill sharptalon lore","horde interest in sharptalon","зачем убивать острого когтя","интерес орды к острому когтю"}},{q="Входит ли это задание в более длинную цепочку?",a="Да. Оно входит в «Большую охоту» — серию испытаний на выслеживание зверей от Сенани Громовое Сердце, которая завершается заданием «Завершение охоты».",al={"ashenvale hunt chain","quest chain sharptalon","цепочка большая охота","цепочка заданий острый коготь"}},{q="Кто такая Сенани Громовое Сердце?",a="Сенани Громовое Сердце — таурен-охотница на Заставе Расщепленного Дерева, которая следит за равновесием леса и проверяет мужество охотников Орды в схватках с самыми опасными существами Ясеневого леса.",al={"senani lore","who is senani","сенани","кто такая сенани"}}},fp="17,275,30.407.0,17.424.0,19.162.0,43.195.0,37.104.0,43.178.0,37.146.0,27.194.0"}
P.entries["quest:20"] = {n="Угроза Черной горы",s="Маршал Маррис из Приозерья поручает искателям приключений сократить число агрессивных орков Черной горы, вторгшихся в Красногорье. Забрав их потрепанные в боях топоры, защитники города надеются прорвать осаду, сжимающуюся вокруг поселения.",h="Маршал Маррис из Приозерья поручает искателям приключений сократить число агрессивных орков Черной горы...",ang={["class:Warrior"]="Схватка щит в щит с закаленными налетчиками Черной горы — суровое испытание воинской дисциплины и стойкости на передовой.",["faction:Alliance"]="Оборона Приозерья крайне важна для удержания южной границы королевства Штормград против давних врагов.",["race:Human"]="Клан Черной горы разрушил первоначальное Королевство Штормград в Первую войну; новая встреча с ним в Красногорье вызывает горькую историческую скорбь."},sec={{t="Осажденный город",b="Приозерье оказалось в кольце сразу с нескольких сторон, но ни одна угроза не так страшна, как орки Черной горы, хлынувшие из Пылающих степей. Продвинувшись на юг в Красногорье, эти ветераны-налетчики захватили укрепления и бродят по скалистым перевалам. Из-за них жители фактически заперты в поселении, а торговля, сбор припасов и путешествия по северным дорогам прекращены."},{t="Удар по авангарду",b="Marshal Marris, commander of the beleaguered Lakeshire guard, cannot spare a detachment to assault their positions outright. Instead, he enlists roaming adventurers to bleed the invaders' forward scouts and foot soldiers. By demanding their crude, battleworn axes as proof of death, Marris seeks to thin the invaders' numbers both around Stonewatch to the north and in the rugged pockets of southeastern Redridge."}},faq={{q="Откуда пришли эти орки Черной горы?",a="Они двинулись на юг через зубчатые горные перевалы из Пылающих степей, своего исконного оплота вокруг Черной горы.",al={"where are the orcs from","blackrock invasion redridge","why are orcs in redridge","откуда орки","вторжение черной горы в красногорье","почему орки в красногорье"}},{q="Кто дает это задание?",a="Маршал Маррис — старший офицер, отвечающий за оборону Приозерья и поддержание порядка в условиях растущего окружения города.",al={"who gives blackrock menace","blackrock menace quest giver","marshal marris quest","кто дает угрозу черной горы","угроза черной горы персонаж, выдающий задание","задание маршала марриса"}},{q="Где можно найти захватчиков из Черной горы?",a="Они занимают северные нагорья вокруг Крепости Каменной Стражи, а также закрепились в юго-восточной части Красногорья.",al={"where are blackrock orcs","battleworn axe locations","redridge orc camps","где орки черной горы","где добыть потрепанные топоры","лагеря орков в красногорье"}},{q="Почему маршал Маррис просит потрепанные в боях топоры?",a="Потрепанные в боях топоры служат неоспоримым вещественным доказательством того, что искатель приключений вступил в бой и убил налетчиков Черной горы, угрожающих долине.",al={"why axes","proof of death","battleworn axe purpose","зачем топоры","доказательство убийства","для чего топоры"}},{q="Что будет после разгрома этих разведчиков?",a="Сокращение авангарда побуждает маршала Марриса приказать нанести удар по местному предводителю Черной горы, засевшему в горах, — Тарил'зуну.",al={"what comes after blackrock menace","next quest after blackrock menace","who leads the orcs","что после угрозы черной горы","следующее задание после угрозы черной горы","кто ведет орков"}},{q="Связаны ли эти орки с Ордой Тралла?",a="Нет. Клан Черной горы, действующий здесь, состоит из остатков Старой Орды, яростно враждебных Альянсу и действующих независимо от новой Орды Тралла в Калимдоре.",al={"are these horde orcs","is blackrock clan part of thrall horde","friendly orcs in redridge","это орки орды","клан черной горы часть орды тралла","дружелюбные орки в красногорье"}}},fp="16,228,18.405.0,21.413.0,41.142.0,21.135.0,42.147.0,48.154.0,45.136.1,44.183.0"}
P.entries["quest:2038"] = {n="Пропавшее снаряжение Бинглза",s="Потерпев крушение на своем гирокоптере в водах озера Лок, эксцентричный гном-инженер Бинглз Покрышкинс подвергся нападению местных троггов, которые похитили его необходимое снаряжение. Застряв на юго-восточном берегу озера, он нуждается в возвращении украденных гаечного ключа, отвертки, молотка и особых взрывчатых зарядов Бластенхаймера, чтобы починить свою машину и вернуться к борьбе за Гномреган.",h="Потерпев крушение на своем гирокоптере в водах озера Лок, эксцентричный гном-инженер Бинглз Покрышкинс...",kw={"bingles","blastencapper","blastenheimer","gnomeregan","gyrocopter","hammer","loch modan","screwdriver","the loch","trogg","wrench","бинглз","бластенхаймер","взрывчатка бластенхаймера","гномреган","гирокоптер","молоток","лок модан","отвертка","озеро лок","трогг","гаечный ключ"},ang={["faction:Alliance"]="Помощь пилоту Альянса в самом сердце Лок Модана обеспечивает безопасность водных путей и помогает общим стратегическим усилиям по возвращению утраченных земель Каз Модана.",["profession:Engineering"]="Оставить специальные инструменты и нестабильную взрывчатку вроде взрывчатки Бластенхаймера в грубых руках троггов — оскорбление мастерства и катастрофа, которая только и ждет своего часа.",["race:Dwarf"]="Вспышка активности троггов на островах озера Лок угрожает местной торговле и путешествиям, поэтому любой удар по их лагерям — желанная услуга горным пехотинцам.",["race:Gnome"]="Каждый возвращенный инструмент приближает гномов к воздушному контрнаступлению против троггов и лепрогномов, душащих Гномреган."},sec={{t="Холодное падение",b="Bingles Blastenheimer was piloting his gyrocopter over Loch Modan when an unexpected crash sent him plummeting directly into the cold waters of the Loch. Surviving the impact was fortunate enough, but dragging himself ashore proved to be only half the ordeal. The troggs infesting the lake's central islands took immediate advantage of his predicament, swarming the dazed pilot and looting his most valuable belongings."},{t="Гномья изобретательность в осаде",b="Мародерствующие трогги разбросали важное снаряжение Бинглза по своим островным лагерям. Среди пропавших припасов — его обычные полевые инструменты: гаечный ключ, отвертка и молоток, а также любимое изобретение — «Сорвиголовка Бинглза». Потерять обычное снаряжение неприятно, но лишиться взрывчатки большой мощности в местности, где и так полно троггов, — прямая опасность для каждого, кто проходит через Лок Модан."},{t="За Гномреган",b="Бинглз не просто развлекается полетами в небесах Каз Модана: он считает себя воздушным авангардом освобождения своей павшей родины. Поскольку Гномреган захвачен подземными троггами и лепрогномами, Бинглз задумал решающий воздушный удар, чтобы сломить власть врага. Но без инструментов и взрывчатки для починки летающей машины его грандиозная воздушная кампания прочно застряла в камышах."}},faq={{q="Почему Бинглз Покрышкинс застрял в Лок Модане?",a="Бинглз разбил свой гирокоптер прямо в озеро Лок. Пока он пытался прийти в себя после крушения на юго-восточном берегу, на него напали трогги с соседних островов и украли его инструменты и экспериментальные боеприпасы.",al={"why is bingles here","how did bingles crash","bingles crash","почему бинглз здесь","как бинглз разбился","крушение бинглза"}},{q="Какие припасы украли трогги?",a="Трогги унесли четыре важных предмета: гаечный ключ, отвертку и молоток Бинглза, а также особый взрывной заряд — «Сорвиголовка Бинглза».",al={"what did troggs steal","bingles supplies","what items bingles","что украли трогги","припасы бинглза","какие предметы у бинглза"}},{q="Куда трогги унесли снаряжение Бинглза?",a="Трогги отнесли украденное снаряжение в свои лагеря на островах в северной части озера Лок, разбросав ведра с инструментами и взрывчатку по скалистым берегам.",al={"where are bingles tools","trogg island location","where is blastencapper","где инструменты бинглза","остров троггов","где взрывчатка бластенхаймера"}},{q="Что такое взрывчатка Бластенхаймера?",a="Это особое взрывное устройство собственной конструкции Бинглза Покрышкинса, предназначенное для боевого применения в воздушных ударах по врагам, захватившим Гномреган.",al={"what is blastencapper","blastenheimer blastencapper","bingles explosive","что такое взрывчатка бластенхаймера","бластенхаймер","взрывчатка бинглза"}},{q="О каком движении говорит Бинглз?",a="Бинглз предан делу возвращения Гномрегана. Он намерен организовать воздушную бомбардировку, чтобы изгнать подземных троггов и лепрогномов, удерживающих гномью столицу в заложниках.",al={"what movement","for gnomeregan","bingles cause","какое движение","за гномреган","дело бинглза"}},{q="Почему Бинглз не может сам вернуть припасы?",a="Бинглз одинок, промок до нитки и совершенно безоружен после катастрофического крушения. Для одинокого инженера без оружия и летательного аппарата идти через открытую воду на укрепленный лагерь агрессивных троггов было бы самоубийством.",al={"why doesnt bingles get them","why bingles waiting","почему бинглз сам не берет","почему бинглз ждет"}}},fp="25,387,14.419.0,29.443.0,14.446.0,52.210.0,40.155.0,40.188.0,26.169.0,38.192.0,48.227.0"}
P.entries["quest:2039"] = {n="Найти Бинглза",s="«Найти Бинглза» — задание Альянса, начинающееся в Стальгорне у гнома Гноарна. Обеспокоенный авиатором, пропавшим более недели назад во время воздушной разведки в сторону павшего Гномрегана, Гноарн направляет искателей приключений обыскать берега Лок Модана. Поиски приводят прямо к Бинглзу Покрышкинсу, который жив и здоров, но отчаянно нуждается в механических запчастях.",h="«Найти Бинглза» — задание Альянса, начинающееся в Стальгорне у гнома Гноарна.",ang={["faction:Alliance"]="Разведчики Альянса часто служат связующим звеном между залами Стальгорна и полевыми операциями в Лок Модане.",["profession:Engineering"]="Инженеры оценят профессиональные риски гномьей авиации, где потеря гайки или взрыв двигателя — обычный день в поле.",["race:Gnome"]="Для гномов возвращение Бинглза — это поддержание надежды на отвоевание Гномрегана, где важен каждый разведчик и каждая летающая машина."},sec={{t="Пропавший пилот",b="В шумном гномьем квартале Город механиков в Стальгорне царит тревога из-за пропавших сородичей и потерянных машин. Гнома-авиатора Бинглза Покрышкинса отправили в воздушную разведку над облученными руинами Гномрегана. Когда больше недели не было вестей, Гноарн заподозрил худшее: что Бинглз пал жертвой профессионального риска гномьих инженеров и взорвал себя в небе. Последний раз эксцентричного летчика видели где-то над водами озера Лок."},{t="У озера Лок",b="Вместо трагической груды дымящихся обломков искатели находят Бинглза живым и бодрым на берегу Лок Модана. Нимало не смущенный долгим отсутствием и слегка обиженный тем, что усомнились в его мастерстве пилота, застрявший изобретатель думает лишь о своем великом деле. Вместо того чтобы сразу вернуться с докладом к Гноарну, Бинглз тут же просит своего спасителя помочь вернуть инструменты и взрывчатку Бластенхаймера, украденные троггами, чтобы продолжить службу гномьему движению."}},faq={{q="Who is Bingles Blastenheimer?",a="Bingles Blastenheimer is an eccentric gnomish aviator and mechanic. He was sent aloft to conduct aerial surveillance over the fallen city of Gnomeregan before crashing his flying machine near Loch Modan.",al={"who is bingles","bingles blastenheimer lore","who is the pilot"}},{q="Почему Бинглз летал над Гномреганом?",a="Гномье руководство и механики постоянно наблюдают за Гномреганом после его трагического падения под натиском троггов и радиации. Бинглз поднялся в небо, чтобы разведать позиции врага и состояние местности сверху, помогая общим усилиям по возвращению дома.",al={"bingles mission","why was bingles flying","gnomeregan recon","задание бинглза","почему бинглз летал","разведка гномрегана"}},{q="Где находится Бинглз?",a="Бинглза можно найти на берегу озера Лок в Лок Модане, на юго-восточном берегу: он пытается разобраться со своей подбитой летающей машиной.",al={"where is bingles","find bingles location","where to find bingles","где бинглз","где найти бинглза","местонахождение бинглза"}},{q="Кто такой Гноарн?",a="Гноарн — гном-координатор из Города механиков в Стальгорне. Он следит за гномьим персоналом и заданиями и начинает поиски, когда Бинглз не возвращается вовремя.",al={"who is gnoarn","quest giver gnoarn","кто такой гноарн","гноарн задание"}},{q="Что происходит после того, как Бинглз найден?",a="Finding Bingles opens the follow-up task Bingles' Missing Supplies, in which adventurers recover his wrench, screwdriver, hammer, and Blastencapper explosives from the troggs on the Loch's islands.",al={"what next after find bingles","wing nut quest","bingles follow up","что дальше после найти бинглза","следующее задание бинглза","продолжение бинглза"}},{q="Пострадал ли Бинглз при крушении?",a="Бинглз совершенно невредим, хотя его гордость слегка задета тем, что Гноарн усомнился в его летных навыках. Больше всего его заботит возвращение инструментов и взрывчатки, украденных троггами.",al={"is bingles injured","did bingles die","ранен ли бинглз","погиб ли бинглз"}}},fp="12,409,15.522.0,16.513.0,29.203.0,39.253.0,25.145.0,14.187.0,35.197.0,31.191.0"}
P.entries["quest:2040"] = {n="Битва под землей",s="«Битва под землей» — задание Альянса, которое дает Шони Молшунья в Квартале Дворфов города Штормград. Помогая изгнанным гномам, искатели приключений отправляются в Мертвые копи, чтобы добыть целый энергетический блок гоблинского крошшера. Этот украденный компонент предназначен для буровых машин, которые должны возглавить освобождение Гномрегана.",h="«Битва под землей» — задание Альянса, которое дает Шони Молшунья в Квартале Дворфов города Штормград.",kw={"deadmines","gnoam sprecklesprocket","gnomeregan","goblin shredder","gyrodrillmatic","shoni the shilent","troggs","underground assault","мертвые копи","зубчатый спрек-механизм гномов","гномреган","гоблинский крошшер","гиробур","шони молшунья","трогги","битва под землей"},ang={["faction:Alliance"]="Помощь изгнанным гномам Квартала Дворфов укрепляет связь между Штормградом и его изгнанными союзниками и наносит удар по линии снабжения Братства Справедливости.",["profession:Engineering"]="Механики оценят дерзкую инженерную мысль: пустить энергетический блок свирепого гоблинского крошшера на питание точных гномьих экскавационных машин.",["race:Gnome"]="Для изгнанных гномов-искателей приключений добыча этого энергоблока — личный шаг к тому, чтобы пробить скальные стены павшего дома и изгнать троггов из Гномрегана."},sec={{t="Отчаянная изобретательность",b="После катастрофического падения Гномрегана под натиском примитивных троггов уцелевшие гномы-механики были вынуждены уйти в изгнание по Каз Модану и Штормграду. Не предаваясь унынию, инженеры вроде Шони Молшуньи уже разрабатывают механические операции по возвращению утраченного дома. Главное препятствие — плотная подземная порода вокруг технократического города, требующая огромных проходческих машин — гиродрилломатических экскаваторов. Не имея нужных местных источников энергии в человеческих землях, гномы обратили взгляд на неожиданную и опасную альтернативу: тяжелую технику гоблинов, действующую в преступном подполье."},{t="Грабеж литейных Братства Справедливости",b="Глубоко в извилистых шахтах Мертвых копей в Западном Крае Братство Справедливости Эдвина ван Клифа использует гоблинских инженеров для создания боевых машин, включая полностью исправный гоблинский крошшер. Шони направляет бойцов Альянса проникнуть в этот цех, уничтожить или разобрать неуклюжий механизм и добыть его особое сердце — зубчатый спрек-механизм гномов. Завладев мощным гоблинским источником энергии, изгнанные гномы получат необходимую механическую мощность, чтобы пробурить подземный периметр и начать контрнаступление за возвращение Гномрегана."}},faq={{q="Кто дает задание «Битва под землей»?",a="Задание дает Шони Молшунья, гном-инженер из Квартала Дворфов города Штормград. Искателей приключений часто направляют к ней после разговора с другими гномами, упоминающими ее амбициозные планы.",al={"quest giver underground assault","who gives underground assault","shoni quest","кто дает битву под землей","задание битва под землей","задание шони"}},{q="Где найти зубчатый спрек-механизм гномов?",a="Зубчатый спрек-механизм гномов добывают из исправного гоблинского крошшера в глубине туннелей литейной Мертвых копей в Западном Крае.",al={"sprecklesprocket location","where is sprecklesprocket","shredder part deadmines","где спрек-механизм","местонахождение спрек-механизма","деталь крошшера мертвые копи"}},{q="Зачем Шони нужны детали гоблинского крошшера?",a="Гномьим гиробуровым экскавационаторам нужен огромный переносной источник энергии, чтобы пробить укрепленные подземные границы вокруг Гномрегана. Мощный энергетический блок гоблинского крошшера Братства Справедливости дает именно ту механическую мощность, которая нужна для буров.",al={"why goblin parts","why shredder power supply","sprecklesprocket purpose","зачем детали гоблинов","зачем энергоблок крошшера","для чего спрек-механизм"}},{q="Какова общая цель этого задания?",a="Задание служит будущему освобождению Гномрегана. Запустив тяжелые буры, изгнанные гномы намерены прорыть путь прямо через скальный периметр захваченного города и внезапно атаковать оккупировавших его троггов.",al={"why do underground assault","reclaiming gnomeregan quest","gnome assault plan","зачем битва под землей","задание освобождение гномрегана","план атаки гномов"}},{q="Что случилось с Гномреганом, из-за чего планируется это нападение?",a="Гномреган был захвачен вторжением подземных троггов, поднявшихся из глубин под городом. В хаосе обороны город был заражен токсичной радиацией, и уцелевшим гномам пришлось бежать в Стальгорн и Штормград в качестве беженцев.",al={"why did gnomeregan fall","what happened to gnomeregan","trogg invasion","почему пал гномреган","что случилось с гномреганом","вторжение троггов"}},{q="Союзны ли Братство Справедливости и трогги?",a="Нет, между ними нет связи. Братство Справедливости лишь наняло гоблинских механиков для постройки боевых машин в Западном Крае. Шони просто использует присутствие Братства Справедливости в Мертвых копях как удобный источник мощных гоблинских технологий.",al={"defias and troggs","are troggs with defias","братство справедливости и трогги","трогги с братством справедливости"}}},fp="19,356,21.658.0,28.571.0,40.214.0,43.135.0,49.279.0,41.251.0,67.253.0,49.230.0"}
P.entries["quest:2078"] = {n="Месть Гиромачта",s="Гелхак Гиромачт жаждет расплаты с местными мурлоками, разграбившими его разбитый корабль на побережье Темных берегов. Для мести эксцентричный капитан посылает авантюристов оживить его механического помощника — Бешенатора 4100.",h="Гелхак Гиромачт жаждет расплаты с местными мурлоками, разграбившими его разбитый корабль на побережье Темных...",kw={"darkshore","gelkak","golem","gyromast","key","murloc","threshwackonator","threshwackonator 4100","темные берега","гелхак","голем","гиромачт","ключ","мурлок","бешенатор","бешенатор 4100"},ang={["faction:Alliance"]="Устранение неисправных механизмов и агрессивных мурлоков помогает обезопасить побережье для путешествий Альянса между Аубердином и землями на юге.",["profession:Engineering"]="Механический первый помощник Гелхака показывает, насколько севший на мель капитан зависит от инженерного оборудования.",["race:Gnome"]="Гномы могут узнать в заводном ключе привычный способ приведения механического автомата в действие."},sec={{t="Месть капитана",b="Оказавшись на туманных берегах Темных берегов, Гелхак Гиромачт не желает мириться с поражением от прибрежных мурлоков. Собрав обломки, нужные для его замыслов, эксцентричный капитан нацелился на полную расправу над племенем и его вождем. Вместо того чтобы лезть в прибой с саблей, Гелхак полагается на тяжелую инженерию и вверяет заводной ключ любому смельчаку-сухопутной крысе, готовому управиться с его механическим подчиненным."},{t="Бунт помощника",b="Верный первый помощник Гелхака — не бывалый дворф и не моряк, а Бешенатор 4100: лязгающий механический голем, брошенный на мелководье к югу от места крушения. Хотя заводная автоматика сулит легкую расправу над мурлоками, именно эта машина оказывается крайне ненадежной. Когда голема заводят и приводят обратно к капитану, он дает катастрофический сбой, принимает своего спасителя и создателя за врагов и вынуждает их вступить в бой на берегу."}},faq={{q="Кто помощник Гелхака?",a="Помощник Гелхака — Бешенатор 4100, автоматический механический голем, стоящий на побережье к югу от лагеря потерпевшего крушение капитана.",al={"first mate","gelkak first mate","who is the first mate","помощник","помощник гелхака","кто помощник"}},{q="Почему Гелхак хочет мести?",a="Корабль Гелхака потерпел крушение у Темных берегов, а местные мурлоки Серой Мглы растащили его вещи и донимали уцелевших членов команды. Гелхак намерен использовать голема, чтобы разгромить племя и его вождя.",al={"why revenge","murloc revenge","gelkak motivation","почему месть","месть мурлокам","мотив гелхака"}},{q="Что происходит, когда вы приводите Бешенатора обратно?",a="Приведите первого помощника обратно к Гелхаку, активировав его ключом. Как он поведет себя, дойдя до капитана, выясняется во время сопровождения.",al={"threshwackonator attack","robot malfunction","why does the golem attack","атака бешенатора","сбой робота","почему голем нападает"}},{q="What do I do with Gyromast's Key after finishing the quest?",a="The key activates the Threshwackonator. After the mission is finished, it has no further purpose.",al={"gyromast key use","keep gyromast key","can i delete key"}},{q="Откуда у Гелхака Бешенатор?",a="Голем входил в груз и снаряжение, спасенное после злосчастного плавания Гелхака вдоль северного Калимдора, и предназначался как тяжелая механическая сила для его команды.",al={"who built threshwackonator","threshwackonator origin","кто построил бешенатора","происхождение бешенатора"}},{q="Сдается ли Гелхак после уничтожения голема?",a="Планы Гелхака и его отклик на вашу работу раскрываются, когда вы приводите его первого помощника обратно.",al={"what happens to gelkak","after gyromast revenge","что с гелхаком","после мести гиромачта"}}},fp="18,252,20.490.0,23.473.1,27.138.0,29.206.0,54.140.1,59.97.1,42.159.0,49.93.1"}
P.entries["quest:2098"] = {n="Помощь Гиромачту",s="Потерпевший крушение у туманного побережья Темных берегов эксцентричный гном-пират Гелхак Гиромачт ищет помощи, чтобы восстановить своего механического помощника. Его важный заводной ключ разбился о скалы, и обломки растащили местные звери и мурлоки. Найти три части — первый шаг к тому, чтобы вернуть команду в рабочее состояние.",h="Потерпевший крушение у туманного побережья Темных берегов эксцентричный гном-пират Гелхак Гиромачт ищет...",kw={"darkshore","first mate","foreststrider","gelkak gyromast","greymist","gyromast's retrieval","pirate","reef crawler","threshadon","темные берега","помощник","лесной ходок","гелхак гиромачт","серая мгла","помощь гиромачту","пират","рифовый краб","жесткозуб"},ang={["profession:Engineering"]="Инженеры оценят сложность поддержания работы заводных механизмов после жестокого кораблекрушения в соленой воде.",["race:Gnome"]="Гномы сразу узнают в Гелхаке приверженность заводным устройствам вместо живых товарищей по кораблю, хотя образ жизни пирата для их народа весьма необычен."},sec={{t="Потерпевший на Темных берегах",b="Гелхак Гиромачт — странное зрелище на мрачных песках Темных берегов: гном-пират, застрявший вдали от обычных морских путей Южных морей. По словам Гелхака, его судно погибло неподалеку от берега, атакованное и потопленное агрессивными жесткозубами. Выброшенный на берег среди обломков, он оказался совсем один, оторванный от верной команды."},{t="Украденный ключ",b="Больше всего Гелхака заботят не припасы и не золото, а помощник. Для его запуска и управления нужен особый ключ, который разбился на три части, когда Гелхак налетел на скалистую отмель. Прежде чем он собрал осколки, местные звери — юркие рифовые крабы на пляже, высокие лесные ходоки у леса и падальщики из племени мурлоков Серой Мглы — унесли блестящие железки."},{t="Необычный спутник",b="Гелхак говорит о своем помощнике с яростной верностью морского капитана, хотя упоминания о том, что спутника нужно привести «в рабочий порядок», намекают на необычного члена команды. Гном-моряк на чужих берегах естественно полагается на механическую изобретательность, а сборка сломанного ключа важна для запуска любого заводного чуда, которое Гелхак вытащил из глубин."}},faq={{q="Кто такой Гелхак Гиромачт?",a="Гелхак Гиромачт — эксцентричный гном-пират, потерпевший крушение у побережья Темных берегов, когда хищные жесткозубы напали на его судно и потопили его.",al={"gelkak gyromast","who is the gnome pirate","darkshore gnome pirate","гелхак гиромачт","кто гном-пират","гном-пират темные берега"}},{q="Для чего нужен ключ?",a="Ключ нужен, чтобы вновь запустить и завести помощника Гелхака — механическое создание, отключившееся во время катастрофического кораблекрушения.",al={"why does gelkak need the key","gelkak key purpose","first mate key","зачем гелхаку ключ","назначение ключа гелхака","ключ помощника"}},{q="Куда делись три части ключа?",a="Когда ключ разбился на берегу, его части растащили местные существа: верхнюю унесли лесные ходоки, среднюю — мурлоки Серой Мглы, а нижнюю — прибрежные рифовые крабы.",al={"where are the key pieces","who stole the key","broken key darkshore","где части ключа","кто украл ключ","сломанный ключ темные берега"}},{q="Почему гном-пират плыл возле Темных берегов?",a="Гелхак плыл по водам у северного Калимдора в поисках добычи, но враждебные жесткозубы внезапно оборвали его плавание.",al={"why is gelkak in darkshore","pirates in darkshore","почему гелхак на темных берегах","пираты на темных берегах"}},{q="Что происходит после сборки ключа?",a="Когда у Гелхака есть все три части ключа, он может завести своего спутника, что напрямую ведет к заданию «Месть Гиромачта».",al={"what next after key","gyromast retrieval follow up","что дальше после ключа","продолжение помощи гиромачту"}},{q="Какие мурлоки хранят часть ключа?",a="Среднюю часть унесло племя мурлоков Серой Мглы, устроившее дом среди обломков затонувших кораблей на отмелях Темных берегов.",al={"darkshore murlocs","greymist murloc key","shipwreck murlocs","мурлоки темных берегов","мурлоки серой мглы ключ","мурлоки кораблекрушения"}}},fp="20,328,21.381.0,17.468.0,20.376.1,23.148.0,25.145.0,41.194.0,46.137.0,42.144.1,42.150.0"}
P.entries["quest:21"] = {n="Схватка у рудника Горного эха",s="Схватка у рудника Горного эха — прямая военная операция, которую приказал провести маршал Макбрайд, чтобы очистить Рудник Горного Эха от кобольдов-рабочих. После первоначальной разведки этот удар призван не дать подземным вредителям закрепиться в Долине Североземья.",h="Схватка у рудника Горного эха — прямая военная операция, которую приказал провести маршал Макбрайд, чтобы...",kw={"echo ridge","echo ridge mine","elwynn","kobold","laborer","marshal mcbride","mcbride","northshire","skirmish","stormwind army","рудник горного эха","горное эхо","элвиннский лес","кобольд","рабочий","маршал макбрайд","макбрайд","североземье","схватка","армия штормграда"},ang={["class:Warrior"]="Подземные драки с роящимися рабочими дают молодым воинам первый опыт ближнего боя против нескольких засевших врагов.",["faction:Alliance"]="Каждая шахта, отвоеванная у наступающих чудовищ, обеспечивает камнем и рудой, нужными, чтобы восстановить и укрепить человеческие поселения после войны.",["profession:Mining"]="Зачистка возвращает надежду, что ценные рудные жилы по всей Долине Североземья снова можно будет безопасно добывать и плавить.",["race:Human"]="Очистка Рудника Горного Эха — первое настоящее боевое испытание новобранца в защиту родного королевства, где он доказывает свою доблесть штормградскому командованию."},sec={{t="Зачистка рудника",b="После того как ранняя разведка подтвердила, что кобольды захватили Рудник Горного Эха, маршал Макбрайд без промедления организовал активную контратаку. Если оставить подземных паразитов в покое, они быстро укрепляют свои туннели, копят награбленные припасы и неудержимо размножаются. Чтобы защитить Долину Североземья — важное земледельческое и духовное убежище, — местный гарнизон полагается на новобранцев: те должны напрямую атаковать кобольдов-рабочих и проредить их ряды, пока они не закрепились еще сильнее."},{t="Тонкая оборона",b="Необходимость отправлять новобранцев в лобовую атаку отражает бедственное положение Армии Штормграда. Передовые гарнизоны растянуты вдоль южных границ, а по Элвиннскому лесу ходят слухи о растущих беспорядках, поэтому местным офицерам, таким как Макбрайд, приходится собирать всех, кто готов сражаться. Успешная схватка у рудника Горного эха доказывает надежность новобранца, приносит ему официальное уважение и готовит к более важным поручениям в других частях королевства."}},faq={{q="Почему кобольды заполонили Рудник Горного Эха?",a="Кобольдов естественным образом влекут богатые минералами подземные туннели и заброшенные карьеры. Из-за нехватки военных сил Штормграда необорняемые места вроде Горного Эха стали легкой добычей для вредителей, которые хотят рыть норы, копить золото и закрепляться под землей.",al={"why kobolds in mine","echo ridge kobolds","what are kobolds doing","почему кобольды в руднике","кобольды рудника горного эха","что делают кобольды"}},{q="Кто отдает приказ о схватке?",a="Операцией командует маршал Макбрайд, старший офицер Армии Штормграда, расквартированный в Аббатстве Североземья. Он отвечает за оборону долины и обязан поддерживать порядок, несмотря на нехватку солдат.",al={"who gives skirmish quest","marshal mcbride orders","кто дает задание схватка","приказы маршала макбрайда"}},{q="Каково стратегическое значение Рудника Горного Эха?",a="Рудник Горного Эха дает камень и руду, необходимые для содержания Североземья и более широких усилий по восстановлению Штормграда. Если позволить заразе разрастись на северной границе Североземья, это станет прямой угрозой для аббатства и ближайших виноградников.",al={"why echo ridge matters","echo ridge mine importance","почему важен рудник горного эха","значение рудника горного эха"}},{q="Куда ведет это задание дальше?",a="Когда рудник очищен от первого сопротивления рабочих, маршал Макбрайд признает боевые способности искателя приключений и направляет его в Златоземье — помогать в более широкой обороне региона.",al={"what quest after skirmish","next step after echo ridge","какое задание после схватки","следующий шаг после рудника горного эха"}},{q="Почему Армия Штормграда не очистит рудник сама?",a="Армии Штормграда остро не хватает людей: она с трудом защищает далекие границы и отвечает на разбой по всему Элвиннскому лесу. Офицерам вроде Макбрайда приходится полагаться на недавно принявших присягу новобранцев в борьбе с местными угрозами, пока опытные стражники удерживают оборонительные рубежи.",al={"why recruits","where are stormwind soldiers","почему новобранцы","где солдаты штормграда"}},{q="Достаточно ли кобольды разумны, чтобы быть организованной военной угрозой?",a="Хотя отдельные кобольды-рабочие трусливы и недалеки, в большом числе они опасно агрессивны и защищают свою территорию. Если их не остановить, они быстро роют запутанные туннели, обрушивают пещеры и зовут к себе более крупных и лучше вооруженных вредителей.",al={"are kobolds smart","kobold danger level","умны ли кобольды","опасность кобольдов"}}},fp="22,283,16.486.0,14.500.0,46.266.0,24.223.0,52.263.0,34.203.0,57.260.0,66.252.0"}
P.entries["quest:2118"] = {n="Зачумленные земли",s="Зачумленные земли — задание Альянса, которое дает Тарнариун Исцелитель Деревьев в Темных берегах. Стремясь исцелить распространяющуюся порчу, терзающую местных животных, Тарнариун поручает искателям приключений живьем поймать бешеного чертополохового медведя с помощью зачарованной реликвии, чтобы попытаться его вылечить.",h="Зачумленные земли — задание Альянса, которое дает Тарнариун Исцелитель Деревьев в Темных берегах.",kw={"cleansing of the infected","darkshore","plagued lands","rabid thistle bear","tharnariun treetender","tharnariun's hope","thistle bear","избавление от заразы","темные берега","зачумленные земли","бешеный чертополоховый медведь","тарнариун исцелитель деревьев","надежда тарнариуна","чертополоховый медведь"},ang={["class:Druid"]="Друиды разделяют скорбь Тарнариуна при виде оскверненной природы, а трагическая гибель медведя подчеркивает, насколько глубоко въелась болезнь, расползающаяся по земле.",["faction:Alliance"]="Путникам Альянса, идущим по северному Калимдору, приходится считаться с неукрощенной порчей, подступающей прямо к границам обжитых земель.",["race:NightElf"]="Для кальдораев видеть, как родные растения и животные Темных берегов гибнут в бешеном безумии, — оскорбление Кенария и равновесия природы, которое они поклялись защищать."},sec={{t="Язва в глуши",b="Зловещий недуг ползет по лесам Темных берегов, превращая зверей в безумные, агрессивные тени их прежних себя. Сильнее всех от этого безумия пострадали местные чертополоховые медведи: бешеная ярость угрожает и проезжим путникам, и хрупкому равновесию природы побережья. Там, где ночные эльфы-часовые нередко отвечают сталью, друиды стремятся понять и излечить первопричину."},{t="Надежда Тарнариуна",b="Не желая убивать зараженных зверей, не попытавшись их спасти, Тарнариун Исцелитель Деревьев создал особую ловушку — Надежду Тарнариуна. Искатели приключений ставят устройство на лесную землю, и его успокаивающий свет ненадолго усмиряет разум разъяренного чертополохового медведя. Укрощенный зверь покорно следует за путником к лагерю Тарнариуна для изучения."},{t="Трагическое лекарство",b="Когда искатель приключений успешно приводит зараженного медведя в лагерь, Тарнариун тут же пытается изгнать болезнь исцеляющей магией. К сожалению, его первые усилия оборачиваются катастрофой: вихрь очищающей энергии подавляет ослабленный организм зверя, и тот падает замертво. Неудача показывает, насколько глубоко въелась темная чума."}},faq={{q="Кто дает задание «Зачумленные земли»?",a="Задание дает Тарнариун Исцелитель Деревьев, друид-ночной эльф из Аубердина в Темных берегах, стремящийся излечить больных животных.",al={"quest giver plagued lands","tharnariun darkshore quest","who starts plagued lands","персонаж, выдающий задание зачумленные земли","задание тарнариуна темные берега","кто начинает зачумленные земли"}},{q="Какова цель задания «Зачумленные земли»?",a="Вы должны с помощью выданного предмета, Надежды Тарнариуна, поймать и усмирить бешеного чертополохового медведя в Темных берегах, а затем живым отвести укрощенного зверя к Тарнариуну.",al={"plagued lands goal","what to do in plagued lands","how to catch bear darkshore","цель зачумленные земли","что делать в зачумленных землях","как поймать медведя темные берега"}},{q="Что происходит с медведем, когда вы приводите его обратно?",a="Тарнариун пытается очистить животное исцеляющей магией, но болезнь зашла слишком глубоко. Нагрузка оказывается непосильной для зверя, и он умирает сразу после лечения.",al={"does the bear die","tharnariun bear cure result","bear death plagued lands","умирает ли медведь","результат лечения медведя тарнариуном","смерть медведя зачумленные земли"}},{q="Каким предметом вы ловите медведя?",a="Тарнариун дает зачарованную ловушку под названием Надежда Тарнариуна: она излучает успокаивающий свет, усмиряющий разъяренного медведя, и тот следует за вами.",al={"plagued lands trap","tharnariun's hope item","bear cage darkshore","ловушка зачумленные земли","предмет надежда тарнариуна","клетка для медведя темные берега"}},{q="Какое задание следует за «Зачумленными землями»?",a="Зачумленные земли — первая часть цепочки из трех заданий. Их выполнение открывает следующее задание, «Избавление от заразы», которое в итоге ведет к заключительному заданию, «Надежда Тарнариуна».",al={"next quest after plagued lands","plagued lands chain","tharnariun follow up","следующее задание после зачумленных земель","цепочка зачумленные земли","продолжение от тарнариуна"}},{q="Почему чертополоховые медведи бешеные?",a="По Темным берегам расползается подкрадывающаяся губительная чума, отравляющая разум и тело местных животных и обращающая благородных чертополоховых медведей в бездумную ярость.",al={"why are bears sick in darkshore","darkshore plague bears","darkshore corruption","почему медведи больны в темных берегах","чумные медведи темные берега","порча темных берегов"}}},fp="13,269,26.422.0,17.371.0,15.390.1,34.139.0,39.161.0,48.186.1,41.155.0,33.189.0,32.171.0"}
P.entries["quest:2138"] = {n="Избавление от заразы",s="Избавление от заразы — задание Альянса в Темных берегах, которое дает Тарнариун Исцелитель Деревьев в Аубердине. После того как его попытка исцеления не остановила лесную болезнь, хранитель неохотно приказывает истребить бешеных чертополоховых медведей, бродящих по туманной глуши. Это горький перелом, когда сохранение уступает место сдерживанию.",h="Избавление от заразы — задание Альянса в Темных берегах, которое дает Тарнариун Исцелитель Деревьев в...",kw={"auberdine","cleansing","darkshore","infected","rabid thistle bear","tharnariun","treetender","аубердин","избавление","темные берега","зараза","бешеный чертополоховый медведь","тарнариун","исцелитель деревьев"},ang={["class:Druid"]="Друиды, почитающие духов диких медведей, находят приказ Тарнариуна особенно горьким: это акт милосердия и лесной сортировки раненых, а не обычная охота.",["class:Hunter"]="Охотники понимают, что истребление больных хищников порой необходимо для защиты всей экосистемы, даже если первопричина остается неустановленной.",["race:NightElf"]="Для кальдораев приказ убивать зараженных зверей — тяжелое бремя, показывающее, как глубоко послевоенная порча проникла в их родные земли."},sec={{t="Горькая необходимость",b="Тарнариун Исцелитель Деревьев долго искал средство, способное остановить ползущую болезнь, что портит животных Темных берегов. Несмотря на попытку исцелить пойманного медведя, чертополоховые медведи остаются тяжело больными и свирепыми. Исчерпав более мягкие способы, ночной эльф-хранитель приходит к выводу, что единственный быстрый способ не дать зверям терзать других существ и разносить болезнь дальше по древним лесам — убить их."},{t="Сдерживание дикой природы",b="Истребление двадцати бешеных медведей — мучительный долг для любого слуги природы. Тарнариун прямо признает, что убийство зверей не излечит чуму, но выигрывает ценное время для защитников Аубердина. Пока не удастся найти и устранить главный источник порчи леса, сокращение численности агрессивных стад остается единственным щитом поселения от катастрофы."}},faq={{q="Почему Тарнариун хочет убить чертополоховых медведей, а не вылечить?",a="Ранее Тарнариун пытался очистить пойманного медведя, но лечение не удалось, и зверь погиб. Больные медведи становятся свирепыми и угрожают другим существам, поэтому убийство — последняя мера, чтобы замедлить распространение болезни.",al={"why kill the bears","why not cure bears","tharnariun bear quest","зачем убивать медведей","почему не вылечить медведей","задание тарнариуна про медведей"}},{q="Кто такой Тарнариун Исцелитель Деревьев?",a="Тарнариун — ночной эльф-хранитель, живущий в Аубердине. Он изучает недуги, поражающие растения и животных Темных берегов, и стремится сохранить природное равновесие перед лицом распространяющейся порчи.",al={"tharnariun role","who gives cleansing of the infected","роль тарнариуна","кто дает избавление от заразы"}},{q="Закончится ли чума, если убить бешеных медведей?",a="Нет. Тарнариун прямо предупреждает, что убийство бешеных медведей не остановит чуму. Оно лишь выигрывает для леса и жителей Аубердина драгоценное время, замедляя заражение и вспышки ярости.",al={"does this fix darkshore","is the plague cured","решает ли это проблему темных берегов","вылечена ли чума"}},{q="Что идет после «Избавления от заразы»?",a="Когда вы вернетесь к Тарнариуну, он попросит вас приготовить дух к новому кровопролитию и предложит следующее задание, «Надежда Тарнариуна», чтобы продолжить борьбу с пораженной порчей дикой природой.",al={"next quest after cleansing","what follows cleasning infected","следующее задание после избавления","что после избавления от заразы"}},{q="Где обитают бешеные чертополоховые медведи?",a="Бешеные чертополоховые медведи бродят по прибрежным и внутренним лесным участкам центральных Темных берегов, часто среди туманных сосен к югу и востоку от Аубердина.",al={"rabid thistle bear location","where are bears darkshore","где бешеные чертополоховые медведи","где медведи темные берега"}},{q="Из-за чего чертополоховые медведи стали бешеными?",a="Медведи стали жертвами загадочной скверны, охватывающей леса северного Калимдора и превращающей мирных животных в яростных, агрессивных зверей, на которых не действует лечение Тарнариуна.",al={"why are bears sick","bear sickness darkshore","почему медведи больны","болезнь медведей темные берега"}}},fp="25,344,18.466.0,20.402.1,67.232.0,29.192.0,53.202.0,43.189.0,40.159.0,42.192.0"}
P.entries["quest:2139"] = {n="Надежда Тарнариуна",s="«Надежда Тарнариуна» — мрачное завершение усилий Тарнариуна Исцелителя Деревьев по борьбе с болезнью животных Темных берегов. Перебив из милосердия множество зараженных зверей в лесах, герой Альянса получает задание убить бешеную Мать логова к северо-востоку от Аубердина.",h="«Надежда Тарнариуна» — мрачное завершение усилий Тарнариуна Исцелителя Деревьев по борьбе с болезнью животных...",kw={"auberdine","bashal'aran","cleansing of the infected","darkshore","den mother","rabid thistle bear","tharnariun treetender","tharnariun's hope","аубердин","башал'аран","избавление от заразы","темные берега","мать логова","бешеный чертополоховый медведь","тарнариун исцелитель деревьев","надежда тарнариуна"},ang={["class:Druid"]="Друиды глубоко почитают медведей благодаря учениям Урсока. Убийство зараженной Матери логова служит суровым напоминанием о хрупком равновесии природы и трагедиях порчи.",["class:Hunter"]="Охотники понимают трагедию хищника, сведенного с ума болезнью, и знают, когда убийство зараженного зверя — истинное милосердие.",["faction:Alliance"]="Защита Аубердина укрепляет позиции Альянса на побережье северного Калимдора и доказывает его готовность защищать земли ночных эльфов от растущих угроз дикой природы.",["race:NightElf"]="Для ночных эльфов убийство лесных зверей, особенно медведицы-матриарха, противоречит их глубокому почитанию природы, и этот долг становится горькой и печальной необходимостью."},sec={{t="Трагическая необходимость",b="После Третьей войны дикие существа Темных берегов начали поддаваться неестественной болезни, вызывающей бешенство. Тарнариун Исцелитель Деревьев, живший в Аубердине, днями поручал путникам убивать зараженных зверей, чтобы облегчить страдания леса. Однако истребление бешеных чертополоховых медведей лишь устраняло симптом. Чтобы остановить распространение, он решил, что нужно уничтожить источник среди местных медведей — матриарха, известную как Мать логова."},{t="Мать логова",b="Мать логова, обитавшая в пещере к северо-востоку от Аубердина, возле древних руин Башал'Аран, когда-то была важной защитницей лесной фауны. Охваченная безумной болезнью, распространяющейся по северному Калимдору, она раз за разом рождала и растила выводки бешеных медвежат. Выследив матриарха в ее логове, герои Альянса прекратили ее муки и остановили поток обезумевших медведей, бродивших у прибрежной дороги."},{t="Суровая действительность Калимдора",b="После гибели Матери логова Тарнариун выражает глубокую благодарность, омраченную печалью. Для кальдораев поднимать оружие на лесных существ — мучительный долг. Но пока темные силы наступают на их новый дом, а многие впадают в отчаяние или ищут укрытия, подобные поступки доказывают, что защитники Аубердина готовы нести тяжкое нравственное бремя ради защиты своих лесов."}},faq={{q="Кто такой Тарнариун Исцелитель Деревьев?",a="Тарнариун Исцелитель Деревьев — ночной эльф, смотритель, живущий в Аубердине. Потрясенный порчей и безумием, искажающими животных Темных берегов, он руководит усилиями по изучению и выслеживанию страдающих животных и, в конечном счете, избавлению их от мучений.",al={"tharnariun","who gives tharnariun's hope","treetender auberdine","тарнариун","кто выдает надежду тарнариуна","исцелитель деревьев аубердин"}},{q="Где находится Мать логова?",a="Она обитает в пещере среди холмов к северо-востоку от Аубердина, сразу к востоку от руин Башал'Аран.",al={"where is den mother","den mother cave location","find den mother","где мать логова","пещера матери логова","найти мать логова"}},{q="Почему Мать логова нужно убить, а не исцелить?",a="Болезнь, поражающая животных Темных берегов, глубоко укоренилась и толкает зверей к яростному безумию. Поскольку немедленного лекарства нет, а Мать логова продолжает растить бешеное потомство, Тарнариун решил, что убить ее — единственный способ не дать болезни распространяться дальше.",al={"can den mother be saved","why kill den mother","cure den mother","можно ли спасти мать логова","зачем убивать мать логова","вылечить мать логова"}},{q="Какие задания предшествуют «Надежде Тарнариуна»?",a="Это задание — заключительное звено цепочки из трех. Она начинается с «Зачумленных земель», продолжается заданием «Избавление от заразы» и завершается «Надеждой Тарнариуна».",al={"prerequisites for tharnariuns hope","quest chain tharnariun","предыдущие задания надежда тарнариуна","цепочка заданий тарнариун"}},{q="Что вызывает болезнь у животных Темных берегов?",a="Тарнариун не называет источник. Он знает лишь, что по Темным берегам распространяется болезнь, захватывающая разум и тело всех, кого коснется, и что сильнее всего пострадали чертополоховые медведи.",al={"why are bears rabid in darkshore","darkshore animal plague cause","what corrupted the bears","почему медведи бешеные на темных берегах","причина болезни животных темные берега","что испортило медведей"}},{q="Почему Тарнариун говорит, что люди бегут в укрепленные земли?",a="Аубердин — открытый прибрежный форпост, осаждаемый призраками, зараженными животными и враждебными существами. Пока цивилизация ночных эльфов с трудом восстанавливается после вторжения Пылающего Легиона, некоторые жители чувствуют себя подавленными и прячутся или отступают к более безопасным оплотам Альянса.",al={"fleeing auberdine","fortified alliance lands","бегство из аубердина","укрепленные земли альянса"}}},fp="17,272,18.445.0,14.431.1,28.400.0,29.234.0,32.110.0,51.305.0,41.170.0,45.198.0,63.294.0"}
P.entries["quest:214"] = {n="Красные шелковые банданы",s="«Красные шелковые банданы» — задание, которое выдает Разведчица Риэла от имени Народного ополчения. Оно отправляет искателей приключений из Альянса в Мертвые копи, чтобы выследить высокопоставленных членов Братства Справедливости и принести их характерные красные шелковые маски как доказательство.",h="«Красные шелковые банданы» — задание, которое выдает Разведчица Риэла от имени Народного ополчения.",kw={"deadmines","defias brotherhood","moonbrook","peoples militia","red silk bandanas","scout riell","vancleef","westfall","мертвые копи","братство справедливости","луноречье","народное ополчение","красные шелковые банданы","разведчица риэла","ван клиф","западный край"},ang={["class:Rogue"]="Красные шелковые маски Братства Справедливости — часть известной традиции преступного мира, отмечающая опытных головорезов и тайных заговорщиков.",["faction:Alliance"]="Каждый офицер, павший в Мертвых копях, ослабляет хватку Братства Справедливости на житнице Королевства Штормград.",["profession:Tailoring"]="Тонкий красный шелк — дорогая роскошь для простых бандитов, и это показывает, насколько богато снаряжено и обеспечено руководство Братства Справедливости."},sec={{t="Иерархия в ткани",b="Хотя обычные воры и разбойники по всему Западному Краю повязывают лица грубой красной тканью, в Братстве Справедливости существует строгая внутренняя иерархия, отраженная в материале. Разведчица Риэла и Народное ополчение выяснили, что рядовые бандиты носят грубую ткань, а старшие заговорщики и члены ближнего круга отличаются тонким красным шелком. Снимая эти банданы, вы бьете прямо по опытным офицерам, координирующим восстание Эдвина ван Клифа."},{t="Удар в самое сердце",b="Поскольку шелк означает старшинство, больше всего таких высокопоставленных разбойников собирается в глубине Мертвых копей под Луноречьем. Стражи и разведчики, расположенные у Сторожевого холма, полагаются на вольных героев, которые проникают в спорные подземные туннели. Каждая добытая шелковая бандана означает одним лейтенантом меньше — тем, кто устраивал засады, охранял склады оружия и обеспечивал власть ван Клифа по всему Западному Краю."}},faq={{q="Почему члены Братства Справедливости носят красные банданы?",a="Красная бандана — общий символ и визитная карточка Братства Справедливости на землях Штормграда. Она скрывает личности и в то же время показывает верность мятежному движению Эдвина ван Клифа.",al={"defias mask meaning","why red masks","defias uniform","значение маски братства справедливости","почему красные маски","форма братства справедливости"}},{q="Чем красные шелковые банданы отличаются от обычных?",a="По словам Разведчицы Риэлы, ткань указывает на положение в Братстве. Простые уличные головорезы носят грубую дешевую ткань, а ветеранам, офицерам и доверенным лейтенантам достается красный шелк.",al={"why red silk","silk vs cloth defias","silk bandana difference","почему красный шелк","шелк или ткань братство справедливости","отличие шелковой банданы"}},{q="Кто такая Разведчица Риэла?",a="Разведчица Риэла — агент Народного ополчения в Западном Крае. Она следит за передвижениями Братства Справедливости и направляет искателей приключений на удар по его оплотам вокруг Мертвых копей.",al={"scout riell westfall","who gives red silk bandanas quest","разведчица риэла западный край","кто выдает задание красные шелковые банданы"}},{q="Где находятся члены Братства Справедливости в шелковых банданах?",a="Они сосредоточены в Мертвых копях под городом Луноречье и вокруг них, где старшие силы Эдвина ван Клифа руководят подземными операциями.",al={"where to find silk bandanas","deadmines silk bandana location","где найти шелковые банданы","шелковая бандана мертвые копи"}},{q="Что такое Народное ополчение?",a="Народное ополчение — добровольческие силы обороны, созданные Грианом Камнегривом и измученными фермерами Западного Края для защиты своих земель после того, как армия Штормграда не смогла обеспечить достаточные гарнизоны.",al={"who are the people's militia","peoples militia westfall","кто такое народное ополчение","народное ополчение западный край"}},{q="Есть ли у этих бандан иное применение, кроме доказательства убийства?",a="Для Народного ополчения они служат лишь неоспоримым доказательством того, что высокопоставленные разбойники уничтожены, а командная структура Братства Справедливости ослаблена.",al={"can you wear red silk bandana","what are the bandanas for","можно ли носить красную шелковую бандану","для чего нужны банданы"}}},fp="17,240,20.475.0,17.421.0,36.216.0,70.196.0,19.186.0,51.149.0,29.201.0,57.165.0"}
P.entries["quest:2159"] = {n="Посылка в Доланаар",s="«Посылка в Доланаар» — поручение для молодых ночных эльфов, покидающих укрытые ветви Тенистой долины ради более широких просторов Тельдрассила. Портанниус, занятый делами с местными друидами, просит путников отнести посылку с травами на юг Хозяину таверны Кельдамиру. Этот простой путь отмечает переход новичка в оживленный центр Доланаара.",h="«Посылка в Доланаар» — поручение для молодых ночных эльфов, покидающих укрытые ветви Тенистой долины ради...",kw={"delivery","dolanaar","dolanaar delivery","herbs","innkeeper keldamyr","night elf","porthannius","shadowglen","teldrassil","доставка","доланаар","посылка в доланаар","травы","хозяин таверны кельдамир","ночной эльф","портанниус","тенистая долина","тельдрассил"},ang={["class:Druid"]="Занятость Портанниуса друидами Тенистой долины намекает на более глубокие духовные обязанности и природный дисбаланс, которыми занят Круг Кенария на ветвях.",["profession:Herbalism"]="Эта доставка показывает, как важны сырые травы с плодородных почв Тенистой долины для целителей, поваров и смотрителей Доланаара.",["race:NightElf"]="Взяв это задание, ночной эльф покидает защищенную колыбель Альдрассила и выходит навстречу более широким обязанностям по защите Тельдрассила."},sec={{t="Посыльный для Тенистой долины",b="Прежде чем новые искатели приключений покинут тренировочные земли Тенистой долины, Портанниус ищет того, кто направляется по дороге к остальному Тельдрассилу. Погрузившись в неотложные дела с друидами, ухаживающими за поляной, он не может отлучиться и сам выполнять обычные поручения. Поэтому он вручает связку свежесобранных трав начинающему герою, чтобы необходимые припасы дошли на юг по лесной тропе."},{t="Дорога в Доланаар",b="Южная дорога из уединенной долины ведет путников в Доланаар — одно из главнейших поселений ночных эльфов на великих ветвях Тельдрассила. Там Хозяин таверны Кельдамир заботится о гостеприимстве, отдыхе и припасах для странников, стражей и друидов. Приняв травы от имени Портанниуса, Кельдамир пользуется случаем, чтобы призвать молодых искателей приключений дать отдых уму и духу, прежде чем встретиться с растущей порчей на мировом древе."}},faq={{q="Кто такой Портанниус?",a="Портанниус — ночной эльф, живущий в Тенистой долине, начальной поляне Тельдрассила. Работая бок о бок с местными друидами, он просит путников, покидающих поляну, отнести от его имени припасы на юг.",al={"porthannius","who gives dolanaar delivery","quest giver porthannius","портанниус","кто выдает посылку в доланаар","портанниус задание"}},{q="Почему Портанниус не может сам доставить травы?",a="У Портанниуса срочные незавершенные дела с друидами Тенистой долины. Поскольку обязанности удерживают его в укромной долине, ему приходится полагаться на проходящих мимо искателей приключений, которые отправятся на юг.",al={"why does porthannius need help","why cant porthannius go","почему портанниус просит помощи","почему портанниус не может пойти"}},{q="Что находится в посылке?",a="В посылке — собрание трав, собранных в Тенистой долине и предназначенных для таверны в Доланааре.",al={"dolanaar delivery package contents","what are the herbs","содержимое посылки в доланаар","что за травы"}},{q="Кто такой Хозяин таверны Кельдамир?",a="Хозяин таверны Кельдамир управляет таверной в Доланааре. Помимо гостеприимства, ночлега и камней возвращения для путников, он часто организует торговлю и обмен припасами с другими поселениями Тельдрассила.",al={"keldamyr","dolanaar innkeeper","who receives the herbs","кельдамир","хозяин таверны доланаар","кто получает травы"}},{q="Где находится Доланаар?",a="Доланаар лежит к югу от Тенистой долины. Если идти по главной дороге от выхода из долины, она приведет путников прямо в центр города.",al={"where is dolanaar","dolanaar location","directions to dolanaar","где доланаар","расположение доланаара","как добраться до доланаара"}},{q="Почему эта доставка важна для молодых искателей приключений?",a="Она знакомит с миром за пределами Тенистой долины и побуждает новичков выйти за пределы тренировочных земель и узнать таверну, учителей и поставщиков услуг Доланаара.",al={"significance of delivery","why deliver herbs","значение доставки","зачем доставлять травы"}}},fp="17,359,26.414.0,20.466.0,19.211.0,48.201.0,27.111.0,26.216.0,26.140.0,53.187.0"}
P.entries["quest:2160"] = {n="Припасы для Таннока",s="«Припасы для Таннока» — поручение для начинающих искателей приключений, покидающих Холодную долину через опасный горный перевал в глубь Дун Мороге. Гном-механик Ручник Ржавозубчик отправляет ящик необходимых припасов Танноку Молоту Стужи в таверну «Громоварка» в Караносе в обход троггских троп, из-за которых прервалась обычная торговля.",h="«Припасы для Таннока» — поручение для начинающих искателей приключений, покидающих Холодную долину через...",kw={"anvilmar","coldridge pass","hands springsprocket","kharanos","supplies to tannok","tannok frosthammer","thunderbrew","troggs","старая наковальня","туннель холодной долины","ручник ржавозубчик","каранос","припасы для таннока","таннок молот стужи","громоварское","трогги"},ang={["faction:Alliance"]="Восстановление торговли между изолированными заставами поддерживает снабжение внутренних земель Стальгорна, несмотря на дерзкие набеги троггов.",["race:Dwarf"]="Доставка припасов из Старой Наковальни в Каранос — ваш обряд посвящения: вы покидаете защищенную долину и вступаете на службу более широкому королевству Стальгорна.",["race:Gnome"]="Помощь Ручнику Ржавозубчику показывает надежное сотрудничество между изгнанниками из Гномрегана и принявшими их дворфами в Дун Мороге."},sec={{t="Блокированная долина",b="Холодная долина — традиционно место испытаний и убежище для молодых дворфов Стальгорна и изгнанных уцелевших гномов Гномрегана, но недавние события осложнили ее связь с остальным Дун Морогом. Трогги захватили Туннель Холодной долины, и пройти через горное ущелье стало опасно. Стрелки-горцы разбросаны по поселениям и оборонительным рубежам, и плановые сопровождения обозов откладываются на многие дни."},{t="Ручник и помощник хозяина таверны",b="Ручник Ржавозубчик, гном из Старой Наковальни, оказался с ящиком важных трактирных припасов, предназначенных для Караноса, и без надежного способа доставить его лично. Понимая, что бывалые искатели приключений уже готовятся к опасному перевалу, он просит отправляющихся путников доставить груз Танноку Молоту Стужи, помощнику в шумной таверне Громоваров."},{t="Радушный очаг в Караносе",b="Прибытие в Каранос открывает путешественнику дорогу в большой мир Дун Мороге. Таннок Молот Стужи охотно принимает доставку и замечает, что вести из Старой Наковальни почти перестали приходить с тех пор, как трогги нарушили движение через перевал. Доставка груза восстанавливает хрупкую связь и торговлю между двумя изолированными общинами дворфов."}},faq={{q="Кто такой Ручник Ржавозубчик?",a="Ручник Ржавозубчик — предприимчивый гном, живущий в Старой Наковальне в Холодной долине. Не имея возможности в одиночку пройти опасный горный перевал, он полагается на умелых путников, которые доставят товары в Каранос.",al={"hands springsprocket","quest giver","who gives supplies to tannok","ручник ржавозубчик","персонаж, выдающий задания","кто дает припасы для таннока"}},{q="Кто такой Таннок Молот Стужи?",a="Таннок Молот Стужи — помощник хозяина таверны «Громоварка» в Караносе. Он помогает управлять снабжением таверны и принимает припасы, присылаемые из таких застав, как Старая Наковальня.",al={"tannok","tannok frosthammer","kharanos innkeeper assistant","таннок","таннок молот стужи","помощник хозяина таверны в карано"}},{q="Почему Ручник не может сам доставить припасы?",a="Перевал, соединяющий Холодную долину с Каранос, захвачен враждебными троггами. Ручник не приспособлен пробиваться с боем в одиночку, а официальные сопровождающие из числа горцев сильно задерживаются.",al={"why can't hands deliver it","why need adventurer","why is the pass dangerous","почему ручник не может доставить","зачем нужен искатель приключений","чем опасен перевал"}},{q="Где находится таверна в Караносе?",a="Таннок Молот Стужи находится внутри таверны «Громоварка» — большого постоялого двора в самом центре Каранос, на главной дороге, ведущей на восток к Стальгорну.",al={"where is tannok","thunderbrew distillery location","kharanos inn location","где таннок","где таверна громоварка","где таверна в карано"}},{q="Что лежит в ящике с припасами для постоялого двора?",a="В ящике находятся необходимые мелочи и провизия для таверны, собранные в Старой Наковальне, чтобы пополнить запасы таверны «Громоварка» в Караносе.",al={"what is in the crate","crate of inn supplies","что в ящике","ящик с припасами для постоялого двора"}},{q="Почему связь между Старой Наковальней и Каранос прервана?",a="Трогги, выходящие из подземных туннелей, заполонили Туннель Холодной долины. Их агрессивное присутствие лишило возможности легко ходить пешком и регулярно обмениваться донесениями между Холодной долиной и остальным Дун Морогом.",al={"why scarce word from anvilmar","trogg problem pass","почему нет вестей из старой наковальни","проблема с троггами на перевале"}}},fp="18,367,18.421.0,35.383.0,30.353.0,28.205.0,26.196.0,45.192.0,37.174.0,41.140.0,59.201.0"}
P.entries["quest:2161"] = {n="Ноша батрака",s="«Ноша батрака» — вводное поручение на доставку от Укора, встревоженного орка-работника, оставшегося на тропе у Долины Испытаний. Попытавшись доставить провизию новобранцам, которым она оказалась не нужна, Укор просит путников благополучно вернуть тяжелый груз в Колючий Холм.",h="«Ноша батрака» — вводное поручение на доставку от Укора, встревоженного орка-работника, оставшегося на тропе...",kw={"durotar","food","innkeeper grosk","peon","razor hill","supplies","ukor","valley of trials","дуротар","еда","хозяин таверны гроск","батрак","колючий холм","припасы","укор","долина испытаний"},ang={["faction:Horde"]="Этот путь служит переходом от места испытаний к Колючему Холму — главному центру обороны и снабжения Орды на юге Дуротара.",["race:Orc"]="Орочья культура ценит физическую силу и храбрость, поэтому батраки вроде Укора находятся в самом низу иерархии; выполняя его поручение, видно, как даже скромный труд поддерживает жизнь молодого государства в Дуротаре."},sec={{t="Неудачная доставка",b="Укор — старательный батрак, отправившийся из Колючего Холма с добрыми намерениями и тащивший тяжелый тюк с провизией к Долине Испытаний. Полагая, что новобранцы, тренирующиеся в красном ущелье, отчаянно нуждаются в пайках, он прошел весь путь, но его прогнали. Надзиратели, следящие за испытаниями, намеренно держат припасы скудными: как позже замечает Хозяин таверны Гроск, жизнь на скудном пайке считается способом выковать дисциплину и выносливость у молодых воинов Орды."},{t="Опасности Красной пустоши",b="Хотя Укору удалось дойти до перевала, он в ужасе от мысли возвращаться тем же путем по выжженной солнцем земле Дуротара. Скалы вдоль тропы кишат агрессивными скорпидами, ядовитыми пауками и бродячими кабанами. Без оружия, брони и боевого духа, ожидаемого от орков-грантов, испуганный работник ждет у дороги и умоляет любого проходящего искателя приключений, покидающего место испытаний, взять его ношу и вернуть в таверну."}},faq={{q="Кто такой Укор?",a="Укор — орк-батрак, оставшийся на дороге, ведущей из Долины Испытаний. Добрый, но робкий, он отправился доставить провизию из Колючего Холма, но понял, что слишком боится местных зверей, чтобы вернуться одному.",al={"ukor","who is the peon on the road","peon near valley of trials","укор","кто батрак на дороге","батрак возле долины испытаний"}},{q="Почему наставники в Долине Испытаний не захотели принять еду?",a="Надзиратели в Долине Испытаний верят в строгую дисциплину для молодых новобранцев. Как с юмором замечает Хозяин таверны Гроск, наставники предпочитают держать учеников голодными, чтобы проверить их характер и закалить дух, поэтому благотворительная посылка Укора оказалась нежеланной.",al={"why refuse food","why did ukor carry food","innkeeper grosk starvation","почему отказались от еды","почему укор нес еду","хозяин таверны гроск голод"}},{q="Куда нужно доставить груз?",a="Ношу нужно отнести на север по главной дороге Дуротара в Колючий Холм и передать Хозяину таверны Гроску в таверне поселения.",al={"where is razor hill","who do i give the food to","where to deliver ukor's burden","где колючий холм","кому отдать еду","куда доставить ношу укора"}},{q="Чем путь опасен для батрака?",a="Каменистые пустоши Дуротара полны территориальных скорпидов, ядовитых пауков-ползунов и диких кабанов. Опытные новобранцы справятся с такими тварями, но безоружный и необученный работник вроде Укора едва ли уцелеет при нападении.",al={"why is ukor scared","durotar road dangers","почему укор боится","опасности дороги в дуротаре"}},{q="Какова роль батраков в Орде?",a="Батраки занимают самую низкую ступень орочьего общества и выполняют черную работу: таскают припасы, рубят лес, возводят укрепления. Пока грантов и чемпионов хвалят и славят, батраков часто не замечают, хотя они кормят и содержат поселения.",al={"orc peons lore","peon status","what are peons","орки-батраки предания","статус батраков","кто такие батраки"}},{q="Кто такой Хозяин таверны Гроск?",a="Хозяин таверны Гроск заведует таверной в Колючем Холме. Он управляет жильем и припасами городка, предлагает путешествующим воинам еду, питье и очаг и напоминает новобранцам, что отдых необходим, прежде чем отправляться в большой мир.",al={"innkeeper grosk","grosk razor hill","razor hill innkeeper","хозяин таверны гроск","гроск колючий холм","хозяин таверны в колючем холме"}}},fp="15,305,20.477.0,23.460.0,12.254.0,62.278.0,36.156.0,44.229.0,39.269.0,23.222.0"}
P.entries["quest:217"] = {n="Защита королевских земель",s="«Защита королевских земель» завершается прямым ударом по предводителям троггов в Лок Модане. Дворфийские разведчики выследили источник нашествия — вождя Грамуга и его свирепых телохранителей в глубине Долины Камнедробов. Капитан Ругельфасс поручает отважным искателям приключений Альянса убить вождя, чтобы сломить боевой дух троггов и вернуть южные границы королевства.",h="«Защита королевских земель» завершается прямым ударом по предводителям троггов в Лок Модане.",kw={"brawler","gnasher","grawmug","kings lands","loch modan","rugelfuss","stonesplinter","trogg","драчун","грызун","грамуг","королевские земли","лок модан","ругельфасс","камнедробы","трогг"},ang={["faction:Alliance"]="Оборона Лок Модана сохраняет важнейшую сухопутную связь между Стальгорном и восточными рубежами и обеспечивает безопасность снабжения всех сил Альянса.",["race:Dwarf"]="Для дворфов отражение троггов с древней земли Каз Модана — вопрос защиты родины и чести: горные твердыни должны остаться незапятнанными подземной напастью."},sec={{t="Обезглавить полчище",b="Постоянная угроза троггов на юге Лок Модана оказалась чем-то большим, чем случайные вылазки из-под земли. Разведчики капитана Ругельфасса выяснили, что трогги Камнедробы действуют под грубым руководством вождя по имени Грамуг. В отличие от обычных разрозненных мародеров, эта стая нападает согласованно и грозит захватить Королевские земли, если ее не остановить. Атаковав их логово и убив Грамуга вместе с его личными головорезами, защитники-дворфы надеются разрушить сплоченность стаи и остановить натиск."},{t="В логово Камнедробов",b="Грамуг держит оборону в темной пещере в юго-восточных скалах Долины Камнедробов. В окружении самых верных громил, Грызуна и Драчуна, вождь представляет серьезную опасность для одиноких воинов. Убийство этого ближнего круга повергает остальных троггов в смятение и дает осажденным горцам столь необходимую возможность укрепить дороги и загнать тварей обратно в темные глубины."}},faq={{q="Кто такой Грамуг?",a="Грамуг — свирепый вождь троггов, объединивший троггов Камнедробов на юге Лок Модана. Дворфийские разведчики определили, что именно он стоит за организованными нападениями на долину; два грозных телохранителя, Грызун и Драчун, всегда находятся рядом с ним.",al={"grawmug lore","who is the trogg leader","chieftain grawmug","предания о грамуге","кто предводитель троггов","вождь грамуг"}},{q="Где находятся Грамуг и его стражи?",a="Грамуг, Грызун и Драчун засели в пещере на юго-восточной окраине Долины Камнедробов в Лок Модане. Все вместе они обитают в глубине пещеры.",al={"grawmug location","where is grawmug","where to find grawmug","где грамуг","где найти грамуга","местонахождение грамуга"}},{q="Кто такой капитан Ругельфасс?",a="Капитан Ругельфасс — дворфийский офицер, находящийся в Южной сторожевой башне в Лок Модане. Он руководит оборонительными кампаниями против наступающих троггов и отдает приказы по защите территориальной целостности Королевских земель.",al={"rugelfuss","captain rugelfuss role","who gives defense of the kings lands","ругельфасс","капитан ругельфасс","кто выдает защиту королевских земель"}},{q="Почему нужно убить и стражей Грамуга?",a="Грызун и Драчун — личные телохранители Грамуга, никогда не покидающие его. Чтобы устранить вождя и окончательно сломить руководство наступления троггов, нужно победить обоих тяжелых защитников вместе с их предводителем.",al={"why kill gnasher and brawler","gnasher and brawler","grawmug bodyguards","зачем убивать грызуна и драчуна","грызун и драчун","телохранители грамуга"}},{q="Что происходит после гибели Грамуга?",a="Убийство Грамуга приносит Лок Модану важное облегчение. Без вождя, координирующего набеги, трогги Камнедробы теряют организованность, и местное дворфийское ополчение получает шанс удержать границы и вытеснить тварей под землю.",al={"outcome of killing grawmug","troggs after grawmug dies","did we save loch modan","итог убийства грамуга","трогги после смерти грамуга","спасли ли лок модан"}},{q="Почему трогги вторгаются в Лок Модан?",a="Трогги давно гнездились в подземных пещерах под Каз Моданом. Раскопки и вскрытые пещеры позволили им хлынуть на поверхность, где они агрессивно вытесняют поселения и нападают на путников на королевских дорогах.",al={"why are troggs here","trogg invasion loch modan","stonesplinter trogg origin","почему здесь трогги","вторжение троггов в лок модан","откуда трогги камнедробы"}}},fp="30,391,22.553.0,23.450.0,15.278.0,41.171.0,25.246.0,43.231.0,41.266.1,35.241.0"}
P.entries["quest:2178"] = {n="Спокойная жизнь долгоногов",s="«Спокойная жизнь долгоногов» — местное кулинарное задание, которое выдает Аландариан Песня Ночи в Аубердине. Она охотно делится своим любимым рецептом похлебки из долгонога, если искатель приключений согласен выследить свирепых лесных долгоногов, бродящих по Темным берегам, и принести их мясо.",h="«Спокойная жизнь долгоногов» — местное кулинарное задание, которое выдает Аландариан Песня Ночи в Аубердине.",kw={"alanndarian nightsong","auberdine","cooking","darkshore","easy strider living","foreststrider","strider meat","strider stew","аландариан песня ночи","аубердин","кулинария","темные берега","спокойная жизнь долгоногов","лесной долгоног","мясо долгонога","похлебка из долгонога"},ang={["class:Hunter"]="Лесные долгоноги — одновременно быстрая дичь и возможные звери-спутники, что дает охотнику практику выслеживания на туманных тропах Темных берегов.",["profession:Cooking"]="Это задание важно для поваров, путешествующих по Темным берегам: наградой становится рецепт питательной похлебки из долгонога из местной дичи.",["race:NightElf"]="Жизнь в гармонии с природой Калимдора часто означает жизнь за счет земли, и сытная похлебка из долгонога стала прибрежной основой рациона для ночных эльфов Аубердина."},sec={{t="Вкус дикой природы",b="Аубердин — тихая портовая деревушка, но выживание на побережье требует умело пользоваться местной дичью. У Аландариан Песни Ночи есть секретный рецепт сытной похлебки из долгонога — наваристого блюда из высоких быстроногих лесных долгоногов, что рыщут в сумрачных лесах Темных берегов. Вместо того чтобы просто раздавать кулинарные секреты, она просит начинающих поваров и охотников самим отправиться в путь и добыть этих птиц."},{t="Охота на лесных долгоногов",b="Лесные долгоноги — быстрые пернатые хищники с острыми клювами, обитающие в окутанных туманом лесах и на побережье к северу и югу от Аубердина. Они бывают вспыльчивы и агрессивны, если их потревожить, но их сочное мясо — отличная основа для наваристой похлебки. Свежее мясо наполняет голодный котел Аландариан и приносит охотнику ее заветный рецепт."}},faq={{q="Кто такая Аландариан Песня Ночи?",a="Аландариан Песня Ночи — ночной эльф, жительница Аубердина на Темных берегах. Она известна своим кипящим котлом с похлебкой из долгонога и готова научить своему кулинарному искусству путников, доказавших свое охотничье мастерство.",al={"alanndarian","who is alanndarian nightsong","stew cook auberdine","аландариан","кто такая аландариан песня ночи","повар похлебка аубердин"}},{q="Где взять мясо долгонога?",a="Мясо долгонога добывают, охотясь на лесных долгоногов на Темных берегах. Эти крупные нелетающие птицы бродят и по песчаным берегам, и по лесным рощам возле Аубердина.",al={"strider meat location","where are foreststriders","how to get strider meat","где мясо долгонога","где лесные долгоноги","как добыть мясо долгонога"}},{q="В чем смысл этого задания?",a="В задании нужно выследить лесных долгоногов и принести пять кусков мяса для Аландариан Песни Ночи, а взамен вы узнаете, как приготовить похлебку из долгонога.",al={"why do easy strider living","quest purpose","easy strider living objective","спокойная жизнь долгоногов зачем","цель задания","спокойная жизнь долгоногов цель"}},{q="Опасно ли охотиться на лесных долгоногов?",a="Лесные долгоноги — территориальные птицы с острыми клювами и быстрыми ногами, поэтому при приближении они агрессивны. Однако достаточно хорошо экипированный искатель приключений справится с ними без особого риска.",al={"are striders hard to kill","foreststrider danger","сложно ли убить долгоногов","опасность лесных долгоногов"}},{q="Дает ли это задание рецепт для кулинарии?",a="Да. Когда вы приносите Аландариан нужное мясо, она делится кулинарными секретами и учит искателей приключений рецепту похлебки из долгонога.",al={"do i get recipe","strider stew recipe","cooking reward","получу ли рецепт","рецепт похлебки из долгонога","награда кулинария"}},{q="Где происходит это задание?",a="Задание начинается и заканчивается в поселении Аубердин, а охота проходит в диких местах Темных берегов.",al={"quest zone","where is easy strider living","зона задания","где спокойная жизнь долгоногов"}}},fp="19,267,19.430.0,26.361.0,29.202.0,33.176.0,34.165.0,41.196.0,40.133.0,33.119.0"}
P.entries["quest:218"] = {n="Украденные записи",s="«Украденные записи» — одно из первых заданий Альянса в Дун Мороге: Грелин Белобород просит искателей приключений проникнуть в пещеру троллей в Холодной долине и вернуть его украденный блокнот. Для этого вам нужно победить грозного предводителя троллей Грик'нира Холодного. Вернув записи, Грелин сможет завершить оценку угрозы троллей в Холодной долине.",h="«Украденные записи» — одно из первых заданий Альянса в Дун Мороге: Грелин Белобород просит искателей...",kw={"coldridge valley","dun morogh","frostmane hold","frostmane troll","grelin whitebeard","grik'nir the cold","senir whitebeard","stolen journal","холодная долина","дун морог","мерзлогривы","тролль мерзлогрив","грелин белобород","грик'нир холодный","сенир белобород","украденные записи"},ang={["faction:Alliance"]="Подавление агрессивного племени Мерзлогривов гарантирует, что стартовые долины Дун Морога останутся защищенными от внутренних беспорядков.",["race:Dwarf"]="Уничтожение предводителей Мерзлогривов в Холодной долине защищает юных дворфийских новобранцев, делающих первые шаги за пределами Старой Наковальни.",["race:Gnome"]="Гномы-беженцы, нашедшие приют в Старой Наковальне, полагаются на безопасность перевалов Холодной долины, пока перегруппировываются на землях дворфов."},sec={{t="Потерянные записи ученого",b="Грелин Белобород наблюдал за Мерзлогривами, проникающими в Холодную долину, и вел подробные записи об их повадках и внезапной агрессии. Во время беспорядков необычайно внушительный тролль похитил его личный дневник и скрылся в глубинах своего логова. Для Грелина это не просто сентиментальная потеря: в блокноте — основная часть его разведданных, и официальная оценка застопорилась, пока дневник не вернут из пещеры."},{t="Схватка с Грик'ниром Холодным",b="Похитил дневник Грик'нир Холодный — могучий тролль из племени Мерзлогривов с особой раскраской на теле и лице, правящий в сердце пещеры троллей долины. Убийство Грик'нира лишает пещерных троллей их ближайшего местного предводителя и возвращает дневник Грелина. Когда вожак повержен, Грелин уверенно сообщает, что положение с троллями в долине под контролем, и отправляет готовые выводы своему брату Сениру."}},faq={{q="Кто забрал дневник Грелина Белоборода?",a="Дневник забрал Грик'нир Холодный, крупный тролль из племени Мерзлогривов с необычными отметинами на коже и лице, затаившийся в глубине пещеры троллей.",al={"who stole the journal","who has grelin's journal","journal thief","кто украл дневник","у кого дневник грелина","вор дневника"}},{q="Где найти Грик'нира Холодного?",a="Грик'нир Холодный находится в пещере троллей на южных рубежах Холодной долины.",al={"where is griknir","grik'nir location","how to find grik'nir","где грик'нир","грик'нир местонахождение","как найти грик'нира"}},{q="Почему дневник важен для Грелина?",a="В дневнике хранятся записи и выводы Грелина Белоборода о действиях троллей в Холодной долине. Он нужен ему, чтобы составить полный отчет для брата Сенира.",al={"why does grelin want his journal","what is in grelin's journal","зачем грелину дневник","что в дневнике грелина"}},{q="Что будет после возвращения дневника?",a="Когда дневник найден, Грелин заканчивает отчет об оценке положения с троллями в Холодной долине и просит вас доставить его наблюдения брату, Сениру Белобороду, в Каранос.",al={"what is next after the stolen journal","stolen journal next quest","что дальше после украденных записей","украденные записи следующее задание"}},{q="Изгнаны ли Мерзлогривы из Холодной долины после этого?",a="Грелин считает, что после поражения Грик'нира положение с троллями в Холодной долине под контролем, хотя Мерзлогривы остаются постоянной угрозой на всех горных перевалах Дун Морога.",al={"are trolls defeated in coldridge","is coldridge safe from trolls","побеждены ли тролли в холодной долине","безопасна ли холодная долина от троллей"}},{q="Кто такой Сенир Белобород?",a="Сенир Белобород — брат Грелина, разведчик Альянса, дислоцированный за пределами Холодной долины близ Караноса, который собирает сведения об угрозах королевству.",al={"who is senir","grelin brother senir","кто такой сенир","брат грелина сенир"}}},fp="18,368,22.459.0,29.474.0,37.160.0,37.95.0,39.176.0,42.193.1,67.198.0,24.160.0"}
P.entries["quest:219"] = {n="Пропавший без вести",s="«Пропавший без вести» — задание Альянса на сопровождение в Красногорье: нужно спасти капрала Кеешана из плена орков клана Черной горы. После гибели его полка в холмах Кеешан потерял сознание и был утащен в пещерную крепость. Благополучное возвращение раненого солдата в Приозерье помогает местному гарнизону подтвердить мрачную судьбу пропавших.",h="«Пропавший без вести» — задание Альянса на сопровождение в Красногорье: нужно спасти капрала Кеешана из плена...",kw={"blackrock orcs","corporal keeshan","escort","keeshan","lakeshire","marshal marris","missing in action","redridge","орки черной горы","капрал кеешан","сопровождение","кеешан","приозерье","маршал маррис","пропавший без вести","красногорье"},ang={["class:Warrior"]="Чтобы вызволить Кеешана из вооруженного орочьего лагеря, нужно удерживать передовую против волн неутомимых воинов Черной горы и прикрывать контуженного товарища.",["faction:Alliance"]="Гарнизон Приозерья на пределе сил, поэтому каждый спасенный солдат жизненно важен для обороны королевства от клана Черной горы."},sec={{t="Разгромленный полк",b="В Красногорье становится все опаснее: орки Черной горы спускаются с северных вершин. Патрули городской стражи часто попадают в засады, и отряд капрала Кеешана пострадал сильнее всех. Окруженные превосходящим врагом, большинство солдат его полка были убиты на месте. Кеешан выжил лишь потому, что сокрушительный удар лишил его чувств до казни, и орки утащили его в свою пещеру пленником."},{t="Побег из пещер",b="Избитый, с контузией, в глубине вражеской территории, Кеешан не мог сам спуститься с горы. Путь вниз, в безопасное Приозерье, ведет мимо многочисленных орочьих отрядов, занявших гребни хребтов. Живым добраться до Ратуши — значит принести долгожданное облегчение маршалу Маррису, который пытался выяснить судьбу пропавшего полка и готовил Приозерье к новым нападениям."}},faq={{q="Кто такой капрал Кеешан?",a="Капрал Кеешан — пехотинец Альянса, расквартированный в Красногорье. Во время патруля в скалистых холмах его полк был разгромлен орками Черной горы, и он остался единственным известным выжившим, прежде чем его утащили в плен.",al={"corporal keeshan","who is keeshan","keeshan lore","капрал кеешан","кто такой кеешан","предания о кеешане"}},{q="Где был схвачен капрал Кеешан?",a="Его держат в плену в глубине кишащей орками пещеры в северных холмах Красногорья, в окружении враждебных воинов Черной горы.",al={"where is keeshan","keeshan location","keeshan cave","где кеешан","местонахождение кеешана","пещера кеешана"}},{q="Что случилось с остальным отрядом Кеешана?",a="По словам Кеешана, орки Черной горы напали из засады и одолели его полк, убив почти всех во время первой стычки.",al={"keeshan squad","what happened to the regiment","keeshan men","отряд кеешана","что случилось с полком","люди кеешана"}},{q="Кто посылает игроков спасать Кеешана?",a="Задание выдает сам капрал Кеешан в своей пещере-темнице, когда искатели приключений Альянса находят и освобождают его.",al={"who starts missing in action","quest giver","where to pick up missing in action","кто дает пропавший без вести","персонаж, выдающий задание","где взять пропавший без вести"}},{q="Куда направляется Кеешан после освобождения?",a="Его нужно сопроводить вниз по склону горы в Приозерье, где он докладывает маршалу Маррису в ратуше.",al={"turn in missing in action","where does keeshan run","keeshan destination","сдать пропавший без вести","куда бежит кеешан","куда идти кеешану"}},{q="Почему орки Черной горы оказались в Красногорье?",a="Клан Черной горы продвигается на юг из своих крепостей в Пылающих степях в Красногорье, угрожая слабо укрепленному Приозерью и устраивая засады на патрули королевства.",al={"blackrock orcs redridge","why orcs in lakeshire","blackrock invasion","орки черной горы красногорье","почему орки в приозерье","вторжение черной горы"}}},fp="17,365,18.474.0,21.424.0,24.243.0,36.128.0,44.138.0,36.131.0,40.123.0,39.181.0"}
P.entries["quest:22"] = {n="Пирог из печени жутеклыка",s="«Пирог из печени жутеклыка» — кулинарное поручение Сальмы Сальден на ферме Сальденов в Западном Крае. Житница королевства разорена засухой и бандитами, и местные хуторяне охотятся на свирепых кабанов, чтобы накормить семью. Помощь Сальме дарит редкую толику уюта и домашнего гостеприимства на суровом пограничье.",h="«Пирог из печени жутеклыка» — кулинарное поручение Сальмы Сальден на ферме Сальденов в Западном Крае.",kw={"boar","cooking","goretusk","liver pie","saldean farm","salma saldean","westfall","кабан","кулинария","жутеклык","пирог из печени","ферма сальденов","сальма сальден","западный край"},ang={["faction:Alliance"]="Помощь сельским хуторянам вроде Сальденов напрямую поддерживает верные людские семьи, пытающиеся удержать пограничье королевства в отсутствие армии Штормграда.",["profession:Cooking"]="Блюдо Сальмы иллюстрирует традиционную сельскую людскую кухню: огородные ароматные травы — чеснок, розмарин и укроп — превращают потроха дичи в сытное повседневное блюдо."},sec={{t="Гостеприимство пограничья",b="Западный Край был плодородной житницей Штормграда, но последние годы принесли трудные времена. Из-за запущенной инфраструктуры, бродячих разбойников и заросших полей жизнь немногих оставшихся поселенцев стала тяжелой. На ферме Сальденов Сальма Сальден неустанно трудится, чтобы сохранить дух домашнего очага, несмотря на растущие опасности. Приготовление традиционного мясного пирога — одна из немногих скромных радостей, доступных хуторянам, стремящимся сохранить свой уклад."},{t="Дикие звери Западного Края",b="Равнины Западного Края кишат жутеклыками — свирепыми дикими кабанами с прочной шкурой и грозными клыками. Они опасны для одиноких работников, но и служат жизненно важным источником мяса для семей, отрезанных от торговли. По рецепту Сальмы требуется тщательная подготовка — толченый розмарин, рубленый чеснок, измельченный укроп и томящаяся подливка, — чтобы превратить острые на запах потроха этих выносливых зверей в сытное, наваристое угощение."}},faq={{q="Кто такая Сальма Сальден?",a="Сальма Сальден — стойкая хуторянка, живущая с мужем, фермером Сальденом, на их ферме в центральной части Западного Края. Она известна своей домашней стряпней и делает все, чтобы поддерживать бодрость духа, несмотря на опасность от бандитов и диких зверей.",al={"salma saldean","who is salma","saldean wife","сальма сальден","кто такая сальма","жена сальдена"}},{q="Зачем Сальме печень жутеклыка?",a="Сальма готовит свой знаменитый мясной пирог, чтобы разделить его с мужем. Корж уже испечен, приправы готовы, не хватает только печени местных жутеклыков, чтобы дотомить начинку.",al={"why goretusk liver","what is the pie made of","liver pie purpose","зачем печень жутеклыка","из чего пирог","цель пирога из печени"}},{q="Где в Западном Крае обычно встречаются жутеклыки?",a="Жутеклыки широко бродят по золотым равнинам и заброшенным фермерским участкам Западного Края, роются на брошенных полях и ходят по грунтовым дорогам.",al={"goretusk locations","where to find boars","goretusk liver hunt","где жутеклыки","где найти кабанов","охота на печень жутеклыка"}},{q="Опасны ли жутеклыки для местных фермеров?",a="Да. Жутеклыки — свирепые территориальные дикие кабаны с острыми клыками. Они представляют серьезную угрозу для скота и незащищенных путников на равнинах.",al={"are goretusks hostile","boar danger westfall","враждебны ли жутеклыки","опасность кабанов западный край"}},{q="Почему сейчас в Западном Крае так мало еды?",a="Сочетание губительных засух, отсутствия королевской поддержки из Штормграда и набегов организованных бандитов вынудило многих фермеров покинуть свои земли, превратив бывшую житницу королевства в нищее, борющееся за жизнь пограничье.",al={"westfall famine","why no food westfall","westfall hard times","голод в западном крае","почему нет еды в западном крае","тяжелые времена западный край"}},{q="Помогает ли выполнение этого задания ферме Сальденов выжить?",a="Хотя оно не решает более широких бед Западного Края, добыча свежего мяса напрямую кормит семью Сальденов и дает путникам сытный паек в дорогу.",al={"does the pie matter","saldean food supply","важен ли пирог","запасы еды сальденов"}}},fp="18,375,20.494.0,23.417.0,21.245.0,36.213.0,48.163.0,45.169.0,44.233.0,56.180.0"}
P.entries["quest:220"] = {n="Зов воды",s="Этот этап шаманского испытания поручает новичку принести очищенную воду через Степи к Ислен Заклинательнице Воды. Фиал приготовила и благословила затворница Брин, и в нем содержится катализатор, необходимый для перегонки духовной сапты. Когда отвар будет готов, он откроет духов стихий, обитающих в дальних водах Серебряного бора.",h="Этот этап шаманского испытания поручает новичку принести очищенную воду через Степи к Ислен Заклинательнице...",kw={"brine","call of water","islen waterseer","sapta","silverpine forest","the barrens","vial of purest water","water sapta","water totem","брин","зов воды","ислен заклинатель воды","сапта","серебряный бор","степи","фиал с чистейшей водой","сапта воды","тотем воды"},ang={["class:Shaman"]="Каждый шаман Орды должен пройти обряды Зова Воды, чтобы общаться с духами и заслужить право носить Тотем воды, управляющий исцелением и восполнением сил.",["faction:Horde"]="Испытание охватывает Калимдор и Лордерон и показывает географический размах Орды: юные неофиты отправляются из Степей в Серебряный бор, контролируемый Отрекшимися."},sec={{t="Возвращение к берегу",b="Пройдя через южные Степи и выполнив испытания Брин, неофит-шаман получает Фиал с чистейшей водой. Наполненный из нетронутых источников и освященный уединенными обрядами Брин, этот сосуд воплощает чистую силу стихии. Бережно донести его до восточного побережья, где несет стражу Ислен Заклинатель Воды, — важнейшее звено, соединяющее простую мудрость Брин с формальными обрядами тотема."},{t="Назначение сапты",b="Получив чистую воду, Ислен объясняет, что смертным нелегко увидеть неуловимых духов воды. Чтобы говорить с ними, неофит должен выпить особый отвар — сапту. Жидкость, принесенная от Брин, станет мощной основой этого зелья и откроет чувства шамана для сил, скрытых от обычного взора. Но, предостерегает Ислен, общение — лишь половина пути: сами духи требуют испытания."},{t="Путь в Лордерон",b="Ислен сообщает, что завершение испытания произойдет не на засушливых просторах Калимдора. Шаман должен отправиться далеко за море, к древним, окутанным туманом берегам Серебряного бора, к югу от Подгорода. Там, возле уединенного святилища, нужно выпить сапту, чтобы неофит мог лицом к лицу встретиться со стихиями и заслужить право призвать Тотем воды."}},faq={{q="Что находится в Фиале с чистейшей водой?",a="В фиале находится вода, которую новичок собрал из чистых источников и освятил обрядами отшельницы Брин. Это неоскверненная стихийная вода, необходимая для приготовления алхимической сапты, позволяющей общаться с духами воды.",al={"vial of purest water","brine's water","what did brine give me","фиал с чистейшей водой","вода брина","что дал мне брин"}},{q="Кто такая Ислен Заклинатель Воды?",a="Ислен Заклинатель Воды — старейшая шаманка, живущая на уединенном юго-восточном побережье Степей, к югу от Кабестана. Она — главная наставница шаманов Орды, стремящихся постичь стихию воды и получить свой Тотем воды.",al={"islen","who is islen waterseer","islen waterseer lore","ислен","кто такая ислен заклинатель воды","ислен заклинатель воды предания"}},{q="Что такое сапта?",a="Сапта — церемониальный отвар, который готовят наставники-шаманы. После его употребления меняется восприятие пьющего, и шаман ясно видит духов стихий, невидимых для обычного зрения, и может взаимодействовать с ними.",al={"sapta meaning","water sapta","what does sapta do","что такое сапта","сапта воды","что делает сапта"}},{q="Почему мне нужно идти в Серебряный бор?",a="Стихийное святилище, связанное с этим обрядом, находится в прибрежных водах Серебряного бора, к югу от Подгорода в Восточных королевствах. Обитающие там духи требуют общения и последнего испытания, прежде чем даруют власть над своей стихией.",al={"why silverpine","silverpine water totem","shrine in silverpine","почему серебряный бор","тотем воды серебряный бор","святилище в серебряном бору"}},{q="Где живет Брин?",a="Брин живет в уединенной хижине высоко в холмах южных Степей, к западу от дороги, ведущей вниз к Великому Подъемнику и в Тысячу Игл.",al={"brine location","where is brine","finding brine","где брин","местонахождение брина","как найти брина"}},{q="Может ли шаман обойтись без приготовления сапты?",a="Нет. Обряды общения требуют, чтобы дух шамана был настроен на незримый мир. Без восприятия, которое дает сапта, к духам воды в святилище невозможно обратиться или бросить им вызов.",al={"skip sapta","is sapta required","shaman vision quest","пропустить сапту","нужна ли сапта","шаманское задание на видение"}}},fp="13,347,19.429.0,24.445.0,23.397.1,40.257.0,23.238.0,16.225.0,46.247.0,22.146.0,39.206.0"}
P.entries["quest:2205"] = {n="Выход на ШРУ",s="Выход на ШРУ — вводное задание, которое Керин Сильвиус дает начинающим разбойникам в Элвиннском лесу. Неся небольшой сверток из Златоземья в Штормград, новички знакомятся с Мастером Матиасом Шоу, главой тайной разведывательной сети короны.",h="Выход на ШРУ — вводное задание, которое Керин Сильвиус дает начинающим разбойникам в Элвиннском лесу.",kw={"goldshire","keryn sylvius","mathias shaw","old town","rogue","seek out si: 7","si:7","stormwind","златоземье","керин сильвиус","матиас шоу","старый город","разбойник","выход на шру","шру","штормград"},ang={["class:Rogue"]="Это задание знаменует официальное вступление разбойника на службу в ведущую шпионскую организацию Штормграда: от мелких трюков в подворотнях к королевской разведке.",["faction:Alliance"]="ШРУ служит глазами и ушами короны против внутренних и внешних угроз, тихо защищая королевство, пока король Вариан Ринн пропал."},sec={{t="Проверка курьера",b="В таверне Гордость Льва в Златоземье наставница разбойников Керин Сильвиус не тратит время на комплименты новичкам. Считая, что свежие новобранцы больше похожи на разносчиков сыра, чем на способных тайных агентов, Сильвиус все же поручает им дело: доставить запечатанную посылку в столицу. Это задание — и надежная курьерская работа, и негласная проверка разведчиков, вступающих на более широкую службу королевства."},{t="За закрытыми дверями Старого города",b="Пункт назначения находится в глубине Старого города — шумного и обветшалого квартала Штормграда. В юго-восточном углу района расположен штаб ШРУ — Штормградской разведывательной управы, седьмого отдела. Здесь Мастер Матиас Шоу руководит тайными операциями королевства. Приняв посылку со свойственным ему сухим скепсисом, Шоу оценивает, хватит ли путнику стойкости для настоящего шпионажа."}},faq={{q="Что такое ШРУ?",a="ШРУ — это Штормградская разведывательная управа, седьмой отдел. Это тайная разведывательная служба Королевства Штормград, занимающаяся скрытными операциями; ее возглавляет Мастер Матиас Шоу, а штаб находится в Старом городе.",al={"what does si 7 mean","what is si7","si:7 lore","что значит шру","что такое шру","шру предания"}},{q="Кто такая Керин Сильвиус?",a="Керин Сильвиус — наставница разбойников в Златоземье, в таверне Гордость Льва. Действуя в связи с ШРУ, она оценивает местных новобранцев и направляет перспективных разведчиков к Мастеру Матиасу Шоу в Штормград.",al={"keryn sylvius","goldshire rogue trainer","керин сильвиус","наставник разбойников златоземье"}},{q="Где в Штормграде находится Матиас Шоу?",a="Мастера Матиаса Шоу можно найти на верхнем этаже штаба ШРУ, в юго-восточном углу Старого города в Штормграде, за местными наставниками разбойников.",al={"where is shaw","find mathias shaw","mathias shaw location","где шоу","найти матиаса шоу","местонахождение матиаса шоу"}},{q="Что происходит после доставки посылки Шоу?",a="Когда вы докладываете Матиасу Шоу, он тут же проверяет ваши практические навыки разбойника, отправляя вас на тайную операцию в Лагерь Джерода, чтобы выкрасть расписание поставок у начальника порта Братства Справедливости.",al={"next quest after seek out si 7","what does shaw want","следующее задание после выхода на шру","что нужно шоу"}},{q="Почему Керин насмехается над игроком, прежде чем передать посылку?",a="Агенты ШРУ гордятся своей компетентностью и острым чутьем. Сильвиус сурово обходится с новобранцами, чтобы оценить их характер и сделать так, чтобы Мастера Шоу беспокоили лишь те, у кого толстая кожа и настоящая решимость.",al={"why does keryn insult me","cheese delivery insult","почему керин оскорбляет меня","оскорбление про сыр"}}},fp="14,267,16.414.0,31.426.0,13.207.0,21.216.0,43.175.0,50.191.1,64.212.0"}
P.entries["quest:2206"] = {n="Держи-хватай!",s="Держи-хватай! — тайное поручение, которое Мастер Матиас Шоу, глава ШРУ, дает перспективным разбойникам. Оно требует проникнуть в Лагерь Джерода и выкрасть сведения о поставках Братства Справедливости.",h="Держи-хватай!",kw={"crystal lake","defias","dockmaster","goldshire","jerod's landing","mathias shaw","shipping schedule","si:7","snatch and grab","кристальное озеро","братство справедливости","начальник порта","златоземье","лагерь джерода","матиас шоу","расписание поставок","шру","держи-хватай"},ang={["class:Rogue"]="Это задание знаменует официальное знакомство разбойника с ШРУ: проверяя скрытность и воровские навыки, оно приносит признание и фирменный клинок от Матиаса Шоу.",["faction:Alliance"]="Перехват цепочек поставок Братства Справедливости в Лагере Джерода защищает Элвиннский лес и подтачивает преступный синдикат, угрожающий окрестным землям Штормграда."},sec={{t="Проверка мастерства",b="Для начинающего агента в Штормграде встреча с Мастером Матиасом Шоу — настоящая проверка на право вступить в тайное разведывательное крыло королевства. Вместо грубой силы Шоу требует доказательств ловкости и скрытности. Тихо устранять ключевые фигуры и добывать важные бумаги, не втягивая королевство в открытый скандал, — основная задача ШРУ, и это задание служит новичку испытательным полигоном."},{t="Контрабандисты на реке",b="Лагерь Джерода расположен на реке на юге Элвиннского леса, к югу от Златоземья и сразу к востоку от Виноградников Маклура. Когда-то это была тихая местная пристань, но Братство Справедливости захватило ее, чтобы устроить тайный транзитный путь. Перевозя по воде контрабандное оружие, припасы и запрещенные товары из Красногорья в сторону Западного Края, воры полностью обходят королевские дорожные патрули."},{t="Правдоподобное отрицание",b="Прежде чем отправить агентов в поле, Шоу предельно ясно излагает постоянную доктрину ШРУ: если агента схватят, раскроют или убьют, корона и ее главы шпионов отрекутся от любого знания о его существовании. Добыв расписание начальника порта Братства Справедливости, агент получает важное доказательство путей снабжения Братства, а официальная причастность Штормграда остается в тени."}},faq={{q="Кто выдает задание «Держи-хватай!»?",a="Мастер Матиас Шоу, глава разведывательной службы Штормграда ШРУ, выдает это задание в штабе ШРУ в Старом городе.",al={"who gives snatch and grab","quest giver snatch grab","кто дает держи-хватай","персонаж, выдающий задание держи-хватай"}},{q="Где находится Лагерь Джерода?",a="Лагерь Джерода — пристань на реке на юге Элвиннского леса, к югу от Златоземья и сразу к востоку от Виноградников Маклура. Братство Справедливости захватило тамошние причалы и портовый домик.",al={"jerods landing location","where is jerod's landing","dockmaster location","где лагерь джерода","расположение лагеря джерода","где начальник порта"}},{q="Что Братство Справедливости провозит контрабандой через Лагерь Джерода?",a="Братство Справедливости использует Лагерь Джерода для переправки по воде крупных партий контрабанды и припасов между Красногорьем и Западным Краем в обход сторожевых постов и дорожных застав королевства.",al={"what are they smuggling","defias contraband","что они провозят","контрабанда братства справедливости"}},{q="У кого находится Расписание поставок Братства Справедливости?",a="Расписание поставок есть у начальника порта Братства Справедливости, которого можно найти у портового домика в Лагере Джерода.",al={"where is shipping schedule","who drops schedule","defias dockmaster","где расписание поставок","у кого расписание","начальник порта братства справедливости"}},{q="Что будет, если агента схватят во время этого задания?",a="Как предупреждает Мастер Матиас Шоу, ШРУ действует в условиях строгого правдоподобного отрицания. Если агента раскроют или схватят, ШРУ откажется от любой связи с ним.",al={"what happens if i fail","disavowed by si7","что будет если провалюсь","шру отрекается"}},{q="Почему ШРУ интересует это расписание поставок?",a="В документе подробно описано, как Братство Справедливости перевозит контрабанду между Красногорьем и Западным Краем. Заполучив его, разведка Штормграда сможет составить карту снабжения врага, не насторожив преступный синдикат.",al={"why need schedule","si7 shipping schedule","зачем нужно расписание","расписание поставок шру"}}},fp="15,223,20.422.0,22.390.0,21.390.0,38.132.0,25.200.0,54.184.0,41.119.0,61.160.0,48.206.0"}
P.entries["quest:222"] = {n="Воргены в лесу",s="Пока стая Ночной Погибели крепче сжимает хватку на Сумеречном лесу, Калор направляет искателей приключений против самых опасных ее рядов. Нападая прямо на южные логова и шахты, защитники отбрасывают дикую угрозу от Темнолесья.",h="Пока стая Ночной Погибели крепче сжимает хватку на Сумеречном лесу, Калор направляет искателей приключений...",kw={"calor","carevin","darkshire","duskwood","nightbane","tainted one","vile fang","worgen","калор","карвин","темнолесье","сумеречный лес","ночная погибель","оскверненный","мерзкий клык","ворген"},ang={["class:Hunter"]="Хитрость стаи Ночной Погибели делает ее неестественной добычей и требует бдительности от следопытов, забредающих близ ее темных логовищ.",["faction:Alliance"]="Темнолесье стоит изолированно на мрачном юге королевства; зачистка южных пещер помогает защитить хрупкие линии снабжения и оставшиеся усадьбы Сумеречного леса."},sec={{t="Дикий плацдарм",b="Нашествие воргенов в Сумеречном лесу — далеко не бессмысленный хаос. Захватив земли в темных просторах к югу от Темнолесья, звери, известные как Ночная Погибель, начали устраивать укрепленные лагеря. Калор с растущим ужасом наблюдает, как вдали мерцают их костры, и отмечает, что твари заняли глубокие пещеры и заброшенные шахты. Среди них Мерзкие Клыки и Оскверненные — самые злобные породы, проявляющие свирепую дикость и упорство, грозящие смять оборону города."},{t="Рекомендация Калора",b="Калор — бдительный вербовщик на передовой обороны Темнолесья, хотя и не питает иллюзий насчет ужасной природы волкоподобных захватчиков. Сломить хребет Мерзким Клыкам и Оскверненным — испытание для любого героя. Те, кому удается перебить эти закаленные стаи, получают больше, чем просто монеты: они завоевывают уважение Калора и его личную рекомендацию мастеру Карвину, замкнутому человеку, координирующему более широкое наступление на воргенов."}},faq={{q="Где находятся Мерзкие Клыки и Оскверненные?",a="Эти опасные породы стаи Ночной Погибели собираются у пещер и шахты на юге Сумеречного леса, часто вокруг заметных костров.",al={"where are tainted ones","where are vile fangs","worgen locations duskwood","где оскверненные","где мерзкие клыки","воргены сумеречный лес"}},{q="Кто такой Калор?",a="Калор — преданный житель Темнолесья, следящий за угрозой воргенов в лесу и привлекающий способных искателей приключений, чтобы остановить натиск тварей.",al={"calor darkshire","who gives worgen in the woods 3","калор темнолесье","кто выдает воргены в лесу 3"}},{q="Кто такой мастер Карвин?",a="Master Carevin is Jonathan Carevin of Darkshire, whose family takes the fight to the region's evils, and who coordinates efforts to eradicate the worgen threat from the surrounding region.",al={"master carevin","carevin duskwood","мастер карвин","карвин сумеречный лес"}},{q="Почему у воргенов есть костры?",a="Несмотря на чудовищный, волкоподобный облик, воргены Ночной Погибели проявляют тревожный разум: собираются в организованные лагеря, используют огонь и удерживают укрепленные позиции вроде шахт.",al={"why do worgen make fires","nightbane bonfires","зачем воргены разводят костры","костры ночной погибели"}},{q="Что будет после завершения этой охоты?",a="Впечатлив Калора, вы получите рекомендательное письмо, которое направит вас прямо к мастеру Карвину, чтобы помочь ему на следующем этапе охоты.",al={"next quest after worgen in the woods 3","worgen in the woods follow up","следующее задание после воргены в лесу 3","воргены в лесу продолжение"}},{q="Почему Темнолесье так тревожат именно эти воргены?",a="Мерзкие Клыки и Оскверненные — одни из самых смертоносных и агрессивных членов стаи. Если оставить их без присмотра возле южных шахт, звери могут полностью заполонить окрестные дороги.",al={"why nightbane vile fang","vile fang danger","почему мерзкие клыки ночной погибели","опасность мерзких клыков"}}},fp="19,242,16.538.0,19.475.1,50.158.0,13.150.0,22.188.0,32.189.0,40.135.0,58.205.0"}
P.entries["quest:223"] = {n="Воргены в лесу",kw={"calor","calor's note","darkshire","duskwood","jonathan carevin","night watch","worgen in the woods","калор","записка калора","темнолесье","сумеречный лес","джонотан карвин","ночной дозор","воргены в лесу"},ang={["class:Paladin"]="Карвин приветствует проверенных союзников призывами к Свету, ища святых защитников, готовых стойко противостоять разгулу нечестивого зла Сумеречного леса.",["class:Priest"]="Прощальное благословение Карвина «Слава под Светом» отражает отчаянную веру оставшихся защитников Темнолесья перед лицом нескончаемой темной порчи.",["faction:Alliance"]="Поскольку Королевство Штормград не может выделить солдат для окраин Сумеречного леса, независимые искатели приключений Альянса и мстители вроде Карвина — единственная линия обороны города."},sec={{t="Редкая рекомендация",b="Перебив стаю Ночной Погибели, рыщущую у Погибели Роланда и в тенистых лощинах, вы заслужили нелегкое уважение Калора. Он стоит на темных рубежах леса и редко спешит раздавать похвалы, а тем более формальные рекомендации. Передав вам выцветший клочок пергамента, он велит доставить его слово прямо Джонотану Карвину в Темнолесье и замечает, что будь у них больше таких бойцов, как вы, их небольшой отряд мог бы наконец затмить злосчастный Ночной Дозор города."},{t="Бдение Карвина",b="Jonathan Carevin operates within Darkshire under tremendous strain, wary of outsiders and perpetually pressed for time. The town faces onslaughts not only from slavering worgen, but also from unresting undead, shadowy demonic forces, and traitorous cultists aiding the corruption from within. Receiving Calor's glowing endorsement breaks Carevin's cold demeanor, confirming you as a trustworthy blade dedicated to preserving the Light against the suffocating terrors of Duskwood."}},faq={{q="Кто посылает меня с этим поручением?",a="Calor sends you on this errand. Having observed your success against the voracious worgen packs throughout Duskwood, he provides you with a faded note of recommendation to carry to his associate, Jonathan Carevin.",al={"quest giver","who starts this","calor","персонаж, выдающий задания","кто начинает это задание","калор"}},{q="Who is Jonathan Carevin?",a="Джонотан Карвин — мрачный, предельно сосредоточенный житель Темнолесья, координирующий борьбу со сверхъестественным злом, угрожающим городу. Хотя он с опаской относится к чужакам, он работает бок о бок с надежными людьми вроде Калора, чтобы искоренить нежить, демонов и пособников, им помогающих.",al={"carevin","who is carevin","master carevin","карвин","кто такой карвин","мастер карвин"}},{q="Почему Калор так пренебрежительно относится к Ночному Дозору?",a="Калор намекает, что официальный Ночной Дозор города испытывает трудности и слишком растянут, чтобы справиться со всем разнообразием ужасов, вторгшихся в Сумеречный лес. Он считает, что несколько способных, преданных бойцов, действующих вне формальной бюрократии, добьются гораздо большего против наступающих теней.",al={"calor night watch","outnumber the night watch","why compete with night watch","калор ночной дозор","числом превосходить ночной дозор","почему соперничать с ночным дозором"}},{q="О каких угрозах предупреждает Карвин при доставке?",a="Прочитав рекомендацию, Карвин предупреждает, что Темнолесье сталкивается с угрозами со всех сторон: голодными воргенами, бродячей нежитью, вторгающимися демонами и коварными культистами или пособниками, помогающими им. Он советует вам всегда быть начеку и доверять только проверенным союзникам.",al={"carevin enemies","what does carevin say","what are we fighting","враги карвина","что говорит карвин","с кем мы сражаемся"}},{q="Нужно ли в этом задании сражаться?",a="Нет. Этот заключительный шаг — полностью поручение на доставку. После опасных охот на воргенов Ночной Погибели по всему Сумеречному лесу в предыдущих частях цепочки от вас требуется лишь благополучно донести записку Калора до Карвина в Темнолесье.",al={"any fighting","do i kill anything","delivery only","нужно ли сражаться","надо ли кого-то убивать","только доставка"}},{q="Где найти Джонотана Карвина?",a="Джонотана Карвина можно найти в городе Темнолесье в Сумеречном лесу, где он занят неотложными делами, связанными с шаткой обороной города.",al={"carevin location","where is carevin","where to turn in","где карвин","карвин расположение","куда сдавать задание"}}},fp="19,285,21.503.0,15.479.0,29.213.0,24.271.0,46.276.0,51.271.0,35.246.0,34.140.0"}
P.entries["quest:224"] = {n="Защита королевских земель",s="Горный пехотинец Кремневик охраняет южную башню в Долине Королей и отчаянно ищет помощи против наступающих троггов Камнедробов. Поскольку армия Стальгорна занята на дальних фронтах, оборона южных перевалов Лок Модана ложится на плечи проходящих мимо добровольцев Альянса.",h="Горный пехотинец Кремневик охраняет южную башню в Долине Королей и отчаянно ищет помощи против наступающих...",kw={"cobbleflint","gravelgaw","ironforge","loch modan","mountaineer","stonesplinter","trogg","valley of kings","кремневик","булыжный карьер","стальгорн","лок модан","горный пехотинец","камнедроб","трогг","долина королей"},ang={["class:Hunter"]="Скалы и уступы Долины Камнедробов — идеальная местность, чтобы с высоты выбивать агрессивных троггов-часовых и разведывательные отряды.",["faction:Alliance"]="Помощь в защите Долины Королей показывает силу союза Альянса: он откликается на призыв Стальгорна, когда войска дворфов направлены на дальние союзные фронты.",["race:Dwarf"]="Для дворфов-искателей приключений ответ на призыв Кремневика — вопрос защиты родины: нужно не дать подземным тварям захватить исконные долины короля Магни, пока армия сражается в других местах."},sec={{t="Тонкая линия обороны в Долине Королей",b="Огромные дворфийские монументы, высеченные в горах Долины Королей, нависают над гарнизоном, находящимся под тяжелым давлением. Горный пехотинец Кремневик и его товарищи, несущие службу в южной сторожевой башне, сталкиваются с растущим нашествием троггов, выбирающихся из-под земли. Поскольку значительная часть регулярной армии короля Магни Бронзоборода отправлена за границу ради союзнических обязательств перед Альянсом, тыл в основном полагается на местные патрули и наемных бойцов, чтобы не дать захватить провинцию."},{t="Вторжение Камнедробов",b="Подземная угроза исходит из Долины Камнедробов — скалистого ущелья, врезающегося в южные пики Лок Модана. Троггов и их разведчиков вышло на поверхность огромное множество, и вдоль дна долины они устроили укрепленные лагеря. Если их не остановить, их разведывательные отряды будут угрожать важным дорогам, соединяющим Лок Модан с южными перевалами, и горцам придется вести непрерывную войну на истощение."}},faq={{q="Почему гарнизон в Лок Модане так малочисленен?",a="Король Магни Бронзобород направил значительную часть армии Стальгорна на дальние поля сражений и в форпосты Альянса по всему Азероту. Из-за этого родные земли, такие как Лок Модан, защищены в основном легкими патрулями горных пехотинцев, которым приходится звать странствующих искателей приключений, чтобы остановить местные вторжения.",al={"why so few guards","where are ironforge soldiers","why undermanned","почему так мало стражей","где солдаты стальгорна","почему не хватает людей"}},{q="Кто такой горный пехотинец Кремневик?",a="Горный пехотинец Кремневик — дворф-часовой на южной сторожевой башне в Долине Королей. Он координирует охрану периметра вдоль южной границы Лок Модана и руководит контратаками против гнездящихся племен троггов.",al={"cobbleflint","who gives quest","quest giver","кремневик","кто выдает задание","персонаж, выдающий задания"}},{q="Где находится Долина Камнедробов?",a="Долина Камнедробов находится к югу от Телсамара; вход в нее расположен у главной дороги, перед огромными статуями дворфов в Долине Королей. Несколько лагерей троггов раскинулись на ее скалистом дне.",al={"stonesplinter location","where are troggs","find stonesplinter valley","где камнедробы","где находятся трогги","как найти долину камнедробов"}},{q="Чем трогги так опасны для дворфов?",a="Трогги — агрессивные подземные громилы, которые прокладывают ходы сквозь сплошную скалу и обходят обычные наземные стены и укрепления. Поскольку они могут внезапно вырваться из-под земли под дорогами, поселениями и шахтами, власти дворфов видят в их безудержном росте смертельную угрозу безопасности Стальгорна.",al={"trogg threat","why fight troggs","are troggs dangerous","угроза троггов","зачем сражаться с троггами","опасны ли трогги"}},{q="К кому обратиться после помощи Кремневику?",a="After thinning the ranks of the Stonesplinter troggs and scouts, Cobbleflint directs you to Mountaineer Gravelgaw, stationed just inside the adjacent watchtower, who manages the next phase of the patrol along the valley front.",al={"next quest","where to go after","gravelgaw"}},{q="Организованы ли трогги Камнедробы?",a="Хотя клан Камнедробов примитивен, он проявляет зачатки организации: специальные разведчики осматривают дороги, а грубые пехотинцы держат оборонительные лагеря по всему ущелью.",al={"trogg scouts","are troggs smart","stonesplinter structure","разведчики троггов","умны ли трогги","устройство камнедробов"}}},fp="30,289,34.477.0,27.426.0,49.323.0,31.239.0,38.219.0,54.314.0,44.226.0,39.218.0"}
P.entries["quest:2242"] = {n="Зов судьбы",s="Зов судьбы — тайное расследование, которое поручает Сиарна, чтобы найти источник порчи, проникающей в ветви Тельдрассила. Лазутчику нужно проскользнуть мимо враждебного сатира Сетира Древнего возле Поляны Оракула или сразиться с ним и забрать его дневник.",h="Зов судьбы — тайное расследование, которое поручает Сиарна, чтобы найти источник порчи, проникающей в ветви...",kw={"darkshore","darnassus","destiny calls","journal","oracle glade","satyr","sethir the ancient","syurna","teldrassil","темные берега","дарнасс","зов судьбы","дневник","поляна оракула","сатир","сетир древний","сиарна","тельдрассил"},ang={["class:Rogue"]="Это задание, которое дают наставники скрытности Дарнасса, проверяет умение лазутчика выкрасть важные сведения прямо из-под носа опасного сатира.",["faction:Alliance"]="Открытие связывает местные лесные беды Тельдрассила с порчей на всем материке и подготавливает почву для сил Альянса, отправляющихся на север Калимдора.",["race:NightElf"]="Для защитников-кальдораев весть о том, что древнее проклятие Темных берегов пересекло море и достигло Тельдрассила, означает тревожную угрозу их священному убежищу."},sec={{t="Тихая разведка",b="Руководство ночных эльфов в Дарнассе с тихой тревогой наблюдает за растущим недугом Тельдрассила. Вместо вооруженных патрулей, которые гибнут, наставница разбойников Сиарна ищет того, кто способен на тонкую работу. Сатир Сетир Древний, обосновавшийся на удаленной ветви возле Поляны Оракула, отразил все попытки как силы, так и дипломатии. Чтобы узнать, что ему известно, нужно проникнуть в его логово и завладеть его личными вещами."},{t="Надвигающаяся тень с Темных берегов",b="Найденные страницы дневника Сетира приносят мрачные открытия. Коварная порча, угрожающая юному Мировому Древу, напрямую связана с древней гнилью и скверной, пожирающими леса и воды за туманным морем, на Темных берегах. Это не болезнь одной лишь почвы: недуг указывает на более широкую, намеренную злую волю, угрожающую сердцу земель кальдораев."}},faq={{q="Кто такой Сетир Древний?",a="Сетир Древний — неуловимый сатир, скрывающийся на ветви у северных окраин Поляны Оракула в Тельдрассиле. Враждебный и хитрый, он сорвал как военные нападения, так и мирные попытки выяснить, что ему известно о порче острова.",al={"sethir","who is sethir","satyr in oracle glade","сетир","кто такой сетир","сатир на поляне оракула"}},{q="Зачем Сиарне дневник Сетира?",a="Сиарна полагает, что Сетир знает важное о неестественной болезни, распространяющейся по Тельдрассилу. В его личном дневнике есть записи о деятельности сатира и природе темной порчи.",al={"why sethir journal","syurna objective","what is in the journal","зачем дневник сетира","цель сиарны","что в дневнике"}},{q="Что раскрывает дневник после выполнения задания?",a="Дневник подтверждает, что недуг, охвативший ветви Тельдрассила, связан с более глубокой демонической скверной, сжимающей древние леса и побережья Темных берегов за проливом.",al={"journal lore","what did sethir find","darkshore connection","предания дневника","что нашел сетир","связь с темными берегами"}},{q="Где можно получить это задание?",a="Задание дает Сиарна, наставница разбойников, живущая в тенях Дарнасса, после первоначальной оценки ваших способностей.",al={"where do i get destiny calls","destiny calls questgiver","who gives destiny calls","где взять зов судьбы","зов судьбы персонаж","кто дает зов судьбы"}},{q="Куда отправиться после выполнения этого задания?",a="Сиарна отмечает, что вы сделали для Тельдрассила все возможное, и направляет юных защитников на Темные берега, где скрыт настоящий корень порчи материка.",al={"what comes next","next step after destiny calls","after sethir","что дальше","следующий шаг после зова судьбы","после сетира"}},{q="Почему порчей леса занимается наставница разбойников, а не друиды?",a="Обычные методы — и военная сила, и друидская дипломатия — потерпели неудачу против Сетира со смертельными последствиями. Когда открытые действия заходят в кровавый тупик, Сиарна прибегает к скрытой разведке и проникновению.",al={"why rogue quest","why syurna","why not cenarion circle","почему задание разбойника","почему сиарна","почему не кенарийский круг"}}},fp="13,276,23.456.0,31.375.1,26.260.0,38.206.0,45.186.1,29.148.0,58.174.1,68.211.0"}
P.entries["quest:2259"] = {n="Эрион Шепот Тени",s="Эрион Шепот Тени — простой вызов, направляющий начинающих разбойников Альянса в Дарнасс. Послание передает Джаннок Поющий Ветерок: путников направляют в Анклав Кенария, где Эрион ждет, чтобы вывести их деятельность за пределы местных границ.",h="Эрион Шепот Тени — простой вызов, направляющий начинающих разбойников Альянса в Дарнасс.",kw={"cenarion enclave","darnassus","erion shadewhisper","erion's behest","jannok breezesong","rogue breadcrumb","syurna","анклав кенария","дарнасс","эрион шепот тени","директива эриона","джаннок поющий ветерок","задание-наводка разбойника","сиарна"},ang={["class:Rogue"]="Это задание-наводка знаменует ваш переход от начальной работы в Тельдрассиле и направляет вас прямо к Эриону Шепоту Тени за заданиями, требующими изящества за пределами стартовых лесов.",["faction:Alliance"]="Задание направляет агентов Альянса на севере Калимдора согласовать действия с куратором в Дарнассе, прежде чем отправляться на спорные территории.",["race:NightElf"]="Для ночных эльфов — скрытных охотников доклад Эриону в Дарнассе — важный обряд перехода от местной охраны к более широким обязанностям на материке."},sec={{t="Вызов в Анклав",b="Когда разбойник становится известен в окрестностях Тельдрассила, Джаннок Поющий Ветерок следит за тем, чтобы его таланты не пропали зря. Развеяв тревожные мысли о том, что придется идти к требовательной наставнице Сиарне, Джаннок направляет агента прямо в сердце Дарнасса. Там, среди зеленых ветвей Анклава Кенария, Эрион Шепот Тени ведает делами, требующими более тихого и тонкого подхода."},{t="Взгляд за горизонт",b="Встреча с Эрионом — важный поворотный момент для любого разбойника на землях ночных эльфов. Его приветствие ясно дает понять, что защищающие леса Тельдрассила больше не вмещают обязанности агента. Роль Эриона — направлять способных людей в более широкий и опасный мир, служа трамплином к заданиям за морем."}},faq={{q="Кто посылает вас к Эриону Шепоту Тени?",a="Вызов отправляет Джаннок Поющий Ветерок, веля вам немедленно отправиться в Дарнасс и поговорить с Эрионом Шепотом Тени в Анклаве Кенария.",al={"quest giver","who starts erion shadewhisper","jannok breezesong quest","персонаж, выдающий задания","кто дает эриона шепот тени","задание джаннок поющий ветерок"}},{q="Где находится Эрион Шепот Тени?",a="Эрион Шепот Тени находится в Анклаве Кенария в Дарнассе, среди деревьев на верхних ярусах анклава.",al={"erion location","where is erion","where to find erion shadewhisper","где эрион","местонахождение эриона","где найти эриона шепот тени"}},{q="Почему Джаннок упоминает Сиарну?",a="Сиарна — известная наставница разбойников в Дарнассе, славящаяся строгостью и требовательным обучением. Джаннок шутливо замечает, что вам ничего не грозит и вас не тащат на ее суровые уроки.",al={"who is syurna","why not syurna","jannok syurna line","кто такая сиарна","почему не сиарна","шутка джаннока про сиарну"}},{q="Что происходит после доклада Эриону?",a="Когда вы закончите доклад, Эрион дает вам следующее поручение — задание «Директива Эриона», которое отправляет вас из Тельдрассила расширять сферу действий в Калимдоре.",al={"what next","erion follow up","quest after erion shadewhisper","что дальше","продолжение эриона","задание после эриона шепот тени"}},{q="Какой работой руководит Эрион?",a="Эрион координирует операции и направляет молодых разбойников в Дарнассе, выступая куратором, который связывает местных агентов с более широкими заданиями по всей сети Альянса.",al={"is erion a rogue trainer","erion shadewhisper role","what does erion do","эрион наставник разбойников","роль эриона шепот тени","чем занимается эрион"}},{q="Почему куратор разбойников находится в Анклаве Кенария?",a="Хотя Анклав Кенария известен в основном друидами и поклонением природе, его раскидистые тенистые деревья дают скрытным агентам достаточно уединения, чтобы собираться и вести дела вдали от Храма Луны.",al={"cenarion enclave rogue","why druid area for rogue","анклав кенария разбойник","почему друидская зона для разбойника"}}},fp="18,245,24.444.0,19.359.0,41.142.0,36.127.0,31.217.0,38.164.0,37.170.0,57.221.0"}
P.entries["quest:226"] = {n="Волки идут по пятам",s="«Волки идут по пятам» — задание Альянса, которое выдает Ларс в Лагере Свена на западе Сумеречного леса. Путники охотятся на бешеных и голодных лютоволков, бродящих в окрестных лесах, и тем самым устраняют ближайшие угрозы, чтобы Свен и Ларс могли сосредоточиться на мести некроманту Морбенту Скверну.",h="«Волки идут по пятам» — задание Альянса, которое выдает Ларс в Лагере Свена на западе Сумеречного леса.",kw={"dire wolf","duskwood","flash bundles","lars","morbent fel","rabid dire wolf","starving dire wolf","sven","sven's camp","лютоволк","сумеречный лес","ослепляющие свертки","ларс","морбент скверн","бешеный лютоволк","голодный лютоволк","свен","лагерь свена"},ang={["class:Hunter"]="Приручать или истреблять искаженных животных Сумеречного леса нужно с предельной внимательностью: эти лютоволки намного отчаяннее и свирепее обычных лесных зверей.",["faction:Alliance"]="Помощь Ларсу укрепляет уединенный лагерь Свена и обеспечивает Альянсу опорный пункт против сил нежити на западе Сумеречного леса."},sec={{t="Опасный лагерь",b="В западных холмах Сумеречного леса, у границы с Западным Краем, Свен Йорген и его товарищ Ларс держат уединенный лагерь. Жизнь вдали от Темнолесья заставляет их полностью полагаться на собственную охоту и собирательство. Но если Ларс несет свежую добычу через темные леса, он становится желанной целью для голодных хищников, рыщущих по затененным берегам реки и в подлеске."},{t="Очистка леса",b="Стаи голодных и бешеных лютоволков бродят в основном к северу и востоку от лагеря, у реки. Истребляя этих неистовых зверей, путники снимают осаду с охотничьих трудов Ларса. Когда волков становится меньше, обоим не приходится постоянно бороться за хлеб насущный, и они могут всецело обратиться к некроманту Морбенту Скверну, затаившемуся дальше на востоке."}},faq={{q="Кто такой Ларс?",a="Ларс — закаленный выживальщик, помогающий Свену Йоргену в небольшом лагере среди холмов на западе Сумеречного леса. Он занимается ежедневной охотой и собирательством, пока Свен одержим местью темным силам, угрожающим региону.",al={"lars","who gives wolves at our heels","quest giver lars","ларс","кто выдает волки идут по пятам","ларс задание"}},{q="Где бродят волки?",a="Лютоволки бродят по лесам прямо к северу и востоку от Лагеря Свена, особенно по берегам реки, отделяющей Сумеречный лес от северных земель.",al={"wolf location","where are rabid dire wolves","where are starving dire wolves","где волки","где бешеные лютоволки","где голодные лютоволки"}},{q="Почему лютоволки так агрессивны?",a="Дикая природа Сумеречного леса пришла в упадок под натиском наступающей тьмы. Дичи мало, и лютоволки почти голодают, а болезнь или темная порча сделала многих из них бешеными и безрассудно жестокими к любому, кто несет свежее мясо.",al={"why are wolves attacking","rabid wolves duskwood","почему волки нападают","бешеные волки сумеречный лес"}},{q="Кто такой Морбент Скверн?",a="Морбент Скверн — могущественный некромант, практикующий темные искусства на кладбище и среди курганов к востоку. Свен и Ларс питают к нему лютую ненависть и готовятся расправиться с ним, как только удовлетворят основные нужды выживания.",al={"morbent fel","the necromancer","who is the necromancer to the east","морбент скверн","некромант","кто некромант на востоке"}},{q="Что такое ослепляющие свертки, которые Ларс дает в награду?",a="Ослепляющие свертки — устройства, создающие ослепительную вспышку, их делают жители Темнолесья. Сочувствующие горожане передали их лагерю Свена, чтобы помочь ему в борьбе с нежитью и зверьем, наводнившими леса.",al={"flash bundles","lars reward","what is flash bundle","ослепляющие свертки","награда ларса","что такое ослепляющий сверток"}},{q="Почему Свен и Ларс не живут в Темнолесье?",a="Семью Свена постигла трагедия, превратившая его в озлобленного мстителя-одиночку. Вместо того чтобы укрываться за спинами Ночного Дозора в Темнолесье, Свен и Ларс поселились в глуши, чтобы самим выслеживать зло, терзающее леса.",al={"why live in a camp","svens camp location","why not in town","почему лагерь","где лагерь свена","почему не в городе"}}},fp="19,311,17.404.0,18.401.0,12.237.0,30.163.0,38.246.0,19.223.0,50.197.0,42.242.0"}
P.entries["quest:2260"] = {n="Директива Эриона",s="«Директива Эриона» — вызов, который получают многообещающие ночные эльфы-разбойники в Дарнассе. Заметив их растущее мастерство скрытности, наставник разбойников Эрион Шепот Тени отправляет их за море, в Штормград, на доклад в Разведку Штормграда.",h="«Директива Эриона» — вызов, который получают многообещающие ночные эльфы-разбойники в Дарнассе.",kw={"darnassus","erion shadewhisper","erion's behest","old town","renzik the shiv","rogue","si:7","stormwind","дарнасс","эрион шепот тени","директива эриона","старый город","рензик нож","разбойник","шру","штормград"},ang={["class:Rogue"]="Этот вызов знаменует ваш переход от местных стычек в Калимдоре к континентальному шпионажу и смертоносной подготовке в ШРУ.",["faction:Alliance"]="ШРУ сосредоточивает тайные операции Альянса, чтобы талантливые лазутчики всех входящих в него рас могли действовать там, где они нужнее всего короне.",["race:NightElf"]="Покинуть кров Дарнасса и Тельдрассила ради службы в людской разведке на каменных улочках Штормграда — часто сильный культурный шок для кальдораев-соглядатаев."},sec={{t="Вызов из-за моря",b="Ночные эльфы-разбойники у Тельдрассила обычно оттачивают мастерство под тихим присмотром наставников вроде Эриона Шепота Тени. Но когда агент проявляет исключительный талант, слух разносится далеко за ветви Мирового Древа. Через Эриона Разведка Штормграда, более известная как ШРУ, лично приглашает его пересечь Великое море и прибыть в столицу людей."},{t="На службе ШРУ",b="Путь тяжел: от северных земель Калимдора через гавани Темных берегов или Болотины к шумным улицам Штормграда. Попав в столицу, агент должен пробраться в Старый город и явиться в штаб ШРУ. Там его ждет Рензик Нож, чтобы оценить новичка, открывая путь к высшему шпионскому искусству, мастерству ядов и тайным операциям на благо Альянса."}},faq={{q="Кто отправляет меня на это задание?",a="Это поручение вам дает Эрион Шепот Тени, учитель разбойников в Дарнассе, после того как ваши первые дела привлекли внимание разведывательных сетей за морем.",al={"quest giver","erion shadewhisper","who gave me this","выдающий задание","эрион шепот тени","кто мне это дал"}},{q="Почему Разведка Штормграда обращается к ночному эльфу?",a="Хотя у ночных эльфов есть собственные традиции скрытности, Альянс во многом полагается на ШРУ в координации тайной разведки и диверсий. Разведка Штормграда регулярно ищет способных разбойников любой расы Альянса, чтобы усилить свои ряды.",al={"why si:7","why stormwind","why do humans care","почему шру","почему штормград","почему людям есть дело"}},{q="Где найти Рензика Ножа?",a="Рензик Нож находится в штабе ШРУ, скрытом в районе Старый город в Штормграде.",al={"renzik location","where is the shiv","find renzik","где рензик","где рензик нож","найти рензика"}},{q="Это задание только для разбойников?",a="Да. Это классовое задание разбойников Альянса, которое направляет агентов из Калимдора в главный центр разведывательной подготовки Альянса в Штормграде.",al={"rogue only","can other classes do this","is this rogue quest","только разбойники","могут ли другие классы","задание разбойника"}},{q="Что будет после встречи с Рензиком?",a="Доклад Рензику включает вас в учебные операции ШРУ в Восточных королевствах и открывает путь к специальной подготовке и тайным заданиям по всем землям людей.",al={"next quest","what do i get","after renzik","следующее задание","что я получу","после рензика"}},{q="Как ночному эльфу добраться до Штормграда на этом этапе?",a="Путник должен сесть на корабль из Аубердина на Темных берегах и отплыть через море в Гавань Менетилов в Болотине, затем преодолеть опасный путь через Лок Модан и Дун Морог до Стальгорна и сесть на Подземный поезд до Штормграда.",al={"how to get to stormwind","travel to stormwind","path to stormwind","как добраться до штормграда","путь в штормград","дорога в штормград"}}},fp="14,262,24.399.0,28.426.0,29.161.0,53.256.0,34.128.0,30.153.0,34.182.0,57.225.0"}
P.entries["quest:2281"] = {n="Встречи в Красногорье",s="«Встречи в Красногорье» — поручение для разбойников Альянса из штаба разведки Штормграда. Понимая, что необученным новобранцам не хватает тонкости для опасных полевых операций, ШРУ направляет многообещающих агентов в Приозерье совершенствовать мастерство под началом опытных оперативников.",h="«Встречи в Красногорье» — поручение для разбойников Альянса из штаба разведки Штормграда.",kw={"lakeshire","lucius","redridge rendezvous","renzik the shiv","rogue quest","si:7","stormwind","приозерье","люций","встречи в красногорье","рензик нож","задание разбойника","шру","штормград"},ang={["class:Rogue"]="Это задание знаменует вступление разбойника в официальную полевую работу ШРУ: подготовка переходит от воровства в подворотнях к расчетливому государственному шпионажу.",["faction:Alliance"]="Поручение показывает, как далеко простирается тайная рука Штормграда, чьи скрытые агенты размещены в дальних поселениях вроде Приозерья."},sec={{t="Мера выживания",b="В тайных залах ШРУ в Штормграде заместитель главы Рензик Нож прямо говорит о недолгой жизни новичков. Если бросать необтесанных агентов в опасные операции, это приведет к потерям, а не к сведениям. Чтобы избежать напрасных жертв, перспективных новобранцев отправляют на восток, в Красногорье, к Люцию, оперативнику, засевшему среди озерных причалов."},{t="Глаза в Приозерье",b="Приозерье — идеальное место для тайной подготовки. Городок на границе, зажатый между гноллами и орками клана Черной горы, предлагает множество настоящих опасностей, а шумные пристани дают оперативнику вроде Люция отличное прикрытие, чтобы оценивать скрытность, реакцию и умение вскрывать замки у разбойника, не привлекая внимания горожан и стражи."}},faq={{q="Кто выдает задание «Встречи в Красногорье»?",a="Рензик Нож, гоблин-мастер шпионов в штабе ШРУ в Старом городе Штормграда, дает это поручение разбойникам, явившимся к командованию разведки.",al={"who starts redridge rendezvous","redridge rendezvous questgiver","who gives quest","кто начинает встречи в красногорье","встречи в красногорье персонаж","кто выдает задание"}},{q="Где находится Люций?",a="Люций расположился на деревянных причалах Приозерья в Красногорье и смешивается с местными бездельниками и рыбаками у воды.",al={"where is lucius","lucius location","find lucius","где люций","люций местоположение","найти люция"}},{q="Зачем ШРУ отправляет разбойников в Красногорье?",a="Рензик считает зеленых разбойников непригодными для ответственных полевых заданий разведки. Люцию поручено отшлифовать их навыки и проверить умения, такие как карманная кража и вскрытие замков, в условиях глуши.",al={"why lakeshire","purpose of redridge rendezvous","why redridge","почему приозерье","цель встреч в красногорье","почему красногорье"}},{q="Что идет после «Встреч в Красногорье»?",a="Доклад Люцию ведет прямо к учебным заданиям, начиная с Лесопилки Альтера, где агенту предстоит испытать скрытность и ловкость рук.",al={"next quest","redridge rendezvous followup","after redridge rendezvous","следующее задание","продолжение встреч в красногорье","после встреч в красногорье"}},{q="Доступно ли это задание не только разбойникам?",a="Нет. «Встречи в Красногорье» — исключительно классовое задание разбойников Альянса, связанное с полевой подготовкой ШРУ.",al={"can warriors do redridge rendezvous","is this rogue only","class requirement","могут ли воины встречи в красногорье","только для разбойников","требование класса"}},{q="Почему Рензик работает на разведку Штормграда?",a="Несмотря на то что он гоблин, Рензик Нож — доверенный помощник главы шпионов Матиаса Шоу, отвечающий за набор и обучение агентов в глубине крепости ШРУ.",al={"why is a goblin in si7","renzik lore","goblin in stormwind","почему гоблин в шру","рензик предыстория","гоблин в штормграде"}}},fp="19,288,21.416.0,17.368.0,40.178.0,24.146.0,38.227.0,48.172.0,53.101.0,48.175.0"}
P.entries["quest:2282"] = {n="Лесопилка Альтера",s="«Лесопилка Альтера» — важное учебное задание, которое разбойникам Альянса дает Люций в Приозерье. Посланные на ближнюю лесопилку с набором воровских инструментов, новички должны проникнуть в место под надзором орков Черной горы, взломать запертый сундук и забрать воровской знак.",h="«Лесопилка Альтера» — важное учебное задание, которое разбойникам Альянса дает Люций в Приозерье.",kw={"alther's mill","blackrock orcs","lakeshire","lockpicking","lucius","redridge mountains","si:7","thieves tools","token of thievery","лесопилка альтера","орки черной горы","приозерье","взлом замков","люций","красногорье","шру","воровские инструменты","воровской знак"},ang={["class:Rogue"]="Этот обряд посвящения дает вам основные отмычки и полевые полномочия и проверяет ваше терпение и скрытность среди патрулирующих орков Черной горы.",["faction:Alliance"]="Подготовка специализированных воров и лазутчиков на окраине Приозерья укрепляет разведку Альянса и позволяет внимательно следить за передвижениями Черной горы."},sec={{t="Испытание ловкости и мастерства",b="В Приозерье наставники разбойников не тратят время на отвлеченные лекции, если запертый сундук научит быстрее. Люций отправляет перспективных агентов на северо-восток по дороге к Лесопилке Альтера, вручив им первый набор воровских инструментов. Чтобы получить Воровской сертификат, новички должны пробраться на заброшенную лесопилку, вскрыть личный ларец Люция и принести спрятанный в нем знак."},{t="Тени среди пил",b="Хотя Лесопилка Альтера когда-то была обычным лесозаготовительным пунктом, недавно она привлекла опасное внимание орков Черной горы, наступающих на Красногорье. Люций с удовольствием считает этих поджигателей войны дополнительным практическим испытанием. Незаметно взламывать замки на вражеской территории — именно то испытание, которое ШРУ ждет от своих агентов."}},faq={{q="Какова цель задания на Лесопилке Альтера?",a="Это практический полевой экзамен для разбойников Альянса, осваивающих взлом замков. Люций дает вам воровские инструменты и требует достать особый знак из запертого сундука, чтобы доказать ваше мастерство.",al={"why go to althers mill","quest purpose","what does this quest do","зачем идти на лесопилку альтера","цель задания","что дает это задание"}},{q="Кто такой Люций?",a="Люций — опытный учитель разбойников в Приозерье в Красногорье. Многие годы он обучает новобранцев-разбойников, присланных по связям со всего Альянса, проверяя их скрытность и ловкость рук.",al={"who is lucius","lucius lakeshire","who gives this quest","кто такой люций","люций приозерье","кто выдает это задание"}},{q="Где находится Лесопилка Альтера?",a="Лесопилка Альтера лежит неподалеку от дороги к северо-востоку и востоку от Приозерья, прижавшись к предгорьям перед высокими горными перевалами.",al={"where is the mill","althers mill location","how do i find althers mill","где лесопилка","лесопилка альтера местоположение","как найти лесопилку альтера"}},{q="Почему вокруг Лесопилки Альтера орки?",a="Орки клана Черной горы спустились с высот Водопада Каменной Стражи и пылающих хребтов выше, нападая на поселения людей и создавая передовые опорные пункты по всему Красногорью, в том числе вокруг заброшенной лесопилки.",al={"why are orcs here","blackrock orcs redridge","who controls althers mill","почему здесь орки","орки черной горы красногорье","кто управляет лесопилкой альтера"}},{q="Какую награду дает Люций за выполнение задания?",a="Люций вручает вам Воровской сертификат, подтверждающий, что вы освоили основы механизмов замков и отмычек и теперь можете действовать как полноценный полевой разбойник.",al={"what is the reward","certificate of thievery","quest completion reward","какая награда","воровской сертификат","награда за задание"}},{q="Как это задание вписывается в подготовку разбойников Альянса?",a="Разбойников по всем землям Альянса связные, такие как агенты ШРУ Матиаса Шоу в Штормграде, направляют на встречу с Люцием в Приозерье. Поручение на Лесопилке Альтера становится практической кульминацией их базовой полевой подготовки.",al={"rogue quest chain","si7 connection","redridge rendezvous followup","цепочка заданий разбойника","связь с шру","продолжение встреч в красногорье"}}},fp="13,289,27.415.0,23.376.0,52.231.0,14.228.0,31.143.0,40.223.0,55.174.0,64.236.0"}
P.entries["quest:23"] = {n="Лапа Топтыжня",s="Это задание подтверждает убийство Топтыжня — одного из самых свирепых и легендарных хищников Ясеневого леса. Если принести отрубленную лапу зверя Сенани Громовое Сердце на Заставе Расщепленного Дерева, следопыты Орды воздадут вам почести, а также откроется неочевидная связь между огромным медведем и местными ночными эльфами.",h="Это задание подтверждает убийство Топтыжня — одного из самых свирепых и легендарных хищников Ясеневого леса.",kw={"ashenvale","ashenvale hunt","bear","crescent emblem","paw","senani thunderheart","splintertree post","ursangous","ясеневый лес","большая охота","медведь","знак полумесяца","лапа","сенани громовое сердце","застава расщепленного дерева","топтыжень"},ang={["class:Hunter"]="Выследить и одолеть одного из старейших и самых опасных хищников Ясеневого леса — высшее испытание для охотника: оно требует мастерства следопыта, выживания и боевых навыков.",["faction:Horde"]="Охотники Орды считают Топтыжня опасной добычей, победа над которой приносит почет на Заставе Расщепленного Дерева.",["race:Tauren"]="Для охотников-тауренов взять лапу Топтыжня — священное дело: так они чтут зверя, проявляют боевую решимость и уважение к духам охоты."},sec={{t="Трофей Большой охоты",b="В рамках Большой охоты следопыты с Заставы Расщепленного Дерева выслеживают древних зверей, господствующих под густым пологом леса. Топтыжень — один из самых свирепых среди этих верховных хищников; он известен тем, что убил множество путников и воинов, вставших на его пути. Одолеть такого зверя — нелегкое дело, а его лапа служит неоспоримым вещественным доказательством того, что могучее создание наконец встретило достойного противника."},{t="Связь с ночными эльфами",b="При внимательном осмотре лапы Топтыжня на ней заметен небольшой знак в виде четверти полумесяца, вырезанный или выжженный на плоти. Когда лапу показывают Сенани Громовое Сердце, она признает в этой метке явный признак влияния кальдораев. Ночные эльфы часто приручают и обучают могучих лесных зверей для защиты своих священных границ, а значит, Топтыжень был не просто диким хищником — он стал невольным стражем или оружием Альянса."}},faq={{q="Кто такой Топтыжень?",a="Топтыжень — исключительно огромный и смертоносный медведь, бродящий по чащам Ясеневого леса. Охотники и странники боялись его одинаково, и он отнял немало жизней, прежде чем пал от руки охотников Орды.",al={"who is ursangous","ursangous bear","ursangous lore","кто такой топтыжень","медведь топтыжень","предания о топтыжне"}},{q="Что означает знак полумесяца на лапе?",a="Эмблема в виде четверти полумесяца остается загадкой при осмотре трофея. Сенани Громовое Сердце может изучить ее, когда вы доставите лапу.",al={"crescent mark on paw","paw emblem","why is there a crescent","знак полумесяца на лапе","знак на лапе","почему на лапе полумесяц"}},{q="Кому нужно отнести Лапу Топтыжня?",a="Лапу нужно доставить Сенани Громовое Сердце, охотнице-тауренке на Заставе Расщепленного Дерева в восточной части Ясеневого леса.",al={"where turn in paw","who wants ursangous paw","senani thunderheart location","куда сдать лапу","кому нужна лапа топтыжня","где сенани громовое сердце"}},{q="Как это связано с Большой охотой?",a="Топтыжень — один из трех великих зверей, на которых нацелена Большая охота, наряду с Тенумброй и Острым Когтем. Чтобы завершить обряд, нужно победить всех трех и предъявить их трофеи.",al={"ashenvale hunt chain","what is the hunt","hunting quest line","цепочка большой охоты","что такое большая охота","цепочка заданий охоты"}},{q="Почему Орда охотится на великих зверей Ясеневого леса?",a="Охотники Орды, особенно таурены и орки с Заставы Расщепленного Дерева, охотятся на этих верховных хищников, чтобы проверить свое боевое мастерство и устранить самые опасные угрозы вблизи уязвимых путей снабжения и лагерей.",al={"why hunt bears","splintertree hunting lore","зачем охота на медведей","предания охоты расщепленного дерева"}},{q="Что происходит после сдачи лапы?",a="Когда вы соберете трофеи Топтыжня и остальной назначенной добычи, Сенани Громовое Сердце признает вашу победу в заключительном испытании — «Завершение охоты».",al={"next quest after paw","what follows ursangous","следующее задание после лапы","что после топтыжня"}}},fp="15,321,26.441.0,24.456.1,18.193.0,46.130.0,34.122.0,42.198.0,55.224.0,38.177.0"}
P.entries["quest:230"] = {n="Лагерь Свена",s="«Лагерь Свена» — задание Альянса в Сумеречном лесу, раскрывающее важную улику о трагедии на ферме Йоргенов. Откопав безымянный дневник из кучи рыхлой земли на заброшенной ферме, герои выясняют, кто был свидетелем убийства семьи Свена Йоргена.",h="«Лагерь Свена» — задание Альянса в Сумеречном лесу, раскрывающее важную улику о трагедии на ферме Йоргенов.",kw={"dark riders","duskwood","mound of loose dirt","shadowy figure","sven yorgen","yorgen farm","темные всадники","сумеречный лес","куча рыхлой земли","таинственный незнакомец","свен йорген","ферма йоргенов"},ang={["faction:Alliance"]="Расследование убийства семьи Йоргенов — часть более широкой борьбы Альянса за понимание темных сил, надвигающихся на Сумеречный лес."},sec={{t="Улика в земле",b="Свена Йоргена выгнали из дома темные всадники; вернувшись, он нашел свою семью убитой, а ферму — в руинах. Охваченный горем и жаждой мести, он отправил союзников обыскать развалины усадьбы. Под кучей свежевскопанной земли лежала зарытая небольшая книжка, испачканная землей и брошенная в суматохе."},{t="Безмолвный свидетель",b="Когда книгу приносят Свену в его лагерь в западных холмах, она открывает жуткую подробность: оказывается, за жестокой расправой над его семьей наблюдал таинственный незнакомец. Дневник не приносит Свену покоя — его горе обращается на поиски этого неизвестного очевидца и требование ответов."}},faq={{q="Что за книга найдена в куче земли?",a="Это безымянный дневник, испачканный землей и зарытый на ферме Йоргенов. Его записи доказывают, что за убийством семьи Свена Йоргена наблюдал неопознанный очевидец.",al={"what book is this","book from svens farm","what did i dig up","что это за книга","книга с фермы свена","что я откопал"}},{q="Куда ведет это задание дальше?",a="Если отнести книгу Свену Йоргену, начнется задание «Таинственный незнакомец» — поиски загадочного свидетеля.",al={"what comes next","next quest after svens camp","who is the shadowy figure","что дальше","следующее задание после лагеря свена","кто такой таинственный незнакомец"}},{q="Где находится Свен Йорген?",a="Свен укрылся в лагере в северо-западных холмах Сумеречного леса, размышляя о судьбе своей семьи и замышляя месть.",al={"where is sven","sven yorgen location","where do i turn this in","где свен","где свен йорген","куда сдавать это задание"}},{q="Почему книга была зарыта на ферме?",a="Книга была спрятана в куче рыхлой земли среди развалин усадьбы — ее либо наспех бросили, либо скрыл наблюдатель, оставшийся на месте нападения.",al={"why buried","who hid the book","mound of loose dirt","почему зарыта","кто спрятал книгу","куча рыхлой земли"}},{q="Кто убил семью Свена?",a="Таинственные темные всадники пронеслись по ферме, убив родных Свена и превратив некогда мирную усадьбу в руины, кишащие нежитью.",al={"who attacked the farm","who killed svens family","svens family killers","кто напал на ферму","кто убил семью свена","убийцы семьи свена"}},{q="Какая фракция может выполнить это задание?",a="Это задание доступно только игрокам Альянса, так как Свен Йорген ищет помощи лишь у защитников Сумеречного леса и Альянса.",al={"is this alliance only","can horde do svens camp","только ли для альянса","может ли орда выполнить лагерь свена"}}},fp="11,291,18.318.0,16.303.1,44.160.0,32.135.0,29.144.0,36.168.0,25.144.0,37.123.0"}
P.entries["quest:2300"] = {n="ШРУ",s="Этот приказ вызывает многообещающих молодых разбойников из Элвиннского леса в сердце тайной разведки Штормграда. По распоряжению Керин Сильвиус в Златоземье агенты должны немедленно явиться к Рензику Ножу в Старом городе. Откликнувшись, оперативник поступает на службу к Мастеру Матиасу Шоу.",h="Этот приказ вызывает многообещающих молодых разбойников из Элвиннского леса в сердце тайной разведки...",kw={"keryn sylvius","mathias shaw","old town","renzik the shiv","rogue","sentinel hill","si:7","stormwind","керин сильвиус","матиас шоу","старый город","рензик нож","разбойник","шру","штормград"},ang={["class:Rogue"]="Этот приказ означает ваш переход от плута, берущегося за местные дела, к признанному оперативнику официальной разведки Штормграда.",["faction:Alliance"]="ШРУ служит тайным щитом Альянса, выполняя опасные шпионские операции, которые обычные маршалы и пехота не могут проводить открыто."},sec={{t="Вызов в Старый город",b="Наставница разбойников Керин Сильвиус из Таверны Гордость Льва в Златоземье следит за местными новобранцами. Когда разбойник проявляет достаточно хитрости и умения в борьбе с растущей угрозой Братства Справедливости, Сильвиус передает весть из штаба. Приказ краток и лишен церемоний: без промедления явиться к Рензику Ножу. Оставив поля Элвиннского леса, агент отправляется прямо в тайное сердце столицы."},{t="Скрытые глаза Штормграда",b="За фасадом неприметных казарм в Старом городе скрывается штаб ШРУ — главного разведывательного ведомства Штормграда. Под командованием Мастера Матиаса Шоу ШРУ проводит тайные операции, разведку и убийства по всему королевству и за его пределами. Рензик Нож, острый на язык заместитель Шоу, лично проверяет многообещающих агентов, прежде чем отправить их на рискованные операции, недоступные регулярной армии королевства."}},faq={{q="Кто посылает меня явиться в ШРУ?",a="Приказ вам дает Керин Сильвиус, наставница разбойников из Таверны Гордость Льва в Златоземье. Когда вы докажете свою пригодность в деле, Сильвиус передает приказ явиться в штаб в Штормграде.",al={"who gives quest","quest giver","keryn sylvius","кто дает задание","персонаж, выдающий задание","керин сильвиус"}},{q="Кто такой Рензик Нож?",a="Рензик Нож — гоблин-оперативник, заместитель командира ШРУ, подчиняющийся непосредственно Мастеру Матиасу Шоу. Он оценивает полевых агентов и координирует задания тайной разведки из штаба ШРУ в Старом городе.",al={"renzik the shiv","who is renzik","renzik","рензик нож","кто такой рензик","рензик"}},{q="Что такое ШРУ?",a="ШРУ — сокращение от «Штормградская разведывательная управа» — тайная служба шпионажа, разведки и убийств Королевства Штормград. Под руководством Матиаса Шоу ее оперативники собирают сведения об угрозах короне, с которыми не справятся обычные стражи и солдаты.",al={"what is si7","what does si7 do","stormwind intelligence","что такое шру","чем занимается шру","штормградская разведка"}},{q="Где находится штаб ШРУ?",a="Штаб ШРУ расположен в восточной части Старого города в Штормграде. Он действует из укрепленного дома гильдии и тренировочных казарм, скрытых от главных улиц.",al={"where is si7","si7 location","where is renzik","где шру","расположение шру","где рензик"}},{q="Что происходит после доклада Рензику?",a="Когда вы явитесь к Рензику, он проверит вашу готовность и даст полевое задание за стенами города — встретиться с оперативником в Красногорье.",al={"next quest","what comes after","redridge rendezvous","следующее задание","что дальше","встреча в красногорье"}},{q="Почему Керин Сильвиус называет меня «рыбкой»?",a="Это сленг для неопытного новичка или новобранца. Оперативники ведомства дают друг другу колоритные, колкие прозвища, чтобы новички не зазнавались, пока не проявят себя в настоящих заданиях.",al={"why called fish","fish meaning","почему рыбка","значение рыбка"}}},fp="4,339,21.429.0,23.473.0,31.223.0,25.240.0,13.281.0,39.184.0,39.170.1,38.192.0"}
P.entries["quest:233"] = {n="Почта Холодной долины",s="«Почта Холодной долины» — простое курьерское поручение, которое Стен Крепкорук дает новобранцам в Старой Наковальне. Горные перевалы часто завалены снегом, а неподалеку наседают троггами, поэтому доставка свежей корреспонденции в лагеря у замерзшего озера поддерживает связь с изолированными защитниками долины.",h="«Почта Холодной долины» — простое курьерское поручение, которое Стен Крепкорук дает новобранцам в Старой...",kw={"anvilmar","coldridge valley","dun morogh","grelin whitebeard","mail delivery","sten stoutarm","talin keeneye","старая наковальня","холодная долина","дун морог","грелин белобород","доставка почты","стен крепкорук","талин остроглаз"},ang={["faction:Alliance"]="Каждая застава в Холодной долине помогает обеспечивать безопасность Дун Морога, поэтому надежная переписка необходима для ранней военной координации.",["race:Dwarf"]="Передача вестей между заставами подчеркивает общинную стойкость дворфов Стальгорна: даже самые дальние разведчики долины остаются связаны со своими кланами.",["race:Gnome"]="Будучи гостями и союзниками в Дун Мороге после падения Гномрегана, гномы укрепляют доверие местных дворфов-защитников, помогая поддерживать линии связи."},sec={{t="Курьер в снегах",b="Жизнь в Холодной долине замкнута даже в самые спокойные времена года. Когда зимние курьеры проходят через горный перевал с почтой из остального Дун Морога, письма быстро накапливаются в Старой Наковальне. Стен Крепкорук, занятый снабжением и охраной, полагается на странствующих новобранцев, которые разносят эти связки по западной дороге, чтобы важные вести не залеживались в зале."},{t="Передовые заставы",b="Адресат, Талин Остроглаз, дозорит у замерзшего озера на западе, наблюдая за передвижениями троггов и опасными зверями. Даже на холоде вести из Стальгорна и окрестных застав очень ценны. Однако сортировка почты в суровых горных условиях редко бывает безупречной, и письма для разных разведчиков часто путешествуют в одной связке."}},faq={{q="Кто дает задание по доставке почты?",a="Задание на доставку вам дает Стен Крепкорук возле Старой Наковальни. Ему принесли стопку писем, только что доставленных через горный перевал, но он не может оставить свои обязанности, чтобы разнести их лично.",al={"quest giver","who gives coldridge valley mail delivery","sten stoutarm quest","персонаж, выдающий задание","кто дает почту холодной долины","задание стена крепкорука"}},{q="Где находится Талин Остроглаз?",a="Талин Остроглаз расположился лагерем к западу от Старой Наковальни, прямо у дороги возле замерзшего озера в Холодной долине.",al={"where is talin keeneye","talin keeneye location","finding talin keeneye","где талин остроглаз","расположение талина остроглаза","как найти талина остроглаза"}},{q="Все ли письма в стопке действительно для Талина?",a="Нет. Разбирая связку, Талин обнаруживает, что одно из писем адресовано Грелину Белобороду, который находится неподалеку в долине.",al={"is the mail all for talin","grelin whitebeard letter","misplaced mail","вся ли почта для талина","письмо грелина белоборода","не та почта"}},{q="Почему Стену нужен искатель приключений для доставки почты?",a="Пока Старая Наковальня отбивается от набегов троггов и других угроз, дворфы-защитники вроде Стена заняты неотложными заботами по снабжению и обороне. Проезжие путники и молодые новобранцы — самый быстрый способ доставить письма на дальние заставы.",al={"why run mail","why doesnt sten deliver it","mail delivery duty","зачем разносить почту","почему стен сам не доставит","обязанность доставки почты"}},{q="Ведет ли это задание к другим заданиям?",a="Да. После доставки Талин просит вас отнести ошибочно попавшее к нему письмо Грелину Белобороду во второй части цепочки доставки почты.",al={"next quest","mail chain","follow up to mail delivery","следующее задание","цепочка почты","продолжение доставки почты"}},{q="Откуда изначально пришли письма?",a="Письма пришли через перевал, ведущий в Холодную долину, и были отправлены в эту укрытую котловину из более широких земель Дун Морога и Стальгорна.",al={"where did mail come from","source of letters","откуда пришла почта","источник писем"}}},fp="30,297,21.405.0,17.372.0,29.210.0,31.118.0,52.151.1,49.265.0,36.148.1,43.146.0"}
P.entries["quest:234"] = {n="Почта Холодной долины",s="Это поручение завершает курьерский маршрут через снежные заносы Холодной долины. Передав донесение горного пехотинца Талина Остроглаза по юго-восточной дороге, вы поддерживаете связь Грелина Белоборода со столицей дворфов.",h="Это поручение завершает курьерский маршрут через снежные заносы Холодной долины.",kw={"coldridge valley","courier","dun morogh","grelin whitebeard","ironforge","mail delivery","talin keeneye","холодная долина","курьер","дун морог","грелин белобород","стальгорн","доставка почты","талин остроглаз"},ang={["faction:Alliance"]="Надежные курьерские маршруты через коварные снежные перевалы обеспечивают дальних разведчиков Альянса приказами и важными сведениями.",["race:Dwarf"]="Каждый пост в Дун Мороге рассчитывает на донесения из резиденции короля Магни в Стальгорне, чтобы оборона королевства оставалась согласованной."},sec={{t="Связь с горой",b="Даже в такой изолированной котловине, как Холодная долина, должны передаваться новости и официальная переписка. Хотя Старая Наковальня — административный центр долины, разведчики и часовые на тропах полагаются на пеших курьеров, которые доставляют донесения между высокими перевалами и Стальгорном."},{t="Весточка для Белоборода",b="Грелин Белобород держит небольшой лагерь на дороге к юго-востоку от поста Талина Остроглаза. Среди ледяных заносов и постоянных набегов троггов опытные горные пехотинцы на этих дальних постах зависят от регулярных посланий, чтобы быть в курсе событий в Дун Мороге и за его пределами."}},faq={{q="Кто такой Грелин Белобород?",a="Грелин Белобород — ветеран-дворф, служащий на заставе у юго-восточной дороги Холодной долины. Он следит за дорогами долины и охраняет их от местных угроз, например наступающих троггов и зверей.",al={"grelin","grelin whitebeard info","who is grelin","грелин","грелин белобород","кто такой грелин"}},{q="Откуда пришло это письмо?",a="Письмо отправили из столицы дворфов Стальгорна. Его доставили в Холодную долину, и местные гонцы и часовые несли его по горным перевалам к конечному адресату.",al={"where is letter from","ironforge letter","letter sender","откуда письмо","письмо из стальгорна","отправитель письма"}},{q="Почему здесь почту доставляют пешком?",a="Холодную долину окружают отвесные промерзшие пики, и она отрезана от главных дорог Дун Морога. Грифоны напрямую не долетают до изолированных лагерей, поэтому надежные путники и горные пехотинцы носят донесения между постами вручную.",al={"why foot courier","why run mail","no mailboxes in coldridge","почему пеший курьер","почему носить почту","нет почтовых ящиков в холодной долине"}},{q="Где находится лагерь Грелина Белоборода?",a="Его лагерь расположен дальше по юго-восточной дороге через Холодную долину, за охотничьими и разведывательными угодьями верхнего перевала.",al={"where is grelin camp","grelin whitebeard location","find grelin","где лагерь грелина","где грелин белобород","найти грелина"}},{q="Кто передал письмо для Грелина?",a="Талин Остроглаз, опытный охотник и разведчик на перевале, передал письмо после того, как его доставили с главного сборного пункта близ Старой Наковальни.",al={"who gave the letter","talin keeneye role","who starts quest","кто дал письмо","талин остроглаз","кто выдает задание"}},{q="Что происходит после того, как Грелин получает почту?",a="Получив вести из Стальгорна, Грелин обращается к насущным опасностям, угрожающим долине, и нередко направляет новобранцев на помощь в борьбе с набегами троллей Мерзлогривов и троггов.",al={"what next after mail","grelin next quest","after mail delivery","что дальше после почты","следующее задание грелина","после доставки почты"}}},fp="30,230,22.291.0,19.316.0,25.214.0,32.205.0,35.246.0,42.146.0,47.173.0,44.197.0"}
P.entries["quest:235"] = {n="Большая охота",s="Это поручение Военного глашатая Горлача из Оргриммара призывает начинающих героев Орды на север, через Степи, в древние чащи Ясеневого леса. Игрокам предписано явиться к Сенани Громовое Сердце на Заставу Расщепленного Дерева, чтобы принять участие в охоте и укрепить расширяющиеся границы Орды.",h="Это поручение Военного глашатая Горлача из Оргриммара призывает начинающих героев Орды на север, через Степи...",kw={"ashenvale","barrens","gorlach","hunt","orgrimmar","senani","splintertree","thunderheart","ясеневый лес","степи","горлач","охота","оргриммар","сенани","застава расщепленного дерева","громовое сердце"},ang={["class:Hunter"]="Густые кроны и опасные звери Ясеневого леса — лучшее испытание для начинающих следопытов, откликнувшихся на зов Сенани Громовое Сердце.",["faction:Horde"]="Поход в Ясеневый лес проверяет, сможет ли недавно объединенная Орда расшириться за сухие утесы Дуротара на богатые ресурсами, но враждебные чужие земли.",["race:Tauren"]="Служба под началом Сенани Громовое Сердце позволяет героям-таурен принести глубокое почтение к великой охоте в дикие северные леса."},sec={{t="Зов дикой природы",b="Оргриммар кипит воинственным пылом, но молодому городу нужно много древесины, мяса и безопасных торговых путей для роста. Военный глашатай Горлач — голос верховного командования Орды, направляющий бывалых странников и новичков в активные кампании. Для воинов, взрослеющих в Дуротаре и Степях, древние чащи Ясеневого леса — следующее испытание ради славы и выживания."},{t="Коварный рубеж",b="Пересекая северную границу Степей, путники попадают прямо в Ясеневый лес, где у Орды два главных оплота: Застава Расщепленного Дерева в восточных лесах и Форт Зорам'гар на западном побережье. Сенани Громовое Сердце руководит операциями на Заставе Расщепленного Дерева, организуя следопытов и охотников, чтобы укротить кишащий зверьем полог леса и отбросить враждебных ночных эльфов-часовых, оспаривающих притязания Орды."}},faq={{q="Кто выдает это задание и где его найти?",a="Военный глашатай Горлач выдает это задание в Оргриммаре, столице Орды. Он офицер, призывающий способных героев к кампаниям за пределами Дуротара.",al={"quest giver","where is gorlach","who gives ashenvale hunt","персонаж, выдающий задания","где горлач","кто дает большую охоту"}},{q="Где находится Застава Расщепленного Дерева?",a="Застава Расщепленного Дерева лежит прямо к северу от Степей, в восточной части Ясеневого леса, на главной лесной дороге, ведущей на восток к Азшаре.",al={"splintertree location","where is splintertree post","how to get to splintertree","застава расщепленного дерева","где застава расщепленного дерева","как добраться до заставы расщепленного дерева"}},{q="Кто такая Сенани Громовое Сердце?",a="Сенани Громовое Сердце — опытная следопытка-таурен на Заставе Расщепленного Дерева. Она руководит охотой в Ясеневом лесу и оценивает героев, желающих участвовать в местных испытаниях.",al={"who is senani","senani thunderheart location","turn in npc","кто такая сенани","сенани громовое сердце","кому сдавать задание"}},{q="Для чего нужна Большая охота?",a="Охота позволяет Орде добывать дичь, собирать ценные шкуры и истреблять главных хищников, угрожающих патрулям у Заставы Расщепленного Дерева и ближним лесозаготовкам.",al={"why hunt in ashenvale","ashenvale hunt story","horde goal in ashenvale","зачем охота в ясеневом лесу","большая охота","цель орды в ясеневом лесу"}},{q="Какие еще форпосты есть у Орды в Ясеневом лесу?",a="Кроме Заставы Расщепленного Дерева, Орда держит лагерь на дальнем западном краю леса, у Зорамского взморья.",al={"horde bases in ashenvale","zoram strand post","ashenvale outposts","базы орды в ясеневом лесу","зорамское взморье","форпосты ясеневого леса"}},{q="Есть ли в этом задании сражения?",a="Нет. Это задание лишь направляет вас: нужно безопасно добраться из Оргриммара через Степи и доложить Сенани Громовое Сердце.",al={"is there fighting in this quest","do i fight anything","simple turn in","есть ли бой в задании","нужно ли сражаться","простая сдача"}}},fp="18,314,17.436.0,22.438.0,48.176.0,27.143.0,27.198.0,42.177.0,53.129.0,35.156.0"}
P.entries["quest:2359"] = {n="Башня Клейвена",s="Башня Клейвена — тайная задача ШРУ для разбойников Альянса в Западном Крае. По сведениям Посланницы Кеарнен, агентам нужно обчистить карман ради ключа, проникнуть в хорошо охраняемый форпост Братства Справедливости и добыть зловещие документы, связанные с противоестественными опытами.",h="Башня Клейвена — тайная задача ШРУ для разбойников Альянса в Западном Крае.",kw={"agent kearnen","defias brotherhood","duskwood chest","klaven mortwake","klaven's tower","mathias shaw","poisons","si:7","westfall","zanzil","посланница кеарнен","братство справедливости","сундук из сумеречного леса","клейвен мортвейк","башня клейвена","матиас шоу","яды","шру","западный край","занзил"},ang={["class:Rogue"]="Это тайное проникновение — важный обряд посвящения для разбойников Альянса, требующий мастерства скрытности, карманной кражи, взлома замков и умения использовать физические слабости врага.",["faction:Alliance"]="Раскрытие замысла Братства Справедливости в башне показывает, что мятежники — не просто обиженные каменщики, а опасные заговорщики, готовые связаться с троллями джунглей и темной алхимией, чтобы угрожать королевству.",["race:Human"]="Люди — защитники Штормграда — в ужасе видят, как их бывших соотечественников в Западном Крае превратили в бездумных мертвых рабов."},sec={{t="Слежка в Западном Крае",b="На юго-восточном краю Западного Края, у реки и к северу от Холмов Разбойничьих Кинжалов, стоит одинокая каменная башня, занятая Братством Справедливости. Хотя люди-воры и бандиты Братства обычны на равнинах, Посланница Кеарнен после недель одинокого наблюдения заметила странные перемены. Недавно прямо из тенистых чащ Сумеречного леса прибыл странный груз под охраной чудовищных уродливых часовых, не похожих на обычных разбойников."},{t="Башня и шипастый страж",b="Башней командует Клейвен Мортвейк, а охраняют ее странно измененные часовые с тяжелым хриплым дыханием. Среди этих бредущих стражей есть огромный зомби, пронзенный железными шипами, у которого хранится Ключ от Башни Братства Справедливости. Кража ключа требует тишины и ловкости: так оперативник минует защиту внизу, проберется на верхние уровни крепости и вскроет запертый на замок сундук из Сумеречного леса."},{t="Зелье Занзила",b="Личный дневник Клейвена Мортвейка, найденный в сундуке, описывает мрачный союз Братства Справедливости, Торговой Компании и троллей джунглей Тернистой долины. Записи показывают, что знахарь Занзил открыл алхимический яд, способный поднимать бездумных послушных мертвых рабов. Для Мастера Матиаса Шоу и ШРУ это открытие раскрывает растущие амбиции Братства Справедливости и делает глубокое знание ядов необходимым для агентов."}},faq={{q="Где находится Башня Клейвена?",a="Башня Клейвена лежит на юго-восточном краю Западного Края, у реки и к северу от Холмов Разбойничьих Кинжалов. Это надежный укрепленный оплот Братства Справедливости.",al={"klavens tower location","where is klavens tower","defias tower location westfall","башня клейвена","где башня клейвена","башня братства справедливости в западном крае"}},{q="Кто такая Посланница Кеарнен?",a="Посланница Кеарнен — агент разведки Штормграда, ШРУ. Она несколько недель тайно наблюдала за Башней Клейвена из соседнего лагеря, отслеживая странные поставки и планируя проникновение.",al={"agent kearnen","who gives klaven's tower quest","who is the rogue in westfall","посланница кеарнен","кто дает задание башня клейвена","кто разбойница в западном крае"}},{q="Чем необычны стражи Башни Клейвена?",a="В отличие от обычных людей-бандитов Братства Справедливости, часовые башни — мутировавшие мертвые рабы. Это безмозглые работники, созданные необычным алхимическим зельем, ввезенным в Западный Край.",al={"why are guards zombies","klaven tower guards","what are the tower guards","почему стражи зомби","стражи башни клейвена","кто охраняет башню"}},{q="Откуда у Братства Справедливости мертвые слуги?",a="Братство Справедливости раздобыло особое ядовитое варево, составленное знахарем Занзилом из троллей джунглей в Тернистой долине. Благодаря сделкам с Торговой Компанией яд ввезли, чтобы превращать живых в послушных рабов.",al={"how did defias get zombies","why defias have undead","zanzil defias connection","как у братства зомби","почему у братства нежить","занзил и братство справедливости"}},{q="Кто такой Клейвен Мортвейк?",a="Клейвен Мортвейк — высокопоставленный надзиратель Братства Справедливости в башне. Он принимал темные грузы из Сумеречного леса и вел личный дневник с описанием их зловещей алхимии.",al={"klaven mortwake lore","who is klaven mortwake","klaven","клейвен мортвейк","кто такой клейвен","клейвен"}},{q="Почему Матиас Шоу интересуется найденным дневником?",a="Мастеру Матиасу Шоу нужны применимые сведения о союзах Братства Справедливости и опасных чужих агентах. Узнав, что тролли Занзила могут создавать нежить с помощью яда, ШРУ осознает новую серьезную угрозу для Штормграда и вынуждена тщательно обучать агентов искусству ядов.",al={"why mathias shaw wants journal","si7 zanzil poison","mathias shaw klaven","зачем матиасу шоу дневник","шру занзил яд","матиас шоу клейвен"}}},fp="14,279,22.463.0,30.420.1,19.466.2,32.172.0,21.203.0,48.205.1,41.233.1,23.189.0,55.291.1"}
P.entries["quest:237"] = {n="Защита королевских земель",kw={"gravelgaw","ironforge","loch modan","mountaineer","seer","skullthumper","stonesplinter","troggs","valley of kings","булыжный карьер","стальгорн","лок модан","горный пехотинец","провидец","черепокол","камнедробы","трогги","долина королей"},ang={["faction:Alliance"]="Это задание показывает, какой высокой ценой дается широкая военная кампания Альянса: защита далеких территорий оставила родные земли основных членов союза уязвимыми для местных угроз.",["race:Dwarf"]="Для дворфа защита Долины Королей — личное дело: эта земля чтит величайших правителей Стальгорна, и горько видеть, как ее оскверняют ноги троггов, пока ваши сородичи истекают кровью на далеких полях сражений."},sec={{t="Тонкая оборона",b="Горные пехотинцы, расставленные вдоль южного прохода в Дун Морог, растянуты до опасного предела. Король Магни Бронзобород направил значительную часть военной мощи дворфов на широкий фронт Альянса, и на сторожевых башнях Долины Королей не хватает регулярной пехоты. Горный пехотинец Булыжный Карьер полагается на сторонних добровольцев, которые совершают упреждающие набеги в Долину Камнедробов и сдерживают подземных захватчиков, пока местные гарнизоны ждут подкреплений, которые могут так и не прибыть."},{t="Шаманы и бойцы Камнедробов",b="Трогги из племени Камнедробов — не бездумные звери, бесцельно бродящие по округе: их боевые отряды действуют сообща, полагаясь на грубую силу и примитивную магию стихий. Булыжный Карьер выбирает целью опытных воинов племени — черепоколов — и их мистических предводителей, провидцев. Устранение этих командиров на передовой лишает племя напора, вносит смятение в южные лагеря и не дает им всей массой двинуться на дорогу к Стальгорну."},{t="Мрачные вести с фронта",b="Когда вы докладываете об успехе, Булыжный Карьер сообщает безрадостную новость: обещанные подкрепления дворфов не прибудут. Тяжелые потери на далеком фронте Альянса истощили резервы Стальгорна, и теперь Лок Модан целиком полагается на местных горных пехотинцев и наемников, проходящих мимо, в защите сердца королевства."}},faq={{q="Где находится горный пехотинец Булыжный Карьер?",a="Горный пехотинец Булыжный Карьер стоит у южной сторожевой башни на дороге через Долину Королей и охраняет проход, соединяющий Лок Модан с Дун Морогом.",al={"gravelgaw location","where is gravelgaw","turn in gravelgaw","булыжный карьер где найти","где булыжный карьер","сдать задание булыжному карьеру"}},{q="Почему у дворфов-горных пехотинцев так мало людей?",a="Король Магни Бронзобород направил основную часть постоянной армии Стальгорна на широкие фронты Альянса за границей. Пока потери растут в других местах, пограничные посты, такие как в Лок Модане, остаются с минимальными гарнизонами и вынуждены полагаться на добровольцев из числа путников.",al={"why no dwarven guards","where are the reinforcements","ironforge army loch modan","почему нет дворфов-стражей","где подкрепления","армия стальгорна лок модан"}},{q="Где можно найти камнедробов-черепоколов и провидцев?",a="В основном они собираются в южных лагерях Долины Камнедробов к востоку от Долины Королей. Небольшая группа также обитает на самом северном острове озера Лок.",al={"stonesplinter skullthumper location","stonesplinter seer location","where are the troggs","камнедроб черепокол где найти","камнедроб провидец где найти","где трогги"}},{q="Почему целью выбраны именно череполы и провидцы?",a="Черепоколы — главные штурмовые войска племени камнедробов, а провидцы владеют примитивной магией и направляют младших троггов. Уничтожение и тех и других лишает захватчиков силы и магической согласованности.",al={"why kill seers","why skullthumpers","trogg targets","зачем убивать провидцев","зачем черепоколы","цели троггов"}},{q="Куда Булыжный Карьер отправляет вас дальше?",a="Булыжный Карьер направляет вас к горному пехотинцу Стенолому, стоящему у южной сторожевой башни в Долине Королей, чтобы помочь на следующем этапе обороны долины.",al={"next quest gravelgaw","who is wallbang","after defense of the king's lands","следующее задание булыжный карьер","кто такой стенолом","после защиты королевских земель"}}},fp="30,343,14.495.0,34.424.0,27.317.1,39.164.0,48.259.0,61.203.0,48.228.0,35.163.1"}
P.entries["quest:2378"] = {n="Поиски Изувеченной Длани",s="«Поиски Изувеченной Длани» — задание-путешествие, отправляющее многообещающих разбойников из числа Отрекшихся из Тирисфальских лесов через море в Дуротар. По указанию Стражей смерти новичок добирается до тайных недр Оргриммара, чтобы изучить особые умения у клана Изувеченной Длани.",h="«Поиски Изувеченной Длани» — задание-путешествие, отправляющее многообещающих разбойников из числа Отрекшихся...",kw={"cleft of shadow","deathstalkers","mennet carkad","orgrimmar","rogue quest","shattered hand","shenthul","расселина теней","стражи смерти","меннит каркад","оргриммар","задание разбойника","изувеченная длань","шентул"},ang={["class:Rogue"]="Это задание связывает местное обучение с широкой преступной и тайной сетью Орды и знакомит разбойников с главными наставниками подполья в Калимдоре.",["faction:Horde"]="Задание показывает, что сотрудничество в Орде не ограничивается воинами на передовой и шаманами: оно демонстрирует глубокую согласованность тайных служб Оргриммара и Подгорода.",["race:Undead"]="Для юных разбойников из числа Отрекшихся это официальный переход от борьбы с местными остатками Плети в Лордероне к включению в основные земли Орды в Дуротаре."},sec={{t="Союз теней",b="Пока Отрекшиеся растят собственный тайный орден — Стражей смерти, их союз с Ордой открывает возможности для сотрудничества в более темных искусствах. Меннит Каркад, увидев, как разбойник проявил себя в Тирисфальских лесах, понимает, что тому нужно более широкое обучение. Он направляет многообещающих теней на поиски Изувеченной Длани в Оргриммаре, опираясь на негласное партнерство между нежитью-агентами Лордерона и орочьей гильдией убийц Калимдора."},{t="В Расселину Теней",b="Путь заканчивается в глубине Расселины Теней — подземной пещеры под Оргриммаром, где чернокнижники, разбойники и укротители демонов занимаются ремеслами, на которые жители поверхности предпочитают не смотреть. Там ждет Шентул, наставник Изувеченной Длани. Одной репутацией его не впечатлить: суровый тролль встречает вновь прибывшего агента-нежить с жестоким скепсисом, желая проверить, есть ли у посланца настоящая хитрость или он зря пересек Великое море."}},faq={{q="Кто дает задание «Поиски Изувеченной Длани»?",a="Задание дает Меннит Каркад, наставник Стражей смерти в Квартале разбойников Подгорода, когда разбойник докажет свои базовые навыки в Тирисфальских лесах.",al={"who starts find the shattered hand","mennet carkad quest","who sends me to orgrimmar","кто дает поиски изувеченной длани","меннит каркад задание","кто посылает в оргриммар"}},{q="Где находится Шентул?",a="Шентул находится в Расселине Теней — темном ущелье под центральными путями Оргриммара.",al={"find shenthul","shenthul location","where is shenthul in orgrimmar","найти шентула","шентул где найти","где шентул в оргриммаре"}},{q="Какие отношения связывают Стражей смерти и Изувеченную Длань?",a="Стражи смерти — разведывательная сеть и гильдия убийц Отрекшихся, а Изувеченная Длань выполняет схожую тайную роль для Орды в Оргриммаре. Они сотрудничают как официальные союзники, обмениваясь продвинутым обучением и тайными контрактами между разными силами Орды.",al={"deathstalkers and shattered hand","forsaken rogues orc rogues","why sent to orgrimmar","стражи смерти и изувеченная длань","разбойники отрекшиеся орки","почему отправили в оргриммар"}},{q="Почему Шентул называет меня бесперспективным?",a="Изувеченная Длань превыше всего ценит физическую стойкость и безжалостную хитрость. Шентул часто оскорбляет и принижает новичков, чтобы сломить их гордость и проверить, хватит ли им решимости выдержать суровую подготовку убийц.",al={"shenthul dialogue","why is shenthul mean","shenthul completion text","диалог шентула","почему шентул грубит","текст завершения шентул"}},{q="Что происходит после встречи с Шентулом?",a="Шентул сразу берет агента в работу: предлагает задание «Зандо'зан» и затем отправляет его на юг, в Кабестан, для практических полевых операций в Степях.",al={"what comes after find the shattered hand","next quest after shenthul","shattered hand chain","что после поисков изувеченной длани","следующее задание после шентула","цепочка изувеченной длани"}},{q="Могут ли разбойники не из числа Отрекшихся получить это задание?",a="Нет. «Поиски Изувеченной Длани» — вариант для Отрекшихся, который выдают Стражи смерти. Разбойники-орки и тролли в Дуротаре получают равнозначное переходное задание «В Оргриммар!».",al={"orc rogue find the shattered hand","troll version","to orgrimmar alternate","разбойник орк поиски изувеченной длани","версия для троллей","в оргриммар другой вариант"}}},fp="23,266,19.462.0,24.474.0,44.169.0,26.105.0,74.297.0,38.228.0,37.178.0,39.189.0"}
P.entries["quest:2379"] = {n="Зандо'зан",s="Это поручение направляет многообещающих разбойников Орды к Зандо'зану в глубины Расселины Теней в Оргриммаре. Отправленный наставником Шентулом, новичок делает первые шаги в тайных рядах и запретных приемах Изувеченной Длани.",h="Это поручение направляет многообещающих разбойников Орды к Зандо'зану в глубины Расселины Теней в Оргриммаре.",kw={"cleft of shadow","lockpicking","orgrimmar","rogue","shattered hand","shenthul","stealth","wrenix","zando'zan","расселина теней","взлом замков","оргриммар","разбойник","изувеченная длань","шентул","скрытность","рэникс","зандо'зан"},ang={["class:Rogue"]="Это задание — ваше официальное посвящение в тайный аппарат Изувеченной Длани: из неопытного бойца на ножах вы становитесь признанным агентом Орды.",["faction:Horde"]="Хотя вождь часто говорит о чести и лобовой атаке, Изувеченная Длань берет на себя необходимый шпионаж и тайную грязную работу, оберегая молодую Орду от невидимых угроз."},sec={{t="Шаг в тень",b="Оргриммар может казаться крепостью грубой силы и воинской дисциплины, но его правители знают, что одной мускулатурой не выиграть каждую войну. В подземном сумраке Расселины Теней действует Изувеченная Длань — тайная гильдия, занимающаяся шпионажем, диверсиями и кражами для Орды. Когда наставник разбойников Шентул решает, что новичок подает достаточно надежд, он посылает его доложиться непосредственно Зандо'зану для особой подготовки агентов."},{t="Доказать свою ценность",b="Зандо'зан не выказывает уважения каждому зеленому разбойнику, забредшему в пещеру. Обращение к нему — формальное посвящение в тонкие тайные искусства, начиная с деликатных навыков скрытности, обмана и воровства. Встреча с Зандо'заном сокращает разрыв между уличными карманниками и организованными агентами разведки и готовит разбойника к непростой полевой работе за безопасными красными стенами каньона столицы."}},faq={{q="Кто такой Зандо'зан?",a="Зандо'зан — наставник разбойников и куратор Изувеченной Длани, живущий в подземной Расселине Теней в Оргриммаре. Он оценивает новобранцев и обучает их практической скрытности, взлому и ремеслу агента.",al={"zandozan","who is zando'zan","zando'zan cleft of shadow","зандозан","кто такой зандо'зан","зандо'зан расселина теней"}},{q="Почему Шентул посылает разбойников к Зандо'зану?",a="Шентул видит, когда начинающий разбойник перерос простые драки и нуждается в особой подготовке как агент Изувеченной Длани. Зандо'зан руководит уроками взлома и работы с замками, необходимыми для тайных полевых операций.",al={"why do i talk to zando'zan","shenthul zando'zan","purpose of quest","зачем говорить с зандо'заном","шентул зандо'зан","цель задания"}},{q="Что такое Изувеченная Длань в Оргриммаре?",a="Изначально жестокий орочий клан из Дренора, известный ритуальным самоувечьем, Изувеченная Длань в Дуротаре превратилась в тайную разведывательную и убийственную службу Орды. Ее члены действуют из тени Оргриммара и занимаются шпионажем, ядами и разведкой.",al={"what is shattered hand","shattered hand orgrimmar","horde rogues shattered hand","что такое изувеченная длань","изувеченная длань оргриммар","разбойники орды изувеченная длань"}},{q="Куда ведет эта цепочка обучения дальше?",a="Представившись Зандо'зану, вы получаете от него направление в Кабестан на побережье Степей, к связному-гоблину по имени Рэникс, чтобы начать практическую полевую работу со взломом замков.",al={"next quest","what comes after zando'zan","wrenix of ratchet","следующее задание","что после зандо'зана","рэникс кабестан"}},{q="Где найти Зандо'зана?",a="Он скрывается в Расселине Теней — глубокой сети пещер под центром Оргриммара, где чернокнижники, жрецы теней и агенты-разбойники собираются вдали от дневного света.",al={"zando'zan location","where is zando'zan","how to find zando'zan","зандо'зан где найти","где зандо'зан","как найти зандо'зана"}},{q="Почему Зандо'зан извиняется при встрече со мной?",a="Скорее всего, у Зандо'зана были сомнения или он не верил в вашу решимость до вашего прихода. Увидев вас перед собой готовым учиться, он вынужден признать вашу преданность делу и отказаться от прежнего скепсиса.",al={"why zandozan apologize","completion dialogue zando'zan","почему зандозан извиняется","диалог завершения зандо'зан"}}},fp="9,249,23.461.0,19.441.0,17.220.0,47.240.0,40.273.0,41.190.1,27.182.0,45.195.0"}
P.entries["quest:2380"] = {n="В Оргриммар!",s="«В Оргриммар!» — вводное поручение, по которому начинающий разбойник Орды из Колючего Холма отправляется в столицу. По приказу Каплака новичок должен спуститься в Расселину Теней, явиться к Шентулу и войти глубже в сеть Изувеченной Длани.",h="«В Оргриммар!» — вводное поручение, по которому начинающий разбойник Орды из Колючего Холма отправляется в...",kw={"cleft of shadow","kaplak","razor hill","rogue","shattered hand","shenthul","to orgrimmar","расселина теней","каплак","колючий холм","разбойник","изувеченная длань","шентул","в оргриммар"},ang={["class:Rogue"]="Это поручение знаменует ваше официальное посвящение в тайную сеть столицы: вы переходите от грубых стычек на границе к ремеслу ядов, воровства и обмана под надзором Шентула.",["faction:Horde"]="Тихое недовольство Шентула показывает трения между благородным новым путем Тралла и теневыми остатками старых кланов, уцелевшими под Оргриммаром."},sec={{t="Вызов в тени",b="Набравшись опыта в Дуротаре, начинающие разбойники рано или поздно привлекают внимание более влиятельных наставников. В Колючем Холме Каплак прямо признает, что зарождающиеся таланты агента, хоть и неотесанные, были замечены. Вместо того чтобы оставаться среди красных скал, агента направляют на север, в пещерные закоулки Оргриммара."},{t="Под бдительным оком Тралла",b="Встреча с Шентулом в подземной Расселине Теней открывает более глубокое напряжение под основополагающими идеалами Орды. Шентул не скрывает своей настороженности к политическим реформам вождя Тралла. Для Изувеченной Длани грубой силы и открытого неповиновения никогда не хватит для защиты своих интересов: для выживания и влияния нужны терпение, скрытность и тонкий обман."}},faq={{q="Кто отправляет меня на это задание?",a="Каплак, учитель разбойников в Колючем Холме, передает вызов, решив, что ваши навыки привлекли внимание начальства в Оргриммаре.",al={"quest giver","who gives to orgrimmar","kaplak quest","кто выдает задание","кто дает задание в оргриммар","задание каплака"}},{q="Где найти Шентула?",a="Шентул находится в Расселине Теней — темном подземном районе глубоко под Оргриммаром, где собираются разбойники, чернокнижники и прочие изгои.",al={"shenthul location","where is shenthul","cleft of shadow shenthul","где шентул","шентул расположение","расселина теней шентул"}},{q="Каковы цели Изувеченной Длани в Оргриммаре?",a="Изувеченная Длань действует как гильдия разведки и убийств внутри Орды. Формально входя в новую столицу, такие лидеры, как Шентул, с опаской относятся к благородным реформам Тралла и делают упор на скрытность, чтобы сохранить влияние и выжить.",al={"shattered hand motives","why shattered hand in orgrimmar","shattered hand thrall","цели изувеченной длани","зачем изувеченная длань в оргриммаре","изувеченная длань тралл"}},{q="Почему меня посылают именно сейчас?",a="Начинающих агентов, показавших себя в простой разведке и стычках, привлекают к более формальным обязанностям гильдии, начиная со взлома замков и тайных полевых поручений в столице.",al={"level 16 rogue quest","why go to orgrimmar now","rogue training summons","задание разбойника 16 уровня","почему в оргриммар сейчас","вызов разбойников на обучение"}},{q="Чем это задание отличается от «Поисков Изувеченной Длани»?",a="Оба вводных задания ведут разбойников к Шентулу в Оргриммаре; в зависимости от того, где вы учитесь или получаете приказы, вам достается одно из них для продвижения по той же цепочке обучения.",al={"find the shattered hand vs to orgrimmar","alternate breadcrumb quest","поиски изувеченной длани","в оргриммар","альтернативное вводное задание"}},{q="Что будет после доклада Шентулу?",a="Шентул проверяет вашу пригодность и направляет вас дальше, знакомя с такими контактами, как Зандо'зан, а затем и с тайной работой с гоблинами в Кабестане.",al={"next quest after to orgrimmar","what does shenthul give","следующее задание после в оргриммар","что дает шентул"}}},fp="13,301,24.353.0,27.382.1,27.157.0,25.157.0,49.250.0,47.188.0,54.189.0,41.174.0"}
P.entries["quest:2381"] = {n="Грабь награбленное",s="Это испытание, которое дает гоблин Реникс Презренный в Кабестане, проверяет начинающего разбойника Орды в схватке с Флибустьерами Южных морей. Проникнув на пиратский корабль «Волнорез», агенты должны обойти головорезов, вскрыть замки в трюме и обезвредить чудовищного пернатого стража с помощью гоблинской техники, чтобы завладеть Сокровищем Южного моря.",h="Это испытание, которое дает гоблин Реникс Презренный в Кабестане, проверяет начинающего разбойника Орды в...",kw={"e.c.a.c.","lockpicking","plundering the plunderers","polly","ratchet","southsea freebooters","southsea treasure","thistle tea","tide razor","wrenix the wretched","хочу","взлом замков","грабь награбленное","полли","кабестан","флибустьеры южных морей","сокровище южного моря","артишоковый чай","волнорез","реникс презренный"},ang={["class:Rogue"]="Это испытание учит важнейшему искусству взлома замков под давлением и награждает ценным рецептом артишокового чая, становясь незаменимым этапом для любого агента на службе Орды.",["faction:Horde"]="Изувеченная Длань использует нейтральные гоблинские связи в Кабестане, чтобы проверять будущих полевых агентов в схватках с Флибустьерами Южных морей, угрожающими побережью Степей.",["profession:Cooking"]="Задание дает кулинарный рецепт артишокового чая, позволяя разбойникам с тягой к кулинарии готовить собственные тонизирующие напитки из простых трав и воды."},sec={{t="Испытание скрытности и стали",b="Для начинающего агента Изувеченной Длани грубая сила ничего не значит без ловкости. Реникс Презренный, гоблин из Кабестана, устраивает полевое испытание. Он направляет разбойников на юг вдоль выжженного солнцем побережья Степей в бухту, где стоит «Волнорез», корабль Флибустьеров Южных морей. Задача обманчиво проста: незаметно подняться на борт, проникнуть в пиратское логово, где обучают собственных карманников, вскрыть сундуки в нижнем трюме и принести их драгоценную добычу."},{t="Полли и штуковина",b="Для добычи нужны не только ловкие пальцы. Реникс предупреждает, что прежние воры возвращались к нему по частям, в основном из-за стража нижнего трюма — свирепого попугая по имени Полли. Чтобы справиться с этим крылатым ужасом, Реникс дает экспериментальное устройство — ХОЧУ. Если бросить его в злобную птицу после вскрытия пиратского сундука, штуковина дезориентирует и уменьшает зверя, превращая верную смерть в победимую схватку."}},faq={{q="Кто такой Реникс Презренный?",a="Реникс Презренный — гоблин-разбойник, контакт в нейтральном порту Кабестан. Работая с агентами, связанными с Изувеченной Дланью Оргриммара, он испытывает начинающих воров, отправляя их на пиратскую территорию практиковаться во взломе замков и возвращать награбленное.",al={"wrenix","who is wrenix","ratchet goblin rogue quest","реникс","кто такой реникс","задание разбойника в кабестане"}},{q="Где находится «Волнорез»?",a="«Волнорез» стоит на якоре к югу от Кабестана на восточном побережье Степей, внутри поселения Флибустьеров Южных морей. Корабль служит базой и учебным логовом пиратских проходимцев.",al={"tide razor location","where is pirate ship","where are the southsea pirates","волнорез расположение","где пиратский корабль","где пираты южных морей"}},{q="Что такое ХОЧУ и как им пользоваться?",a="ХОЧУ — экспериментальная гоблинская штуковина, которую выдает Гизмотронный аппарат Реникса. Ее применяют против Полли, смертоносного гигантского попугая, охраняющего Сокровище Южного моря в трюме «Волнореза»: она сильно ослабляет зверя, и его можно победить.",al={"ecac","what is ecac","how to beat polly","хочу","что такое хочу","как победить полли"}},{q="Чем важна зона взлома замков на корабле?",a="Вторая палуба «Волнореза» служит учебной комнатой пиратов Южных морей. Там стоят возрождающиеся запертые ящики, на которых разбойники могут отработать взлом замков в полевых условиях, прежде чем взяться за главный сундук внизу.",al={"lockpicking practice","footpad training ship","picking boxes barrens","тренировка взлома","учебный корабль разбойников","вскрытие ящиков степи"}},{q="Почему это задание так важно для разбойников?",a="Успешное ограбление доказывает ценность разбойника для сети Изувеченной Длани. В качестве вашей доли Реникс награждает вас секретным рецептом артишокового чая — бесценного травяного отвара, быстро восстанавливающего энергию разбойника в бою.",al={"rogue quest thistle tea","why do plundering the plunderers","rogue quest reward","задание разбойника артишоковый чай","грабь награбленное","награда разбойника"}},{q="Кто такая Полли?",a="Полли — свирепый сторожевой попугай Флибустьеров Южных морей, обитающий в нижнем трюме «Волнореза». Если ее не ослабить гоблинской техникой, птица смертельно опасна для неопытных лазутчиков.",al={"polly","giant parrot","tide razor boss","полли","гигантский попугай","босс волнореза"}}},fp="25,348,27.537.0,19.489.1,27.264.0,32.195.0,40.257.0,52.248.0,40.228.0,13.214.0"}
P.entries["quest:2382"] = {n="Реникс из Кабестана",s="«Реникс из Кабестана» — задание разбойникам Орды, направляющее начинающих агентов из Оргриммара в гоблинский порт Кабестан. Безумный тролль Зандо'зан отправляет агентов на юг помочь скверному гоблину по имени Реникс Презренный.",h="«Реникс из Кабестана» — задание разбойникам Орды, направляющее начинающих агентов из Оргриммара в гоблинский...",kw={"ratchet","rogue","shattered hand","the barrens","thrall","wrenix","zando'zan","кабестан","разбойник","изувеченная длань","степи","тралл","реникс","зандо'зан"},ang={["class:Rogue"]="Это путешествие — важный этап обучения разбойника Орды: оно уводит молодых агентов из безопасного Оргриммара на нейтральную пиратскую территорию.",["faction:Horde"]="Изувеченная Длань держит глаза и уши за пределами Дуротара, часто полагаясь на нейтральные порты вроде Кабестана для щекотливых поручений."},sec={{t="Пророк в тени",b="В извилистых расселинах Расселины Теней в Оргриммаре гильдия разбойников действует по большей части незаметно. Агентов, пришедших к Зандо'зану, встречают дикие бормотания и зловещие предзнаменования, включая мрачные видения убийства вождя Тралла ядом и клинком. Вместо объяснения пророчества эксцентричный тролль быстро отправляет агентов в портовый город Кабестан в Степях."},{t="Решатель проблем Кабестана",b="Нейтральный порт Кабестан, лежащий на побережье к востоку от Перекрестка, приютил всевозможных негодяев, наемников и умельцев. Реникс Презренный работает в этой шумной гавани, хотя терпения к чудачествам Зандо'зана у него мало. По словам Реникса, прежние посланцы тролля нашли печальный конец в кишащих хищниками водах бухты."}},faq={{q="Кто отправляет вас в Кабестан?",a="Зандо'зан, тролль, связанный с Изувеченной Дланью в Расселине Теней Оргриммара, посылает вас с этим поручением, выпалив странные видения.",al={"who gives quest","quest giver","zandozan","кто дает задание","кто выдает задание","зандозан"}},{q="Кто такой Реникс Презренный?",a="Реникс Презренный — гоблин, контакт в портовом городе Кабестан. Он занимается тайными делами и механическим снабжением разбойников, действующих в Степях.",al={"who is wrenix","wrenix ratchet","wrenix identity","кто такой реникс","реникс кабестан","личность реникса"}},{q="Что случилось с агентами, посланными до меня?",a="По словам Реникса, предыдущие пять агентов, посланных Зандо'заном, провалили задания и стали кормом для акул у берегов Кабестана.",al={"previous rogues","shark food","other recruits","прежние разбойники","корм для акул","другие новобранцы"}},{q="О чем говорил Зандо'зан насчет Тралла?",a="Зандо'зан утверждает, что видел, как Тралла поражает в спину отравленный кинжал, но тут же обрывает себя и меняет тему.",al={"thrall prophecy","thrall poisoned","zandozan thrall vision","пророчество о тралле","тралл отравлен","видение зандозана о тралле"}},{q="Где находится Кабестан?",a="Кабестан расположен на восточном побережье Степей, прямо к востоку от Перекрестка. С Дуротаром его соединяют дороги, идущие на юг от Реки Строптивой.",al={"where is ratchet","find ratchet","ratchet location","где кабестан","найти кабестан","расположение кабестана"}},{q="Что дальше после встречи с Рениксом?",a="Поприветствовав Реникса, вы получаете от него задание «Грабь награбленное», которое предполагает проникновение к Флибустьерам Южных морей на побережье к югу от Кабестана.",al={"next quest","after wrenix","ratchet follow up","следующее задание","после реникса","продолжение в кабестане"}}},fp="17,236,24.403.0,24.363.0,25.146.0,27.167.0,47.147.0,50.159.0,25.164.0,37.155.1"}
P.entries["quest:239"] = {n="Гарнизон у Западного ручья просит помощи!",s="Маршал Дугхан отправляет всех свободных искателей приключений на запад, в Гарнизон у Западного ручья — застава охраняет границу Элвиннского леса с Западным Краем. Поскольку армия Штормграда растянута по всему королевству, Заместитель судьи Рейнер и его стража без регулярного подкрепления испытывают растущее давление со стороны агрессивных гноллов Речной Лапы и бродячих воров.",h="Маршал Дугхан отправляет всех свободных искателей приключений на запад, в Гарнизон у Западного ручья —...",kw={"deputy rainer","elwynn forest","gnolls","goldshire","marshal dughan","riverpaw","westbrook garrison","заместитель судьи рейнер","элвиннский лес","гноллы","златоземье","маршал дугхан","речная лапа","гарнизон у западного ручья"},ang={["faction:Alliance"]="Добровольцы Альянса занимают место регулярных солдат, выполняя необходимую черновую работу, чтобы не дать основным землям скатиться в полный хаос.",["race:Human"]="Для людей Штормграда это поручение — тревожный знак пренебрежения королевства: оно воочию показывает, как истончилась оборона короны после исчезновения Короля."},sec={{t="Растянутая граница",b="Гарнизон у Западного ручья отмечает западный край Элвиннского леса, там, где обжитые лесные земли начинают сменяться неспокойными равнинами Западного Края. Поскольку отряды гноллов и бандиты становятся смелее вдоль рек и западных дорог, малочисленный гарнизон заставы просит подкрепления. Однако у маршала Дугхана и управления Златоземья нет профессиональных солдат Штормграда, так что местным командирам остается нанимать странствующих наемников и искателей приключений."},{t="Угроза за ручьем",b="Главная угроза для Заместителя судьи Рейнера и его людей — стая гноллов Речной Лапы, чьи рейдерские отряды донимают путников и ближние усадьбы. Действуя в приграничье между Элвинном и Западным Краем, гноллы воспользовались политической и военной занятостью Штормграда, чтобы проникнуть глубже в обитаемые земли. Гарнизон у Западного ручья — последний рубеж, не дающий им свободно бродить в сердце леса."}},faq={{q="Почему Штормград не может прислать регулярных солдат в Гарнизон у Западного ручья?",a="Регулярная армия Штормграда крайне перегружена на многих границах. Поскольку король Вариан Ринн пропал, а королевство охвачено внутренними раздорами, верховное командование отказалось или не смогло направить регулярных солдат на сельские заставы, и городским маршалам вроде Дугхана приходится полагаться на вольных добровольцев.",al={"why no stormwind troops","why send adventurers","where is stormwind army","почему нет войск штормграда","зачем посылать искателей приключений","где армия штормграда"}},{q="Где находится Гарнизон у Западного ручья?",a="Гарнизон стоит на западном краю Элвиннского леса. Следуйте по главной дороге на запад из Златоземья мимо небольшого ручья; укрепленная башня будет справа, прямо перед границей с Западным Краем.",al={"westbrook garrison location","how to get to westbrook","where is deputy rainer","гарнизон у западного ручья расположение","как добраться до западного ручья","где заместитель судьи рейнер"}},{q="Какие угрозы беспокоят гарнизон?",a="Заместитель судьи Рейнер сталкивается с постоянными набегами гноллов Речной Лапы, а также с ростом активности воров и бандитов в приграничье между Западным Краем и Элвиннским лесом.",al={"what attacks westbrook","why does rainer need help","who is attacking westbrook garrison","кто атакует западный ручей","зачем рейнеру помощь","кто нападает на гарнизон у западного ручья"}},{q="Кто такой Заместитель судьи Рейнер?",a="Заместитель судьи Рейнер — офицер Штормграда, командующий Гарнизоном у Западного ручья. Ему поручено удерживать западную границу, и из-за острой нехватки официального подкрепления он вынужден обращаться к добровольцам из мирных жителей и наемникам.",al={"rainer lore","deputy rainer","who is rainer","предания о рейнере","заместитель судьи рейнер","кто такой рейнер"}},{q="Что будет после доклада Заместителю судьи Рейнеру?",a="Заместитель судьи Рейнер сразу привлекает вас против местных гноллов Речной Лапы, назначая награду за их ошейники, чтобы сократить их число и защитить пограничную дорогу.",al={"what comes next","westbrook quest chain","rainer quest","что дальше","цепочка заданий западного ручья","задание рейнера"}},{q="Почему гноллы продвигаются в Элвиннский лес?",a="Гноллы Речной Лапы устроили лагеря вдоль рек, разделяющих Элвинн и Западный Край. Пользуясь ослабленным военным присутствием на границе, они осмелели настолько, что грабят торговые пути и продвигаются к внутренним фермам Элвинна.",al={"riverpaw gnolls elwynn","why are gnolls here","gnoll problem","гноллы речной лапы элвинн","почему здесь гноллы","проблема с гноллами"}}},fp="30,345,25.500.0,27.446.0,64.313.0,36.200.0,40.188.0,21.244.0,46.162.0,46.249.0"}
P.entries["quest:2399"] = {n="Росток папоротника",s="После ботанических опытов Деналана у озера Аль'Амет посаженные семена папоротника прорастают и расцветают. Этот тихий момент знаменует успешный урожай в изучении странной и жизненно важной флоры Тельдрассила. Путники, осматривающие грядки, могут своими глазами увидеть быстрый рост.",h="После ботанических опытов Деналана у озера Аль'Амет посаженные семена папоротника прорастают и расцветают.",kw={"denalan","herbalism","planter","seeds","shimmering frond","sprouted fronds","teldrassil","wellspring lake","деналан","травничество","грядка","семена","мерцающий папоротник","росток папоротника","тельдрассил","озеро"},ang={["class:Druid"]="Друиды, наблюдающие за грядкой Деналана, могут оценить тихое равновесие природы: жизнь расцветает под заботливым уходом даже среди растущих опасностей Тельдрассила.",["profession:Herbalism"]="Исследования Деналана отражают практическое искусство сбора и изучения уникальной растительности Тельдрассила и показывают, как быстро местные семена приживаются в ухоженной почве.",["race:NightElf"]="Уход за новыми ростками отражает ответственность кальдораев за наблюдение и поддержание жизни, укореняющейся на их молодом Мировом Древе."},sec={{t="Сад у озера Аль'Амет",b="Неподалеку от озера Аль'Амет ботаник Деналан посвящает себя описанию необычных растений Тельдрассила. После посева семян, найденных на таинственном мерцающем папоротнике, почва быстро дает результат. В его ухоженной грядке из плодородной земли тянутся вверх странные дрожащие листья папоротника, которые так и ждут, чтобы их собрали и изучили."},{t="Странная флора Мирового Древа",b="Тельдрассил молод, огромен и стремительно развивается, что одновременно очаровывает и тревожит травников-ночных эльфов. Мерцающие листья папоротника и их проросшие побеги — яркий признак того, как быстро жизнь укореняется на ветвях великого дерева, и намек на мощную, но непредсказуемую жизненную силу, заключенную в почве острова."}},faq={{q="Что такое росток папоротника?",a="Это взрослые растения, выросшие из семян, посеянных Деналаном в его лагере у озера. Эти необычные растения, выращенные из мерцающего папоротника, найденного в других местах Тельдрассила, дрожат от энергии, когда готовы к сбору.",al={"sprouted fronds","what are these plants","denalans fronds","росток папоротника","что это за растения","папоротник деналана"}},{q="Где находится сад Деналана?",a="Деналан держит сад и исследовательский лагерь на восточном берегу озера Аль'Амет, к юго-востоку от Доланаара в Тельдрассиле.",al={"denalan location","where is denalan","wellspring lake garden","где деналан","расположение деналана","сад у озера"}},{q="Зачем Деналан сажает этот папоротник?",a="Деналан изучает необычный и быстрый рост растений Тельдрассила. Сажая семена в контролируемую почву, он исследует их природу и проверяет, обладают ли они полезными целебными или травяными свойствами.",al={"why plant fronds","denalan experiment","purpose of fronds","зачем сажать папоротник","опыт деналана","цель папоротника"}},{q="Опасен ли росток папоротника?",a="Нет. В отличие от некоторой оскверненной или враждебной флоры на ветвях Тельдрассила, эти ростки папоротника — безвредные ботанические образцы, которые остается лишь сорвать.",al={"are fronds dangerous","do fronds attack","is the plant harmful","опасен ли папоротник","нападает ли папоротник","вредно ли растение"}},{q="Что предшествует этому заданию?",a="Искатели приключений сначала находят мерцающий папоротник в глуши Тельдрассила и приносят его Деналану, который сажает семена в грядку в своем саду и ждет всходов.",al={"prereq for sprouted fronds","what quest comes first","предыдущее задание","какое задание первое"}},{q="Почему папоротник дрожит?",a="Листья дрожат в ожидании сбора. Источник не объясняет, что вызывает это движение.",al={"trembling fronds","why do they shake","дрожащий папоротник","почему они трясутся"}}},fp="19,281,25.337.0,35.336.0,29.224.0,34.120.0,36.220.0,34.166.0,29.166.0,26.96.0"}
P.entries["quest:24"] = {n="Голова Тенумбры",s="Это задание — доказательство победы над Тенумброй, свирепой ночной саблезубой кошкой, выслеживавшей путников на западных тропах Ясеневого леса. Отнести отрубленную голову зверя Сенани Громовому Сердцу на Заставе Расщепленного Дерева — ключевое испытание Большой охоты, которое открывает безопасные пути к Зорамскому взморью.",h="Это задание — доказательство победы над Тенумброй, свирепой ночной саблезубой кошкой, выслеживавшей путников...",kw={"ashenvale hunt","nightsaber","senani thunderheart","shadumbra","splintertree post","trophy","zoram strand","большая охота","ночная саблезубая кошка","сенани громовое сердце","тенумбра","застава расщепленного дерева","трофей","зорамское взморье"},ang={["class:Hunter"]="Выследить и одолеть неуловимую ночную саблезубую кошку вроде Тенумбры — образцовое испытание меткости, терпения и выживания в густом лесу.",["faction:Horde"]="Застава Расщепленного Дерева остается изолированным оплотом Орды; устранение местных угроз вроде Тенумбры сохраняет открытыми жизненно важные линии снабжения к Зорамскому взморью.",["race:Tauren"]="Для тауренов охота на зверя калибра Тенумбры чтит естественный порядок Матери-Земли: это проверка мастерства против хищника на вершине пищевой цепи и защита соплеменников на дороге."},sec={{t="Угроза западной дороги",b="Тенумбра — не обычный хищник среди высоченных деревьев Ясеневого леса. Огромная ночная саблезубая кошка рыскала в лесах к западу от Заставы Расщепленного Дерева и нападала на разведчиков и гонцов Орды, пытавшихся добраться до Зорамского взморья. Ее скорость, скрытность и свирепость делали путешествие пешком опасным, и защитники заставы были настороже всякий раз, когда патрули уходили на запад."},{t="Доказательство охоты",b="В рамках Большой охоты охотница-тауренка Сенани Громовое Сердце предлагает чемпионам Орды выследить и сразить главных зверей леса. Голова Тенумбры — не просто мрачная демонстрация мастерства: это неоспоримое доказательство того, что дороги стали безопаснее, а охотник одолел одного из самых смертоносных местных хищников Калимдора."}},faq={{q="Кто такая Тенумбра?",a="Тенумбра — исключительно свирепая ночная саблезубая кошка, бродившая по лесам к западу от Заставы Расщепленного Дерева. Она устраивала засады на путников, идущих в долгий путь к побережью, и считалась одним из самых опасных зверей Ясеневого леса.",al={"what is shadumbra","shadumbra lore","who is the cat","кто такая тенумбра","предания о тенумбре","кто эта кошка"}},{q="Зачем Сенани Громовому Сердцу нужна голова?",a="Сенани Громовое Сердце руководит Большой охотой на Заставе Расщепленного Дерева. Голова служит и традиционным трофеем впечатляющей охоты, и подтверждением того, что угроза путникам, идущим на запад, устранена.",al={"why bring head","senani thunderheart trophy","ashenvale hunt proof","зачем принести голову","трофей сенани громовое сердце","доказательство большой охоты"}},{q="Какое место это задание занимает в Большой охоте?",a="Это одно из главных испытаний, которые открываются после принятия Большой охоты. Убийство Тенумбры, а также других великих зверей леса, таких как Урсангус и Острый Коготь, приводит к окончательному признанию и заданию «Завершение охоты».",al={"what is ashenvale hunt","hunt questline","next hunt quest","что такое большая охота","цепочка заданий охоты","следующее задание охоты"}},{q="Почему устранение этого зверя важно для Орды?",a="Застава Расщепленного Дерева зависит от разведчиков и гонцов, идущих на запад к лагерю Орды в форте Зорам'гар на Зорамском взморье. Хищная натура Тенумбры постоянно угрожала пешим путникам Орды в диких лесах.",al={"why horde care","zoram strand road danger","splintertree post safety","почему орде важно","опасность дороги к зорамскому взморью","безопасность заставы расщепленного дерева"}},{q="Где можно найти Тенумбру?",a="Тенумбра рыщет в лесах к западу от Заставы Расщепленного Дерева, бродя среди деревьев между дорогой и древними руинами ночных эльфов, разбросанными по центральной и западной части Ясеневого леса.",al={"shadumbra location","where is shadumbra","find shadumbra","где тенумбра","расположение тенумбры","найти тенумбру"}},{q="Союзна ли Тенумбра ночным эльфам?",a="Нет. Хотя ночных саблезубых кошек ночные эльфы часто приручают и почитают, Тенумбра — дикий, неукротимый ужас леса, действующий исключительно по хищному инстинкту и угрожающий любому, кто пересечет ее территорию.",al={"is shadumbra a pet","sentinel pet","shadumbra night elf","питомец ли тенумбра","питомец стражей","тенумбра ночные эльфы"}}},fp="16,309,28.368.0,17.354.0,18.236.0,43.224.0,44.236.0,50.233.0,29.180.0,41.202.0"}
P.entries["quest:240"] = {n="Возвращение к Трясунчику",s="«Возвращение к Трясунчику» завершает кулинарное поручение Шеф-повара Груаля в Сумеречном лесу. Приготовив свои пресловутые «крабовые» пирожки из липких лапок местных ядовитых пауков, Груаль отправляет вас обратно к голодающему, перепуганному отшельнику на Вороньем Холме. Доставленная еда наконец утоляет отчаянный голод Трясунчика.",h="«Возвращение к Трясунчику» завершает кулинарное поручение Шеф-повара Груаля в Сумеречном лесу.",kw={"chef grual","darkshire","duskwood","dusky crab cakes","growling gut","jitters","scarlet raven tavern","шеф-повар груаль","темнолесье","сумеречный лес","темные пирожки с крабами","урчащий живот","трясунчик","таверна алый ворон"},ang={["faction:Alliance"]="Скудный, необычный рацион в Темнолесье показывает, насколько город отрезан от общих линий снабжения Штормграда: местным приходится полагаться на все, что скрывается в тенях.",["profession:Cooking"]="Умение Шеф-повара Груаля превращать липкие лапки ядовитых пауков в съедобные пирожки — свидетельство суровой находчивости, которой требует от поваров жизнь на границе."},sec={{t="Сомнительный деликатес",b="В Сумеречном лесу мало обычного скота и морепродуктов, поэтому Шеф-повар Груаль из Таверны «Алый ворон» импровизирует из того, что дает проклятый лес. Его известные «Темные пирожки с крабами» вовсе не содержат крабового мяса: их делают из липких лапок ядовитых пауков, ползающих по лесу. Груаль считает это находчивой кухней; людям с тонким желудком она может показаться ужасной."},{t="Успокоить Трясунчика",b="Трясунчик целыми днями сидит, сжавшись, на Вороньем Холме, объятый страхом и скованный ужасами, выгнавшими его из леса. Ослабев от ужаса и не находя смелости охотиться или собирать пищу, он страдает еще сильнее от пустого желудка. Теплые пирожки приносят дрожащему бродяге редкое облегчение, и он слишком голоден, чтобы спрашивать, какой именно «краб» пошел в дело у Шеф-повара Груаля."}},faq={{q="Из чего сделаны Темные пирожки с крабами?",a="В Сумеречном лесу нет крабов. Шеф-повар Груаль готовит свои фирменные пирожки из липких лапок местных ядовитых пауков, приправляя их так, чтобы они напоминали традиционные пирожки с морепродуктами.",al={"crab cakes ingredients","what are dusky crab cakes made of","are they real crab","состав пирожков с крабами","из чего темные пирожки с крабами","настоящий ли краб"}},{q="Знает ли Трясунчик, что пирожки сделаны из паучьей слизи?",a="Шеф-повар Груаль хранит свой кулинарный секрет при себе, а Трясунчик слишком голоден и напуган, чтобы расспрашивать о рецепте. Он жадно ест пирожки, не подозревая об их настоящем происхождении.",al={"does jitters know","does jitters know about the spiders","знает ли трясунчик","знает ли трясунчик о пауках"}},{q="Почему Трясунчик не мог добыть еду сам?",a="Трясунчик полностью подавлен страхом после встреч в диких чащах Сумеречного леса. Парализованный паникой, он отказывается уходить далеко от своего укрытия на Вороньем Холме и полагается на сочувствующих путников, которые приносят ему пищу.",al={"why is jitters starving","why doesn't jitters hunt","почему трясунчик голодает","почему трясунчик не охотится"}},{q="Кто такой Шеф-повар Груаль?",a="Шеф-повар Груаль — повар в Таверне «Алый ворон» в Темнолесье. Город отрезан тенями и зверьми, поэтому он использует любые необычные ингредиенты, которые приносят ему добытчики, чтобы кормить посетителей таверны.",al={"chef grual role","cook in darkshire","роль шеф-повара груаля","повар в темнолесье"}},{q="Где начинается эта цепочка заданий?",a="Поручение начинается с Трясунчика на Вороньем Холме, который просит помочь с урчащим животом в задании «Урчащий живот Трясунчика». Оно ведет к охоте на ядовитых пауков для Шеф-повара Груаля, после чего вы возвращаетесь сюда с готовым блюдом.",al={"how to start jitters food quest","jitters quest chain start","как начать задание с едой для трясунчика","начало цепочки трясунчика"}},{q="Приходит ли Трясунчик в себя после еды?",a="Еда утоляет его физический голод и приносит вам его искреннюю благодарность, но не излечивает глубоко засевший психологический ужас. Он по-прежнему тревожен и преследуем темными тайнами леса.",al={"is jitters cured","does food help jitters","излечен ли трясунчик","помогает ли еда трясунчику"}}},fp="17,299,18.423.0,24.416.0,32.168.0,51.177.0,38.240.0,18.209.0,34.216.0,34.204.0"}
P.entries["quest:2438"] = {n="Изумрудный ловец снов",s="Таллонкай Гибкий Корень из Доланаара просит искателей приключений вернуть дорогую семейную реликвию из его брошенного дома в Деревне Звездного Ветра. Изумрудный Ловец снов, подаренный ему хранителем-друидом Гароласом Талветреном, остался там, когда оскверненные фурболги Узловатой Сосны захватили мирное поселение. Возвращение амулета не позволит его мягкой природной магии попасть в нечистые руки.",h="Таллонкай Гибкий Корень из Доланаара просит искателей приключений вернуть дорогую семейную реликвию из его...",kw={"ban'ethil barrow den","dolanaar","emerald dream","emerald dreamcatcher","furbolg","gaerolas talvethren","gnarlpine","starbreeze village","tallonkai swiftroot","teldrassil","обитель бен'этиль","доланаар","изумрудный сон","изумрудный ловец снов","фурболг","гаролас талветрен","узловатая сосна","деревня звездного ветра","таллонкай гибкий корень","тельдрассил"},ang={["class:Druid"]="Амулет — прямое творение Гароласа Талветрена, хранителя, присматривающего за вашими спящими сородичами в Обители Бен'этиль, поэтому его возвращение — дело друидской чести.",["faction:Alliance"]="Помощь изгнанным кальдораям Доланаара укрепляет порядок в округе, пока Тельдрассил борется с распространяющейся скверной среди племен фурболгов.",["race:NightElf"]="Звездный Ветер когда-то был тихим приютом для вашего народа. Помогая Таллонкаю вернуть наследие, вы наносите небольшой удар по безумию, охватившему животных Тельдрассила."},sec={{t="Друидский талисман",b="Изумрудный ловец снов — гораздо больше, чем просто украшение. Амулет создал Гаролас Талветрен, почитаемый хранитель спящих друидов в Обители Бен'этиль, чтобы направлять безмятежные потоки Изумрудного Сна. Черпая эту чистую духовную энергию, ловец снов дарует своему владельцу покой и удачу. Такие талисманы чрезвычайно редки, и их вручают лишь немногим доверенным лицам, чья жизнь связана с заботой о лесе."},{t="Бегство из Деревни Звездного Ветра",b="Еще недавно Деревня Звездного Ветра была мирным поселением среди ветвей Тельдрассила. Эта тихая жизнь закончилась, когда местные фурболги Узловатой Сосны впали в неистовое безумие и изгнали ночных эльфов из их древних жилищ. В ужасе и суматохе эвакуации Таллонкаю пришлось оставить свое самое ценное достояние спрятанным в комоде в юго-восточной части деревни: самостоятельно забрать его он не в силах."},{t="Угроза осквернения",b="Оставить средоточие магии Изумрудного Сна в сердце захваченной деревни очень опасно. Племя Узловатой Сосны оказалось подвержено темному влиянию, и артефакт, пульсирующий энергией Сна, легко может быть осквернен или обращен в оружие. Если безопасно вернуть ловец снов, частица наследия Звездного Ветра вернется к Таллонкаю, прежде чем фурболги или иные нечистые твари осквернят его остаточную магию."}},faq={{q="Что такое Изумрудный ловец снов?",a="Это редкий амулет, созданный Гароласом Талветреном, хранителем друидов в Обители Бен'этиль. Ловец снов черпает энергию Изумрудного Сна и дарует удачу и духовную гармонию тому, кто его носит.",al={"what is the dreamcatcher","dreamcatcher lore","emerald dreamcatcher","что такое ловец снов","ловец снов предания","изумрудный ловец снов"}},{q="Почему ловец снов остался в Деревне Звездного Ветра?",a="Деревню Звездного Ветра быстро захватили, когда местные фурболги Узловатой Сосны впали в неистовство и скверну. Таллонкаю Гибкому Корню пришлось спасаться бегством в Доланаар, а драгоценная реликвия осталась в комоде в его спальне.",al={"why leave it behind","starbreeze village dresser","tallonkai dresser","почему оставил","комод в деревне звездного ветра","комод таллонкая"}},{q="Кто такой Таллонкай Гибкий Корень?",a="Таллонкай — беженец-ночной эльф, который сейчас живет в Доланааре. Спасшись при падении Деревни Звездного Ветра, он ищет отважных путников, готовых вернуться в занятые врагом руины, чтобы забрать семейные реликвии и уберечь друидские сокровища.",al={"who is tallonkai","tallonkai swiftroot","кто такой таллонкай","таллонкай гибкий корень"}},{q="Кто создал ловец снов?",a="Его создал и подарил Гаролас Талветрен, хранитель, который присматривает за спящими друидами в Обители Бен'этиль.",al={"who made it","gaerolas talvethren dreamcatcher","gaerolas","кто создал","гаролас талветрен ловец снов","гаролас"}},{q="Где в Деревне Звездного Ветра находится ловец снов?",a="Он лежит в личном комоде Таллонкая, в самом юго-восточном доме Деревни Звездного Ветра, где теперь рыщут враждебные фурболги Узловатой Сосны.",al={"where is the dresser","starbreeze dresser location","find dreamcatcher","где комод","расположение комода звездного ветра","найти ловец снов"}},{q="Что происходит после возвращения ловца снов?",a="Осмотрев возвращенный амулет, Таллонкай обнаруживает, что изумруд пропал: его похитил предводитель Узловатой Сосны Фероситас Пожиратель Снов. Так начинается охота на него.",al={"quest continuation","next quest after dreamcatcher","продолжение задания","следующее задание после ловца снов"}}},fp="24,377,18.471.0,26.451.0,24.410.1,33.219.0,59.242.0,27.237.0,26.128.0,56.172.0,48.185.1"}
P.entries["quest:244"] = {n="Вторжение гноллов",s="«Вторжение гноллов» — задание Альянса: стража Приозерья предупреждает о гноллах, опасно близко подбирающихся к границе Элвиннского леса. Стражник Паркер обнаруживает лагеря вдоль пограничного перевала и отправляет путников предупредить Заместителя судьи Фелдона. Новости подтверждают растущие опасения Приозерья, что зверолюды хотят полностью отрезать Красногорье.",h="«Вторжение гноллов» — задание Альянса: стража Приозерья предупреждает о гноллах, опасно близко подбирающихся...",kw={"assessing the threat","deputy feldon","elwynn border","encroaching gnolls","guard parker","lakeshire","redridge","подсчет врагов","заместитель судьи фелдон","граница элвиннского леса","вторжение гноллов","стражник паркер","приозерье","красногорье"},ang={["faction:Alliance"]="Изоляция Приозерья угрожает восточному фронту Альянса, поэтому разведданные о границе очень важны для путников и обозов со снабжением.",["race:Human"]="Вторжение зверолюдов в виду Элвиннского леса показывает, насколько уязвимыми стали центральные земли королевства в отсутствие короля."},sec={{t="Глаза на границе",b="Дорога из Элвиннского леса в Красногорье должна быть одним из самых безопасных путей королевства, но поредевшие силы Штормграда почти не защищают ее. Стражник Паркер несет службу на западной пограничной тропе и следит за передвижениями. Ему удается держать гравийную дорогу проходимой для обозов, но разведка на севере и востоке показывает, что отряды гноллов спустились со скал и разбили лагеря тревожно близко к дороге."},{t="Город в осаде",b="Получив сигнал у моста Приозерья, Заместитель судьи Фелдон понимает, что положение хуже, чем он думал. Гноллы Красногорья не просто грабят окраины города: их передовые отряды у границы Элвиннского леса могут окружить Приозерье и прорваться в сердце королевства. Штормград не отвечает на мольбы о подкреплении, и дозор Приозерья плохо готов к угрозе с двух сторон."}},faq={{q="Кто выдает это задание?",a="Стражник Паркер выдает это задание на дороге в западной части Красногорья, около пограничного перехода в Элвиннский лес.",al={"quest giver","where to start","guard parker location","персонаж, выдающий задания","где начать","где стражник паркер"}},{q="Где найти Заместителя судьи Фелдона?",a="Заместитель судьи Фелдон несет службу в Приозерье и патрулирует местность чуть южнее большого каменного моста города.",al={"feldon location","who is deputy feldon","turn in location","где фелдон","кто такой заместитель судьи фелдон","где сдать задание"}},{q="Чем гноллы опасны для дороги?",a="Дорога в Элвиннский лес — единственная безопасная сухопутная связь Приозерья с остальным королевством. Если гноллы захватят западные склоны, город окажется отрезан от снабжения и путей отступления.",al={"why gnolls matter","redridge gnoll problem","road danger","почему важны гноллы","проблема гноллов красногорья","опасность дороги"}},{q="Почему Штормград не присылает помощь в Приозерье?",a="Король Вариан Ринн пропал, а королевство охвачено волнениями, поэтому верховный лорд Болвар и двор отказались посылать королевские войска в Красногорье. Оборона Приозерья целиком легла на местных помощников шерифа и добровольцев.",al={"where are stormwind guards","no reinforcements","lakeshire defense","где стража штормграда","нет подкреплений","оборона приозерья"}},{q="Что происходит после доклада о гноллах?",a="Заместитель судьи Фелдон просит вас продолжить, ближе разведав лагеря гноллов в задании «Подсчет врагов», чтобы определить их истинную численность.",al={"next quest","chain follow up","следующее задание","продолжение цепочки"}},{q="Какие стаи гноллов вторгаются сюда?",a="Гноллы Красногорья, собирающиеся в холмах как стая гноллов Красногорья, становятся все смелее и организованнее по мере ослабления человеческого контроля над регионом.",al={"which gnolls","redridge gnoll clans","какие гноллы","кланы гноллов красногорья"}}},fp="18,361,18.460.0,18.417.0,22.121.0,31.108.0,40.190.0,45.214.0,40.159.0,39.159.0"}
P.entries["quest:245"] = {n="Восьминогая угроза",s="«Восьминогая угроза» — контракт ополчения, который выдает Дозорный Додс в Сумеречном лесу. Западная граница наводнена агрессивными карликовыми ядовитыми пауками, и Ночной Дозор, которому не хватает людей, полагается на странствующих искателей приключений, чтобы истребить выводок, пока в паутине не оказалось больше стражников.",h="«Восьминогая угроза» — контракт ополчения, который выдает Дозорный Додс в Сумеречном лесу.",kw={"darkshire","duskwood","eight-legged menaces","night watch","pygmy venom web spider","spiders","watcher dodds","темнолесье","сумеречный лес","восьминогая угроза","ночной дозор","карликовый ядовитый паук","пауки","дозорный додс"},ang={["class:Hunter"]="Ядовитые пауки Сумеречного леса — свирепые твари: чтобы успешно охотиться на них, нужны осторожные движения и противоядия.",["faction:Alliance"]="Ночной Дозор стоит совсем один, без помощи Дома знати, поэтому любая поддержка путников Альянса жизненно важна, чтобы дороги оставались открытыми."},sec={{t="Граница в осаде",b="Вдоль западной дороги из Западного Края в Сумеречный лес густой полог листвы сменяется спутанными зарослями, затянутыми паутиной. Когда тьма сжала Большую деревню и превратила ее в зловещую рощу, какой она известна сегодня, местные паукообразные превратились в чудовищных хищников. Теперь карликовые ядовитые пауки роями населяют заросли, угрожая путникам и подбираясь к хрупким оборонительным рубежам Ночного Дозора."},{t="Бремя Ночного Дозора",b="Находясь далеко от безопасного Темнолесья, Дозорный Додс отчаянно нуждается в людях. Командир Алтея Чернодрев не может выделить подкрепления для дальних застав, когда нежить и ворген наседают на сам город. Оставшись один, Додс уже видел, как его товарищи становились жертвами пауков: он находил людей, висящих вниз головой в кронах, пока парализующий яд медленно растворял их для корма."}},faq={{q="Кто выдает это задание?",a="Дозорный Додс, член Ночного Дозора, расположившийся в небольшом лагере в Сумеречном лесу, поручает это задание путникам, способным истребить пауков.",al={"quest giver","who gives eight-legged menaces","watcher dodds","персонаж, выдающий задания","кто дает восьминогая угроза","дозорный додс"}},{q="Почему Ночной Дозор не справляется с пауками сам?",a="Командир Алтея Чернодрев вынуждена держать свой малочисленный гарнизон у Темнолесья, чтобы отражать непрерывные атаки нежити. У Додса нет людей, чтобы штурмовать пограничные гнезда, не оставив свой пост.",al={"why need help","why call adventurers","darkshire militia shortage","зачем нужна помощь","почему зовут искателей приключений","нехватка ополчения темнолесья"}},{q="Где находятся эти пауки?",a="Карликовые ядовитые пауки во множестве гнездятся в западных чащах Сумеречного леса, прячась в зарослях у главной дороги из Западного Края.",al={"spider location","where are pygmy venom webs","spider woods","где пауки","где карликовые ядовитые пауки","лес пауков"}},{q="Чем эти пауки так опасны для дозора?",a="Помимо огромной численности, у них сильный яд, который парализует и растворяет плоть: пойманные бойцы Ночного Дозора беспомощно висят в ветвях, становясь легкой добычей.",al={"spider poison","spider venom","spider victims","паучий яд","яд пауков","жертвы пауков"}},{q="Это единственные пауки в Сумеречном лесу?",a="Нет. Карликовые ядовитые пауки — лишь мелкие птенцы выводка. В глубине леса обитают куда более крупные и смертоносные особи, представляющие еще большую опасность для путников.",al={"other duskwood spiders","spider species","venom web spiders","другие пауки сумеречного леса","виды пауков","ядовитые пауки"}},{q="Почему так сильно выросло число насекомых и пауков?",a="Всепроникающая магическая скверна, окутавшая Сумеречный лес, исказила местных животных, усилив их агрессию, размеры и смертоносность в этом погибающем лесу.",al={"why so many spiders","duskwood corruption nature","spider origin","почему так много пауков","скверна сумеречного леса","происхождение пауков"}}},fp="20,268,20.429.0,29.421.0,22.145.0,56.206.0,32.143.0,51.178.0,39.165.0,63.171.0"}
P.entries["quest:2458"] = {n="Надежное прикрытие",s="Надежное прикрытие — тайное поручение, которое Шентул в Оргриммаре дает перспективным разбойникам Орды. Задание отправляет агента к буровым площадкам Торговой Компании в Нефтяном болоте, чтобы установить скрытую связь с внедренным агентом Изувеченной Длани.",h="Надежное прикрытие — тайное поручение, которое Шентул в Оргриммаре дает перспективным разбойникам Орды.",kw={"barrens rogue","deep cover","flare gun","shattered hand","shenthul","sludge fen","taskmaster fizzule","venture company","разбойник степи","надежное прикрытие","сигнальная ракетница","изувеченная длань","шентул","нефтяное болото","надсмотрщик физзул","торговая компания"},ang={["class:Rogue"]="Это задание — важная веха для растущих разбойников Орды: из простых уличных разведчиков они становятся доверенными агентами, способными координировать тайные операции.",["faction:Horde"]="Беспощадная вырубка и бурение Торговой Компании в Степях угрожают контролю Орды над землями и природными ресурсами, что требует активной разведки."},sec={{t="Шпион среди барышников",b="Изувеченная Длань — тайная разведывательная организация и гильдия убийц Орды, которая безжалостными и практичными методами негласно охраняет интересы Оргриммара. Целый год гильдия трудилась над тем, чтобы внедрить своего человека в иерархию алчной Торговой Компании. Этот агент, Надсмотрщик Физзул, сумел завоевать доверие и закрепиться на их промышленном буровом посту к северу от Нефтяного болота."},{t="Знаки и сигналы",b="Работа в глубине наемничьих рядов не оставляет места для ошибки. Поскольку Физзул играет роль жестокого человека, чтобы удовлетворить корпоративных начальников, любой нежданный гость рискует попасть под немедленную атаку. Чтобы подтвердить свою личность, прибывшие разбойники должны выпустить две сигнальные ракеты из специальной сигнальной пушки в пределах видимости его башни, тихо подойти и выполнить тайное приветствие Изувеченной Длани, после чего получат его отчет о растущих замыслах Торговой Компании."}},faq={{q="Кто такой Надсмотрщик Физзул?",a="Надсмотрщик Физзул — внедренный агент Изувеченной Длани в иерархии Торговой Компании к северу от Нефтяного болота. Он целый год пробивался на руководящее положение среди наемников, наблюдая за их операциями и передавая сведения в Оргриммар.",al={"fizzule","who is fizzule","taskmaster fizzule identity","физзул","кто такой физзул","личность надсмотрщика физзула"}},{q="Почему Физзул нападает, если не подать ему правильный сигнал?",a="Физзул поддерживает прикрытие грубого, жесткого надсмотрщика Торговой Компании. Если кто-то приближается к его посту без точного сигнала двумя ракетами и приветствия Изувеченной Длани, он обязан счесть чужака враждебным незваным гостем или агентом конкурентов и атаковать на месте, чтобы сохранить маскировку.",al={"why does fizzule attack","fizzule hostile","fizzule kills me","почему физзул нападает","физзул враждебен","физзул убивает меня"}},{q="Где находится башня Торговой Компании?",a="Башня возвышается над промышленными работами к северу от Нефтяного болота, в центральной северной части Степей.",al={"fizzule location","tower location","where is sludge fen tower","где физзул","расположение башни","где башня нефтяного болота"}},{q="Почему Орда шпионит за Торговой Компанией?",a="Торговая Компания известна безрассудным истощением ресурсов, эксплуатацией и жестоким насилием по всему Калимдору. Недавние сведения Изувеченной Длани показали, что картель готовит в Степях крупный замысел, и Шентул задействовал своего агента.",al={"why spy on venture co","venture co threat","зачем шпионить за торговой компанией","угроза торговой компании"}},{q="Что происходит после встречи с Физзулом?",a="Когда связь надежно установлена, Физзул поручает разбойнику проникнуть в ближайшую башню Торговой Компании, убить ее обитателей, включая Главного смотрителя Пузика Галливикса, и выкрасть запас Измененной смеси Занзила, доказав свою ценность гильдии.",al={"what next after deep cover","after fizzule","что дальше после надежного прикрытия","после физзула"}},{q="Что такое Изувеченная Длань?",a="Изувеченная Длань — теневая сеть разбойников, шпионов и убийц, действующая из Расселины Теней в Оргриммаре. Некогда это был печально известный клан на Дреноре, а в новой Орде он служит тайной разведкой Орды.",al={"shattered hand","who are shattered hand","изувеченная длань","кто такая изувеченная длань"}}},fp="10,261,22.401.0,17.460.0,26.284.0,58.308.0,43.136.0,47.276.0,47.264.1,27.233.0"}
P.entries["quest:2459"] = {n="Фероситас Пожиратель Снов",s="Фероситас Пожиратель Снов — задание Альянса, которое дает Таллонкай Гибкий Корень в Доланааре. Починив поврежденный фамильный ловец снов, Таллонкай обнаруживает, что его мощное изумрудное ядро вырвали фурболги Седой Сосны к северу от Деревни Звездного Ветра. Искателей приключений отправляют убить порченых мистиков и забрать украденный самоцвет у их вожака, Фероситаса.",h="Фероситас Пожиратель Снов — задание Альянса, которое дает Таллонкай Гибкий Корень в Доланааре.",kw={"dolanaar","dream eater","emerald dreamcatcher","ferocitas","gnarlpine mystics","starbreeze village","tallonkai swiftroot","tallonkai's jewel","teldrassil","доланаар","пожиратель снов","изумрудный ловец снов","фероситас","мистики седой сосны","деревня звездного ветра","таллонкай гибкий корень","самоцвет таллонкая","тельдрассил"},ang={["race:NightElf"]="Племя Седой Сосны когда-то было союзником кальдораев, поэтому порча их мистиков и кража священных талисманов — горькая трагедия для любого ночного эльфа, защищающего Тельдрассил."},sec={{t="Оскверненная реликвия",b="Когда Таллонкай Гибкий Корень осмотрел ловец снов, найденный в порченых землях, облегчение быстро сменилось унынием. Священный предмет осквернили: яркий изумрудный центр вырвали из плетеной рамы. Среди ночных эльфов ходили слухи, что отряд мистиков Седой Сосны к северу от Деревни Звездного Ветра попал под влияние вожака фурболгов по имени Фероситас Пожиратель Снов, который нагло носил на шее сверкающий зеленый камень. Понимая, что священный самоцвет бесполезен и осквернен в лапах этого существа, Таллонкай отправил защитников отобрать его."},{t="Изгнание мистиков",b="Фурболги Седой Сосны, населяющие северные земли Тельдрассила, прежде были мирными соседями, но растущая порча, просачивающаяся в Мировое Древо, ввергла их в буйство и безумие. Их мистики, ранее совершавшие гармоничные обряды природы, стали черпать искаженную магическую энергию. Выследив Фероситаса и прорвавшись через свиту мистиков, охраняющую его лесное логово, путники восстанавливают равновесие в лесу и возвращают самоцвет Таллонкая, чтобы ловец снов наконец стал целым."}},faq={{q="Где найти Фероситаса Пожирателя Снов?",a="Фероситас Пожиратель Снов находится в лесу к северу от Деревни Звездного Ветра в Тельдрассиле, в окружении порченых мистиков Седой Сосны и других лесных опасностей.",al={"ferocitas location","where is ferocitas","find dream eater","где фероситас","расположение фероситаса","найти пожирателя снов"}},{q="Кто такой Фероситас?",a="Фероситас — вожак фурболгов Седой Сосны, командующий отрядом порченых мистиков к северу от Деревни Звездного Ветра. Он забрал изумруд из ловца снов Таллонкая Гибкого Корня и сделал из него грубое ожерелье.",al={"who is ferocitas","ferocitas lore","what is dream eater","кто такой фероситас","предание о фероситасе","кто такой пожиратель снов"}},{q="Почему Таллонкай Гибкий Корень хочет вернуть самоцвет?",a="Пропавший изумруд — основной источник силы ловца снов Таллонкая. Без него талисман нельзя починить, и он не может направлять защитные энергии Изумрудного Сна.",al={"why tallonkai wants jewel","tallonkai jewel purpose","зачем таллонкаю самоцвет","назначение самоцвета таллонкая"}},{q="Могут ли фурболги Седой Сосны действительно использовать магию изумруда?",a="Нет. По словам Таллонкая Гибкого Корня, магические свойства изумруда совершенно бесполезны для таких существ, как Фероситас и мистики Седой Сосны, которые желали его лишь как блестящую безделушку.",al={"can gnarlpine use dreamcatcher","does ferocitas use emerald","могут ли фурболги использовать ловец снов","использует ли фероситас изумруд"}},{q="Что происходит после этого задания?",a="Это задание — заключительное звено цепочки из двух частей, начавшейся с задания «Изумрудный ловец снов». Когда вы доставите самоцвет Таллонкаю в Доланаар, он наконец сможет починить свою реликвию.",al={"quest after ferocitas","next quest dreamcatcher","задание после фероситаса","следующее задание ловец снов"}},{q="Почему мистики Седой Сосны враждебны?",a="Как и многие животные и племена фурболгов Тельдрассила, Седая Сосна поддалась странной порче, искажающей ветви недавно посаженного Мирового Древа, которая извратила их разум и сделала их агрессивными.",al={"why are furbolgs mad","gnarlpine corruption","почему фурболги злые","порча седой сосны"}}},fp="25,360,18.578.0,19.503.0,42.163.0,17.219.0,49.174.0,51.191.0,30.184.0,38.218.0"}
P.entries["quest:246"] = {n="Подсчет врагов",s="Подсчет врагов — оборонительная разведывательная операция по поручению Заместителя судьи Фелдона в Приозерье. Гарнизон растянут, а подкрепления из Штормграда не присылают, поэтому искателей приключений нанимают истреблять вторгающиеся стаи гноллов вдоль южной дороги и оценивать силу растущей угрозы.",h="Подсчет врагов — оборонительная разведывательная операция по поручению Заместителя судьи Фелдона в Приозерье.",kw={"assessing","feldon","gnolls","lakeshire","mongrel","poacher","reconnaissance","redridge","threat","подсчет","фелдон","гноллы","приозерье","шавки","браконьер","разведка","красногорье","угроза"},ang={["class:Warrior"]="Заместитель судьи Фелдон требует агрессивной боевой разведки, проверяя способность вооруженного бойца ворваться в укрепленные вражеские лагеря и сломить их авангард.",["faction:Alliance"]="Красногорье показывает трещины в сердце Альянса: заброшенным пограничным поселениям приходится нанимать вольных героев, чтобы выжить, пока столица отворачивается.",["race:Human"]="Для защитников-людей оборона Приозерья — личное дело: эти семьи на границе расплачиваются за политический паралич в Крепости Штормграда."},sec={{t="Напряженная граница",b="Город Приозерье борется за выживание на нескольких фронтах. Между отрядами орков Черной горы, спускающимися с высот, и агрессивными стаями гноллов, терзающими долины, местные защитники не могут выделить войска для обычных разведывательных патрулей. Когда первые донесения подтвердили вторжение гноллов на границу, Заместитель судьи Фелдон обратился за помощью извне. Вместо того чтобы посылать в глушь обычных стражников, город платит странствующим героям, чтобы они лично проверили силу врага."},{t="Разведка боем",b="Задание посылает разведчиков по южной дороге Красногорья, в лагеря красногорских шавок и браконьеров. Это сбор сведений на истощение: уничтожение передовых разведчиков, срыв линий снабжения и выяснение, бродячие ли это падальщики или часть организованной военной силы, угрожающей поселению. Кровавые стычки дают Фелдону конкретные цифры, нужные для планирования напряженной обороны Приозерья."}},faq={{q="Почему Заместитель судьи Фелдон посылает искателей приключений, а не городскую стражу?",a="Гарнизон Приозерья критически малочислен. Подкрепления из Штормграда не приходят, а враги давят со всех сторон, поэтому городская стража не может выделить солдат для долгих патрулей вдоль южной дороги.",al={"why hire adventurers","where are the guards","lakeshire guard shortage","зачем нанимать искателей приключений","где стража","нехватка стражи приозерья"}},{q="Где находятся гноллы для этого задания?",a="Красногорские шавки и браконьеры устраивают разрозненные военные лагеря вдоль южной дороги и в низких предгорьях Красногорья, к югу от Приозерья и около пограничных проходов.",al={"where are redridge mongrels","gnoll locations redridge","southern road gnolls","где красногорские шавки","расположение гноллов красногорья","гноллы южной дороги"}},{q="Какова стратегическая цель истребления этих гноллов?",a="У операции две цели: отбросить передовых разведчиков, вторгающихся на дорогу, и добыть из первых рук военные сведения о численности, вооружении и дисциплине гноллов Красногорья.",al={"why kill gnolls","threat assessment goal","lakeshire defense","зачем убивать гноллов","цель оценки угрозы","оборона приозерья"}},{q="Помогает ли Штормград в борьбе с гноллами?",a="Нет. Дом знати Штормграда и регентский совет отказывают окраинным землям вроде Красногорья в обычной военной поддержке, вынуждая местные власти, такие как Мировой судья Соломон и Заместитель судьи Фелдон, полагаться на наемников.",al={"stormwind reinforcements","why won't stormwind help","stormwind army lakeshire","подкрепления штормграда","почему штормград не помогает","армия штормграда в приозерье"}},{q="Что Заместитель судьи Фелдон делает с вашим отчетом?",a="Заместитель судьи Фелдон оценивает силу и стойкость стай и подтверждает, что южные гноллы представляют серьезную военную опасность, а не являются разрозненными зверями, после чего направляет вас помогать другим городским руководителям укреплять оборону.",al={"feldon's reaction","what happens after assessing threat","turn in report","реакция фелдона","что после подсчета врагов","сдать отчет"}},{q="Как это задание связано с предыдущим?",a="Это прямое продолжение задания «Вторжение гноллов». После того как вы впервые предупредили гарнизон о передвижении гноллов, Фелдон поручил этот боевой патруль, чтобы выяснить, насколько серьезно вторжение.",al={"quest line connection","encroaching gnolls followup","prerequisite quest","связь цепочки заданий","продолжение вторжения гноллов","предыдущее задание"}}},fp="20,305,19.493.0,23.461.0,63.247.0,46.170.0,54.208.0,47.229.0,44.231.0,46.193.0"}
P.entries["quest:2460"] = {n="Приветствие Изувеченной Длани",s="Приветствие Изувеченной Длани — ритуал посвящения, который проводит Шентул в Расселине Теней в Оргриммаре. Изучая этот особый знак узнавания, начинающие разбойники учатся безопасно определять в поле соратников из Изувеченной Длани.",h="Приветствие Изувеченной Длани — ритуал посвящения, который проводит Шентул в Расселине Теней в Оргриммаре.",kw={"cleft of shadows","covert","deep cover","orgrimmar","rogue","shattered hand","shattered salute","shenthul","расселина теней","тайный","глубокое внедрение","оргриммар","разбойник","изувеченная длань","приветствие изувеченной длани","шентул"},ang={["class:Rogue"]="Для разбойника Орды освоение тайных сигналов Изувеченной Длани означает превращение из обычного карманника в доверенного агента разведывательной сети Оргриммара.",["faction:Horde"]="Хотя вождь Тралл правит с честью, Орда во многом полагается на тайные методы Изувеченной Длани, чтобы устранять угрозы до того, как они выйдут на поверхность."},sec={{t="Знаки и тени",b="В темных туннелях Расселины Теней Изувеченная Длань действует как тайная разведка и орудие убийств Орды Тралла. Из-за опасного и секретного характера заданий агенты не могут полагаться на открытые знамена или обычную военную геральдику. Шентул обучает новопосвященных разбойников приветствию Изувеченной Длани — особому жесту, который служит безошибочным безмолвным сигналом между союзниками."},{t="Подготовка к заданию",b="Освоить приветствие — не просто церемониальное упражнение, а жизненно важное шпионское ремесло. Агентам-разбойникам, отправленным на опасную территорию или внедряемым во вражеские группировки, нужно проверять связных так, чтобы не насторожить посторонних и цели. Шентул требует, чтобы агент без труда узнавал этот жест и повторял его, прежде чем доверить ему тайную работу в полевых условиях."}},faq={{q="Для чего нужно приветствие Изувеченной Длани?",a="Приветствие Изувеченной Длани служит тайным опознавательным сигналом среди членов Изувеченной Длани. Оно позволяет агентам узнавать друг друга в глубоком подполье или на враждебной территории, не раскрывая посторонним свою истинную принадлежность.",al={"why do i need the salute","shattered salute purpose","what does the salute do","зачем нужно приветствие","цель приветствия изувеченной длани","что делает приветствие"}},{q="Кто обучает приветствию Изувеченной Длани?",a="Приветствию обучает Шентул, наставник разбойников, находящийся в глубине Расселины Теней под Оргриммаром.",al={"who gives the quest","who is shenthul","where do i learn the salute","кто выдает задание","кто такой шентул","где выучить приветствие"}},{q="Какая организация использует этот жест?",a="Его использует Изувеченная Длань — орден орков-разбойников, шпионов и убийц, служащий нынешней Орде из теней Оргриммара.",al={"shattered hand clan","who are the shattered hand","what guild uses this","клан изувеченная длань","кто такая изувеченная длань","какая организация использует это"}},{q="Почему нужно выучить приветствие, прежде чем отправляться на задание?",a="Агенты, отправленные на задания по внедрению, например для связи с тайными агентами, полагаются на приветствие, чтобы не раскрыть себя и не принять врага за союзника.",al={"why practice salute","is the salute required","зачем учить приветствие","обязательно ли приветствие"}},{q="Где проходит это обучение?",a="Обучение проходит в Расселине Теней — подземном районе под Оргриммаром, где собираются разбойники, чернокнижники и другие приверженцы запретных искусств вдали от посторонних глаз.",al={"salute location","where is shenthul located","где приветствие","где находится шентул"}},{q="Какое задание следует после освоения приветствия?",a="Когда Шентул удовлетворен тем, как агент освоил приветствие, он назначает его на операции глубокого внедрения, проверяя, умеет ли тот использовать сигнал для связи с агентами в полевых условиях.",al={"what comes next","next quest after salute","deep cover quest","что дальше","следующее задание после приветствия","задание глубокого внедрения"}}},fp="20,257,17.431.0,25.365.0,44.230.0,33.111.0,36.141.0,65.174.0,36.193.0,51.183.0"}
P.entries["quest:247"] = {n="Завершение охоты",s="Завершение охоты — кульминация великих испытаний зверями, которые устраивает Сенани Громовое Сердце в Ясеневом лесу. Сразив Урсангуса, Тенумбру и Острого Когтя, воин Орды доказывает свою силу, стойкость и первобытное мастерство в спорном лесу.",h="Завершение охоты — кульминация великих испытаний зверями, которые устраивает Сенани Громовое Сердце в...",kw={"ashenvale","beasts","hunt","predator","senani","shadumbra","sharptalon","thunderheart","trophy","ursangous","ясеневый лес","звери","охота","хищник","сенани","тенумбра","острый коготь","громовое сердце","трофей","урсангус"},ang={["class:Hunter"]="Победа над тремя главными хищниками Ясеневого леса — высший обряд выслеживания и меткости, доказывающий, что ваши инстинкты не уступают диким зверям.",["faction:Horde"]="Укрощение зверей Ясеневого леса помогает Орде закрепиться в опасном, враждебном лесу, полном хищников и часовых Альянса.",["race:Tauren"]="Для шу'хало охота на Урсангуса, Тенумбру и Острого Когтя — освященное веками испытание уважения, равновесия и гордости предков."},sec={{t="Доказательство охотника",b="Сенани Громовое Сердце, находящаяся среди сил Орды в Ясеневом лесу, проверяет путников не только на верность вождю, но и на умение выживать в дикой природе. Большая охота нацелена на трех легендарных хищников, обитающих под древними ветвями: медведя Урсангуса, кошку Тенумбру и свирепого гиппогрифа Острого Когтя. Победа над всеми тремя и добытые трофеи доказывают, что в жилах испытуемого течет истинная кровь охотника."},{t="В честь предков",b="Для тауренов охота — священный акт равновесия и уважения, даже посреди идущей войны. Одолев самых грозных обитателей Ясеневого леса, охотник чтит духов земли и заслуживает благословение предков от Сенани Громового Сердца. Охота завершается официальной благодарностью и знаком милости, закрепляющими репутацию воина по всему лесу."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание завершается у Сенани Громовое Сердце, охотницы-таурена, которая вместе с Ордой расквартирована в древних чащах Ясеневого леса.",al={"quest giver","where to turn in","senani thunderheart location","персонаж, выдающий задание","где сдать задание","где сенани громовое сердце"}},{q="Что нужно для завершения охоты?",a="Вы должны убить трех главных хищников, бродящих по Ясеневому лесу, и принести доказательства их гибели: лапу медведя Урсангуса, голову ночной саблезуба Тенумбры и коготь гиппогрифа Острого Когтя.",al={"what beasts to kill","prerequisites","which animals","каких зверей убить","требования","какие животные"}},{q="Зачем Сенани Громовое Сердце нужно убийство этих зверей?",a="Охота служит испытанием силы и стойкости. Победа над такими грозными зверями доказывает, что путник обладает истинным сердцем и чутьем хищника, способного выжить в коварной глуши Ясеневого леса.",al={"why hunt them","senani motive","purpose of hunt","зачем охотиться на них","мотив сенани","цель охоты"}},{q="Каково культурное значение охоты для Орды?",a="Для таурена вроде Сенани Громовое Сердце испытать свою доблесть в схватке с могучими зверями — почетная традиция, обращенная к духам и предкам. Она показывает владение дикой природой без безрассудного бесчестья.",al={"tauren hunt lore","cultural meaning","why do tauren hunt beasts","предания тауренов об охоте","культурное значение","зачем тауренам охота на зверей"}},{q="Признается ли это испытание всей Ордой?",a="Да. Завершив охоту, вы будете считаться испытанным охотником в глазах Орды в Ясеневом лесу, получите благословение предков и уважение соратников.",al={"horde recognition","is it official","horde commendation","признание орды","официально ли это","благодарность орды"}},{q="На каких трех зверей направлена Большая охота?",a="Цели — великий медведь Урсангус, скрытная ночная саблезуб Тенумбра и смертоносный гиппогриф Острый Коготь.",al={"the three beasts","hunt targets","named animals","три зверя","цели охоты","именные животные"}}},fp="18,243,16.447.0,22.354.0,49.128.0,47.201.0,53.215.0,59.217.0,45.164.0,54.114.0"}
P.entries["quest:2479"] = {n="Помощь Хинотта",s="«Помощь Хинотта» — срочное путешествие разбойников Орды, пораженных изнуряющим тропическим токсином. Болезнь была получена во время задания по проникновению в Степях и требует особых познаний Сержа Хинотта на Мельнице Таррен. Обратившись к нему, можно получить спасительное лекарство и обучение искусству приготовления смертельных ядов.",h="«Помощь Хинотта» — срочное путешествие разбойников Орды, пораженных изнуряющим тропическим токсином.",kw={"hillsbrad foothills","hinott's assistance","rogue poison quest","serge hinott","shenthul","tarren mill","undercity zeppelin","zanzil","zanzil's mixture","предгорья хилсбрада","помощь хинотта","задание яды разбойника","серж хинотт","шентул","мельница таррен","дирижабль в подгород","занзил","смесь занзила"},ang={["class:Rogue"]="Этот обряд посвящения соединяет простую скрытность с алхимией, проверяя выносливость разбойника и открывая путь к самостоятельному изготовлению ядов.",["faction:Horde"]="Задание показывает практическое сотрудничество орков и троллей-разбойников Калимдора со зловещими алхимическими знаниями Отрекшихся в Лордероне."},sec={{t="Ядовитое положение",b="После дерзкого проникновения в башню Торговой Компании к северу от Нефтяного болота разбойники оказываются отравлены измененной смесью Занзила. Яд разрушает тело, притупляет рефлексы и грозит самой жизни. Осознав тяжесть недуга, учитель разбойников Шентул в Оргриммаре признает, что местные средства бессильны, и отправляет отравленного лазутчика за море, в Восточные королевства."},{t="Путешествие на Мельницу Таррен",b="Поиски лекарства ведут на юг через Лордерон, в деревню Мельница Таррен в Предгорьях Хилсбрада. Там живет Серж Хинотт, фармацевт, чье увлечение смертоносными зельями делает его идеальным кандидатом для изучения редкого образца. Пока обычные целители отшатывались от яда Занзила, Хинотт с профессиональным восторгом взялся за смертельный состав, желая разобрать мерзкую смесь и обучить достойных разбойников варить собственные яды."}},faq={{q="Почему мне нужно увидеть Сержа Хинотта?",a="Серж Хинотт — опытный фармацевт с Мельницы Таррен, специалист по редким токсинам и противоядиям. Обычные целители не могут вывести измененную смесь Занзила, поэтому только Хинотт способен изучить состав, спасти вам жизнь и обучить искусству изготовления ядов.",al={"why hinott","who cures the poison","serge hinott role","почему хинотт","кто лечит яд","роль сержа хинотта"}},{q="Где находится Мельница Таррен?",a="Мельница Таррен — поселение Отрекшихся на севере Предгорий Хилсбрада. Из Оргриммара доплывите на дирижабле до Подгорода в Тирисфальских лесах, затем отправляйтесь на юг через Серебряный бор и поверните на восток по дороге в Хилсбрад.",al={"tarren mill location","how to get to tarren mill","where is hinott","где мельница таррен","как добраться до мельницы таррен","где хинотт"}},{q="Как я вообще отравился?",a="Вы заразились во время тайного задания «Миссия: выполнима, но с трудом» в башне Торговой Компании к северу от Нефтяного болота в Степях. Вскрыв хорошо охраняемый сундук, вы подверглись действию измененной смеси Занзила, что вызвало затяжной изнуряющий недуг.",al={"how did i get zanzil poison","mission possible poison","why am i poisoned","как я получил яд занзила","миссия выполнима яд","почему я отравлен"}},{q="Что происходит после того, как Серж Хинотт получает образец?",a="Получив образец, Хинотт изучает его свойства и готовит противоядие, чтобы очистить ваш организм. Излечив от токсина, он делится своими знаниями, позволяя разбойникам освоить приготовление и применение собственных ядов.",al={"hinott quest follow up","do i get cured","after hinotts assistance","продолжение задания хинотта","исцелюсь ли я","после помощи хинотта"}},{q="Кто такой Шентул и почему он отправил меня прочь?",a="Шентул — учитель разбойников Изувеченной Длани в Расселине Теней в Оргриммаре. Он наблюдал за вашим испытанием мастерства в Степях и понял, что состав Занзила далеко выходит за пределы медицинских знаний Оргриммара и нужен специалист в Хилсбраде.",al={"who is shenthul","shenthul orgrimmar","why did trainer send me","кто такой шентул","шентул оргриммар","почему учитель отправил меня"}},{q="Может ли другой класс выполнить это задание?",a="Нет. Это задание — часть особой линии обучения разбойников, дающей основы искусства приготовления ядов и противоядий.",al={"rogue only quest","can warriors do hinotts assistance","задание только для разбойников","могут ли воины выполнить помощь хинотта"}}},fp="19,359,19.431.0,22.461.0,34.289.0,29.229.0,42.263.0,52.233.1,44.265.0,40.137.0"}
P.entries["quest:2480"] = {n="Помощь Хинотта",s="«Помощь Хинотта» — завершение пути разбойника Орды к победе над смертоносным медленным ядом Занзила. На Мельнице Таррен фармацевт Серж Хинотт дает пораженному лазутчику противоядие и начальное обучение алхимическому искусству ядов.",h="«Помощь Хинотта» — завершение пути разбойника Орды к победе над смертоносным медленным ядом Занзила.",kw={"anti-toxin","cure","hillsbrad","hinott","poisons","rogue quest","serge hinott","tarren mill","zanzil","противоядие","лекарство","хилсбрад","хинотт","яды","задание разбойника","серж хинотт","мельница таррен","занзил"},ang={["class:Rogue"]="Этот обряд посвящения излечивает изнуряющий недуг, перенесенный во время вашего посвящения, и открывает знания, нужные для создания боевых ядов.",["faction:Horde"]="Алхимия Отрекшихся незаменима для скрытных лазутчиков Орды: она превращает редкие яды троллей джунглей в обычное полевое знание.",["race:Undead"]="Фармацевт Хинотт воплощает отстраненное научное восхищение Королевского фармацевтического общества любым ядом, в котором виден подлинный талант мастера, независимо от его происхождения."},sec={{t="Ядовитый шедевр",b="Заразившись губительным ядом, туманящим разум, во время задания в Степях, разбойники Орды отправляются на север, на Мельницу Таррен, к Сержу Хинотту. Этот целеустремленный химик из числа Отрекшихся с профессиональным трепетом относится к яду, созданному изгнанником, троллем из джунглей Занзилом. Личность и происхождение тролля его не волнуют, но он открыто хвалит злую силу состава и хочет изучить его действие, прежде чем создавать противоядие."},{t="Противоядие и ремесло",b="Для создания лекарства нужно лишь терпение, пока Хинотт выделяет действующие вещества. Готовое зелье останавливает подкрадывающееся безумие, хотя химик признает, что не может отмыть стойкую вонь. Избавившись от изнуряющего яда, разбойники из жертв превращаются в практиков и, используя наблюдения Хинотта о работе Занзила, осваивают приготовление собственных боевых ядов."}},faq={{q="Что происходит во время «Помощи Хинотта»?",a="Вам нужно просто подождать немного на Мельнице Таррен, пока Серж Хинотт готовит противоядие. Когда он закончит смешивать состав, поговорите с ним, чтобы принять лекарство и очиститься от яда Занзила.",al={"what do i do here","hinott assistance walk","how to finish quest","что мне делать здесь","прохождение помощи хинотта","как завершить задание"}},{q="Кто такой Серж Хинотт?",a="Серж Хинотт — алхимик из числа Отрекшихся и специалист по ядам, работающий на Мельнице Таррен в Предгорьях Хилсбрада. Он применяет свое мастерство, помогая разбойникам Орды исцелиться от редких недугов и постичь тонкости приготовления ядов.",al={"serge hinott lore","who is hinott","tarren mill apothecary","предания о серже хинотте","кто такой хинотт","фармацевт мельницы таррен"}},{q="Почему Сержа Хинотта впечатлил яд?",a="Хинотт считает формулу Занзила чудом алхимического замысла из-за сильного сочетания подкрадывающегося безумия и телесной слабости. Даже работая над ее нейтрализацией, он открыто восхваляет мастерство, стоящее за столь разрушительным составом.",al={"zanzil poison reaction","why does hinott like it","реакция на яд занзила","почему хинотту нравится яд"}},{q="Что за стойкий запах упоминает Хинотт?",a="У смеси Занзила резкий, тошнотворный запах, проникающий в поры жертвы. Противоядие Хинотта успешно останавливает развитие яда и проясняет разум, но не сразу убирает оставшуюся вонь.",al={"why do i smell","madness smell","quest smell","почему я пахну","запах безумия","запах задания"}},{q="Какова награда за выполнение этого задания?",a="Выполнение задания снимает стойкий ослабляющий эффект, полученный в цепочке заданий класса разбойника, и открывает путь к изучению умения «Яды разбойника», позволяя варить собственные ослабляющие покрытия.",al={"what do rogues get","hinotts assistance reward","что получают разбойники","награда помощи хинотта"}},{q="Где сдается это задание?",a="Задание начинается и завершается у Сержа Хинотта на Мельнице Таррен, на севере Предгорий Хилсбрада.",al={"where is hinott","turn in location","где хинотт","место сдачи задания"}}},fp="19,279,19.460.0,26.398.1,40.200.0,20.237.0,44.239.0,44.244.0,45.206.0,30.118.0"}
P.entries["quest:25"] = {n="Остановка у Каменного Когтя",s="«Остановка у Каменного Когтя» — задание Орды, которое выдает Масток Райльшип на Заставе Расщепленного Дерева, чтобы обезопасить важный путь к Когтистым горам. Оскверненные водные элементали в Озере Мистраль остановили обозы со снабжением, и Орда решает перебить враждебных духов и разведать эльфийскую беседку, откуда видны передвижения Альянса.",h="«Остановка у Каменного Когтя» — задание Орды, которое выдает Масток Райльшип на Заставе Расщепленного Дерева...",kw={"befouled water elemental","gazebo","mastok wrilehiss","mystral lake","splintertree post","stonetalon standstill","talondeep path","tideress","оскверненный водный элементаль","беседка","масток райльшип","озеро мистраль","застава расщепленного дерева","остановка у каменного когтя","туннель когтя","тидересс"},ang={["class:Shaman"]="Искаженное состояние водных элементалей Озера Мистраль говорит о глубоком разладе стихий, пустившем корни в древних чащах Ясеневого леса.",["faction:Horde"]="Застава Расщепленного Дерева не выживет без свободных путей снабжения; защита Туннеля Когтя жизненно важна для связи и торговли с Когтистыми горами.",["race:Orc"]="Воины Орды опираются на лес и тропы Ясеневого леса, снабжая свои поселения, поэтому перебои на горных путях снабжения недопустимы."},sec={{t="Перекрытый путь снабжения",b="Чтобы удерживать позиции Орды в Ясеневом лесу, нужен постоянный поток древесины, припасов и гонцов между лесом и вершинами Когтистых гор. Туннель Когтя служит этой важной артерией и огибает западный берег Озера Мистраль. Когда воды яростно ожили от враждебных элементалей, движение полностью прекратилось. Караваны подвергались нападениям разъяренных водных духов, и Масток Райльшип потребовал срочных мер, пока линии снабжения не рухнули окончательно."},{t="Оскверненные воды",b="Озеро Мистраль больше не мирное лесное убежище. Элементали, скользящие в его глубинах, стали оскверненными, агрессивными и непредсказуемыми и нападают на всех, кто пытается пройти по окрестным тропам. Истребление этих водяных тварей и свержение власти старшего духа Тидересс необходимо, чтобы вернуть хоть какую-то безопасность. Но происхождение их порчи остается зловещей загадкой на фоне общих бедствий, охвативших священные рощи Ясеневого леса."},{t="Взгляд через воду",b="Помимо усмирения гневных духов озера, Орда видит стратегическую возможность на центральном острове Озера Мистраль. На островке стоит древняя беседка ночных эльфов, откуда открывается хороший вид через воду на ближайшее поселение ночных эльфов — Приют Серебряного Ветра. Разведав постройку, разведчики Орды оценивают, можно ли использовать руины как передовой наблюдательный пост, чтобы командиры Расщепленного Дерева могли незаметно следить за соперниками в Калимдоре."}},faq={{q="Что вызвало остановку у Каменного Когтя?",a="Оскверненные водные элементали Озера Мистраль стали агрессивными и нападают на путников на соседнем Туннеле Когтя. Из-за этого остановились обозы со снабжением между Ясеневым лесом и Когтистыми горами.",al={"why are transports stopped","talondeep path blocked","what stopped the supply route","почему остановились обозы","туннель когтя перекрыт","что остановило путь снабжения"}},{q="Кто приказывает уничтожить элементалей?",a="Масток Райльшип, орк, служащий на Заставе Расщепленного Дерева в восточной части Ясеневого леса, поручает восстановить торговые пути Орды и разведать позиции Альянса.",al={"who gives stonetalon standstill","mastok wrilehiss quest","who is mastok","кто выдает остановку у каменного когтя","задание мастока райльшипа","кто такой масток"}},{q="Зачем разведывать беседку посреди Озера Мистраль?",a="Беседка дает возвышенный обзор озера и смотрит прямо на ближайший лагерь Альянса. Масток надеется использовать ее как скрытый наблюдательный пост для слежки за передвижениями врага.",al={"why scout gazebo","mystral lake gazebo purpose","gazebo observation post","зачем разведывать беседку","беседка озера мистраль","наблюдательный пост в беседке"}},{q="Что такое Туннель Когтя?",a="Туннель Когтя — основная горная тропа, соединяющая юго-запад Ясеневого леса с Когтистыми горами; она идет прямо вдоль западного берега Озера Мистраль.",al={"talondeep path location","path to stonetalon","stonetalon road","где туннель когтя","путь в когтистые горы","дорога в когтистые горы"}},{q="Почему водные элементали Озера Мистраль оскверненные?",a="Темные силы и повсеместные беды в Ясеневом лесу нарушили природное равновесие, свели с ума духов Озера Мистраль и сделали их обычно спокойные воды враждебными к чужакам.",al={"why are elementals corrupted","mystral lake water corrupted","befouled elementals origin","почему элементали осквернены","вода озера мистраль осквернена","происхождение оскверненных элементалей"}},{q="Какой форпост Альянса просматривается из беседки?",a="Из беседки виден Приют Серебряного Ветра — поселение ночных эльфов к северу от озера. Его охраняют Часовые, защищающие Ясеневый лес от лесозаготовок Орды.",al={"what alliance base near mystral lake","alliance outpost ashenvale","какая база альянса у озера мистраль","форпост альянса в ясеневом лесу"}}},fp="21,348,21.541.0,20.486.0,21.491.0,47.227.0,34.165.0,51.195.0,27.184.0,54.190.0,56.177.0"}
P.entries["quest:250"] = {s="Главный инженер Плотиннер VII опасается, что после нападений в Болотине следующей целью дворфов из клана Черного Железа станет Каменная Плотина. Большая часть гарнизона плотины переведена в другое место, и герои отправляются выяснить, что затевают подрывники Черного Железа у восточного пандуса.",h="Главный инженер Плотиннер VII опасается, что после нападений в Болотине следующей целью дворфов из клана...",kw={"dark iron","dun modr","hinderweir","loch modan","sappers","stonewrought dam","suspicious barrel","thandol span","черное железо","дун модр","плотиннер","лок модан","подрывники","каменная плотина","подозрительная бочка","мост тандола"},ang={["faction:Alliance"]="Поскольку армии на передовой растянуты по всему континенту, новобранцам Альянса приходится заполнять пустоту и охранять важные тыловые узлы снабжения и региональную инфраструктуру.",["profession:Engineering"]="Инженеры оценят и поразительные масштабы плотины, и коварную опасность подрывников, закладывающих летучую химическую взрывчатку под несущие основания.",["race:Dwarf"]="Каменная Плотина — шедевр дворфийского мастерства и предмет гордости; угроза со стороны вероломных сородичей из Черного Железа превращает расследование в дело государственной обороны."},sec={{t="Уязвимое чудо",b="Каменная Плотина — одно из величайших инженерных достижений Стальгорна, она сдерживает огромные воды Лок Модана. Однако из-за продолжающихся конфликтов в Каз Модане и за его пределами большая часть охраны плотины была переведена на фронт Альянса. Нехватка войск оставляет Главного инженера Плотиннера VII и его малочисленную команду почти беззащитными перед согласованными атаками как раз тогда, когда враг подбирается к гигантскому сооружению."},{t="Отголоски с севера",b="Тревоги Плотиннера вызваны недавними разрушениями на северной границе. Дворфы Черного Железа нанесли смертоносный скоординированный удар в Болотине, разрушили важный Мост Тандола и разграбили крепостной город Дун Модр. Заметив известных подрывников Черного Железа у восточного пандуса плотины, Плотиннер понял закономерность: мятежный клан нацелился на следующую жизненную артерию — уничтожение Озера Лок."},{t="Подозрительная бочка",b="Разведка нижних стен подтверждает худшие опасения инженера. Среди камней, где собирались подрывники, стоит бесхозная подозрительная бочка с летучим порошком странного запаха. Это явное доказательство того, что дворфы Черного Железа готовят подрыв, чтобы разрушить основание Каменной Плотины."}},faq={{q="Почему Главный инженер Плотиннер беспокоится за плотину?",a="Силы Черного Железа недавно разгромили северные гарнизоны, повредив Мост Тандола и разграбив Дун Модр. Увидев подрывников Черного Железа у восточного пандуса Каменной Плотины, Плотиннер убедился, что плотина — их следующая цель.",al={"why hinderweir worried","threat to stonewrought dam","why attack the dam","почему плотиннер беспокоится","угроза каменной плотине","зачем нападать на плотину"}},{q="Куда ушел гарнизон плотины?",a="Большая часть охраны Каменной Плотины, включая лучшего инспектора Плотиннера, была переведена для поддержки фронта Альянса, и важный объект остался слабо защищенным.",al={"why are there no guards at the dam","dam security detail","where are the soldiers","почему нет стражи у плотины","охрана плотины","где солдаты"}},{q="Что вы найдете у восточного пандуса?",a="Рядом с восточным пандусом, где заметили подрывников Черного Железа, следователи находят подозрительную бочку с порошком странного запаха. Это подтверждает, что дворфы Черного Железа закладывают взрывчатку, чтобы разрушить сооружение.",al={"what is the clue","suspicious barrel clue","what are the sappers doing","в чем улика","улика подозрительная бочка","что делают подрывники"}},{q="Какое стратегическое значение имеет Каменная Плотина?",a="Каменная Плотина удерживает водохранилище Лок Модана. Если ее прорвет, поток вызовет огромные разрушения ниже по течению в Болотине и опустошит сердце земель дворфов.",al={"why destroy the dam","what happens if the dam breaks","dam lore","зачем разрушать плотину","что будет если плотину прорвет","предания о плотине"}},{q="Что за нападение на Дун Модр упоминает Плотиннер?",a="Дун Модр был укрепленным поселением дворфов на севере Болотины, рядом с Мостом Тандола. Лазутчики Черного Железа захватили город и ударили по расположенному рядом Мосту Тандола, перерезав важные сухопутные пути снабжения.",al={"dun modr attack","what happened at dun modr","thandol span destruction","нападение на дун модр","что случилось в дун модре","разрушение моста тандола"}},{q="Кто такие дворфы Черного Железа, нацелившиеся на Лок Модан?",a="Клан Черного Железа издавна враждует с дворфами Бронзобородами со времен Войны трех молотов. Действуя из Черной горы и Тлеющего ущелья, они часто совершают диверсии против инфраструктуры и пограничной обороны Бронзобородов.",al={"who are the dark irons","dark iron sappers motive","why do dark irons hate ironforge","кто такие дворфы черного железа","мотив подрывников черного железа","почему черное железо ненавидит стальгорн"}}},fp="19,296,19.451.0,21.422.0,19.330.1,55.245.0,32.204.0,37.226.1,59.198.0,56.211.0,51.241.0"}
P.entries["quest:2518"] = {n="Слезы Луны",s="«Слезы Луны» — торжественное задание, которое выдает жрица А'моора в Храме Луны. Некогда любимая богиней Элуной, великая паучиха леди Сатра впала в безумие, и Сестринству Элуны приходится даровать ей милосердную смерть и забрать ее священные паутинные железы.",h="«Слезы Луны» — торжественное задание, которое выдает жрица А'моора в Храме Луны.",kw={"darnassus","elune","lady sathrah","priestess a'moora","silvery spinnerets","tears of the moon","teldrassil","temple of the moon","wellspring lake","дарнасс","элуна","леди сатра","жрица а'моора","серебристые паутинные железы","слезы луны","тельдрассил","храм луны","родниковое озеро"},ang={["class:Druid"]="Друиды видят во внезапной ярости и муках Сатры еще один тревожный признак нарушенного равновесия Тельдрассила, и потому восстановление ее духа становится необходимостью для природы.",["class:Priest"]="Жрецы, служащие Сестринству Элуны, понимают, что милосердие порой требует скорбного удара, завершающегося ритуальным даром, который возвращает оскверненную душу в объятия Богини.",["race:NightElf"]="Для кальдораев умерщвление Сатры — болезненное напоминание о том, что порча, затронувшая дикие земли Тельдрассила, не щадит ни смиренного зверя, ни священных спутников Элуны."},sec={{t="Падение любимого создания",b="В тихих стенах Храма Луны в Дарнассе жрица А'моора оплакивает трагическую судьбу леди Сатры. Прежде Сатра считалась благословенным созданием Элуны. Она плела тонкие серебристые сети под ночным небом и ловила вечерний туман, собиравшийся на ветвях Тельдрассила. Мерцающая роса, что оседала на ее паутине, обладала чудесными целебными свойствами, и Сестринство Элуны бережно собирало и хранило ее для священных обрядов."},{t="Милосердие для Сатры",b="Как и многие дикие животные юного Мирового Древа, леди Сатра недавно поддалась всепоглощающему безумию. Ее порча угрожает не только путникам, но и ее собственным неотложенным выводкам на севере у Родникового озера. Очистить ее, пока она мечется в ярости, невозможно, и Сестринство решило, что единственный милосердный путь — положить конец ее страданиям. Забрав ее серебристые паутинные железы, жрицы намерены посвятить ее останки на алтаре Элуны и молятся, чтобы Богиня Луны даровала ей покой и чистое перерождение."}},faq={{q="Кто такая леди Сатра?",a="Леди Сатра — величественный древний паук, обитающий в Тельдрассиле. Ее издавна почитали как любимицу Элуны. Она плела серебристую паутину, которая ловила ночной туман, наполненный природной целительной силой.",al={"lady sathrah lore","who is lady sathrah","sathrah backstory","sathrah spider","леди сатра предания","кто такая леди сатра","история сатры","паучиха сатра"}},{q="Почему леди Сатру нужно убить?",a="Ее поглотило подкрадывающееся безумие, охватившее диких животных Тельдрассила. Поскольку она стала яростной и опасной и для своего потомства, и для других, жрицы решили, что убить ее — акт милосердия.",al={"why kill sathrah","can sathrah be saved","why is sathrah aggressive","почему убить сатру","можно ли спасти сатру","почему сатра агрессивна"}},{q="Где найти леди Сатру?",a="Леди Сатра устроила логово в северной глуши Тельдрассила, у берегов Родникового озера.",al={"lady sathrah location","where is sathrah","find sathrah","леди сатра местонахождение","где сатра","найти сатру"}},{q="Для чего использовали паутину леди Сатры?",a="Ее паутина ловила вечерний туман, образуя могучую серебристую росу, известную глубоким целительным действием. Сестринство Элуны хранило ее в Храме Луны.",al={"tears of the moon meaning","sathrah webs use","silvery dew lore","значение слезы луны","применение паутины сатры","серебристая роса предания"}},{q="Кто выдает задание «Слезы Луны»?",a="Жрица А'моора, служительница Храма Луны в Дарнассе, выдает это задание доверенным искателям приключений Альянса.",al={"who gives tears of the moon","tears of the moon quest giver","priestess amoora","кто выдает слезы луны","слезы луны персонаж, выдающий задание","жрица а'моора"}},{q="Что жрицы сделают с паутинными железами Сатры?",a="Их приносят в дар Элуне на алтаре храма в качестве посвящения, прося богиню принять дух Сатры, благословить ее и позволить ей переродиться в мирном покое.",al={"what happens to the spinnerets","spinnerets purpose","sacrifice to elune","что станет с паутинными железами","назначение паутинных желез","жертва элуне"}}},fp="17,276,25.482.0,17.570.1,20.203.0,40.218.0,28.105.0,39.159.0,38.132.0,55.174.0"}
P.entries["quest:2520"] = {n="Жертвоприношение Сатры",s="«Жертвоприношение Сатры» — завершение скорбного ритуала в Храме Луны в Дарнассе. Получив останки леди Сатры, игроки приносят паутинные железы павшего существа в священные воды Элуны, чтобы очистить ее душу от порчи и упокоить ее дух.",h="«Жертвоприношение Сатры» — завершение скорбного ритуала в Храме Луны в Дарнассе.",kw={"a'moora","darnassus","elune","fountain","lady sathrah","purification","sathrah","spinnerets","teldrassil","temple of the moon","а'моора","дарнасс","элуна","фонтан","леди сатра","очищение","сатра","паутинные железы","тельдрассил","храм луны"},ang={["class:Druid"]="Друиды, скорбящие о болезни, терзающей Тельдрассил, находят утешение в том, что павших зверей можно вернуть в природный круговорот через очищение.",["class:Priest"]="Жрецы, ходящие по Храму Луны, воочию видят, как священный свет и святые воды Элуны могут исцелить души, разорванные безумием и порчей.",["race:NightElf"]="Для ночных эльфов этот обряд отражает их торжественный долг перед флорой и фауной Калимдора: даже когда существ приходится убивать, их души почитают и очищают милостью Элуны."},sec={{t="Очищение в священных водах",b="После трагической гибели леди Сатры Жрица А'моора возлагает на посвященных последний духовный долг. Великая паучиха стала жертвой темного безумия, охватившего Тельдрассил, и оно исказило ее некогда мирную натуру, превратив в бездумную агрессию. Жречество Элуны не считает ее смерть простой охотой и стремится искупить ее павшую сущность. Если опустить ее серебристые паутинные железы в центральный фонтан Храма Луны, освященные воды смоют оскверняющую порчу и даруют ей освобождение."},{t="Обновление Сатры",b="Жертва, принесенная Элуне, приносит мгновенное духовное единение. Когда паутинные железы касаются залитого лунным светом водоема, из глубин поднимается призрачный облик леди Сатры, умиротворенный и очищенный от недуга, лишившего ее рассудка. Сестринство Элуны считает этот ритуал необходимым спасением: хотя утрата великого существа тяжела, богословие ночных эльфов учит, что благодаря этому священному очищению она однажды сможет переродиться с непорочным духом."}},faq={{q="Кем была леди Сатра?",a="Леди Сатра была великой паучихой Тельдрассила, поддавшейся подкрадывающейся порче, поражающей диких животных Мирового Древа. Обезумев от скверны, она должна была быть убита, чтобы ее останки можно было освятить.",al={"lady sathrah","who is sathrah","what is sathrah","леди сатра","кто такая сатра","что такое сатра"}},{q="Где приносится жертва?",a="Жертву опускают в священный фонтан в центре Храма Луны — главного святилища Сестринства Элуны в Дарнассе.",al={"where do i put the sacrifice","fountain location","temple fountain","куда положить жертву","расположение фонтана","фонтан храма"}},{q="Что происходит, когда вы опускаете паутинные железы в фонтан?",a="Когда серебристые паутинные железы опущены в благословенные воды, в водоеме ненадолго появляется очищенный Дух Сатры, свободно и мирно ступающий в знак того, что Элуна приняла дар.",al={"what happens at the fountain","spirit of sathrah fountain","что происходит у фонтана","дух сатры фонтан"}},{q="Почему леди Сатре пришлось умереть?",a="Порча, отравлявшая ее разум, была слишком глубока, чтобы исцелить ее при жизни. Жрица А'моора и Сестринство считали, что единственный способ спасти ее душу — прекратить ее страдания и очистить ее останки в священных водах Элуны.",al={"why kill sathrah","could sathrah be saved","sathrah madness","почему убить сатру","можно ли спасти сатру","безумие сатры"}},{q="Кто выдает задание «Жертвоприношение Сатры»?",a="Задание выдает и принимает жрица А'моора, служащая в Храме Луны в Дарнассе и наблюдающая за центральным залом.",al={"quest giver","where to turn in","amoora location","персонаж, выдающий задание","где сдать задание","где а'моора"}},{q="Какая вера лежит в основе этого ритуала у ночных эльфов?",a="Ночные эльфы верят, что души, очищенные Матерью-Луной, могут переродиться в мире природы с очищенными и обновленными духами, свободными от остатков скверны порчи.",al={"night elf reincarnation","elune purification","rebirth lore","перерождение ночных эльфов","очищение элуны","предания о перерождении"}}},fp="19,288,28.530.0,22.470.1,21.213.0,31.158.0,59.182.1,33.217.0,40.144.0,54.185.0"}
P.entries["quest:254"] = {n="Копание земли",s="«Копание земли» — мрачная развязка поисков пропавшего сердца Бальзамировщика в Сумеречном лесу. В хищной тишине Кладбища Вороньего Холма потревоженный холмик земли скрывает погребенный ужас, не желающий оставаться мертвым.",h="«Копание земли» — мрачная развязка поисков пропавшего сердца Бальзамировщика в Сумеречном лесу.",kw={"abercrombie","bride of the embalmer","coffin","digging through the dirt","duskwood","eliza","eliza's grave dirt","embalmer's heart","raven hill cemetery","аберкромби","невеста бальзамировщика","гроб","копание земли","сумеречный лес","элиза","земля могилы элизы","сердце бальзамировщика","кладбище вороньего холма"},ang={["class:Paladin"]="Тревожить свежие могилы противоречит всем похоронным обрядам Света, но освободить и уничтожить заточенное внутри противоестественное создание — необходимый акт очищения.",["class:Priest"]="Звуки царапающих когтей и скрежещущих зубов под освященной землей — оскорбление мирного покоя, обещанного Светом умершим Сумеречного леса.",["faction:Alliance"]="Ночной Дозор постоянно борется с ужасом, исходящим от Вороньего Холма; искоренить погребенные ужасы, спрятанные Бальзамировщиком, жизненно важно для безопасности Темнолесья."},sec={{t="Потревоженная могила",b="Среди бесчисленных обветренных надгробий Кладбища Вороньего Холма находится участок недавно вскопанной рыхлой земли с именем Элиза. Хотя многие могилы Сумеречного леса осквернены падальщиками или дикими упырями, эту землю насыпали намеренно. Если прокопать верхний слой, обнаружатся расщепленные доски погребенного гроба, скрывающего от дневного света то, что хотел спрятать Бальзамировщик."},{t="Скрежет изнутри",b="Под расщепленным деревом лежит не покойный труп. Надавив на крышку, можно ощутить неистовую дрожь — яростное царапанье длинных когтистых пальцев и глухой стук гниющих челюстей. Жуткий опыт Аберкромби, Элиза, неистово ворочается в сосновой темнице, а пропавшее сердце Бальзамировщика бьется в ее груди, пока она ждет неосторожных рук, которые вскроют могилу."}},faq={{q="Что похоронено в могиле Элизы?",a="Под землей лежит гроб с Элизой, нежитью-монстром, созданным Бальзамировщиком. Она замурована под землей, а в ее груди помещено собственное сердце Бальзамировщика.",al={"what is in the grave","who is eliza","eliza grave contents","что в могиле","кто такая элиза","содержимое могилы элизы"}},{q="Где находится эта могила?",a="Могила Элизы находится на Кладбище Вороньего Холма в западной части Сумеречного леса, среди множества населенных призраками склепов и бродящей нежити.",al={"where is elizas grave","eliza grave location","grave dirt location","где могила элизы","расположение могилы элизы","где земля могилы"}},{q="Почему нужно раскапывать гроб?",a="Вы должны раскопать могилу, чтобы сразиться с Элизой и забрать сердце Бальзамировщика, завершив расследование коварных замыслов Бальзамировщика.",al={"why dig the grave","purpose of digging","why open the coffin","зачем раскапывать могилу","цель раскопок","зачем открывать гроб"}},{q="Что происходит, когда гроб открывают?",a="Открытый гроб выпускает Элизу из неглубокой темницы, и вам приходится уничтожить царапающегося, ненасытного упыря, чтобы забрать запертое вместе с ней сердце.",al={"what happens next","coffin opened","opening elizas coffin","что будет дальше","открытый гроб","открыть гроб элизы"}},{q="Кто закопал Элизу?",a="Ее там поместил Бальзамировщик, спрятав свое жуткое творение на обширном кладбище Вороньего Холма вместе со своим драгоценным сердцем.",al={"who buried eliza","who put her there","кто похоронил элизу","кто ее туда положил"}},{q="Элиза — обычный упырь?",a="Элиза — покойная жена самого Бальзамировщика, воскрешенная его темной магией с его сердцем в груди; она гораздо сильнее и расчетливее безмозглых упырей, бродящих по дорогам Сумеречного леса.",al={"what kind of monster is eliza","is eliza a ghoul","что за монстр элиза","элиза упырь"}}},fp="24,239,17.422.0,21.384.1,32.188.1,28.122.0,39.157.1,39.161.1,28.141.1,27.186.1"}
P.entries["quest:2541"] = {n="Спящий друид",s="Глубоко в Обители Бен'этиль спящий ночной эльф Обен Яростный Коготь оказался в страшной магической беде. Враждебные шаманы фурболгов Скверной Сосны отделили его спящий дух от физического тела и с помощью мерзких чар превратили его плоть в неистового стража.",h="Глубоко в Обители Бен'этиль спящий ночной эльф Обен Яростный Коготь оказался в страшной магической беде.",kw={"ban'ethil barrow den","barrow den","emerald dream","gnarlpine","oben rageclaw","shaman voodoo charm","teldrassil","the sleeping druid","обитель бен'этиль","обитель","изумрудный сон","скверная сосна","обен яростный коготь","шаманский оберег вуду","тельдрассил","спящий друид"},ang={["class:Druid"]="Для друидов положение Обена — наяву воплотившийся кошмар: когда тело захвачено во время единения с Изумрудным Сном, это нарушает самую основу друидского сна.",["race:NightElf"]="Осквернение Обители Бен'этиль показывает, как глубоко фурболги Скверной Сосны пали по сравнению с древним родством с кальдораями."},sec={{t="Нарушенный сон",b="Друиды-ночные эльфы входят в обители по всему Калимдору, чтобы веками общаться с природой во сне, блуждая по Изумрудному Сну, пока их смертные тела покоятся в каменных нишах. Однако порча, поразившая Тельдрассил, довела местное племя фурболгов Скверной Сосны до отчаянной жестокости. В Обители Бен'этиль шаманы Скверной Сосны нашли способ нарушить священный покой Обена Яростного Когтя, вырвав его живой дух из спящего сосуда."},{t="Вуду и порча",b="Вместо того чтобы убить Обена, шаманы Скверной Сосны использовали зловещий талисман — Шаманский оберег Вуду, — чтобы насильно оживить его пустую оболочку. Дух Обена, беспомощно запертый в Изумрудном Сне, может лишь наблюдать, как его тело бродит по коридорам и слепо нападает на всякого, кто входит в обитель. Чтобы разрушить чары и найти путь к возвращению тела, его призрачный образ просит искателей приключений добыть для изучения один из оберегов Скверной Сосны."}},faq={{q="Кто такой Обен Яростный Коготь?",a="Обен Яростный Коготь — друид, ночной эльф, погрузившийся в священный сон в Обители Бен'этиль, чтобы общаться с Изумрудным Сном. Враждебные фурболги Скверной Сосны захватили его физический сосуд, оставив его дух без пристанища.",al={"oben rageclaw","who is the sleeping druid","sleeping night elf in barrow den","обен яростный коготь","кто такой спящий друид","спящий ночной эльф в обители"}},{q="Почему тело Обена нападает на людей?",a="Шаманы Скверной Сосны провели ритуал, отделивший сознание Обена от его плоти. Они оживили его пустое физическое тело темной магией, чтобы оно служило свирепым стражем в глубине обители.",al={"why is oben hostile","why is oben attacking","oben rageclaw body attacking","почему обен враждебен","почему обен нападает","тело обена яростного когтя нападает"}},{q="Что такое Шаманский оберег Вуду?",a="Это зачарованный фетиш, который носят шаманы Скверной Сосны в Обители Бен'этиль. С помощью его темной силы они вырывают духов спящих друидов из тел и оживляют их физические оболочки.",al={"shaman charm","voodoo charm teldrassil","what is shaman voodoo charm","шаманский оберег","оберег вуду тельдрассил","что такое шаманский оберег вуду"}},{q="Где настоящий дух Обена во время задания?",a="Сознание Обена блуждает в Изумрудном Сне и не может вернуться в смертную оболочку. Он может общаться с миром бодрствующих лишь как мерцающий дух возле места своего покоя.",al={"where is oben","oben spirit location","emerald dream oben","где обен","где дух обена","обен изумрудный сон"}},{q="Почему фурболги в Обители Бен'этиль враждебны?",a="Племя Скверной Сосны стало жертвой растущей порчи и безумия, поражающих животных и леса Тельдрассила, и обратилось против своих бывших союзников ночных эльфов, оскверняя священные места друидов.",al={"why are gnarlpine mad","furbolg corruption teldrassil","why furbolgs aggressive","почему скверная сосна безумны","порча фурболгов тельдрассил","почему фурболги агрессивны"}},{q="Можно ли спасти тело Обена, не убивая его?",a="Изучение Шаманского оберега Вуду — первая надежда Обена разрушить ритуал. Исследуя мерзкие чары, связывающие его плоть, он надеется понять магию и найти способ разрешить кризис.",al={"save oben rageclaw","can oben be saved","cure oben","спасти обена яростного когтя","можно ли спасти обена","исцелить обена"}}},fp="18,273,19.481.0,21.466.1,21.217.0,36.213.0,32.199.0,45.188.0,53.210.0,44.202.0"}
P.entries["quest:255"] = {n="Наемники",s="«Наемники» — контракт на охоту за головами, который выдал мировой судья Тупонос в Телсамаре: нужно истребить огров Мо'грош, наступающих с северо-востока Лок Модана. Военное подкрепление из Стальгорна увязло в месяцах бюрократической волокиты, и судье приходится нанимать проезжих искателей приключений для защиты уязвимых поселений долины, раскопок и жизненно важной Каменной Плотины.",h="«Наемники» — контракт на охоту за головами, который выдал мировой судья Тупонос в Телсамаре: нужно истребить...",kw={"loch modan","magistrate bluntnose","mercenaries","mo'grosh","ogre","stonewrought dam","thelsamar","лок модан","мировой судья тупонос","наемники","мо'грош","огр","каменная плотина","телсамар"},ang={["faction:Alliance"]="Лок Модан — важнейший коридор между Каз Моданом и северными королевствами; если он погрузится в хаос из-за набегов огров, это будет угрожать линиям снабжения Альянса по всем Восточным королевствам.",["race:Dwarf"]="Для любого горца или путника из столицы призыв Тупоноса к оружию становится личным делом: жемчужина дворфийской инженерии — Каменная Плотина — осталась без охраны из-за стальгорнской волокиты."},sec={{t="Медленные колеса Стальгорна",b="Телсамар ощущает на себе все прелести дворфийской бюрократии. Стальгорну понадобилось целых два месяца, чтобы просто пообещать горстку солдат для усиления обороны Лок Модана, и еще два месяца, прежде чем они должны прибыть. Городская стража измотана до предела, и мировой судья Тупонос не может позволить себе ждать четыре месяца, пока враждебные силы собираются у самых границ долины."},{t="Угроза в холмах",b="Огры Мо'грош укрепили лагерь в холмах к северо-востоку от озера. Их растущее присутствие угрожает не только Телсамару, но и раскопкам Сталекрута и самой Каменной Плотине. Если плотину атакуют или повредят, разрушения ниже по течению будут катастрофическими. Не имея официальных отрядов горцев, Тупонос обратился к вольным наемникам, чтобы проредить ряды огров и выиграть для долины время в борьбе с ограми и троггами."}},faq={{q="Почему мировой судья Тупонос нанимает наемников вместо того, чтобы использовать стражу?",a="Стальгорн мучительно медленно отвечает на мольбы Лок Модана о помощи. Сенату понадобилось два месяца, чтобы одобрить отправку даже горстки солдат, и еще два месяца, пока они прибудут. Перед лицом непосредственной угрозы Телсамару, плотине и местным раскопкам Тупоносу ничего не остается, кроме как платить независимым искателям приключений.",al={"why hire mercenaries","thelsamar guards","ironforge help","зачем нанимать наемников","стража телсамара","помощь стальгорна"}},{q="Где обитают огры Мо'грош?",a="Огры Мо'грош живут в Оплоте Мо'грош, расположенном среди неприступных утесов и холмов к северо-востоку от большого озера Лок Модана.",al={"ogre location","where are mogrosh","mogrosh camp","расположение огров","где мо'грош","лагерь мо'грош"}},{q="Почему Каменной Плотине считается, что грозит опасность?",a="Каменная Плотина регулирует уровень всего озера и является архитектурной жемчужиной дворфов. Военной защиты практически нет, а огры Мо'грош разбили лагерь неподалеку, поэтому Тупонос опасается, что организованный набег может повредить или разрушить громадное сооружение и вызвать катастрофические наводнения.",al={"why protect dam","ogres and the dam","зачем защищать плотину","огры и плотина"}},{q="Какие еще угрозы нависли над Телсамаром помимо огров?",a="Троггов выплеснуло через озеро из подземных руин и раскопок. Тупонос считает их огромной опасностью, но грубая сила ближайшего оплота огров вынуждает его нанимать бойцов, чтобы отбросить Мо'грош, а местная стража могла сосредоточиться на вторжениях троггов.",al={"other threats loch modan","trogg threat","другие угрозы лок модана","угроза троггов"}}},fp="11,378,23.393.0,23.479.0,71.338.0,37.129.0,49.303.0,59.285.0"}
P.entries["quest:256"] = {n="Разыскивается: Чок'сул",s="Награда, объявленная в Телсамаре мировым судьей Тупоносом, требует смерти Чок'сула, военачальника огров, угрожающего северо-востоку Лок Модана. Считается, что он организует нападения на местные поселения и важнейшие объекты, а принесенная голова гарантирует щедрое вознаграждение от городского руководства.",h="Награда, объявленная в Телсамаре мировым судьей Тупоносом, требует смерти Чок'сула, военачальника огров...",kw={"bluntnose","bounty","chok'sul","choksul","loch modan","ogre","stonewrought dam","thelsamar","тупонос","награда","чок'сул","лок модан","огр","каменная плотина","телсамар"},ang={["faction:Alliance"]="Лок Модан служит главным сельскохозяйственным и снабженческим коридором, ведущим в Дун Морог, поэтому стабильность вокруг Телсамара крайне важна для военных усилий Альянса.",["profession:Engineering"]="Каменная Плотина — одно из величайших достижений дворфийского гражданского строительства; любой уважаемый мастер не допустит и мысли, чтобы грубые огры повредили ее.",["race:Dwarf"]="Защита Каменной Плотины и окрестных археологических раскопок напрямую задевает гордость и наследие дворфов и безопасность суверенных земель Стальгорна."},sec={{t="Угроза озеру",b="Хотя троггов и диких зверей в Лок Модане хватало всегда, появление организованных огров — это обострение, которое местные дворфы-горцы не могут игнорировать. Обосновавшись в лагерях на неприступном северо-востоке долины, эти громилы перестали просто собирать подножный корм. По словам местных разведчиков и городских властей, их набеги целенаправленны, постоянны и опасны."},{t="Цена за голову Чок'сула",b="Мировой судья Телсамара Тупонос определил Чок'сула как организатора насилия против города, ближайших дворфийских раскопок и самой Каменной Плотины. Опасаясь катастрофического ущерба главному инженерному достижению долины и гибели мирных жителей, судья назначил награду за вождя огров: убить любыми средствами, а в доказательство предъявить отрубленную голову."}},faq={{q="Кто назначил награду за Чок'сула?",a="Мировой судья Тупонос, главное гражданское должностное лицо Телсамара, официально издал приказ от имени города, чтобы защитить область от организованных набегов.",al={"who wants choksul dead","who posted choksul bounty","thelsamar wanted poster","кто хочет смерти чок'сула","кто назначил награду за чок'сула","объявление о розыске телсамар"}},{q="Почему Чок'сул считается столь приоритетной целью?",a="Считается, что Чок'сул координирует удары огров по Телсамару, стальгорнским археологическим раскопкам и Каменной Плотине — целям, где под угрозой жизни дворфов и важнейшая инфраструктура королевства.",al={"why kill choksul","what did choksul do","choksul threat","зачем убивать чок'сула","что сделал чок'сул","угроза чок'сула"}},{q="Где можно найти Чок'сула?",a="Он находится в лагере огров среди неприступных холмов в северо-восточном углу Лок Модана.",al={"choksul location","where is choksul","ogre camp loch modan","где чок'сул","местонахождение чок'сула","лагерь огров лок модан"}},{q="Какое доказательство требует мировой судья Тупонос?",a="Вы должны принести отрубленную голову Чок'сула прямо мировому судье Тупоносу в Телсамар, чтобы получить награду и благодарность Стальгорна.",al={"choksul head","bounty proof","turn in choksul","голова чок'сула","доказательство для награды","сдать чок'сула"}},{q="Зачем ограм нападать на Каменную Плотину?",a="Каменная Плотина сдерживает огромное озеро Лок Модана и является венцом дворфийской инженерии. Ее разрушение затопило бы болота и подорвало линии снабжения дворфов, что делает ее главной тактической целью для враждебных сил.",al={"why attack the dam","stonewrought dam under attack","зачем атаковать плотину","нападение на каменную плотину"}},{q="Есть ли другие огры, действующие вместе с Чок'сулом?",a="Да, Чок'сул командует лагерем огров, устроенным в северо-восточных холмах у озера, и направляет их набеги по окрестным землям.",al={"choksul clan","loch modan ogres","choksul followers","клан чок'сула","огры лок модана","приспешники чок'сула"}}},fp="16,301,20.404.0,28.402.0,34.154.0,55.232.0,28.110.0,45.134.0,44.240.0,44.154.0"}
P.entries["quest:2561"] = {n="Друид-медведь",s="Глубоко в курганах Тельдрассила призрачный облик Обена Яростного Когтя просит о трагическом освобождении. Порченые фурболги наложили темные чары на его телесную оболочку, и вам предстоит уничтожить его бездушное тело и разорвать связь, чтобы его дух смог вернуться в Изумрудный Сон.",h="Глубоко в курганах Тельдрассила призрачный облик Обена Яростного Когтя просит о трагическом освобождении.",kw={"ban'ethil","druid of the claw","emerald dream","gnarlpine","oben rageclaw","teldrassil","the sleeping druid","voodoo charm","бан'этил","друид-медведь","изумрудный сон","гнилая сосна","обен яростный коготь","тельдрассил","спящий друид","оберег вуду"},ang={["class:Druid"]="Зрелище спящего Друида-медведя, оскверненного порчеными фурболгами, служит леденящим напоминанием об опасности оставлять тело без присмотра во время общения с Изумрудным Сном.",["race:NightElf"]="Тельдрассил должен был стать убежищем для ночных эльфов, но стремительная порча местных фурболгов, таких как племя Гнилой Сосны, создает непосредственную угрозу даже в их священных курганах."},sec={{t="Разделенный дух",b="Отдыхая в курганах под Тельдрассилом, Обен Яростный Коготь постиг ужасную участь. Порченые фурболги из племени Гнилой Сосны подвергли его спящее тело мерзким чарам вуду и оторвали дух от смертной плоти. Запертый в Изумрудном Сне, дух Обена остается поблизости, не в силах ни упокоиться, ни вернуть свое тело."},{t="Милосердие к плоти",b="Осмотр оберега вуду племени Гнилой Сосны открыл мрачную правду: телесная оболочка Обена целиком во власти фурболгов. Чтобы разрушить чары, искатель приключений должен войти в ближайшую пещеру, сразить безмозглую враждебную оболочку Обена Яростного Когтя и применить оберег фурболгов над его останками, окончательно разрушив магию, что связывает его душу."}},faq={{q="Почему я должен убить Обена Яростного Когтя?",a="Фурболги из племени Гнилой Сосны наложили на Обена мощные чары вуду, пока он спал, превратив его тело в бездушную марионетку. Поскольку его плоть полностью в их власти, уничтожение телесной оболочки — единственный способ разорвать чары и освободить его заблудший дух.",al={"why kill oben","kill sleeping druid","oben rageclaw body","зачем убивать обена","убить спящего друида","тело обена яростного когтя"}},{q="Для чего нужен Оберег Вуду?",a="Оберег хранит ключ к чарам, подчиняющим Обена. Когда вы убьете его порченое бездушное тело, применение оберега над павшими останками развеет темную магию, удерживающую его дух в плену.",al={"voodoo charm use","how to use voodoo charm","gnarlpine charm oben","применение оберега вуду","как использовать оберег вуду","оберег гнилой сосны обен"}},{q="Куда отправляется Обен после этого задания?",a="Когда его тело уничтожено, а чары рассеяны, дух Обена Яростного Когтя покидает мир смертных. Он наконец может отправиться в Изумрудный Сон и упокоиться с миром.",al={"oben fate","what happens to oben rageclaw","does oben survive","судьба обена","что станет с обеном яростным когтем","выживет ли обен"}},{q="Почему племя Гнилой Сосны использует магию вуду?",a="Фурболги из племени Гнилой Сосны глубоко погрузились в порчу и безумие, отвернувшись от древней гармонии, и балуются мерзким колдовством и грубой темной магией, чтобы подчинить окрестных существ и спящих друидов.",al={"furbolg voodoo","gnarlpine voodoo magic","why do furbolgs have charms","вуду фурболгов","магия вуду гнилой сосны","почему у фурболгов обереги"}},{q="Кем был Обен Яростный Коготь?",a="Обен был ночным эльфом, Друидом-медведем, который погрузился в священный сон в курганах Тельдрассила, общаясь с Изумрудным Сном, пока фурболги из племени Гнилой Сосны не потревожили его покой и не поработили его смертную оболочку.",al={"who is oben","oben lore","oben rageclaw background","кто такой обен","предыстория обена","обен яростный коготь история"}},{q="Говорит ли со мной дух Обена, пока его тело живо?",a="Да. Темные чары оторвали душу Обена от плоти. Его дух явился призраком у входа в пещеру и совершенно не может управлять зачарованной пустой оболочкой внутри или вернуться в нее.",al={"oben ghost and body","two obens","why is oben in two places","призрак и тело обена","два обена","почему обен в двух местах"}}},fp="17,284,16.324.0,19.345.1,36.287.0,34.201.0,36.194.1,41.219.0,22.210.0,61.197.0"}
P.entries["quest:258"] = {n="Вызов охотнику",s="«Вызов охотнику» — охота на время, которое предлагает дерзкий человек Дерил Юный в Приюте Странников на юго-востоке Лок Модана. Раздосадованный тем, что не смог принизить ваш прежний успех, Дерил ставит на кон рубашку со своих плеч: он уверен, что вы не выследите и не убьете пять старых горных кабанов за двенадцать минут. Это задание проверяет быстроту искателя приключений в суровой местности и среди опасных зверей нагорья.",h="«Вызов охотнику» — охота на время, которое предлагает дерзкий человек Дерил Юный в Приюте Странников на...",kw={"boar","coldridge","daryl","elder mountain boar","farstrider lodge","hunting","loch modan","youngling","кабан","холодная долина","дерил","старый горный кабан","приют странников","охота","лок модан","юный"},ang={["class:Hunter"]="Для мастеров выслеживания поиск пяти старых горных кабанов в зарослях нагорья в жестко ограниченное время — классическая проверка умения управляться с добычей и быстро ее убивать.",["faction:Alliance"]="Приют Странников служит важной опорной базой для лесных стражей Альянса, защищающих восточную границу Лок Модана от диких зверей и угроз нагорья.",["race:Dwarf"]="Любой дворф, прошедший путь через Холодную долину, сразу поймет сравнение Дерила, хотя вытерпеть его снисходительный тон куда труднее."},sec={{t="Хвастовство юнца",b="Дерил Юный живет среди опытных охотников Приюта Странников, но не обладает их спокойным терпением. Недостаток лет он восполняет бахвальством и преувеличенными охотничьими рассказами, в том числе долгими байками о том, как он получил свой «знаменитый» шрам. Не желая признавать чужое мастерство, он постоянно путает имена других охотников и придумывает строгие испытания, чтобы усмирить новичков и вернуть себе завышенное положение среди обитателей приюта."},{t="Охота в нагорье",b="В отличие от более простых кабанов Холодной долины, где юные дворфы-разведчики впервые учатся ремеслу, старые горные кабаны, бродящие по скалам и склонам Лок Модана, огромны, толстокожи и опасны, если их разозлить. Дерил дает охотникам всего двенадцать минут, чтобы найти, убить и подтвердить гибель пяти таких зверей. Если выполнить охоту достаточно быстро, болтливый юнец неловко отступает, делая вид, что не помнит о щедром пари, которое так легко заключил."}},faq={{q="Кто такой Дерил Юный?",a="Дерил — молодой хвастливый охотник-человек, живущий в Приюте Странников на юго-востоке Лок Модана. Отчаянно желая выглядеть столь же внушительно, как старые ветераны вокруг, он без конца превозносит свое мастерство, выдумывает грандиозные истории и бросает проходящим искателям приключений вызов трудными охотничьими испытаниями.",al={"who is daryl","daryl youngling lore","farstrider lodge daryl","кто такой дерил","дерил юный","приют странников дерил"}},{q="Где находятся старые горные кабаны?",a="Старые горные кабаны бродят по предгорьям, лугам и хребтам вокруг Приюта Странников, а также на юге и востоке Лок Модана. Их можно найти пасущимися на холмистом нагорье между приютом и центральным озером.",al={"elder mountain boar location","where to find boars","boar hunt area","где старые горные кабаны","где найти кабанов","место охоты на кабанов"}},{q="Почему эта охота ограничена по времени?",a="Дерил ограничивает охоту двенадцатью минутами, потому что полностью уверен в вашей неудаче. Установив жесткий срок, он надеется смутить вас и доказать, что ваши прежние охотничьи успехи были лишь везением новичка.",al={"why twelve minutes","why is it timed","hunter challenge timer","почему двенадцать минут","почему на время","таймер вызова охотнику"}},{q="Какое пари заключил Дерил?",a="Объясняя испытание, Дерил смело заявил, что отдаст вам рубашку со своих плеч, если вы успеете убить пять старых горных кабанов. Разумеется, когда вы с триумфом возвращаетесь, он быстро делает вид, что ничего не помнит о таком споре.",al={"daryl's bet","shirt off his back","what did daryl wager","пари дерила","рубашка с плеч","на что спорил дерил"}},{q="Чем они отличаются от кабанов Холодной долины?",a="Дерил особо подчеркивает, что эти старые горные кабаны намного сильнее и агрессивнее мелких, ручных кабанов, на которых охотятся начинающие дворфы в Холодной долине. У взрослых кабанов Лок Модана более толстая шкура и опасные клыки, заточенные о гранит нагорья.",al={"coldridge boars vs mountain boars","coldridge comparison","кабаны холодной долины и горные кабаны","сравнение с холодной долиной"}},{q="Куда ведет эта цепочка заданий об охоте дальше?",a="Когда вы заставите Дерила замолчать, выполнив его вызов, внимание в приюте переключается на более серьезные дела, и дальше следует схватка с опасным старым медведем стариной Черношкуром в задании «Месть Вайрина».",al={"what quest is next","after a hunters challenge","hunting questline","какое задание следующее","после вызова охотнику","цепочка заданий об охоте"}}},fp="20,428,15.498.0,17.493.0,27.290.0,43.243.0,23.224.0,24.262.0,48.260.0,40.220.1"}
P.entries["quest:26"] = {n="Необходимый урок",s="«Необходимый урок» — обряд посвящения для молодых друидов-таурен, готовых овладеть властью над водой. Задание выдает Тюрак Рунический Тотем на вершинах Громового Утеса и направляет учеников в Ночную Гавань на Лунной поляне, чтобы начать испытания под руководством Круга Кенария.",h="«Необходимый урок» — обряд посвящения для молодых друидов-таурен, готовых овладеть властью над водой.",kw={"aquatic form","cenarion circle","dendrite starblaze","elder rise","lesson to learn","moonglade","nighthaven","thunder bluff","turak runetotem","водный облик","круг кенария","дендрит блеск звезд","вершина старейшин","необходимый урок","лунная поляна","ночная гавань","громовой утес","тюрак рунический тотем"},ang={["class:Druid"]="Этот обряд знаменует переход от выживания на земле к истинной стихийной разносторонности и открывает путь к овладению дыханием и движением под водой.",["faction:Horde"]="Хотя друиды-таурены верны Орде, они обязаны чтить священный нейтралитет Лунной поляны и идти бок о бок с ночными эльфами под общим пологом Кенария.",["race:Tauren"]="Это задание отражает прочную связь друидов-таурен Громового Утеса с более широким братством Кенария, обосновавшимся на Лунной поляне."},sec={{t="Власть над глубинами",b="Обретя власть над грубой физической силой в облике медведя, друид переходит к изучению приспособляемости. Водные пути Азерота таят опасности для сухопутных путников, и им нужен облик, подходящий для холодных глубин и сокрушительных течений. Тюрак Рунический Тотем внимательно наблюдает за учениками и отправляет на север изучать водный облик лишь тех, кто доказал свою преданность природе."},{t="Дорога в Ночную Гавань",b="Поскольку превращение в водное существо требует глубокого духовного прозрения, посвященные должны искать наставления за пределами утесов Мулгора. Тюрак велит ученикам отправиться на Лунную поляну — священное убежище у подножия горы Хиджал. Там, в тихой Ночной Гавани, древние наставники из числа ночных эльфов Круга Кенария принимают братьев и сестер-таурен, отбрасывая вражду фракций ради сохранения общих учений Кенария."},{t="Два испытания",b="Встреча с Дендритом Блеском Звезд в Ночной Гавани — лишь начало. Ночной эльф-старейшина предупреждает, что власть над водами нельзя просто даровать — ее нужно заслужить испытанием. Он говорит кандидатам, что их ждут два тяжелых испытания: одно проверяет выносливость и самообладание при работе под давлением воды, другое требует глубокого духовного понимания самого водного облика."}},faq={{q="Кто выдает задание «Необходимый урок»?",a="Задание выдает Тюрак Рунический Тотем, наставник друидов на Вершине Старейшин в Громовом Утесе. Когда посвященный набирается достаточно опыта, он отправляет его на углубленное обучение.",al={"who starts a lesson to learn","where do i get a lesson to learn","turak runetotem quest","кто дает необходимый урок","где взять необходимый урок","задание тюрака руническое тотема"}},{q="Куда нужно отправиться, чтобы выполнить это задание?",a="Вы должны отправиться в деревню Ночная Гавань, укрытую в священном лесу Лунной поляны, и поговорить с Дендритом Блеском Звезд из Круга Кенария.",al={"where do i turn in a lesson to learn","dendrite starblaze location","where is nighthaven","где сдать необходимый урок","где находится дендрит блеск звезд","где ночная гавань"}},{q="К какой способности ведет эта цепочка заданий?",a="Это задание — первый шаг цепочки, которая награждает друидов Водным обликом, дающим быстрое плавание и возможность бесконечно дышать под водой.",al={"what form does this give","aquatic form quest","why do this quest","какой облик дает","задание водного облика","зачем выполнять задание"}},{q="Почему друиды-таурен идут учиться к ночному эльфу?",a="Круг Кенария — нейтральное братство, посвященное Кенарию и сохранению природы. На Лунной поляне политические разногласия Орды и Альянса отложены, чтобы ночные эльфы и таурены могли вместе изучать священные искусства.",al={"why moonglade","why dendrite starblaze","cenarion circle tauren","почему лунная поляна","почему дендрит блеск звезд","круг кенария таурены"}},{q="О каких испытаниях говорит Дендрит Блеск Звезд?",a="Дендрит объясняет, что вам предстоят два особых испытания: одно проверяет ваше физическое самообладание при работе под давлением под водой, другое — вашу духовную решимость понять сам облик.",al={"what are the two trials","dendrite tests","aquatic trials","какие два испытания","испытания дендрита","водные испытания"}},{q="Как друид добирается до Лунной поляны на этом этапе?",a="Друиды обладают врожденной духовной связью, дающей им заклинание «Телепортация: Лунная поляна», которое переносит их из любой точки Азерота прямо в безмятежную деревню Ночная Гавань.",al={"how to get to moonglade","teleport to moonglade","getting to nighthaven","как попасть на лунную поляну","телепорт на лунную поляну","как добраться до ночной гавани"}}},fp="17,281,21.406.0,22.424.0,15.395.0,38.190.0,39.150.0,43.182.0,52.251.0,45.220.0,47.177.0"}
P.entries["quest:262"] = {n="Таинственный незнакомец",s="Скорбя о гибели семьи, отшельник Свен Йорген поручает вам выяснить, кто такой таинственный незнакомец, замеченный возле его фермы в ту роковую ночь. Имея лишь загадочную книгу, найденную среди руин, вы должны расспросить жителей Темнолесья и проследить путь незнакомца.",h="Скорбя о гибели семьи, отшельник Свен Йорген поручает вам выяснить, кто такой таинственный незнакомец...",kw={"book","darkshire","duskwood","madame eva","shadowy figure","sven yorgen","sven's camp","книга","темнолесье","сумеречный лес","мадам ева","таинственный незнакомец","свен йорген","лагерь свена"},ang={["class:Priest"]="Расследование гадания Мадам Евы показывает, как тонка завеса между духовным ясновидением, магией Тьмы и незримыми психическими отпечатками на обычных предметах.",["faction:Alliance"]="Из-за того, что Штормград не поддерживает Темнолесье, его травмированным жителям пограничья и местным провидцам приходится полагаться исключительно на странствующих героев Альянса, расследующих смертельные злодеяния в Сумеречном лесу."},sec={{t="Отголоски бойни",b="Свен Йорген скрывается в безлюдных холмах Сумеречного леса, сломленный ужасной резней, в которой погибли его семья и работники. Сначала он винил таинственных черных всадников, терроризирующих лес, но его память терзает другая деталь: тихая, неясная фигура, затаившаяся поблизости в ночь бойни. Отчаянно желая найти ответы, Свен вверяет вам единственную вещественную улику из развалин — странную книгу, оставленную на разграбленной ферме."},{t="В поисках гадания в городе",b="Не имея прямых зацепок в опасной глуши, след ведет обратно на восток, в Темнолесье. Свен надеется, что кто-то из суеверных местных жителей узнает странный том. В Темнолесье хватает чудаков и медиумов, и прежде всего Мадам Ева, чье оккультное чутье и гадания позволяют ей видеть за пределами обычного зрения и читать духовные отпечатки на таинственных реликвиях."},{t="Чужие нити",b="Когда вы показываете книгу Мадам Еве, она ощущает слабые, но несомненные психические отпечатки. Недавно страницы отметило жгучее желание мести самого Свена, но основная аура принадлежит совсем другому человеку. Ева видит, что первоначальный владелец вовсе не жил ни в Темнолесье, ни в Сумеречном лесу, а значит, на ферме до начала кровопролития побывал чужак."}},faq={{q="Кто такой Свен Йорген?",a="Свен Йорген — разбитый горем фермер, изгнанником поселившийся в западных холмах Сумеречного леса. После того как темные всадники напали на его усадьбу и убили всю его семью, он бежал в глушь, охваченный горем, страхом и отчаянной жаждой мести виновным.",al={"who is sven","sven backstory","sven yorgen","кто такой свен","история свена","свен йорген"}},{q="Что за книга найдена на ферме Свена?",a="Книга — вещественная улика, найденная в грязи и обломках разрушенной усадьбы Свена. Она принадлежала неуловимому наблюдателю, которого видели скрывающимся в тени во время нападения на его семью.",al={"what book is this","book from svens farm","mysterious book","что за книга","книга с фермы свена","таинственная книга"}},{q="Зачем нести книгу Мадам Еве?",a="Мадам Ева — местная провидица и гадалка Темнолесья. Обычные горожане мало что могут узнать из книги без пометок, но Ева с помощью ясновидения читает остаточные психические отпечатки, оставленные тем, кто прежде владел предметом или носил его.",al={"why madame eva","who reads the book","darkshire mystic","почему мадам ева","кто прочтет книгу","мистик темнолесья"}},{q="Что Мадам Ева узнает из книги?",a="Мадам Ева чувствует сильный эмоциональный отпечаток мести, оставленный недавними прикосновениями Свена. Но под ним она обнаруживает слабые следы, говорящие о том, что первоначальный владелец был чужаком, не из Темнолесья.",al={"what does eva say","book owner identity","divination result","что говорит ева","владелец книги","результат гадания"}},{q="Куда ведет это расследование дальше?",a="Узнав, что владелец был чужаком, Мадам Ева отправляет вас искать среди других записей и мест Темнолесья тех, кто мог запомнить незнакомого путника, подходящего под описание этой фигуры.",al={"what next","next quest after book","who is the shadowy figure","что дальше","следующее задание после книги","кто таинственный незнакомец"}}},fp="18,315,21.485.0,26.421.0,15.376.1,19.278.0,38.201.0,32.250.0,41.221.1,40.222.1"}
P.entries["quest:263"] = {n="Защита королевских земель",s="Это задание отражает растущую борьбу горных пехотинцев Стальгорна с нашествием троггов на юге Лок Модана. Горный пехотинец Стенолом, действуя из Южной сторожевой башни, отправляет опытных новобранцев в Долину Камнедробов, чтобы уничтожать опасных троггов-шаманов и передовых костоломов. Выполнив это испытание, игрок завоевывает полное доверие Стенолома и получает аудиенцию у командующего капитана гарнизона.",h="Это задание отражает растущую борьбу горных пехотинцев Стальгорна с нашествием троггов на юге Лок Модана.",kw={"bonesnapper","ironforge","loch modan","magni","mountaineer","shaman","stonesplinter","trogg","wallbang","костолом","стальгорн","лок модан","магни","горный пехотинец","шаман","камнедробы","трогг","стенолом"},ang={["class:Shaman"]="Столкновение с грубыми заклинателями троггов Камнедробов дает необработанный, дикий взгляд на магию земли, искаженную свирепыми инстинктами.",["faction:Alliance"]="Помощь Южной сторожевой башне укрепляет важные торговые и дорожные пути, соединяющие Дун Морог с восточными болотами и королевством Штормград.",["race:Dwarf"]="Откликнуться на призыв Стенолома для любого дворфа — дело обороны родной земли: вы защищаете усадьбы Лок Модана, пока регулярные армии ваших сородичей отвлечены за границей."},sec={{t="Тонкая дворфийская линия",b="Оборона Лок Модана растянута до предела. Регулярные дворфийские резервы призваны на далекие фронты по всему Азероту, и местным заставам, таким как Южная сторожевая башня, не хватает людей. Горный пехотинец Стенолом и его немногочисленные товарищи терпят неослабевающий натиск клана Камнедробов, и им приходится в значительной мере полагаться на путешественников из Альянса, чтобы удержать южный проход."},{t="Удар по авангарду Камнедробов",b="Вместо того чтобы выбивать одиночных разведчиков, эта кампания бьет глубже, по иерархии клана Камнедробов. Троггов-костоломов клан использует как грубую силу, а их примитивные шаманы плетут магию земли, чтобы сплотить сородичей. Уничтожение двадцати таких ценных целей ослабляет набеги на низины и напрямую служит обороне королевства короля Магни Бронзоборода."}},faq={{q="Кто такой горный пехотинец Стенолом?",a="Горный пехотинец Стенолом — дворф из Стальгорна, служащий в Южной сторожевой башне в Лок Модане. Ему поручено следить за тем, как трогги выбираются из гор, и координировать действия ополчения, чтобы главная южная дорога оставалась безопасной.",al={"wallbang","who is wallbang","mountaineer wallbang lore","стенолом","кто такой стенолом","горный пехотинец стенолом предания"}},{q="Почему горные пехотинцы просят путешественников о помощи?",a="Военные резервы Стальгорна отозваны на более важные фронты по всему королевству и за его пределами. Из-за этого пограничные заставы, такие как южные сторожевые башни Лок Модана, остро нуждаются в людях перед лицом местных угроз.",al={"why do dwarves need help","where are ironforge guards","why no reserves","почему дворфам нужна помощь","где стражи стальгорна","почему нет резервов"}},{q="Где обитают эти трогги?",a="Они сосредоточены главным образом в Долине Камнедробов, скрытой в неровных холмах к юго-западу от Озера Лок. Небольшие отряды этих шаманов и костоломов также обитают на северных островах посреди самого озера.",al={"where are stonesplinter troggs","stonesplinter shaman location","where is stonesplinter valley","где трогги камнедробы","местоположение шамана камнедробов","где долина камнедробов"}},{q="Чем клан Камнедробов опасен?",a="Трогги быстро размножаются и захватывают обжитые земли за счет огромных подземных полчищ. Клан Камнедробов владеет грубой магией стихий через своих шаманов и полагается на свирепых костоломов, которые расправляются с дворфийскими разведчиками, угрожая ближайшим поселениям и торговым путям.",al={"why are troggs dangerous","stonesplinter threat","чем опасны трогги","угроза камнедробов"}},{q="Что делает горный пехотинец Стенолом после этого задания?",a="Убедившись, что вы проверенный боец на службе короля Магни, Стенолом направляет вас к капитану Ругельфассу за более стратегическими приказами по обороне Лок Модана.",al={"what next after wallbang","who is the captain","что дальше после стенолома","кто капитан"}},{q="Кто правит Стальгорном во время этого кризиса?",a="Король Магни Бронзобород правит дворфийским королевством из Великой кузни в Стальгорне. Все усилия по защите Лок Модана предпринимаются от его имени и во имя обороны его суверенных земель.",al={"who is the dwarven king","king of ironforge","кто король дворфов","король стальгорна"}}},fp="30,419,19.376.0,36.389.0,28.237.0,51.240.0,31.205.0,43.280.0,50.173.0,39.188.0"}
P.entries["quest:264"] = {n="Покуда смерть не разлучит нас",s="«Покуда смерть не разлучит нас» — горькое личное задание, которое ведет к Гробнице в Серебряном бору. Клариса Фостер, Отрекшаяся, живущая в Прудах Видений под Громовым Утесом, посылает искателей приключений оставить ее памятный кулон на могиле ее покойного мужа Юрива. Задание показывает болезненные человеческие расколы, вызванные фанатизмом и войной, когда чума поглотила Лордерон.",h="«Покуда смерть не разлучит нас» — горькое личное задание, которое ведет к Гробнице в Серебряном бору.",kw={"clarice foster","crusade","forsaken","pendant","sepulcher","silverpine","tomb","yuriv","клариса фостер","крестовый поход","отрекшиеся","кулон","гробница","серебряный бор","могила","юрив"},ang={["class:Priest"]="Задание рисует мрачную картину веры, показывая, как преданность Свету может разрушать семьи и порождать затяжную горечь у тех, кто остался.",["faction:Horde"]="Помощь Кларисе позволяет защитникам Орды понять личные трагедии и неугасающую злобу, объединяющие Отрекшихся в Серебряном бору.",["race:Undead"]="Для Отрекшихся беда Кларисы воплощает лицемерие живых: святые воины бросали семьи погибать в священном рвении, оставляя преображенных выживших нести бремя памяти."},sec={{t="Горькая память",b="Клариса Фостер не питает теплых чувств к воспоминаниям о своем земном браке. Когда Лордерон рушился, ее муж Юрив бросил ее и детей и отправился в крестовый поход против растущей угрозы нежити, заявляя, что служение Свету превыше всего. В конце концов его преданность не спасла ни семью, ни его самого. Теперь Клариса восстала в нежизни, а Юрив гниет под оскверненным камнем, и она хочет лишь избавиться от последнего осязаемого напоминания о его нарушенных обещаниях."},{t="Заброшенная могила",b="Могила Юрива находится на кладбище вокруг Гробницы: она изрезана глубокими царапинами, завалена мусором и заросла сорняками. Если положить кулон Кларисы на скульптурный рельеф его рук, не случится ни великого волшебства, ни духовного умиротворения — лишь камень потускнеет, а над надгробиями пронесется холодный безмолвный порыв ветра. Это суровое свидетельство неугасающей обиды павших жителей Лордерона."}},faq={{q="Кто такой Юрив?",a="Юрив был земным мужем Кларисы Фостер. При жизни он оставил ее и детей, чтобы сражаться с Плетью во имя Света, поставив свой поход выше семьи.",al={"who is yuriv","yuriv lore","clarice husband","кто такой юрив","юрив предания","муж кларисы"}},{q="Почему Клариса так ненавидит своего покойного мужа?",a="Клариса ночь за ночью ждала Юрива, пока он ставил религиозный долг на первое место. В итоге его поход не защитил их: он лежит мертвым в заброшенной могиле, а она проклята восстать тою самой нежитью, с которой он сражался.",al={"why is clarice mad","clarice foster backstory","почему клариса злится","клариса фостер история"}},{q="Что происходит, когда вы возвращаете кулон?",a="Когда кулон кладут на каменные руки рельефа Юрива, его самоцвет заметно тускнеет. Над Гробницей проносится резкий холодный ветер, оставляя оскверненную могилу в холодном, тихом запустении.",al={"pendant on grave","ending of until death do us part","кулон на могиле","концовка покуда смерть не разлучит нас"}},{q="Где находится могила Юрива?",a="Надгробие Юрива находится на территории кладбища Гробницы, оплота Отрекшихся на севере Серебряного бора.",al={"where is yuriv tomb","yuriv grave location","где могила юрива","местоположение могилы юрива"}},{q="Почему могила Юрива так повреждена?",a="Могила изрезана, завалена мусором и поросла сорняками. Отрекшиеся, живущие в Гробнице, не испытывают ни сочувствия, ни почтения к крестоносцу, погибшему в борьбе с их сородичами.",al={"why is grave defaced","tomb abused","почему могила осквернена","поруганная гробница"}},{q="Выжили ли дети Кларисы?",a="Клариса упоминает, что Юрив бросил и детей, и ее, но их дальнейшая судьба не названа. Учитывая полное опустошение Лордерона, вероятно, их ждал трагический конец.",al={"what happened to the kids","clarice children","что стало с детьми","дети кларисы"}}},fp="22,379,17.477.0,19.397.0,14.194.0,47.254.0,41.200.1,30.127.0,32.187.0,31.186.0"}
P.entries["quest:265"] = {n="Продолжение поисков незнакомца",s="После гадания Мадам Евы это расследование ведет из ее салона к Клерку Далтри в Темнолесье. Оно посвящено поиску происхождения дневника, найденного в руинах разоренной фермы Свена Йоргена.",h="После гадания Мадам Евы это расследование ведет из ее салона к Клерку Далтри в Темнолесье.",kw={"book","clerk daltry","darkshire","duskwood","journal","madame eva","shadowy figure","sven yorgen","книга","клерк далтри","темнолесье","сумеречный лес","дневник","мадам ева","таинственный незнакомец","свен йорген"},ang={["class:Rogue"]="Выслеживать нервную цель по городу, идя по записям о покупках и впечатлениям торговцев, — классическое сыскное ремесло.",["faction:Alliance"]="Выяснить, кто снабжал и поддерживал некромантов в Сумеречном лесу, жизненно важно для защиты Темнолесья и справедливости для убитых поселенцев."},sec={{t="Поиски переплета",b="Осмотрев обгоревший дневник, спасенный после трагедии на ферме Свена, Мадам Ева поняла, что хотя его автор — чужак, сама книга происходит из Темнолесья. Клерк Далтри часто продает чистые книги учета и тома странствующим ученым, заклинателям и писцам. Идя по следу местной торговли, расследователи ищут обычные бумажные следы, чтобы выявить неуловимого и зловещего чужака, скрывающегося в мрачных рощах Сумеречного леса."},{t="Нервный покупатель",b="Осмотрев том, Клерк Далтри ясно вспоминает сделку, несмотря на множество записей, проходящих через ратушу Темнолесья. Примерно месяц назад нервный, скрытный путник купил чистую книгу, так и не назвав имени. Дерганое поведение покупателя и постоянные взгляды через плечо произвели на клерка сильное впечатление и подтвердили, что таинственный незнакомец, которого видел Свен, открыто бывал среди жителей Темнолесья."}},faq={{q="Откуда взялась таинственная книга?",a="Madame Eva says the author is a stranger to Darkshire but the book was bought in town. Clerk Daltry sells blank books and may remember its purchaser.",al={"origin of book","who sold the book","book source","происхождение книги","кто продал книгу","источник книги"}},{q="Почему Мадам Ева посылает вас к Клерку Далтри?",a="Мадам Ева определила, что переплет и материалы книги куплены здесь же, в городе. Клерк Далтри торгует чистыми книгами учета и дневниками для местных жителей и странствующих ученых.",al={"why daltry","eva daltry connection","who made the book","почему далтри","ева и далтри","кто сделал книгу"}},{q="Что Клерк Далтри помнит о покупателе?",a="Daltry remembers the people who bought books from him in recent months. Presenting the volume lets him investigate who purchased it.",al={"who bought book","buyer description","shadowy figure appearance","кто купил книгу","описание покупателя","как выглядел незнакомец"}},{q="Как это связано с фермой Свена?",a="Книгу нашли на разрушенной ферме Свена Йоргена на юге Сумеречного леса: ее оставили во время кровавого налета, уничтожившего его семью и работников.",al={"sven connection","why are we looking","sven yorgen","связь со свеном","зачем мы ищем","свен йорген"}},{q="Куда ведет расследование дальше?",a="Раз нервный незнакомец провел время в городе, поиски продолжаются в таверне Темнолесья, таверне «Алый ворон», чтобы выяснить, не видел ли кто, где он останавливался и с кем говорил.",al={"what next","after daltry","next clue","что дальше","после далтри","следующая зацепка"}},{q="Грозит ли опасность Клерку Далтри?",a="Daltry is helping identify a buyer from his ordinary book sales. This exchange gives no indication that he is personally threatened.",al={"clerk daltry danger","daltry safe","опасность клерку далтри","далтри в безопасности"}}},fp="28,217,19.483.0,15.449.1,40.149.0,45.199.0,48.132.0,37.154.0,39.178.1,26.132.0"}
P.entries["quest:266"] = {n="Расспросы в таверне",s="«Расспросы в таверне» — задание Альянса в Темнолесье, продолжающее расследование о таинственном незнакомце, связанном с разоренной фермой Свена Йоргена. По указанию Клерка Далтри искатели приключений относят найденный дневник в таверну «Алый ворон», чтобы расспросить Хозяина таверны Смиттса о том, кто там останавливался.",h="«Расспросы в таверне» — задание Альянса в Темнолесье, продолжающее расследование о таинственном незнакомце...",kw={"clerk daltry","darkshire","duskwood","inquire at the inn","raven hill","scarlet raven","shadowy figure","sven yorgen","tavernkeep smitts","клерк далтри","темнолесье","сумеречный лес","расспросы в таверне","вороний холм","алый ворон","таинственный незнакомец","свен йорген","хозяин таверны смиттс"},ang={["class:Rogue"]="Выслеживать параноидального беглеца от трактирных слухов до безлюдных руин — прямое применение сыскного ремесла разбойника.",["faction:Alliance"]="Расследование угроз внутри Темнолесья помогает защитить одно из самых уязвимых и изолированных приграничных поселений Альянса на юге Восточных королевств."},sec={{t="Зацепка в «Алом вороне»",b="Когда Клерк Далтри заканчивает осматривать потрепанную книгу с фермы Свена Йоргена, он предполагает, что любой чужак в Темнолесье почти наверняка заходил в местную таверну. Таверна «Алый ворон» стоит на другом конце города и является единственным местом сбора и ночлега в Темнолесье, так что это самое разумное место, чтобы найти проезжих."},{t="Параноидальный постоялец",b="Показав книгу Хозяину таверны Смиттсу, вы подтверждаете догадку Далтри. Смиттс сразу узнает том: постоялец снимал комнату несколько дней и вечерами одержимо писал за стойкой. По словам трактирщика, гость бежал из Темнолесья в ужасе, уверенный, что его неустанно преследует невидимый враг. Его путь лежал на запад по мрачной дороге к Вороньему Холму."}},faq={{q="Кто посылает вас в таверну?",a="Клерк Далтри, городской писарь в ратуше Темнолесья, возвращает дневник и советует поискать в местной таверне того, кто мог бы узнать его владельца.",al={"who gives this quest","quest giver","where does inquire at the inn start","кто дает это задание","персонаж, выдающий задания","где начинается расспросы в таверне"}},{q="Что за книгу вы несете?",a="Это потрепанный дневник, найденный на разоренной ферме Свена Йоргена на юге Сумеречного леса; считается, что он принадлежит таинственному незнакомцу, замеченному поблизости.",al={"what is the book","book from svens farm","journal","что за книга","книга с фермы свена","дневник"}},{q="Кто содержит таверну «Алый ворон»?",a="Хозяин таверны Смиттс управляет таверной «Алый ворон»: наливает напитки и сдает комнаты всем путникам, которые еще осмеливаются заходить в Сумеречный лес.",al={"who is the tavernkeeper","innkeeper darkshire","who is smitts","кто хозяин таверны","трактирщик темнолесья","кто такой смиттс"}},{q="Что Хозяин таверны Смиттс рассказывает о госте?",a="Смиттс вспоминает, что владелец дневника снимал комнату несколько дней, а ночи проводил за выпивкой и письмом. Затем путник в панике бежал на запад, бормоча, что за ним охотится нечто ужасное.",al={"what did smitts say","what happened to the shadowy figure","what does the innkeeper know","что сказал смиттс","что стало с незнакомцем","что знает трактирщик"}},{q="Куда бежал таинственный незнакомец?",a="Он поспешил на запад из Темнолесья в поисках укрытия, указав ищущим на заброшенное поселение и обширное кладбище Вороньего Холма.",al={"where did he go","where is the shadowy figure","where to next","куда он пошел","где таинственный незнакомец","куда дальше"}},{q="Какое задание следует за заданием «Расспросы в таверне»?",a="Хозяин таверны Смиттс велит вам идти по следу незнакомца на запад в задании «Поиски таинственного незнакомца».",al={"next quest","what comes after inquire at the inn","following quest","следующее задание","что после расспросов в таверне","продолжение"}}},fp="18,299,27.363.0,18.419.1,25.172.0,34.162.0,31.143.0,51.205.0,34.157.0,38.112.0"}
P.entries["quest:267"] = {n="Троггская угроза",s="«Троггская угроза» — задание Альянса, которое выдает капитан Ругельфасс у Южных ворот Лок Модана. Местный резерв Стальгорна отозван на поддержку фронтов Альянса, и оставшиеся защитники едва справляются с враждебными племенами троггов в холмах. Искателям приключений поручено истребить троггов и принести их каменные зубы, чтобы ослабить давление на горный перевал.",h="«Троггская угроза» — задание Альянса, которое выдает капитан Ругельфасс у Южных ворот Лок Модана.",kw={"captain rugelfuss","ironforge reserve","khaz modan","loch modan","magni bronzebeard","southern gate","trogg","trogg stone tooth","капитан ругельфасс","резерв стальгорна","каз модан","лок модан","магни бронзобород","южные ворота","трогг","каменный зуб трогга"},ang={["faction:Alliance"]="Задание показывает, как обязательства Альянса в дальних землях лишили местные гарнизоны, например в Лок Модане, их оборонительных резервов.",["race:Dwarf"]="Для дворфов истребление троггов у Южных ворот — прямой долг перед Каз Моданом, который принесет похвалу самого короля Магни Бронзоборода."},sec={{t="Обескровленный рубеж",b="Оборонительная линия, охраняющая южный подступ к Лок Модану, находится в шатком положении. Обычные дворфийские горные пехотинцы и полки резерва Стальгорна отправлены на усиление более широких фронтов Альянса, и капитан Ругельфасс остался с горсткой гарнизона у южной сторожевой башни. Строгий приказ не покидать ворота не позволяет Ругельфассу вести наступление в нагорья, и окрестные поселенцы и путники остаются уязвимыми для засад."},{t="Сдержать натиск",b="Трогги, обитающие в окрестных скалах, представляют все большую опасность для Каз Модана. Если их не сдерживать, их число быстро растет и грозит захлестнуть дворфийские форпосты. Чтобы выиграть время и ослабить угрозу, Ругельфасс призывает странствующих искателей приключений напасть на троггов прямо в их логовах на холмах и предъявить отрубленные каменные зубы как вещественное доказательство."}},faq={{q="Кто такой капитан Ругельфасс?",a="Капитан Ругельфасс — офицер дворфийской армии, расквартированный в сторожевой башне у Южных ворот Лок Модана. Он должен защищать перевал от вторжений, испытывая при этом острую нехватку гарнизонных войск.",al={"captain rugelfuss","who gives the trogg threat","rugelfuss","капитан ругельфасс","кто выдает троггскую угрозу","ругельфасс"}},{q="Почему у Южных ворот не хватает людей?",a="Резерв Стальгорна мобилизован и переброшен на крупные фронты Альянса за рубежом. У ворот остался лишь небольшой отряд, привязанный к оборонительному посту и неспособный наносить ответные удары.",al={"why are there no guards","ironforge reserve absent","where are the dwarven soldiers","почему нет стражи","резерв стальгорна отсутствует","где дворфийские солдаты"}},{q="Что такое каменные зубы троггов?",a="У троггов естественно окаменевшие, подобные камню зубы, отражающие их подземное, земляное происхождение. Капитан Ругельфасс требует их как неоспоримое вещественное доказательство гибели троггов.",al={"trogg stone tooth","stone teeth","why trogg teeth","каменный зуб трогга","каменные зубы","зачем зубы троггов"}},{q="Где находятся трогги?",a="Троггов можно найти в скалистых холмах, ущельях и раскопках по обе стороны дороги у Южных ворот в Лок Модане.",al={"where to find troggs","trogg locations loch modan","where are troggs for this quest","где найти троггов","трогги лок модан","где трогги для этого задания"}},{q="Почему трогги сейчас так опасны?",a="Трогги быстро размножаются, отличаются яростной территориальной агрессией и захватывают обитаемые земли, стоит отвести военные гарнизоны. Если их не истреблять, они грозят перекрыть перевалы, соединяющие Лок Модан с соседними землями.",al={"why are troggs dangerous","trogg problem","what do troggs want","чем опасны трогги","проблема троггов","чего хотят трогги"}},{q="Как выполнение этого задания помогает королю Магни Бронзобороду?",a="Король Магни Бронзобород отвечает за безопасность всего Каз Модана. Сокращая число троггов, пока армии Стальгорна сражаются за рубежом, искатели приключений защищают внутренние линии снабжения королевства и уязвимые приграничные поселения.",al={"magni bronzebeard connection","does magni care","why help ironforge","связь с магни бронзобородом","заботится ли магни","зачем помогать стальгорну"}}},fp="16,396,19.487.0,17.370.0,25.221.0,38.228.0,27.201.0,29.137.0,43.244.0,58.247.0"}
P.entries["quest:268"] = {n="Возвращение к Свену",s="Это задание отмечает миг, когда Свен Йорген наконец узнает правду о жестокой расправе над его семьей в Усадьбе Йоргена. Разыскав беглеца Трясунчика, вы возвращаетесь в уединенный лагерь Свена на границе Западного Края с законченным дневником бродяги. Дневник обещает ответы на вопросы, терзавшие Свена со времени нападения.",h="Это задание отмечает миг, когда Свен Йорген наконец узнает правду о жестокой расправе над его семьей в...",kw={"dark riders","duskwood","forlorn rowe","jitters","jitters' completed journal","morbent fel","sven yorgen","yorgen farmstead","темные всадники","сумеречный лес","покинутая усадьба","трясунчик","законченный дневник трясунчика","морбент скверн","свен йорген","усадьба йоргена"},ang={["class:Paladin"]="Помощь Свену в раскрытии сил, стоящих за убийством его семьи, служит священному долгу защищать невинных и добиваться справедливости.",["faction:Alliance"]="Трагическая гибель Усадьбы Йоргена — суровое напоминание о полной неспособности Штормграда защитить приграничные поселения Сумеречного леса от надвигающихся теней."},sec={{t="Признание труса",b="Когда на ферму Свена Йоргена напали, Трясунчик в ужасе бросился в лес, оставив среди бойни лишь неоконченный дневник. Страшась гнева Свена и преследуемый увиденным, Трясунчик спрятался в глубине Сумеречного леса. Когда его находят, он охотно отдает законченный дневник, отчаянно надеясь, что полный рассказ о нападении избавит его от личной встречи с мстительным фермером."},{t="Разоблачение Темных всадников",b="Прочитав законченный рассказ Джиттерса, Свен наконец сложил воедино ужасающие обрывки. Резня на его ферме не была случайным наплывом нежити или нападением диких зверей: ее устроили загадочные Темные всадники, искавшие некий артефакт. Кроме того, Свен вспоминает, что видел этих самых фигур в капюшонах на тайной встрече с некромантом Морбентом Скверном возле Покинутой усадьбы. Дневник Джиттерса превращает слепую скорбь Свена в целенаправленную охоту за возмездием над темным магом."}},faq={{q="Почему Трясунчик так боится Свена Йоргена?",a="Трясунчик сбежал с фермы Свена и боится гнева скорбящего фермера. Он просит вас доставить его дневник, чтобы Свен мог прочесть его рассказ.",al={"why is jitters scared","jitters afraid of sven","what did jitters do","почему трясунчик боится","трясунчик боится свена","что сделал трясунчик"}},{q="Что в законченном дневнике Трясунчика?",a="Это полный рассказ Трясунчика о событиях на ферме Свена. Свену нужно прочесть его, чтобы понять, что случилось с его семьей.",al={"what does the journal say","jitters completed journal lore","что говорится в дневнике","законченный дневник трясунчика предания"}},{q="Кто такие Темные всадники, о которых говорит Свен?",a="Темные всадники — загадочные фигуры в плащах с капюшонами, бродящие по Сумеречному лесу. Безжалостные и смертоносные, они вошли в лес, неустанно разыскивая могущественные магические реликвии, и повсюду оставляют смерть и разорение.",al={"who are dark riders","riders in duskwood","black riders","кто такие темные всадники","всадники в сумеречном лесу","черные всадники"}},{q="Как Морбент Скверн связан с нападением на ферму Свена?",a="Морбент Скверн — могущественный некромант на западе Сумеречного леса. Его связь с нападением раскрывается в ходе расследования Свена и благодаря дневнику Трясунчика.",al={"morbent fel connection","why morbent fel","who is morbent fel","связь морбента скверна","почему морбент скверн","кто такой морбент скверн"}},{q="Где найти Свена Йоргена?",a="Свен покинул свою разрушенную усадьбу и теперь живет в небольшом напряженном лагере у северо-западных холмов Сумеречного леса, близ пограничного перехода в Западный Край.",al={"where is sven","sven yorgen location","sven camp","где свен","свен йорген местонахождение","лагерь свена"}},{q="Что будет после передачи дневника Свену?",a="Свен читает законченный рассказ Трясунчика и просит вас доказать боевые навыки в следующем задании — «Доказательство силы».",al={"next quest after return to sven","sven questline next","следующее задание после возвращения к свену","цепочка заданий свена дальше"}}},fp="14,359,21.425.0,25.487.1,43.136.0,38.122.1,42.213.0,58.151.1,31.175.0,43.119.1"}
